// Yuki 自习室 内置词库 · 4532 词 · 由 js/lexicon.js 转换为 ES 模块
export default [{"word":"resilient","ipa":"/rɪˈzɪliənt/","pos":"adj.","def":"有韧性的；能恢复的；适应力强的","sen":"The team proved to be resilient when their initial experiment failed.","trans":"当最初的实验失败时，团队展现出了极强的韧性。","mne":"re (回) + sili (跳跃) + ent -> 能够弹回原状的"},{"word":"catalyst","ipa":"/ˈkætəlɪst/","pos":"n.","def":"催化剂；促使事情发生的人或物","sen":"A small decision acted as a catalyst for major innovation.","trans":"一个小小的决定成为了重大创新的催化剂。","mne":"cata (向下/分解) + lyst -> 加速反应之物"},{"word":"a","ipa":"/ə/","pos":"art.","def":"一(个)","sen":"There is a dog in my house.","trans":"我家里有一条狗。","mne":""},{"word":"abandon","ipa":"/əˈbændən/","pos":"v.","def":"放弃，抛弃；放弃","sen":"The patient decided to abandon the treatment due to severe side effects.","trans":"由于严重的副作用，患者决定放弃治疗。","mne":"ab去 + ban被命令 + don表名词 → 一直被别人命令，放弃自我 → abandon抛弃，放弃 "},{"word":"ability","ipa":"/əˈbɪləti/","pos":"n.","def":"才能，能力","sen":"He has the ability to run on water.","trans":"他可以在水上跑。","mne":""},{"word":"able","ipa":"/ˈeɪbl/","pos":"adj.","def":"能够……的，可以...的；有能力的","sen":"Now he is able to walk without the help of crutches.","trans":"现在他能够脱离拐杖走路了。","mne":""},{"word":"abnormal","ipa":"/æbˈnɔːrml/","pos":"adj.","def":"不正常的","sen":"This potato has an abnormal shape.","trans":"这个土豆的形状很不正常。","mne":"ab相反，变坏，离去 + normal正常的 → abnormal反常的"},{"word":"aboard","ipa":"/əˈbɔːrd/","pos":"adv.","def":"在（交通工具）上；  prep.在（交通工具）上","sen":"In Thailand, some women cook meals aboard their boats.","trans":"在泰国，一些女性经常在船上做饭。","mne":"a在...上面 + board木板 -> aboard在（交通工具）上"},{"word":"abolish","ipa":"/əˈbɑːlɪʃ/","pos":"v.","def":"废除，废止","sen":"In the mid 1800s, slavery was abolished in most states of America.","trans":"19世纪中期，美国大多数州废除了奴隶制。","mne":"abol消除 + ish动词后缀 → abolish废除"},{"word":"abolition","ipa":"/ˌæbəˈlɪʃn/","pos":"n.","def":"废除；废除，废止","sen":"The abolition of slavery was a significant historical event.","trans":"奴隶制的废除是一个重要的历史事件。","mne":"aboli(sh)废除 + tion名词后缀 → abolition 废除"},{"word":"about","ipa":"/əˈbaʊt/","pos":"adv.","def":"附近，大约，转向，左右，周围","sen":"The lipstick costs about 220 yuan.","trans":"这口红的售价大约是220元。","mne":"a在...上面 + bo位于，靠近 + ut在...外面 → 某事物的各个方面 → about附近，周围，有关"},{"word":"above","ipa":"/əˈbʌv/","pos":"prep.","def":"在……之上；在…… 上方；  adv.在……上面，上文中，上述；  adj.上面的，上述的","sen":"The bird is flying above the water.","trans":"鸟儿在水面上飞行。","mne":"a在...上面 + bo位于，靠近 + ve高 → above在...之上"},{"word":"abroad","ipa":"/əˈbrɔːd/","pos":"adv.","def":"到国外，在国外；在户外","sen":"The two Asian students study abroad together.","trans":"这两个亚洲学生一起出国留学。","mne":"a去，到 + broad宽的，广阔的 -> 去广阔的地方 -> abroad到国外"},{"word":"abrupt","ipa":"/əˈbrʌpt/","pos":"adj.","def":"突然的；唐突的，鲁莽的","sen":"An abrupt gust of wind suddenly turned his umbrella inside out.","trans":"一阵突如其来的大风把他的雨伞都吹翻了。","mne":"ab分离，脱离 + rupt裂，破坏 → abrupt不连贯的，突然的"},{"word":"absence","ipa":"/ˈæbsəns/","pos":"n.","def":"不在，缺席","sen":"None of the classmates know the reason for his absence.","trans":"同学们都不知道他缺席的原因。","mne":"ab远离的 + sen(t)出现 + ce名词后缀 → 没有出现 → absence缺席"},{"word":"absent","ipa":"/ˈæbsənt/, /æbˈsent/","pos":"adj.","def":"缺席的，不在场的；  v.不参加；缺席","sen":"My PE teacher is always absent, but my math teacher has perfect attendance.","trans":"体育老师总是不在，数学老师却从不缺席。","mne":"ab远离的 + sent出现 → 没有出现 → absent缺席的"},{"word":"absent-minded","ipa":"/ˌæbsənt ˈmaɪndɪd/","pos":"adj.","def":"心不在焉的，健忘的","sen":"He is absent-minded at work.","trans":"他工作时心不在焉。","mne":""},{"word":"absolute","ipa":"/ˈæbsəluːt/","pos":"adj.","def":"绝对的；完全的","sen":"Marx thought that motion is absolute, while stillness is relative.","trans":"马克思认为运动是绝对的，而静止是相对的。","mne":"ab离开 + solute松开，分离 → 不会放手的 → absolute绝对的"},{"word":"absolutely","ipa":"/ˈæbsəluːtli/","pos":"adv.","def":"绝对地；完全地","sen":"The ad said the product was absolutely guaranteed to work.","trans":"广告说这个产品是保证绝对有效的。","mne":"ab不 ＋ solute松开 ＋ ly...地 → 不松开地 → absolutely绝对地"},{"word":"absorb","ipa":"/əbˈzɔːrb/","pos":"v.","def":"吸收；理解，掌握；吸引……的注意","sen":"Plants absorb water from the soil.","trans":"植物从土壤中吸收水分。","mne":"ab离开 + sorb吸收 → absorb吸收到"},{"word":"abstract","ipa":"/ˈæbstrækt/","pos":"adj.","def":"抽象的；  n.摘要；  v.提取（读作/ˈæbˌstrækt/）","sen":"Abstract art is often difficult to understand.","trans":"抽象艺术通常让人难以理解。","mne":"abs向外 + tract拉 → abstract提取，抽象"},{"word":"abundant","ipa":"/əˈbʌndənt/","pos":"adj.","def":"大量的；丰富的；充裕的","sen":"Fish are abundant in the pond.","trans":"池塘里鱼类丰富。","mne":"ab一再 + und波动 + ant...的 → 波浪一多就溢出了 → abundant丰富的"},{"word":"abuse","ipa":"/əˈbjuːs/","pos":"v.","def":"滥用（读作/əˈbjuz/）；虐待；辱骂；  n.滥用；虐待；辱骂（读作/əˈbjus/）","sen":"The man often abuses drugs, so he looks very tired.","trans":"这个人经常滥用药物，所以看起来很累。","mne":"ab离开 + use使用 → abuse滥用"},{"word":"abusive","ipa":"/əˈbjuːsɪv/","pos":"adj.","def":"辱骂的；虐待的；滥用的","sen":"She became abusive when she was drunk.","trans":"她喝醉酒后就开始辱骂人。","mne":"abus(e)滥用 + ive形容词后缀 → abusive 滥用的"},{"word":"academic","ipa":"/ˌækəˈdemɪk/","pos":"adj.","def":"学术的；学院的；  n.学者；高等院校教师","sen":"This academic meeting has both students and professors.","trans":"这次学术会议有学生也有教授。","mne":"academ学术 + ic……的 → 学院的;学术的;学究的"},{"word":"accelerate","ipa":"/əkˈseləreɪt//ekˈseləˌreɪt/","pos":"v.","def":"【航】加速；加速，加快","sen":"The pilot needs to accelerate the aircraft to reach the required takeoff speed.","trans":"飞行员需要加速飞机以达到所需的起飞速度。","mne":"ac去 + celer迅速 + ate动词后缀 → accelerate加速"},{"word":"accent","ipa":"/ˈækˌsɛnt/, /ækˈsɛnt/","pos":"n.","def":"口音，腔调；重音符号；  v.强调（读作/ækˈsɛnt/）","sen":"The word 'tomato' is pronounced differently in British and American accents.","trans":"'番茄'在英式口音和美式口音中的发音不同。","mne":"ac=ad去，向 + cent唱歌 → 说话像唱歌 → accent口音；重音"},{"word":"accept","ipa":"/əkˈsept/","pos":"v.","def":"接受（所提供或给予的物品）；同意做；接纳，认可","sen":"Thank you — I accept your lovely gift with pleasure!","trans":"谢谢你，我非常高兴地接受你送的可爱的礼物!","mne":"ac一再 + cept拿 → accept接受，承认"},{"word":"acceptance","ipa":"/əkˈseptəns/","pos":"n.","def":"接纳；赞同","sen":"Clapping can be a sign of acceptance.","trans":"鼓掌可以是一种表示接纳的标志。","mne":"ac一再+cept拿+ance→acceptance接受；承认"},{"word":"access","ipa":"/ˈækses/","pos":"n.","def":"进入；接触；通道，入口；  v.进入，使用，获取；接近","sen":"The ramp gives access to disabled people.","trans":"这个斜坡可以让残障人士通行。","mne":"ac一再 + cess=go行走 → 接近；入口"},{"word":"accessible","ipa":"/əkˈsesəbl/","pos":"adj.","def":"可进入的；可接近的，可到达的；可使用的","sen":"The secret garden is only accessible with the secret key.","trans":"这个秘密花园要用秘密钥匙才能进入。","mne":"ac一再 + cess=行走 + ible形容词后缀，能…的 → accessible能接触到的"},{"word":"accident","ipa":"/ˈæksɪdənt/","pos":"n.","def":"不测，事故，意外事件；意外遭遇","sen":"An accident happened, and then the egg was broken.","trans":"鸡蛋意外摔倒，然后碎了。","mne":"ac强调 + cid降下 + ent为名词词尾 → 偶然降临的事 → accident偶然的事，意外"},{"word":"acclaim","ipa":"/əˈkleɪm/","pos":"n.","def":"欢呼，赞扬，称赞；  v.欢呼，喝彩","sen":"She was highly acclaimed for her wonderful performance.","trans":"她因自己出色的成绩受到了高度称赞。","mne":"ac去 + claim呼喊 → acclaim喝彩，赞扬"},{"word":"accommodate","ipa":"/əˈkɑːmədeɪt/","pos":"v.","def":"容纳；适应","sen":"The hostel accommodates travellers from all over the world.","trans":"这家青年旅舍为来自全球各地的游客提供住宿。","mne":"ac使 + commodate适应 → accommodate使适应，容纳"},{"word":"accommodation","ipa":"/əˌkɑːməˈdeɪʃn/","pos":"n.","def":"住处，停留处；工作场所；住宿，膳宿","sen":"Her accommodation during her travel is a nice hotel.","trans":"她旅行期间的住处是一间不错的酒店。","mne":"accommodat(e)使适应，容纳 + ion名词后缀 → accommodation住所"},{"word":"accompany","ipa":"/əˈkʌmpəni/","pos":"v.","def":"陪伴；为……伴奏（或伴唱）","sen":"I always accompany my children to their school.","trans":"我总是陪着我的孩子去学校。","mne":"ac使 + company做伴 → accompany陪伴"},{"word":"accomplish","ipa":"/əˈkɑːmplɪʃ/","pos":"v.","def":"（通过努力）完成；实现","sen":"She accomplished her weight-loss goal.","trans":"她完成了自己的减肥目标。","mne":"ac使 + complish填满 → 已经填满的 → accomplish完成"},{"word":"accomplishment","ipa":"/əˈkɑːmplɪʃmənt/","pos":"n.","def":"成就","sen":"His winning the Nobel Prize for Literature was a great accomplishment.","trans":"他获得诺贝尔文学奖是一项极大的成就。","mne":"ac 一再 + complish=complete 造成... + ment 表示行为、行为的过程或结果 → n. 成就；完成；技艺，技能"},{"word":"according","ipa":"/əˈkɔːrdɪŋ/","pos":"prep.","def":"根据","sen":"According to the map, we should go this way.","trans":"根据地图来看，我们应该走这边。","mne":""},{"word":"according to","ipa":"/əˈkɔːrdɪŋ tuː/","pos":"phr.","def":"根据，按照","sen":"According to the law, you are guilty.","trans":"根据法律，你的罪名成立。","mne":""},{"word":"account","ipa":"/əˈkaʊnt/ ","pos":"n.","def":"账目，账户；描述；叙述；  v.做出说明（或解释）；占（一定数量或比例）","sen":"I have no money in my bank account.","trans":"我的银行账户里没有钱。","mne":"ac去 +count计算 → 去计算 → account算账，账目"},{"word":"accumulate","ipa":"/əˈkjuːmjəleɪt/","pos":"v.","def":"积累，累积","sen":"Long-term exposure to air pollutants may cause toxins to accumulate in the lungs.","trans":"长期接触空气污染物可能导致毒素在肺部积累。","mne":"ac(ad)=to, towards 朝着；靠近 + cumul堆积 + ate使 → 朝着……堆积 → accumulate积累"},{"word":"accumulation","ipa":"/əˌkjuːmjəˈleɪʃn/","pos":"n.","def":"积聚，累积","sen":"The accumulation of coins took a lot of time.","trans":"硬币的累积需要很长时间。","mne":"accumulat积累 + ion名词后缀 → accumulation积累"},{"word":"accuracy","ipa":"/ˈækjərəsi/","pos":"n.","def":"准确度","sen":"She is a professional archer who always shoots with high accuracy.","trans":"她是一名职业射箭手，总是射得很准。","mne":"accura=accurate准确的 + cy名词后缀 → accuracy准确度"},{"word":"accurate","ipa":"/ˈækjərət/","pos":"adj.","def":"准确的，正确的","sen":"I never miss my target because my aim is so accurate.","trans":"我从未脱靶，因为我瞄得很准。","mne":"ac加强语气 + cur关心 + ate形容词词尾 → 去关注、关心，不马虎大意 → accurate准确的；精确的"},{"word":"accusation","ipa":"/ˌækjuˈzeɪʃn/","pos":"n.","def":"谴责","sen":"The accusations from different people make him lower his head in shame.","trans":"来自不同人的指责让他羞愧地低下了头。","mne":"accus(e) 指责 + ation名词后缀 → accusation指责"},{"word":"accuse","ipa":"/əˈkjuːz/","pos":"v.","def":"指责；控告；把……归咎于","sen":"They accused each other of being wrong.","trans":"他们相互指责对方做错了。","mne":"ac=ad有关 + cuse起因；诉讼 → accuse指控"},{"word":"accustomed","ipa":"/əˈkʌstəmd/","pos":"adj.","def":"习惯于；通常的，惯常的","sen":"He got accustomed to the food after 10 years of living here.","trans":"在这里住了十年之后，他习惯了这里的食物。","mne":"ac加强意义 + custom习惯 + ed形容词后缀 → accustomed习惯的"},{"word":"ache","ipa":"/eɪk/","pos":"n.","def":"疼痛；  v.觉得疼痛","sen":"Mark had an ache in his back.","trans":"马克背部疼痛。","mne":""},{"word":"achieve","ipa":"/əˈtʃiːv/","pos":"v.","def":"实现，（尤指凭长期努力）达到（某目标）","sen":"She managed to achieve great success in her career.","trans":"她成功地在职业生涯中取得了巨大的成就。","mne":"ad去 + chieve=chief头 → 到头，达到 → achieve完成，达到"},{"word":"achievement","ipa":"/əˈtʃiːvmənt/","pos":"n.","def":"成就；实现；成绩","sen":"He is known for his great achievements in the sport of tennis.","trans":"他在网球运动上的成就令人瞩目。","mne":"achieve达成 + ment表示行为、行为的过程或结果 → achievement成就；实现"},{"word":"acknowledge","ipa":"/əkˈnɑːlɪdʒ/","pos":"v.","def":"承认；认可；告知收到","sen":"The boy acknowledged breaking the glass.","trans":"小男孩承认自己打碎了杯子。","mne":"ac使 + knowledge了解 → acknowledge承认，认知"},{"word":"acquaint","ipa":"/əˈkweɪnt/","pos":"v.","def":"使认识；使熟悉","sen":"I am trying to get acquainted with my new colleague.","trans":"我正努力认识新同事。","mne":"ac使 + quaint知道 → acquaint使认识，使熟悉"},{"word":"acquaintance","ipa":"/əˈkweɪntəns/","pos":"n.","def":"相识的人，熟人","sen":"He met an old acquaintance at his friend's wedding.","trans":"他在朋友的婚礼上遇见了一位老熟人。","mne":"acquaint熟悉 + ance名词后缀 → acquaintance认识，熟人"},{"word":"acquire","ipa":"/əˈkwaɪər/","pos":"v.","def":"（通过努力、能力）获得；学到；得到","sen":"The little boy acquired knowledge of the universe from observing.","trans":"小男孩通过观察学到了关于宇宙的知识。","mne":"ac加强 + quir寻求，询问 + e → acquire取得，学到"},{"word":"acquisition","ipa":"/ˌækwɪˈzɪʃ(ə)n/","pos":"n.","def":"获得；掌握；收购","sen":"We study for the acquisition of knowledge.","trans":"我们为了获得知识而读书。","mne":"ac加强 + quis询问 + ition名词后缀 → 通过询问得到 → 获得；增添的人(或物)"},{"word":"act","ipa":"/ækt/","pos":"v.","def":"表演，扮演；行动；  n.行为，行动；（戏剧、歌剧等的）一幕；法案","sen":"The girl will act the part of princess in the play.","trans":"这个女孩将在剧中扮演公主的角色。","mne":"act行动，做 → act表演，装作"},{"word":"action","ipa":"/ˈækʃn/","pos":"n.","def":"行为；行动","sen":"It is a polite action to offer your seat to old people.","trans":"给老人让座是一种有礼貌的行为。","mne":"act行动 + ion表行为，情况 → action行为"},{"word":"active","ipa":"/ˈæktɪv/","pos":"adj.","def":"积极的，主动的；活跃的","sen":"Students should take an active approach to studying.","trans":"学生们应该采取积极有效的学习方法。","mne":"act行动 + ive有…...性质的 → active积极的"},{"word":"activity","ipa":"/ækˈtɪvəti/","pos":"n.","def":"活动；活跃","sen":"They all like outdoor activities.","trans":"他们都喜欢户外活动。","mne":"act行动，做 + ivity名词后缀 → 活动 → activity活动"},{"word":"actor","ipa":"/ˈæktər/ ","pos":"n.","def":"演员，男演员","sen":"The actor is rehearsing his lines.","trans":"这位演员正在排练他的台词。","mne":"act表演 + or名词后缀：人 → actor演员"},{"word":"actress","ipa":"/ˈæktrəs/","pos":"n.","def":"女演员","sen":"The actress is practising her line on the stage.","trans":"这位女演员正在舞台上练习她的台词。","mne":"act表演 + ress女性 → actress女演员"},{"word":"actual","ipa":"/ˈæktʃuəl/","pos":"adj.","def":"实际的，真实的","sen":"I refused the red packet, but the actual fact was that I wanted it.","trans":"我拒绝了那个红包，但事实上我想要它。","mne":"act行动 + ual形容词后缀 → actual现实的，现行的"},{"word":"actually","ipa":"/ˈæktʃuəli/","pos":"adv.","def":"实际上；事实上；竟然（表示惊讶）","sen":"Mary may appear to be reading, but actually she is thinking about food.","trans":"玛丽看起来像是在看书，但实际上，她正想着食物。","mne":""},{"word":"adapt","ipa":"/əˈdæpt/","pos":"v.","def":"适应；改编","sen":"This animal changes its color to adapt to its new surroundings.","trans":"这只动物为适应新环境改变自身的颜色。","mne":"ad朝向 + apt适应 → adapt使适合"},{"word":"add","ipa":"/æd/","pos":"v.","def":"加，增加","sen":"Add some milk to the bowl.","trans":"往碗里加点牛奶。","mne":"ad往，到 + d给予 → add加，增加"},{"word":"addition","ipa":"/əˈdɪʃn/","pos":"n.","def":"加法；附加物","sen":"Simple addition is the easiest part of math class.","trans":"简单加法是数学课中最容易的部分。","mne":"add加 + ition名词后缀 → addition附加，附加物"},{"word":"additional","ipa":"/əˈdɪʃənl/","pos":"adj.","def":"增加的；附加的","sen":"He had to pay an additional charge for the overweight luggage.","trans":"他得为超重的行李支付额外的费用。","mne":"add加上 + ition名词后缀 + al形容词后缀 → additional附加的，追加的"},{"word":"address","ipa":"/ˈædres/, /əˈdres/","pos":"n.","def":"地址，住址；致辞；  v.写姓名地址；向……讲话","sen":"You must write down the address before sending a letter.","trans":"寄信之前你必须写上地址。","mne":""},{"word":"adequate","ipa":"/ˈædɪkwət/","pos":"adj.","def":"足够的，充分的；尚可的，过得去的","sen":"The meal would not feed a family, but it was adequate for two.","trans":"这一餐不够一家人吃，但够两个人的量。","mne":"ad加强意义 + equ相等 + ate…的 → 与所要求的相等 → adequate足够的"},{"word":"adhere","ipa":"/ədˈhɪr/","pos":"v.","def":"黏附；附着，粘在……上","sen":"I used glue to adhere the poster to the wall.","trans":"我用胶水把海报贴在墙上。","mne":"ad做…，加强… + here粘 → 粘在一起 → 坚持"},{"word":"adjective","ipa":"/ˈædʒɪktɪv/","pos":"n.","def":"【语法学】形容词","sen":"We use adjectives to describe things.","trans":"我们用形容词来描述物体。","mne":"ad向，朝 + ject扔 + ive形容词后缀 → 扔上去的，附加上去的 → adjective形容词"},{"word":"adjust","ipa":"/əˈdʒʌst/","pos":"v.","def":"调整，调节；适应","sen":"It's too hot in the room; I'll adjust the temperature.","trans":"房间里太热了，我调节一下温度。","mne":"ad做…，加强… + just正确 → 弄正确 → 调整"},{"word":"administer","ipa":"/ədˈmɪnɪstər/","pos":"v.","def":"管理；执行；实施；给予","sen":"His job as manager is to administer many departments within the company.","trans":"作为经理，他的工作是管理公司内部的许多部门。","mne":"ad去，往 + minister服务，参加 → administer管理，执行"},{"word":"administration","ipa":"/ədˌmɪnɪˈstreɪʃn/","pos":"n.","def":"管理，行政","sen":"She works in the university's administration office.","trans":"她在大学的行政办公室里工作。","mne":"ad表加强 + ministr管理 + ation名词后缀 → 行政，管理 → administration管理"},{"word":"administrative","ipa":"/ədˈmɪnɪstreɪtɪv/","pos":"adj.","def":"行政的，管理的","sen":"She was busy with administrative work all day.","trans":"她一整天都忙于行政工作。","mne":"ad一再 + ministr=minister招待 + ative有……作用的 → adj. 管理的，行政的"},{"word":"admire","ipa":"/ədˈmaɪər/","pos":"v.","def":"钦佩，崇拜","sen":"The little girl admires this boxer and sees her as a model.","trans":"小女孩崇拜这位拳击手并将她视为榜样。","mne":"ad关于 + mire感到惊讶 → admire钦佩"},{"word":"admission","ipa":"/ədˈmɪʃn/","pos":"n.","def":"准许进入；进入权","sen":"Children can gain admission to primary school at the age of 6.","trans":"孩子要到6岁才能上小学。","mne":"ad向.... + mission放开；发送 → admission承认，允许进入"},{"word":"admit","ipa":"/ədˈmɪt/","pos":"v.","def":"承认；准许进入","sen":"The boy admitted that he broke the vase.","trans":"小男孩承认是他弄碎了花瓶。","mne":"ad去，往 + mit送，放出 → 送来 → admit许可进入"},{"word":"adolescent","ipa":"/ˌædəˈlesnt/","pos":"n.","def":"青少年；  adj.青少年的；青春期的","sen":"Acne is common among adolescents.","trans":"青少年长粉刺很普遍。","mne":"adolesc进入青春期 + ent表示具有……性质的，关于……的 → 青春期的,青少年的"},{"word":"adopt","ipa":"/əˈdɑːpt/ ","pos":"v.","def":"收养；采纳，采用","sen":"The couple adopted a child from the orphanage.","trans":"这对夫妻从孤儿院收养了一个孩子。","mne":"ad做…，加强… + opt选择 → 选出来 → adopt采纳，收养"},{"word":"adult","ipa":"/əˈdʌlt/","pos":"n.","def":"成年人，成年动物；  adj.成年的；成年人的；（内容）色情的","sen":"An adult is a person who is 18 years old or over.","trans":"成年人的年龄大于或等于18岁。","mne":"ad(to)去 + ul成长 + t → adult成人"},{"word":"advance","ipa":"/ədˈvæns/","pos":"n.","def":"预先；进步，进展；  v.提前；前进；发展，进步；  adj.预先的，事先的","sen":"He finished his homework in advance.","trans":"他提前做完了作业。","mne":"ab（从、离开）+ ante（前面的、在前方）→ 拉丁语 abante → 古法语 avance（b变v，ante 变 ance）→ 英语误变 ad 得 advance（向前推进、提升）"},{"word":"advanced","ipa":"/ədˈvænst/","pos":"adj.","def":"先进的；高级的","sen":"The robot is so advanced that it can cook all kinds of meals.","trans":"这个机器人很先进，能做各式各样的饭菜。","mne":"advanc前进 + ed……的 → 往前进的 → advanced先进的，高级的"},{"word":"advantage","ipa":"/ədˈvæntɪdʒ/","pos":"n.","def":"优势；好处，优点；【化】优点","sen":"The man with the rocket gets a huge advantage.","trans":"坐着火箭的人占了很大的优势。","mne":""},{"word":"adventure","ipa":"/ədˈventʃər/","pos":"n.","def":"冒险，冒险活动","sen":"The boy went on an adventure in the jungle.","trans":"这个男孩去丛林里冒险了。","mne":"ad做…，加强… + venture冒险 → adventure冒险"},{"word":"advertise","ipa":"/ˈædvərtaɪz/","pos":"v.","def":"为……做广告","sen":"This rich man is advertising breakfast cereal.","trans":"富翁史密斯在为这款早餐麦片打广告。","mne":"ad再 + vert转变 + ise使…… → 转变客户想法 → advertise为……做广告"},{"word":"advertisement","ipa":"/ˌædvərˈtaɪzmənt/","pos":"n.","def":"广告","sen":"This advertisement is used to promote a new product.","trans":"这则广告的目的是推广新产品。","mne":"advertise做广告 + ment表名词 → advertisement广告"},{"word":"advertiser","ipa":"/ˈædvərtaɪzər/","pos":"n.","def":"广告客户；报幕员","sen":"He is an effective advertiser.","trans":"他是一个有影响力的广告人。","mne":"ad加强 + vert转 + is名词后缀 + er表示人 → 使顾客注意力转移到商品上的人 → advertiser广告客户；刊登广告的人"},{"word":"advice","ipa":"/ədˈvaɪs/","pos":"n.","def":"建议，意见","sen":"The doctor is giving her some good advice.","trans":"医生正给予她一些好的建议。","mne":""},{"word":"advisable","ipa":"/ədˈvaɪzəbl/","pos":"adj.","def":"明智的；可取的","sen":"It's advisable to eat more vegetables if you want to keep fit.","trans":"如果你想保持健康，多吃蔬菜是明智的选择。","mne":"advis=advise建议的 + able …的 → 可以参照的 → 可取的；明智的"},{"word":"advise","ipa":"/ədˈvaɪz/","pos":"v.","def":"建议；劝告，忠告；通知","sen":"My friend advised me to use this app when I failed the English exam.","trans":"当我的英语考试不及格时，我的朋友建议我用这个应用程序。","mne":"ad朝向 + vise看见 → 看向某人 → （向某人）建议，劝告"},{"word":"adviser","ipa":"/əd'vaɪzə/","pos":"n.","def":"顾问（=advisor）","sen":"The adviser is giving advice on the company's development.","trans":"顾问正在对公司的发展提出建议。","mne":""},{"word":"advisor","ipa":"/ədˈvaɪzər/","pos":"n.","def":"顾问","sen":"Our financial advisor helps us with our money plans.","trans":"我们的理财顾问帮助我们制定财务计划。","mne":""},{"word":"advocate","ipa":"/ˈædvəkeɪt/","pos":"v.","def":"提倡，主张；  n.提倡者；拥护者；辩护律师","sen":"Experts advocate a healthy diet and regular exercise.","trans":"专家提倡健康的饮食和规律的锻炼。","mne":"ad朝向 + voc喊叫 + ate动词词尾 → advocate提倡；鼓吹"},{"word":"affair","ipa":"/əˈfer/","pos":"n.","def":"事情，事务；私通，风流韵事","sen":"The CEO is handling some commercial affairs.","trans":"这位总裁正在处理一些商务事宜。","mne":"af加强 + fair=fact做 → affair事务"},{"word":"affect","ipa":"/əˈfekt/","pos":"v.","def":"影响；深深打动","sen":"Secondhand smoking may affect people's health.","trans":"吸二手烟会影响人的健康。","mne":"af加强 + fect做，制作 → 做得让人加强印象 → affect影响；感动"},{"word":"affection","ipa":"/əˈfekʃn/","pos":"n.","def":"感情；喜爱，钟爱；疾病","sen":"The girl sent her mother a card and flowers to show her deep affection.","trans":"女孩送了妈妈一张卡片和鲜花来表达自己对她深深的感情。","mne":"affect情感上深深打动 + ion为名词后缀 → affection喜爱"},{"word":"afford","ipa":"/əˈfɔːrd/","pos":"v.","def":"买得起；提供；负担得起","sen":"Finally, I can afford this car.","trans":"我终于买得起这辆车了。","mne":""},{"word":"affordable","ipa":"/əˈfɔːrdəbl/","pos":"adj.","def":"买得起的，担负得起的","sen":"He is thinking about whether a bicycle is affordable for him.","trans":"他正在考虑是否买得起一辆自行车。","mne":"afford负担 + able有能力的 → affordable负担得起的，能承受的"},{"word":"afraid","ipa":"/əˈfreɪd/","pos":"adj.","def":"害怕的，畏惧的","sen":"The dog looks afraid of the man.","trans":"这只狗看上去害怕这个男人。","mne":"af走出，在...之外 + raid友善，爱 → 远离好的情绪 → afraid害怕的"},{"word":"after","ipa":"/ˈæftər/","pos":"adv.","def":"后来，以后；  prep.【数】在...之后","sen":"They lived happily ever after.","trans":"他们从此过上了幸福的生活。","mne":"af=of离开 + ter后缀 → after在...之后"},{"word":"afternoon","ipa":"/ˌæftərˈnuːn/","pos":"n.","def":"午后，下午","sen":"I have to go back to work in the afternoon.","trans":"下午我不得不回去工作。","mne":"after之后 + noon中午 → 中午之后 → afternoon午后，下午"},{"word":"afterward","ipa":"/'ɑːftəwəd/","pos":"adv.","def":"之后，后来，以后","sen":"Afterward, please clean up your dog's poop.","trans":"随后，请清洁你家狗狗的便便。","mne":"after以后 + ward向...的 → afterward之后"},{"word":"afterwards","ipa":"/ˈæftərwərdz/","pos":"adv.","def":"后来","sen":"They had a romantic dinner and decided to watch a movie afterwards.","trans":"他们吃了一顿浪漫的晚餐，然后决定去看电影。","mne":"after随后 + ward向…后 + s表副词 → afterwards后来；然后"},{"word":"again","ipa":"/əˈɡen/ ","pos":"adv.","def":"又，再次","sen":"It looks like it will rain again.","trans":"看起来又要下雨了。","mne":"a在 + gain相反，相对 → 在相反的方向，回到此前位置 → again又，再次"},{"word":"against","ipa":"/əˈɡenst/","pos":"prep.","def":"反对；对（着），逆；违反；靠近，倚在；紧靠，碰，撞","sen":"We should all stand against animal cruelty!","trans":"我们都应该抵制虐待动物的行为！","mne":""},{"word":"age","ipa":"/eɪdʒ/","pos":"n.","def":"年龄；时代；  v.（使）变老","sen":"He started playing the piano at an early age.","trans":"他幼年开始弹钢琴。","mne":""},{"word":"agency","ipa":"/ˈeɪdʒənsi/","pos":"n.","def":"代理机构；(政府的)局，处；服务机构","sen":"It's more convenient to buy tickets from a ticket agency.","trans":"从车票代售点买票更方便。","mne":"ag做，代理做 + ency表示机构或状态 → 代理处"},{"word":"agenda","ipa":"/əˈdʒendə/","pos":"n.","def":"议程，议程表；议事日程","sen":"\"There are many items that need to be discussed on the agenda\", she said.","trans":"“议程上有许多事情需要讨论。”安迪说道。","mne":"ag做，代理做 + enda表示复数 → 做的事情 → agenda议事日程"},{"word":"agent","ipa":"/ˈeɪdʒənt/","pos":"n.","def":"代理商，代理人；特工；动因；药剂","sen":"There are some real estate agents waiting for customers at the subway entrance.","trans":"一些房产中介在地铁口等待顾客。","mne":"ag做，代理做 + ent表人或物 → 代理人 → agent作用因素；代理人"},{"word":"aggression","ipa":"/əˈɡreʃn/","pos":"n.","def":"侵略；侵犯，侵害","sen":"A war of aggression started by aliens is very common in movies.","trans":"外星人发动侵略战争的情节在电影中很常见。","mne":"ag一再 + gress走 + ion名词后缀 → 一再往前走 → 进攻，侵略"},{"word":"aggressive","ipa":"/əˈɡresɪv/","pos":"adj.","def":"有侵略性的；有攻击性的；积极进取的","sen":"I was terrified by this aggressive dog.","trans":"我被这只攻击性很强的狗吓到了。","mne":"ag朝，向 + gress行走 + ive形容词词尾 → 侵略的；进取的"},{"word":"ago","ipa":"/əˈɡoʊ/","pos":"adv.","def":"以前","sen":"I started going to school a few years ago.","trans":"我几年前就上学了。","mne":""},{"word":"agony","ipa":"/ˈæɡəni/","pos":"n.","def":"极大的痛苦","sen":"The man is in agony after hearing the bad news.","trans":"在听到这个坏消息之后，这个人陷入了极大的痛苦中。","mne":"agon挣扎 + y表名词 → agony痛苦"},{"word":"agree","ipa":"/əˈɡriː/","pos":"v.","def":"同意，赞成","sen":"She agreed to go shopping with her friend.","trans":"她同意和朋友一起去购物。","mne":"a=ad去 + gree支持，欢迎 → agree同意"},{"word":"agreement","ipa":"/əˈɡriːmənt/","pos":"n.","def":"一致，相合；同意；一致意见；协议，协定","sen":"We reached an agreement on this idea.","trans":"我们就这个想法达成一致。","mne":""},{"word":"agricultural","ipa":"/ˌæɡrɪˈkʌltʃərəl/","pos":"adj.","def":"农业的","sen":"Technological advancements have improved agricultural efficiency.","trans":"科技进步提高了农业生产的效率。","mne":"agri田地，农业 + cult培养 + ur=ure表名词 + al形容词后缀 → 农业的，农艺的，农学的"},{"word":"agriculture","ipa":"/ˈæɡrɪkʌltʃər/ ","pos":"n.","def":"农业","sen":"Farmers rely on agriculture to make a living.","trans":"农民以务农为生。","mne":"agri田地 + cult耕种 + ure表名词 → 在田地里耕作 → agriculture农业"},{"word":"ahead","ipa":"/əˈhed/","pos":"adv.","def":"领先地；提前","sen":"I am running ahead of the rest of the group.","trans":"跑步的时候，我领先于小组的其他人。","mne":"a副词前缀 + head头 → ahead在前，提前"},{"word":"aid","ipa":"/eɪd/","pos":"n.","def":"帮助；援助，帮助；  v.援助，帮助","sen":"The blind man walks with the aid of a guide dog.","trans":"那个盲人在导盲犬的帮助下走路。","mne":""},{"word":"aim","ipa":"/eɪm/","pos":"n.","def":"目的；目标；  v.瞄准，对准；力求达到，力争做到","sen":"His aim of exercising is to get more muscles.","trans":"他健身的目的是让自己练出更多肌肉。","mne":""},{"word":"air","ipa":"/er/","pos":"n.","def":"空气；天空，空中；神态，样子；  v.通风；  v.晾干","sen":"Could you blow some air into the balloons?","trans":"你能给这个气球吹点气吗？","mne":""},{"word":"air-conditioner","ipa":"/'eərkənd'ɪʃənər/","pos":"n.","def":"空调机","sen":"The air-conditioner keeps the room cool during the hot summer days.","trans":"空调在炎热夏季使房间保持凉爽。","mne":""},{"word":"air-conditioning","ipa":"/'eərkənd'ɪʃnɪŋ/","pos":"n.","def":"空调","sen":"The man is fixing the air-conditioning.","trans":"那个男人正在修理空调。","mne":""},{"word":"aircraft","ipa":"/ˈerkræft/","pos":"n.","def":"飞机，航空器","sen":"Aircraft are meant to be in the sky.","trans":"飞机注定要飞上天空。","mne":"air空气 + craft技艺 → aircraft飞行器"},{"word":"airline","ipa":"/ˈerlaɪn/","pos":"n.","def":"航空公司","sen":"The plane of this airline has some red paint at the bottom.","trans":"这个航空公司的飞机底部有一些红色的油漆。","mne":"air空气，空运 + line直线 → airline航空系统，航线"},{"word":"airplane","ipa":"/ˈerpleɪn/","pos":"n.","def":"飞机","sen":"You can go through the clouds by taking airplanes. It feels so amazing!","trans":"坐飞机可以穿过云层，那感觉太神奇了！","mne":"air空气 + plane飞机 → airplane飞机"},{"word":"airport","ipa":"/ˈerpɔːrt/","pos":"n.","def":"机场","sen":"The plane landed at the airport.","trans":"飞机降落在机场。","mne":"air空气，空中 + port港口 → airport机场，航空站"},{"word":"alarm","ipa":"/əˈlɑːrm/","pos":"n.","def":"警报器，警报；  v.使惊恐，使忧虑","sen":"He switched off the fire alarm.","trans":"他关闭了火警警报器。","mne":"a=to朝着，去 + l=the + arm武器 → 拿起武器，准备战斗 → alarm警报"},{"word":"alcohol","ipa":"/ˈælkəhɔːl/","pos":"n.","def":"酒；酒精，乙醇；含酒精饮品","sen":"I avoid alcohol because it weakens my judgment.","trans":"我不喝酒，因为它会削弱我的判断力。","mne":""},{"word":"alert","ipa":"/əˈlɜːrt/ ","pos":"adj.","def":"警惕的；  v.向……报警，使警惕；  n.警报","sen":"The cat is alert when guarding its fish.","trans":"喵星人在守卫自己的鱼的时候是很警觉的。","mne":"al=ab加强 + ert直 → alert警惕的"},{"word":"alien","ipa":"/ˈeɪliən/","pos":"n.","def":"外星人；外国人；  adj.外国的；陌生的","sen":"Do you ever think that aliens could be our friends?","trans":"你有没有想过外星人可能是我们的朋友？","mne":"ali其他的，改变状态 + en表形容词或名词 → 其他地方的 → alien外国的，外国人的，外来的"},{"word":"alike","ipa":"/əˈlaɪk/","pos":"adj.","def":"相同的，类似的；相像的；  adv.相像地，相似地","sen":"Their haircut is the only reason why they look alike.","trans":"宋小宝和贝克汉姆的同款发型是他们唯一的相似之处。ㄟ( ▔, ▔ )ㄏ","mne":"a加强意义 + like相像 → alike相同的（地）"},{"word":"alive","ipa":"/əˈlaɪv/","pos":"adj.","def":"活着的，在世；活跃的，有生气的","sen":"His beating heart shows that he is alive.","trans":"跳动的心脏表明他还活着。","mne":"a…的 + live活 → alive活的"},{"word":"all","ipa":"/ɔːl/","pos":"adv.","def":"全部（地）","sen":"My girl friends and I all went shopping.","trans":"我和女性朋友们都去购物了。","mne":""},{"word":"allow","ipa":"/əˈlaʊ/ ","pos":"v.","def":"允许，准许，许可；承认；同意","sen":"The green light allows you to go.","trans":"绿灯（表示）允许你通行。","mne":"al=ad去，向 + low表扬 → allow允许"},{"word":"allowance","ipa":"/əˈlaʊəns/","pos":"n.","def":"零用钱；津贴","sen":"He has an allowance of 3,000 dollars every month.","trans":"他每月有3 000美元零用钱。","mne":"allow分配；发津贴 + ance行为，性质 → allowance津贴"},{"word":"almost","ipa":"/ˈɔːlmoʊst/","pos":"adv.","def":"几乎，差不多","sen":"He almost reached the diamonds.","trans":"他差一点就挖到钻石了。","mne":""},{"word":"alone","ipa":"/əˈloʊn/","pos":"adj.","def":"单独的；  adv.独自地","sen":"Seesaws are not very fun when you're alone.","trans":"当你孤身一人时，跷跷板就不那么有趣了。","mne":"al全部的，完全的 + one一个 → alone单独的"},{"word":"along","ipa":"/əˈlɔːŋ/","pos":"prep.","def":"沿着；  adv.一起","sen":"She walked along the road for a long time.","trans":"她沿着马路走了很久。","mne":"a加强 + long长 → 向两边延长 → along沿着"},{"word":"alongside","ipa":"/əˌlɔːŋˈsaɪd/","pos":"prep.","def":"在旁边，和……并排；和……一起，和......同时","sen":"The prisoners are sitting alongside each other on the benches.","trans":"杨树林和他的两个狱友并排坐在长凳上。（都坐牢了还不忘耍酷）","mne":"along沿着 + side……的一边 → 沿着……的边 → alongside在旁边"},{"word":"aloud","ipa":"/əˈlaʊd/","pos":"adv.","def":"大声地；出声地","sen":"The boy is wearing earphones and singing aloud.","trans":"这个男孩正戴着耳机，大声地唱歌。","mne":"a加强意义 + loud大声 → 高声地"},{"word":"alphabet","ipa":"/ˈælfəbet/","pos":"n.","def":"字母表","sen":"The English alphabet has 26 letters.","trans":"英语字母表有26个字母。","mne":""},{"word":"already","ipa":"/ɔːlˈredi/","pos":"adv.","def":"已经","sen":"The concert has already started at 7 o'clock, hurry up!","trans":"演唱会七点就已经开始了，快点啊！","mne":"al=all全部的 + ready准备好的 → already已经"},{"word":"also","ipa":"/ˈɔːlsoʊ/","pos":"adv.","def":"也，同样；还，此外","sen":"She is also drinking his juice.","trans":"她也在喝他的果汁。","mne":""},{"word":"alter","ipa":"/ˈɔːltər/","pos":"v.","def":"改变；改动","sen":"Time alters her face.","trans":"时光改变了她的容貌。","mne":"alter其他的 → 变成〔其它的）→ alter变更，改变"},{"word":"alternate","ipa":"/ˈɔ:ltərnət/","pos":"adj.","def":"交替的，间隔的；  v.（使）交替，（使）轮流；  n.代替者","sen":"This is a week of alternate sunshine and rain.","trans":"这是晴雨交替的一周。","mne":"altern其他的，改变状态 + ate表示做、造成 → 交替的，轮流的；间隔的"},{"word":"alternative","ipa":"/ɔːlˈtɜrnətɪv/","pos":"adj.","def":"供选择的；  n.替代品","sen":"She provides an alternative choice for the girl who wants to buy a diamond ring.","trans":"她给那个想买钻戒的女生提供了另一种选择。","mne":"altern另外的 + ative形容词/名词后缀 → alternative替换的，替换物"},{"word":"although","ipa":"/ɔːlˈðoʊ/","pos":"conj.","def":"虽然，尽管，即使","sen":"Although it is a rainy day, the girl is still having fun.","trans":"尽管这是一个雨天，小姑娘还是玩得很开心。","mne":""},{"word":"altitude","ipa":"/ˈæltɪtuːd/","pos":"n.","def":"海拔；【数】高度","sen":"At this altitude it would be dangerous to fall off.","trans":"在这种高度下跌落很危险。","mne":"alt高 + itude表抽象名词 → altitude高度"},{"word":"altogether","ipa":"/ˌɔːltəˈɡeðər/","pos":"adv.","def":"总共，一共；总而言之；完全","sen":"These gifts cost me 1,000 dollars altogether.","trans":"这些礼物总共花了我1000美元。","mne":""},{"word":"always","ipa":"/ˈɔːlweɪz/","pos":"adv.","def":"总是；一直，不断地","sen":"It always rains in London.","trans":"伦敦总是下雨。","mne":"al全部 + ways方式 → 全部都是这个方式 → 总是"},{"word":"am","ipa":"/əm/ ","pos":"v.","def":"是（动词be的第一人称形式）","sen":"I am a student.","trans":"我是一个学生。","mne":""},{"word":"amaze","ipa":"/əˈmeɪz/","pos":"v.","def":"使惊奇，使惊诧","sen":"The contents on the phone amazed both men greatly.","trans":"手机上的内容让这两个人都大吃一惊。","mne":"a表加强 + maze迷宫 → 像进了迷宫一样 → amaze使诧异"},{"word":"amazing","ipa":"/əˈmeɪzɪŋ/","pos":"adj.","def":"令人惊奇的，令人惊喜的","sen":"The sunrise is so amazing!","trans":"日出美得惊人！","mne":"amaz=amaze惊异 + ing形容词后缀 → amazing令人惊异的"},{"word":"ambassador","ipa":"/æmˈbæsədər/","pos":"n.","def":"（特命全权）大使","sen":"\"Our country wishes to have peace.\" said the ambassador.","trans":"“我们国家渴望和平。”大使说道。","mne":"amb围绕 + ass驱动，拉出 + a + dor名词后缀，做...的人 → ambassador大使，代表"},{"word":"ambiguous","ipa":"/æmˈbɪɡjuəs/","pos":"adj.","def":"含糊不清的","sen":"This ambiguous image can have multiple meanings.","trans":"这个模棱两可的图像会有很多含义。","mne":"ambi两者都 + guous...的 → 模棱两可的"},{"word":"ambition","ipa":"/æmˈbɪʃn/","pos":"n.","def":"雄心，野心；抱负","sen":"This powerful man's political ambition was to unify the three kingdoms.","trans":"这个有权势的男人的政治野心是一统三国。","mne":"amb大 + it行走 + ion名词后缀 → 走大步 → ambition雄心，志向"},{"word":"ambitious","ipa":"/æmˈbɪʃəs/","pos":"adj.","def":"有抱负的，有野心的","sen":"The boy is ambitious and wants to be a successful businessman one day.","trans":"男孩很有抱负，未来想成为一个成功的商人。","mne":"amb大 + it行走 + ious形容词后缀 → 大步向前走的 → ambitious有雄心的"},{"word":"ambulance","ipa":"/ˈæmbjələns/","pos":"n.","def":"救护车","sen":"The ambulance sent the patient to the hospital.","trans":"救护车把病人送到了医院。","mne":"ambul行走，走路 ＋ ance名词后缀 → 走的东西 → ambulance救护车，流动医院"},{"word":"among","ipa":"/əˈmʌŋ/","pos":"prep.","def":"在……中间，在……之中","sen":"There is an apple among the other fruits.","trans":"这个苹果在这些水果之中。","mne":"a在...上 + mong揉捏，合身 → among处于...中，在...中间"},{"word":"amount","ipa":"/əˈmaʊnt/","pos":"n.","def":"数量；  v.总计","sen":"The amount of sugar in this product is 28g.","trans":"这一产品中糖的总量是28克。","mne":"a去，往 + mount山顶 → 去山顶 → amount总计"},{"word":"ample","ipa":"/ˈæmpl/","pos":"adj.","def":"富足的；丰满的","sen":"We're lucky to have an ample amount of food to eat.","trans":"我们非常幸运能吃到这么多食物。","mne":"ampl大，宽 + e → 很大，很宽 → ample富足的；宽敞的"},{"word":"amuse","ipa":"/əˈmjuːz/","pos":"v.","def":"使人发笑；（提供）娱乐，消遣；逗乐；娱乐","sen":"Their talk show amused the audience.","trans":"他们的脱口秀把观众逗乐了。","mne":"a使 + muse娱乐 → amuse娱乐，使发笑"},{"word":"amusement","ipa":"/əˈmjuːzmənt/","pos":"n.","def":"娱乐；消遣；乐趣；逗乐","sen":"We had a good time in the amusement park.","trans":"我们在游乐园玩得很开心。","mne":"amuse娱乐 + ment表名词 → amusement娱乐，消遣"},{"word":"an","ipa":"/ən/","pos":"art.","def":"（用在元音音素前）一","sen":"There is an apple on the plate.","trans":"盘里有一个苹果。","mne":""},{"word":"analyse","ipa":"/ˈænəlaɪz/","pos":"v.","def":"分析，分解","sen":"Knowing how to analyse the stock market, he made a lot of money.","trans":"因为他知道如何分析股票市场，所以他挣了不少钱。","mne":""},{"word":"analysis","ipa":"/əˈnæləsɪs/","pos":"n.","def":"分析报告","sen":"Could you write up an analysis of how the market is moving this week?","trans":"你能写一篇关于这周市场走势的分析报告吗？","mne":"ana完全，彻底地 + lysis解开，分开 → 彻底分开来（观察） → analysis分析"},{"word":"analyst","ipa":"/ˈænəlɪst/","pos":"n.","def":"分析员","sen":"The analyst is explaining the trend of the stock market.","trans":"分析员正在解说股市走向。","mne":"ana分开 + lyst裂开，分解 → 分解 → analyst分析者"},{"word":"analyze","ipa":"/ˈænəlaɪz/","pos":"v.","def":"【数】分析","sen":"Let's analyze the pattern of these shapes together, kids.","trans":"让我们一起分析这些形状的规律吧孩子们。","mne":"ana完全 + lyze解开 → 完全解开 → analyze分析"},{"word":"ancestor","ipa":"/ˈænsestər/","pos":"n.","def":"祖先；祖宗","sen":"It's said that the ancestors of whales may have had four limbs.","trans":"据说鲸鱼的祖先可能有四肢。","mne":"an=ante前，先 + cest=cess行走，前进 + or表人 → 走在前面的人 → ancestor祖先"},{"word":"ancient","ipa":"/ˈeɪnʃənt/","pos":"adj.","def":"古代的；古老的；  n.古代人","sen":"These ancient statues are over 2,000 years old.","trans":"这些古代雕像有2 000多年的历史。","mne":"anci古老 + ent……的 → ancient古代的"},{"word":"and","ipa":"/ənd/","pos":"conj.","def":"和，与","sen":"She and I are both confused.","trans":"她和我都很疑惑。","mne":""},{"word":"angel","ipa":"/ˈeɪndʒl/","pos":"n.","def":"天使；可爱的人","sen":"Every child is an angel to their parents.","trans":"每个孩子都是父母的天使。","mne":""},{"word":"anger","ipa":"/ˈæŋɡər/","pos":"n.","def":"怒火，怒气","sen":"The man was stuck in traffic, fuming with anger.","trans":"这名男子被堵在路上，怒火中烧。","mne":""},{"word":"angry","ipa":"/ˈæŋɡri/","pos":"adj.","def":"愤怒的","sen":"The phone call makes him very angry.","trans":"这通电话让他非常生气。","mne":"angr痛苦 + y表形容词 → angry愤怒的"},{"word":"animal","ipa":"/ˈænɪml/","pos":"n.","def":"动物","sen":"There are many kinds of animals on the Earth.","trans":"地球上的动物种类繁多。","mne":""},{"word":"anniversary","ipa":"/ˌænɪˈvɜːrsəri/","pos":"n.","def":"周年纪念日","sen":"He gave his wife a diamond ring on their tenth anniversary.","trans":"在结婚十周年之际，他送给老婆一枚钻戒。","mne":"anni=ann年 + vers转 + ary名词后缀 → 一年的转弯处一次 → anniversary周年纪念日"},{"word":"announce","ipa":"/əˈnaʊns/","pos":"v.","def":"宣布，通知","sen":"Her album was announced as the winner.","trans":"她的专辑被宣布为获奖作品。","mne":"an加强意义 + nounce通知 → announce通告"},{"word":"announcement","ipa":"/əˈnaʊnsmənt/","pos":"n.","def":"宣告；通告，公告","sen":"She makes an announcement with a loudspeaker.","trans":"她用喇叭发表声明。","mne":"an给予 + nounce讲话，说出 + ment名词后缀 → 通告"},{"word":"annoy","ipa":"/əˈnɔɪ/","pos":"v.","def":"使烦恼，使生气","sen":"Talking on your phone during a movie is likely to annoy others.","trans":"在看电影的时候打电话很可能会惹怒其他人。","mne":""},{"word":"annoyed","ipa":"/əˈnɔɪd/","pos":"adj.","def":"恼怒的，烦闷的","sen":"I am really annoyed with my roommate's snoring.","trans":"我真的被室友的鼾声搞得很烦。","mne":"annoy烦人 + ed形容词后缀 → annoyed恼怒的"},{"word":"annual","ipa":"/ˈænjuəl/","pos":"adj.","def":"年度的，一年一次的；  n.年鉴；年刊","sen":"Our company has seen a rise in annual revenues in recent years.","trans":"近年来，我们公司的年收入不断增加。","mne":"ann一年 + ual…的 → annual一年一度的"},{"word":"another","ipa":"/əˈnʌðər/","pos":"det.","def":"另外的，不同的","sen":"You have another way to the train station if you are in a traffic jam.","trans":"如果你遇到交通堵塞，你可以选择另一条路线前往火车站。","mne":""},{"word":"answer","ipa":"/ˈænsər/","pos":"n.","def":"回答，答复；答案；  v.回答，答复","sen":"I didn't know the answer to the last question.","trans":"我不知道最后一个问题的答案。","mne":"an在...前面 + swer断言，发誓 → 给出肯定的声明 → answer回答，答复"},{"word":"anticipate","ipa":"/ænˈtɪsɪpeɪt/","pos":"v.","def":"期待；提早（做）；预测，预料","sen":"I anticipate him winning the first prize as he is really great!","trans":"我期待他能得第一，因为他真的很棒！","mne":"anti前面 + cip抓 + ate动词后缀 → 开始抓 → anticipate预料；预期的"},{"word":"anticipation","ipa":"/ænˌtɪsɪˈpeɪʃn/","pos":"n.","def":"期待；预期，预料","sen":"She is full of anticipation—her baby is almost due.","trans":"她充满了期待，因为她的宝贝就要出世了。","mne":"anti反对 + cip拿、抓 + ation名词后缀 → 提前抓住 → anticipation预期，预料"},{"word":"anxiety","ipa":"/æŋˈzaɪəti/","pos":"n.","def":"焦虑；担心","sen":"His unfinished homework is causing him anxiety.","trans":"作业没写完使他焦虑不安。","mne":"anxi焦虑 + e + ty名词后缀 → anxiety焦虑"},{"word":"anxious","ipa":"/ˈæŋkʃəs/","pos":"adj.","def":"焦虑的，不安的；渴望的；急切的","sen":"The boy is anxious about the exam.","trans":"这个男孩对考试感到焦虑。","mne":"anxi焦虑 + ous形容词后缀 → anxious焦虑的"},{"word":"any","ipa":"/ˈeni/","pos":"pron.","def":"任何一个","sen":"You can ride any of these bikes.","trans":"你可以骑这些自行车里的任何一辆。","mne":""},{"word":"anybody","ipa":"/ˈenibɑːdi/","pos":"pron.","def":"随便哪个人；任何人；  n.重要人物","sen":"He is taller than anybody else present.","trans":"他比在场的其他任何人都高。","mne":"any任何 + body身体 → anybody任何人"},{"word":"anyhow","ipa":"/ˈenihaʊ/","pos":"adv.","def":"不论用何种方法，无论如何","sen":"Someone has to wash the dishes anyhow, so I'll do it.","trans":"反正得有人洗碗，那就我洗吧。","mne":"any无论 + how怎么 → 无论如何 → anyhow无论如何"},{"word":"anyone","ipa":"/ˈeniwʌn/","pos":"pron.","def":"任何人，无论什么人","sen":"It's very discouraging for anyone to be out of a job.","trans":"对于任何人来说，失业都是非常令人沮丧的。","mne":"any任何 + one一个 → anyone任何一个"},{"word":"anything","ipa":"/ˈeniθɪŋ/","pos":"pron.","def":"任何事；任何事物","sen":"Welcome! Is there anything I can help you with?","trans":"欢迎光临！请问有什么可以帮您的吗？","mne":"any任何 + thing事物 → anything任何东西"},{"word":"anyway","ipa":"/ˈeniweɪ/","pos":"adv.","def":"无论如何，总之","sen":"It doesn't matter; they all go to the same place anyway.","trans":"没关系，所有路无论如何都通向一个地方。","mne":"any无论 + way方式 → anyway无论如何"},{"word":"anywhere","ipa":"/ˈeniwer/","pos":"adv.","def":"任何地方，无论何处","sen":"You can connect to the internet from anywhere in the world.","trans":"你可以从世界上的任何地方连接到互联网。","mne":"any任何 + where哪里 → anywhere无论何处"},{"word":"apart","ipa":"/əˈpɑːrt/","pos":"adv.","def":"分离地，分开地；  adj.分隔的，拆开的，撇开的","sen":"They set one man apart from the rest.","trans":"他们把一个人与其他人分开了。","mne":"a=ad去，向 + part授予，分配 → apart分离，分开"},{"word":"apartment","ipa":"/əˈpɑːrtmənt/","pos":"n.","def":"<美>公寓","sen":"We have rented an apartment; time to buy some furniture.","trans":"我们租了一套公寓，现在该去买些家具了。","mne":"apart分离的，分开的 + ment名词后缀 → 楼房分隔开住的地方 → 一套公寓房间"},{"word":"apologise","ipa":"/əˈpɑːlədʒaɪz/","pos":"v.","def":"道歉，认错（=apologize）","sen":"I should apologise to my friend for what I did.","trans":"我应该为我的所作所为向我朋友道歉。","mne":"apo离开 + log演说 + ise → 表动词退后一步说 → apologise道歉"},{"word":"apologize","ipa":"/əˈpɑːlədʒaɪz/","pos":"v.","def":"认错；道歉（=apologise）","sen":"The cat apologized to its owner for breaking the vase.","trans":"这只猫为打碎花瓶而向主人认错。","mne":""},{"word":"apology","ipa":"/əˈpɑːlədʒi/","pos":"n.","def":"道歉，歉意","sen":"He is making an apology to his boss.","trans":"他在向他的老板道歉。","mne":"apo离开 + logy说话 → 退后一步说 → apology道歉"},{"word":"apparent","ipa":"/əˈpærənt/","pos":"adj.","def":"显然的；表面上的，貌似（真实）的","sen":"It's apparent that the boy is taller than the girl.","trans":"很明显，那个男孩比女孩高。","mne":"ap加强意义 + par看见 + ent…的 → 能看见的 → apparent清晰易见的；显然的"},{"word":"apparently","ipa":"/əˈpærəntli/","pos":"adv.","def":"显然；看来，似乎","sen":"Apparently, this chair is too small for the elephant.","trans":"对大象来说，这把椅子显然太小了。","mne":""},{"word":"appeal","ipa":"/əˈpiːl/","pos":"v.","def":"请求；呼吁；有吸引力；上诉","sen":"They appealed to everyone to help protect the environment.","trans":"他们请求大家一起保护环境。","mne":"ap=ad去，向 + peal促使，推进 → appeal呼吁；上诉"},{"word":"appear","ipa":"/əˈpɪr/","pos":"v.","def":"出现，呈现，露面；  link-v.显得，似乎","sen":"She appeared on stage as a surprise guest at the concert.","trans":"她作为演唱会嘉宾突然出现在舞台上。","mne":"ap再 + pear看见 → 看见 → appear出现，显露"},{"word":"appearance","ipa":"/əˈpɪrəns/","pos":"n.","def":"外貌，外表；出现，公开露面","sen":"She is checking her appearance in the mirror.","trans":"她正在对着镜子检查自己的外表。","mne":"appear出现，显露 + ance性质，状况 → 显露出的性质 → appearance外貌 "},{"word":"appendix","ipa":"/əˈpendɪks/","pos":"n.","def":"附录；阑尾","sen":"There is no appendix in this notebook.","trans":"这本书没有附录。","mne":""},{"word":"appetite","ipa":"/ˈæpɪtaɪt/","pos":"n.","def":"食欲；嗜好","sen":"I had a very healthy appetite and finished the whole meal.","trans":"我的胃口很好，吃光了整顿饭。","mne":"ap加强动作 + pet追寻，寻求 + ite表名词 → 一再追求 → appetite胃口，欲望"},{"word":"applaud","ipa":"/əˈplɔːd/","pos":"v.","def":"鼓掌；称赞","sen":"The audience laughed and applauded.","trans":"观众边笑边鼓掌。","mne":"ap使 + plaud鼓掌 → applaud鼓掌；喝彩"},{"word":"applause","ipa":"/əˈplɔːz/","pos":"n.","def":"鼓掌，掌声；喝彩","sen":"The cat praised herself with a round of applause.","trans":"帕克为自己鼓掌称赞。","mne":"ap一再 + plause=plaud赞扬 → 一再赞扬 → applause掌声"},{"word":"apple","ipa":"/ˈæpl/","pos":"n.","def":"苹果","sen":"I had an apple for breakfast today.","trans":"我今天早餐吃了一个苹果。","mne":""},{"word":"appliance","ipa":"/əˈplaɪəns/","pos":"n.","def":"家用电器，器具；器具，器械","sen":"I spent all my money on domestic appliances, like TVs and refrigerators.","trans":"我把所有钱都花在像电视和冰箱这种家用电器上了。","mne":"apply适用 + ance表名词 → appliance家用电器，应用"},{"word":"applicable","ipa":"/ˈæplɪkəbl/","pos":"adj.","def":"【法】可适用的","sen":"This license is applicable only to the Software.","trans":"本许可仅适用于该软件。","mne":"ap一再+plic重叠、折叠+able能... → applicable适用的"},{"word":"applicant","ipa":"/ˈæplɪkənt/","pos":"n.","def":"申请人；请求者","sen":"The applicants are waiting outside before the interview.","trans":"面试之前，申请人在外面等候。","mne":""},{"word":"application","ipa":"/ˌæplɪˈkeɪʃn/","pos":"n.","def":"应用程序；申请（表）","sen":"I download many applications on my cellphone.","trans":"我在手机上下载了许多应用程序。","mne":"apply放置到=应用 + cation表名词 → application应用，运用"},{"word":"apply","ipa":"/əˈplaɪ/","pos":"v.","def":"涂，施于；申请；应用","sen":"Don't forget to apply sunscreen if you spend time out in the sun.","trans":"如果你要长时间待在太阳下，一定别忘记涂防晒霜。","mne":"ap去 + ply应用 → 去运用起来 → apply申请，应用"},{"word":"appoint","ipa":"/əˈpɔɪnt/","pos":"v.","def":"委派，任命；确定，约定","sen":"My boss has appointed me to manage this project.","trans":"我的老板已任命我来管理这个项目。","mne":"ap加强 + point指 → appoint指定；任命"},{"word":"appreciate","ipa":"/əˈpriːʃieɪt/","pos":"v.","def":"感谢，感激；欣赏；增值","sen":"Grandma appreciated the gift on her birthday.","trans":"外婆为她生日那天收到的礼物表示感谢。","mne":"ap一再 + preci价值 + ate动词后缀 → 一再给价 → appreciate欣赏"},{"word":"appreciation","ipa":"/əˌpriːʃiˈeɪʃn/","pos":"n.","def":"鉴赏，欣赏；感激；理解，了解","sen":"Appreciation of art is a skill that needs to be nurtured.","trans":"艺术鉴赏是一种需要培养的技能。","mne":"ap一再 + preci价值 + ation名词后缀，表示行为 → 一再估价 → 评价，鉴赏，欣赏"},{"word":"approach","ipa":"/əˈproʊtʃ/","pos":"v.","def":"靠近；接近；着手处理；  n.接近；途径；方法","sen":"The ship is approaching the shore at a high speed.","trans":"这艘船正以很快的速度靠近岸边。","mne":"ap一再 + proach接近 → approach接近"},{"word":"appropriate","ipa":"/əˈprəʊpriət/","pos":"adj.","def":"合适的，适当的；  v.挪用；拨款；私占","sen":"Slippers are not appropriate​ for a job interview.","trans":"拖鞋不适合在求职面试时穿。","mne":"ap=ad到 + propri正确的 + ate形容词后缀 → appropriate合适的，适当的"},{"word":"appropriately","ipa":"/əˈproʊpriətli/","pos":"adv.","def":"合适地","sen":"Dress up appropriately for different occasions.","trans":"要根据不同场合穿合适的衣服。","mne":"ap一再+propri恰当+ate形容词后缀+ly...地→适当地；合适的；相称地"},{"word":"approval","ipa":"/əˈpruːvl/","pos":"n.","def":"批准；赞同","sen":"The doctor gives me his approval to leave the hospital.","trans":"医生批准我出院。","mne":"ap一再 + prov证明 + al名词后缀 → 赞成"},{"word":"approve","ipa":"/əˈpruːv/","pos":"v.","def":"正式核准，称许；赞成；满意","sen":"They all approve of my good performance.","trans":"他们都称许我良好的表现。","mne":"ap加强 + prove证明 → approve承认，赞成"},{"word":"approximate","ipa":"/əˈprɑːksəmət/, /əˈprɑksəmeɪt/","pos":"adj.","def":"近似的（读作/əˈprɑːksəmət/）；  v.接近，近似（读作/əˈprɑksəmeɪt/）","sen":"The approximate value of this car is 3,000 dollars.","trans":"这辆车价值大约3000美元。","mne":"ap不断 + proxim接近 + ate表动词 → 不断靠近 → approximate接近的，近似的"},{"word":"approximately","ipa":"/əˈprɑːksɪmətli/","pos":"adv.","def":"近似地，大约","sen":"Pi is approximately equal to 3.1416.","trans":"圆周率大约等于3.1416。","mne":"ap引申 + proxim接近 + ate形容词后缀 + ly...地 → approximately大约，近似地；近于"},{"word":"april","ipa":"/ˈeɪprəl/","pos":"n.","def":"四月（略作Apr.）","sen":"Everything turns green in April as a result of all the rain it brings.","trans":"四月带来了充沛的雨水，令万物呈现一派绿意。","mne":""},{"word":"arbitrary","ipa":"/ˈɑːrbɪtreri/","pos":"adj.","def":"随意的，任性的，随心所欲的；霸道的，专制的，蛮横的；主观的，武断的","sen":"Tossing a coin is a rather arbitrary method of making a choice.","trans":"靠抛硬币来做选择实在是太随便了。","mne":"arbitr判断 + ary……的 → 做出自己的判断 → arbitrary武断的"},{"word":"arbitration","ipa":"/ˌɑːrbɪˈtreɪʃn/","pos":"n.","def":"仲裁；仲裁，公断","sen":"The two companies agreed to resolve their dispute through arbitration.","trans":"两家公司同意通过仲裁解决他们的争端。","mne":"arbitr判断+ation行为 →arbitration仲裁"},{"word":"architect","ipa":"/ˈɑːrkɪtekt/","pos":"n.","def":"建筑师","sen":"The architect is looking at a model of the building he designed.","trans":"这位建筑师正在看他设计的建筑模型。","mne":"archi表示统治，主要的 + tect表示建筑 → 统治〔建筑〕的人 → architect建筑师"},{"word":"architecture","ipa":"/ˈɑːrkɪtektʃər/","pos":"n.","def":"建筑学；建筑风格，建筑设计","sen":"Our professor is explaining the theory of architecture in class.","trans":"我们的教授正在课堂上讲解建筑学理论。","mne":"archi主要 + tect建造 +ure名词后缀 → 主要做造房 → architecture建筑学 "},{"word":"area","ipa":"/ˈeriə/","pos":"n.","def":"面积；区域，地区","sen":"The area of the office is about 40 square meters.","trans":"办公室的面积大约是40平方米。","mne":""},{"word":"argue","ipa":"/ˈɑːrɡjuː/","pos":"v.","def":"争论；主张，认为；表明（原因等）","sen":"The workers are arguing about a problem.","trans":"员工们在争论一个问题。","mne":""},{"word":"argument","ipa":"/ˈɑːrɡjumənt/","pos":"n.","def":"争吵，争论，争辩；论据，论点","sen":"The girl had an argument with her boyfriend about the video game.","trans":"女孩和她的男朋友因为电子游戏争吵。","mne":"argu(e)争论 + ment名词后缀 → argument争论，辩论"},{"word":"arise","ipa":"/əˈraɪz/","pos":"v.","def":"起床，起身；由……引起，发生","sen":"He arises at 7 a.m. every morning.","trans":"他每天早上7点起床。","mne":"a加强意义 + rise升起 → arise起来，升起"},{"word":"arm","ipa":"/ɑːrm/","pos":"n.","def":"手臂；上肢；  v.武装，装备","sen":"She is showing how strong her arm is.","trans":"她正在展示她那强壮的手臂。","mne":""},{"word":"army","ipa":"/ˈɑːrmi/","pos":"n.","def":"陆军，军队，部队","sen":"The army is standing on the grass.","trans":"这支军队正站在草地上。","mne":"arm武器，装甲 + y表名词 → 有武器、装甲的人 → army陆军，军队 "},{"word":"around","ipa":"/əˈraʊnd/","pos":"adv.","def":"周围，环绕；大约，四处；  prep.环绕，围绕，在……周围","sen":"I stand up and look around.","trans":"我站起身来环顾四周。","mne":"a古英语前缀 + round圆圈 → around大约，四处"},{"word":"arouse","ipa":"/əˈraʊz/","pos":"v.","def":"唤起","sen":"Being aroused from sleep is the beginning of his day.","trans":"从梦中醒来是他一天的开始。","mne":"a在...的 + rouse唤醒 → arouse唤起"},{"word":"arrange","ipa":"/əˈreɪndʒ/","pos":"v.","def":"筹备，安排；改编（乐曲）","sen":"They are arranging the coming event.","trans":"他们正在筹备即将举行的活动。","mne":"ar使 + range排列 → 使排列好 → arrange安排"},{"word":"arrangement","ipa":"/əˈreɪndʒmənt/","pos":"n.","def":"安排；协议","sen":"Here are my important arrangements for today.","trans":"这些是我今天的重要安排。","mne":"arrange安排 + ment名词后缀 → arrangement排列，布置"},{"word":"arrest","ipa":"/əˈrest/","pos":"n.","def":"逮捕，拘留；  v.逮捕，拘留；吸引","sen":"He was arrested for breaking the law.","trans":"他因为犯法被抓起来了。","mne":"ar一再 + rest休息 → 不让动 → arrest逮捕，阻止"},{"word":"arrival","ipa":"/əˈraɪvl/","pos":"n.","def":"到来，到达","sen":"Passengers on the platform are waiting for the train's arrival.","trans":"站台上的乘客正在等候火车到站。","mne":"arriv(e)到达 + al名词后缀 → arrival到达"},{"word":"arrive","ipa":"/əˈraɪv/","pos":"v.","def":"到达","sen":"She arrived at the airport on time.","trans":"她准时抵达了机场。","mne":"ar一再 + rive河 → 到达河边 → 达到目标 → arrive到达"},{"word":"arrow","ipa":"/ˈæroʊ/","pos":"n.","def":"箭；（指示方向的）箭头","sen":"An arrow has a sharp point at one end and feathers on the other.","trans":"箭的一端是尖的，另一端是羽毛。","mne":""},{"word":"art","ipa":"/ɑːrt/","pos":"n.","def":"艺术","sen":"Painting and dance are forms of art.","trans":"绘画和舞蹈都是艺术的表现形式。","mne":""},{"word":"article","ipa":"/ˈɑːrtɪkl/ ","pos":"n.","def":"（报刊上的）文章，论文，报道；物品；条款；冠词","sen":"She is reading the article in the newspaper.","trans":"她正在阅读报纸上的文章。","mne":"art技巧，艺术 + icle东西 → 用技巧做出的东西 → article物品，文章"},{"word":"artificial","ipa":"/ˌɑːrtɪˈfɪʃl/","pos":"adj.","def":"人造的，仿造的；人工的；假的","sen":"Even with an artificial leg, he can still beat you in a race.","trans":"尽管有一条假肢，他依然可以跑赢你。","mne":"artific技巧 + ial形容词后缀 → 用技巧做出的 → artificial人工的；矫揉造作的"},{"word":"artist","ipa":"/ˈɑːrtɪst/","pos":"n.","def":"艺术家，画家","sen":"The artist is spraying colors on the wall.","trans":"这个艺术家在朝墙上喷涂颜料。","mne":"art艺术 + ist表示从事某种职业的人 → artist艺术家，画家"},{"word":"as","ipa":"/æz/","pos":"adv.","def":"和……一样；  prep.作为，当做；像，如同","sen":"Our actions look as consistent as each other's!","trans":"我们的动作看起来很一致。","mne":""},{"word":"ash","ipa":"/æʃ/","pos":"n.","def":"灰，灰烬，废墟","sen":"These backpackers left nothing here but a pile of ashes.","trans":"这些背包客只在这儿留下一堆灰烬。","mne":""},{"word":"ashamed","ipa":"/əˈʃeɪmd/ ","pos":"adj.","def":"羞耻的；感到惭愧的","sen":"The cat felt ashamed that it was caught when eating the goldfish.","trans":"这只猫很羞愧，因为它偷吃金鱼的时候被人发现了。","mne":"a加强 + sham(e)羞耻 + ed形容词后缀 → ashamed感到羞愧的"},{"word":"aside","ipa":"/əˈsaɪd/","pos":"adv.","def":"在旁边","sen":"Cars all step aside to let the ambulance pass.","trans":"汽车们纷纷退让到一边，让救护车通过。","mne":"a在…的 + side旁边 → 在旁边 → aside在边上"},{"word":"ask","ipa":"/æsk/","pos":"v.","def":"询问；要求","sen":"The man is asking a stranger for directions.","trans":"这个男人正在向陌生人问路。","mne":""},{"word":"asleep","ipa":"/əˈsliːp/","pos":"adj.","def":"睡着的，睡熟的","sen":"This boy fell asleep in his stepfather's arms. How lovely!","trans":"曼尼在杰的怀里睡着了，多有爱啊！","mne":"a表强调 + sleep睡觉 → asleep睡着的"},{"word":"aspect","ipa":"/ˈæspekt/","pos":"n.","def":"（问题等的）方面；外表，面貌；方位，方向","sen":"The students are recording every aspect of the plant's growth.","trans":"学生们正在记录这株植物生长的各个方面。","mne":"a来，临近 + spect看 → 看的东西 → aspect外表，容貌，形势，方面"},{"word":"aspire","ipa":"/əˈspaɪər/","pos":"v.","def":"渴望，有志于","sen":"She aspires to be a firefighter and serve the people.","trans":"她立志成为一名消防员，为人民服务。","mne":"a加强 + spir呼吸 + e强调 → 看到渴望的东西加强呼吸 → aspire渴望"},{"word":"assemble","ipa":"/əˈsembəl/","pos":"v.","def":"集合；组装，装配（机器等）","sen":"The family assembled in the living room for a family photo.","trans":"家庭成员为了拍这张照片在客厅集合。","mne":"as不断 + semble相类似，一样 → 不断使东西相同 → 组装东西 → assemble集合；装配"},{"word":"assert","ipa":"/əˈsɜːrt/","pos":"v.","def":"肯定地说；断言","sen":"They both assert their opposing opinions, and I have no idea whom I should believe.","trans":"他们公说公有理，婆说婆有理，而我完全不知道该信谁。","mne":"as加强 + sert加入，插入 → 强行插入观点 → assert断言"},{"word":"assertion","ipa":"/əˈsɜːrʃn/","pos":"n.","def":"断言；主张，坚持","sen":"He made an assertion that aliens exist.","trans":"他断言外星人存在。","mne":"as加强 + sert加入，插入 + ion名词后缀 → 加入讨论 → assertion声明；主张"},{"word":"assertive","ipa":"/əˈsɜːrtɪv/","pos":"adj.","def":"坚定自信的","sen":"In the negotiation, it's crucial to be assertive when stating our bottom line.","trans":"在谈判中，明确表述我们的底线时展现出坚定自信至关重要。","mne":"as加强 + sert加入，插入 + ive...的 → assertive断言的；确定的"},{"word":"assess","ipa":"/əˈses/","pos":"v.","def":"评估，评定","sen":"The doctor needs to assess the patient’s symptoms before making a diagnosis.","trans":"医生需要在做出诊断前评估病人的症状。","mne":"ad=as有关 + sess坐 -> 文职人员都是坐着的 -> 评估"},{"word":"assessment","ipa":"/əˈsesmənt/","pos":"n.","def":"评估，估价；评定；估计","sen":"\"My assessment is that you are in good health,\" said the doctor.","trans":"“根据我的评估，你的身体很健康。”医生说。","mne":"assess评定 + ment表示行为、行为的过程或结果 → assessment（为征税对财产所作的）估价"},{"word":"asset","ipa":"/ˈæset/","pos":"n.","def":"财产，资产；有价值的人或物","sen":"My house is an important part of my assets.","trans":"我的房子是我的财产中重要的一部分。","mne":"as朝，向，去 + set足够 → asset财产"},{"word":"assign","ipa":"/əˈsaɪn/","pos":"v.","def":"分配；指派","sen":"Our teacher assigned us lots of homework.","trans":"我们的老师给我们布置了许多家庭作业。","mne":"as一再 + sign记号 → 不断给人标记号 → assign指定；分配"},{"word":"assignment","ipa":"/əˈsaɪnmənt/","pos":"n.","def":"（课外）作业；任务；分配，委派","sen":"My teacher gave me a lot of assignments for the weekend.","trans":"老师给我布置了很多周末的家庭作业。","mne":"assign分配 + ment名词后缀 → assignment（课外）作业"},{"word":"assimilation","ipa":"/əˌsɪməˈleɪʃn/","pos":"n.","def":"同化，同化作用；消化","sen":"Assimilation is the process when a group comes to resemble those of another.","trans":"同化是一个群体变得与另一个群体相似的过程。","mne":""},{"word":"assist","ipa":"/əˈsɪst/","pos":"v.","def":"帮助；协助","sen":"They assisted each other to the top of the mountain.","trans":"他们互相帮助，登上了山顶。","mne":"as一再 ＋ sist站 → 站过来 → assist帮助"},{"word":"assistance","ipa":"/əˈsɪstəns/","pos":"n.","def":"帮助；援助","sen":"I climbed up the hill with the assistance of my friend.","trans":"在我朋友的帮助下，我爬上了山。","mne":"assist帮助 + ance名词后缀 → assistance援助"},{"word":"assistant","ipa":"/əˈsɪstənt/","pos":"n.","def":"助理，助手；  adj.助理的，辅助的","sen":"The businessman has an assistant to help him with his work every day.","trans":"这个商人有一名每天协助他工作的助理。","mne":"assist援助 + ant名词后缀 → 帮助之人 → assistant助手，助理"},{"word":"associate","ipa":" /əˈsoʊsieɪt/; /əˈsoʊʃieɪt/ ","pos":"v.","def":"与某人交往；联系；  n.同事，合作人；  adj.副的","sen":"Nowadays, people like to associate with others online.","trans":"如今，人们喜欢在网上与别人交往。","mne":"as去 + soci联合 + ate表动词  → 结成团队 → associate联合"},{"word":"association","ipa":"/əˌsəʊsiˈeɪʃn/","pos":"n.","def":"协会，联盟；联想；联系，关联","sen":"The association members wanted to attract new people to join them.","trans":"社团成员们想吸引更多的人加入他们。","mne":"as加强 + soci社会 + at(e)使… + ion表名词 → associate结成社会=联合 + ion表名词 → association联合"},{"word":"assume","ipa":"/əˈsuːm/","pos":"v.","def":"猜想；认为；接受；  v.采取","sen":"I assumed that the red team would win.","trans":"我猜红队会赢。","mne":"as加强 + sume拿取 → 主动拿起 → assume承担"},{"word":"assure","ipa":"/əˈʃʊr/","pos":"v.","def":"向……保证，使确信","sen":"I can assure you that the dog will be well cared for.","trans":"我可以向你保证，狗会得到很好的照顾。","mne":"as一再 + sure确定 → 一再确定 → assure肯定，确信"},{"word":"astonish","ipa":"/əˈstɑːnɪʃ/","pos":"v.","def":"使吃惊","sen":"The opponent's harsh words astonished him.","trans":"对手的狠话使他震惊。","mne":"as=ex表强调 + ton打雷 + ish表动词 → astonish使吃惊"},{"word":"astronaut","ipa":"/ˈæstrənɔːt/ ","pos":"n.","def":"宇航员，太空人","sen":"I would love to be an astronaut and go to space.","trans":"我想成为一名宇航员进入太空。","mne":"astro星际 + naut航行员 → 宇航员"},{"word":"at","ipa":"/æt/","pos":"prep.","def":"在（地点），于，向，对准，在……方面","sen":"We are at school.","trans":"我们在学校。","mne":""},{"word":"athlete","ipa":"/ˈæθliːt/","pos":"n.","def":"运动员，田径运动员","sen":"He was a great athlete who ran really fast.","trans":"他以前是一名优秀的运动员，跑得非常快。","mne":"athl比赛 + ete → 参加体育比赛的专业人士 → athlete运动员"},{"word":"atmosphere","ipa":"/ˈætməsfɪr/ ","pos":"n.","def":"大气层；空气；氛围，气氛","sen":"The Earth's atmosphere absorbs part of the sun's energy.","trans":"地球大气层吸收太阳的部分能量。","mne":"atmo蒸汽 + sphere范围 → 大气层；空；气氛"},{"word":"attach","ipa":"/əˈtætʃ/","pos":"v.","def":"贴上，使依附；把……固定，把……附（在……上）；缚；认为...有重要性；附加；赋予","sen":"The card player has several pieces of paper to attach to his face.","trans":"这个打牌的人有好多张纸条要贴在他的脸上。","mne":"at=ad 去 + tach 固定，栓→ 去固定 → attach附上，使附属，使依恋"},{"word":"attachment","ipa":"/əˈtætʃmənt/","pos":"n.","def":"（通过邮件发送的）附件；依恋","sen":"I have sent my resume as an attachment.","trans":"我以附件的形式发送了简历。","mne":"attach附加 + ment表名词 → 附属物"},{"word":"attack","ipa":"/əˈtæk/","pos":"v.","def":"攻击，进攻，袭击；毁坏；  n.疾病发作","sen":"The soldiers attacked the enemy during the war.","trans":"在战争中，战士们对敌人发起了攻击。","mne":""},{"word":"attain","ipa":"/əˈteɪn/","pos":"v.","def":"获得，得到","sen":"I finally attained my driving license!","trans":"我终于拿到了驾照！","mne":"at一再 + tain拿住 → attain获得；达到"},{"word":"attainable","ipa":"/əˈteɪnəbəl/","pos":"adj.","def":"【财】可实现的，可获得的","sen":"The attainable profits can be maximized by reducing operational costs.","trans":"通过降低运营成本，可以实现最大化的利润。","mne":""},{"word":"attainment","ipa":"/əˈteɪnmənt/","pos":"n.","def":"达到","sen":"Landing on the moon is now very possible attainment.","trans":"现在，人们有可能登上月球了。","mne":"attain获得+ment表名词→获得的成就 → 成就，造诣"},{"word":"attempt","ipa":"/əˈtempt/","pos":"v.","def":"试图，尝试；  n.试图，尝试；企图","sen":"The cat attempts to catch that fish.","trans":"那只猫咪试图抓到那条鱼。","mne":"at表强调 + tempt尝试 → 一再尝试 → attempt尝试，企图"},{"word":"attend","ipa":"/əˈtend/","pos":"v.","def":"护理，照顾；处理；参加；注意","sen":"A nurse is attending to the newborn baby.","trans":"一位护士正在照顾新生的宝宝。","mne":"at=ad，to + tend延伸 → 把思维延伸到 → 关注，引申为期待某人到达，后来又引申为到达 → attend出席"},{"word":"attendance","ipa":"/əˈtendəns/","pos":"n.","def":"出席","sen":"The register kept a record of people's attendances at the conference.","trans":"登记簿记录了人们出席会议的情况。","mne":""},{"word":"attendant","ipa":"/əˈtendənt/","pos":"n.","def":"服务员，侍者，随从；  adj.伴随的，随之而产生的","sen":"The gas attendant is filling up the car for the customer.","trans":"这个加油站服务员正在为顾客的汽车加油。","mne":"attend照料 + ant名词后缀  → 照料的人  → 服务员，随从"},{"word":"attention","ipa":"/əˈtenʃn/","pos":"n.","def":"专心，注意力","sen":"Only one student in the class was paying attention to what the teacher was saying.","trans":"班上只有一个学生在专心听老师讲课。","mne":"attent关注 + ion名词后缀 → attention注意力"},{"word":"attitude","ipa":"/ˈætɪtuːd/","pos":"n.","def":"态度；姿势；看法，态度","sen":"A positive attitude is what you need to solve problems.","trans":"你需要以积极的态度来解决问题。","mne":"att=apr倾向 + itude后缀，构成抽象名词 → attitude态度"},{"word":"attract","ipa":"/əˈtrækt/","pos":"v.","def":"吸引","sen":"This vibrant flower attracts a butterfly.","trans":"这朵鲜艳的花吸引了一只蝴蝶。","mne":"at一再 + tract拉 → 拉过来 → attract吸引"},{"word":"attraction","ipa":"/əˈtrækʃn/","pos":"n.","def":"吸引力，魅力","sen":"The park's attraction is enhanced by its beautiful gardens.","trans":"公园因其美丽的花园而更具吸引力。","mne":"attract吸引 + ion表名词 → attraction吸引力"},{"word":"attractive","ipa":"/əˈtræktɪv/","pos":"adj.","def":"（事物）有吸引力的，诱人的","sen":"With such a low price, the hotel room is really attractive.","trans":"这个旅馆房间价格如此低廉，真的很吸引人。","mne":"at加强 + tract拉 + ive...的 → attract拉过来=吸引 + ive...的 → attractive引人注目的"},{"word":"attribute","ipa":"/əˈtrɪbjuːt/ /ˈætrɪbjuːt/","pos":"v.","def":"把……归因于，把……归咎于（读作/əˈtrɪbjut/）；  n.属性；特征；定语","sen":"Success can be attributed to hard work and a bit of luck.","trans":"成功都可以归因于努力的奋斗和些许的运气。","mne":"at+tribut给予+e→attribute把...归因于..."},{"word":"auction","ipa":"/ˈɔːkʃn/","pos":"n.","def":"拍卖；  v.拍卖","sen":"I hold an auction to sell my house because I am broke.","trans":"我举办了一个拍卖会来卖掉我的房子，因为我破产了。","mne":"auct=aug抬高，增加 + ion表名词 → auction拍卖"},{"word":"audience","ipa":"/ˈɔːdiəns/ ","pos":"n.","def":"观众，听众","sen":"The audience in the conference hall stayed quiet during his speech.","trans":"他讲话时，会议厅里的听众都很安静。","mne":"audi听 + ence表名词 → 听众，观众，读者"},{"word":"august","ipa":"/ˈɔːɡəst/","pos":"n.","def":"八月","sen":"Autumn usually begins in August.","trans":"秋天一般从八月开始。","mne":""},{"word":"aunt","ipa":"/ænt/","pos":"n.","def":"阿姨","sen":"This aunt enjoys tea very much.","trans":"这位阿姨很喜欢喝茶。","mne":""},{"word":"authentic","ipa":"/ɔːˈθentɪk/","pos":"adj.","def":"真正的；真实的；真品的，真迹的；可靠的","sen":"This diamond isn't fake-I'm sure it's authentic.","trans":"这颗钻石不是假的——我敢保证它是真的！","mne":"auth=author作者 + entic形容词后缀 → authentic真的，真正的"},{"word":"author","ipa":"/ˈɔːθər/","pos":"n.","def":"作者，作家","sen":"Lu Xun is the author of this book.","trans":"鲁迅是这本书的作者。","mne":"auth增加，创造 + or表人 → 创作的人 → author作者，作家"},{"word":"authorisation","ipa":"/ˌɔːθərəˈzeɪʃən/","pos":"n.","def":"【财】授权；核准","sen":"Those who decide to pull out because of US sanctions will need to be granted authorisation from the European commission, without which they face the risk of being sued by EU member states.","trans":"那些因美国制裁而决定撤出的人需要获得欧洲委员会的授权，否则他们将面临被欧盟成员国起诉的风险。","mne":""},{"word":"authorise","ipa":"/'ɒθəraɪz/","pos":"v.","def":"授权；委任；  v.批准","sen":"He is authorised to log in the account.","trans":"他被授权登录这个账户。","mne":""},{"word":"authority","ipa":"/əˈθɔːrəti/","pos":"n.","def":"权威，威信；权威人士；权力，职权；当局，官方","sen":"The authority declared that catmint would be banned completely in three months.","trans":"当局宣称猫薄荷将在三个月后被全面禁止。","mne":"auth使增加；创造 + or施动者后缀 +ity名词后缀 → authority权力；权威"},{"word":"authorization","ipa":"/ˌɔːθərəˈzeɪʃn/","pos":"n.","def":"授权(书)；批准","sen":"You need authorization to enter this area.","trans":"你需要得到授权才能进入这个区域。","mne":""},{"word":"authorize","ipa":"/ˈɔːθəraɪz/","pos":"v.","def":"批准；授权","sen":"The emperor authorized this document with a stamp.","trans":"皇帝加印批准了这个文件。","mne":"auth授权 + or人 + ize动词后缀 → authorize授权，批准"},{"word":"automatic","ipa":"/ˌɔːtəˈmætɪk/","pos":"adj.","def":"自动的","sen":"The automatic production line improves the working efficiency greatly.","trans":"自动化生产线大大地提高了工作效率。","mne":"autom=auto，autom自动 + atic有…性质的 → automatic自动的，机械的"},{"word":"automobile","ipa":"/ˈɑːtəmoʊbiːl/","pos":"n.","def":"汽车，机动车","sen":"This green automobile is for sale. Let's take a look.","trans":"这辆绿色的汽车正在出售，我们去看看吧。","mne":"auto自己 + mobile移动的 → automobile汽车"},{"word":"autonomy","ipa":"/ɔːˈtɑːnəmi/","pos":"n.","def":"人身自由；自治；自治权；自主权","sen":"Parents give the child autonomy to make her favorite juice.","trans":"父母给了这个孩子自主权去做她喜欢的果汁。","mne":"auto自己 + nomy系统，统治 → 自己统治 → autonomy自治"},{"word":"autumn","ipa":"/ˈɔːtəm/ ","pos":"n.","def":"秋天","sen":"In autumn, leaves turn orange and yellow before falling to the ground.","trans":"在秋天，树叶会变黄然后落地。","mne":""},{"word":"availability","ipa":"/əˌveɪləˈbɪləti/","pos":"n.","def":"可得性，可用性","sen":"Even in the desert my wireless service's availability is 100%!","trans":"即使在沙漠里，我的无线服务都是百分之百可以使用的！","mne":"avail效用 + ability可……性 → 可效性"},{"word":"available","ipa":"/əˈveɪləbl/","pos":"adj.","def":"可获得的，可用的；有空的","sen":"The receptionist told me that there was only one room available.","trans":"前台接待员告诉我只有一个房间可以入住。","mne":"avail利用 + able能……的 → 能够利用的；可得到的"},{"word":"avenue","ipa":"/ˈævənuː/","pos":"n.","def":"林荫道，道路；大街；方式，手段","sen":"The avenue is lined with lush green trees.","trans":"道路两旁，绿树成荫。","mne":"a向 + ven来，走 + ue → 让人可以走来走去 → avenue大路，道路"},{"word":"average","ipa":"/ˈævərɪdʒ/","pos":"n.","def":"平均数；  v.平均为；  adj.平均的；平庸的，普通的","sen":"His height equals the average of his parents' heights.","trans":"他的身高等于他父母身高的平均数。","mne":""},{"word":"aviation","ipa":"/ˌeɪviˈeɪʃn/","pos":"n.","def":"航空，航空学；飞行","sen":"Aviation is one of my biggest interests—I love airplanes.","trans":"航空是我最大的爱好之一 ——我喜欢飞机。","mne":"avi鸟 + ation表示行为、状态 → 像鸟一样在空中 → aviation航空"},{"word":"avoid","ipa":"/əˈvɔɪd/","pos":"v.","def":"避免，防止","sen":"The driver avoided hitting the dogs on the road.","trans":"司机避免了撞到路上的狗。","mne":"a=out处于 ＋ void空 → 空出来 → avoid避开，避免"},{"word":"await","ipa":"/əˈweɪt/","pos":"v.","def":"等候","sen":"People are awaiting the bus.","trans":"人们正在等车。","mne":"a使 + wait等待 → await等候"},{"word":"awake","ipa":"/əˈweɪk/","pos":"adj.","def":"醒着的；  v.（使）醒来；唤起，被唤起","sen":"It's already 3:22 a.m., but she is still awake.","trans":"现在已经是凌晨3点22分了，但她还醒着。","mne":"a加强意义 + wake醒着 → awake唤醒，使醒"},{"word":"award","ipa":"/əˈwɔːrd/","pos":"n.","def":"奖品；奖学金；  v.授予；奖励","sen":"The actress got an award for her movie.","trans":"这个女演员凭其电影赢得了这个奖项。","mne":"a=ex向外 + ward看 → award奖品"},{"word":"aware","ipa":"/əˈwer/","pos":"adj.","def":"意识到的；知道的","sen":"The teacher is aware that the student is cheating in the exam.","trans":"老师察觉到那个学生在考试中作弊。","mne":"a使 + ware注视 → aware意识到的"},{"word":"awareness","ipa":"/əˈwernəs/","pos":"n.","def":"意识；察觉，觉悟 ","sen":"He tries to raise people's awareness of the importance of recycling.","trans":"他试图增强人们对回收利用的重要性的意识。","mne":"aware知道 ＋ ness表名词 → awareness意识，知觉"},{"word":"away","ipa":"/əˈweɪ/","pos":"adv.","def":"离开，远离；在远处","sen":"The blue balloon flies away.","trans":"蓝色气球飞走了。","mne":"a来自，朝向 + way道路 → 从某个方向来 → away离开，远离"},{"word":"awful","ipa":"/ˈɔːfl/","pos":"adj.","def":"糟糕的，讨厌的；极大的，极多的","sen":"The penguin's English is awful.","trans":"这只企鹅的英语水平很糟糕。","mne":"aw=awe敬畏 + ful形容词后缀 → 使人畏惧的 → awful糟糕的，可怕的"},{"word":"awkward","ipa":"/ˈɔːkwərd/","pos":"adj.","def":"尴尬的；笨拙的","sen":"It was awkward when he farted in the library.","trans":"他在图书馆放了个屁，真是尴尬。","mne":"awk错误方向 + ward朝向 → 转错方向 → awkward尴尬的"},{"word":"baby","ipa":"/ˈbeɪbi/","pos":"n.","def":"婴儿","sen":"What a cute hat for a baby!","trans":"好可爱的婴儿帽啊！","mne":""},{"word":"bachelor","ipa":"/ˈbætʃələr/","pos":"n.","def":"学士；单身汉","sen":"After four years of hard work, I finally got my bachelor's degree!","trans":"经过四年的努力学习，我终于拿到了我的学士学位！","mne":""},{"word":"back","ipa":"/bæk/","pos":"n.","def":"背部，背影；  adv.回原处；向后；  adj.后面的；  v.支持；资助","sen":"His back hurt so much that he couldn't stand up straight.","trans":"他的背疼得他站不直。","mne":""},{"word":"background","ipa":"/ˈbækɡraʊnd/","pos":"n.","def":"出身，经历；（事件的）背景","sen":"They come from different cultural backgrounds.\t","trans":"他们来自不同的文化背景。","mne":"back背后 + ground场地 → background背景，后台"},{"word":"backward","ipa":"/ˈbækwərd/","pos":"adv.","def":"向后地；  adj.落后的；向后的，倒行的","sen":"He leaned backward to stretch his back after sitting for hours.","trans":"坐了几个小时后，他向后仰伸展了下背部。","mne":"back后边 + ward向 → backward 向后的"},{"word":"backwards","ipa":"/ˈbækwərdz/","pos":"adv.","def":"向后，倒着，往回","sen":"When we both bend backwards, we almost make a complete circle.","trans":"当我们都向后仰的时候，我们几乎组成了一个完整的圆。","mne":"back后 + wards表副词，向… → backwards向后"},{"word":"bacteria","ipa":"/bækˈtɪriə/","pos":"n.","def":"细菌（bacterium的复数）","sen":"You can't see bacteria without a microscope.","trans":"没有显微镜你看不到细菌。","mne":"bact细菌的 + er表示物 + ia总称 → bacteria细菌（都是球状或者棍状的）"},{"word":"bad","ipa":"/bæd/","pos":"adj.","def":"糟糕的；坏的，恶的，错的；  adv.非常，不好地","sen":"The bad weather has seriously affected people's daily lives.","trans":"糟糕的天气严重影响了人们的日常生活。","mne":""},{"word":"badly","ipa":"/ˈbædli/","pos":"adv.","def":"严重地；非常","sen":"The boy was badly injured.","trans":"男孩受了很严重的伤。","mne":"bad坏的 + ly副词后缀 → badly恶劣地"},{"word":"bag","ipa":"/bæɡ/","pos":"n.","def":"袋，包","sen":"This white bag is so big! You can put so much in it.","trans":"这个白色的包真大！你可以放很多东西进去。","mne":""},{"word":"baggage","ipa":"/ˈbæɡɪdʒ/","pos":"n.","def":"行李","sen":"The young man is waiting for his baggage.","trans":"这个年轻人正在等他的行李。","mne":"bagg=bag包 + age表示集合名词、总称 → baggage行李"},{"word":"bake","ipa":"/beɪk/","pos":"v.","def":"烤，烘焙","sen":"I've put some sesame crackers in the oven to bake.","trans":"我已经把几片芝麻脆饼放进烤箱里烤了。","mne":""},{"word":"balance","ipa":"/ˈbæləns/","pos":"n.","def":"平衡，平衡能力；天平；余额；  v.平衡；抵消","sen":"Look! He can keep balance on that rope.","trans":"看！他能在那根绳索上保持平衡。","mne":"ba=bi两个的 + lance天平刻度，盘子 → 天平的两端保持一致 → balance平衡"},{"word":"bald","ipa":"/bɔːld/","pos":"adj.","def":"秃头的；不加赘述的","sen":"Wait, why am I combing my hair?-I'm bald, I don't have any hair.","trans":"等等，我为什么要梳头？我是秃头，我根本没有头发。","mne":""},{"word":"ball","ipa":"/bɔːl/","pos":"n.","def":"球；舞会","sen":"Kick the ball into the net!","trans":"把球踢进网！","mne":""},{"word":"balloon","ipa":"/bəˈluːn/","pos":"n.","def":"气球；热气球；  v.猛增","sen":"We bought many colorful balloons for the party.","trans":"我们为聚会买了许多五颜六色的气球。","mne":"ball球 + oon表名词 → balloon气球"},{"word":"ban","ipa":"/bæn/","pos":"v.","def":"明令禁止；  n.禁止，禁令","sen":"Smoking is banned in public places.","trans":"公共场所禁止吸烟。","mne":""},{"word":"banana","ipa":"/bəˈnænə/","pos":"n.","def":"香蕉","sen":"Bananas are my favorite fruit.","trans":"香蕉是我最喜欢的水果。","mne":""},{"word":"band","ipa":"/bænd/","pos":"n.","def":"乐队；帮伙；一帮，一群","sen":"The band's live performance fascinated their fans.","trans":"这个乐队的现场表演让他们的粉丝为之疯狂。","mne":""},{"word":"bang","ipa":"/bæŋ/","pos":"n.","def":"重击；巨响","sen":"He gave the door a loud bang.","trans":"他给了门一声响亮的重击。","mne":""},{"word":"bank","ipa":"/bæŋk/","pos":"n.","def":"银行；岸；  v.把钱存入银行","sen":"Is the bank a safe place to keep my money?","trans":"银行是保管钱的安全之所吗？","mne":""},{"word":"bankrupt","ipa":"/ˈbæŋkrʌpt/","pos":"adj.","def":"破产的；  n.破产者；  v.使破产","sen":"With no more money, I'm completely bankrupt.","trans":"没有钱，我彻底破产了。","mne":"bank柜台 + rupt断裂 → 柜台断了 → 破产了 → bankrupt破产的"},{"word":"bankruptcy","ipa":"/ˈbæŋkrəptsi/","pos":"n.","def":"破产","sen":"A number of different debts drove the company into bankruptcy.","trans":"许多不同的债务迫使这家公司破产了。","mne":"bank柜台 + rupt断裂 + cy名词后缀 → 破产"},{"word":"banquet","ipa":"/ˈbæŋkwɪt/","pos":"n.","def":"（正式的）宴会；盛宴","sen":"The banquet was very grand.","trans":"这场宴会非常隆重。","mne":""},{"word":"bar","ipa":"/bɑːr/","pos":"n.","def":"(金属)棒；闩；酒吧","sen":"This old man used a huge bar as a weapon.","trans":"三代火影用巨大金箍棒作为武器。","mne":""},{"word":"barbecue","ipa":"/ˈbɑːrbɪkjuː/","pos":"n.","def":"烧烤；户外烧烤；烤肉；烧烤架；  v.烧烤","sen":"They are having a barbecue together.","trans":"他们正在一起烧烤野餐。","mne":""},{"word":"barber","ipa":"/ˈbɑːrbər/","pos":"n.","def":"（男）理发师","sen":"I asked my barber to give me a new style this time.","trans":"这一次我让我的理发师给我理一个新发型。","mne":"barb胡子 + er人 → 修理胡子的人 → barber理发师"},{"word":"bare","ipa":"/ber/ ","pos":"adj.","def":"赤裸的；光秃秃的；贫瘠的；勉强够的；  v.使裸露，暴露","sen":"He is running around in bare feet.","trans":"他正赤着脚到处跑。","mne":""},{"word":"barely","ipa":"/ˈberli/","pos":"adv.","def":"仅仅；几乎不","sen":"He barely caught the train.","trans":"他差一点就赶不上火车了。","mne":"bare + ly副词后缀 → barely"},{"word":"bargain","ipa":"/ˈbɑːrɡən/","pos":"v.","def":"讨价还价；经讨价还价成交；  n.交易；便宜货；契约","sen":"The lady is trying to bargain with the seller.","trans":"这位女士试图和卖方砍价。","mne":""},{"word":"barrier","ipa":"/ˈbæriər/","pos":"n.","def":"障碍；屏障，障碍物；隔阂","sen":"There is a barrier on the road so we can't go this way.","trans":"路上有障碍物，所以我们不能走这条路。","mne":"barr棒，阻拦 + ier名词后缀，表示物 → barrier栅栏"},{"word":"base","ipa":"/beɪs/","pos":"n.","def":"根基；基础；底部；  v.以……作基础","sen":"A firm base is very important for building a house.","trans":"稳固的根基对于建造房屋十分重要。","mne":""},{"word":"basic","ipa":"/ˈbeɪsɪk/","pos":"adj.","def":"基础的，最简单的","sen":"The brand's bags came in both basic and limited editions.","trans":"这一品牌的包既有基础款也有限量款。","mne":"bas=basis基础 + ic形容词，...的 → basic基本的"},{"word":"basically","ipa":"/ˈbeɪsɪkli/","pos":"adv.","def":"基本上","sen":"Basically, all the students are depressed during a hard English examination.","trans":"在这场困难的英语考试中，基本上所有学生都很郁闷。","mne":"basic基础的 + ally……地 → basically基本上"},{"word":"basin","ipa":"/ˈbeɪsn/","pos":"n.","def":"水池；盆地；流域","sen":"The basin in our bathroom is very clean.","trans":"我们浴室的水池很干净。","mne":""},{"word":"basis","ipa":"/ˈbeɪsɪs/","pos":"n.","def":"基础","sen":"The English alphabet is the basis of written English.","trans":"英文字母表是书面英语的基础。","mne":""},{"word":"basket","ipa":"/ˈbæskɪt/","pos":"n.","def":"车筐","sen":"The shared bike has a practical basket for carrying belongings.","trans":"共享单车配备了实用的车筐，方便携带物品。","mne":""},{"word":"basketball","ipa":"/ˈbæskɪtbɔːl/","pos":"n.","def":"篮球","sen":"Girls love to play basketball too, and they can play it very well.","trans":"女生们也喜欢打篮球，而且她们打得不错。","mne":"basket篮子 + ball球 → basketball篮球"},{"word":"bat","ipa":"/bæt/","pos":"n.","def":"蝙蝠；球棒，球拍；  v.用球板击球","sen":"Bats hang themselves upside down when they sleep.","trans":"蝙蝠睡觉的时候会将身体倒挂起来。","mne":""},{"word":"bath","ipa":"/bæθ/","pos":"n.","def":"洗澡；浴室；  v.给……洗澡","sen":"I took a long bath to relax myself.","trans":"我泡了很长时间的澡来放松自己。","mne":""},{"word":"bathe","ipa":"/beɪð/","pos":"v.","def":"洗澡；用水清洗；给……洗澡","sen":"The dog, cat, and duck love to bathe together.","trans":"狗、猫和鸭子喜欢在一起洗澡。","mne":""},{"word":"bathroom","ipa":"/ˈbæθruːm/","pos":"n.","def":"浴室，盥洗室","sen":"This bathroom contains a washbasin, a toilet and a shower.","trans":"这个浴室有一个洗脸盆，一个马桶和一个淋浴器。","mne":"bath洗澡 + room房间 → bathroom 浴室"},{"word":"battery","ipa":"/ˈbætəri/","pos":"n.","def":"电池（组）；一组，许多，众多","sen":"My phone is out of battery. It'll shut off soon.","trans":"我的手机没电了，很快就会关机。","mne":""},{"word":"battle","ipa":"/ˈbætl/","pos":"n.","def":"战役，战斗；斗争","sen":"The knight killed many enemies bravely in the battle.","trans":"骑士在战役中英勇地杀了很多敌人。","mne":"batt打，走 + le表名词 → battle战斗"},{"word":"bay","ipa":"/beɪ/","pos":"n.","def":"海湾，港湾","sen":"The bay cuts into the land and makes a perfect place to go swimming.","trans":"嵌入陆地的海湾正是绝佳的游泳场所。","mne":""},{"word":"be","ipa":"/bi/","pos":"v.","def":"是；在，存在","sen":"\"Be quiet\", said the teacher.","trans":"老师说:“安静！”","mne":""},{"word":"beach","ipa":"/biːtʃ/","pos":"n.","def":"海滩，河滩","sen":"We spent a wonderful day at the beach.","trans":"我们在海滩上度过了美妙的一天。","mne":""},{"word":"bear","ipa":"/ber/","pos":"n.","def":"熊；  v.带有；忍受；承受，支撑（重量）；生育","sen":"Look! The bear is eating honey.","trans":"看！那只熊在吃蜂蜜。","mne":" "},{"word":"beast","ipa":"/biːst/","pos":"n.","def":"野兽；性情凶残的人","sen":"Lions, tigers, wolves and leopards are all dangerous wild beasts.","trans":"狮子、老虎、狼和豹子都是危险的野兽。","mne":""},{"word":"beat","ipa":"/biːt/  ","pos":"v.","def":"敲打；打败，击败；有节奏地跳动；搅拌，搅打（用叉等）快速搅拌；  n.敲打；节拍","sen":"He is beating the drum hard with two sticks.","trans":"他正用两根鼓槌使劲击鼓。","mne":""},{"word":"beautiful","ipa":"/ˈbjuːtɪfl/","pos":"adj.","def":"美丽的，美好的","sen":"She looks beautiful in her new black shirt.","trans":"她穿着新买的黑色衬衫，真好看。","mne":"beauti美丽 + ful……的 → beautiful美的，美丽的"},{"word":"beauty","ipa":"/ˈbjuːti/","pos":"n.","def":"美人；美丽的东西；美（丽）","sen":"She is such a beauty that many people take pictures of her.","trans":"她是个大美人，许多人为她拍照。","mne":""},{"word":"because","ipa":"/bɪˈkɔːz/","pos":"conj.","def":"因为","sen":"The tooth is in pain because its master ate lots of sugar.","trans":"这颗牙齿很痛苦，因为它的主人吃了太多甜食。","mne":""},{"word":"become","ipa":"/bɪˈkʌm/","pos":"v.","def":"变成；成为","sen":"The bud became a beautiful rose.","trans":"花蕾变成了美丽的玫瑰。","mne":"be成为，变得 + come到达，出现 → become变成"},{"word":"bed","ipa":"/bed/","pos":"n.","def":"床；圃，花坛","sen":"My bed is so comfortable.","trans":"我的床相当舒服。","mne":""},{"word":"bedroom","ipa":"/ˈbedruːm/","pos":"n.","def":"卧室","sen":"There is a double bed and a dresser in the bedroom.","trans":"卧室里有一张双人床和一个梳妆台。","mne":"bed床 + room房间 → bedroom卧室"},{"word":"bee","ipa":"/biː/","pos":"n.","def":"蜜蜂","sen":"There's a bee on the yellow flower.","trans":"这朵黄花上有一只蜜蜂。","mne":""},{"word":"beef","ipa":"/biːf/","pos":"n.","def":"牛肉","sen":"This is a pack of beef steaks.","trans":"这是一盒牛排。","mne":""},{"word":"beer","ipa":"/bɪr/","pos":"n.","def":"啤酒","sen":"Drinking too much beer can make a person fat.","trans":"喝太多啤酒能让一个人变胖。","mne":""},{"word":"before","ipa":"/bɪˈfɔːr/","pos":"prep.","def":"【数】在...之前；  adv.以前","sen":"Add 3 to 3 before subtracting 1.","trans":"3加3，再减1。","mne":"be在 + fore在前的 → before在…以前"},{"word":"beforehand","ipa":"/bɪˈfɔːrhænd/","pos":"adv.","def":"预先","sen":"Dinner is ready when she arrives at the restaurant, because she ordered beforehand by phone.","trans":"她到餐厅时，晚餐已经准备好了，因为她预先用手机点了菜。","mne":""},{"word":"beg","ipa":"/beɡ/","pos":"v.","def":"乞求，恳求","sen":"The little dog is begging his master for food.","trans":"这只小狗正在向主人乞求食物。","mne":""},{"word":"begin","ipa":"/bɪˈɡɪn/","pos":"v.","def":"开始","sen":"The bell rings and class begins.","trans":"上课铃响就开始上课。","mne":""},{"word":"beginning","ipa":"/bɪˈɡɪnɪŋ/","pos":"n.","def":"开始，开端","sen":"I won the race! I was ahead from the beginning.","trans":"我赢得了跑步比赛！我从一开始就遥遥领先。","mne":"begin开始 + n + ing名词后缀 → beginning 开始"},{"word":"behalf","ipa":"/bɪˈhæf/","pos":"n.","def":"代表（某人），因为某人；利益；赞同，支持","sen":"\"I'll destroy you on behalf of the moon!\"","trans":"我要代表月亮消灭你！","mne":""},{"word":"behave","ipa":"/bɪˈheɪv/","pos":"v.","def":"表现；举止","sen":"The dog behaved well while bathing.","trans":"这条狗在洗澡时表现得很好。","mne":"be使 + have持有 → 一个人拥有的动作 → behave举止端正"},{"word":"behavior","ipa":"/bɪˈheɪvjə(r)/ ","pos":"n.","def":"行为（=behaviour）；举止","sen":"Your behaviors are really childish! You are scientists!","trans":"你俩的行为可真是幼稚！你们可是科学家！","mne":"be表示动作 + hav持有 + ior表名词 → 人持有的动作 → behavior举止行为"},{"word":"behaviour","ipa":"/bɪˈheɪvjər/","pos":"n.","def":"行为，举止","sen":"I will not tolerate this bad behaviour in my classroom!","trans":"我不能容忍在我的教室里有这种不良行为！","mne":""},{"word":"behind","ipa":"/bɪˈhaɪnd/","pos":"prep.","def":"在……后面；  adv.（时间或空间上）在后面","sen":"He was one of the few rich criminals that was actually put behind bars.","trans":"他是为数不多真正入狱的富有罪犯之一。","mne":"be构成介词 + hind藏在后面 → behind在......后面"},{"word":"being","ipa":"/ˈbiːɪŋ/","pos":"n.","def":"存在；生物；生命；  v.存在，处于；是","sen":"The universe came into being as a result of a big bang.","trans":"宇宙的出现是大爆炸的结果。","mne":"be存在，成为 + ing名词后缀 → being存在"},{"word":"belief","ipa":"/bɪˈliːf/","pos":"n.","def":"信仰；信念","sen":"Her personal belief gives her strength to face life's hardships.","trans":"她的个人信仰给了她面对人生苦难的力量。","mne":"be关于 + lief关心，爱 → belief信仰"},{"word":"believe","ipa":"/bɪˈliːv/","pos":"v.","def":"相信；认为；有宗教信仰","sen":"Some people believe that investment is a good way to make a fortune.","trans":"有些人相信投资是个发财致富的好方法。","mne":""},{"word":"bell","ipa":"/bel/","pos":"n.","def":"钟声；车铃","sen":"The sound of the church bell echoed through the quiet village, marking the start of a new day.","trans":"教堂的钟声在宁静的村庄中回荡，宣告新一天的开始。","mne":""},{"word":"belong","ipa":"/bɪˈlɔːŋ/","pos":"v.","def":"属于，附属","sen":"A belongs to B.","trans":"A属于B。","mne":"be使 + long长 → 使长久拥有 → belong属于"},{"word":"beloved","ipa":"/bɪˈlʌvɪd/","pos":"adj.","def":"心爱的，所钟爱的","sen":"He prepares a gift for his beloved wife. ","trans":"他为心爱的妻子准备了一份礼物。","mne":"be是 + loved被爱，所爱 → beloved 心爱的"},{"word":"below","ipa":"/bɪˈloʊ/","pos":"prep.","def":"在……之下；在…… 下方；（数量）少于；（标准）低于；  adv.在（或到）下面","sen":"Most of the iceberg is hidden below the water.","trans":"大部分冰山都隐藏在水下。","mne":"be表强调 ＋ low在下面 → below在…下面"},{"word":"belt","ipa":"/belt/","pos":"n.","def":"带，腰带；传送带","sen":"Each belt represents a different taekwondo level.","trans":"在跆拳道中，每种腰带代表不同的级位。","mne":""},{"word":"bench","ipa":"/bentʃ/","pos":"n.","def":"长凳；长形工作台","sen":"There are many benches along the street.","trans":"街道旁有很多长凳。","mne":""},{"word":"bend","ipa":"/bend/","pos":"v.","def":"（使）弯曲，把...弄弯；  n.弯曲，弯曲处","sen":"First bend to the right, and then to the left.","trans":"先向右弯曲，再向左弯曲。","mne":""},{"word":"beneath","ipa":"/bɪˈniːθ/","pos":"prep.","def":"在……下方","sen":"Most of the iceberg is beneath the sea surface.","trans":"冰山的大部分在海面之下。","mne":"be是 + neath下面 → beneath在下面"},{"word":"beneficial","ipa":"/ˌbenɪˈfɪʃl/","pos":"adj.","def":"有益的，有利的","sen":"Eating nutritious food and exercising are beneficial to our health.","trans":"吃有营养的食物和锻炼身体对我们的健康有益。","mne":"bene好 + fic做 + ial形容词，“有…的” → 有好处的 → beneficial有益的"},{"word":"benefit","ipa":"/ˈbenɪfɪt/","pos":"n.","def":"（政府）补助金，救济金；利益，好处；  v.得益于","sen":"The government provides benefits to the unemployed.","trans":"政府为失业者提供各种形式的补助。","mne":"bene善，好 + fit做 → 做事后的好处 → benefit利益，好处"},{"word":"beside","ipa":"/bɪˈsaɪd/","pos":"prep.","def":"在……旁边","sen":"The loyal dog is lying beside its owner.","trans":"这只忠诚的狗正趴在主人旁边。","mne":"be构成介词 + side旁边 → beside在……旁边"},{"word":"besides","ipa":"/bɪˈsaɪdz/","pos":"adv.","def":"此外；而且","sen":"There's a bride, and more women besides!","trans":"这里有一个新娘，此外，还有些女人！","mne":"be构成介词 + side边 + s表副词 → besides此外，而且"},{"word":"best","ipa":"/best/","pos":"adj.","def":"最好的；  adv.最好地","sen":"The restaurant in the middle is the best of the three.","trans":"中间那家餐厅是三家当中最好的。","mne":""},{"word":"bet","ipa":"/bet/","pos":"n.","def":"赌，赌注；  v.打赌；敢断定","sen":"The man made a bet on the score of a game.","trans":"这个人在比赛比分上赌了一把。","mne":""},{"word":"better","ipa":"/ˈbetər/","pos":"adj.","def":"（good的比较级）更好的；  adv.（well的比较级）更好地","sen":"The boy gets better grades after studying hard.","trans":"这个男孩在认真学习后，成绩越来越好。","mne":""},{"word":"between","ipa":"/bɪˈtwiːn/","pos":"prep.","def":"【数】在...之间","sen":"There is a pear between an apple and an orange.","trans":"在苹果和橙子中间有一个梨。","mne":"be强调 + tween二 → between在...之间"},{"word":"beyond","ipa":"/bɪˈjɑːnd/","pos":"prep.","def":"超出","sen":"I couldn't hit him as he was beyond my reach.","trans":"我打不了他，因为我够不着他。","mne":"be强调 + yond那边 → 超过"},{"word":"bible","ipa":"/ˈbaɪbl/","pos":"n.","def":"圣经","sen":"He's reading from the Bible in a church.","trans":"他正在教堂阅读《圣经》。","mne":""},{"word":"bicycle","ipa":"/ˈbaɪsɪkl/","pos":"n.","def":"自行车，脚踏车（=bike）","sen":"We are riding bicycles for a trip.","trans":"我们正在骑自行车旅行。","mne":"bi两 + cycle轮转 → bicycle自行车"},{"word":"bid","ipa":"/bɪd/","pos":"v.","def":"出价；投标；吩咐；  n.出价；投标；努力争取","sen":"The two superheroes bid for the batman suit.","trans":"这两位超级英雄都在竞拍蝙蝠侠的衣服。","mne":""},{"word":"big","ipa":"/bɪɡ/","pos":"adj.","def":"大的，巨大的","sen":"It's a big hamburger, but I can finish it!","trans":"这个汉堡包很大，但是我能吃完！","mne":""},{"word":"bill","ipa":"/bɪl/","pos":"n.","def":"账单；纸币，钞票；议案，法案；  v.给……开账单","sen":"The waiter said, “Here is your bill, sir.”","trans":"服务员说：”这是您的账单，先生。“","mne":""},{"word":"billion","ipa":"/ˈbɪljən/","pos":"num.","def":"十亿","sen":"The baby counted 9 zeros in the number 1 billion.","trans":"这个小孩从10亿这个数字里数出了9个零。","mne":"bi二 + llion=million百万 → 十亿"},{"word":"bind","ipa":"/baɪnd/","pos":"v.","def":"捆绑；装订；约束；结合；  n.窘境，困境","sen":"The mummies help to bind each other with the bandage.","trans":"木乃伊互相帮着绑绷带。","mne":""},{"word":"biological","ipa":"/ˌbaɪəˈlɑːdʒɪkl/","pos":"adj.","def":"生物学的；生物的，生物学的","sen":"Biological science is concerned with research of animals, plants and micro-organisms.","trans":"生物科学涉及对动物、植物和微生物的研究。","mne":"bio生物 ＋ logical...学的 → biological生物学（上）的"},{"word":"biology","ipa":"/baɪ'ɑlədʒɪ/","pos":"n.","def":"生物学","sen":"Biology is the study of life and living things.","trans":"生物学是研究生命和生物的学科。","mne":"bio生物 + logy……学 → biology生物学"},{"word":"bird","ipa":"/bɜːrd/","pos":"n.","def":"鸟，禽","sen":"These birds all have bright colors.","trans":"这些鸟的颜色都很鲜艳。","mne":""},{"word":"birth","ipa":"/bɜːrθ/","pos":"n.","def":"分娩，出生；【生】出生，诞生","sen":"With the doctor's help, the mother gave birth to a baby.","trans":"在医生的帮助下，这位母亲顺利产下一个婴儿。","mne":""},{"word":"birthday","ipa":"/ˈbɜːrθdeɪ/","pos":"n.","def":"生日派对","sen":"Are you excited for the birthday party tomorrow?","trans":"你对明天的生日派对感到兴奋吗？","mne":"birth出生 + day日子 → birthday生日"},{"word":"bit","ipa":"/bɪt/","pos":"v.","def":"咬，叮（bite的过去式）","sen":"A mosquito bit me last night.","trans":"昨晚有只蚊子咬了我。","mne":""},{"word":"bite","ipa":"/baɪt/","pos":"v.","def":"咬； 咬，叮，蜇；  n.咬","sen":"The patient complained of jaw pain when he tried to bite into a sandwich.","trans":"病人抱怨说，他在试着咬三明治时会下巴疼。","mne":""},{"word":"bitter","ipa":"/ˈbɪtər/","pos":"adj.","def":"味苦的；带来痛苦的；激烈而不愉快的","sen":"The coffee is so bitter.","trans":"这杯咖啡太苦了。","mne":""},{"word":"black","ipa":"/blæk/","pos":"adj.","def":"黑色的；  n.黑色","sen":"Her shiny black hair is beautiful.","trans":"她的闪亮黑发很美。","mne":""},{"word":"blackboard","ipa":"/ˈblækbɔːrd/","pos":"n.","def":"黑板","sen":"She is the student on duty today, so she needs to clean the blackboard.","trans":"她是今天的值日生，所以她要擦黑板。","mne":"black黑色的 + board板子 → blackboard黑板"},{"word":"blame","ipa":"/bleɪm/","pos":"n.","def":"指责；责备；  v.把……归咎于；责备","sen":"I always get all the blame, but I never do anything wrong.","trans":"我总是受到所有的责备，但我从没有做错过任何事。","mne":""},{"word":"blank","ipa":"/blæŋk/","pos":"adj.","def":"（纸等）空白的；  n.空白，空白处","sen":"You can write something on a blank page of this notebook.","trans":"你可以在这个本子的空白页上写点东西。","mne":""},{"word":"blanket","ipa":"/ˈblæŋkɪt/","pos":"n.","def":"毯子，毛毯；  adj.总括的；  v.使覆盖","sen":"The cute little kitten is sleeping in a soft blanket.","trans":"那只可爱的小猫正睡在一条柔软的毯子里。","mne":"blank=blanc白 ＋ et表名词 → 白色织物 → blanket毛毯，毯子，羊毛毯"},{"word":"blast","ipa":"/blæst/","pos":"n.","def":"爆炸；一阵（疾风等）；  v.爆破","sen":"The building was destroyed in the blast after he turned around.","trans":"他转身后，这栋楼在爆炸中被摧毁了。","mne":""},{"word":"bleed","ipa":"/bliːd/","pos":"v.","def":"流血","sen":"The paw of the dog is bleeding.","trans":"这只狗的爪子在流血。","mne":""},{"word":"blend","ipa":"/blend/","pos":"v.","def":"混合；晕染，融合","sen":"Blend the flour and the water with a spoon.","trans":"用勺子把面粉和水混到一起。","mne":""},{"word":"blind","ipa":"/blaɪnd/","pos":"adj.","def":"失明的；瞎的；  v.使失明；  n.百叶窗","sen":"The blind woman is crossing the street with her guide dog.","trans":"这位失明的女士正和她的导盲犬一起过马路。","mne":""},{"word":"block","ipa":"/blɑ:k/","pos":"n.","def":"一块（指木头，石头等硬物）；街区；大楼，大厦；  v.阻塞，阻挡","sen":"This block of stone has stood here for a long time.","trans":"这块石头立在这里很久了。","mne":""},{"word":"blood","ipa":"/blʌd/","pos":"n.","def":"血（液）；血统","sen":"The doctor took some blood from me during my checkup.","trans":"医生在给我检查时抽了点儿血。","mne":"blo茁壮成长，绽放 + od → 富有生命力的事物 → blood血液"},{"word":"bloom","ipa":"/bluːm/","pos":"v.","def":"开花；  n.花；开花期","sen":"These red flowers bloom in spring.","trans":"这些红色的花在春天开放。","mne":""},{"word":"blouse","ipa":"/blaʊs/","pos":"n.","def":"短上衣","sen":"The off-shoulder blouse is on trend nowadays.","trans":"这种露肩短上衣最近很流行。","mne":""},{"word":"blow","ipa":"/bloʊ/","pos":"v.","def":"吹，吹动，吹气；打击，殴打；  n.打击，殴打","sen":"The kid likes to blow bubbles.","trans":"这个小孩喜欢吹泡泡。","mne":""},{"word":"blue","ipa":"/bluː/","pos":"adj.","def":"蓝色的；忧郁的；  n.蓝色","sen":"Look at the blue sky and sea. What a view!","trans":"看，蓝天大海一色，真是壮观！","mne":""},{"word":"board","ipa":"/bɔːrd/","pos":"n.","def":"板；栏；董事会；  v.上船（或火车、飞机、公共汽车等）","sen":"This is a large board.","trans":"这是一块大的木板。","mne":""},{"word":"boat","ipa":"/boʊt/","pos":"n.","def":"小船，小舟，小艇；  v.划船；  v.用船运输","sen":"The little wooden boat floats on the water.","trans":"这艘小木船浮在水面上。","mne":""},{"word":"body","ipa":"/ˈbɑːdi/","pos":"n.","def":"身体","sen":"The human body is beautiful, amazing, yet delicate.","trans":"人体非常美丽、神奇，却也非常脆弱。","mne":""},{"word":"boil","ipa":"/bɔɪl/","pos":"v.","def":"烧开，煮沸，沸腾；  n.煮沸，沸腾","sen":"The water is boiling in the cooking pot.","trans":"锅里的水正在沸腾。","mne":""},{"word":"bold","ipa":"/boʊld/","pos":"adj.","def":"大胆自信的，勇于冒险的；醒目的；大胆自信的；无耻的，放肆的","sen":"She is a bold and fearless climber.","trans":"她是一个勇敢无畏的攀登者。","mne":""},{"word":"bomb","ipa":"/bɑːm/","pos":"n.","def":"炸弹；  v.轰炸，投弹于……","sen":"This bomb will explode any minute!","trans":"这个炸弹随时都会爆炸！","mne":""},{"word":"bond","ipa":"/bɑːnd/","pos":"n.","def":"情谊，羁绊；束缚物，联结物；保释金；债券；  v.使牢固结合；团结一致","sen":"Family members often share a bond so deep that no conflict can truly break it.","trans":"家庭成员之间往往有着一种极为深厚的羁绊，没有矛盾能真正将其割断。","mne":""},{"word":"bone","ipa":"/boʊn/","pos":"n.","def":"【医】骨；骨头","sen":"A fracture is a break or crack in a bone, often caused by trauma or stress.","trans":"骨折是指骨头出现断裂或裂缝，通常是由外伤或压力引起的。","mne":""},{"word":"bonus","ipa":"/ˈboʊnəs/","pos":"n.","def":"奖金，红利；红利；奖金，额外津贴","sen":"Employees received a year-end bonus for exceeding their sales targets.","trans":"员工因超额完成销售目标而获得年终奖金。","mne":"bon好 + us用 → 用好的东西进行奖励 → 奖金，红利"},{"word":"book","ipa":"/bʊk/","pos":"n.","def":"书；  v.预订","sen":"I found three books in the library to read.","trans":"我在图书馆里找了三本书来读。","mne":""},{"word":"boom","ipa":"/bu:m/","pos":"n.","def":"轰鸣声；繁荣；增长期，繁荣期；  v.迅速发展；  v.轰鸣","sen":"The bomb went off with a loud boom.","trans":"炸弹随着轰隆的一声巨响爆炸了。","mne":""},{"word":"boost","ipa":"/buːst/","pos":"v.","def":"使增长，使兴旺；促进，推动；  n.提高，增长","sen":"The turtle uses a rocket to boost his speed.","trans":"这个乌龟使用火箭来增加自己的速度。","mne":""},{"word":"boot","ipa":"/buːt/","pos":"n.","def":"靴子","sen":"When I camp in the mountains, I always wear hiking boots.","trans":"当我在山上露营时，我总是穿登山靴。","mne":""},{"word":"border","ipa":"/ˈbɔːrdər/","pos":"n.","def":"边界；边沿；  v.近似；毗邻；与……接壤；为……镶边","sen":"There is a distinct border between the urban and the rural areas.","trans":"城市与农村之间有一条明显的边界。","mne":"bord边 + er表名词 → border边境"},{"word":"bore","ipa":"/bɔːr/","pos":"v.","def":"使厌烦；挖掘，开凿；钻孔；bear的过去式；  n.孔","sen":"The man's endless talking has bored his colleagues to sleep.","trans":"这个男人冗长的讲话让同事们都厌烦得想睡觉了。","mne":""},{"word":"boring","ipa":"/ˈbɔːrɪŋ/","pos":"adj.","def":"无聊的，乏味的","sen":"I've done my boring homework — now can I go outside and play?","trans":"我已经完成无聊的作业了，现在我可以出去玩了吗？","mne":"bor无聊 + ing名词后缀，表状态 → boring令人厌烦的，乏味的"},{"word":"born","ipa":"/bɔːrn/","pos":"adj.","def":"天生的","sen":"He was a born pianist.","trans":"他是位天生的钢琴家。","mne":""},{"word":"borrow","ipa":"/ˈbɔːrəʊ/","pos":"v.","def":"【数】借位","sen":"When subtracting numbers with different digits, remember to borrow from the left column if needed.","trans":"在对位数不同的数相减时，如果需要，请记得从左边的一列借位。","mne":""},{"word":"boss","ipa":"/bɔːs/","pos":"n.","def":"老板，上司","sen":"I was nervous when my boss asked to speak with me.","trans":"当我的老板和我说话时我很紧张。","mne":""},{"word":"both","ipa":"/boʊθ/","pos":"pron.","def":"两者（都）","sen":"They both are considering their next move.","trans":"他们都在考虑下一步怎么走。","mne":""},{"word":"bother","ipa":"/ˈbɑːðər/","pos":"v.","def":"打扰，因……操心；麻烦","sen":"He always plays the guitar at night, which really bothers me!","trans":"他总在晚上弹吉他，这真的打扰到我了！","mne":""},{"word":"bottle","ipa":"/ˈbɑːtl/","pos":"n.","def":"瓶子","sen":"I hope someone will find my message in this bottle.","trans":"我希望有人能发现瓶子里我的留言。","mne":""},{"word":"bottom","ipa":"/ˈbɑːtəm/","pos":"n.","def":"底部；尽头","sen":"The bottom of this object is red.","trans":"这个物体的底部是红色的。","mne":""},{"word":"bound","ipa":"/baʊnd/","pos":"adj.","def":"必然的；有义务的；与…密切相关的；准备前往（某地）；  v.跳跃着前行；  n.跳跃","sen":"The prisoner is bound to face his execution.","trans":"这个犯人必然会面临死刑。","mne":""},{"word":"boundary","ipa":"/ˈbaʊndəri/","pos":"n.","def":"边界，国界；分界线","sen":"Many students will draw a line on the desk as a boundary.","trans":"许多学生会在课桌上画一条线作为分界。","mne":"bound范围 + ary表抽象名词 → boundary分界线，边界"},{"word":"bowl","ipa":"/boʊl/","pos":"n.","def":"碗；一碗的容量；  v.滚动（球）；[体]投球","sen":"The four bowls are in four different colors.","trans":"这四个碗分别有四种不同的颜色。","mne":""},{"word":"bowling","ipa":"/ˈboʊlɪŋ/","pos":"n.","def":"保龄球","sen":"I am teaching my son how to play bowling.","trans":"我正在教我儿子怎样打保龄球。","mne":"bowl球 + ing后缀 → bowling保龄球"},{"word":"box","ipa":"/bɑːks/","pos":"n.","def":"盒子，箱子；  v.拳击","sen":"The box of books is really heavy.","trans":"这一箱书可真沉。","mne":""},{"word":"boy","ipa":"/bɔɪ/","pos":"n.","def":"男孩","sen":"The little boy loves to read.","trans":"这个小男孩儿喜欢阅读。","mne":""},{"word":"brain","ipa":"/breɪn/","pos":"n.","def":"脑","sen":"Your brain is the organ inside your head that controls your body's activities.","trans":"大脑是在你的脑袋里控制身体活动的器官。","mne":""},{"word":"branch","ipa":"/bræntʃ/","pos":"n.","def":"树枝；分支","sen":"The man cut off a branch from the tree.","trans":"那个男人从树上剪下了一根树枝。","mne":""},{"word":"brand","ipa":"/brænd/","pos":"n.","def":"品牌；烙印；  v.加污名于；给……打上烙印；加商标于；谴责","sen":"The woman knows so many girls' beauty brands.","trans":"这个女人知道好多女孩子用的美妆品牌。","mne":""},{"word":"brave","ipa":"/breɪv/ ","pos":"adj.","def":"勇敢的，无畏的","sen":"A brave swimmer jumped into the river to save the drowning boy.","trans":"一位勇敢的游泳者跳进河里救了那个溺水的男孩。","mne":""},{"word":"bravery","ipa":"/ˈbreɪvəri/","pos":"n.","def":"勇敢，勇气","sen":"Jumping between the two rocks requires a lot of bravery.","trans":"在这两块石头间跳跃需要很大的勇气。","mne":"brave勇敢 + ry表名词 → bravery勇气，勇敢"},{"word":"bread","ipa":"/bred/","pos":"n.","def":"面包；生计","sen":"There is nothing more delicious than freshly baked bread.","trans":"没有什么能比刚烤出来的面包更美味的了。","mne":""},{"word":"break","ipa":"/breɪk/","pos":"v.","def":"打破，摔碎；  n.中断；休息","sen":"If you break a glass, be careful when picking up the pieces!","trans":"如果你打碎了玻璃杯，捡碎片的时候要小心！","mne":""},{"word":"breakfast","ipa":"/ˈbrekfəst/","pos":"n.","def":"早餐","sen":"Breakfast is the most important meal of the day.","trans":"早餐是一天中最重要的一餐。","mne":"break中断 + fast斋戒 → 中断斋戒进食 → breakfast早饭"},{"word":"breast","ipa":"/brest/","pos":"n.","def":"乳房","sen":"Women should pay attention to breast health.","trans":"女性应该注意乳房健康。","mne":""},{"word":"breath","ipa":"/breθ/  ","pos":"n.","def":"呼吸；气息","sen":"Take a deep breath and try to relax.","trans":"深吸一口气，试着放松。","mne":""},{"word":"breathe","ipa":"/briːð/","pos":"v.","def":"呼吸；呼出；低语","sen":"She breathes deeply to relax herself when doing yoga.","trans":"她做瑜伽时用深呼吸的方式来放松自己。","mne":""},{"word":"breed","ipa":"/briːd/","pos":"v.","def":"饲养，培育；繁殖；  n.品种","sen":"He makes a living by breeding cows.","trans":"他以饲养奶牛为生。","mne":""},{"word":"brick","ipa":"/brɪk/","pos":"n.","def":"砖","sen":"The wall is made up of plenty of bricks.","trans":"这面墙壁是用许多块砖头筑成的。","mne":""},{"word":"bride","ipa":"/braɪd/","pos":"n.","def":"新娘","sen":"The bride looks like an angel in her white dress.","trans":"这个穿着白色婚纱的新娘看起来像个天使。","mne":""},{"word":"bridge","ipa":"/brɪdʒ/","pos":"n.","def":"桥，桥梁","sen":"This is an old bridge across the river.","trans":"河上的这座桥有些年头了。","mne":""},{"word":"brief","ipa":"/briːf/","pos":"adj.","def":"简洁的，简短的；  n.摘要；  v.简单汇报；向…通报情况","sen":"The brief letter explains why she wants to quit.","trans":"这封简短的信解释了她为何想辞职。","mne":""},{"word":"bright","ipa":"/braɪt/","pos":"adj.","def":"明亮的，光线充足的；鲜艳的；聪明的","sen":"Bright light makes him close his eyes.","trans":"强烈的亮光让他闭上了眼睛。","mne":""},{"word":"brilliant","ipa":"/ˈbrɪliənt/","pos":"adj.","def":"聪颖的；卓越的；明亮的；极好的","sen":"This girl is so brilliant that she can solve the difficult problem.","trans":"这个小女孩很聪明，她能解决这道难题。","mne":"brilli=brill光辉 + ant…的 → brilliant光辉的；卓越的"},{"word":"bring","ipa":"/brɪŋ/","pos":"v.","def":"带来；拿来；引起，导致","sen":"Every morning he brings a package of things for my baby.","trans":"每天早晨他都带一包东西给我的宝宝。","mne":""},{"word":"broad","ipa":"/brɔːd/","pos":"adj.","def":"宽阔的","sen":"This road is broad enough for many cars to drive on.","trans":"这条道路足够宽，可以容纳很多车行驶。","mne":""},{"word":"broadcast","ipa":"/ˈbrɔːdkæst/","pos":"n.","def":"广播或电视节目；  v.播放，广播","sen":"A broadcast is a program, a performance, or a speech on the radio or on television.","trans":"广播电视节目是指在收音机里或在电视上播放的节目、表演或演说。","mne":"broad宽广 + cast投射 → 广播, 播音"},{"word":"broaden","ipa":"/ˈbrɔːdn/","pos":"v.","def":"（使）变宽；扩大（影响）","sen":"This once narrow track has been broadened into a wider road.","trans":"这条曾经的狭窄小道被拓宽成了一条宽阔的马路。","mne":"broad宽 + en变成 → broaden加宽"},{"word":"brochure","ipa":"/brəʊˈʃʊr/","pos":"n.","def":"手册，小册子；资料(或广告)手册","sen":"She carefully studied the company's brochure.","trans":"她认真地研究过这家公司的手册。","mne":"broch刺，缝 + ure表名词 → 手册"},{"word":"broom","ipa":"/bruːm/","pos":"n.","def":"扫把，扫帚","sen":"Use the broom to clean the floor.","trans":"请用扫帚来扫地。","mne":""},{"word":"brother","ipa":"/ˈbrʌðər/","pos":"n.","def":"兄弟，哥哥，弟弟","sen":"The brother and sister play together.","trans":"两兄妹在一起玩。","mne":""},{"word":"brow","ipa":"/braʊ/","pos":"n.","def":"眉，眉毛；额；山脊，坡顶","sen":"She is painting her eye brows.","trans":"她正在画眉毛。","mne":""},{"word":"brown","ipa":"/braʊn/","pos":"adj.","def":"褐色的，棕色的；  n.褐色，棕色","sen":"Her hair is brown, whereas her friend's is black.","trans":"她的头发是棕色的，然而她朋友的头发是黑色的。","mne":""},{"word":"brush","ipa":"/brʌʃ/","pos":"n.","def":"画笔，笔刷；灌木丛；  v.刷","sen":"Brushes of different sizes may be applied in different situations.","trans":"不同尺寸的画笔可以用于不同的情况。","mne":""},{"word":"brutal","ipa":"/ˈbruːtl/","pos":"adj.","def":"残忍的，粗鲁的","sen":"Sometimes players perform brutal actions at sport arena.","trans":"有时候运动员在场上表现得十分凶狠。","mne":"brut=brute残暴的人 + al如……的 → brutal野兽般的；冷酷的"},{"word":"budget","ipa":"/ˈbʌdʒɪt/","pos":"n.","def":"预算","sen":"The total amount on the shopping list is over my budget.","trans":"购物清单的总额超出了我的预算。","mne":""},{"word":"bug","ipa":"/bʌɡ/","pos":"n.","def":"臭虫，小虫子；【计】（程序中的）漏洞、故障；窃听器；  v.窃听","sen":"There are some bugs on the leaf.","trans":"叶子上有一些小虫子。","mne":""},{"word":"build","ipa":"/bɪld/","pos":"v.","def":"建立，发展；建造","sen":"He has been entering speech contests to help build his confidence.","trans":"他通过参加演讲比赛来建立自信。","mne":""},{"word":"building","ipa":"/ˈbɪldɪŋ/","pos":"n.","def":"建筑物；楼房，房子","sen":"These buildings stretch high into the sky.","trans":"这些建筑物直插云天。","mne":"build建造 + ing某种行为的产物 → building建筑物"},{"word":"bulletin","ipa":"/ˈbʊlətɪn/","pos":"n.","def":"公告；公报；新闻简报","sen":"The students are reading some notices posted on the bulletin board.","trans":"学生正在读公告栏上张贴的一些通知。","mne":""},{"word":"bunch","ipa":"/bʌntʃ/","pos":"n.","def":"束，串，群，伙","sen":"A bunch of pomelo leaves is perfect to sweep away bad luck.","trans":"一束柚子叶非常适合用来扫除晦气。","mne":""},{"word":"burden","ipa":"/ˈbɜːrdn/","pos":"n.","def":"负担；  v.使负重，装载；烦扰","sen":"His working burden is too heavy, which makes him have to surrender.","trans":"他的工作负担太沉重了，让他不得不投降。","mne":""},{"word":"bureau","ipa":"/ˈbjʊroʊ/","pos":"n.","def":"局，司，处，社，所","sen":"The Federal Bureau of Investigation is a government agency in the United States investigating crimes.","trans":"联邦调查局是美国调查犯罪的政府机构。","mne":""},{"word":"burn","ipa":"/bɜːrn/","pos":"v.","def":"燃烧；烧；  n.烧伤","sen":"The candle will burn slowly until it melts completely.","trans":"蜡烛会慢慢燃烧，直到完全融化。","mne":""},{"word":"burst","ipa":"/bɜːrst/","pos":"v.","def":"爆炸；迸发；  n.爆炸；爆裂；迸发","sen":"The red balloon burst, and it scared the child.","trans":"这个红色的气球爆炸了，吓到了这个孩子。","mne":""},{"word":"bury","ipa":"/ˈberi/","pos":"v.","def":"埋葬；隐藏，埋藏","sen":"It's not much fun to be buried in the dirt like this!","trans":"（HATA王子）像这样被埋在土里一点也不好玩儿。","mne":"bur隐藏；保护 + y表发音 → bury隐藏；埋葬"},{"word":"bus","ipa":"/bʌs/","pos":"n.","def":"公共汽车，巴士；大客车；巴士","sen":"Let's take the bus to the next city.","trans":"让我们乘公交车去下一个城市吧。","mne":""},{"word":"bush","ipa":"/bʊʃ/  ","pos":"n.","def":"灌木丛；矮树丛","sen":"Look, there is a rabbit in the bush!","trans":"看，那丛灌木里有一只兔子！","mne":""},{"word":"business","ipa":"/ˈbɪznəs/","pos":"n.","def":"商业，生意；事务","sen":"We expanded our business around the globe.","trans":"我们把生意扩展到了世界各地。","mne":"busi=busy忙碌的 + ness性质，表名词 → 对某事很关心、焦虑 → business事务；生意"},{"word":"busy","ipa":"/ˈbɪzi/","pos":"adj.","def":"忙碌的，占线的","sen":"I have been calling him all day, but his line is always busy.","trans":"我已经给他打了一天电话了，但他电话总是占线。","mne":""},{"word":"but","ipa":"/bʌt/, /bət/","pos":"conj.","def":"但是，可是，然而；  adv.仅","sen":"I want to play football, but I have to finish my homework first.","trans":"我想要踢足球，但我得先完成我的作业。","mne":"b=by通过 + ut外面 → 例外 → but但是，然而"},{"word":"butter","ipa":"/ˈbʌtər/","pos":"n.","def":"黄油，奶油；  v.涂黄油于……上","sen":"She usually has bread with butter for breakfast.","trans":"她早餐经常吃黄油面包。","mne":"but牛 + ter奶酪 → 牛奶加工而成的乳酪 → butter黄油"},{"word":"button","ipa":"/ˈbʌtn/","pos":"n.","def":"（机器上的）按钮，开关；纽扣","sen":"Press the button to turn off the computer.","trans":"按这个按钮关掉电脑。","mne":""},{"word":"buy","ipa":"/baɪ/","pos":"v.","def":"买；收买；相信","sen":"The couple was excited to buy their first home together.","trans":"这对恋人因为一起买了他们的第一栋房子而很兴奋。","mne":""},{"word":"by","ipa":"/baɪ/","pos":"prep.","def":"通过（表示方式）；乘……；被，由（表被动）","sen":"The children go to school by bus.","trans":"孩子们坐公交车去上学。","mne":""},{"word":"bye","ipa":"/baɪ/","pos":"excl.","def":"再见（=goodbye）","sen":"After saying bye, he is going to take the train.","trans":"说完再见后，他就要去乘火车了。","mne":""},{"word":"bye-bye","ipa":"/'baɪˌbaɪ/","pos":"int.","def":"再见","sen":"The girl is saying \"bye-bye\" to the boy.","trans":"女孩正在给男孩说拜拜。","mne":""},{"word":"cable","ipa":"/ˈkeɪbl/","pos":"n.","def":"电缆；缆绳，钢索","sen":"Many birds are standing on the cables for a rest.","trans":"许多小鸟正停在电缆上休息。","mne":""},{"word":"cafe","ipa":"/kæˈfeɪ/","pos":"n.","def":"咖啡馆","sen":"The man drinks coffee in a cafe.","trans":"这个男人在咖啡馆喝咖啡。","mne":""},{"word":"cake","ipa":"/keɪk/","pos":"n.","def":"蛋糕，饼","sen":"Would you like some chocolate cake?","trans":"你想来点儿巧克力蛋糕吗？","mne":""},{"word":"calculate","ipa":"/ˈkælkjuleɪt/","pos":"v.","def":"计算","sen":"Let's calculate the final amount.","trans":"让我们计算一下最终的金额。","mne":"calc石头 + ul + ate表动词 → 用小石头计数 → 计算"},{"word":"calculation","ipa":"/ˌkælkjuˈleɪʃn/","pos":"n.","def":"计算","sen":"The little girl is doing calculations on the blackboard.","trans":"小女孩正在黑板上做计算题。","mne":"calcul计算 ＋ ation表示行为、状态、过程 → calculation计算，考虑"},{"word":"calculator","ipa":"/ˈkælkjuleɪtər/","pos":"n.","def":"计算器，计算者","sen":"The man is working with a calculator.","trans":"这个男人正在用计算器工作。","mne":"calcul计算 + ator 表示做……工作的物 → n.计算器，计算者"},{"word":"calendar","ipa":"/ˈkælɪndər/","pos":"n.","def":"日历，挂历","sen":"The month is over, so it's time to flip to the next month on the calendar.","trans":"这个月结束了，是时候翻到日历的下一个月了。","mne":"calend每月第一天 + ar表名词 → calendar日历"},{"word":"calf","ipa":"/kæf/","pos":"n.","def":"小腿；小牛，牛犊","sen":"His calf muscles are sore after a long run.","trans":"长跑之后，他的小腿肌肉酸痛。","mne":""},{"word":"call","ipa":"/kɔːl/","pos":"n.","def":"通话，打电话；  v.叫，喊；打电话给…","sen":"He gave his mother a phone call from work.","trans":"他上班的时候给母亲打了个电话。","mne":""},{"word":"calm","ipa":"/kɑːm/","pos":"adj.","def":"冷静的，平静的；沉着的，镇静的；  v.（使）平静，（使）镇定；  n.平静，安宁","sen":"She remains calm while her scared friends hide behind her.","trans":"她保持镇定，而她害怕的朋友们则躲在她身后。","mne":""},{"word":"camera","ipa":"/ˈkæmərə/","pos":"n.","def":"照相机，摄影机","sen":"She is able to take high quality photos with that camera.","trans":"她能用那台照相机拍出高质量的照片。","mne":""},{"word":"camp","ipa":"/kæmp/","pos":"n.","def":"营地；阵营；  v.露营；宿营","sen":"Our camp is located by the lake.","trans":"我们的营地在湖边。","mne":"camp=field田野 → camp营地"},{"word":"campaign","ipa":"/kæmˈpeɪn/","pos":"n.","def":"（社会性、政治性）活动，运动；  v.从事活动","sen":"Many people launched a campaign to call for environmental protection.","trans":"许多人发起了一场呼吁环保的运动。","mne":"camp营地 + aign名词后缀 → 营地 → 战役"},{"word":"campus","ipa":"/ˈkæmpəs/","pos":"n.","def":"校园","sen":"On our campus, we can just sit on the lawn to do our group work.","trans":"在我们的校园里，我们可以坐在草坪上做小组作业。","mne":"camp田野 + us用 →用田野建造学校→ campus校园"},{"word":"can","ipa":"/kæn/","pos":"n.","def":"罐头；听，一听（的量）","sen":"I've bought you a can of coke. Go ahead and enjoy it!","trans":"我为你买了一听可乐，喝吧！","mne":""},{"word":"canal","ipa":"/kəˈnæl/","pos":"n.","def":"运河，河流；水渠，灌溉渠","sen":"There are many canals running through the city.","trans":"这座城市有很多运河穿流其中。","mne":""},{"word":"cancel","ipa":"/ˈkænsl/","pos":"v.","def":"取消","sen":"I cancelled my shopping order.","trans":"我取消了我的购物订单。","mne":""},{"word":"cancer","ipa":"/ˈkænsər/","pos":"n.","def":"癌症","sen":"Smoking may cause lung cancer.","trans":"吸烟可能会导致肺癌。","mne":"canc=kar艰难，严重 + er名词后缀，人或物 → 严重的疾病 → cancer癌症"},{"word":"candidate","ipa":"/ˈkændɪdət/","pos":"n.","def":"候选人；考生，应试者","sen":"We have shortlisted you as a potential candidate for the position.","trans":"我们已经将你列入该职位的潜在候选人名单中。","mne":"cand发光，白 + id + ate表名词  → 白衣人（古罗马时期谋求官职者都着白衣） → candidate候选人"},{"word":"cap","ipa":"/kæp/","pos":"n.","def":"帽子；  v.覆盖","sen":"This is a blue police cap.","trans":"这是一顶蓝色的警帽。","mne":""},{"word":"capable","ipa":"/ˈkeɪpəbl/","pos":"adj.","def":"有本领的，有能力的","sen":"Your penguin is a weightlifter? That must be a very capable bird.","trans":"你的企鹅是个举重运动员？那它一定是一只有本领的鸟。","mne":"cap握住 ＋ able形容词后缀，具有某种性质的 → capable有能力的，有才能的"},{"word":"capacity","ipa":"/kəˈpæsɪti/","pos":"n.","def":"容量；才能；负载量；本领","sen":"The capacity of this cup is 2 liters.","trans":"这个杯子的容量是两升。","mne":"cap拿 + acity名词后缀 → 拿住的能力 → capacity容量"},{"word":"capital","ipa":"/ˈkæpɪtl/","pos":"n.","def":"首都；资金，资本；省会","sen":"Beijing is the capital of China.","trans":"北京是中国的首都。","mne":"capit头 + al…的 → 头的 → capital首都"},{"word":"captain","ipa":"/ˈkæptɪn/","pos":"n.","def":"船长，机长","sen":"The captain is standing at the helm of the ship.","trans":"船长正在船上掌舵。","mne":"capt头 + ain表名词，...的人 → captain首领"},{"word":"capture","ipa":"/ˈkæptʃər/","pos":"v.","def":"捕获，抓住；留存；使迷住；（用文字或图片）记录；  n.俘虏；捕获","sen":"The rabbit was captured by the hunter.","trans":"猎人抓到了那只兔子。","mne":"capt拿，抓，握住 + ure名词后缀 → 抓住毛病 → capture逮捕，捉拿"},{"word":"car","ipa":"/kɑːr/","pos":"n.","def":"汽车，小汽车，轿车","sen":"There is a green car parked at the side of the road.","trans":"路边停着一辆绿色的车。","mne":""},{"word":"carbon","ipa":"/ˈkɑːrbən/","pos":"n.","def":"碳；复写纸","sen":"Coal burns so easily because it contains lots of carbon.","trans":"煤很容易燃烧是因为它含有大量的碳。","mne":"carb碳 + on名词后缀 → carbon碳"},{"word":"card","ipa":"/kɑːrd/","pos":"n.","def":"卡，卡片，贺卡，名片；纸牌，牌","sen":"Here is my card. It has my phone number and email on it.","trans":"这是我的名片，上面有我的电话号码和邮箱地址。","mne":""},{"word":"care","ipa":"/ker/","pos":"v.","def":"关心；照顾，照料","sen":"She really cares about her patient.","trans":"她真的很关心她的病人。","mne":""},{"word":"career","ipa":"/kəˈrɪr/","pos":"n.","def":"职业，事业；生涯，经历","sen":"The little girl is thinking about her future career.","trans":"小女孩思考着自己的未来职业。","mne":""},{"word":"careful","ipa":"/ˈkerfl/","pos":"adj.","def":"仔细的，细心的；小心的","sen":"Pay careful attention to each piece so you don't choose the wrong one.","trans":"每一块拼图都要仔细观察，这样你就不会选错。","mne":"care照料 + ful有…...的 → careful小心的"},{"word":"careless","ipa":"/ˈkerləs/","pos":"adj.","def":"粗心的","sen":"If you're careless with your trash, other people may get hurt.","trans":"如果你乱扔垃圾，其他人可能会因此受伤。","mne":"care关心 ＋ less否定后缀 → 不关心的 → careless粗心的，漫不经心的"},{"word":"cargo","ipa":"/ˈkɑːrɡoʊ/ ","pos":"n.","def":"货物","sen":"This machine loads the cargo onto the ship.","trans":"这台机器把货物装载到船上。","mne":""},{"word":"carpet","ipa":"/ˈkɑːrpɪt/","pos":"n.","def":"地毯","sen":"I put my books on the carpet.","trans":"我把我的书放在了地毯上。","mne":""},{"word":"carry","ipa":"/ˈkæri/","pos":"v.","def":"携带（疾病、病菌）；传送，运送，输送","sen":"It is widely believed that bats carry many viruses.","trans":"目前，人们广泛认为蝙蝠携带着大量病毒。","mne":""},{"word":"cart","ipa":"/kɑːrt/","pos":"n.","def":"手推车，运货马车","sen":"Carts are useful for carrying goods in the supermarket.","trans":"在超市里用手推车装商品很方便。","mne":""},{"word":"cartoon","ipa":"/kɑːrˈtuːn/","pos":"n.","def":"卡通（片），动画片","sen":"Almost every kid loves to watch cartoons!","trans":"几乎所有小孩子都喜欢看卡通片！","mne":"cart一张纸 + oon表名词 → 画在纸上的 → cartoon动画片；漫画"},{"word":"case","ipa":"/keɪs/","pos":"n.","def":"案件；情况；箱，盒；容器；套；状况，场合；事实；事例，实例","sen":"They are discussing the case in court.","trans":"他们正在法庭上讨论这个案件。","mne":""},{"word":"cash","ipa":"/kæʃ/","pos":"n.","def":"现金","sen":"The woman behind the counter said she takes cash only.","trans":"柜台后面的女人说她只接受现金。","mne":""},{"word":"cashier","ipa":"/kæˈʃɪr/","pos":"n.","def":"出纳员，收银员；  v.驱逐，革除，废除","sen":"The cashier at the supermarket is scanning each item.","trans":"超市的收银员正在扫描每一件商品。","mne":"cash现金 + ier表名词，人或物 → 管理现金的人 → cashier出纳"},{"word":"cassette","ipa":"/kəˈset/","pos":"n.","def":"录像带，盒式磁带","sen":"I don't even have the machine to play these old cassettes.","trans":"我连播放这些旧磁带的设备都没有。","mne":"cass=case盒子 + ette表名词  → 小盒子  → cassette录像带"},{"word":"cast","ipa":"/kæst/","pos":"v.","def":"投，掷；投射（光）；  n.演员表；全体演员","sen":"He's going to cast that rock at the seaside.","trans":"他准备在海边把石块投掷出去。","mne":""},{"word":"casual","ipa":"/ˈkæʒuəl/","pos":"adj.","def":"偶然的；随便的；非正式的；临时的","sen":"Our first meeting was purely casual; we bumped into each other at a coffee shop.","trans":"我们的第一次见面完全是偶然的；我们在咖啡店碰巧遇到了。","mne":"cas落下 + ual……的 → 突然降临的，不是安排好的 → casual偶然的"},{"word":"cat","ipa":"/kæt/","pos":"n.","def":"猫","sen":"I prefer dogs, but this cat is so cute!","trans":"我更喜欢狗，但是这只猫真可爱！","mne":""},{"word":"catalog","ipa":"/ˈkætəlɔːɡ/","pos":"n.","def":"目录，目录册，商品目录","sen":"There is a variety of products in the catalog for us to select.","trans":"我们可以在商品目录中选择各式各样的产品。","mne":"cata向下 + log说 → 在下面要说的话 → catalog目录"},{"word":"catalogue","ipa":"/ˈkætəlɔːɡ/","pos":"n.","def":"目录","sen":"The girl got information about the clothes from the product catalogue.","trans":"女孩能从产品目录中得到关于衣服的信息。","mne":""},{"word":"catch","ipa":"/kætʃ/ ","pos":"v.","def":"接住；抓住；赶上","sen":"He is trying to catch this football.","trans":"他正试图接住这只足球。","mne":""},{"word":"cattle","ipa":"/ˈkætl/","pos":"n.","def":"（总称）牛，牲口","sen":"The cattle are eating grass on the grassland.","trans":"牛正在草地上吃草。","mne":""},{"word":"cause","ipa":"/kɔːz/","pos":"v.","def":"引起，导致，造成，使发生；  n.原因，理由；事业","sen":"Too much screen time may cause your eyes to feel tired.","trans":"长时间看屏幕会使眼睛疲劳。","mne":""},{"word":"caution","ipa":"/ˈkɔːʃ(ə)n/","pos":"n.","def":"警告；谨慎，小心；  v.劝……谨慎小心","sen":"The caution sign indicated that there's something dangerous ahead.","trans":"警告标志显示前方有危险。","mne":"caut=cautious小心 + ion名词后缀 → 小心，谨慎"},{"word":"cautious","ipa":"/ˈkɔːʃəs/","pos":"adj.","def":"小心的，谨慎的","sen":"The maid is very cautious about serving the empress. ","trans":"这个丫鬟在皇后面前非常谨慎。","mne":"caution小心 + ous表形容词  → 小心的，谨慎的"},{"word":"cave","ipa":"/keɪv/","pos":"n.","def":"山洞，洞穴","sen":"He went into the dark cave by himself.","trans":"他独自一人走进了漆黑的山洞。","mne":"cav洞 + e → cave山洞"},{"word":"cease","ipa":"/siːs/","pos":"v.","def":"停止，结束；  n.停止，停息","sen":"The rain ceased and the rainbow showed up.","trans":"雨停了，彩虹出现在天边。","mne":""},{"word":"ceiling","ipa":"/ˈsiːlɪŋ/","pos":"n.","def":"天花板","sen":"Look at my bright pink ceiling! It's so girly!","trans":"看我亮粉色的天花板！多么少女！","mne":"ceil装天花板 + ing名词后缀 → ceiling 天花板"},{"word":"celebrate","ipa":"/ˈselɪbreɪt/","pos":"v.","def":"庆祝，庆贺；赞美","sen":"We gathered with family to celebrate the New Year with a big dinner.","trans":"我们与家人团聚，共进丰盛的晚餐，以庆祝新年。","mne":"celebr庆祝 + ate表示做… → celebrate庆祝；歌颂"},{"word":"cell","ipa":"/sel/","pos":"n.","def":"细胞；单间牢房；【财】单元格","sen":"White blood cells help protect our body.","trans":"白细胞可以保护我们的身体。","mne":""},{"word":"census","ipa":"/ˈsensəs/","pos":"n.","def":"人口普查，人口调查","sen":"The government is taking a census. May I ask: how many people live here?","trans":"政府正在做人口普查。请问一下：这里住了多少人？","mne":"cens评估 + us表名词 → 查[人口] → 普查 → 人口普查"},{"word":"cent","ipa":"/sent/","pos":"n.","def":"分币；分","sen":"This coin is only worth one cent.","trans":"这枚硬币只值1美分。","mne":" "},{"word":"center","ipa":"/ˈsentər/","pos":"n.","def":"中央，中心","sen":"You'll get lots of points if you hit the center of the target.","trans":"如果击中目标的中心，你会得很高的分数。","mne":""},{"word":"centigrade","ipa":"/ˈsentɪɡreɪd/","pos":"adj.","def":"摄氏度的；  n.摄氏度","sen":"The flower grows well at 25 degrees centigrade.","trans":"花在25摄氏度的环境下生长得很好。\n","mne":"centi百 + grade级，度 → 百分度的"},{"word":"centimeter","ipa":"/ˈsentəˌmiːtɚ/","pos":"n.","def":"厘米（同centimetre）","sen":"This ruler measures objects in centimeters.","trans":"这把尺子以厘米为单位来测量物体。","mne":"centi百分之一 + meter计量，测量 → 用一米的百分之一来测量 → n.厘米(cm)"},{"word":"centimetre","ipa":"/ˈsentɪmiːtər/","pos":"n.","def":"厘米","sen":"One hundred centimetres is equal to one meter.","trans":"一百厘米等于一米。","mne":"centi一百 + meter米 → 100厘米为1米 → centimetre厘米"},{"word":"central","ipa":"/ˈsentrəl/","pos":"adj.","def":"中心的","sen":"We should all meet at a central point.","trans":"我们都应该去中心点那儿碰头。","mne":"centr中心 + al形容词后缀 → central中心的"},{"word":"centre","ipa":"/ˈsentər/","pos":"n.","def":"中心，中枢；中央（=center）；  v.把…放在中部","sen":"The centre of the target is red.","trans":"靶子的中心是红色的。","mne":""},{"word":"century","ipa":"/ˈsentʃəri/","pos":"n.","def":"世纪，百年","sen":"I think that 2012 is the greatest year of the 21st century so far.","trans":"我认为，到目前为止，2012年是21世纪最好的一年。","mne":""},{"word":"ceremony","ipa":"/ˈserəmoʊni/","pos":"n.","def":"典礼；仪式","sen":"The student was awarded her certificate during the graduation ceremony.","trans":"这位毕业生在毕业典礼上被授予毕业证书。","mne":""},{"word":"certain","ipa":"/ˈsɜːrtn/","pos":"adj.","def":"确定的；某一，某些，一定（量）的；某种，某个，特定的","sen":"He is certain that he saw a dragon.","trans":"他确信他看见了一条龙。","mne":"cert确实 + ain形容词后缀 → certain确实的，一定的"},{"word":"certainly","ipa":"/ˈsɜːrtnli/","pos":"adv.","def":"当然，没问题（用于回答）","sen":"I'm certainly not scared of him. ","trans":"我当然不怕他。","mne":"certain确实的 + ly…地 → certainly无疑，确定"},{"word":"certificate","ipa":"/sərˈtɪfɪkɪt/, /sərˈtɪfɪkeɪt/","pos":"n.","def":"合格证书，文凭；证明，证明书（读作/sərˈtɪfɪkɪt/）；证书；  v.给……发证书（读作/sərˈtɪfɪˌkeɪt/）","sen":"He passed the exam and got the certificate.","trans":"他通过了考试并获得了证书。","mne":"certify证明 + cate表名词 → certificate证件"},{"word":"chain","ipa":"/tʃeɪn/","pos":"n.","def":"链条；链子；连锁；  v.用链条拴住","sen":"The lady's bag with a chain is a popular fashion style.","trans":"这个带链条的女包是一种流行的时尚款式。","mne":""},{"word":"chair","ipa":"/tʃer/","pos":"n.","def":"椅子；主席（职位）","sen":"Sitting in the dentist's chair always fills me with fear.","trans":"坐在牙医的椅子上总是让我充满了恐惧。","mne":""},{"word":"chairman","ipa":"/ˈtʃermən/","pos":"n.","def":"主席，董事长；主持人","sen":"The man standing in the middle is the chairman of the board.","trans":"站在中间的那个人是董事会主席。","mne":"chair主席位 + man人 → chairman主席；议长"},{"word":"challenge","ipa":"/ˈtʃælɪndʒ/","pos":"n.","def":"挑战；质疑；  v.挑战；质疑","sen":"Walking on the tightrope is a big challenge for him.","trans":"走钢丝对他来说是个很大的挑战。","mne":""},{"word":"champion","ipa":"/ˈtʃæmpiən/","pos":"n.","def":"冠军，优胜者；拥护者，卫士；  v.拥护；保卫","sen":"The French football team became the champion of the 2018 World Cup!","trans":"法国足球队成为2018年世界杯冠军！","mne":""},{"word":"chance","ipa":"/tʃæns/","pos":"n.","def":"机会；可能性；风险，冒险","sen":"I have a chance to win the prize.","trans":"我有机会赢得这个奖品。","mne":""},{"word":"change","ipa":"/tʃeɪndʒ/","pos":"n.","def":"【化】变化；零钱；找回的零钱；  v.变化，改变","sen":"The pH change can affect the rate of the enzymatic reaction.","trans":"pH值的变化可以影响酶反应的速率。","mne":""},{"word":"channel","ipa":"/ˈtʃænl/","pos":"n.","def":"海峡；渠道，方法；频道；  v.引导","sen":"The English Channel is between France and England. ","trans":"英吉利海峡在英国和法国之间。","mne":"chann管道 + el表名词 → channel航道；渠道；频道"},{"word":"chapter","ipa":"/ˈtʃæptər/","pos":"n.","def":"章，回，篇","sen":"Please open your books to the first chapter.","trans":"请把书翻到第一章。","mne":""},{"word":"character","ipa":"/ˈkærəktər/","pos":"n.","def":"角色；性格；特点，特性，特征；字","sen":"She dressed up as a character from a classic fairy tale.","trans":"她打扮成了经典童话故事中的角色。","mne":""},{"word":"characterise","ipa":"/'kærɪktəˌraɪz/","pos":"v.","def":"刻画……的性格，表示……的特性","sen":"How would you characterise him? Is he a happy or sad person?","trans":"你觉得他的性格怎么样？他是一个快乐的人还是忧郁的人？","mne":"character特点 + ise动词后缀 → characterise 表现特性，刻画性格"},{"word":"characteristic","ipa":"/ˌkærəktəˈrɪstɪk/","pos":"n.","def":"特点，特征，特色；  adj.典型的；特有的","sen":"The main characteristic of an elephant is its long trunk.","trans":"大象最大的一个特点就是长鼻子。","mne":"character特点 + istic名词后缀 → characteristic特征，特色"},{"word":"characterize","ipa":"/ˈkærəktəraɪz/","pos":"v.","def":"描述……特性；使……具有特点","sen":"We characterized the style of this building as Gothic style.","trans":"我们描述这种建筑的风格为哥特式风格。","mne":"character性格，品质 + ize……化 → 成为…的特征，以…为特征；描绘(人或物)的特征，描述"},{"word":"charge","ipa":"/tʃɑːrdʒ/","pos":"v.","def":"充电，充值；收费；控告；  n.主管；掌管；费用","sen":"I finally plugged in my phone and let it charge.","trans":"我终于插上我的手机，让它充电了。","mne":""},{"word":"charming","ipa":"/ˈtʃɑːrmɪŋ/","pos":"adj.","def":"迷人的；有魅力的","sen":"The princess in that movie was very charming.","trans":"那部电影里的公主很迷人。","mne":""},{"word":"chart","ipa":"/tʃɑːrt/","pos":"n.","def":"图表，表格；  v.制成图表","sen":"This chart shows that annual sales have continued to rise.","trans":"这张图表显示年度销售额持续上升。","mne":""},{"word":"charter","ipa":"/ˈtʃɑːrtər/","pos":"n.","def":"宪章；  v.包，租（汽车等）","sen":"The American Constitution is a charter that outlines a system of government.","trans":"美国宪法是一个概述政府系统的章程。","mne":"chart纸板，图 + er表名词 → 纸上的东西 → charter契约"},{"word":"chase","ipa":"/tʃeɪs/","pos":"n.","def":"追逐","sen":"l know your time is valuable, so I'll just cut to the chase.","trans":"我知道你们时间宝贵，我就直说了。","mne":""},{"word":"chat","ipa":"/tʃæt/","pos":"n.","def":"闲谈，聊天；  v.闲谈，聊天","sen":"They usually have a chat while drinking coffee.","trans":"他们通常在喝咖啡时闲聊。","mne":""},{"word":"cheap","ipa":"/tʃiːp/","pos":"adj.","def":"便宜的，不贵的","sen":"You won't find cheaper carrots than this anywhere!","trans":"你再也找不到比这更便宜的胡萝卜了！","mne":""},{"word":"cheat","ipa":"/tʃiːt/","pos":"v.","def":"作弊；欺骗，哄骗；  n.骗子","sen":"The man cheated in the card game.","trans":"那个男人在打牌时作弊了。","mne":""},{"word":"check","ipa":"/tʃek/","pos":"n.","def":"检查；方格图案，格子，方格；支票（=cheque）；  v.核实，核对；抑制；查看，检查","sen":"You need to have a security check before boarding.","trans":"你在登机前需要进行安全检查。","mne":""},{"word":"cheer","ipa":"/tʃɪr/","pos":"v.","def":"欢呼；鼓劲，使振作；  n.鼓励，振奋；欢呼声，喝彩声","sen":"The sports fans cheered for their team.","trans":"球迷们为他们的球队加油喝彩。","mne":""},{"word":"cheerful","ipa":"/ˈtʃɪrfl/","pos":"adj.","def":"高兴的；令人愉快的","sen":"He has a big smile and looks so cheerful.","trans":"他有着灿烂的笑容且看起来非常快乐。","mne":"cheer欢乐 + ful形容词后缀 → cheerful快乐的"},{"word":"cheese","ipa":"/tʃiːz/","pos":"n.","def":"乳酪，干酪，芝士","sen":"I love eating cheese.","trans":"我喜欢吃奶酪。","mne":""},{"word":"chemical","ipa":"/ˈkemɪkl/","pos":"n.","def":"化学品，化学物质；  adj.化学的，与化学有关的","sen":"The scientist drew up some clear liquid chemical with a dropper.","trans":"科学家用滴管吸取了一些透明的液体化学物质。","mne":"chem化学 + ical……的 → chemical化学的"},{"word":"chemist","ipa":"/ˈkemɪst/","pos":"n.","def":"化学家；药剂师","sen":"The chemist is working in a lab.","trans":"化学家正在实验室里工作。","mne":"chem化学的 + ist表示人 → chemist化学家"},{"word":"chemistry","ipa":"/ˈkemɪstri/","pos":"n.","def":"化学","sen":"Children like to learn chemistry through experiments.","trans":"孩子们喜欢通过做实验学习化学。","mne":"chemist化学家 + ry表名词 → chemistry化学"},{"word":"cheque","ipa":"/tʃek/","pos":"n.","def":"支票","sen":"The boss is signing the cheque.","trans":"老板在开支票。","mne":""},{"word":"cherish","ipa":"/ˈtʃerɪʃ/","pos":"v.","def":"珍爱，珍视；怀有（感情）；抱有（希望）","sen":"I cherish my little darling.","trans":"我珍爱我的小宝贝。","mne":"cher=char可爱的 + ish表动词 → cherish珍爱"},{"word":"chest","ipa":"/tʃest/","pos":"n.","def":"胸膛，胸部；箱子","sen":"The doctor conducted a chest examination.","trans":"医生进行了胸部检查。","mne":""},{"word":"chicken","ipa":"/ˈtʃɪkɪn/","pos":"n.","def":"鸡肉；鸡","sen":"He cooked chicken for dinner.","trans":"他晚餐做了鸡肉。","mne":"chick小鸡 + en名词后缀 → chicken小鸡"},{"word":"chief","ipa":"/tʃiːf/","pos":"n.","def":"负责人，老板；长官；  adj.首席的，最高级别的；主要的","sen":"This man is the chief of the restaurant.","trans":"这个男人是餐厅的负责人。","mne":""},{"word":"child","ipa":"/tʃaɪld/","pos":"n.","def":"小孩，儿童","sen":"What a cute child!","trans":"好可爱的小朋友啊！","mne":""},{"word":"childhood","ipa":"/ˈtʃaɪldhʊd/","pos":"n.","def":"童年，幼年","sen":"They cherish the memories of their childhood spent playing outside.","trans":"他们珍惜童年在外面玩的时光。","mne":"child孩子 ＋ hood时期，性质 → childhood童年"},{"word":"childish","ipa":"/ˈtʃaɪldɪʃ/","pos":"adj.","def":"幼稚的，傻气的","sen":"Only a child can make such a childish thing.","trans":"只有小孩子才会做出这么幼稚的事情。","mne":"child孩子 + ish表形容词，“像…一样，有的…” → 像孩子一样的 → childish孩子气的"},{"word":"china","ipa":"/ˈtʃaɪnə/","pos":"n.","def":"瓷，瓷器","sen":"This is a beautiful china tea set with a teacup and a teapot.","trans":"这是一套漂亮的瓷茶具，有一个茶杯和一个茶壶。","mne":""},{"word":"chip","ipa":"/tʃɪp/","pos":"n.","def":"芯片；炸薯条，炸薯片；  v.使碎裂","sen":"Computer chips are essential for the technology industry.","trans":"电脑芯片对于科技行业至关重要。","mne":""},{"word":"chocolate","ipa":"/ˈtʃɑːk.lət/","pos":"n.","def":"巧克力","sen":"Yum-yum! This chocolate tastes really good!","trans":"好吃！这巧克力真好吃！","mne":""},{"word":"choice","ipa":"/tʃɔɪs/","pos":"n.","def":"选择，挑选，抉择；  adj.（尤指食物）精选的，上等的","sen":"It's hard for him to make a choice between new shoes and a new game console.","trans":"对他来说，在新鞋和新游戏机中做选择非常困难。","mne":""},{"word":"choose","ipa":"/tʃuːz/","pos":"v.","def":"选择，挑选","sen":"He's having a hard time choosing his milk tea flavor.","trans":"他选个奶茶口味选得好纠结。","mne":""},{"word":"chore","ipa":"/tʃɔːr/ ","pos":"n.","def":"日常家庭杂务，日常工作","sen":"Doing chores is a responsibility shared by all family members.","trans":"做家务是全家人共同的责任。","mne":""},{"word":"christian","ipa":"/ˈkrɪstʃən/","pos":"n.","def":"基督教徒；  adj.基督教的，基督教徒的","sen":"Everyone in this family is a Christian.","trans":"这一家人都是基督教徒。","mne":"Christ基督 + ian表人 → Christian基督教徒"},{"word":"christmas","ipa":"/ˈkrɪsməs/","pos":"n.","def":"圣诞节","sen":"Christmas is a traditional holiday in Western countries.","trans":"圣诞节是西方国家的传统节日。","mne":"Christ基督 + mas(s)圣餐 → 为纪念耶稣诞生吃圣餐 → Christmas圣诞节"},{"word":"church","ipa":"/tʃɜːrtʃ/","pos":"n.","def":"教堂","sen":"The church is located in a beautiful suburb.","trans":"教堂位于一处美丽的郊区。","mne":""},{"word":"cigar","ipa":"/sɪˈɡɑːr/","pos":"n.","def":"雪茄烟","sen":"I really don’t like the smell of cigars.","trans":"我真的很不喜欢雪茄的味道。","mne":""},{"word":"cigaret","ipa":"/ˌsɪgə'ret/","pos":"n.","def":"香烟","sen":"Cigarettes are bad for your health.","trans":"香烟对你的健康有害。","mne":""},{"word":"cigarette","ipa":"/ˈsɪɡəret/","pos":"n.","def":"香烟，纸烟，卷烟","sen":"Cigarettes are bad for your health.","trans":"香烟对你的健康有害。","mne":"cigar雪茄 + ette小的 → 比雪茄小 → cigarette香烟"},{"word":"cinema","ipa":"/ˈsɪnəmə/","pos":"n.","def":"电影院；电影，影片","sen":"The cinema has a massive screen.","trans":"这家影院有一个巨幕。","mne":"cine移动、电影 + ma表结果和产物 → cinema影院"},{"word":"circle","ipa":"/ˈsɜːrkl/","pos":"n.","def":"圆圈；  v.围绕；将...圈起来","sen":"We're running in circles.","trans":"我们在绕圈跑。","mne":"circ环 + le名词后缀 → circle圆圈"},{"word":"circuit","ipa":"/ˈsɜːrkɪt/","pos":"n.","def":"【化】电路，回路；环行；【物】电路；巡回","sen":"The circuit needs to be closed for the device to work properly.","trans":"设备需要在电路闭合的情况下正常工作。","mne":"circu圆，环 + it走 → 环行 → 环行；电路"},{"word":"circumstance","ipa":"/ˈsɜːrkəmstæns/","pos":"n.","def":"情况；环境","sen":"Under such circumstances, she can't focus on her work.","trans":"在这种情况下，她无法专心工作。","mne":"circum环绕 + stance站 → 站在周围 → circumstance环境，条件"},{"word":"citizen","ipa":"/ˈsɪtɪzn/","pos":"n.","def":"公民；市民；居民","sen":"I have become a Chinese citizen who has the right to vote after turning eighteen.","trans":"十八岁以后，我就成为一个享有选举权的中国公民了。","mne":"citiz=city城市 + en表名词 → citizen公民"},{"word":"city","ipa":"/ˈsɪti/","pos":"n.","def":"城市，都市","sen":"This is a big city with a large number of high-rise buildings.","trans":"这是一座有很多高层建筑的大城市。","mne":""},{"word":"civil","ipa":"/ˈsɪvl/","pos":"adj.","def":"民用的，公民的；国内的；文明的","sen":"A civil aircraft is used for taking passengers.","trans":"民用飞机用于载客。","mne":""},{"word":"civilisation","ipa":"/ˌsɪvələˈzeɪʃn/","pos":"n.","def":"文明（=civilization）；文化","sen":"Many relics from the ancient Egyptian civilisation have been discovered.","trans":"很多古埃及文明的遗迹都被发现了。","mne":"civil公民的 +isation=ization表名词→ [英]文明"},{"word":"civilization","ipa":"/ˌsɪvələˈzeɪʃn/","pos":"n.","def":"文明","sen":"Atlantis is a lost civilization.","trans":"亚特兰蒂斯是一个已经消失的文明。","mne":"civil市民；礼貌 + ization……化 → 文明，文化"},{"word":"claim","ipa":"/kleɪm/ ","pos":"n.","def":"索赔；主张；断言；  v.索赔","sen":"I want to make an insurance claim for the damage of my car.","trans":"我想为我的汽车遭受的损失提出保险索赔。","mne":""},{"word":"clap","ipa":"/klæp/","pos":"v.","def":"拍手，鼓掌，击掌；  n.拍手，鼓掌，掌声","sen":"The audience clapped for the amazing performance of the band.","trans":"听众们为乐队精彩的表演而鼓掌。","mne":""},{"word":"clarify","ipa":"/ˈklærəfaɪ/","pos":"v.","def":"阐明，澄清","sen":"During class the student clarified his ideas about the book.","trans":"在课堂上，这个学生阐明了自己关于这本书的看法。","mne":"clar清楚 + ify表动词 → clarify澄清，弄清"},{"word":"clash","ipa":"/klæʃ/","pos":"v.","def":"发生冲突；发出撞击声；  n.冲突","sen":"The couple clashed over who should wash the dishes.","trans":"这对情侣为谁该洗碗的问题发生了冲突。","mne":""},{"word":"class","ipa":"/klæs/","pos":"n.","def":"班级；课堂；课，上课；【计】类","sen":"Our class is going on a field trip next week.","trans":"我们班下周要去郊游。","mne":""},{"word":"classic","ipa":"/ˈklæsɪk/","pos":"adj.","def":"经典的；第一流的；典雅的，老式的；  n.经典著作；优秀典范","sen":"This is a classic scene in the movie “Titanic”.","trans":"这是电影\"泰坦尼克号\"里的经典场景。","mne":"class阶级 + ic表示人 → 高等阶级之人 → classic古典作家"},{"word":"classical","ipa":"/ˈklæsɪkl/","pos":"adj.","def":"古典的","sen":"I love classical music.","trans":"我热爱古典音乐。","mne":"classic典型的 + al形容词后缀 → classical古典的"},{"word":"classify","ipa":"/ˈklæsɪfaɪ/","pos":"v.","def":"把……分类","sen":"The color of the bin is what classifies the type of garbage.","trans":"垃圾箱的颜色可以区分垃圾的类型。","mne":"classi=class分类 + fy使成为... → 把...分类"},{"word":"classmate","ipa":"/ˈklæsmeɪt/","pos":"n.","def":"同班同学","sen":"All of my classmates are in this class photo.","trans":"我们全班同学都在这张班级照里。","mne":"class班级 + mate伙伴，同事 → classmate同班同学"},{"word":"classroom","ipa":"/ˈklæsruːm/","pos":"n.","def":"教室，课堂","sen":"Students can have lessons in classrooms.","trans":"学生们可以在教室里上课。","mne":"class班级 + room房间 → classroom教室"},{"word":"clause","ipa":"/klɔːz/","pos":"n.","def":"从句；条款","sen":"The sentence consists of a main clause and a subordinate clause.","trans":"这个句子包含一个主句和一个从句。","mne":""},{"word":"clean","ipa":"/kliːn/","pos":"v.","def":"打扫；使干净；  adj.清洁的，干净的","sen":"The man has been cleaning the house the whole afternoon.","trans":"这个男人一整个下午都在打扫房子。","mne":""},{"word":"cleaner","ipa":"/ˈkliːnər/","pos":"n.","def":"清洁工","sen":"The cleaner needs different tools to do her job.","trans":"清洁工需要用各种工具来完成工作。","mne":"clean清净 + er表人/物 → cleaner清洁工；干洗店"},{"word":"clear","ipa":"/klɪr/","pos":"adj.","def":"清楚的；明确的，澄清的；清澈的；  v.清除","sen":"Only one of these photos is clear.","trans":"这些照片中只有一张是清晰的。","mne":""},{"word":"clearly","ipa":"/ˈklɪrli/","pos":"adv.","def":"清楚地，明白地；显然地，明显地","sen":"I can see everything so clearly with my new glasses.","trans":"有了新眼镜，我能清楚地看到一切。","mne":""},{"word":"clerk","ipa":"/klɜːrk/","pos":"n.","def":"职员；店员","sen":"For many people, being a bank clerk is a stable and decent job.","trans":"对许多人来说，银行职员是一份稳定又体面的工作。","mne":""},{"word":"clever","ipa":"/ˈklevər/ ","pos":"adj.","def":"聪明的","sen":"This clever cat can tell items apart.","trans":"这只聪明的猫可以分辨不同的物品。","mne":""},{"word":"client","ipa":"/ˈklaɪənt/","pos":"n.","def":"委托人，当事人，客户","sen":"The architect is discussing the new design with his clients.","trans":"建筑师正在和他的委托人讨论新设计。","mne":""},{"word":"climate","ipa":"/ˈklaɪmət/","pos":"n.","def":"气候；（社会思想等的）趋势；风气","sen":"Climates differ from place to place, and from season to season.","trans":"气候随着地域和季节的不同而变化。","mne":"clim区域 + ate表名词  → 不同区域的气候  →climate气候"},{"word":"climb","ipa":"/klaɪm/","pos":"v.","def":"攀登，爬","sen":"I don't think I could climb that mountain.","trans":"我觉得我攀不上这座山。","mne":""},{"word":"clinic","ipa":"/ˈklɪnɪk/","pos":"n.","def":"诊所，门诊部","sen":"She took her dog to the animal clinic to see if he's sick.","trans":"她带她的狗去动物诊所，看看它是否生病了。","mne":""},{"word":"clock","ipa":"/klɑːk/","pos":"n.","def":"【数】时钟","sen":"At twelve o'clock the clock hands form a straight line.","trans":"十二点时时钟指针形成一条直线。","mne":""},{"word":"clockwise","ipa":"/ˈklɑːkwaɪz/","pos":"adj.","def":"顺时针方向的；  adv.顺时针方向地","sen":"The man is walking around the garden in a clockwise direction.","trans":"那个男人以顺时针方向在花园里散步。","mne":"clock时钟 + wise方向，状态 → clockwise顺时针的"},{"word":"close","ipa":"/kləʊz/","pos":"v.","def":"关闭，合上；  adj.亲密的；  adv.（空间或时间上）接近地，靠近地","sen":"The man is closing the door.","trans":"这个人正在关门。","mne":""},{"word":"cloth","ipa":"/klɔːθ/","pos":"n.","def":"（一块）布","sen":"The shop sells different kinds of cloth.","trans":"这家商店出售各式各样的布料。","mne":""},{"word":"clothe","ipa":"/kloʊð/","pos":"v.","def":"穿衣","sen":"The mum clothed the baby.","trans":"妈妈给宝宝穿上衣服。","mne":""},{"word":"clothes","ipa":"/kloʊðz/","pos":"n.","def":"衣服","sen":"I hung the clothes on the washing line.","trans":"我把衣服挂在了晾衣绳上。","mne":""},{"word":"cloud","ipa":"/klaʊd/","pos":"n.","def":"云，云朵","sen":"There was only one cloud in the middle of the blue sky.","trans":"蓝天中只有一朵云。","mne":""},{"word":"cloudy","ipa":"/ˈklaʊdi/","pos":"adj.","def":"多云的；（尿）浑浊的","sen":"It's cloudy today, so you can't see the sun.","trans":"今天多云，所以你看不见太阳。","mne":"cloud云 + y...的 → cloudy多云的"},{"word":"club","ipa":"/klʌb/","pos":"n.","def":"社团，俱乐部；  v.用棍棒打","sen":"You should join a club to do exercise.","trans":"你应该加入个俱乐部来进行锻炼。","mne":""},{"word":"clue","ipa":"/kluː/","pos":"n.","def":"线索；提示","sen":"The paw print is a big clue in the case.","trans":"爪印是此案的一个关键线索。","mne":""},{"word":"coach","ipa":"/koʊtʃ/","pos":"n.","def":"教练；长途汽车；旅客车厢；  v.训练，指导","sen":"The volleyball coach is talking to her team members.","trans":"这位排球教练正在和她的队员们交谈。","mne":""},{"word":"coal","ipa":"/koʊl/","pos":"n.","def":"煤","sen":"He is holding a few pieces of coal.","trans":"他正捧着几块煤。","mne":""},{"word":"coarse","ipa":"/kɔːrs/","pos":"adj.","def":"粗糙的；粗俗的；粗鲁的","sen":"Poor people used coarse cloth to make clothes in ancient China.","trans":"在中国古代，穷人用粗糙的布料制作衣服。","mne":""},{"word":"coast","ipa":"/koʊst/","pos":"n.","def":"海岸，海滨；  v.沿海航行","sen":"The view of the coast is amazing.","trans":"这片海岸的景色棒极了。","mne":""},{"word":"coastal","ipa":"/ˈkoʊstl/","pos":"adj.","def":"海岸的","sen":"This coastal road has wonderful views of the mountains and the sea.","trans":"在这条沿海公路上可以看到美丽的山海景色。","mne":"coast海岸 + al...的 → coastal海岸的"},{"word":"coat","ipa":"/koʊt/","pos":"n.","def":"大衣；  v.覆盖","sen":"The coat lining is detachable? That's perfect for our variable climate!","trans":"大衣内衬可拆卸？太适合多变天气了！","mne":""},{"word":"cock","ipa":"/kɑːk/","pos":"n.","def":"公鸡","sen":"The cock has a beautiful tail.","trans":"这只公鸡的尾巴很漂亮。","mne":""},{"word":"code","ipa":"/koʊd/","pos":"n.","def":"编码，代码；规范，准则；法典","sen":"The programmer is writing code for the new software on his computer.","trans":"这位程序员正在电脑上为一款新软件写代码。","mne":""},{"word":"coffee","ipa":"/ˈkɔːfi/","pos":"n.","def":"咖啡","sen":"Coffee is a drink made with water and ground coffee beans.","trans":"咖啡是用水和磨碎的咖啡豆制成的饮料。","mne":""},{"word":"cognition","ipa":"/kɑːɡˈnɪʃən/","pos":"n.","def":"认知；认识","sen":"Developing moral cognition is as important as acquiring knowledge.","trans":"建立道德认知与获取知识一样重要。","mne":""},{"word":"cognitive","ipa":"/ˈkɑːɡnətɪv/","pos":"adj.","def":"认知的","sen":"This test will assess your cognitive skills and ability to think quickly.","trans":"这个测试可以评估你的认知能力和反应能力。","mne":"cogn知道 + itive…的 → cognitive认识的"},{"word":"coherent","ipa":"/koʊˈhɪrənt/","pos":"adj.","def":"清楚易懂的；条理清楚的，有条理的","sen":"The woman uses different graphs to make her presentation coherent.","trans":"这个女人用不同的图表使她的演讲清楚易懂。","mne":"co共同 + her粘附 + ent……的 → 共同粘附的 → coherent连贯的；有条理的"},{"word":"coin","ipa":"/kɔɪn/","pos":"n.","def":"硬币；  v.铸造（硬币）；创造","sen":"This coin is worth ten cents.","trans":"这枚硬币值10美分。","mne":""},{"word":"cold","ipa":"/koʊld/","pos":"n.","def":"寒冷；感冒，伤风；  adj.寒冷的","sen":"His face turned red in the cold.","trans":"他的脸在寒冷中冻得发红。","mne":""},{"word":"collar","ipa":"/ˈkɑːlər/","pos":"n.","def":"衣领；  v.抓住；为……戴上项圈，为……上领子","sen":"The collar of this shirt is too tight.","trans":"这件衬衣的衣领太紧了。","mne":"coll脖子 + ar名词后缀 → collar衣领"},{"word":"colleague","ipa":"/ˈkɑːliːɡ/","pos":"n.","def":"同事","sen":"I really learned a lot by discussing with my colleagues.","trans":"通过和同事们讨论，我真的学到了很多。","mne":"col共同 + league捆绑 → 捆绑在一起的人 → colleague同事"},{"word":"collect","ipa":"/kəˈlekt/","pos":"v.","def":"收集，采集；领取","sen":"I like collecting old stamps.","trans":"我喜欢收集旧邮票。","mne":"col共同 + lect收 → collect收集"},{"word":"collection","ipa":"/kəˈlekʃən/","pos":"n.","def":"收藏，收藏品","sen":"I own a very valuable collection of guitars.","trans":"我拥有一些很有价值的吉他珍藏。","mne":"collect收集 + ion名词后缀 → collection采集，收藏"},{"word":"collective","ipa":"/kəˈlɛktɪv/","pos":"adj.","def":"集体的，共同的；【财】共同的；  n.集体","sen":"Class fund is collective property. It needs everybody to contribute.","trans":"班费是集体财产，它需要每个人的贡献。","mne":"col一起 + lect选择，收集 + ive……的 → 集中到一起 → 集体的"},{"word":"college","ipa":"/ˈkɑːlɪdʒ/","pos":"n.","def":"学院；大学","sen":"Students are gathering in front of the college building. ","trans":"学生们聚集在学院大楼前。","mne":"col=com一起，与 + leg选择，收集 + e → 一起做研究工作的师生 → college大学"},{"word":"colony","ipa":"/ˈkɑːləni/","pos":"n.","def":"殖民地","sen":"A colony on another planet might look like this!","trans":"在另一个星球，殖民地可能是这样的！","mne":""},{"word":"color","ipa":"/ˈkʌlər/","pos":"n.","def":"颜色（=colour）","sen":"We are in different colors.","trans":"我们有着不同的颜色。","mne":""},{"word":"colorful","ipa":"/ˈkʌlərfl/","pos":"adj.","def":"多彩的，华美的，色彩的","sen":"These eggs are so colorful.","trans":"这些蛋真是多彩。","mne":"color色彩 ＋ ful...的 → colorful多彩的，色彩的"},{"word":"colour","ipa":"/ˈkʌlər/","pos":"n.","def":"颜色（=color），涂色；  v.给……着色","sen":"I like to paint with different colours.","trans":"我喜欢用不同的色彩画画。","mne":""},{"word":"colourful","ipa":"/ˈkʌlərfl/","pos":"adj.","def":"丰富多彩的（=colorful）","sen":"Compared with her brother's painting, hers is more colourful.","trans":"和她弟弟的画相比，她的画色彩更丰富。","mne":""},{"word":"column","ipa":"/ˈkɑləm/","pos":"n.","def":"柱，支柱，圆柱；栏，专栏；列","sen":"Only a few columns of the old building are still standing.","trans":"这栋老建筑只有几根柱子还立在那儿。","mne":"col顶部 + u + mn名词后缀 → 突出顶部的物体 → column柱，栏"},{"word":"comb","ipa":"/koʊm/","pos":"n.","def":"梳子；  v.梳（头发）","sen":"This monster became a red comb after being defeated.","trans":"女妖结罗被犬夜叉和戈薇击败后变成了一把红色的梳子。","mne":""},{"word":"combat","ipa":"/ˈkɑmbæt/, /kəmˈbæt/","pos":"n.","def":"战斗，格斗；  v.与……战斗，与……斗争（读作/kəmˈbæt/）；防止，抑制","sen":"The two servants were in combat all night for their master.","trans":"骑士王和枪哥为了他们的主人彻夜战斗。","mne":"com共同，对抗之意 + bat打 → 一起对打 → combat战斗"},{"word":"combination","ipa":"/ˌkɑːmbɪˈneɪʃn/","pos":"n.","def":"结合，联合","sen":"Fried chicken plus cold beer is a perfect combination on a snowy day.","trans":"下雪天，炸鸡和啤酒真是完美的搭配。","mne":"com共同 + bin=bine藤蔓 + ation表名词 → combination结合，联合"},{"word":"combine","ipa":"/kəmˈbaɪn/, /ˈkɑmˌbaɪn/","pos":"v.","def":"混合，联合；（使）结合","sen":"Combine yellow and blue, and you will get green.","trans":"把黄色和蓝色混合起来，你就会得到绿色。","mne":"com与...一起 + bin成对地 + e → combine联合"},{"word":"come","ipa":"/kʌm/","pos":"v.","def":"来，来到","sen":"Will he come to your home with Christmas gifts?","trans":"他会带着圣诞礼物来你家么？","mne":""},{"word":"comedy","ipa":"/ˈkɑːmədi/ ","pos":"n.","def":"喜剧，喜剧片，滑稽节目","sen":"This TV comedy show makes people laugh a lot.","trans":"这个电视喜剧节目引人发笑。","mne":"com宴会 + edy表名词 → 像宴会一样热闹 → comedy喜剧"},{"word":"comfort","ipa":"/ˈkʌmfərt/","pos":"n.","def":"舒适；安慰；  v.使舒适","sen":"Ah! The level of comfort of this chair is amazing.","trans":"啊！这张椅子的舒适度真是太棒了。","mne":"com共同 + fort加强 → 精神强大 → comfort安慰"},{"word":"comfortable","ipa":"/ˈkʌmfərtəbl/","pos":"adj.","def":"舒适的，舒服的","sen":"The man looked so comfortable lying in the chair.","trans":"这个男人躺在椅子上，看起来非常舒适。","mne":"com共同 + fort强大，力量 + able能…的 → comfortable愉快舒适的"},{"word":"command","ipa":"/kəˈmænd/","pos":"v.","def":"值得，博得；命令；指挥，统率；掌管，控制；  n.命令；控制","sen":"His good performance commands our praise. ","trans":"他表现得好，值得表扬。","mne":"com一起 + mand命令 → 命令大家一起做 → command指挥，命令"},{"word":"commander","ipa":"/kəˈmændər/","pos":"n.","def":"司令官，指挥官","sen":"The commander was thinking about possible strategies.","trans":"指挥官在思考下一步可行的策略。","mne":"com共同 + mand命令 + er表示做某事的人 → n.司令官，指挥员"},{"word":"comment","ipa":"/ˈkɑːment/","pos":"n.","def":"评论，意见；批评，指责；意见；批评；  v.评论","sen":"Some of my friends left me comments.","trans":"我的一些朋友给我评论了。","mne":"com共同 + ment思考，神智 → 共同思考 → 评论"},{"word":"commerce","ipa":"/ˈkɑːmɜːrs/","pos":"n.","def":"商业，贸易","sen":"Online platforms have completely changed the mode of commerce.\n","trans":"在线平台已经彻底改变了商业模式。","mne":"com共同 ＋ merce交易 → 共同交易 → commerce商业"},{"word":"commercial","ipa":"/kəˈmɜːrʃl/","pos":"n.","def":"商业广告；  adj.贸易的；商业的","sen":"The kids are watching a TV commercial of fast food.","trans":"孩子们正在看快餐的电视广告。","mne":"com共同 + merc交易 + ial...的 → 共同交易的 → 商业的"},{"word":"commercialise","ipa":"/kə'mɜːʃəlaɪz/","pos":"v.","def":"使商业化","sen":"The farmer decided to commercialise her homemade jam and sell it in the supermarket.","trans":"那位农民决定将她自制的果酱商业化，并在超市里销售。","mne":""},{"word":"commercialize","ipa":"/kəˈmɜːrʃəlaɪz/","pos":"v.","def":"使商业化，使商品化","sen":"Endorsing a product such as perfume can finally commercialize the model's personal image.","trans":"代言一种产品（如香水）最终可以商业化模特的个人形象。","mne":"com 共同 + merci=merc交易 + al...的 + ize 使... → vt. 使商业化；使商品化"},{"word":"commission","ipa":"/kəˈmɪʃn/","pos":"n.","def":"委员会；佣金；  v.正式委托（谱写、制作等）；委任","sen":"The State Health Care Commission meets once every month to make policy.","trans":"州立卫生保健委员会每个月都会碰一次头来制定政策。","mne":"com共同 + miss送 + ion名词后缀 → 共同选出的人 → commission委员会"},{"word":"commit","ipa":"/kəˈmɪt/","pos":"v.","def":"犯（罪）；进行 (自杀)；承诺","sen":"The fox committed a crime and was sent to prison.","trans":"狐狸犯了罪，并被抓进了监狱。","mne":"com一起 + mit释放，抛出 → 某种行为的宣泄 → commit承诺，自杀"},{"word":"commitment","ipa":"/kəˈmɪtmənt/","pos":"n.","def":"承诺，许诺；信奉；奉献，献身","sen":"They made a commitment to each other at their wedding ceremony.","trans":"在婚礼上，他们相互做出承诺。","mne":"commit承诺 + ment名词后缀 → commitment承诺"},{"word":"committee","ipa":"/kəˈmɪti/","pos":"n.","def":"委员会；全体委员","sen":"The committee members come to the meeting to make decisions for the group they represent.","trans":"委员会成员们代表着他们各自的组织来开会做决议。","mne":"com集合，团结 + mitt(mittere)解放 + ee名词后缀，受动者 → committee委员会"},{"word":"commodity","ipa":"/kəˈmɑːdəti/","pos":"n.","def":"商品，货物","sen":"You can find many commodities in supermarkets.","trans":"你可以在超市看到各种各样的商品。","mne":"com共同 + mod方式，模式，风度 + ity名词后缀 → 有共同模式的东西 → 商品"},{"word":"common","ipa":"/ˈkɑːmən/","pos":"adj.","def":"一般的，常见的；普通的","sen":"It is common to see people take a bicycle to work.","trans":"经常能看到人们骑自行车去上班。","mne":"com一起 + mon改变；去 → 所有人都共享的 → common普通的"},{"word":"communicate","ipa":"/kəˈmjuːnɪkeɪt/","pos":"v.","def":"沟通，交流；传达，传递","sen":"The police communicate with each other by radio.","trans":"警察通过无线电进行沟通。","mne":"com共同 + muni交流 + cate表动词 → 共同交流 → 传播"},{"word":"communication","ipa":"/kəˌmjuːnɪˈkeɪʃn/","pos":"n.","def":"通信，交流","sen":"They like to use cell phones for communication.","trans":"他们喜欢用手机来交流。","mne":"communi通常，一般 + cation名词后缀 → 共同的事物 → communication通信，交流"},{"word":"community","ipa":"/kəˈmjuːnəti/ ","pos":"n.","def":"群体，团体；社区","sen":"The largest Chinese community in this city lives in its Chinatown.","trans":"这个城市最大的华人社区居住在其唐人街。","mne":"com共同 + mun公共的 + ity状态 → 公共状态 → community社区"},{"word":"commute","ipa":"/kəˈmjuːt/","pos":"v.","def":"通勤；  n.通勤，在两地之间乘车往返","sen":"If I didn't have to commute two hours every day, I'd have so much more time for vlogging!","trans":"如果我每天不用通勤两个小时，我就会有更多时间来做 vlog 了！","mne":"com和，一起 + mute改变 -> commute两地往返"},{"word":"compact","ipa":"/kəmˈpækt/, /ˈkɑmˌpækt/","pos":"adj.","def":"紧凑的，密集的；  n.合约，条约","sen":"The room is compact but well-equipped.","trans":"这个房间虽然布局紧凑，但设施一应俱全。","mne":"com共同 + pact压紧 → 全部压紧 → compact紧密的"},{"word":"companion","ipa":"/kəmˈpænjən/","pos":"n.","def":"同伴；伴侣","sen":"Dogs are good companions.","trans":"狗狗是很好的伙伴。","mne":"com共同 + panion面包 → 吃一条面包的 → companion同伴"},{"word":"company","ipa":"/ˈkʌmpəni/ ","pos":"n.","def":"陪伴；公司","sen":"The little girl smiled in her father's company.","trans":"她在父亲的陪伴下笑了。\n","mne":"com一起 + pany面包 → 一起吃面包 → company陪伴"},{"word":"comparable","ipa":"/ˈkɑːmpərəbl/","pos":"adj.","def":"类似的，比得上的，可比较的","sen":"The two dogs are comparable in size and strength.","trans":"这两条狗在大小和强壮程度方面都不相上下。","mne":"compar=compare比较，对照 + able形容词后缀，可……的 → (to)比得上的；(with)可比较的,类似的"},{"word":"comparative","ipa":"/kəmˈpærətɪv/","pos":"adj.","def":"【财】比较的","sen":"The performance measures chosen by local authorities usually consist of comparative statistics and unit \ncosts.","trans":"地方当局选择的绩效衡量标准通常包括比较统计数据和单位成本。","mne":"com共同 + par看见 + ative...的 → 看见共同之处的 → comparative比较的"},{"word":"compare","ipa":"/kəmˈper/","pos":"v.","def":"与……相比较；将……比作； 比较；对比","sen":"It's smart to compare products when you go shopping.","trans":"当你购物时，比较一下商品是很明智的。","mne":"com共同 + pare=par平等 → 平等放在一起 → compare对照；比较"},{"word":"comparison","ipa":"/kəmˈpærɪsn/","pos":"n.","def":"比较；对比","sen":"I made a comparison between the two houses.","trans":"我将这两栋房子做了比较。","mne":"compar=compare比较 + ison表名词 → comparison比较"},{"word":"compass","ipa":"/ˈkʌmpəs/","pos":"n.","def":"指南针；罗盘","sen":"When you lose your way, you can use a compass.","trans":"当你迷路时，你可以使用指南针。","mne":"com一起，共同 + pass传播，走 → compass指南针"},{"word":"compatible","ipa":"/kəmˈpætəbl/","pos":"adj.","def":"合得来的；兼容的","sen":"He is compatible with his friend because of their similar interests and opinions.","trans":"他和他的朋友很合得来，因为他们有相似的兴趣和观点。","mne":"com共同+pat感情+ible能...的→有共同感情的→相容的"},{"word":"compel","ipa":"/kəmˈpel/","pos":"v.","def":"强迫","sen":"He was compelled to stay in the circle.","trans":"他被迫待在一个圆圈里。","mne":"com共同 + pel推 → 一起推 → 强迫"},{"word":"compensate","ipa":"/ˈkɑːmpenseɪt/","pos":"v.","def":"补偿，赔偿；弥补","sen":"He should be compensated for his work-related injury.","trans":"他应该得到工伤赔偿。","mne":"com全部 + pens花费 + ate动词后缀 → 花费的钱全部拿回来 → 赔偿"},{"word":"compensation","ipa":"/ˌkɑmpənˈseɪʃən/","pos":"n.","def":"赔偿金；补偿；补偿，报酬，赔偿金","sen":"The injured man received his compensation from the insurance agent.","trans":"那个受伤的人收到了保险代理人的赔偿金。","mne":""},{"word":"compete","ipa":"/kəmˈpiːt/ ","pos":"v.","def":"竞争；参加比赛（或竞赛）","sen":"We compete against each other to see who's the fastest rider.","trans":"我们相互竞争，想看看谁才是最快的骑手。","mne":"com共同 + pete追求 → 一起追 → compete比赛"},{"word":"competent","ipa":"/ˈkɑːmpɪtənt/","pos":"adj.","def":"有能力的；能胜任的","sen":"She's a competent worker and is good at her job.","trans":"她是一个有能力的员工，并且擅长她的工作。","mne":"com共同 + pet追寻，寻求 + ent……的 → competent有资格的"},{"word":"competition","ipa":"/ˌkɑːmpəˈtɪʃn/ ","pos":"n.","def":"比赛，竞赛；竞争者","sen":"Who is going to win this competition?","trans":"谁将赢得这场比赛呢？","mne":"compet=compete竞争 + ition名词后缀 → competition比赛"},{"word":"competitive","ipa":"/kəmˈpetətɪv/","pos":"adj.","def":"【化】竞争的；有竞争力的","sen":"In competitive inhibition, an inhibitor binds to the active site of the enzyme.","trans":"在竞争性抑制中，抑制剂与酶的活性位点结合。","mne":"compet=compete竞争 + itive..的 → competitive有竞争力的；竞争的"},{"word":"competitor","ipa":"/kəmˈpetɪtər/","pos":"n.","def":"参赛者","sen":"Over 3000 competitors entered the race.","trans":"3000多名参赛者参加了跑步比赛。","mne":"com共同 + pet追求 + itor人 → competitor比赛者"},{"word":"complacent","ipa":"/kəmˈpleɪsənt/","pos":"adj.","def":"自满的，得意的","sen":"The complacent driver is too confident and hasn't noticed the danger on the icy road.","trans":"这个自以为是的司机太自信了，并没意识到在结冰的路上驾驶的危险。","mne":"com加强语气 + plac使满意 + ent形容词后缀 → 被取悦 → complacent自满的"},{"word":"complain","ipa":"/kəmˈpleɪn/","pos":"v.","def":"抱怨，发牢骚；投诉","sen":"The man complained about his neighbors being too noisy.","trans":"这个男人抱怨他的邻居太吵。","mne":"com共同 + plain抱怨 → 抱怨，诉苦；控告"},{"word":"complaint","ipa":"/kəmˈpleɪnt/","pos":"n.","def":"怨言，投诉；抱怨","sen":"The customer made a complaint to the manager.","trans":"顾客向经理投诉。","mne":"com全部 + plaint抱怨 → 对全部东西抱怨 → complaint抱怨"},{"word":"complete","ipa":"/kəmˈpliːt/","pos":"adj.","def":"完整的；  v.完成","sen":"Finally, the puzzle is complete.","trans":"最终，拼图完整了。","mne":"com全部 + plete满 → 全满 → complete完全的"},{"word":"completely","ipa":"/kəmˈpliːtli/","pos":"adv.","def":"完全地","sen":"My hair is completely gone.","trans":"我的头发全没了。","mne":"com共同 + plete=plet满，填满 + ly……地 → adv.完全地，彻底地；完整地"},{"word":"complex","ipa":"/kəmˈpleks/","pos":"adj.","def":"复杂的，难解的；复合的（读作/kɑmˈplɛks/）；  n.情结；综合体，集合体（读作/ˈkɒmpleks/）","sen":"He has no clue about how to solve this complex case.","trans":"他对如何解决这个复杂的案件毫无头绪。","mne":"com共同 + plex重叠 → 全部重叠 → complex复杂的"},{"word":"complicate","ipa":"/ˈkɑːmplɪkeɪt/","pos":"v.","def":"（使）变复杂","sen":"He always tended to complicate simple matters.","trans":"他总喜欢把简单的问题复杂化。","mne":"com全部 + plic重叠，折叠 + ate使 → 全部重叠起来 → complicate弄复杂"},{"word":"complicated","ipa":"/ˈkɑːmplɪkeɪtɪd/","pos":"adj.","def":"复杂的","sen":"Math is a very complicated subject—it makes my head hurt.","trans":"数学是一门非常复杂的学科，它让我很头疼。","mne":""},{"word":"comply","ipa":"/kəmˈplaɪ/","pos":"v.","def":"遵守，依从，服从","sen":"We should comply with traffic regulations.","trans":"我们应该遵守交通规则。","mne":"com共同 + ply重叠，折叠 → [观点]共同叠在一起 → 同意，答应"},{"word":"component","ipa":"/kəmˈpoʊnənt/","pos":"n.","def":"成分；零件，组成部分；  adj.组成的","sen":"Each vaccine contains an active component that stimulates the immune response.","trans":"每种疫苗都含有能激发免疫反应的活性成分。","mne":"com共同 + pon放 + ent名词后缀 → 放到一起的东西 → component成分"},{"word":"compose","ipa":"/kəmˈpoʊz/","pos":"v.","def":"创作；使平静；组成","sen":"The man composes new songs on his keyboard.","trans":"这位男士在他的键盘上创作新歌。","mne":"com一起 + pose放 → compose组成，构成；创作"},{"word":"composer","ipa":"/kəmˈpoʊzər/","pos":"n.","def":"作曲家","sen":"The composer has difficulty writing this piece.","trans":"作曲家在写这首曲子时遇到了困难。","mne":"compos(e)创作 + er名词后缀：人 → composer作家，作曲家"},{"word":"composition","ipa":"/ˌkɑːmpəˈzɪʃ(ə)n/","pos":"n.","def":"作品；构成，组成，成分","sen":"Beethoven's compositions are great works.","trans":"贝多芬的作曲是伟大的作品。","mne":"com一起 + posit放 + ion名词后缀 → 放到一起 → 组合 → composition创作、作文"},{"word":"compound","ipa":"/ˈkɑːmpaʊnd/, /kəmˈpaʊnd/","pos":"n.","def":"【化学】化合物；复合物；  adj.合成的；复合的；多功能的（读作/ˈkɑːmpaʊnd/）","sen":"The science teacher is teaching about chemical compounds.","trans":"理科老师正在课堂上讲化学化合物。","mne":"com一起 + pound放 → compound 混合物"},{"word":"comprehend","ipa":"/ˌkɑːmprɪˈhend/","pos":"v.","def":"了解；理解；领会；包含","sen":"I like my teacher because she makes difficult ideas easier to comprehend.","trans":"我喜欢我的老师，因为她把复杂的概念变得简单易懂。","mne":"com全部 + prehend抓住 → 全部抓住 → comprehend理解"},{"word":"comprehension","ipa":"/ˌkɑːmprɪˈhenʃn/","pos":"n.","def":"理解力；测试","sen":"The two guys must have a high level of comprehension to understand this picture.","trans":"这俩人肯定具有高水平的理解能力，所以才能看懂这幅画。","mne":"com全部 + prehens抓住 + ion名词后缀 → 全部抓住 → comprehension理解"},{"word":"comprehensive","ipa":"/ˌkɑːmprɪˈhensɪv/","pos":"adj.","def":"全面的，完整的；详尽的；广泛的，无所不包的；广义的；综合的","sen":"She's making a comprehensive consideration of all her options.","trans":"她正在全面考虑她所有的选择。","mne":"comprehens理解 + ive形容词后缀 → comprehensive有理解力的；综合的"},{"word":"compress","ipa":"/kəmˈpres/, /ˈkɑmˌpres/","pos":"v.","def":"压缩；压紧，压缩，压榨（读作/kəmˈpres/）；  n.（止血、减痛等的）敷布，压布（读作/ˈkɑmˌpres/）","sen":"The band decided to compress their tracks for a punchier sound.","trans":"这个乐队决定压缩他们的音轨以获得更有力的声音。","mne":"com共同 + press压 → 一起压 → compress压缩"},{"word":"comprise","ipa":"/kəmˈpraɪz/","pos":"v.","def":"构成，由……组成","sen":"These animals comprise most of the cat family.","trans":"这些动物构成了猫科动物的大部分。","mne":"com全部 + prise拿住，抓住 → 全部抓住 → comprise包括，含有"},{"word":"compromise","ipa":"/ˈkɑːmprəˌmaɪz/","pos":"n.","def":"妥协，折中","sen":"The seller made a compromise and sold the dress at 50 yuan.","trans":"卖方做出了妥协，以50元的价格卖出了那条裙子。","mne":"com共同 + pro前面 + mise送，放出 → 共同承诺、遵守一项决定 → 妥协，和解"},{"word":"compute","ipa":"/kəmˈpjuːt/","pos":"v.","def":"计算，估计；【数】计算，运算","sen":"I like using a calculator to compute.","trans":"我喜欢用计算器来计算。","mne":"com一起 + pute计算，思考 → 算在一起 → compute计算，估算"},{"word":"computer","ipa":"/kəmˈpjutər/","pos":"n.","def":"【计】计算机；计算机，电脑","sen":"The computer's hostname and IP address are retrieved using the socket module in Python.","trans":"使用Python的socket模块获取计算机的主机名和IP地址。","mne":"com一起 + pute估计，精简 + r → 通过计算确定 → computer计算机，电脑"},{"word":"conceal","ipa":"/kənˈsiːl/","pos":"v.","def":"隐藏，隐瞒；【财】隐瞒","sen":"I use this mask to conceal my face.","trans":"我用面具来隐藏我的脸。","mne":"con加强 + ceal隐藏 → conceal隐埋，掩盖"},{"word":"concentrate","ipa":"/ˈkɑːnsntreɪt/","pos":"v.","def":"全神贯注于；浓缩；  n.浓缩物","sen":"He is concentrating on making his bread look perfect.","trans":"他正在专心地使面包看起来完美。","mne":"con共同 + centr中心 + ate动词后缀 → 都在中心 → concentrate集中；浓缩"},{"word":"concentration","ipa":"/ˌkɑːnsnˈtreɪʃn/","pos":"n.","def":"专注；聚集；浓度","sen":"Repairing watches requires a great deal of concentration.","trans":"修理手表需要注意力非常集中。","mne":"con共同 + centr中心 + ation后缀 → 都在中心 → concentration集中；浓缩"},{"word":"concept","ipa":"/ˈkɑːnsept/","pos":"n.","def":"概念；想法；观念","sen":"Copernicus presented a new concept regarding the solar system.","trans":"哥白尼提出了一个有关太阳系的新概念。","mne":"con共同 + cept掌握 → 能共同掌握的 → 概念，设计"},{"word":"concern","ipa":"/kənˈsɜːrn/","pos":"n.","def":"关心，关切；  v.感兴趣","sen":"Hair loss is a real concern for her.","trans":"脱发的确是她所担忧的问题。","mne":"con表强调 + cern区别 → 区分开，只关心自己的部分 → concern关系到"},{"word":"concerning","ipa":"/kənˈsɜːrnɪŋ/","pos":"prep.","def":"关于","sen":"The book gives lots of useful information concerning Botany.","trans":"这本书介绍了许多关于植物学的有用信息。","mne":"con共同 ＋ cern搞清 ＋ ing构成介词 → concerning关于"},{"word":"concert","ipa":"/ˈkɑnsərt/, /kənˈsɜrt/","pos":"n.","def":"音乐会，演奏会","sen":"I went to the concert. It was awesome.","trans":"我去了那场音乐会。真的棒极了。","mne":"con一起 + cert歌唱 → 一起歌唱 → concert音乐会"},{"word":"conclude","ipa":"/kənˈkluːd/","pos":"v.","def":"推断出；得出结论；使结束，终止","sen":"The doctor concluded that she was not seriously ill, but just caught a cold. ","trans":"医生推断她没什么大病，只是感冒了而已。","mne":"con共同 + clude关闭 → 全部关闭 → conclude结束，总结"},{"word":"conclusion","ipa":"/kənˈkluːʒn/","pos":"n.","def":"结论，推论；结束，结局","sen":"She drew a conclusion from these facts.","trans":"她终于从这些事实中得出了一条结论。","mne":"conclu表示结束 + sion为名词后缀 → conclusion结论；结束"},{"word":"conclusive","ipa":"/kənˈkluːsɪv/","pos":"adj.","def":"决定性的，无争论余地的","sen":"The fingerprint is conclusive evidence that he is the criminal.","trans":"指纹是证明他是罪犯的决定性证据。","mne":"con全部 + clus关闭 + ive……的 → conclusive结论性的"},{"word":"concrete","ipa":"/ˈkɑːnkriːt/","pos":"n.","def":"混凝土；  adj.具体的；  v.给 (道路等) 浇混凝土","sen":"The workers are mixing the concrete together.","trans":"工人们正在把混凝土搅拌在一起。","mne":"con共同 + crete=cre制造 → 共同制造 → concrete混凝土"},{"word":"condemn","ipa":"/kənˈdem/","pos":"v.","def":"谴责，责备；判（某人某罪）","sen":"People condemned the thief for stealing from the supermarket.","trans":"人们谴责这个超市偷东西的小偷。","mne":"con表强调 + demn伤害，破坏 → condemn谴责"},{"word":"condition","ipa":"/kənˈdɪʃən/","pos":"n.","def":"环境，形势；状况，状态；条件；  v.使适应，使处于良好状态","sen":"The living conditions here are really poor.","trans":"这儿的生活条件真的很差。","mne":"con和，一起 + dit说 +ion名词后缀 → condition状况，形势"},{"word":"conduct","ipa":"/kənˈdʌkt/, /ˈkɑnˌdʌkt/","pos":"v.","def":"指挥；传导；进行；  n.行为；引导（读作/ˈkɑnˌdʌkt/）","sen":"He is conducting an orchestra.","trans":"他正指挥着一支交响乐团。","mne":"con共同 + duct引导，带来 → 引导大家一起做→conduct指挥"},{"word":"conductor","ipa":"/kənˈdʌktər/","pos":"n.","def":"指挥；售票员；导体","sen":"The conductor is leading the band.","trans":"乐队指挥正在指挥乐队。","mne":"con共同 + duct引导，带来 + or表名词，人 → 引导大家共同做事情的人 → conductor指挥家"},{"word":"conference","ipa":"/ˈkɑːnfərəns/","pos":"n.","def":"会议；讨论会","sen":"He is delivering his speech at the pet owners' conference.","trans":"他正在宠物主人会议上发表演讲。","mne":"con共同 + fer承担 + ence名词后缀 → 共同商议承担 → conference会议"},{"word":"confess","ipa":"/kənˈfes/","pos":"v.","def":"（向神父或上帝）忏悔；承认，坦白","sen":"Father, I'm here to confess all my sins.","trans":"神父，我在此忏悔我所有的罪行。","mne":"con全部 + fess说 → 全部说出 → confess承认，坦白"},{"word":"confidence","ipa":"/ˈkɑːnfɪdəns/","pos":"n.","def":"信心；信任；秘密，机密","sen":"The student raised her hand with confidence to answer the question.","trans":"这个学生自信地举起手回答问题。","mne":"con全部 + fid相信，信念 + ence名词后缀 → 全部相信 → confidence自信，信任"},{"word":"confident","ipa":"/ˈkɑːnfɪdənt/","pos":"adj.","def":"自信的；确信的","sen":"She is a confident woman who is certain of her views.","trans":"她是一位充满自信的女性，对自己的观点深信不疑。","mne":"con全部 + fid相信，信念 + ent...的 → confident自信的"},{"word":"confidential","ipa":"/ˌkɑːnfɪˈdenʃl/","pos":"adj.","def":"机密的，秘密的","sen":"He destroyed the confidential document as soon as he had finished reading it.","trans":"他一读完机密文件就把它销毁了。","mne":"confident有信心的 + ial形容词后缀 → confidential表示信任的"},{"word":"confine","ipa":"/kənˈfaɪn/","pos":"v.","def":"监禁；限制","sen":"I am confined to my jail cell.","trans":"我被囚禁在监牢里了。","mne":"con加强意义 + fine界限 → confine边界；限制"},{"word":"confirm","ipa":"/kənˈfɜːrm/","pos":"v.","def":"证实；确认，使确信；批准","sen":"The X-ray picture confirmed that he had broken his finger.","trans":"X光影像证实他的手指已经骨折。","mne":"con共同 + firm坚定 → confirm证实；坚定"},{"word":"conflict","ipa":"/ˈkɑːnflɪkt, kənˈflɪkt/","pos":"n.","def":"冲突，矛盾；  v.冲突，抵触（读作/kənˈflɪkt/）","sen":"Apparently there is a conflict between them.","trans":"显然，他们之间有争执。","mne":"con共同 + flict打 → 一起打斗 → conflict冲突"},{"word":"conform","ipa":"/kənˈfɔːrm/","pos":"v.","def":"符合；相一致","sen":"Passport photos must conform to certain standards.","trans":"护照照片必须要符合一定的标准。","mne":"con共同 + form形状 → conform符合，一致"},{"word":"confront","ipa":"/kənˈfrʌnt/","pos":"v.","def":"面对；与……对抗","sen":"He has confronted a difficult situation.","trans":"他面临着一个困难的局面。","mne":"con共同 + front前额 → 互相面对 → confront对抗，面临"},{"word":"confrontation","ipa":"/ˌkɑːnfrənˈteɪʃn/","pos":"n.","def":"对抗，对峙；冲突","sen":"They felt confrontation was the only way to solve their disagreement.","trans":"他们觉得对抗是解决他们之间的分歧的唯一办法。","mne":"confront面对 + ation名词后缀 → confrontation面对，对峙"},{"word":"confuse","ipa":"/kənˈfjuːz/","pos":"v.","def":"使混乱，使迷惑；混淆","sen":"I always confuse the girl with her twin sister.","trans":"我一直把那个女孩和她的双胞胎姐姐搞混。","mne":"con一起 + fuse流 → confuse混淆，使困惑"},{"word":"confusion","ipa":"/kənˈfjuːʒn/","pos":"n.","def":"混乱；困惑；混淆","sen":"He is in a state of confusion.","trans":"他正处于一个混乱的状态。","mne":"confus使混乱 + ion名词后缀 → confusion混乱"},{"word":"congratulate","ipa":"/kənˈɡrætʃuleɪt/","pos":"v.","def":"向（某人）道贺，祝贺","sen":"My colleagues congratulated me on the promotion.","trans":"我的同事们祝贺我升职了。","mne":"con和，一起 + gratulate致谢 → congratulate祝贺"},{"word":"congratulation","ipa":"/kənˌɡrætʃəˈleɪʃn/","pos":"n.","def":"祝贺（常用复数形式）；恭喜","sen":"He received many congratulations for his excellent work.","trans":"由于出色地完成了工作，他收到很多祝贺。","mne":"con共同 + grat高兴 + u + lat拿出 + ion表示状态 → 喜事拿出来一起高兴 → congratulation祝贺，恭喜"},{"word":"congress","ipa":"/ˈkɑːŋɡrəs/","pos":"n.","def":"国会；代表大会；议会","sen":"A congress is a legislative body that discusses national policies.","trans":"国会是讨论国家政策的立法机构。","mne":"con共同 + gress行走 → 走到一起 → congress代表大会"},{"word":"connect","ipa":"/kəˈnekt/","pos":"v.","def":"连接，关联；把……联系起来","sen":"My phone is connected to the computer.","trans":"我的手机正连接着电脑。","mne":"con共同 + nect连结 → connect连结"},{"word":"connection","ipa":"/kəˈnekʃn/","pos":"n.","def":"连接；联系，关系","sen":"Each one of these cables is an Internet connection.","trans":"这儿的每一条线缆都是互联网上的一次连接。","mne":"connect连结 + ion名词后缀 → connection连结"},{"word":"conquer","ipa":"/ˈkɑːŋkər/","pos":"v.","def":"征服，攻克；克服","sen":"I managed to conquer the difficulties in my work.","trans":"我成功地克服了工作上的困难。","mne":"con表加强 + quer寻求 → 寻求直到拥有 → conquer征服"},{"word":"conscious","ipa":"/ˈkɑːnʃəs/","pos":"adj.","def":"神志清醒的；意识到的；有意的","sen":"The patient was fully conscious hours after the operation.","trans":"手术几小时后，这个病人完全清醒了。","mne":"con全部 + sci知道 + ous形容词后缀 → conscious有意识的"},{"word":"consciousness","ipa":"/ˈkɑːnʃəsnəs/","pos":"n.","def":"意识，知觉","sen":"His consciousness was clouded by the pain.","trans":"疼痛使他的意识变得模糊。","mne":"conscious有意识的 + ness名词后缀 → consciousness意识，知觉"},{"word":"consequence","ipa":"/ˈkɑːnsɪkwens/ ","pos":"n.","def":"结果；重要性；后果","sen":"The consequence of eating too much junk food is getting fat.","trans":"吃太多垃圾食品的后果就是长胖。","mne":"con一起 + sequ跟随  + ence名词后缀 → 随之而来的事物 → consequence后果"},{"word":"consequently","ipa":"/ˈkɑːnsɪkwentli/","pos":"adv.","def":"因此，结果","sen":"She studied hard，and consequently got high marks.","trans":"她努力学习，因此得到了高分。","mne":""},{"word":"conservative","ipa":"/kənˈsɜːrvətɪv/","pos":"adj.","def":"保守的；保守估计的；保守党的；  n.保守者；保守党党员","sen":"His conservative grandfather still wears traditional clothes every day.","trans":"他那位保守的爷爷每天仍然穿着传统服装。","mne":"conserv保留 + a + tive形容词后缀 → conservative保守的"},{"word":"conserve","ipa":"/kənˈsɜːrv/, /ˈkɑnˌsɜːrv/","pos":"v.","def":"保护，保存；节约（读作/kənˈsɜrv/）；  n.蜜饯，果酱（读作/ˈkɑnˌsɜrv/）","sen":"Our long-term goal is not just to protect, but to conserve the wildlife in this area for future generations.","trans":"我们的长期目标不仅是保护，更是要为子孙后代保育这一地区的野生动物。","mne":"con全部 + serve服务，保持 → 全部保持下来 → 保存"},{"word":"consider","ipa":"/kənˈsɪdər/","pos":"v.","def":"考虑，细想；认为，把...看作","sen":"I will consider your offer, but I think I can find a better one.","trans":"我会考虑你给的职位，但我觉得我能找到一个更好的。","mne":"con有关 + sider星座 → 对星座的观察 → consider考虑"},{"word":"considerable","ipa":"/kənˈsɪdərəbl/","pos":"adj.","def":"相当大的，相当重要的；重要的；可观的","sen":"Students have considerable pressure in their final year of university.","trans":"学生们在大学的最后一年有相当大的压力。","mne":"consider考虑 + able可……的 → 需要考虑的很多 → considerable相当大的"},{"word":"considerate","ipa":"/kənˈsɪdərət/","pos":"adj.","def":"体贴的，考虑周到的","sen":"As a considerate boyfriend, he took good care of her when she was ill.","trans":"作为一个体贴的男朋友，他在她生病时无微不至地照顾她。","mne":"consider仔细思考，考虑 + ate...的 → 考虑周到的"},{"word":"consideration","ipa":"/ kənˌsɪdəˈreɪʃ(ə)n /","pos":"n.","def":"考虑，思考；体贴，体谅，顾及","sen":"He has three cars as options for consideration.","trans":"他有三辆车作为选择以供考虑。","mne":""},{"word":"consist","ipa":"/kənˈsɪst/","pos":"v.","def":"由……组成；在于","sen":"A bicycle consists of many parts.","trans":"自行车由许多部分组成。","mne":"con共同 + sist站立 → 站到一起 → consist由…组成；与…一致"},{"word":"consistent","ipa":"/kənˈsɪstənt/","pos":"adj.","def":"【计】一致的；始终如一的，一致的","sen":"If the user inputs are the same, we can say that the inputs are consistent.","trans":"如果用户的输入相同，我们可以说这些输入是一致的。","mne":"con共同 + sist站立 + ent形容词后缀……的 → consistent 一致的，一贯的"},{"word":"consistently","ipa":"/kənˈsɪstəntli/","pos":"adv.","def":"一致地","sen":"The company has consistently denied it had knowingly broken arms embargoes.","trans":"这家公司一致否认自己是有意违反武器禁运规定。","mne":"con共同 + sist站立 + ent...的 + ly...地 → consistently一贯地；一致地"},{"word":"constant","ipa":"/ˈkɑːnstənt/","pos":"adj.","def":"持续不断的；不变的；  n.常数，恒量","sen":"The baby needs his mother's constant attention.","trans":"这个婴儿需要妈妈时刻的照料。","mne":"con始终 + stant站立 → 始终站着 → constant不变的"},{"word":"constantly","ipa":"/ˈkɑːnstəntli/","pos":"adv.","def":"不断地，时常地","sen":"He is constantly updating his blog.","trans":"他不断地更新他的博客。","mne":"con始终 + stant=stand站 + ly ...地 → constant始终站着=不变的 + ly ...地 → constantly不变地"},{"word":"constitute","ipa":"/kɒnstɪtjuːt/","pos":"v.","def":"构成，组成","sen":"Bread, beef, cheese and salad constitute the perfect burger.","trans":"面包、牛肉、芝士和沙拉组成了一个完美的汉堡。","mne":"con共同 + stitute=set up放 → 放到一起 → constitute构成，组成"},{"word":"constitution","ipa":"/ˌkɑːnstɪˈtuːʃn/","pos":"n.","def":"宪法，章程；体质，体格；体质","sen":"Constitution is the fundamental law.","trans":"宪法是根本法。","mne":"constitut组成 + ion名词后缀 → constitution构成；宪法"},{"word":"construct","ipa":"/kənˈstrʌkt/, /ˈkɑnˌstrʌkt/","pos":"v.","def":"建造；作（图）；  n.结构体；构想，构筑，构思；概念","sen":"The workers are constructing a tall building.","trans":"工人们正在建造一座高楼。","mne":"con共同 + struct建立 → 共同建立 → construct建造"},{"word":"construction","ipa":"/kənˈstrʌkʃn/ ","pos":"n.","def":"建造；建筑","sen":"They are doing construction at night around the Montmartre so as not to disturb daytime traffic.","trans":"为了不影响白天的交通，他们晚上在蒙马特酒店附近建造施工。","mne":"con一起 + struct堆起 + ion名词后缀 → construction建造"},{"word":"consult","ipa":"/kənˈsʌlt/","pos":"v.","def":"请教，咨询；查阅；请教","sen":"The couple are consulting the advisor for help.","trans":"这对夫妇正在咨询那位顾问以寻求帮助。","mne":"con共同，一起 + sult跳跃 → 召集人们聚到一起 → consult咨询"},{"word":"consultant","ipa":"/kənˈsʌltənt/","pos":"n.","def":"顾问；高级顾问医师","sen":"The consultant will explain how we should run our business.","trans":"顾问将会解释我们应该如何经营我们的事业。","mne":"consult咨询 + ant表示人 → consultant会诊医师，专科医生；顾问"},{"word":"consume","ipa":"/kənˈsuːm/ ","pos":"v.","def":"消耗，消费；吃，喝，饮","sen":"We've consumed all of the toilet paper that we bought from the supermarket.","trans":"我们把从超市买来的厕纸都用完了。","mne":"con全部 + sum拿取 + e → 全部拿光 → consume消费"},{"word":"consumer","ipa":"/kənˈsuːmər/","pos":"n.","def":"消费者","sen":"Consumers are shopping in the supermarket.","trans":"消费者正在超市里购物。","mne":"con全部 + sum拿取 + er人 → consumer消费者"},{"word":"consumption","ipa":"/kənˈsʌmpʃn/","pos":"n.","def":"消耗，消耗量，消费","sen":"We need to reduce energy consumption.","trans":"我们需要减少能源消耗。","mne":"consum(e)消费 + p + tion名词后缀 → consumption消费"},{"word":"contact","ipa":"/ˈkɑːntækt/","pos":"v.","def":"联系；  n.联系，联络","sen":"They are contacting each other by a video call.","trans":"他们正通过视频电话来联系对方。","mne":"con一起 + tact接触 → contact接触，联系"},{"word":"contain","ipa":"/kənˈteɪn/","pos":"v.","def":"包含，含有，容纳；自制，抑制，克制","sen":"Sea water contains salt.","trans":"海水含有盐分。","mne":"con一起 + tain握住 → contain包容，包含"},{"word":"container","ipa":"/kənˈteɪnər/","pos":"n.","def":"集装箱","sen":"There are a lot of containers at the port.","trans":"港口有很多集装箱。","mne":"con全部 + tain握住 + er表示物 → container容器，集装箱"},{"word":"contemporary","ipa":"/kənˈtempəreri/","pos":"adj.","def":"同时代的；当代的，现代的；  n.同时代的人；同龄人，同辈","sen":"The two writers are contemporary with each other.","trans":"这两位作家是同时代的人。","mne":"con共同 + tempor时间 + ary……的 → contemporary同时代的"},{"word":"content","ipa":"/ˈkɑːntent/,/kənˈtent/","pos":"n.","def":"目录；  adj.满足的；  v.使满意（读作/kənˈtent/）","sen":"You can get a brief idea of a book from the table of contents.","trans":"你可以从目录页了解一本书的大致内容。","mne":"con一起，全部 + tent拿  → 一起拿住  → content容量，引申为内容"},{"word":"contest","ipa":"/ˈkɑːntest/, /kənˈtest/","pos":"n.","def":"比赛，竞争（读作/ˈkɑːntest/）；  v.争夺，争论（读作/kənˈtest/）；争辩","sen":"The girl in the middle seems to be the winner of the contest.","trans":"中间的女生好像是这场比赛的获胜者。","mne":"con共同 + test测试 → 共同测试 → contest比赛，竞赛"},{"word":"context","ipa":"/ˈkɑːntekst/","pos":"n.","def":"【计】上下文；上下文，语境","sen":"Context-oriented Programming enables the expression of behavioral variation dependent on context.","trans":"以上下文为导向的程序设计能够根据上下文表达行为变化。","mne":"con一起 + text编织 → context上下文，来龙去脉"},{"word":"continent","ipa":"/ˈkɑːntɪnənt/","pos":"n.","def":"大陆，陆地，洲","sen":"The continents were closer to each other in the past.","trans":"在过去，各大洲之间的距离都比较近。","mne":"con共同 + tin握，持 + ent名词后缀：物 → 保持连在一起的陆地 → continent大陆，陆地，大洲"},{"word":"continual","ipa":"/kənˈtɪnjuəl/","pos":"adj.","def":"不断的，连续的","sen":"Learning English is a long-term continual process.","trans":"学习英语是一个长期的、连续不断的过程。","mne":"continu(e)持续 + al形容词后缀 → continual持续的，不间断的"},{"word":"continue","ipa":"/kənˈtɪnjuː/","pos":"v.","def":"继续","sen":"She continued running when the others stopped.","trans":"当其他人停下的时候，她还在继续奔跑。","mne":"con全部 + tinu握住 + e → 全部拿住 → 做事做到尾 → continue继续"},{"word":"continuous","ipa":"/kənˈtɪnjuəs/","pos":"adj.","def":"连续的","sen":"There will be three days of continuous snow.","trans":"接下来连续三天都会下雪。","mne":"continu(e)持续 + ous形容词后缀 → continuous持续不断的"},{"word":"contract","ipa":"/ˈkɑːntrækt/, /kənˈtrækt/","pos":"n.","def":"合同，契约（读作/ˈkɑːntrækt/）；  v.感染（疾病）；签合同；缩减","sen":"I signed the contract and bought the house.","trans":"我签了合同，买下了这栋房子。","mne":"con共同 + tract拉 → 拉到一起来 → contract合同"},{"word":"contradict","ipa":"/ˌkɑːntrəˈdɪkt/","pos":"v.","def":"反驳","sen":"The little girl contradicts everything her mom says.","trans":"这个小女孩对她妈妈说的每一句话都唱反调。","mne":"contra反对，相反 + dict说 → 反着说 → contradict反驳"},{"word":"contrary","ipa":"/ˈkɑːntreri/","pos":"adj.","def":"对立的，相反的","sen":"The lady and the man hold contrary views.","trans":"这位女士和这位男士持有相反的意见。","mne":"contr反对，相反 + ary形容词后缀 → contrary相反的"},{"word":"contrast","ipa":"/ˈkɑnˌtræst/, /kənˈtræst/","pos":"n.","def":"差异；对照，对比；  v.对照，对比（读作/kənˈtræst/）","sen":"There's a striking contrast between his portrayals of two different characters.","trans":"他扮演的两个不同的角色很有反差感。","mne":"contra相反 + st站 → 站在对立面 → contrast对比"},{"word":"contribute","ipa":"/kənˈtrɪbjuːt/","pos":"v.","def":"贡献；投稿","sen":"Many people contribute money to help people in need.","trans":"很多人捐钱来帮助有需要的人们。","mne":"con共同 + tribute给予 → 全部给出 → contribute捐献，贡献"},{"word":"contribution","ipa":"/ˌkɑːntrɪˈbjuːʃ(ə)n/","pos":"n.","def":"贡献；投稿稿件","sen":"Thanks to all of you for making a contribution to our charity.","trans":"感谢各位对我们慈善机构的贡献。","mne":"con 共同 + tribut 给予 + ion 抽象名词 → n. 贡献,促成作用;捐款,捐献物;(投给报刊等的)稿件"},{"word":"control","ipa":"/kənˈtroʊl/","pos":"v.","def":"控制，管理；  n.控制，管理","sen":"The little boy can control the direction of his toy car.","trans":"小男孩可以控制玩具汽车的方向。","mne":""},{"word":"convenience","ipa":"/kənˈviːniəns/","pos":"n.","def":"方便；便利设施","sen":"We have provided seats for the convenience of our customers. ","trans":"为方便顾客我们备有座位。","mne":"con全部 + veni来 + ence表名词 → 全部能来没有障碍 → convenience方便"},{"word":"convenient","ipa":"/kənˈviːniənt/","pos":"adj.","def":"便利的，方便的，省事的","sen":"Utilities are convenient for everyone.","trans":"公用设施为每个人提供了便利。","mne":"con共同，全部 + ven来 + ient……的 → convenient便利的，近便的"},{"word":"convention","ipa":"/kənˈvenʃn/","pos":"n.","def":"会议；习俗；惯例；（尤指国际性的）公约，协定","sen":"The barbers got together for the convention.","trans":"理发师们为了这场大会聚在一起。","mne":"con=com一起 + vent来 + ion表名词 → 大家来到一起 → convention会议"},{"word":"conventional","ipa":"/kənˈvenʃənl/","pos":"adj.","def":"传统的，惯用的；依照惯例的","sen":"It is a conventional custom to write New Year couplets.","trans":"写春联是一种传统习俗。","mne":"con共同 + vent来 + ion表名词 + al…的 → conventional普通的"},{"word":"conversation","ipa":"/ˌkɑːnvərˈseɪʃn/","pos":"n.","def":"非正式交谈，谈话；非正式会谈","sen":"They had a conversation in the cafe.","trans":"他们在咖啡厅里进行了一次交谈。","mne":"convers交谈 + ation名词后缀 → conversation会话"},{"word":"conversion","ipa":"/kənˈvɜːrʒn/","pos":"n.","def":"转变，转换；【化】转化，转换；（宗教或信仰的）改变","sen":"She went through a significant conversion in the last four years.","trans":"她在过去的四年里经历了巨大的转变。","mne":"conver转化 + sion名词后缀 → conversion 转化"},{"word":"convert","ipa":"/kənˈvɜːrt/, /ˈkɑnˌvɜːrt/","pos":"v.","def":"可转变为，可变换成；使改变信仰；  n.皈依者，改变宗教信仰者（读作/ˈkɑnˌvɜrt/）","sen":"Cool! The sofa can be easily converted into a bed.","trans":"真棒！这张沙发轻轻松松就能变成一张床。","mne":"con共同 + vert转变 → 共同转 → 转化；改造"},{"word":"convertible","ipa":"/kənˈvɜːrtəbl/","pos":"adj.","def":"可改变的，自由兑换的","sen":"This sofa is convertible; it can be turned into a bed for guests.","trans":"这个沙发是可转换的，它可以变成一张床给客人用。","mne":"convert转移 ＋ ible可…的 → convertible可变换的"},{"word":"convey","ipa":"/kənˈveɪ/","pos":"v.","def":"传送，运送；表达","sen":"The belt conveys the luggage to the passengers.","trans":"传送带将行李运出来给乘客。","mne":"con共同，一起 + vey路，移动 → 一起在路上移动 → convey运输"},{"word":"convince","ipa":"/kənˈvɪns/","pos":"v.","def":"使确信，使相信；说服","sen":"The footprints convinced the wife that it was the cat who made the mess.","trans":"这些脚印使这位太太确信是猫把一切弄乱的。","mne":"con加强 + vinc征服 + e → 彻底征服对方 → convince使确信"},{"word":"convincing","ipa":"/kənˈvɪnsɪŋ/","pos":"adj.","def":"有说服力的","sen":"The cream on the cat's face is convincing evidence that it ate the cake.","trans":"猫脸上的奶油是它吃了蛋糕的有力证据。","mne":"convinc(e)使确信 + ing形容词后缀 → convincing 令人信服的"},{"word":"cook","ipa":"/kʊk/","pos":"n.","def":"厨师；  v.烹饪，烹调；煮，烧","sen":"She is a great cook. Look at all this delicious food!","trans":"她是个很棒的厨师。看看这些美食！","mne":""},{"word":"cool","ipa":"/kuːl/","pos":"adj.","def":"凉的，凉爽的；冷静的；酷的；  v.（使）冷却；变凉","sen":"In summer, taking a shower is a great way to keep cool.","trans":"在夏天，冲凉是很好的方式，能保持凉爽。","mne":""},{"word":"cooperate","ipa":"/koʊˈɑːpəreɪt/","pos":"v.","def":"合作；协作","sen":"Baicizhan cooperated with a famous brand to co-brand these new T-shirts.","trans":"百词斩和某个著名的品牌合作推出了这些新款联名T恤。","mne":"co共同 ＋ oper工作 ＋ ate使 → cooperate共同工作"},{"word":"cooperation","ipa":"/koʊˌɑːpəˈreɪʃn/","pos":"n.","def":"合作；协作","sen":"The success of the plan will rely on full cooperation from everybody!","trans":"计划的成功依赖于大家的通力合作！","mne":"co共同 + operat操作 + ion名词后缀 → 共同操作 → 合作"},{"word":"coordinate","ipa":"/koʊˈɔrdəˌneɪt/, /koʊˈɔrdənət/","pos":"v.","def":"协调；（衣服、家具等）搭配，协调；  n.坐标；  adj.并列的；【数】坐标","sen":"The nurse must coordinate with the surgical team to ensure patient safety.","trans":"护士必须与手术团队协调，以确保患者安全。","mne":"co共同 + ordin顺序 + ate动词后缀 → 顺序相同 → coordinate协调，同等的"},{"word":"cope","ipa":"/koʊp/","pos":"v.","def":"处理，应对","sen":"The experienced captain can cope with the dangerous situation and find a solution.","trans":"这位经验丰富的机长能应付危险情况并找到解决方法。","mne":""},{"word":"copper","ipa":"/ˈkɑːpər/","pos":"n.","def":"铜；铜币","sen":"Chinese ancient coins were made of copper.","trans":"中国古代钱币是铜做的。","mne":""},{"word":"copy","ipa":"/ˈkɑpi/","pos":"n.","def":"副本，拷贝；复印件，复制品；  v.【计】拷贝；复制，复印","sen":"She is going to make a few more copies of the document.","trans":"她准备给文件多制作几份副本。","mne":"co和，与 + py权力，财富，资源 → copy抄写"},{"word":"copyright","ipa":"/ˈkɑːpiraɪt/","pos":"n.","def":"版权，著作权","sen":"He sold the copyright on his book to the large publishing house.","trans":"他把书的版权卖给了那家大型出版社。","mne":"copy复制，复印 + right权利 → copyright版权，著作权"},{"word":"core","ipa":"/kɔːr/","pos":"n.","def":"核心，要点；果心，核；  v.去核","sen":"The Earth's core is hot.","trans":"地心的温度很高。","mne":"cor心脏 + e → core果实的心，核心"},{"word":"corn","ipa":"/kɔːrn/","pos":"n.","def":"玉米；谷物，谷粒","sen":"Sweet corn tastes best with salt and butter.","trans":"吃甜玉米的时候加上盐和黄油味道最好。","mne":""},{"word":"corner","ipa":"/ˈkɔːrnər/","pos":"n.","def":"角落，角","sen":"The little boy unhappily sat in the corner of the room.","trans":"小男孩不高兴地坐在房间的角落里。","mne":"corn角，头 + er名词后缀，人或物 → corner角落"},{"word":"corporate","ipa":"/ˈkɔːrpərət/","pos":"adj.","def":"公司的；全体的","sen":"This is the corporate logo of our company.","trans":"这是我们公司的标志。","mne":"corpor身体，团体 + ate形容词后缀 → corporate共同的"},{"word":"corporation","ipa":"/ˌkɔːrpəˈreɪʃn/","pos":"n.","def":"公司","sen":"In our corporation, we listen to everyone's opinion.","trans":"在我们公司，我们会听取每个人的意见。","mne":"corporat(e)公司的 + ion名词后缀 → corporation公司"},{"word":"correct","ipa":"/kəˈrekt/","pos":"adj.","def":"正确的；  v.改正；矫正；批改","sen":"Only one in four people know the correct answer to the question.","trans":"只有四分之一的人知道这个问题的正确答案。","mne":"cor共同，加强意义 + rect正 → 全部正确的 → 正确的，恰当的"},{"word":"correspond","ipa":"/ˌkɔːrəˈspɑːnd/","pos":"v.","def":"相似；相符，一致；通信；  v.类似于","sen":"The clothes of the mother and the daughter correspond closely.","trans":"这对母女的衣服极其相似。","mne":"cor共同 + respond回应 → 相互回应 → correspond通信，符合"},{"word":"correspondence","ipa":"/ˌkɔːrəˈspɑːndəns/","pos":"n.","def":"通信，通信联系；相似","sen":"Nowadays, we can keep up correspondence with our families via our phones.","trans":"如今，我们可以通过手机与家人保持联系。","mne":"cor共同 + respond回答 + ence表名词 → correspondence通信；通信联系"},{"word":"correspondent","ipa":"/ˌkɔːrəˈspɑːndənt/","pos":"n.","def":"通讯员，记者；通信者","sen":"After the earthquake, the correspondent sent us the first news.","trans":"发生地震后，这记者发回了第一手新闻。","mne":""},{"word":"corresponding","ipa":"/ˌkɔːrəˈspɑːndɪŋ/","pos":"adj.","def":"相应的；符合的，一致的；通信的","sen":"Each lock has its own corresponding key.","trans":"每一把锁都有它对应的钥匙。","mne":"correspond符合，通信 + ing形容词后缀 → corresponding 相应的；通信的"},{"word":"corridor","ipa":"/ˈkɔːrɪdɔːr/","pos":"n.","def":"走廊，通道","sen":"The students hurried down the corridor to their next class.","trans":"学生们匆匆走过走廊去上下一节课。","mne":"corr走 + idor表物 → corridor 走廊，回廊，通路"},{"word":"corrupt","ipa":"/kəˈrʌpt/","pos":"adj.","def":"腐败的；  v.使腐败","sen":"He is a corrupt official.","trans":"他是一个腐败的官员。","mne":"cor共同 + rupt断 → 全部断 → corrupt变坏的，腐败的"},{"word":"corruption","ipa":"/kəˈrʌpʃən/","pos":"n.","def":"腐败","sen":"In business ethics, corruption is a serious concern that can ruin a company's reputation.","trans":"在商业道德中，腐败是一个严重的问题，它可能会毁掉一个公司的声誉。","mne":"corrupt腐败的 + ion名词后缀 → corruption腐败"},{"word":"cosmetic","ipa":"/kɑːzˈmetɪk/","pos":"n.","def":"化妆品；  adj.化妆用的，美容的；装门面的 [表不满]","sen":"Her bag was filled with various cosmetics for the event.","trans":"她的包里装满了为这次活动准备的各种化妆品。","mne":""},{"word":"cost","ipa":"/kɔːst/","pos":"n.","def":"费用，价钱；代价，损失；  v.花费，价钱为","sen":"The cost of this new house is one million dollars.","trans":"这座新房子的价钱是一百万美元。","mne":"co一起 + st站立，使稳定 → 使事物形成所需的东西 → cost支出，成本，花费"},{"word":"costly","ipa":"/ˈkɔːstli/","pos":"adj.","def":"昂贵的；价值高的","sen":"The diamond ring is quite costly.","trans":"这枚钻戒相当昂贵。","mne":"cost花费 + ly形容词后缀 → costly昂贵的"},{"word":"cotton","ipa":"/ˈkɑːtn/","pos":"n.","def":"棉花；棉布","sen":"Cotton feels soft and can be ideal for clothing.","trans":"棉花摸起来很柔软，可以用来制作衣服。","mne":""},{"word":"couch","ipa":"/kaʊtʃ/","pos":"n.","def":"长沙发；长椅；  v.表达","sen":"I prefer a red couch in my house.","trans":"我喜欢在家里放红色的沙发。","mne":""},{"word":"cough","ipa":"/kɔːf/","pos":"v.","def":"咳嗽；  n.咳嗽","sen":"He coughed badly when he was ill.","trans":"他生病时咳嗽得厉害。","mne":""},{"word":"could","ipa":"/kʊd/","pos":"v.","def":"可以，可能","sen":"These building blocks could collapse soon.","trans":"这些积木可能很快倒塌。","mne":"can能 + d过去分词后缀 → could可以，可能"},{"word":"council","ipa":"/ˈkaʊnsl/","pos":"n.","def":"议会；理事会；委员会","sen":"The council members are currently holding a meeting.","trans":"委员会成员现在正在举行会议。","mne":""},{"word":"count","ipa":"/kaʊnt/","pos":"v.","def":"计算；认为；计数；  n.计数","sen":"I try to count sheep when I want to fall asleep.","trans":"当我想睡觉的时候，我就尝试着数绵羊。","mne":""},{"word":"counter","ipa":"/ˈkaʊntər/","pos":"n.","def":"柜台；回击，反击；  v.抵制；  adv.相反地","sen":"Customers pay money at the counter.","trans":"顾客在柜台付钱。","mne":"count计算，加总 + er表名词 → 结账的地方 → counter柜台"},{"word":"counterpart","ipa":"/ˈkaʊntərpɑːrt/","pos":"n.","def":"副本","sen":"I stared right in the face of my counterpart.","trans":"我直盯着这个极像我的人的脸。","mne":"counter相对应 + part部分，分开 → 对应的一部分 → counterpart相对物；副本"},{"word":"countless","ipa":"/ˈkaʊntləs/","pos":"adj.","def":"无数的","sen":"There are countless stars in the night sky.","trans":"夜空中有无数的星星。","mne":"count计算+less表形容词，无...的 →数不清的"},{"word":"country","ipa":"/ˈkʌntri/","pos":"n.","def":"国家；乡村","sen":"Each country has its own national flag.","trans":"每个国家都有自己的国旗。","mne":"counter相对，相反 + y名词后缀 → 相对于他国而言的本国土地 → country国家"},{"word":"countryside","ipa":"/ˈkʌntrisaɪd/","pos":"n.","def":"乡村，郊野","sen":"This lovely house is in the countryside.","trans":"这栋漂亮的房子在乡下。","mne":"country农村 + side边 → countryside乡下，农村"},{"word":"couple","ipa":"/ˈkʌpl/","pos":"n.","def":"一对；几个（人或事物）；夫妇；  v.配对，连接，结合","sen":"There are a couple of rabbits sitting on the grass.","trans":"有一对小兔子坐在草坪上。","mne":"co一起 ＋ up取到 ＋ le → 联系，连接 →couple恋人"},{"word":"courage","ipa":"/ˈkɜːrɪdʒ/","pos":"n.","def":"勇气，胆量","sen":"It needs a lot of courage for the little girl to climb the rock wall.","trans":"小女孩攀登这块岩壁需要很大的勇气。","mne":""},{"word":"courageous","ipa":"/kəˈreɪdʒəs/","pos":"adj.","def":"勇敢的，英勇的，有胆量的","sen":"The courageous prince is fighting against the fierce dragon.","trans":"勇敢的王子在与恶龙搏斗。","mne":"courage勇气 + ous形容词后缀 → courageous勇敢的"},{"word":"course","ipa":"/kɔːrs/","pos":"n.","def":"课程；过程；一道菜；  v.快速流动","sen":"The college student took a math course online.","trans":"这个大学生在网上学习数学课程。","mne":"cour发生 + se → 发展；进程，课程，一道菜"},{"word":"court","ipa":"/kɔːrt/","pos":"n.","def":"法院，法庭；球场；宫廷；  v.招致灾祸","sen":"The aim of the court is to provide justice.","trans":"法庭致力于伸张正义。","mne":"com一起 + hort庭院 → 一起聚集在庭院中 → court法院；法庭"},{"word":"courteous","ipa":"/ˈkɜːrtiəs/","pos":"adj.","def":"有礼貌的，谦恭有礼的","sen":"They give a courteous bow to each other.","trans":"他们彼此之间有礼貌地鞠躬。","mne":"court礼貌 + eous有……的 → 有礼貌的"},{"word":"cousin","ipa":"/ˈkʌzn/","pos":"n.","def":"堂（或表）兄弟（姐妹），同辈表亲（或堂亲）","sen":"The boy likes to play with his little cousin.","trans":"男孩喜欢和他的小表妹一起玩。","mne":"cou=com共同 + sin姐妹 → 共同的兄弟姐妹 → cousin堂/表兄弟/姐妹"},{"word":"cover","ipa":"/ˈkʌvər/","pos":"v.","def":"盖住；包括；覆盖，遮盖","sen":"He covers his face with sunglasses and a mask.","trans":"他用墨镜和口罩遮住了脸。","mne":"co表强调 + ver关闭，覆盖 → cover盖住"},{"word":"cow","ipa":"/kaʊ/","pos":"n.","def":"母牛，奶牛；母兽","sen":"We feed a cow to get milk for breakfast.","trans":"我们养了一头奶牛为我们的早餐提供牛奶。","mne":""},{"word":"craft","ipa":"/kræft/  ","pos":"n.","def":"手艺，工艺；船；  v.手工制作，精心制作","sen":"Crafts usually involve making things skillfully with one's hands.","trans":"手工艺品中往往包含了熟练的手工制作。","mne":""},{"word":"crash","ipa":"/kræʃ/","pos":"v.","def":"碰撞；坠落；崩溃；  n.撞车；坠毁；崩溃","sen":"The car behind crashed into the one ahead.","trans":"后面的车撞上前面那辆车了。","mne":""},{"word":"crazy","ipa":"/ˈkreɪzi/","pos":"adj.","def":"疯狂的，荒唐的；狂热的，迷恋的","sen":"The crazy man wears a watermelon as a hat.","trans":"那个疯狂的男人把西瓜当帽子戴。\n","mne":"craz=craze发狂 + y表形容词  → 发狂的  → crazy疯狂的，荒唐的"},{"word":"cream","ipa":"/kriːm/","pos":"n.","def":"奶油；奶油，乳脂","sen":"Would you like whipped cream on your coffee?","trans":"您的咖啡上要加打发的奶油吗？","mne":""},{"word":"create","ipa":"/kriˈeɪt/","pos":"v.","def":"创造；创作","sen":"The writer created many characters.","trans":"这位作家创造了很多角色。","mne":"cre增长，产生 + ate造成 → 增长 → create创造"},{"word":"creative","ipa":"/kriˈeɪtɪv/","pos":"adj.","def":"有创造力的","sen":"The little girl was very creative and painted a brilliant picture.","trans":"这个小女孩很有创造力，画了一幅很漂亮的画。","mne":"cre增长，产生 + ative形容词后缀，具有……性质的 → creative有创造性的"},{"word":"creativity","ipa":"/ˌkriːeɪˈtɪvəti/","pos":"n.","def":"创造力；创造","sen":"His creativity made him famous on the internet.","trans":"他的创造力让他火遍全网。","mne":""},{"word":"creature","ipa":"/ˈkriːtʃər/ ","pos":"n.","def":"动物；生物","sen":"Is your favorite creature the dog, the cat, or the rabbit?","trans":"你最喜欢的动物是狗、猫，还是兔子？","mne":"creat创造 + ure表名词 → 创造物，生物"},{"word":"credit","ipa":"/ˈkredɪt/","pos":"n.","def":"（借钱偿还的）信誉，信用；荣誉；学分；借款；债权；  v.信赖；认为是……的功劳；记学分","sen":"It's better to use a credit card than to carry cash.","trans":"刷信用卡比携带现金要好。","mne":"cred相信 + it名词后缀 → credit信任"},{"word":"crew","ipa":"/kruː/","pos":"n.","def":"（有专门技术的）一组工作人员，（飞机、轮船等的）全体工作人员","sen":"This is a picture of the crew and the aircraft.","trans":"这是一张机组人员与飞机的合影。","mne":""},{"word":"crime","ipa":"/kraɪm/","pos":"n.","def":"犯罪活动；罪行","sen":"The police are investigating the crime scene.","trans":"警方正在调查犯罪现场。","mne":""},{"word":"criminal","ipa":"/ˈkrɪmɪnl/","pos":"n.","def":"罪犯，犯人；  adj.犯罪的，犯法的","sen":"The criminal is in prison now.","trans":"这个罪犯现在在监狱里。","mne":"crimin罪 + al表名词 → criminal罪犯"},{"word":"crisis","ipa":"/ˈkraɪsɪs/","pos":"n.","def":"危机；危急关头，存亡之际","sen":"He found himself in a crisis after disturbing the beehive.","trans":"他扰动了蜂窝，然后发现自己陷入了危机。","mne":"cris判断，分辨 + is → 需要作出判断的时刻 → crisis危机时刻"},{"word":"critic","ipa":"/ˈkrɪtɪk/","pos":"n.","def":"评论家","sen":"As a strict food critic, I think the pizza is just so so.","trans":"作为一个严格的美食评论家，我觉得这个比萨还行吧。","mne":"crit批评 + ic人 → critic批评家"},{"word":"critical","ipa":"/ˈkrɪtɪkl/","pos":"adj.","def":"危急的；批评性的；临界的；关键的，决定性的；重要的","sen":"The injured man was in a critical condition so doctors rushed him to the emergency room.","trans":"这位伤者情况危急，因此医生们赶紧把他送到了急诊室。","mne":"critic批评家 + al表形容词 → critical挑剔的"},{"word":"criticise","ipa":"/ˈkrɪtɪsaɪz/","pos":"v.","def":"批评；批判","sen":"He criticised me for not doing my work very well.","trans":"他因为我工作没有做好而批评我。","mne":"critic批评家 ＋ ise动词后缀 → criticise批评"},{"word":"criticism","ipa":"/ˈkrɪtɪsɪzəm/","pos":"n.","def":"批评；评论；指责","sen":"The stick man took criticism from another.","trans":"这个火柴人受到了另一个火柴人的批评。","mne":"critic批评者 + ism名词后缀 → criticism 批评"},{"word":"criticize","ipa":"/ˈkrɪtɪsaɪz/","pos":"v.","def":"批评，评论，责难（同criticise）","sen":"Her manager criticized the girl for her poor performance.","trans":"经理批评关雎尔工作没做好。","mne":"critic评论家 + ize表动词 → criticize批评"},{"word":"crop","ipa":"/krɑːp/ ","pos":"n.","def":"作物，庄稼；（一季的）收成；  v.裁剪","sen":"The crops are dying because of the drought.","trans":"因为干旱，庄稼都快死了。","mne":""},{"word":"cross","ipa":"/krɔːs/","pos":"v.","def":"穿越，穿过；使交叉；  n.十字架；  adj.生气的","sen":"Always use a crosswalk when you cross the road.","trans":"过马路的时候请走人行道。","mne":""},{"word":"crowd","ipa":"/kraʊd/","pos":"n.","def":"人群，观众；  v.聚集在……周围","sen":"Wow! There was a large crowd of people at the concert.","trans":"哇！音乐会上有很多人。","mne":""},{"word":"crucial","ipa":"/ˈkruːʃl/","pos":"adj.","def":"关键的，至关重要的；决定性的","sen":"This crucial round will decide who will win the game.","trans":"这个关键回合将决定谁会赢得比赛。","mne":"cruc十字形，交叉 + ial具有...性质的 → 十字路口 → crucial关键的"},{"word":"crude","ipa":"/kruːd/","pos":"adj.","def":"天然的；粗糙的；粗鲁的；简陋的","sen":"These are crude ores hewn from the mountains.","trans":"这些是从山上开采出来的天然矿石。","mne":"crud生的 + e → crude粗糙的；原始的"},{"word":"cruel","ipa":"/ˈkruːəl/","pos":"adj.","def":"残忍的，残酷的；冷酷的","sen":"Don't be so cruel to me! I'm just a watermelon.","trans":"不要对我这么残忍！我只是一个西瓜。","mne":" "},{"word":"crush","ipa":"/krʌʃ/","pos":"v.","def":"压扁，压坏；  n.热恋，迷恋","sen":"The can was crushed and put into the recycling bin.","trans":"易拉罐被压扁并扔进了可回收垃圾桶中。","mne":""},{"word":"cry","ipa":"/kraɪ/","pos":"v.","def":"哭，哭泣","sen":"He is crying tears of joy.","trans":"他喜极而泣。","mne":""},{"word":"crystal","ipa":"/ˈkrɪstl/","pos":"n.","def":"水晶；结晶","sen":"She is holding a purple crystal in her hand.","trans":"她正拿着一块紫水晶。","mne":"crys冻，结冰 + tal → crystal水晶，晶体"},{"word":"cube","ipa":"/kjuːb/","pos":"n.","def":"立方体，立方","sen":"The tofu cheese is cut into cubes before being canned.","trans":"豆腐乳在装罐前要切成小块。","mne":""},{"word":"cue","ipa":"/kjuː/","pos":"n.","def":"提示；暗示，信号；  v.给……提示","sen":"The cue reminded the man that there's only 5 minutes left for his speech.","trans":"信号提醒这个男人他的演讲只剩五分钟了。","mne":""},{"word":"cultivate","ipa":"/ˈkʌltɪveɪt/","pos":"v.","def":"耕作，种植，栽培；培养，发展","sen":"Despite the burning sun, these boys were cultivating with joy.","trans":"尽管烈日炎炎，这些少年还是在快乐地耕作着。","mne":"cult耕种，培养 + ivate表动词 → 耕作；培养"},{"word":"cultural","ipa":"/ˈkʌltʃərəl/","pos":"adj.","def":"文化的","sen":"These cultural symbols are very important to Chinese people.","trans":"这些文化符号对中国人来说非常重要。","mne":"cultur(e)文化 + al形容词后缀 → cultural文化的"},{"word":"culture","ipa":"/ˈkʌltʃər/ ","pos":"n.","def":"文化；（细菌或细胞）培养","sen":"China is a beautiful country with long history and colorful culture.","trans":"中国是一个有着悠久历史以及多彩文化的美丽国家。","mne":"cult耕种，培养 + ure抽象名词 → [对心灵的]培养 → culture修养；文化"},{"word":"cup","ipa":"/kʌp/","pos":"n.","def":"杯，杯子；（一）杯（的容量）","sen":"The two cups are made of chocolate.","trans":"这两个杯子是由巧克力制成的。","mne":""},{"word":"cupboard","ipa":"/ˈkʌbərd/","pos":"n.","def":"碗橱，衣柜；壁橱","sen":"She is taking out a bowl from the cupboard.","trans":"她正从橱柜里拿出一个碗。","mne":"cup杯子 + board板子 → 放杯子的板子 → cupboard碗柜"},{"word":"curb","ipa":"/kɜːrb/","pos":"v.","def":"勒住；限制，抑制；  n.约束；路缘；勒马绳","sen":"Curb your horse now before it runs off the cliff!","trans":"在你的马掉下悬崖前，快勒住它！","mne":""},{"word":"cure","ipa":"/kjʊr/","pos":"v.","def":"治愈，治疗","sen":"These pills will cure your sickness.","trans":"这些药丸能治好你的病。","mne":""},{"word":"curiosity","ipa":"/ˌkjʊriˈɑːsəti/","pos":"n.","def":"好奇心","sen":"Curiosity drives the cat to see what is in the box.","trans":"好奇心驱使小猫去看盒子里有什么。","mne":"curi关心 + osity多的状态 → 关心多 → 好奇心"},{"word":"curious","ipa":"/ˈkjʊriəs/ ","pos":"adj.","def":"好奇的","sen":"The cat is curious about the black mouse.","trans":"这只猫对这个黑色鼠标感到好奇。","mne":"curi好奇 + ous形容词后缀 → curious好奇的"},{"word":"currency","ipa":"/ˈkɜːrənsi/","pos":"n.","def":"货币；流通","sen":"The currency of the United States of America is the US dollar.","trans":"美国的流通货币是美元。","mne":"curr跑，发生 + ency表名词，性质状态 → 跑来跑去的钱 → 流通货币"},{"word":"current","ipa":"/ˈkɜːrənt/","pos":"adj.","def":"当前的，现在的；流动的；  n.水流","sen":"I can get all the current news instantly on my cellphone.","trans":"我可以在手机上迅速获取所有的时事新闻。","mne":"curr跑，发生 + ent具有……性质的 → 跑的 → current流动的"},{"word":"currently","ipa":"/ˈkɜːrəntli/","pos":"adv.","def":"现在，目前","sen":"He used to be just a waiter; but currently, he is a successful businessman.","trans":"曾经他只是个服务员，但现在他已经成了一位成功的商人。","mne":"curr =run跑，发生 + ent...的 + ly...地 → current跑的=趋势，普遍 + ly...地 → currently当前，普遍"},{"word":"curriculum","ipa":"/kəˈrɪkjələm/","pos":"n.","def":"课程，（学校或专业的）全部课程","sen":"She color-coded different subjects on her curriculum schedule.","trans":"她把课程表中不同的课用不同的颜色标注。","mne":"curr跑，发生 + iculum表名词 → 学员跑来跑去的 → curriculum课表"},{"word":"curse","ipa":"/kɜːrs/","pos":"n.","def":"诅咒；咒骂；祸因；  v.诅咒；咒骂；使受罪","sen":"I will draw a circle to lay a curse on you.","trans":"我要画个圈圈诅咒你！","mne":""},{"word":"curtain","ipa":"/ˈkɜːrtn/","pos":"n.","def":"窗帘；幕布","sen":"Look! A little girl is hiding behind the curtain!","trans":"看！有个小女孩正躲在窗帘后面！","mne":""},{"word":"curve","ipa":" /kɜːrv/","pos":"v.","def":"使弯曲；  n.曲线；弯曲","sen":"Her lips curved in a smile.","trans":"她咧嘴笑了。","mne":""},{"word":"cushion","ipa":"/ˈkʊʃn/","pos":"n.","def":"靠垫；  v.减轻，缓和","sen":"For added comfort, you can use a lumbar cushion when sitting.","trans":"为了增加舒适度，你可以在坐的时候垫个腰部靠垫。","mne":""},{"word":"custom","ipa":"/ˈkʌstəm/","pos":"n.","def":"风俗","sen":"Paying New Year calls is a traditional custom of Chinese New Year.","trans":"拜年是中国春节的传统习俗。","mne":"cu=com表加强 + stom习惯于 → custom风俗；习惯"},{"word":"customer","ipa":"/ˈkʌstəmər/","pos":"n.","def":"顾客","sen":"Would the customer buy this pair of blue jeans?","trans":"这个顾客会买这条蓝色的牛仔裤吗？","mne":"custom习惯 + er人 → 习惯进商店的人 → customer顾客"},{"word":"customs","ipa":"/ˈkʌstəmz/","pos":"n.","def":"海关；关税","sen":"The customs officer is checking my bag.","trans":"海关工作人员正在检查我的包。","mne":""},{"word":"cut","ipa":"/kʌt/","pos":"v.","def":"切；  v.割，砍；  n.切工；伤口","sen":"I like the way he cuts my hair.","trans":"我喜欢他给我剪头发的方式。","mne":""},{"word":"cycle","ipa":"/ˈsaɪkəl/","pos":"n.","def":"周期，循环；自行车；  v.骑自行车","sen":"The diagram shows the water cycle process.","trans":"这张图表展示了水循环过程。","mne":""},{"word":"dad","ipa":"/dæd/","pos":"n.","def":"爸爸，爹爹","sen":"This dad can do many things at the same time.","trans":"这位父亲能同时做很多事情。","mne":""},{"word":"daddy","ipa":"/ˈdædi/","pos":"n.","def":"<口>爸爸","sen":"This is my daddy.","trans":"这是我爸爸。","mne":""},{"word":"daily","ipa":"/ˈdeɪli/","pos":"adj.","def":"每日的，日常的；  n.日报；  adv.每日，每天，天天","sen":"I like to read the daily paper every morning.","trans":"我喜欢在每天早上读日报。","mne":"dai日子，白天 + ly副词后缀 → daily每日的，日常的"},{"word":"dairy","ipa":"/ˈderi/","pos":"adj.","def":"奶制的，牛奶的；乳品（业）的；  n.乳品店","sen":"Dairy foods contain lots of calcium.","trans":"奶制品富含钙。","mne":"da揉面，管家，女仆 + iry名词后缀 → 提供面包原料的事物 → dairy牛奶的，牛奶厂"},{"word":"damage","ipa":"/ˈdæmɪdʒ/","pos":"v.","def":"破坏；  n.损坏，毁坏，破坏","sen":"My car was badly damaged after hitting the tree.","trans":"我的车在撞上树后严重损坏了。","mne":""},{"word":"damp","ipa":"/dæmp/","pos":"adj.","def":"潮湿的，有湿气的；  v.弄湿，使弄湿","sen":"I had an umbrella, but my clothes still got damp from the rain.","trans":"尽管带了伞，我的衣服还是淋湿了。","mne":""},{"word":"dance","ipa":"/dæns/","pos":"n.","def":"舞；  v.跳舞","sen":"They had a dance battle as they were waiting for the traffic jam to end.","trans":"在等待通车的过程中，他们在斗舞。","mne":""},{"word":"dancer","ipa":"/ˈdænsər/","pos":"n.","def":"舞蹈演员","sen":"My sister is a great dancer.","trans":"我的姐姐是一名很棒的舞蹈演员。","mne":""},{"word":"danger","ipa":"/ˈdeɪndʒər/","pos":"n.","def":"危险，（坏事或不快之事发生的）可能性；危险，危险的物(或人)","sen":"This sign warned us that we were in danger.","trans":"这个指示牌警告我们有危险。","mne":"dan(g)房子，家庭 + er名词后缀，表人或物 → 家庭抵御危险(法语传入) → danger危险"},{"word":"dangerous","ipa":"/ˈdeɪndʒərəs/ ","pos":"adj.","def":"有危险的，不安全的","sen":"It's very dangerous to open the car door without looking back.","trans":"不看后面就打开车门是很危险的。","mne":"danger危险 + ous……的 → 有危险的 → dangerous危险的"},{"word":"dare","ipa":"/der/","pos":"v.","def":"敢于；胆敢","sen":"He dares to walk along the tightrope!","trans":"他竟然敢走钢丝！","mne":""},{"word":"dark","ipa":"/dɑːrk/","pos":"adj.","def":"黑暗的，昏暗的；暗色的；深色的；  n.（尤指夜里的）黑；黑暗，暗处","sen":"It's dark outside and I can't see much.","trans":"外面很黑，我看不清。","mne":""},{"word":"dash","ipa":"/dæʃ/","pos":"v.","def":"猛冲，突进；  n.破折号","sen":"The woman is dashing forward.","trans":"这个女人朝前猛冲。","mne":""},{"word":"data","ipa":"/ˈdeɪtə/","pos":"n.","def":"数据；资料","sen":"A huge amount of data can be stored on a computer.","trans":"一台电脑可以储存大量数据。","mne":""},{"word":"database","ipa":"/ˈdeɪtəˌbeɪs/","pos":"n.","def":"数据库","sen":"A database contains many documents and detailed information.","trans":"一个数据库包含有很多文档和详细信息。","mne":"data数据 + base基地，根据 → database数据库"},{"word":"date","ipa":"/deɪt/","pos":"n.","def":"日期，日子；约会；枣子；  v.约会","sen":"What's the date today?","trans":"今天是几号？","mne":""},{"word":"datum","ipa":"/ˈdeɪtəm/","pos":"n.","def":"数据，资料","sen":"We have set a unique password for every datum.","trans":"我们为每个数据都设置了单独的密码。","mne":""},{"word":"daughter","ipa":"/ˈdɔːtər/","pos":"n.","def":"女儿","sen":"She reads to her daughter.","trans":"她给她的女儿读书。","mne":""},{"word":"dawn","ipa":"/dɔːn/","pos":"n.","def":"黎明；  v.开始","sen":"The rooster standing in the field crows at dawn.","trans":"站在田野里的公鸡在黎明时分打鸣。","mne":""},{"word":"day","ipa":"/deɪ/","pos":"n.","def":"（一）天，一日；【数】一天；时期，时代","sen":"A day has 24 hours.","trans":"一天有24小时。","mne":""},{"word":"dead","ipa":"/ded/","pos":"adj.","def":"死的，无生命的；  n.死者，死人；  adv.完全地","sen":"The fish is dead.","trans":"这条鱼死了。","mne":""},{"word":"deadline","ipa":"/ˈdedlaɪn/","pos":"n.","def":"最后期限","sen":"The employee worked overtime to meet the deadline.","trans":"为了赶最后期限，这名员工加班加点地工作。","mne":"dead死亡 + line直线，线条 → 死亡期限 → 最后期限"},{"word":"deadly","ipa":"/ˈdedli/","pos":"adj.","def":"致命的；极度的；  adv.死一般地；非常","sen":"The mouse died after eating the deadly bread, which had been poisoned.","trans":"那只老鼠吃了带毒药的面包后死了。","mne":"dead死 + ly后缀 → deadly致死的"},{"word":"deaf","ipa":"/def/","pos":"adj.","def":"聋的；不愿听的","sen":"The girl is completely deaf; she can't hear anything.","trans":"这个女孩失聪了，什么也听不见。","mne":""},{"word":"deal","ipa":"/diːl/","pos":"v.","def":"处理，应对；做买卖；  n.交易，协议","sen":"The captain calmly dealt with the danger.","trans":"机长从容地处理了危险。","mne":""},{"word":"dealer","ipa":"/ˈdiːlər/","pos":"n.","def":"经销商，商人，（俚）毒贩","sen":"The car dealer gave us a great deal on our new car.","trans":"买这辆新车时，汽车经销商给了我们很大的优惠。","mne":"deal生意 + er名词后缀：行为的主动者，做某事的人 → n.经销商，商人"},{"word":"dear","ipa":"/dɪr/","pos":"adj.","def":"亲爱的；昂贵的；  n.亲爱的人","sen":"\"I love you so much,\" the father said to his dear son.","trans":"“我非常爱你。”父亲对他亲爱的儿子说。","mne":""},{"word":"death","ipa":"/deθ/","pos":"n.","def":"死亡","sen":"Mr. Egg is crying over the death of his friend.","trans":"蛋先生为他朋友的死而哭泣。","mne":""},{"word":"debate","ipa":"/dɪˈbeɪt/","pos":"v.","def":"辩论；争论，议论；  n.辩论；讨论，争论","sen":"She was on the stage debating with the bearded man.","trans":"克莱尔和大胡子对手在台上激烈辩论。","mne":"de否定，相反 + bat打，击 + e → 持对方相反的观点而与之进行口头上的攻击 → 反驳，辩论"},{"word":"debt","ipa":"/det/","pos":"n.","def":"债；欠款","sen":"The man is burdened with the housing debt.","trans":"这个男人背负着房贷。","mne":""},{"word":"decade","ipa":"/ˈdekeɪd/","pos":"n.","def":"十年，一个年代","sen":"People can change a lot after a decade.","trans":"十年会给人带来很大的变化。","mne":"dec=deca十 + ade名词后缀，表状态 → 十年"},{"word":"decay","ipa":"/dɪˈkeɪ/ ","pos":"v.","def":"腐烂；衰退；  n.腐烂","sen":"These oranges have decayed on top.","trans":"这些橘子从顶部开始腐烂了。","mne":"de向下 + cay落下 → 向下掉 → decay腐烂，衰退"},{"word":"deceive","ipa":"/dɪˈsiːv/","pos":"v.","def":"欺骗，行骗","sen":"The man deceives others by wearing a hilarious mask.","trans":"这个男人用一张搞笑面具来欺骗别人。","mne":"de相反 + ceive拿，抓，握 → deceive欺骗"},{"word":"decelerate","ipa":"/ˌdiːˈseləreɪt/","pos":"v.","def":"（使）减速","sen":"These speed bumps force the driver to decelerate.","trans":"这些减速带迫使司机减速。","mne":"de 降低，减少 + celer 快，速 + ate 表示使之成... → v.(使)减速"},{"word":"december","ipa":"/dɪˈsembər/","pos":"n.","def":"十二月","sen":"Christmas is celebrated in December.","trans":"人们在十二月庆祝圣诞节。","mne":""},{"word":"decent","ipa":"/ˈdiːsnt/","pos":"adj.","def":"体面的，得体的；相当不错的；正派的","sen":"The gentleman in the decent suit displayed great charm.","trans":"这位绅士衣着得体，魅力十足。","mne":"dec合适的 + ent形容词后缀 → decent得体的"},{"word":"decide","ipa":"/dɪˈsaɪd/","pos":"v.","def":"对...做出抉择，决定，下决心","sen":"It's time to decide which way to go.","trans":"是时候决定走哪条路了。","mne":"de使…成为 + cide切 → 切下去 → 下决心 → 决定，决心"},{"word":"decision","ipa":"/dɪˈsɪʒn/","pos":"n.","def":"决定","sen":"Facing three paths in the forest, he made a decision to take the left one.","trans":"面对森林中的三条小道，他决定走左边那条。","mne":"deci决定 + sion名词后缀 → decision决定"},{"word":"decisive","ipa":"/dɪˈsaɪsɪv/","pos":"adj.","def":"决定性的，果断的","sen":"The last judge has the decisive vote in deciding the winner.","trans":"最后一个评委拥有选出胜利者的决定性一票。","mne":"deci决定 + sive形容词后缀 → decisive决定性的"},{"word":"declaration","ipa":"/ˌdekləˈreɪʃən/","pos":"n.","def":"宣言，声明书；宣布，宣告","sen":"The leaders in the room drafted the Declaration of Independence.","trans":"屋子里的几位领导人拟定了《独立宣言》。","mne":"declar宣称 + ation名词后缀 → declaration宣言"},{"word":"declare","ipa":"/dɪˈkler/","pos":"v.","def":"宣布，宣告；断言；申报","sen":"I now declare this meeting open.","trans":"我现在宣布本次会议开始。","mne":"de加强 + clare（拉丁语）澄清 → declare表明，声明"},{"word":"decline","ipa":"/ dɪˈklaɪn /","pos":"n.","def":"衰退，衰落；  v.拒绝，谢绝；婉言拒绝，谢绝；下降；衰退","sen":"The world economy is on a decline.","trans":"世界经济日趋低迷。","mne":"de下 + cline倾斜 → decline下降"},{"word":"decorate","ipa":"/ˈdekəreɪt/","pos":"v.","def":"装饰，布置；装潢","sen":"They are decorating the Christmas tree.","trans":"佩妮和莱纳德正一起装饰圣诞树。","mne":"decor装饰 + ate动词后缀 → decorate装修，装潢"},{"word":"decoration","ipa":"/ˌdekəˈreɪʃn/","pos":"n.","def":"装饰","sen":"There are many pretty decorations on the Christmas tree.","trans":"圣诞树上有许多漂亮的装饰品。","mne":"decor装饰 + ation表示行为、情况、状态、过程、结果 → 装饰，装潢；装饰品；奖章"},{"word":"decrease","ipa":"/dɪˈkriːs/, /ˈdiːkriːs/","pos":"v.","def":"减少；  n.减少","sen":"Our sales have decreased for the last two years, and now we're out of money.","trans":"过去两年我们的销售额都在减少，现在我们没钱了。","mne":"de向下 + crease增长 → 向下增加 → 减少"},{"word":"dedicate","ipa":"/ˈdedɪkeɪt/","pos":"v.","def":"致力于，献出（全部时间、精力等）","sen":"The teacher has dedicated his life to education.","trans":"这位老师把他的一生献给了教育事业。","mne":"de加强 + dic说 + ate使，造成 → 再说 → 努力献身"},{"word":"deed","ipa":"/diːd/","pos":"n.","def":"行为；契约","sen":"The kind man did many good deeds for people.","trans":"这个善良的男人为人们做了很多好事。","mne":""},{"word":"deem","ipa":"/diːm/","pos":"v.","def":"认为，视为","sen":"He deemed the music beautiful.","trans":"他觉得音乐悦耳。","mne":""},{"word":"deep","ipa":"/diːp/","pos":"adj.","def":"深的；  adv.深深地；  n.深处","sen":"No one has found the ship's treasure because it lies deep under the sea.","trans":"没有人能找到船里的宝藏，因为它处于大海中很深的地方。","mne":""},{"word":"deeply","ipa":"/ˈdiːpli/","pos":"adv.","def":"深深地；深刻地；很，非常","sen":"I care deeply for my new baby.","trans":"我深深地牵挂着我刚出生的小宝宝。","mne":"deep深的 + ly副词后缀 → deeply深刻地，浓浓地"},{"word":"deer","ipa":"/dɪr/","pos":"n.","def":"鹿（单复数同形）","sen":"The girl with food was immediately surrounded by deer.","trans":"拿着食物的小女孩被小鹿们迅速围住了。","mne":""},{"word":"defeat","ipa":"/dɪˈfiːt/","pos":"v.","def":"打败，击败，战胜；  n.挫败；失败，战败","sen":"Our team defeated them in the final game.","trans":"我们的球队在决赛中击败了他们。","mne":"de向下 + feat做，制作 → 做下去 → 打下去 → defeat打败，摧毁"},{"word":"defence","ipa":"/dɪˈfens/","pos":"n.","def":"防御，防务，辩护（=defense）","sen":"The iron fence built by the shepherd is a great defence against the wolf.","trans":"牧羊人建造的铁栅栏可以很好地防御狼。","mne":"de从...离开 + fen打，打击 + ce表名词 → defence防御"},{"word":"defend","ipa":"/dɪˈfend/ ","pos":"v.","def":"保卫，防守；为……辩护，为……辩解","sen":"The dog defends its friend with a knife and shield.","trans":"这只小狗用刀和盾保护它的朋友。","mne":"de去掉 + fend打击 → 打退敌人 → defend保卫，防御"},{"word":"defendant","ipa":"/dɪˈfendənt/","pos":"n.","def":"被告人","sen":"The defendant pleaded not guilty to all charges.","trans":"被告人对所有指控都表示无罪。","mne":"de使成… + fend打击 + ant表示人→ 成为被打击的人→ 被告"},{"word":"defender","ipa":"/dɪˈfendər/","pos":"n.","def":"防卫者，拥护者，辩护者，【运动】卫冕者","sen":"This knight is the defender of the King's treasure.","trans":"这个骑士是国王的宝藏的守护者。","mne":"de否定，相反 + fend=strike，表示“打击” + er[名词后缀]，行为的主动者 → defender防卫者，拥护者"},{"word":"defense","ipa":"/dɪˈfens/","pos":"n.","def":"防御，防护；防守","sen":"The iron fence built by the shepherd is a great defense against the wolf.","trans":"牧羊人建造的铁栅栏可以有效地防狼。","mne":"de去掉 + fens打击 + e → 去掉打击 → 打退敌人 → defense保卫"},{"word":"deficiency","ipa":"/dɪˈfɪʃənsi/","pos":"n.","def":"不足，缺乏","sen":"Sleep deficiency may cause dark circles under the eyes.","trans":"睡眠不足可能会导致黑眼圈。","mne":"de不 + fic做 + iency表名词 → 做得不够 → 缺陷"},{"word":"deficit","ipa":"/ˈdefɪsɪt/","pos":"n.","def":"亏损；赤字","sen":"The company was in a financial deficit in 2018.","trans":"该公司在2018年出现了亏损。","mne":"de不 ＋ fic做 ＋ it名词后缀，表抽象名词 → 做得不够 → deficit亏空"},{"word":"define","ipa":"/dɪˈfaɪn/","pos":"v.","def":"给（词、短语等）下定义；界定，解释","sen":"Many believe achieving success defines the American Dream.","trans":"许多人认为“取得成功”能定义美国梦。","mne":"de加强语意 + fine边界 → define下定义"},{"word":"definite","ipa":"/ˈdefɪnət/","pos":"adj.","def":"明确的，肯定的","sen":"The police found definite proof that he committed the crime.","trans":"警方已经掌握明确证据，可以证明是他实施了犯罪。","mne":"defin明确 + ite形容词后缀 → definite明确的"},{"word":"definition","ipa":"/ˌdefɪˈnɪʃn/","pos":"n.","def":"定义，释义；（轮廓等）清晰","sen":"The dictionary contains the definition of thousands of words.","trans":"字典包含了成千上万个词的释义。","mne":"de使…成为 + fin界限 + ition名词后缀 → 划出界限 → 定义 "},{"word":"degree","ipa":"/dɪˈɡriː/","pos":"n.","def":"学位；度；程度","sen":"I finally got my degree after four years of studying.","trans":"经过四年的学习，我终于拿到了学位。","mne":"de下面 + gree一步，一个台阶 → 一个位置和阶段 → degree学位"},{"word":"delay","ipa":"/dɪˈleɪ/","pos":"v.","def":"延误，延迟；磨蹭，使迟到；耽误；  n.延期，耽搁；耽搁（的时间）","sen":"His flight is delayed because of bad weather.","trans":"他的航班由于恶劣的天气晚点了。","mne":"de从...离开 + lay留下，停留 → delay延迟"},{"word":"delegate","ipa":"/ˈdelɪɡeɪt/","pos":"v.","def":"【财】委派；授权（读作/ˈdɛləˌgeɪt/）；  n.代表（读作/ˈdɛləgɪt/）","sen":"Tasks neither urgent nor important should be delegated or binned.","trans":"即不紧急也不重要的任务可以委派他人处理或者直接舍弃。","mne":"de使…成为，加强 + leg法律 + ate动词后缀 → 加强法律 → delegate授权"},{"word":"delete","ipa":"/dɪˈliːt/","pos":"v.","def":"删除","sen":"Remember to delete your search history.","trans":"记得及时删除你的搜索记录。","mne":"de离开 + lete弄脏 → delete除"},{"word":"deliberate","ipa":"/dɪˈlɪbərət/","pos":"adj.","def":"故意的；  v.仔细考虑","sen":"The boy made a deliberate attempt to annoy the girl.","trans":"男孩故意要惹女孩生气。","mne":"de否定 + liber自由 + ate……的 → 不是任意而为 → deliberate故意的"},{"word":"deliberately","ipa":"/dɪˈlɪbərətli/","pos":"adv.","def":"故意地；慢条斯理地，从容不迫地","sen":"Why does he deliberately try to make other people fall over?","trans":"他为什么故意绊倒别人？","mne":"deliberate故意的 + ly……地 → deliberate不是任意而为=故意的"},{"word":"delicate","ipa":"/ˈdelɪkət/","pos":"adj.","def":"易碎的，脆弱的；精美的，精致的；（人）娇弱的，体弱多病的","sen":"The vase is delicate and should be packed with care.","trans":"花瓶易碎，应小心打包。","mne":"de远离 + licate诱惑，吸引 → 易损坏但有吸引力的 → delicate精致的，易碎的"},{"word":"delicious","ipa":"/dɪˈlɪʃəs/ ","pos":"adj.","def":"美味的，可口的","sen":"The rice noodles my brother is cooking look so delicious!","trans":"我哥哥煮的米粉看起来真美味！","mne":"de再 + lic诱惑 + ious表形容词 → 再引诱的 → delicious美味的，可口的"},{"word":"delight","ipa":"/dɪˈlaɪt/","pos":"n.","def":"快乐；高兴事；  v.使快乐","sen":"To the delight of the children, the ice cream truck stopped right in front of the house.","trans":"令孩子们万分高兴的是，冰淇淋车正好停在房子前面。","mne":"de完全地 + light诱惑 → 完全将其迷惑住 → delight使高兴"},{"word":"delighted","ipa":"/dɪˈlaɪtɪd/","pos":"adj.","def":"高兴的，愉快的","sen":"She is delighted that she finished her work.","trans":"她很高兴她完成了工作。","mne":"de加强意义 + light光明 + ed…的 → 阳光的 → delighted欣喜的，快乐的"},{"word":"deliver","ipa":"/dɪˈlɪvər/","pos":"v.","def":"递送，交付；发表（演讲）；分娩；传达","sen":"The man delivers the packages to the woman.","trans":"男人把包裹送到这位女士的手上。","mne":"de离开 + liver自由 → deliver投递，投送"},{"word":"delivery","ipa":"/dɪˈlɪvəri/","pos":"n.","def":"递送；分娩；交付","sen":"The delivery service aims to deliver each package as quickly as possible.","trans":"投递服务旨在尽快派送每个包裹。","mne":"de完全 + liver释放 + y形容词后缀 → 快递;投递;交付;分娩"},{"word":"demand","ipa":"/dɪˈmænd/","pos":"v.","def":"强烈要求，坚决要求；  n.需求，需要","sen":"He has always demanded some unreasonable things from his children.","trans":"他总是向子女们提出一些无理的要求。","mne":"de加强 + mand命令 → demand要求"},{"word":"democracy","ipa":"/dɪˈmɑːkrəsi/","pos":"n.","def":"民主制度；民主国家；民主主义；民众","sen":"Voting is an important part of democracy.","trans":"投票是民主制度的一个重要部分。","mne":"demo人民 + cracy统治 → democracy民主政治"},{"word":"democratic","ipa":"/ˌdeməˈkrætɪk/","pos":"adj.","def":"民主的，民主政体的，民主党的","sen":"In a democratic society, everyone has the right to vote.","trans":"在一个民主的国家，人民有权投票选举。","mne":"demo人民 + cr + atic…的 → 民主的，民主主义的；民主政体的"},{"word":"demonstrate","ipa":"/ˈdemənstreɪt/","pos":"v.","def":"演示，展示；（用实例、实验）论证；示范；示威","sen":"The salesman demonstrates how the device works on a watermelon.","trans":"推销员在演示怎么操作切瓜神器。","mne":"de加强 + monstr指出 + ate动词后缀 → 特别指出 → demonstrate证明"},{"word":"demonstration","ipa":"/ˌdemənˈstreɪʃ(ə)n/","pos":"n.","def":"示范表演，演示","sen":"He gave a demonstration of how to use the new smartphone.","trans":"他对如何使用新的智能手机进行了演示。","mne":"de加强 + monstr显示 + ation表名词 → 证明；示威游行"},{"word":"dense","ipa":"/dens/","pos":"adj.","def":"稠密的，浓密的；愚钝的","sen":"This area is very dense with so many buildings everywhere.","trans":"这是一片密集的区域，到处都是建筑物。","mne":""},{"word":"density","ipa":"/ˈdensəti/","pos":"n.","def":"密度；密集，稠密","sen":"The high density of buildings makes the city so crowded.","trans":"这个城市的建筑密度很高，所以城市也非常拥挤。","mne":"dens稠密的 + ity名词后缀表性质 → 稠密 → density稠度，密度"},{"word":"dentist","ipa":"/ˈdentɪst/","pos":"n.","def":"牙科医生","sen":"The dentist explained the procedure to the patient before starting the treatment.","trans":"牙科医生在开始治疗前向病人解释了整个过程。","mne":"dent牙齿 + ist人 → dentist牙科医生"},{"word":"deny","ipa":"/dɪˈnaɪ/","pos":"v.","def":"否认；拒绝","sen":"The little boy denied breaking the window.","trans":"小男孩否认是他打破了窗户。","mne":"de向下 + ny=neg否决 → deny否认"},{"word":"depart","ipa":"/dɪˈpɑːrt/","pos":"v.","def":"离开，出发；离职","sen":"The steamship just departed from the dock.","trans":"这艘蒸汽轮船刚刚离开了港口。","mne":"de从 + part分开 → depart离开"},{"word":"department","ipa":"/dɪˈpɑːrtmənt/","pos":"n.","def":"部门；（大学）系，部","sen":"Our company consists of three departments.","trans":"我们公司由三个部门组成。","mne":"de加强意义 + part部分 + ment名词后缀 → 一部分 → department部门，系"},{"word":"departure","ipa":"/dɪˈpɑːrtʃər/","pos":"n.","def":"离开；出发","sen":"His departure from home made his family sad.","trans":"他离开了家，这使其家人感到悲伤。","mne":"depart出发 + ure名词后缀 → departure离开，出发"},{"word":"depend","ipa":"/dɪˈpend/","pos":"v.","def":"依靠；依赖","sen":"Sometimes people have to depend on others for help.","trans":"有时候，人们不得不依靠他人的帮助。","mne":"de加强 + pend挂  → 挂在...上面  → depend依靠；依赖"},{"word":"dependent","ipa":"/dɪˈpendənt/ ","pos":"adj.","def":"依赖的；  n.依赖他人者","sen":"Ever since the accident, she's been dependent on her son to help her get around.","trans":"那场车祸后，她的行动就一直依赖她儿子。","mne":"depend依靠 + ent形容词后缀 → dependent依靠的"},{"word":"deposit","ipa":"/dɪˈpɑːzɪt/","pos":"v.","def":"存钱；沉淀；  n.存款","sen":"I deposit money in my piggy bank when I get money.","trans":"当我有钱时我会往我的存钱罐里存钱。","mne":"de下 + posit放 → deposit储存"},{"word":"depress","ipa":"/dɪˈpres/","pos":"v.","def":"使沮丧；压下，压低；使萧条；  v.降低(价格)","sen":"Life depresses him so he drinks some liquor.","trans":"生活使他感到沮丧，于是他借酒消愁。","mne":"de向下 + press压 → depress压下；使沮丧"},{"word":"depressed","ipa":"/dɪˈprest/","pos":"adj.","def":"沮丧的；意志消沉的","sen":"He felt very depressed when he got fired.","trans":"被解雇时，他感到非常沮丧。","mne":"de向下 + press挤压 + ed形容词后缀 → 向下挤压的 → depressed感到压抑的"},{"word":"depressing","ipa":"/dɪˈpresɪŋ/","pos":"adj.","def":"使人沮丧的","sen":"The lonely woman found tea time to be very depressing without anyone to talk to.","trans":"没有人和她谈话，这位孤独老妇人觉得下午茶变得令人沮丧。","mne":"de使成… + press挤压 + ing...的 → depressing压抑的；使人沮丧的"},{"word":"depression","ipa":"/dɪˈpreʃn/","pos":"n.","def":"抑郁，沮丧；不景气，萧条（期）；洼地，凹陷","sen":"My cat sank into a deep depression since I had a boyfriend.","trans":"自从我有了男朋友，我的猫就陷入了深深的抑郁之中。","mne":"de向下 + press挤压 + ion名词后缀 → 向下挤压 → 沮丧；萧条"},{"word":"deprive","ipa":"/dɪˈpraɪv/","pos":"v.","def":"使丧失；剥夺","sen":"The baby cried as his friend deprived him of the toy.","trans":"这个婴儿哭了，因为他的朋友抢走了他的玩具。","mne":"de去掉 + prive单个 → 从个人身边拿走 → 剥夺，夺去"},{"word":"depth","ipa":"/depθ/","pos":"n.","def":"深度；深刻","sen":"These fish dived to a depth of 150 meters.","trans":"这些鱼潜至水下150米深处。","mne":"dep深的 + th名词后缀 → depth深度"},{"word":"derive","ipa":"/dɪˈraɪv/","pos":"v.","def":"源自；获得；得自","sen":"The English word \"teacher\" derives from the root word \"teach\".","trans":"英文单词“teacher”一词来源于词根“teach”。","mne":"de离开 + riv河流 + e → 派生，得出"},{"word":"describe","ipa":"/dɪˈskraɪb/","pos":"v.","def":"描述","sen":"She described her missing child to a passer-by.","trans":"她向一位路人描述她走失的孩子的模样。","mne":"de表加强 + scribe写 → describe描写"},{"word":"description","ipa":"/dɪˈskrɪpʃn/","pos":"n.","def":"描写，形容，叙述","sen":"The policeman asked the girl to give a description of the criminal.","trans":"警察让女孩描述一下犯罪嫌疑人的样子。","mne":"de向下 + script写 + ion表名词 → 写下来 → description描写"},{"word":"desert","ipa":"/ˈdezərt/, /dɪˈzɜːrt/","pos":"n.","def":"荒漠，沙漠（读作/ˈdezərt/）；  v.离弃（读作/dɪˈzɜːt/）","sen":"I finally found water in the desert.","trans":"我终于在沙漠里找到水了。","mne":"de分开 + sert加入，插入 → 不再加入 → desert离开"},{"word":"deserve","ipa":"/dɪˈzɜːrv/","pos":"v.","def":"值得，应得；应受","sen":"She deserves a pat on the back for all her hard work.","trans":"她工作兢兢业业，值得嘉许。","mne":"de加强语气 + serve为…服务 → deserve值得，应得"},{"word":"design","ipa":"/dɪˈzaɪn/","pos":"n.","def":"设计（方案）；  v.设计，构思","sen":"The design for the house looks great - now let's build it!","trans":"这个房子的设计很棒，现在我们来建造它吧！","mne":"de使…成为，加强 ＋ sign写，做标志 → design设计，计划"},{"word":"designer","ipa":"/dɪˈzaɪnər/","pos":"n.","def":"设计师","sen":"I am a fashion designer; I design clothes for women.","trans":"我是一个服装设计师，专门设计女装。","mne":"design设计 + er名词后缀：人 → designer设计师"},{"word":"desirable","ipa":"/dɪˈzaɪərəbl/","pos":"adj.","def":"令人向往的；理想的，值得拥有的；令人满意的","sen":"Doctors are seen as a high status and desirable profession.","trans":"医生被视为社会地位高、令人向往的职业。","mne":"desir=desirede渴望 + able能……的 → 值得要的"},{"word":"desire","ipa":"/dɪˈzaɪər/","pos":"n.","def":"渴望；欲望；愿望；要求；  v.有希望，期望，愿望；  v.希望，渴望；请求，要求","sen":"The cat is filled with the desire to eat the fish.","trans":"这只猫心里充满了想要吃掉这条鱼的渴望。","mne":""},{"word":"desk","ipa":"/desk/","pos":"n.","def":"书桌，办公桌","sen":"There is an empty desk right here.","trans":"这儿有一张空的桌子。","mne":""},{"word":"despair","ipa":"/dɪˈsper/","pos":"n.","def":"绝望；  v.绝望，感到无望","sen":"\"All of my money is gone!\" the man cried in despair.","trans":"“我的钱全没了！”这个男人绝望地哭喊道。","mne":"de去掉 + spair希望 → despair 绝望"},{"word":"desperate","ipa":"/ˈdespərət/","pos":"adj.","def":"绝望的；拼命的；极需要的，渴望的","sen":"She made a desperate cry for help in the fire.","trans":"她在大火中发出绝望的呼喊。","mne":"de去掉 + sper希望 + ate动词后缀 → 去掉希望 → desperate绝望的"},{"word":"despite","ipa":"/dɪˈspaɪt/","pos":"prep.","def":"尽管，不顾","sen":"Despite the windy day, the reporter was still working outdoors.","trans":"尽管风很大，这名记者仍然在户外工作。","mne":"de向下 + spite看向，观察  → despite尽管"},{"word":"dessert","ipa":"/dɪˈzɜːrt/","pos":"n.","def":"餐后甜点","sen":"I’d like to have some dessert with a cup of tea after dinner.","trans":"吃完晚饭后，我还想吃些甜点、喝杯茶。","mne":"des去掉，取消 + sert服务 → 停止正餐服务，上甜点 → dessert甜点"},{"word":"destination","ipa":"/ˌdestɪˈneɪʃn/","pos":"n.","def":"目的地；终点","sen":"The destination of their journey was the Western Heaven.","trans":"他们此行的目的地是西天。","mne":"de向下 + stin站立 + ation名词后缀 → 下一个立足点 → destination目的地，目标"},{"word":"destroy","ipa":"/dɪˈstrɔɪ/","pos":"v.","def":"摧毁；破坏","sen":"My computer was completely destroyed in the fire.","trans":"我的电脑被大火毁尽了。","mne":"de向下，表否定 + stroy建立 → destroy毁灭"},{"word":"destruction","ipa":"/dɪˈstrʌkʃn/","pos":"n.","def":"破坏，毁灭","sen":"The war caused the destruction of the city.","trans":"这场战争毁了整座城市。","mne":"destruct破坏 + ion名词后缀 → destruction破坏"},{"word":"detail","ipa":"/ˈdiːteɪl/","pos":"n.","def":"细节；  v.详细说明；派遣","sen":"When the leaf is seen up close, you can see a lot of fine details.","trans":"近距离看树叶时，你可以看到很多细节。","mne":"de向下 + tail切割 → detail 细节"},{"word":"detailed","ipa":"/ˈdiːteɪld/","pos":"adj.","def":"详细的","sen":"This is a detailed roadmap.","trans":"这是一份详细的路线图。","mne":""},{"word":"detect","ipa":"/dɪˈtekt/ ","pos":"v.","def":"探测；察觉","sen":"The dog can detect drugs with its nose.","trans":"狗可以用它的鼻子探测毒品。","mne":"de打开 + tect遮盖 → detect发觉，侦查"},{"word":"detection","ipa":"/dɪˈtekʃn/","pos":"n.","def":"侦查；检测","sen":"Good eyes are required for detection of tiny objects.","trans":"对微小物体的侦查需要好眼力。","mne":"detect发觉 + ion表名词 → detection发觉"},{"word":"detective","ipa":"/dɪˈtektɪv/","pos":"n.","def":"侦探，警探；  adj.侦探的","sen":"A detective must know how to see through people's lies.","trans":"侦探必须知道如何看穿人们的谎言。","mne":"de相反 + tect掩盖 + ive...的 → 无法掩盖 → 发现 → detective侦探；侦探的"},{"word":"determination","ipa":"/dɪˌtɜːrmɪˈneɪʃn/","pos":"n.","def":"决心；查明，测定","sen":"His determination helps him lose weight through exercise.","trans":"他的决心帮助他通过运动减肥。","mne":""},{"word":"determine","ipa":"/dɪˈtɜːrmɪn/","pos":"v.","def":"下决心；做决定；确定，测定","sen":"The chubby dog is determined to lose weight.","trans":"这只胖狗下定决心要减肥。","mne":"de加强动作 + termin界限 + e → 加强界限 → determine下决心"},{"word":"develop","ipa":"/dɪˈveləp/","pos":"v.","def":"发展，壮大；逐渐形成，逐渐养成","sen":"The city's road system is developing very rapidly.","trans":"这座城市的道路系统发展地非常迅速。","mne":"de不 + velop盖上 → 不阻止，不掩盖 → develop发展"},{"word":"development","ipa":"/dɪˈveləpmənt/ ","pos":"n.","def":"发展；成长；壮大；开发","sen":"This picture shows the development of phones over time.","trans":"这张图展示了电话发展变化的历程。","mne":"develop发展 + ment名词后缀 → development发展"},{"word":"device","ipa":"/dɪˈvaɪs/","pos":"n.","def":"【计】设备；装置，设备；手段，计谋；方法","sen":"The AI algorithm runs on a powerful machine learning device.","trans":"AI算法在一个功能强大的机器学习设备上运行。","mne":""},{"word":"devise","ipa":"/dɪˈvaɪz/","pos":"v.","def":"设计，想出；发明","sen":"They devised a plan for their company's future.","trans":"他们制定了公司未来发展计划。","mne":"de加强意义 + vis =separate分开 + e → 使分开的部件组装成新的发明 → devise设计，发明"},{"word":"devote","ipa":"/dɪˈvoʊt/","pos":"v.","def":"献身于，专心致力于，把……专用于","sen":"The chicken jumped into the pot and devoted his life to us.","trans":"这只鸡跳进锅里，为我们献出了生命。","mne":"de加强 + vot发誓 + e → 拼命发誓，以命起誓 → devote将…奉献，致力于"},{"word":"devotion","ipa":"/dɪˈvoʊʃn/","pos":"n.","def":"奉献，献身于...；热爱","sen":"Many people show great devotion to their professions, such as doctors, scientists, and soldiers.","trans":"许多人展示了他们对职业的非凡投入，比如医生、科学家以及士兵。","mne":"devot献身 + ion名词后缀 → devotion献身，投入"},{"word":"diagnose","ipa":"/ˌdaɪəɡˈnoʊs/ ","pos":"v.","def":"诊断","sen":"The doctor used several tests to diagnose the patient’s condition.","trans":"医生用了几项检查来诊断患者的病情。","mne":"dia穿过，二者之间 + gnos知道 + e → diagnose诊断(疾病)，对（病人）下诊断结论"},{"word":"diagram","ipa":"/ˈdaɪəɡræm/","pos":"n.","def":"图表；图解，示意图","sen":"The diagram in this textbook shows how the water cycle works.","trans":"这本教科书中的图解展示了水循环的过程。","mne":"dia穿过，二者之间 + gram写，图 → 交叉对着画 → 图表"},{"word":"dial","ipa":"/ˈdaɪəl/","pos":"v.","def":"拨（电话号码）；  n.仪表盘","sen":"I am dialing a number on my phone.","trans":"我正在手机上拨电话号码。","mne":""},{"word":"dialect","ipa":"/ˈdaɪəlekt/","pos":"n.","def":"方言","sen":"They come from two different areas, so they speak different dialects.","trans":"他们来自两个不同的地区，所以他们说不同的方言。","mne":"dia在…之间 + lect讲，读 → 在一部分人之间说 → dialect方言"},{"word":"dialog","ipa":"/ˈdaɪəlɔːɡ/","pos":"n.","def":"对话（=dialogue）","sen":"The two sides entered into a peace dialog.","trans":"双方进行了一次和平对话。","mne":"dia穿过，之间 + log说话 → dialog对话"},{"word":"dialogue","ipa":"/ˈdaɪəlɔːɡ/","pos":"n.","def":"对话，对白（=dialog）","sen":"These two women are having a dialogue about their babies.","trans":"这两个女人在谈论她们的小孩。","mne":"dia穿过，二者之间 + logue话 → 对着说话 → dialogue对话"},{"word":"diameter","ipa":"/daɪˈæmɪtər/","pos":"n.","def":"直径","sen":"The worker was measuring the lumber's diameter.","trans":"工人正在测量木材的直径。","mne":"dia穿过，二者之间 + meter测量 → 穿过两者之间测量 → diameter直径"},{"word":"diamond","ipa":"/ˈdaɪəmənd/","pos":"n.","def":"钻石；菱形；金刚石","sen":"The diamond is shining brightly.","trans":"这枚钻石闪闪发光。","mne":"diam=adam强硬的，不屈服的 + ond → 坚硬的石头 → 钻石"},{"word":"diary","ipa":"/ˈdaɪəri/","pos":"n.","def":"日记","sen":"The girl keeps a diary every day.","trans":"这个女孩每天都写日记。","mne":"di日子 + ary表名词 → diary日记"},{"word":"dictation","ipa":"/dɪkˈteɪʃn/","pos":"n.","def":"口述；听写","sen":"He asked her to write down his dictation.","trans":"他请她把自己的口述写下来。","mne":"dictat口授 + ion名词后缀 → 用嘴说的 → dictation口授，命令"},{"word":"dictionary","ipa":"/ˈdɪkʃəneri/","pos":"n.","def":"词典，字典","sen":"Use this dictionary if there are any words you don't know.","trans":"如果有不认识的单词，用这本词典查查。","mne":"dict说话，断言 + ion行为 + ary表名词 → 措词的书 → dictionary字典"},{"word":"die","ipa":"/daɪ/","pos":"v.","def":"死亡；消亡","sen":"The leader lying on the ground died during the fight.","trans":"杰出的三代火影在保卫木叶村的斗争中死去了。","mne":""},{"word":"differ","ipa":"/ˈdɪfər/","pos":"v.","def":"使……相异，使……不同","sen":"The red paper guy differs from the others in color.","trans":"这个红纸人的颜色不同于其他人。","mne":"di分开 + ffer运行 → differ不同"},{"word":"difference","ipa":"/ˈdɪfrəns/","pos":"n.","def":"差别；分歧","sen":"Their height difference is easy to see.","trans":"他们的身高差显而易见。","mne":"differ不同 + ence名词后缀 → difference差异"},{"word":"different","ipa":"/ˈdɪfrənt/","pos":"adj.","def":"分别的，不同的","sen":"The red tomato looks so different from others.","trans":"红色的西红柿看起来与其他的如此不同。","mne":"differ相异 ＋ ent...的 → 相异的 → different不同的"},{"word":"difficult","ipa":"/ˈdɪfɪkəlt/","pos":"adj.","def":"困难的，难做的","sen":"It is difficult for her to carry such a huge stone.","trans":"让她搬起这么大的一块石头实在太难了。","mne":"dif不 + fic做 + ult表名词 → 不好做 → difficult困难的"},{"word":"difficulty","ipa":"/ˈdɪfɪkəlti/","pos":"n.","def":"困难，困境","sen":"He is having difficulty holding up the board.","trans":"他很难一直举着这块木板。","mne":"difficult困难的 + y表名词 → difficulty困难"},{"word":"dig","ipa":"/dɪɡ/","pos":"v.","def":"挖掘，掘出；看中；  n.挖苦","sen":"The dog is digging a hole.","trans":"这只狗正在挖洞。","mne":""},{"word":"digest","ipa":"/daɪˈdʒest/","pos":"v.","def":"消化；领会，理解（读作/daɪˈdʒest/）；  n.摘要（读作/ˈdaɪˌdʒest/）","sen":"Many parts of your body are involved in digesting food.","trans":"你身体中有很多的部位共同参与了食物的消化过程。","mne":"di分离 + gest执行 → digest消化"},{"word":"digital","ipa":"/ˈdɪdʒɪtl/","pos":"adj.","def":"数字显示的；数码的","sen":"This is a black digital stopwatch.","trans":"这是一块黑色的数码秒表。","mne":""},{"word":"dilemma","ipa":"/dɪˈlemə/ /daɪˈlemə/","pos":"n.","def":"进退两难的窘境","sen":"The man swinging on the rope found himself in a dilemma.","trans":"在绳子上摇摆的男人发现自己进退两难。","mne":"di两个，双 + lemma争论 → 二种争论 → dilemma进退两难"},{"word":"dim","ipa":"/dɪm/","pos":"adj.","def":"暗淡的；  v.（使）变暗淡","sen":"This lamp gives out a dim light.","trans":"这盏灯发出一束微弱的亮光。","mne":""},{"word":"dimension","ipa":"/dɪˈmɛnʃən/","pos":"n.","def":"维，维度；尺寸","sen":"These different shapes have three dimensions.","trans":"这些不同的图形都是三维的。","mne":"di=dis不同的方向 + men测量 + ion名词后缀 → dimension维度"},{"word":"dine","ipa":"/daɪn/","pos":"v.","def":"吃饭，用餐","sen":"After finally meeting again, they sat down to dine.","trans":"终于再次见面后，他们坐下来一起吃饭。","mne":""},{"word":"dinner","ipa":"/ˈdɪnər/","pos":"n.","def":"正餐，主餐，（现通例指）晚餐","sen":"The family enjoyed a big dinner.","trans":"全家人享受了丰盛的晚餐。","mne":"di打破，与...相反 + nner空腹，饥饿 → 打破饥饿的状态吃大餐 → dinner正餐，晚餐"},{"word":"diplomat","ipa":"/ˈdɪpləmæt/","pos":"n.","def":"外交官，外交家","sen":"The diplomat represents his country to make agreements with other countries.","trans":"外交官代表他的国家与他国达成协议。","mne":"diploma公文 + t=ate表名词 → diplomate的简化 → diplomat外交官，外交家"},{"word":"direct","ipa":"/dəˈrekt/","pos":"v.","def":"指导，引导；  adj.直接的","sen":"He used his hands to direct the person the right way.","trans":"关谷伸出双手为迪诺哥引路。","mne":"di使...变成 + rect直 → direct直接；直接的"},{"word":"direction","ipa":"/dəˈrekʃn/  /daɪˈrekʃn/","pos":"n.","def":"方向，方位；指导，管理；指引，指示","sen":"There are two different directions, left and right.","trans":"这里有左和右两个不同的方向。","mne":"di通过 + rect正，直 + ion名词后缀 → 通过正确的道路 → direction指示，指引，说明，指导"},{"word":"directly","ipa":"/daɪˈrektli/, /dɪˈrektli/ ","pos":"adv.","def":"直接地，径直地；立即；坦率地；  conj.一……就……","sen":"Why take the long way while you can walk directly to the company?","trans":"既然你能径直走去公司，为什么还要绕远路？","mne":"di使...变成 + rect直 + ly…地 → direct直接的 + ly...地 → 直接地"},{"word":"director","ipa":"/dəˈrektər/","pos":"n.","def":"（电影、戏剧等的）导演；经理，董事；主任","sen":"\"Cut!\" the director shouted while shooting a film.","trans":"“卡!”导演在拍摄电影的时候大叫道。","mne":"di使……变成 + rect表示直 + or表示人 → director指导者，导演"},{"word":"dirt","ipa":"/dɜːrt/","pos":"n.","def":"灰尘，污垢；泥土","sen":"The vacuum cleaner helps me get rid of the dirt.","trans":"真空吸尘器帮我除去灰尘。","mne":""},{"word":"dirty","ipa":"/ˈdɜːrti/","pos":"adj.","def":"肮脏的，有灰尘的","sen":"His hands are very dirty.","trans":"他的手很脏。","mne":"dirt灰 + y表形容词 → dirty肮脏的，有灰尘的"},{"word":"disabled","ipa":"/dɪsˈeɪbld/","pos":"adj.","def":"有残疾的","sen":"The disabled old man wants to go upstairs.","trans":"这位残疾老人想上台阶。","mne":"dis没有 + abl=able能力 + ed形容词后缀 → 伤残的，丧失能力"},{"word":"disadvantage","ipa":"/ˌdɪsədˈvæntɪdʒ/","pos":"n.","def":"不利地位，不利条件，弱点；  v.使不利","sen":"When the books fell, the tall boy was at a disadvantage, unlike the short one.","trans":"当书掉落时，不像矮个男孩，高个男孩处于不利地位。","mne":"dis不，非 + advantage优点 → disadvantage缺点"},{"word":"disagree","ipa":"/ˌdɪsəˈɡriː/","pos":"v.","def":"不同意，有分歧，持不同意见；（陈述或报道）不一致，不相符","sen":"She disagreed with his advice.","trans":"她不赞同他提出的建议。","mne":"dis否定 + agree赞同 → disagree不同意"},{"word":"disappear","ipa":"/ˌdɪsəˈpɪr/","pos":"v.","def":"消失；不见","sen":"How amazing it is that he can make a bird disappear!","trans":"他能把一只鸟变没了，真是太神奇了！","mne":"dis否定 + appear出现 → disappear消失"},{"word":"disappoint","ipa":"/ˌdɪsəˈpɔɪnt/","pos":"v.","def":"使失望，使受挫折；使失望，使落空","sen":"The exam result disappointed him.","trans":"考试成绩让他很失望。","mne":"dis不 + appoint预约 → 失约 → 失望 → 使失望；受挫折"},{"word":"disappointed","ipa":"/ˌdɪsəˈpɔɪntɪd/","pos":"adj.","def":"失望的，沮丧的","sen":"He felt quite disappointed about his test score.","trans":"他对他这次的考试成绩失望透顶。","mne":"dis非，不是 + appoint约定 + ed形容词后缀 → disappointed失望的"},{"word":"disappointing","ipa":"/ˌdɪsəˈpɔɪntɪŋ/","pos":"adj.","def":"令人失望的","sen":"I found the contents of my gift to be very disappointing.","trans":"当我看到礼物是什么的时候，我感到非常失望。","mne":""},{"word":"disapprove","ipa":"/ˌdɪsəˈpruːv/","pos":"v.","def":"不同意","sen":"The girl disapproved of having pizza for dinner.","trans":"那个女孩不赞成晚餐吃比萨。","mne":"dis不 + ap一再 + prove测试，证明 → 不一再证明 → disapprove不赞成"},{"word":"disaster","ipa":"/dɪˈzæstər/","pos":"n.","def":"灾难，天灾","sen":"The entire city is destroyed. What a disaster!","trans":"整个城市都被毁了，真是场灾难！","mne":"dis不 ＋ aster星 → 星位不正，表示有灾难 → disaster灾难，灾祸"},{"word":"disc","ipa":"/dɪsk/","pos":"n.","def":"唱片；圆盘，盘状物；[计] 磁盘，磁碟片","sen":"The music is stored in the disc.","trans":"音乐储存在这张唱片里。","mne":""},{"word":"discharge","ipa":"/disˈtʃɑrdʒ/","pos":"v.","def":"卸（货）；释放","sen":"How long will the discharge of the container cargo take?","trans":"卸载货柜装货物要花多久？","mne":"dis取消 + charge充电 → discharge放电"},{"word":"discipline","ipa":"/ˈdɪsəplɪn/ ","pos":"n.","def":"纪律；学科；  v.训练；惩罚，管制","sen":"These soldiers are showing great discipline.","trans":"这些士兵展现出很强的纪律性。","mne":"dis分散 + cip拿 + line一条直线 → 使分散的成为一条直线 → discipline纪律"},{"word":"disciplined","ipa":"/ˈdɪsəplɪnd/","pos":"adj.","def":"遵守纪律的","sen":"Mr. Bear, who is disciplined, has never broken the rules.","trans":"遵守纪律的熊先生从未违反过规则。","mne":""},{"word":"disconnect","ipa":"/ˌdɪskəˈnekt/","pos":"v.","def":"断开，拆开，使分离；【航】断开","sen":"The phone company disconnected my phone service because I didn't pay my bill.","trans":"电话公司切断了对我的服务，因为我没有付我的账单。","mne":"dis分开 + con共同 + nect连结 → 拆开，分离"},{"word":"discount","ipa":"/ˈdɪskaʊnt/, /dɪsˈkaʊnt/","pos":"n.","def":"折扣（读作/ˈdɪskaʊnt/）；  v.打折（读作/dɪsˈkaʊnt/）","sen":"We can buy many goods with great discounts during sales.","trans":"我们可以在打折季买到很多打折商品。","mne":"dis取消 + count数量 → 取消一些金钱的花费 → discount折扣"},{"word":"discourage","ipa":"/dɪsˈkɜːrɪdʒ/","pos":"v.","def":"劝阻；使泄气","sen":"The bad weather discouraged her from having a picnic.","trans":"这糟糕的天气使她不能外出野餐。","mne":"dis除去，取消 + courage勇气 → discourage使失去勇气"},{"word":"discover","ipa":"/dɪˈskʌvər/","pos":"v.","def":"找到；发现；查明","sen":"The expert discovered a vase from the Tang dynasty.","trans":"这名专家发现了一个唐朝的花瓶。","mne":"dis相反 + cover盖 → 把盖揭开 → discover发现"},{"word":"discovery","ipa":"/dɪˈskʌvəri/","pos":"n.","def":"发现；发觉","sen":"The discovery of liquid water on Mars is exciting to us.","trans":"在火星上发现液态水是一件激动人心的事。","mne":"discover发现 + y名词后缀 → discovery发现"},{"word":"discriminate","ipa":"/dɪˈskrɪmɪneɪt/","pos":"v.","def":"歧视；区别，辨别","sen":"Discriminating against others is a bad behavior.","trans":"歧视他人是不好的行为。","mne":"dis分开，分离 + crimin分辨 + ate动词后缀 → discriminate分辩开"},{"word":"discrimination","ipa":"/dɪˌskrɪmɪˈneɪʃn/","pos":"n.","def":"区别对待；辨别力，识别力；歧视","sen":"This little duck suffers discrimination for its different look from others.","trans":"这只小鸭子因为长相不同而受到区别对待。","mne":"discriminat(e)歧视 + ion名词后缀 → discrimination歧视"},{"word":"discuss","ipa":"/dɪˈskʌs/","pos":"v.","def":"讨论，商量；详述，论述","sen":"The students discussed the topic on the blackboard.","trans":"学生们讨论了黑板上的话题。","mne":"dis分开，分离 + cuss敲打 → 把问题分开敲 → discuss讨论"},{"word":"discussion","ipa":"/dɪˈskʌʃn/","pos":"n.","def":"讨论，谈论","sen":"The teacher and kids are in a discussion about the Earth.","trans":"老师和孩子们在进行一场关于地球的讨论。","mne":"discuss讨论 + ion名词后缀 → discussion讨论"},{"word":"disease","ipa":"/dɪˈziːz/","pos":"n.","def":"疾病，病","sen":"There is a disease spreading around the family.","trans":"有一种疾病在这家人之间传播。","mne":"dis没有 + ease安逸 → 不舒服 → disease疾病"},{"word":"disguise","ipa":"/dɪsˈɡaɪz/","pos":"v.","def":"伪装；掩饰，掩盖；  n.伪装；伪装物","sen":"Miss Bear disguised herself as a panda by wearing black stockings.","trans":"熊小姐穿上黑色长袜把自己伪装成了一只熊猫。","mne":"dis相反 + guise外貌，外在的样子 → 掩盖外表 → disguise伪装"},{"word":"disgust","ipa":"/dɪsˈɡʌst/","pos":"v.","def":"使作呕，使厌恶；  n.恶心","sen":"The smell in the car disgusted him.","trans":"车里的气味让他感到恶心。","mne":"dis与...相反 + gust尝 → disgust使作呕"},{"word":"disgusting","ipa":"/dɪsˈɡʌstɪŋ/","pos":"adj.","def":"令人厌恶的；令人恶心的；令人无法接受的","sen":"He finds the smell of the sock disgusting.","trans":"这只袜子的味道实在让他恶心。","mne":"disgust使厌恶 + ing形容词后缀 → disgusting令人厌恶的"},{"word":"dish","ipa":"/dɪʃ/","pos":"n.","def":"菜肴；碟，盘子","sen":"Add a slice of lemon to flavor the dish.","trans":"加上一片柠檬为这道菜肴调味。","mne":""},{"word":"disk","ipa":"/dɪsk/","pos":"n.","def":"圆盘，唱片(=disc)；磁盘；光盘","sen":"Music was recorded on this compact disk(CD).","trans":"音乐被刻录在这张光盘上。","mne":""},{"word":"dislike","ipa":"/dɪsˈlaɪk/","pos":"v.","def":"不喜欢","sen":"As a lady of fine taste, she really dislikes this cheap watch.","trans":"作为一位很有品味的贵妇，她实在不喜欢这块廉价手表。","mne":"dis否定 + like喜欢 → dislike不喜欢"},{"word":"dismiss","ipa":"/dɪsˈmɪs/","pos":"v.","def":"开除；不考虑；解散","sen":"The boss was angry and dismissed the staff.","trans":"老板很生气，并且开除了那个职员。","mne":"dis离开 + miss送 → 我送你离开，千里之外 → dismiss解雇"},{"word":"dismissal","ipa":"/ dɪsˈmɪsəl /","pos":"n.","def":"解雇；解雇，免职","sen":"Do not come back. This is your final dismissal.","trans":"不要回来了。你已经被解雇了。","mne":"dis分开 + miss送出 + al表名词 → dismissal解雇"},{"word":"disorder","ipa":"/dɪsˈɔːrdər/","pos":"n.","def":"混乱；失调，紊乱，疾病","sen":"The room was in a state of disorder.","trans":"这个房间混乱不堪。","mne":"dis无 + order顺序 → 没有顺序 → 混乱"},{"word":"display","ipa":"/dɪˈspleɪ/","pos":"v.","def":"展示；显示；陈列；  n.显示；陈列","sen":"He proudly displayed the big fish he had caught.","trans":"他自豪地展示着他钓到的大鱼。","mne":"dis分开，否定 + play折叠 → 打开，分散 → display展示"},{"word":"dispose","ipa":"/dɪˈspoʊz/","pos":"v.","def":"处理，处置","sen":"She is disposing of the unwanted vegetables into the bin.","trans":"她正在处理不需要的蔬菜，把它们全扔进垃圾箱里。","mne":"dis分开 + pos放 + e  → 分开排好 → dispose处理，处置"},{"word":"dispute","ipa":"/dɪˈspjuːt/","pos":"n.","def":"争论，争端；  v.争执，驳斥","sen":"They're having a dispute about the car accident.","trans":"他们正在争论车祸的事情。","mne":"dis分开 + put思考 → 不同的思考 → 引申为dispute争论"},{"word":"dissolve","ipa":"/dɪˈzɑːlv/ ","pos":"v.","def":"（使）溶解；（使）解散","sen":"This tablet dissolves in water.","trans":"这片药在水中会溶解。","mne":"dis分开，分离 + solve解决，溶解 → 完全分散 → dissolve溶解"},{"word":"distance","ipa":"/ˈdɪstəns/ ","pos":"n.","def":"距离；间距；  v.使与……保持距离，撇清和……的关系","sen":"The distance between the two buildings is 2 km.","trans":"这两栋建筑之间的距离是2千米。","mne":"dist距离 + ance表状态 → distance距离，远处"},{"word":"distant","ipa":"/ˈdɪstənt/","pos":"adj.","def":"遥远的；不亲近的；疏远的","sen":"The destination is still distant.","trans":"目的地还很远。","mne":"di分开 + stant站立 → 分开站 → distant有距离的"},{"word":"distinct","ipa":"/dɪˈstɪŋkt/","pos":"adj.","def":"截然不同的；独特的；明显的；清晰的","sen":"The red umbrella is distinct among the black ones.","trans":"这把红伞在这些黑伞中显得与众不同。","mne":"dis分开 + stinct（sting）刺，做标记 → 分开标记的，区分清楚的 → distinct独特的，清楚的"},{"word":"distinction","ipa":"/dɪˈstɪŋkʃn/","pos":"n.","def":"差别，区分；优等评分，荣誉分数","sen":"The main distinction between the red and the black pencils is their color.","trans":"红铅笔和黑铅笔的主要区别是它们的颜色。","mne":"distinct独特的 + ion名词后缀 → distinction卓越；区别"},{"word":"distinctly","ipa":"/dɪˈstɪŋktli/","pos":"adv.","def":"明显地；清楚地；非常，很","sen":"The colors of these two pictures are distinctly different.","trans":"这两张图片的颜色明显不一样。","mne":"di分开 + stinct刺激 + ly……地 → 把刺分开 → 明显地；确实地"},{"word":"distinguish","ipa":"/dɪˈstɪŋɡwɪʃ/","pos":"v.","def":"区别，辨别；辨别","sen":"It's easy to distinguish the blue man from the gray men.","trans":"我们很容易就能把这个蓝色的人从一群灰色的人中辨别出来。","mne":"dis分散，分开 + tingu=ting做标记 + ish动词后缀 → 分开做标记 → distinguish区别"},{"word":"distinguished","ipa":"/dɪˈstɪŋɡwɪʃt/","pos":"adj.","def":"著名的，卓著的","sen":"Einstein is a distinguished physicist and scientist.","trans":"爱因斯坦是一位杰出的物理学家和科学家。","mne":"distinguish区别 + ed表形容词 → 与众不同 → distinguished著名的"},{"word":"distort","ipa":"/dɪˈstɔːrt/","pos":"v.","def":"扭曲，使变形；歪曲，曲解","sen":"Pressing the soft clay too hard will distort its smooth surface.","trans":"过度用力按压软陶会使其光滑表面变形。","mne":"dis分离 + tort变形，扭曲 → distort扭曲"},{"word":"distract","ipa":"/dɪˈstrækt/","pos":"v.","def":"转移（注意力），使分心；  v.转移(注意力)","sen":"The cat tried to distract his friend's attention and took his fish.","trans":"小猫试图转移他朋友的注意力，伺机拿走他的小鱼干。","mne":"dis分开，分离 + tract拉 → 把心拉开 → 分心"},{"word":"distribute","ipa":"/dɪˈstrɪbjuːt/","pos":"v.","def":"分配，分发；配送；分配","sen":"They distribute food to the people in need.","trans":"他们把食物分发给有需要的人。","mne":"dis分开 + tribute赠品 → 分开给 → distribute分配；区分"},{"word":"district","ipa":"/ˈdɪstrɪkt/","pos":"n.","def":"地区；区域；行政区","sen":"The city is made up of four districts.","trans":"这座城市由四个区域组成。","mne":"di分开 + str拉紧 + ict  → 把一块区域分开  → district地区，区域"},{"word":"disturb","ipa":"/dɪˈstɜːrb/","pos":"v.","def":"打扰；使烦恼","sen":"My cute puppy often disturbs me while I'm working.","trans":"我可爱的小狗经常在我工作的时候打扰我。","mne":"dis分开 + turb骚乱 → 分开了 → disturb扰乱，打扰"},{"word":"ditch","ipa":"/dɪtʃ/","pos":"n.","def":"沟，沟渠；  v.丢弃；摆脱；迫降海上；  v.丢弃","sen":"There is a ditch between the two fields.","trans":"两块田之间有一条沟渠。","mne":""},{"word":"dive","ipa":"/daɪv/","pos":"v.","def":"跳水；急剧下降；  n.跳水；潜水；骤降","sen":"Is the water in this swimming pool deep enough to dive into?","trans":"这个游泳池的水深到能跳水吗？","mne":""},{"word":"diverse","ipa":"/daɪˈvɜːrs/","pos":"adj.","def":"多样的；不同的","sen":"The park is home to diverse flowers, such as roses, tulips and sunflowers.","trans":"这个公园里生长着多样的花朵，例如玫瑰、郁金香和向日葵。","mne":"di分开 + vers转变 + e → 转开了 → diverse不同的"},{"word":"divide","ipa":"/dɪˈvaɪd/","pos":"v.","def":"【航】分开；除以；除","sen":"The cabin crew closed the curtain to divide the business class from the economy section.","trans":"乘务员拉上了隔帘，将商务舱与经济舱隔开。","mne":"di分开 + vide分开 → 分开 → divide分开"},{"word":"division","ipa":"/dɪˈvɪʒn/","pos":"n.","def":"分，分配；分开，分隔；部门","sen":"He finished the division of the cake.","trans":"他已把蛋糕分好了。","mne":"di分开 + vis分开 + ion表名词 → division分，分配"},{"word":"divorce","ipa":"/dɪˈvɔːrs/","pos":"n.","def":"离婚，离异；  v.离婚","sen":"The couple have agreed to get a divorce.","trans":"这对夫妻已经同意离婚了。","mne":"di使…变成、分开 + vorce=vert转 → 从伴侣身边转开 → 离婚"},{"word":"do","ipa":"/duː/","pos":"v.","def":"做，干，办（某事）","sen":"The little boy is doing his homework.","trans":"小男孩正在做家庭作业。","mne":""},{"word":"doctor","ipa":"/ˈdɑːktər/","pos":"n.","def":"医生；博士；  v.篡改（文件，照片），伪造","sen":"The doctor will see you in 10 minutes.","trans":"医生会在10分钟内接诊您。","mne":"doct教 ＋ or表名词，人 → 教的人 → doctor博士，医生"},{"word":"document","ipa":"/ˈdɑːkjʊmənt/","pos":"n.","def":"文件，公文；  v.记录；证明（读作/ˈdɑkjuˌmɛnt/）","sen":"He checks out the document before signing it.","trans":"在签署文件之前，他仔细检查了一遍。","mne":"docu=doc教 + ment名词后缀 → 用来告诉别人的东西 → document文件，公文"},{"word":"dog","ipa":"/dɔːɡ/","pos":"n.","def":"狗，犬，犬科动物；  v.跟踪；尾随","sen":"Your dog is really cute.","trans":"你的狗真可爱。","mne":""},{"word":"dollar","ipa":"/ˈdɑːlər/","pos":"n.","def":"美元","sen":"My mother gives me one dollar a week. She loves me so much!","trans":"我妈一个礼拜给我一块钱。她太爱我啦！","mne":""},{"word":"domestic","ipa":"/dəˈmestɪk/","pos":"adj.","def":"国内的；家庭的；驯养的；  n.家仆","sen":"More and more domestic products are sold abroad.\t","trans":"越来越多国货销往海外。","mne":"domes屋，家 + tic形容词后缀 → 家里的 → domestic家里的；国内的"},{"word":"domestically","ipa":"/dəˈmestɪkli/","pos":"adv.","def":"国内地；在国内","sen":"Giant pandas are very famous domestically.","trans":"大熊猫在国内非常出名。","mne":""},{"word":"dominant","ipa":"/ˈdɑːmɪnənt/","pos":"adj.","def":"占优势的，占支配地位的；主要的；显著的","sen":"He achieved a dominant position by occupying the majority of the market share.","trans":"他占据了大部分市场份额，取得了市场主导地位。","mne":"domin=lord（主人）+ ant表示属于…的 → 属于主人的叫统治 → dominant统治的"},{"word":"dominate","ipa":"/ˈdɑːmɪneɪt/","pos":"v.","def":"支配，统治，控制","sen":"Lions are the ultimate predators which dominate the great grassland.","trans":"狮子是支配着大草原的顶级掠食者。","mne":"domin=dom屋，家 + ate做… → 像家长一样 → dominate支配，统治"},{"word":"donate","ipa":"/ˈdoʊneɪt/","pos":"v.","def":"捐赠；捐献","sen":"We donated a sum of money to the charity.","trans":"我们向慈善机构捐了一笔钱。","mne":"don给予 + ate使 → 给出去 → donate捐赠"},{"word":"donkey","ipa":"/ˈdɔːŋki/","pos":"n.","def":"驴","sen":"The donkey is trying to eat a carrot.","trans":"这头驴子正在努力吃一根胡萝卜。","mne":""},{"word":"door","ipa":"/dɔːr/","pos":"n.","def":"门","sen":"Where does the door lead to?","trans":"这扇门通向哪里？","mne":""},{"word":"dormitory","ipa":"/ˈdɔːrmətɔːri/","pos":"n.","def":"宿舍","sen":"My dormitory is clean and tidy.","trans":"我的宿舍干净整洁。","mne":"dorm睡眠 + itory表示场所 → 睡觉的地方 → dormitory寝室，宿舍"},{"word":"dose","ipa":"/doʊs/","pos":"n.","def":"【化】剂量；  v.给……服药","sen":"In biochemistry, it's crucial to control the dose of the chemicals accurately for the experiment.","trans":"在生物化学中，精确剂量化学物质对于实验至关重要。","mne":"do给，被“给”的+se名词后缀，物品→饮用药量 → 一剂药，一剂"},{"word":"dot","ipa":"/dɑːt/","pos":"n.","def":"点（在域名里起分隔作用）","sen":"You need to type the correct dot com at the end of the website address.","trans":"你需要在网址末尾输入正确的.com。","mne":""},{"word":"double","ipa":"/ˈdʌbl/ ","pos":"adj.","def":"两倍的，成双的，成对的；  v.使……翻倍","sen":"The hamburger in the middle is a double cheeseburger.","trans":"中间的汉堡包是一个双层芝士堡。","mne":"doub二，双 + le反复 → 反复两倍 → double 翻倍"},{"word":"doubt","ipa":"/daʊt/","pos":"v.","def":"怀疑；  n.怀疑；疑惑，疑问","sen":"I really doubt whether aliens exist.","trans":"我很怀疑外星人是否真的存在。","mne":""},{"word":"doubtful","ipa":"/ˈdaʊtfl/","pos":"adj.","def":"怀疑的，疑惑的","sen":"I'm doubtful about the true value of the painting.","trans":"我对这幅画的真实价值表示怀疑。","mne":"doubt怀疑 + ful形容词后缀 → doubtful怀疑的"},{"word":"down","ipa":"/daʊn/","pos":"prep.","def":"向下；  adj.向下的；沮丧的，情绪低落的","sen":"She keeps walking down the road.","trans":"她沿着马路一直往下走。","mne":""},{"word":"download","ipa":"/ˈdaʊnˌloʊd/","pos":"v.","def":"下载；  n.下载","sen":"I use my computer to download apps for my phone.","trans":"我用电脑给我的手机下载应用程序。","mne":""},{"word":"downstairs","ipa":"/ˌdaʊnˈsterz/","pos":"adv.","def":"在楼下，往楼下；  adj.楼下的","sen":"They are running downstairs.","trans":"他们跑着下楼。","mne":"down向下 + stairs楼梯 → downstairs楼下的"},{"word":"downtown","ipa":"/ˈdaʊntaʊn/","pos":"adv.","def":"在市中心；  adj.市中心的，商业区的，闹市区的","sen":"She lives downtown and goes to work by bicycle.","trans":"她住在市中心而且骑自行车去上班。","mne":""},{"word":"downward","ipa":"/ˈdaʊnwərd/","pos":"adv.","def":"向下；  adj.向下的，下降的","sen":"I fell downward through the air, hoping my parachute would open.","trans":"我从空中降落，期望着我的降落伞会打开。","mne":"down向下 ＋ ward向... → downward向下地"},{"word":"downwards","ipa":"/ˈdaʊnwərdz/","pos":"adv.","def":"【物】向下","sen":"Gravity pulls objects downwards towards the center of the Earth.","trans":"重力将物体向地球中心拉动，方向是向下的。","mne":"down下去 + wards表副词，向... → 向下，朝下"},{"word":"dozen","ipa":"/ˈdʌzn/","pos":"num.","def":"一打，十二个；许多","sen":"A dozen eggs now cost twenty \ndollars—how expensive!","trans":"一打鸡蛋现在要20美元——好贵啊！","mne":""},{"word":"draft","ipa":"/dræft/","pos":"n.","def":"草稿；  v.起草","sen":"This is just the draft of a building.","trans":"这只是建筑的设计草图。","mne":""},{"word":"drag","ipa":"/dræɡ/","pos":"v.","def":"拖，拉，拽，扯；（时间或事件）拖沓；  n.拖累物；空气阻力","sen":"You can drag this picture from this folder to the other.","trans":"你可以把图片从这个文件夹拖进另一个文件夹里。","mne":""},{"word":"drama","ipa":"/ˈdrɑːmə/","pos":"n.","def":"戏剧","sen":"The two actors are performing a great love drama.","trans":"这两名演员正在表演一部伟大的爱情剧。","mne":"dra表演 + ma → 在舞台上表演的故事 → drama戏剧，剧本"},{"word":"dramatic","ipa":"/drəˈmætɪk/","pos":"adj.","def":"激动人心的；引人注意的；戏剧性化的","sen":"I see two rainbows over the road; it's so dramatic!","trans":"我在路上看到了两道彩虹,太激动人心了。","mne":"drama戏剧 + tic形容词后缀 → dramatic戏剧的，戏剧性的"},{"word":"dramatically","ipa":"/drəˈmætɪkli/","pos":"adv.","def":"显著地，剧烈地，引人注目地","sen":"This selfie app can dramatically change a person's face.","trans":"自拍软件可以显著地改变一个人的面貌。","mne":"drama戏剧 + tic……的 + ally……地 → dramatically戏剧性地"},{"word":"drastic","ipa":"/ˈdræstɪk/","pos":"adj.","def":"极端的；激烈的","sen":"They have experienced drastic weather changes in one day.","trans":"他们在一天之内经历了极端的天气变化。","mne":"dra表演 + stic=istic有……性质的 → 表演十分投入的 → 充满激情的 → drastic激烈的"},{"word":"draw","ipa":"/drɔː/","pos":"v.","def":"绘画；吸引；拉，引出","sen":"The girls are sitting on the ground drawing pictures.","trans":"女孩们正坐在地上画画。","mne":""},{"word":"drawer","ipa":"/drɔːr/, /ˈdrɔːər/","pos":"n.","def":"抽屉；开票人，出票人（读作/ˈdrɔːər/）","sen":"Remember to keep all your files in the drawer.","trans":"记得把你的所有文件都放在抽屉里。","mne":"draw拉，拖 + er施动者名词后缀，表人或物 → 被人拉开 → drawer抽屉"},{"word":"drawing","ipa":"/ˈdrɔːɪŋ/","pos":"n.","def":"绘图，图样","sen":"That's a simple drawing of a big head man.","trans":"那是一张简笔画，画的是一个大头男人。","mne":"draw画 + ing名词后缀 → 画画 → drawing图画,素描;绘图"},{"word":"dream","ipa":"/driːm/","pos":"n.","def":"梦；梦想；愿望；理想；  v.做梦；梦想","sen":"In my dream, I was on a beach in Hawaii.","trans":"我在梦里去了夏威夷海滩。","mne":""},{"word":"dress","ipa":"/dres/","pos":"n.","def":"连衣裙","sen":"I wear a long white dress.","trans":"我穿着一条白色的长裙。","mne":""},{"word":"drift","ipa":"/drɪft/","pos":"v.","def":"漂流；使漂流；  n.漂流物","sen":"The poet is drifting on a boat.","trans":"诗人正乘着小舟随波飘荡。","mne":""},{"word":"drill","ipa":"/drɪl/","pos":"v.","def":"钻孔；  n.训练；反复操练；钻头","sen":"The worker drills into the wall.","trans":"工人在墙上钻孔。","mne":""},{"word":"drink","ipa":"/drɪŋk/","pos":"v.","def":"喝；喝酒；  n.饮料；酒","sen":"He likes drinking orange juice.","trans":"他喜欢喝橙汁。","mne":""},{"word":"drive","ipa":"/draɪv/","pos":"v.","def":"驾驶；驱使，迫使；  n.驱动力","sen":"The man is driving along the coast.","trans":"这个男人沿着海边开着车。","mne":""},{"word":"driver","ipa":"/ˈdraɪvər/","pos":"n.","def":"驾驶员，司机","sen":"The driver with a beard is very handsome.","trans":"这位留着胡子的司机非常帅气。","mne":"driv驾驶 + er表示人 → driver驾驶员，司机"},{"word":"drop","ipa":"/drɑːp/","pos":"v.","def":"落下；  n.下降；滴","sen":"I accidentally dropped my phone. So upset!","trans":"我不小心把手机弄掉了。真难过！","mne":""},{"word":"drought","ipa":"/draʊt/ ","pos":"n.","def":"久旱","sen":"Drought caused the river to dry up.","trans":"干旱使河流干涸。","mne":""},{"word":"drown","ipa":"/draʊn/","pos":"v.","def":"（使）淹死；淹没","sen":"The apple drowned in the water because it couldn't swim.","trans":"苹果因为不会游泳而淹死在了水里。","mne":""},{"word":"drug","ipa":"/drʌɡ/","pos":"n.","def":"药物；毒品；  v.下麻药；  v.使服麻醉药","sen":"The doctor gave me some drugs.","trans":"医生给了我一些药。","mne":""},{"word":"drum","ipa":"/drʌm/  ","pos":"n.","def":"鼓；圆桶；  v.击鼓","sen":"She is playing the drums for the musical show.","trans":"她正在为音乐表演打鼓。","mne":""},{"word":"drunk","ipa":"/drʌŋk/","pos":"v.","def":"喝，喝酒（drink的过去分词）","sen":"They had drunk all night long and made a mess.","trans":"他们喝了一整夜，搞得一团糟。","mne":""},{"word":"drunken","ipa":"/ˈdrʌŋkən/","pos":"adj.","def":"喝醉的","sen":"The drunken woman is sleeping on the bench.","trans":"这个喝醉的女人正在长椅上睡觉。","mne":"drunk醉酒 + en过去分词时态 → 喝醉酒的 → drunken酒醉的"},{"word":"dry","ipa":"/draɪ/","pos":"adj.","def":"干的，干旱的；  v.变干","sen":"These flowers are dry but still beautiful.","trans":"这些花干了也挺漂亮。","mne":""},{"word":"duck","ipa":"/dʌk/","pos":"n.","def":"鸭，鸭子","sen":"Ducks are swimming happily in the water.","trans":"鸭子们在水中欢快地游着。","mne":""},{"word":"due","ipa":"/duː/","pos":"adj.","def":"预期的；欠债的，应给的；到期的","sen":"Her baby is due on February 28th.","trans":"她的宝宝预计于2月28日出生。","mne":""},{"word":"dull","ipa":"/dʌl/","pos":"adj.","def":"枯燥的，沉闷的；愚笨的，迟钝的；无趣的","sen":"The TV show is so dull that it makes him feel sleepy.","trans":"这档电视节目很无趣，让他想睡觉。","mne":""},{"word":"dumb","ipa":"/dʌm/","pos":"adj.","def":"愚笨的；哑的，不能说话的；  v.使沉默","sen":"It's dumb to row on the cracked soil.","trans":"在龟裂的土地上划船是件很蠢的事情。","mne":""},{"word":"dump","ipa":"/dʌmp/","pos":"v.","def":"倾倒，丢弃；  n.垃圾场，废物堆","sen":"The big truck is dumping waste materials.","trans":"这辆大卡车正在倾倒废料。","mne":""},{"word":"dumpling","ipa":"/ˈdʌmplɪŋ/","pos":"n.","def":"饺子；汤圆","sen":"I enjoy eating Chinese dumplings for lunch.","trans":"我喜欢午饭吃饺子。","mne":"dump无秩序的累积 + ling名词后缀，表示小 → 无秩序地累积的小东西 → dumpling饺子；团子"},{"word":"duplicate","ipa":"/ˈduːplɪkeɪt/","pos":"v.","def":"复制；  n.【计】副本；复制品；  adj.完全一样的","sen":"His right hand can duplicate the thing that his left hand touches.","trans":"库哔左手触摸死或不动物体，右手复制。","mne":"du二，双 + plic折 + ate使，造成 → 折成相同的两份 → duplicate加倍，复制"},{"word":"durable","ipa":"/ˈdʊrəbl/","pos":"adj.","def":"耐用的；持久的","sen":"These shoes are quite durable and perfect for hiking.","trans":"这些鞋子非常耐用，非常适合徒步旅行。","mne":"dur持久，坚硬 + able能……的 → 持久的"},{"word":"duration","ipa":"/duˈreɪʃn/","pos":"n.","def":"持续时间；期间","sen":"The duration of this exam is two hours.","trans":"这场考试的时长是两个小时。","mne":"dur持久 + ation名词后缀，表状态 → 持久的状态 → duration持续时间"},{"word":"during","ipa":"/ˈdʊrɪŋ/","pos":"prep.","def":"在…期间","sen":"It's rude to talk on the phone during dinner.","trans":"在吃晚餐时打电话很没礼貌。","mne":"dur持久 ＋ ing构成介词 → during在…期间"},{"word":"dusk","ipa":"/dʌsk/","pos":"n.","def":"黄昏，傍晚","sen":"I enjoy watching the sunset at dusk.","trans":"我很享受在黄昏时看日落。","mne":""},{"word":"dust","ipa":"/dʌst/","pos":"n.","def":"尘土，沙土；  v.撒上粉末","sen":"Driving down the dirt road so fast raised a lot of dust.","trans":"车从土路上全速驶过，激起漫天的尘土。","mne":""},{"word":"dustbin","ipa":"/ˈdʌstbɪn/","pos":"n.","def":"垃圾箱","sen":"I put the trash into the dustbin.","trans":"我把垃圾装进垃圾箱。","mne":"dust尘土 ＋ bin箱子 → dustbin垃圾桶，灰箱"},{"word":"duty","ipa":"/ˈduːti/","pos":"n.","def":"责任，义务，本分","sen":"Everyone should carry out his duty conscientiously when at work.","trans":"每个人在工作时都应该认真履行自己的职责。","mne":"du=de离开 + ty有 → 有责任所以不能离开 → duty责任，义务"},{"word":"dwarf","ipa":"/dwɔːrf/","pos":"n.","def":"侏儒；[天]矮星；  v.使……相形见绌","sen":"The Seven Dwarfs were happy when staying with Snow White.","trans":"七个小矮人和白雪公主在一起时非常开心。","mne":""},{"word":"dynamic","ipa":"/daɪˈnæmɪk/","pos":"adj.","def":"动态的；有活力的，有生机的；不断变化的；  n.动力","sen":"Stock changes are dynamic.","trans":"股票变化是动态的。","mne":"dynam=power，表示“力量” + ic…的 → dynamic有活力的"},{"word":"each","ipa":"/iːtʃ/","pos":"pron.","def":"每人，每个，每件，各自","sen":"Try to support each other when one of you is feeling down.","trans":"当有人觉得情绪低落时，要努力相互打气。","mne":"ea曾经，总是 + ch相似 → 不同事物的对照 → each每个"},{"word":"eager","ipa":"/ˈiːɡər/","pos":"adj.","def":"热切的，渴望的，急不可耐的","sen":"The kids are eager to eat the cake on the table.","trans":"孩子们急不可耐地想要吃掉桌上的蛋糕。","mne":""},{"word":"eagle","ipa":"/ˈiːɡl/","pos":"n.","def":"鹰","sen":"A huge eagle is flying high in the sky.","trans":"一只巨鹰在天上飞翔。","mne":""},{"word":"ear","ipa":"/ɪr/","pos":"n.","def":"耳朵","sen":"The dog's ears are up.","trans":"这只狗竖起了耳朵。","mne":""},{"word":"early","ipa":"/ˈɜːrli/","pos":"adj.","def":"早的，早期的","sen":"It is far too early in the morning to get up!","trans":"现在起床太早了！","mne":"ear早 + ly副词后缀 → early早的，早期的"},{"word":"earn","ipa":"/ɜːrn/","pos":"v.","def":"挣得，挣钱；赢得","sen":"She earns some extra money by doing a part-time job.","trans":"她通过做兼职赚了一些外快。","mne":""},{"word":"earnest","ipa":"/ˈɜːrnɪst/","pos":"adj.","def":"真诚的，诚挚的，认真的","sen":"\"Thank you very much!\" said the granny with an earnest expression on her face.","trans":"“非常感谢你！”这位老奶奶满脸真诚地说道。","mne":""},{"word":"earnings","ipa":"/ˈɜːrnɪŋz/","pos":"n.","def":"工资；收入","sen":"A rise in his online business earnings made him excited.","trans":"网络业务收入的增长让他兴奋不已。","mne":""},{"word":"earth","ipa":"/ɜːrθ/","pos":"n.","def":"地球；陆地；土，泥","sen":"This is what the Earth looks like from the outer space.","trans":"这就是地球从外太空看到的样子。","mne":""},{"word":"earthquake","ipa":"/ˈɜːrθkweɪk/","pos":"n.","def":"地震","sen":"The rescue team went to rescue the victims of the earthquake.","trans":"营救小组去营救地震的受害者。","mne":"earth地球 + quake震动 → earthquake地震"},{"word":"ease","ipa":"/iːz/","pos":"n.","def":"轻松；安逸；  v.缓解；解除痛苦","sen":"The strong man can lift the rock with ease.","trans":"这个强壮的男人可以轻松地举起石头。","mne":""},{"word":"east","ipa":"/iːst/","pos":"n.","def":"东方；  adj.东方的；  adv.在东方","sen":"You can see this Buddha in the east.","trans":"你可以在东方看到这尊佛像。","mne":""},{"word":"eastern","ipa":"/ˈiːstərn/","pos":"adj.","def":"东方的，东部的，朝东的","sen":"I saw the sunrise in the eastern sky.","trans":"我看到太阳从东方升起。","mne":"east东方 + ern形容词后缀 → eastern东方的"},{"word":"easy","ipa":"/ˈiːzi/","pos":"adj.","def":"容易的","sen":"It is easy for the tall boy to touch the ceiling.","trans":"这个高个子男孩很容易摸到天花板。","mne":"ease安乐 + y表形容词 → easy容易的"},{"word":"eat","ipa":"/iːt/","pos":"v.","def":"吃，吃饭","sen":"I got so fat that doctor told me from now on I can only eat fruit.","trans":"我太胖了，医生告诉我从现在起我只能吃水果。","mne":""},{"word":"echo","ipa":"/ˈekəʊ/","pos":"n.","def":"回声；  v.发出回声，产生回响","sen":"If you shout in this valley, you'll hear an echo.","trans":"如果你在这个山谷里大喊，你就会听见回声。","mne":""},{"word":"ecology","ipa":"/iˈkɑːlədʒi/","pos":"n.","def":"生态；生态学","sen":"Animals, plants and humans form the Earth's ecology.","trans":"动物、植物和人类构成了地球的生态。","mne":"eco生态 + logy…学 → ecology生态；生态学"},{"word":"economic","ipa":"/ˌiːkəˈnɑːmɪk/","pos":"adj.","def":"经济上的，经济学的；有利可图的","sen":"It is important to keep a balance between economic development and environmental protection.","trans":"在经济的发展和环境的保护之间保持平衡是非常重要的。","mne":"eco经济 + nom学术领域 + ic……的 → 经济的，经济学的"},{"word":"economical","ipa":"/ˌekəˈnɑːmɪkl/, /ˌiːkəˈnɑːmɪkl/","pos":"adj.","def":"节约的","sen":"To save money, he always makes the most economical decisions.","trans":"为了省钱，他总是做出精打细算的决定。","mne":"eco经济 + nom学术领域 + ical…的 → economical节约的；经济学的"},{"word":"economics","ipa":"/ˌiːkəˈnɑːmɪks/  ","pos":"n.","def":"经济学","sen":"This is a book about economics.","trans":"这是一本关于经济学的书。","mne":"eco经济 + nom学术领域 + ics……学 → economics经济学"},{"word":"economy","ipa":"/ɪˈkɑːnəmi/ ","pos":"n.","def":"经济","sen":"The economy is improving and people have more money.","trans":"经济正在改善，人们也有了更多的钱。","mne":"eco环境，经济 + nomy学术领域 → economy经济（学）"},{"word":"edge","ipa":"/edʒ/","pos":"n.","def":"（悬崖、峭壁的）边缘；  v.（使）徐徐移动；给……开刃，使锐利","sen":"The chicken is so afraid when standing on the edge.","trans":"站在悬崖边上时，小鸡感到非常害怕。","mne":""},{"word":"edit","ipa":"/ˈedɪt/","pos":"v.","def":"编辑；剪辑","sen":"I edit the story using a pencil.","trans":"我用铅笔编辑故事。","mne":"e出 + dit给予 → 给出好文章 → 编辑"},{"word":"edition","ipa":"/ɪˈdɪʃn/","pos":"n.","def":"版，版本，版次","sen":"The dictionary is now in its third edition, which was published in 2017.","trans":"这本字典现在是第三版，于2017年出版。","mne":"edit编辑 + ion名词后缀 → 编成的样本 → edition版，版本"},{"word":"editor","ipa":"/ˈedɪtər/","pos":"n.","def":"（报刊、杂志的）编辑；主编","sen":"The video editor is using special computer software to do his work.","trans":"这位视频编辑正在用特殊的电脑软件工作。","mne":"edit编辑 + or表示人 → editor编者，编辑"},{"word":"editorial","ipa":"/ˌedɪˈtɔːriəl/","pos":"adj.","def":"编辑的，主笔的；  n.（报刊的）社论","sen":"The editorial team is responsible for the magazine's content and layout.","trans":"编辑团队负责杂志的内容和版面设计。","mne":"editor编辑，编者 + ial形容词后缀 → 给出好文章的人的 → editorial编辑的"},{"word":"educate","ipa":"/ˈedʒukeɪt/","pos":"v.","def":"教育，培养","sen":"He was educated at the Baicizhan University.","trans":"他在百词斩大学接受了教育。","mne":"e出 + duc引导 + ate动词后缀 → educate教育"},{"word":"education","ipa":"/ˌedʒuˈkeɪʃn/","pos":"n.","def":"教育学","sen":"She received a high standard of education at a famous university.","trans":"安迪在名校（斯坦福大学）接受了高等教育。","mne":"e出 + duc引导，带来 + ation行为 → 引出知识的行为 → education教育"},{"word":"educational","ipa":"/ˌedʒuˈkeɪʃənl/","pos":"adj.","def":"教育的；有教育意义的","sen":"Learning is an educational process.","trans":"学习是种教育过程。","mne":"educat=educate教育 ＋ ion名词后缀 ＋ al...的 → educational教育的"},{"word":"educator","ipa":"/ˈedʒukeɪtər/","pos":"n.","def":"教育家，教育者，教师","sen":"Confucius is a famous educator in ancient China.","trans":"孔子是中国古代著名的教育家。","mne":"educat = educate教育 + or名词后缀，表示人 → 教育者"},{"word":"effect","ipa":"/ɪˈfekt/","pos":"n.","def":"效果；影响；结果；  v.使发生；引起","sen":"That lighting effect makes the stage look very mysterious.","trans":"那种灯光效果使舞台看起来很神秘。","mne":"ef出 + fect做，制作 → 做出来 → effect实施，生效；效果"},{"word":"effective","ipa":"/ɪˈfektɪv/","pos":"adj.","def":"有效的；生效的","sen":"The medicine she took was effective for treating colds.","trans":"她吃的药对治疗感冒很有效。","mne":"ef出 ＋ fect做，制作 ＋ ive形容词后缀 → 做出来的 → effective有效的"},{"word":"efficiency","ipa":"/ɪˈfɪʃənsi/","pos":"n.","def":"效率；功效","sen":"The robot greatly increases the efficiency of work.","trans":"机器人极大提高了工作的效率。","mne":"ef出 + fic做 + iency表名词 → 做出事情 → efficiency有效率"},{"word":"efficient","ipa":"/ɪˈfɪʃənt/","pos":"adj.","def":"效率高的","sen":"He's very efficient at work, and can do many things at the same time.","trans":"他工作很高效，能同时处理很多事情。","mne":"ef出 + fici做 + ent……的 → 能做出事来 → efficient做事有效的"},{"word":"effort","ipa":"/ˈefərt/","pos":"n.","def":"努力；尽力","sen":"She makes efforts to do exercise so that she can keep fit.","trans":"她努力健身以保持健康。","mne":"ef出 + fort力量 → 付出力量 → effort努力"},{"word":"egg","ipa":"/eɡ/","pos":"n.","def":"蛋，卵；鸡蛋","sen":"The eggs were put in the basket.","trans":"篮子里盛着鸡蛋。","mne":""},{"word":"eight","ipa":"/eɪt/","pos":"num.","def":"八","sen":"This is the number eight.","trans":"这是数字8。","mne":""},{"word":"eighteen","ipa":"/ˌeɪˈtiːn/","pos":"num.","def":"十八，十八个","sen":"Eighteen is the age when you become an adult.","trans":"十八岁是你成为成年人的年龄。","mne":"eight八 + teen十几 → eighteen十八"},{"word":"eighth","ipa":"/eɪtθ/","pos":"num.","def":"第八","sen":"We lit eight candles on his eighth birthday.","trans":"在他的八岁生日上，我们点了八根蜡烛。","mne":"eigh=eight八 + th第… → eighth第八"},{"word":"eighty","ipa":"/ˈeɪti/","pos":"num.","def":"八十，八十个","sen":"My grandfather is eighty years old.","trans":"我祖父八十岁了。","mne":"eigh表示数字八 + ty表示数字十 → eighty八十"},{"word":"either","ipa":"/ˈiːðər/ /ˈaɪðər/","pos":"adv.","def":"也（用于否定句或短语后）；  pron.（两者中的）任何一个","sen":"'I'm not happy!' 'I'm not happy either!'","trans":"“我不高兴！”“我也不高兴！”","mne":""},{"word":"elaborate","ipa":"/ɪˈlæbəˌreɪt/","pos":"adj.","def":"精心设计的，精巧的；复杂的（读作/iˈlæbərɪt/）","sen":"This elaborate wood carving features delicate flowers.","trans":"这件精巧的木雕上有精致的花朵。","mne":"e=ex向外 + labor努力劳动 + ate表动词 → elaborate精心制作"},{"word":"elder","ipa":"/ˈeldər/","pos":"n.","def":"长辈；  adj.年长的，年龄较大的","sen":"The elders sat together and lovingly watched the child play.","trans":"长辈们坐在一起，慈爱地看着孩子玩耍。","mne":""},{"word":"elderly","ipa":"/ˈeldərli/","pos":"adj.","def":"高龄的","sen":"No one offered a seat to the elderly man.","trans":"没有人给老人让座。","mne":"elder年长的 + ly……的 → elderly过了中年的，稍老的"},{"word":"elect","ipa":"/ɪˈlekt/ ","pos":"v.","def":"选举，推选；选择","sen":"We elect our next leader by voting.","trans":"我们通过投票来选举下一任领导。","mne":"e出 + lect选择，收集 → 选出，选举"},{"word":"election","ipa":"/ɪˈlekʃn/","pos":"n.","def":"选举；当选","sen":"In an election, we decide who our leaders will be.","trans":"在选举中，我们决定谁来当我们的领导人。","mne":"e出 + lect选择，收集 + ion名词后缀 → election选举"},{"word":"electric","ipa":"/ɪˈlektrɪk/","pos":"adj.","def":"电的，带电的","sen":"Don't touch these electric wires. It's dangerous.","trans":"不要碰这些电线，这很危险。","mne":""},{"word":"electrical","ipa":"/ɪˈlektrɪkl/","pos":"adj.","def":"电的","sen":"The kettle is heated by electrical power.","trans":"这个水壶是用电力加热的。","mne":"electric电 + al……的 → 电的，电气科学的"},{"word":"electricity","ipa":"/ɪˌlekˈtrɪsəti/","pos":"n.","def":"电，电力；电流；电学","sen":"He touched the socket with a wet finger and the electricity gave him a shock.","trans":"他用湿的手指碰到了插座，被电到了。","mne":"electric电的 + ity名词后缀 → electricity电力"},{"word":"electron","ipa":"/ɪˈlektrɑːn/","pos":"n.","def":"电子","sen":"An electron moves around an atom's nucleus.","trans":"电子绕着原子的原子核运动。","mne":"electr电的 + on表名词 → electron电子"},{"word":"electronic","ipa":"/ɪˌlekˈtrɑːnɪk/","pos":"adj.","def":"电子的","sen":"Laptops, mobile phones and tablet computers are all electronic devices.","trans":"笔记本电脑、手机和平板电脑都属于电子设备。","mne":"electron电子 + ic形容词，……的 → 电子的"},{"word":"elegant","ipa":"/ˈelɪɡənt/","pos":"adj.","def":"优雅的，典雅的","sen":"The ballet dancer is incredibly elegant.","trans":"这位芭蕾舞演员非常优雅。","mne":"e出 + leg选择，收集 + ant形容词后缀 → 选出的 → elegant好的，高雅的"},{"word":"element","ipa":"/ˈelɪmənt/","pos":"n.","def":"元素；成分；要素","sen":"Water contains the elements of hydrogen and oxygen.","trans":"水含有氢和氧元素。","mne":""},{"word":"elementary","ipa":"/ˌelɪˈmentri/","pos":"adj.","def":"初级的；基本的","sen":"The elementary students are starting school for the first time.","trans":"小学生们正准备第一次上学。","mne":"element要素 + ary形容词后缀 → 最简单的要素 → elementary元素的，基本的"},{"word":"elephant","ipa":"/ˈelɪfənt/","pos":"n.","def":"象，大象","sen":"The elephant is drinking water.","trans":"这头大象正在喝水。","mne":""},{"word":"elevate","ipa":"/ˈelɪveɪt/","pos":"v.","def":"举起；提高；  v.提升；使情绪高昂；鼓舞","sen":"The father elevates his lovely daughter high in the air.","trans":"这位父亲将他可爱的女儿高高举起。","mne":"e出 + lev提高，举起，变轻 + ate动词后缀 → 举出 → elevate升高"},{"word":"elevator","ipa":"/ˈelɪveɪtər/","pos":"n.","def":"电梯；起重机","sen":"The three people are waiting for the elevator.","trans":"这三个人正在等电梯。","mne":"elevat升高 + or名词后缀 → elevator电梯"},{"word":"eleven","ipa":"/ɪˈlevn/","pos":"num.","def":"十一，十一个","sen":"My favorite number is eleven.","trans":"我最喜欢的数字是11。","mne":"e一 + lev留下 + en后缀 → 多出一个 → eleven十一"},{"word":"eleventh","ipa":"/ɪˈlevnθ/","pos":"num.","def":"第十一","sen":"Today is her eleventh birthday.","trans":"今天是她11岁生日。","mne":""},{"word":"eliminate","ipa":"/ɪˈlɪmɪneɪt/","pos":"v.","def":"消除，排除；（在比赛中）淘汰；  v.消除，排除","sen":"This device helps me eliminate the weeds in my garden.","trans":"这个装置帮助我除掉我花园里的杂草。","mne":"e出 + limin门槛 + ate动词后缀 → eliminate消灭，删除"},{"word":"else","ipa":"/els/","pos":"adv.","def":"另外，其他；  adj.别的，其他的","sen":"I'm happy, but everybody else is sad.","trans":"我很高兴，但是别的家伙都苦着一张脸。","mne":""},{"word":"elsewhere","ipa":"/ˌelsˈwer/","pos":"adv.","def":"向别处，在别处","sen":"I want to move elsewhere because it's too noisy here.","trans":"我想搬到别处去，因为这儿太吵了。","mne":"else别的 + where地方 → elsewhere在别处"},{"word":"email","ipa":"/ˈiːmeɪl/","pos":"n.","def":"电子信函","sen":"She received several emails and read one of them.","trans":"她收到了几封邮件，并阅读了其中一封。","mne":""},{"word":"embarrass","ipa":"/ɪmˈbærəs/","pos":"v.","def":"使尴尬；  v.使困惑","sen":"He embarrassed himself when he didn't have enough funds to cover the payment.","trans":"买单时显示余额不足，他非常尴尬。","mne":"em进入…之中，包围 + barrass套子 → 进入套子 → embarrass使难堪"},{"word":"embarrassing","ipa":"/ɪmˈbærəsɪŋ/","pos":"adj.","def":"使人尴尬的","sen":"It's too embarrassing to poop with all these kittens watching.","trans":"这么多猫看着我蹲坑，实在是太尴尬了……","mne":"em进入…之中 ＋ barrass套子 ＋ ing形容词后缀…的 → 进入套中 → embarrassing使人尴尬的；令人为难的"},{"word":"embarrassment","ipa":"/ɪmˈbærəsmənt/","pos":"n.","def":"尴尬；令人难堪的人或事；窘迫","sen":"She felt a deep embarrassment when she forgot her speech in the meeting.","trans":"她在会议上忘记发言稿时感到非常尴尬。","mne":""},{"word":"embassy","ipa":"/ˈembəsi/","pos":"n.","def":"大使馆","sen":"The US embassy in the UK is located in London.","trans":"美国驻英大使馆位于伦敦。","mne":"ambi两边，周围 + ass做，代理 + y表名词 → 代理围在一起做事 → embassy大使馆"},{"word":"embrace","ipa":"/ɪmˈbreɪs/","pos":"v.","def":"拥抱；欣然接受，乐意采纳；  n.拥抱","sen":"The Chinese women's football team embraced to celebrate qualifying.","trans":"中国女足运动员们拥抱庆祝晋级。","mne":"em进入 + brace手臂 → embrace拥抱"},{"word":"emerge","ipa":"/iˈmɜːrdʒ/","pos":"v.","def":"出现；兴起；  v.浮现","sen":"A little rabbit emerged from the hole to look for food.","trans":"一只小兔子从洞口钻出来找吃的。","mne":"e出 + merge沉没 → 沉没的东西出现 → emerge浮现"},{"word":"emergency","ipa":"/iˈmɜːrdʒənsi/","pos":"n.","def":"紧急情况，突发事件","sen":"It's an emergency; get her to the hospital as soon as possible.","trans":"情况紧急，尽快送她去医院。","mne":"e出 + merg沉，没 + ency名词后缀 → emergency突然出现的事情"},{"word":"emission","ipa":"/iˈmɪʃn/","pos":"n.","def":"排放物；排放","sen":"The emissions from the coal power station will pollute the air.","trans":"燃煤发电站排放的废气会污染空气。","mne":"e向外+miss送、放、发射+ion名词后缀→ emission排放物 "},{"word":"emotion","ipa":"/ɪˈmoʊʃn/","pos":"n.","def":"情绪，情感；感情；强烈的感情；感性","sen":"She expressed different emotions when watching this TV series.","trans":"她看这部电视剧的时候表现出了不同的情绪。","mne":"e出 + mot移动 + ion名词后缀 → 动出[感情] → emotion感情"},{"word":"emotional","ipa":"/ɪˈmoʊʃənl/","pos":"adj.","def":"情绪激动的，感动的","sen":"She gave an emotional speech at her best friend's wedding.","trans":"她在好朋友的婚礼上发表了一段感人至深的演讲。","mne":"emotion情感 + al形容词后缀 → emotional情感上的"},{"word":"emperor","ipa":"/ˈempərər/","pos":"n.","def":"皇帝","sen":"In ancient China, the emperor had supreme power.","trans":"在中国古代，皇上有着至高无上的权力。","mne":"emper命令，统治 ＋ or表示人 → 统治者 → emperor皇帝"},{"word":"emphasis","ipa":"/ˈemfəsɪs/","pos":"n.","def":"重点；强调","sen":"The word has been highlighted to provide emphasis.","trans":"标亮单词，以示重点。","mne":"em进入 + phasis显示 → 进入显示 → emphasis强调"},{"word":"emphasise","ipa":"/ˈemfəsaɪz/","pos":"v.","def":"强调（=emphasize）","sen":"The teacher emphasised the correct pronunciation of this Chinese character.","trans":"老师强调了这个汉字的正确发音。","mne":""},{"word":"emphasize","ipa":"/ˈemfəsaɪz/","pos":"v.","def":"强调，着重；着重","sen":"I want to emphasize the importance of teamwork.","trans":"我想强调团队合作的重要性。","mne":"emphasi=emphasis强调 + ize动词后缀 → emphasize强调"},{"word":"employ","ipa":"/ɪmˈplɔɪ/","pos":"v.","def":"雇用；使用","sen":"She employed a babysitter to look after her children.","trans":"她雇了个保姆来照顾她的孩子。","mne":"em在……里 + ploy折叠 → employ投入，雇佣"},{"word":"employee","ipa":"/ɪmˈplɔɪiː /","pos":"n.","def":"雇员；受雇者","sen":"The employee felt very happy when his boss praised him.","trans":"听到老板表扬他，这位员工感到很高兴。","mne":"employ雇用 + ee人 → employee雇员"},{"word":"employer","ipa":"/ɪmˈplɔɪər/","pos":"n.","def":"雇主，老板","sen":"The girl is hired by the employer.","trans":"女孩被雇主录用了。","mne":"employ雇用 + er施动者 → employer雇主"},{"word":"employment","ipa":"/ɪmˈplɔɪmənt/","pos":"n.","def":"职业；雇用；就业","sen":"She found employment as an English teacher.","trans":"她找到了一份英语老师的工作。","mne":"employ雇佣 + ment名词后缀 → employment雇佣"},{"word":"empty","ipa":"/ˈempti/","pos":"adj.","def":"空的；无意义的，缺乏力量(或效果)的；  v.倒空；腾空","sen":"There are many seats in the meeting room, but they are all empty.","trans":"会议室有很多座位，但是都是空的。","mne":""},{"word":"enable","ipa":"/ɪˈneɪbl/","pos":"v.","def":"使能够，使可能","sen":"Vegetables enable me to keep healthy.","trans":"蔬菜让我保持健康。","mne":"en使…进入状态 + able能够 → enable使能够"},{"word":"enclose","ipa":"/ɪnˈkloʊz/","pos":"v.","def":"随信（或包裹）附上；围住","sen":"I enclose two tickets along with a letter.","trans":"我随信附上了两张票。","mne":"en使 + close关闭 → enclose包围"},{"word":"encounter","ipa":"/ɪnˈkaʊntər/","pos":"v.","def":"邂逅，偶遇；  n.遭遇","sen":"We encountered a deer in the forest.","trans":"我们在森林里偶遇了一只鹿。","mne":"en在...中 + counter与...相反 → 在某地与反方向的人遇到 → encounter邂逅，偶遇"},{"word":"encourage","ipa":"/ɪnˈkɜːrɪdʒ/","pos":"v.","def":"鼓励，支持；促使","sen":"My teacher always encouraged me to pursue my passion for music.","trans":"我的老师总是鼓励我追求对音乐的热爱。","mne":"en加强 + courage内心的力量=勇气 → encourage鼓励"},{"word":"encouragement","ipa":"/ɪnˈkɜːrɪdʒmənt/","pos":"n.","def":"鼓励；鼓舞","sen":"The trainer offered words of encouragement to the girl as she was running.","trans":"女孩跑步的时候，教练用言语鼓励她。","mne":"encourage鼓励 + ment表名词 → encouragement鼓励"},{"word":"end","ipa":"/end/","pos":"n.","def":"末端，终点；终止，结束；末端；尽头；末尾；目的，目标；  v.结束；终止，结束","sen":"She is at the end of the queue.","trans":"她排在了队伍的末尾。","mne":""},{"word":"endanger","ipa":"/ɪnˈdeɪndʒər/","pos":"v.","def":"危及，危害","sen":"Cutting down trees will endanger the habitats of many animals.","trans":"砍伐树木会危及许多动物的家园。","mne":"en使…进入状态 + danger危险 → 使危险"},{"word":"endless","ipa":"/ˈendləs/","pos":"adj.","def":"无尽的","sen":"There is an endless supply of pickles in the kitchen.","trans":"厨房里的咸菜无限量供应。","mne":"end结束 + less无…的 → endless无止境的"},{"word":"endurance","ipa":"/ɪnˈdʊrəns/ ","pos":"n.","def":"忍耐力，耐性，耐用度","sen":"It takes great endurance to do this exercise.","trans":"做这项锻炼需要很强的耐力。","mne":"endur忍耐 + ance表性质 → endurance忍耐力"},{"word":"endure","ipa":"/ɪnˈdʊr/","pos":"v.","def":"忍受，容忍","sen":"It is very hard to endure the toothache.","trans":"牙痛是难以忍受的。","mne":"en艰难 + dure使……艰难 → endure度过，忍受"},{"word":"enemy","ipa":"/ˈenəmi/","pos":"n.","def":"敌人；敌军","sen":"The man who holds the pan is her enemy.","trans":"拿着平底锅的男人是她的敌人。","mne":"en不是 + emy朋友 → enemy敌人"},{"word":"energetic","ipa":"/ˌenərˈdʒetɪk/","pos":"adj.","def":"精力充沛的，充满活力的","sen":"Her energetic dance makes her hair go back.","trans":"她充满活力的舞蹈让她的头发向后甩动。","mne":"energ活力 + etic形容词后缀 → energetic充满活力的"},{"word":"energy","ipa":"/ˈenərdʒi/","pos":"n.","def":"能量；精力；能源","sen":"The panels use solar energy to make electricity.","trans":"这些板子能够用太阳能发电。","mne":"en在...上 + ergy功 → energy 能量"},{"word":"enforce","ipa":"/ɪnˈfɔːrs/","pos":"v.","def":"强制执行；强迫","sen":"The new parking restrictions will be strictly enforced.","trans":"新的停车规定将被严格执行。","mne":"en进入 + force强大，力量 → 进入力量 → 强行"},{"word":"enforcement","ipa":"/ɪnˈfɔːrsmənt/","pos":"n.","def":"执行，实施；实施","sen":"The police are responsible for the enforcement of the law.","trans":"警察负责法律的执行。","mne":""},{"word":"engage","ipa":"/ɪnˈɡeɪdʒ/","pos":"v.","def":"参加；（军队）交战；使从事；吸引住（注意力、兴趣）；与......建立密切关系","sen":"She used to exercise alone, but now she engages in the group running.","trans":"她过去常常独自锻炼，但现在她加入了集体跑步的行列。","mne":"en进入，使 + gage承诺 → 使人承诺（以加入）→ engage加入，参加"},{"word":"engagement","ipa":"/ɪnˈɡeɪdʒmənt/","pos":"n.","def":"婚约，订婚","sen":"We announced our engagement last week, so now everybody knows we're getting married.","trans":"我们上周宣布了订婚的消息，所以现在大家都知道我们要结婚了。","mne":"en在…中 + gage承诺 + ment名词后缀 → engagement订婚"},{"word":"engine","ipa":"/ˈendʒɪn/","pos":"n.","def":"引擎；发动机","sen":"The engine at the front of the car makes the car move.","trans":"汽车前部的引擎使汽车移动。","mne":"en=in内部 + gine生育 → engine引擎"},{"word":"engineer","ipa":"/ˌendʒɪˈnɪr/","pos":"n.","def":"工程师；技师；火车司机；  v.设计；建造","sen":"The two engineers are discussing their new building plans.","trans":"这两个工程师正在讨论新的建筑计划。","mne":"engine发动机 + er人 → engineer工程师"},{"word":"engineering","ipa":"/ˌendʒɪˈnɪrɪŋ/","pos":"n.","def":"工程；工程学","sen":"All the workers are trying to solve the engineering problem.","trans":"所有工人都尝试着解决这个工程问题。","mne":"engineer工程师 + ing表名词 → engineering工程、工程师行业"},{"word":"enhance","ipa":"/ɪnˈhæns/","pos":"v.","def":"提高（强度、力量、数量等）；增强","sen":"My colleague helps me to enhance my working skills.","trans":"我的同事帮助我提升工作技能。","mne":"en使... + hance高 → enhance提高"},{"word":"enjoy","ipa":"/ɪnˈdʒɔɪ/","pos":"v.","def":"享受……的乐趣，欣赏，喜爱","sen":"A birthday party should be an event everyone can enjoy.","trans":"生日派对应该是每个人都能享受的事情。","mne":"en进入 + joy高兴 → 做高兴的事 → enjoy享受"},{"word":"enjoyment","ipa":"/ɪnˈdʒɔɪmənt/","pos":"n.","def":"愉快；乐趣","sen":"He's eating the hamburgers with great enjoyment.","trans":"他十分愉快地吃着汉堡。","mne":"enjoy享受 + ment名词后缀 → enjoyment 享受"},{"word":"enlarge","ipa":"/ɪnˈlɑːrdʒ/","pos":"v.","def":"放大","sen":"The doctor advised surgery if the tumor continued to enlarge.","trans":"医生建议如果肿瘤继续增大就进行手术。","mne":"en使 + large大 → enlarge使扩大"},{"word":"enlighten","ipa":"/ɪnˈlaɪtn/","pos":"v.","def":"启发，开导","sen":"The teacher really enlightens her students.","trans":"这个老师的确启发了她的学生。","mne":"en使…进入状态 + light光 + en表动词，使变成 → 给人光明 → 启发"},{"word":"enlightened","ipa":"/ɪnˈlaɪtnd/","pos":"adj.","def":"开明的；  v.动词enlighten的过去式和过去分词.","sen":"The teacher's words made me at once become enlightened.","trans":"老师的一席话使我顿开茅塞。","mne":""},{"word":"enormous","ipa":"/ɪˈnɔːrməs/ ","pos":"adj.","def":"庞大的，巨大的；（范围、程度）极大的；庞大的","sen":"The little girl was shocked by the enormous dog.","trans":"小女孩被这只巨大的狗震惊了。","mne":"e出 + norm规则，规范 + ous形容词后缀 → 超出了正常状态 → enormous巨大的"},{"word":"enough","ipa":"/ɪˈnʌf/","pos":"det.","def":"足够的；  adv.足够地；  pron.很多","sen":"No, no, no, I already have enough food.","trans":"别给我夹菜了，已经够多了。","mne":""},{"word":"enquire","ipa":"/ɪnˈkwaɪər/","pos":"v.","def":"询问，打听","sen":"Please enquire at the reception desk.","trans":"请向前台询问。","mne":"en=in进入 + quire询问 → enquire询问"},{"word":"enquiry","ipa":"/ɪnˈkwaɪəri/","pos":"n.","def":"询问；调查","sen":"The police made several enquiries about the theft with the passers-by.","trans":"警察向路人询问了很多关于这起盗窃案的问题。","mne":"en=in在里面 + quir询问 +y表名词 → enquiry询问"},{"word":"enrich","ipa":"/ɪnˈrɪtʃ/","pos":"v.","def":"使富裕","sen":"He used his position to enrich himself.","trans":"他利用职务之便敛财。","mne":"en使成某种状态 + rich富裕 → enrich使富裕"},{"word":"ensure","ipa":"/ɪnˈʃʊr/","pos":"v.","def":"确保；保证","sen":"The swimming rings could ensure the safety of the pigs.","trans":"这些游泳圈可以保证小猪们的安全。","mne":"en使 + sure确定 → ensure 保证"},{"word":"enter","ipa":"/ˈentər/","pos":"v.","def":"走进；进入","sen":"Two men and a woman are entering the building.","trans":"两男一女正在走进大楼。","mne":""},{"word":"enterprise","ipa":"/ˈentərpraɪz/","pos":"n.","def":"企业（或事业）单位，公司","sen":"This small enterprise specializes in milk.","trans":"这家小企业专营牛奶。","mne":"enter进入 + prise拿住，抓住 → 进入抓住 → enterprise事业，进取心"},{"word":"enterprising","ipa":"/ˈentərpraɪzɪŋ/","pos":"adj.","def":"有事业心的，有进取心的，有魅力的，有胆量的","sen":"The enterprising boss has mentioned many financial targets and ambitious ideas.","trans":"极具事业心的老板提到了许多财务目标和自己的雄心壮志。","mne":"enter进入+pris拿住，抓住+ing名词后缀 → 进入抓住目标的 → 有事业心的"},{"word":"entertain","ipa":"/ˌentərˈteɪn/","pos":"v.","def":"使欢乐；招待，款待；心存，怀有","sen":"The woman plays the clown to entertain children at the party.","trans":"这个女人扮成小丑在派对上逗孩子们开心。","mne":"enter在……中间 + tain拥有 → entertain娱乐"},{"word":"entertainment","ipa":"/ˌentərˈteɪnmənt/","pos":"n.","def":"娱乐；招待，款待","sen":"Which kind of entertainment do you enjoy? Games, movies, or TV?","trans":"你喜欢哪种娱乐方式，玩游戏、看电影，还是看电视？","mne":"entertain娱乐，款待 + ment表名词 → entertainment娱乐；款待"},{"word":"enthusiasm","ipa":"/ɪnˈθuːziæzəm/ ","pos":"n.","def":"热情，热心，热忱","sen":"Those kids always have so much enthusiasm about studying.","trans":"这些孩子总是对学习充满热情。","mne":"en进入 + thus = theo神 + iasm状态 → 进入神的状态 → 热情"},{"word":"enthusiastic","ipa":"/ɪnˌθuːziˈæstɪk/","pos":"adj.","def":"狂热的，极感兴趣的；热情的","sen":"They are enthusiastic about reading.","trans":"他们热爱读书。","mne":"en在...中 + thusi上天，天神 + astic形容词后缀 → 对宗教的虔诚信仰 → enthusiastic热情的，狂热的"},{"word":"entire","ipa":"/ɪnˈtaɪər/","pos":"adj.","def":"完整的，全部的","sen":"There's half a chocolate pie and an entire lemon cake on the shelf.","trans":"架子上有半个巧克力派和一整块柠檬蛋糕。","mne":"en进 + tire紧 → 全部靠紧，挤进去 → entire全部的，完整的，整个的"},{"word":"entirely","ipa":"/ɪnˈtaɪərli/","pos":"adv.","def":"完全地；彻底地","sen":"He agreed entirely with what his colleague said.","trans":"他完全同意他的同事所说的话。","mne":""},{"word":"entitle","ipa":"/ɪnˈtaɪtl/","pos":"v.","def":"给（书）题名；给予……权利","sen":"The book is entitled The Journey to the West.","trans":"这本书被命名为《西游记》。","mne":"en=in在里面 + title名称 → entitle给...命名；赋予权利"},{"word":"entrance","ipa":"/ˈentrəns/","pos":"n.","def":"入口，通道；出场，登场；  v.使出神，使入迷","sen":"Children are gathering at the entrance of the park.","trans":"孩子们在公园的入口处集合。","mne":"entr=enter进入 + ance表名词，状态、行为 → entrance入口；进入，入学"},{"word":"entry","ipa":"/ˈentri/","pos":"n.","def":"进入；参与；条目，（日记的）一则；参赛；入口处","sen":"He made his entry into the meeting room.","trans":"他走进了会议室。","mne":""},{"word":"envelope","ipa":"/ˈenvəloʊp/","pos":"n.","def":"信封","sen":"The letter is put into the red envelope.","trans":"信被放在了红色信封里。","mne":"en表示\"进入…之中，包围\" + velop=cover（盖上） + e → envelope信封，封套"},{"word":"envious","ipa":"/ˈenviəs/","pos":"adj.","def":"羡慕的，嫉妒的","sen":"My dog is always envious of our dinner.","trans":"我的狗总是羡慕我们能吃到那样的晚餐。","mne":"env羡慕 + ious形容词后缀 → envious羡慕的"},{"word":"environment","ipa":"/ɪnˈvaɪrənmənt/ ","pos":"n.","def":"自然环境","sen":"They are picking up trash to keep the environment clean.","trans":"为了保持环境整洁，他们正在捡垃圾。","mne":"environ包围，环绕 + ment表名词 → environment环境"},{"word":"environmental","ipa":"/ɪnˌvaɪrənˈmentl/","pos":"adj.","def":"环境的","sen":"This meeting is about environmental protection.","trans":"本次会议是关于环境保护的。","mne":"environment环境 + al形容词后缀 → environmental环境的"},{"word":"envy","ipa":"/ˈenvi/","pos":"v.","def":"羡慕；  n.妒忌","sen":"The baby girl envies her sister for having toys.","trans":"小女孩羡慕姐姐有玩具。","mne":"en使 + vy=vid看到别人 → 妒忌"},{"word":"equal","ipa":"/ˈikwəl/","pos":"adj.","def":"平等的；相等的；  v.比得上；  n.同等的人","sen":"Today, men and women are equal before the law.","trans":"如今，男女在法律面前是平等的。","mne":"equ相等，平均 + al形容词后缀 → 相等的，平等的"},{"word":"equality","ipa":"/iˈkwɑːləti/","pos":"n.","def":"同等，平等；【数】等式","sen":"This picture shows the equality between men and women.","trans":"这张照片显示了男性与女性的平等。","mne":"equal相等的 + ity名词后缀 → equality平等"},{"word":"equally","ipa":"/ˈiːkwəli/","pos":"adv.","def":"平等地；同样地；相等地","sen":"Men and women should be treated equally.","trans":"男女应该被平等对待。","mne":"equ相等 ＋ ally...地 → equally同样地；相等地"},{"word":"equip","ipa":"/ɪˈkwɪp/","pos":"v.","def":"装备","sen":"The worker equips himself with several items.","trans":"这名工人身上装备了好几样东西。","mne":""},{"word":"equipment","ipa":"/ɪˈkwɪpmənt/","pos":"n.","def":"设备，器材；装备，装置","sen":"Students now enjoy using the exercise equipment for working out.","trans":"现在的学生喜欢使用健身器材运动。","mne":"equip配备，装备 + ment表名词 → equipment设备"},{"word":"equivalent","ipa":"/ɪˈkwɪvələnt/","pos":"adj.","def":"相等的；等值的；  n.等价物","sen":"The weight of three small balls is equivalent to that of this large one.","trans":"三个小球的重量与这个大球的重量相等。","mne":"equi相等，平均 + val力量 + ent形容词后缀→ 力量平等 → 相等的，等价的"},{"word":"era","ipa":"/ˈɪrə/","pos":"n.","def":"时代；纪元","sen":"These kinds of costumes were quite popular in the Victorian era.","trans":"这些装束在维多利亚时代非常流行。","mne":""},{"word":"erect","ipa":"/ɪˈrekt/","pos":"v.","def":"建造，建立；  adj.直立的，垂直的","sen":"The workers are busy erecting the building.","trans":"工人们正忙于建房子。","mne":"e向外，向上 + rect指领 → erect建立"},{"word":"erode","ipa":"/ɪˈroʊd/","pos":"v.","def":"侵蚀","sen":"The statue has been steadily eroded by acid rain and lost its face.","trans":"这座雕像已被酸雨逐渐侵蚀，失去了它的脸。","mne":"e出 + rode咬 → 咬出去 → 侵蚀"},{"word":"error","ipa":"/ˈerər/","pos":"n.","def":"错误，过失","sen":"If you make an error, you can just erase it and write again.","trans":"如果你写错了，擦掉重写就好了。","mne":"err错误 + or行为，状况 → error错误"},{"word":"escape","ipa":"/ɪˈskeɪp/","pos":"v.","def":"逃跑，逃脱；  n.逃跑，逃脱","sen":"The bird escapes from the cage.","trans":"小鸟逃出了鸟笼。","mne":"es向外 + cape帽子，斗篷 → 从斗篷里钻出来 → escape逃跑，逃脱"},{"word":"especially","ipa":"/ɪˈspeʃəli/","pos":"adv.","def":"尤其；异常地；专门","sen":"The little girl loves drinking juice, especially orange juice.","trans":"小女孩很爱喝果汁，尤其是橙汁。","mne":"especial特别的 + ly副词后缀 → especially特别地"},{"word":"essay","ipa":"/ˈeseɪ/","pos":"n.","def":"论文；文章，短文","sen":"The girl is busy writing her essay right now.","trans":"这个女孩正忙着写她的论文。","mne":"ess=ex向外 + ay启动，开动 → essay企图"},{"word":"essential","ipa":"/ɪˈsenʃl/","pos":"adj.","def":"必不可少的，极其重要的；本质的；基本的；  n.必需品","sen":"Hot pot and mahjong are essential components of Sichuan culture.","trans":"火锅和麻将是四川文化必不可少的一部分。","mne":"essent存在，本质 + ial ...的 → essential必要的，本质的"},{"word":"establish","ipa":"/əˈstæblɪʃ/ /ɪˈstæblɪʃ/ ","pos":"v.","def":"建立；确立；创立，成立；使确认","sen":"The two businessmen are trying to establish links.","trans":"这两个商人在试图建立联系。","mne":"e缓音字母，无含义 + stablish使稳固 → establish建立"},{"word":"establishment","ipa":"/ɪˈstæblɪʃmənt/","pos":"n.","def":"建立，创立；团体，公司","sen":"He cut the ribbon at the grand opening of the establishment.","trans":"在这场盛大的开幕仪式上，他负责剪彩。","mne":"establish建立 + ment名词后缀 → establishment 建立"},{"word":"estate","ipa":"/ɪˈsteɪt/","pos":"n.","def":"庄园；房地产","sen":"She lives in a castle on an estate in London.","trans":"她住在伦敦一处庄园的城堡里。","mne":"e出 + stat站着 + e强调 → 站出来的东西 → estate房子等不动产"},{"word":"esteem","ipa":"/ɪˈstim/","pos":"v.","def":"【财】尊重；尊敬；  n.尊敬","sen":"Investors esteem a strong financial performance in a company.","trans":"投资者看重公司的强大财务表现。","mne":"esteem=estim价值 → 有价值 → 仰慕 → esteem尊敬"},{"word":"estimate","ipa":"/ˈestɪmeɪt/","pos":"v.","def":"估价，估计；  n.估价，估计","sen":"The man is estimating the value of the watch.","trans":"这个男人在给这块手表估价。","mne":"estim估计 + ate动词后缀 → estimate估计"},{"word":"ethic","ipa":"/ˈeθɪk/","pos":"n.","def":"道德规范；伦理","sen":"Anti-doping is an important code of ethics in sports.","trans":"反兴奋剂是体育界的一条重要道德准则。","mne":""},{"word":"evade","ipa":"/ɪˈveɪd/","pos":"v.","def":"躲避，回避","sen":"She tried to evade the embarrassing questions that the journalists asked.","trans":"她尽力回避记者提出的令人尴尬的问题。","mne":"e出，出来 + vade走 → 走出去 → 逃避"},{"word":"evaluate","ipa":"/ɪˈvæljuˌeɪt/ ","pos":"v.","def":"评价","sen":"They evaluated our performance and thought it was good.","trans":"他们评价了我们的表演，认为很不错。","mne":"e使 + valu价值 + ate动词后缀 → 使……定价 → evaluate估价"},{"word":"evaluation","ipa":"/ɪˌvæljuˈeɪʃən/","pos":"n.","def":"评价；口头（或书面）评估；估价","sen":"Customers can make an online evaluation of the service they received.","trans":"客户可以在线评估他们接受的服务。","mne":"e使 + valu价值 + ation名词后缀 → evaluation评估，估价"},{"word":"eve","ipa":"/iːv/","pos":"n.","def":"（节日等的）前夜，前夕","sen":"We set off some fireworks on New Year's Eve.","trans":"我们在新年前夜放了一些烟花。","mne":""},{"word":"even","ipa":"/ˈiːvn/","pos":"adv.","def":"甚至更加；  adj.偶数的；平坦的；  v.使打平，使相等","sen":"She was even more tired after reading the e-mail.","trans":"读完这封邮件之后她甚至更疲惫了。","mne":""},{"word":"evening","ipa":"/ˈiːvnɪŋ/","pos":"n.","def":"傍晚，晚上","sen":"In the evening, we watched the sunset by the beach.","trans":"傍晚，我们在沙滩边看日落。","mne":""},{"word":"event","ipa":"/ɪˈvent/","pos":"n.","def":"事件，大事；比赛项目","sen":"The \"911 incident\" was an event that shocked the world.","trans":"“911事件”震惊了全世界。","mne":"e向外 + vent到来 → event事件 "},{"word":"eventually","ipa":"/ɪˈventʃuəli/","pos":"adv.","def":"最后，终于","sen":"After weeks of hard study, he eventually got a satisfying result.","trans":"经过几周的刻苦学习，他终于得到了令人满意的结果。","mne":"eventual最后的 + ly 表示方式、程度、状态、“...地” → adv.终于；最后"},{"word":"ever","ipa":"/ˈevər/","pos":"adv.","def":"曾经","sen":"Have you ever been on a hot air balloon?","trans":"你曾经坐过热气球吗？","mne":""},{"word":"every","ipa":"/ˈevri/","pos":"det.","def":"每个，每一","sen":"You cannot trust every businessman.","trans":"不是每一个商人都值得相信。","mne":""},{"word":"everybody","ipa":"/ˈevribɑːdi/","pos":"pron.","def":"每人，人人","sen":"Everybody enjoyed the yoga class.","trans":"每个人都很享受瑜伽课。","mne":"every每个 + body人 → everybody每人，人人"},{"word":"everyday","ipa":"/ˈevrideɪ/","pos":"adj.","def":"日常的，每天的","sen":"Doing exercise and keeping a healthy diet have become my everyday life.","trans":"做运动和坚持健康的饮食已经成了我的日常生活。","mne":"every每个的 + day天 → everyday每天的，日常的"},{"word":"everyone","ipa":"/ˈevriwʌn/","pos":"pron.","def":"每个人，人人，所有人","sen":"Everyone in the world should care about the planet.","trans":"世界上的每个人都应该关爱地球。","mne":"every每 + one一个人 → everyone每个人"},{"word":"everything","ipa":"/ˈevriθɪŋ/","pos":"pron.","def":"一切","sen":"The man had eaten everything in the fridge.","trans":"那个男人把冰箱里的所有东西都吃光了。","mne":""},{"word":"everywhere","ipa":"/ˈevriwer/","pos":"adv.","def":"到处；处处","sen":"I want to travel everywhere in the world.","trans":"我想走遍世界的每个角落。","mne":"every每 + where地方 → everywhere处处"},{"word":"evidence","ipa":"/ˈevɪdəns/ ","pos":"n.","def":"证物；证据，证明；  v.证明","sen":"Keep every piece of evidence to help us solve the crime.","trans":"保留所有的证据来帮助我们破案。","mne":"e出 + vid看 + ence表名词 → 明显的证据 → evidence证据，证人"},{"word":"evident","ipa":"/ˈevɪdənt/","pos":"adj.","def":"显然的，明显的，明白的","sen":"It's evident that the salesman is lying.","trans":"很明显这个推销员在说谎。","mne":"e易于的 + vident看 → evident明显的"},{"word":"evidently","ipa":"/ˈevɪdəntli/","pos":"adv.","def":"显然地","sen":"Evidently, it was my cat who ate my dinner!","trans":"很显然，我的猫偷吃了我的晚餐！","mne":"evident明显的 + ly副词后缀 → evidently显然地，显然"},{"word":"evil","ipa":"/ˈiːvl/","pos":"adj.","def":"邪恶的；  n.邪恶，罪恶，恶行","sen":"This evil monster has a devilish stare.","trans":"这个邪恶的怪物眼中闪过一丝魔鬼般的光芒。","mne":"e加强或引申意义、使… + vil=base（卑劣的）→ evil邪恶；罪恶的"},{"word":"evoke","ipa":"/ɪˈvoʊk/","pos":"v.","def":"唤起；引起","sen":"This picture evokes feelings of summer.","trans":"这张照片唤起了夏天的感觉。","mne":"e出 + voke=vok呼喊，声，召集 → 喊出思想 → evoke唤醒"},{"word":"evolution","ipa":"/ˌevəˈluːʃn/","pos":"n.","def":"进化，演变","sen":"The theory of evolution is a wonderful explanation of how life arose.","trans":"进化论是关于生命如何产生的精彩阐释。","mne":"e出 + volu转 + tion表名词 → evolution进化"},{"word":"evolutionary","ipa":"/ˌevəˈluːʃəneri/","pos":"adj.","def":"进化的，演进的","sen":"The chart shows the evolutionary process of phones.","trans":"这张图表显示了手机的进化过程。","mne":"e出+volu=vol转+tion表名词 + ary ...的 →evolution进化 + ary ...的 → 进化的，演进的"},{"word":"evolve","ipa":"/iˈvɑːlv/","pos":"v.","def":"进化，发展；逐渐形成","sen":"Even today, the human race continues to evolve.","trans":"直到今天，人类都还在持续进化中。","mne":"e出 + volve旋转，卷 → 转出来 → evolve使发展，使进化"},{"word":"exact","ipa":"/ɪɡˈzækt/","pos":"adj.","def":"确切的","sen":"The exact height of the tree is 5.386 meters.","trans":"这棵树的确切高度是5.386米。","mne":"ex出，向外 + act启动，驱动 → 明确执行某事 → exact确切的"},{"word":"exactly","ipa":"/ɪɡˈzæktli/","pos":"adv.","def":"精确地，准确地，确切地","sen":"I want all my grass to be exactly the same height.","trans":"我要我的草都完全一样高。","mne":"exact精确的 + ly副词后缀 → exactly精确地"},{"word":"exaggerate","ipa":"/ɪɡˈzædʒəreɪt/","pos":"v.","def":"夸大，夸张","sen":"The sheep exaggerated the size of the wolf when retelling the story to his friends.","trans":"这只羊在向朋友们复述这个故事时夸大了狼的体型。","mne":"ex使…，加强意义 + agger堆积 + ate动词后缀 → exaggerate夸大"},{"word":"examination","ipa":"/ɪɡˌzæmɪˈneɪʃn/","pos":"n.","def":"考试；检查；审查，调查","sen":"The students are taking an examination.","trans":"学生们正在参加考试。","mne":"examin检查 + ation名词后缀 → examination检查"},{"word":"examine","ipa":"/ɪɡˈzæmɪn/ ","pos":"v.","def":"检查；调查；审查","sen":"I took my dog to the vet to be examined.","trans":"我带我的狗去兽医那里检查。","mne":"ex向外 + act做，驱使，称量 → (拼写受example影响) → examine检查，测验"},{"word":"example","ipa":"/ɪɡˈzæmpl/","pos":"n.","def":"例子，实例，例证","sen":"The math example was completed by Mr. Li.","trans":"这道数学例题是李老师完成的。","mne":"ex出 + ample拿，获得 → 拿出来作为榜样 → example 样本,榜样"},{"word":"exceed","ipa":"/ɪkˈsiːd/","pos":"v.","def":"超过；超出","sen":"The temperature is expected to exceed 90 degrees Fahrenheit today.","trans":"今天的气温预计会超过90华氏度。","mne":"ex向外 + ceed去；让步 → exceed超出"},{"word":"excellent","ipa":"/ˈeksələnt/","pos":"adj.","def":"优秀的；卓越的","sen":"He's an excellent student who always gets excellent scores.","trans":"他是一名优秀的学生，总是得高分。","mne":"ex离开 + cell监狱 + ent…的 → 品德优秀的人离监狱很远 → excellent杰出的"},{"word":"except","ipa":"/ɪkˈsept/","pos":"conj.","def":"除了，只是；  v.把……除外；  prep.除……之外","sen":"Except for the color, these two cars are identical.","trans":"除了颜色，这两辆车完全一样。","mne":"ex向外 + cept拿走 → 把东西拿走 → except除了"},{"word":"exception","ipa":"/ɪkˈsepʃn/","pos":"n.","def":"例外","sen":"Most of the buildings are modern, but the quadrangle is the only exception.","trans":"这些大多是现代建筑，不过这座四合院是唯一的例外。","mne":"ex出 + cept拿，抓，握住 + ion名词后缀 → exception除外"},{"word":"excess","ipa":"/ɪkˈses/, /ˈekses/","pos":"n.","def":"超过，过度；【化】过量，超额","sen":"There is an excess of food for only one person.","trans":"这些食物对于一个人而言过多了。","mne":"ex出 + cess行走 → excess过度，过剩"},{"word":"excessive","ipa":"/ɪkˈsesɪv/","pos":"adj.","def":"过多的；过分的","sen":"Excessive food intake made the cat overweight.","trans":"贪食使得这只猫超重了。","mne":"ex出，出去 + cess行走 + ive形容词后缀 → excessive过度的"},{"word":"exchange","ipa":"/ɪksˈtʃeɪndʒ/","pos":"v.","def":"交流；交换；交易；  n.交易所","sen":"People can exchange their thoughts and ideas.","trans":"人们可以交换他们的思想和想法。","mne":"ex出 + change交换 → exchange交换，交流"},{"word":"excite","ipa":"/ɪkˈsaɪt/","pos":"v.","def":"使激动，使兴奋","sen":"The message she received excited her.","trans":"她收到的信息让她很激动。","mne":"ex使…出自 + cite使开始工作 → excite激发"},{"word":"excited","ipa":"/ɪkˈsaɪtɪd/","pos":"adj.","def":"激动的；兴奋的，激动的","sen":"Joey was excited when he saw himself on TV.","trans":"乔伊看到自己出现在电视上，兴奋极了。","mne":"excit使兴奋 + ed形容词后缀 → excited 兴奋的"},{"word":"excitement","ipa":"/ɪkˈsaɪtmənt/","pos":"n.","def":"兴奋；刺激，激动","sen":"She couldn't control her excitement at receiving the message.","trans":"她无法控制她收到信息时的兴奋。","mne":"excite使兴奋 + ment名词后缀 → excitement兴奋"},{"word":"exciting","ipa":"/ɪkˈsaɪtɪŋ/","pos":"adj.","def":"令人兴奋的","sen":"It was really exciting when she got into the cat's house.","trans":"对小春来说，进入这个小版的猫事务所十分令人兴奋。","mne":"excit使兴奋 + ing形容词后缀 → exciting使人兴奋的"},{"word":"exclaim","ipa":"/ɪkˈskleɪm/","pos":"v.","def":"呼叫，呼喊，惊叫","sen":"\"Help!\" the woman exclaimed as the man stole her bag.","trans":"这个男人偷了她的包，她大喊：“帮帮我！”","mne":"ex出 + claim叫喊 → exclaim叫喊，大声说"},{"word":"exclude","ipa":"/ɪkˈskluːd/","pos":"v.","def":"排挤，排除；驱逐，赶出","sen":"He was excluded by other teenagers.","trans":"他被其他青少年排挤。","mne":"ex向外 + clude关 → 关在外面 → exclude不包括"},{"word":"exclusive","ipa":"/ɪkˈskluːsɪv/","pos":"adj.","def":"排外的；独有的；高档的","sen":"Sorry, this club is very exclusive: VIPs only.","trans":"对不起，这家俱乐部只接受VIP会员。","mne":"exclu(de)排除 + sive形容词后缀 → exclusive专有的，排外的"},{"word":"excursion","ipa":"/ɪkˈskɜːrʒn/","pos":"n.","def":"远足；（尤指集体度假时的）短途旅行","sen":"We took an excursion into the forest.","trans":"我们去森林里远足了。","mne":"ex出+curs跑，发生+ion行为 → 远足；游览"},{"word":"excuse","ipa":"/ɪkˈskjuːs/","pos":"n.","def":"借口；  v.表示宽恕（读作/ɪkˈskjuːz/）；原谅；辩解","sen":"He made up a stupid excuse for not doing homework.","trans":"他为没做作业编了个愚蠢的借口。","mne":"ex远离 + cuse指控 → 逃脱指控 → excuse借口"},{"word":"execute","ipa":"/ˈeksɪkjuːt/","pos":"v.","def":"处决，处死；完成（动作）；实行；执行（计划）","sen":"This pathetic bird is going to be executed by the cruel hunter.","trans":"这只可怜的小鸟将要被残酷的猎人处决了。","mne":"ex向外 + (s)ec跟随，相接 + ute → 一步接一步的执行 → 实施，将……处死"},{"word":"executive","ipa":"/ɪɡˈzekjətɪv/","pos":"n.","def":"经理；执行者；行政人员；  adj.执行的","sen":"The executives of both companies discussed the issue in depth.","trans":"双方公司的经理深入地讨论了这个问题。","mne":"execut执行 + ive名词后缀 → executive执行者"},{"word":"exercise","ipa":"/ˈeksərsaɪz/","pos":"n.","def":"操练，运动；活动；锻炼；  v.行使，运用；锻炼","sen":"Exercise is the key to keeping healthy.","trans":"锻炼是保持健康的关键。","mne":"ex出 + erc力量 + ise表名词，物品，状态 → exercise练习，锻炼"},{"word":"exert","ipa":"/ɪɡˈzɜːrt/","pos":"v.","def":"尽（力），运用，发挥","sen":"I exerted all my strength to lift all the boxes.","trans":"我用尽全力抬起所有箱子。","mne":"ex向外 + ert连接 → exert尽力"},{"word":"exhaust","ipa":"/ɪɡˈzɔst/","pos":"v.","def":"使筋疲力尽；耗尽；详尽论述；  n.排气装置；废气","sen":"Doing housework exhausts me.","trans":"做家务让我筋疲力尽。","mne":"ex完全 + haust抽出 → exhaust用尽，耗尽"},{"word":"exhausted","ipa":"/ɪɡˈzɔːstɪd/","pos":"adj.","def":"疲惫的","sen":"I am exhausted after a long day of work.","trans":"一天的工作后，我感到精疲力竭。","mne":"exhaust使精疲力竭 + ed形容词后缀 → exhausted 精疲力竭的"},{"word":"exhibit","ipa":"/ɪɡˈzɪbɪt/","pos":"n.","def":"展览会，陈列品；  v.展览，陈列","sen":"Let's go to see the Picasso exhibit tomorrow.","trans":"我们明天去看毕加索的展览吧。","mne":"ex出 + hibit拿住 → 拿来 → exhibit展览，显示"},{"word":"exhibition","ipa":"/ˌeksɪˈbɪʃn/","pos":"n.","def":"展览；陈列","sen":"They are visiting a new oil painting exhibition.","trans":"他们正在参观一场新的油画展览。","mne":"ex出 + hibit拿住 + ion名词后缀 → 拿出去给人看 → 展览；陈列"},{"word":"exist","ipa":"/ɪɡˈzɪst/ ","pos":"v.","def":"存在；生存，生活","sen":"Do aliens exist on other planets?","trans":"其他星球上会有外星人存在吗？","mne":"ex出 + ist站立 → 站出来 → 活下来 → exist存在，生存"},{"word":"existence","ipa":"/ɪɡˈzɪstəns/","pos":"n.","def":"存在","sen":"These fossils prove the existence of dinosaurs.","trans":"这些化石证明了恐龙的存在。","mne":"exist存在 + ence名词后缀 → existence存在"},{"word":"exit","ipa":"/ˈeksɪt/","pos":"n.","def":"出口；  v.【计】退出","sen":"You can find the exit by following the green light.","trans":"跟着绿灯走，你就能找到出口。","mne":"ex出自…… + it走 → exit出口"},{"word":"expand","ipa":"/ɪkˈspænd/","pos":"v.","def":"扩大；膨胀；详细展开","sen":"Our business is expanding across the whole country.","trans":"我们的业务正在全国范围内扩大。","mne":"ex出 + pand展开，膨胀 → expand伸展"},{"word":"expansion","ipa":"/ɪkˈspænʃn/","pos":"n.","def":"膨胀，扩张","sen":"The abnormal expansion of the left ventricle was observed on the echocardiogram.","trans":"超声心动图上发现左心室异常扩张。","mne":"ex出 + pans扩展 + ion表示名词，构成抽象名词 → 扩张，expanse扩大"},{"word":"expansive","ipa":"/ɪkˈspænsɪv/","pos":"adj.","def":"广阔的，扩张的，豪爽的","sen":"The horses are grazing on the expansive grassy land.","trans":"马儿在广阔的草地上撒欢。","mne":""},{"word":"expect","ipa":"/ɪkˈspekt/","pos":"v.","def":"期待；预计，预料，预期","sen":"The little rabbit is expecting the girl to feed it carrots.","trans":"小兔子正期待着女孩喂它吃胡萝卜。","mne":"ex出 + pect=spect看 → 看出去 → expect期待"},{"word":"expectation","ipa":"/ˌekspekˈteɪʃn/","pos":"n.","def":"期待","sen":"My parents have high expectations of me.","trans":"我的父母对我有很高的期待。","mne":"expect期待 + ation表名词 → 期待，希望"},{"word":"expend","ipa":"/ɪkˈspend/","pos":"v.","def":"消费，用尽","sen":"I would expend my savings on a car.","trans":"我会花光存款来买一辆车。","mne":"ex出 + pend花费 → 花钱出去 → expend花费"},{"word":"expenditure","ipa":"/ɪkˈspendɪtʃər/","pos":"n.","def":"支出；花费，支出，消耗","sen":"Our company needs to cut down on unnecessary expenditure.","trans":"我们公司需要削减不必要的支出。","mne":"ex出 + pendi=pend花费 + ture表名词 → expenditure支出，开销"},{"word":"expense","ipa":"/ɪkˈspens/ ","pos":"n.","def":"花费，费用；开销，开支","sen":"Buying a car can be a great expense.","trans":"买车是笔大花销。","mne":"ex出 + pense付钱 → expense支出，花费，消费"},{"word":"expensive","ipa":"/ɪkˈspensɪv/","pos":"adj.","def":"昂贵的，价格高的，花钱多的","sen":"These are so expensive! You shouldn't have bought them for me. ","trans":"这些太贵重了！你不该买给我的。","mne":"ex出 + pens花费 + ive形容词后缀 → 要花钱的 → expensive昂贵的"},{"word":"experience","ipa":"/ɪkˈspɪriəns/","pos":"n.","def":"（一次）经历，感受，体验；  v.体验，感受","sen":"That roller coaster ride was really a frightening experience.","trans":"这趟过山车真是一次可怕的经历。","mne":"ex出 + per尝试 + ience名词后缀 → 尝试出来的东西 → experience经验"},{"word":"experiment","ipa":"/ɪkˈsperɪmənt/ ","pos":"n.","def":"实验；试验；  v.进行实验","sen":"There are many scientists doing experiments to find a cure.","trans":"为了找到治疗方法，许多科学家在进行实验。","mne":"ex出 + peri尝试 + ment名词后缀 → experiment实验"},{"word":"expert","ipa":"/ˈekspɜːrt/ ","pos":"n.","def":"专家；  adj.专业的；熟练的；内行的","sen":"The expert is sharing his knowledge of traditional Chinese medicine on the TV show.","trans":"这个电视节目里的专家正在给观众讲授传统中医知识。","mne":"ex向外 + per尝试，试验 + t后缀 → 经历多次的人 → expert专家，行家"},{"word":"expertise","ipa":"/ˌekspɜːrˈtiːz/","pos":"n.","def":"专门知识，专门技能","sen":"He has considerable expertise in bridge design.","trans":"他在桥梁设计方面有很在行的专门知识。","mne":"expert专家 + ise名词后缀 → 专门知识"},{"word":"expire","ipa":"/ɪkˈspaɪər/","pos":"v.","def":"期满，（期限）终止","sen":"As it has expired, the contract is no longer valid.","trans":"合同已经到期，所以不再有效。","mne":"ex出 + pir=spir呼吸 + e强调 → 只出气不进气 → expire断气；期满"},{"word":"explain","ipa":"/ɪkˈspleɪn/","pos":"v.","def":"说明；解释","sen":"The doctor is explaining the patient's illness to her.","trans":"医生正在向她解释病人的病情。","mne":"ex出 + plain清楚的 → 说清楚的 → explain解释"},{"word":"explanation","ipa":"/ˌekspləˈneɪʃn/","pos":"n.","def":"解释，说明","sen":"The boy is giving his explanation for why he arrived late for school.","trans":"男孩正在解释他上学迟到的原因。","mne":"explan=explain解释 + ation名词后缀，表行为 → explanation说明，解释"},{"word":"explicit","ipa":"/ɪkˈsplɪsɪt/","pos":"adj.","def":"明确的","sen":"The map shows an explicit route to me.","trans":"这张地图给我指出了明确的路线。","mne":"ex出 + plic折叠 + it → 说话不重叠的 → explicit明确的"},{"word":"explode","ipa":"/ɪkˈsploʊd/","pos":"v.","def":"爆炸；爆发","sen":"If a light bulb explodes, it is very dangerous to be nearby.","trans":"如果灯泡爆炸了，在那附近是非常危险的。","mne":"ex出 + plode爆炸声 → 发出爆炸声 → explode爆炸"},{"word":"exploit","ipa":"/ɪkˈsplɔɪt/","pos":"v.","def":"剥削，压榨；开发；  n.辉煌的功绩（读作/ˈeksplɔɪt）","sen":"The greedy employer exploits his workers for his own profits.","trans":"这个贪婪的老板为了自己的利益剥削工人。","mne":"ex向外 + ploit卷 → exploit剥削"},{"word":"exploration","ipa":"/ˌekspləˈreɪʃn/","pos":"n.","def":"探索；探险","sen":"She used her flashlight during her exploration of the cave.","trans":"她拿着手电筒在洞穴里探索。","mne":"ex出 + plor喊，哭 + ation名词后缀 → 喊出来 → 探索"},{"word":"explore","ipa":"/ɪkˈsplɔːr/","pos":"v.","def":"探险","sen":"They will explore the dark cave.","trans":"他们即将探索这个漆黑的洞穴。","mne":"ex出，向外 + plore哭泣，叫喊 → explore探险"},{"word":"explorer","ipa":"/ɪkˈsplɔːrər/","pos":"n.","def":"探险家，探险者","sen":"The explorer is reading the map.","trans":"这位探险家正在看地图。","mne":"explor=explore探索 + er表示人 → 探险家"},{"word":"explosion","ipa":"/ɪkˈsploʊʒn/","pos":"n.","def":"爆炸；激增","sen":"The firework explosion was amazing.","trans":"烟花爆炸的场景真是一场视觉盛宴。","mne":"explo(de)爆炸 + sion名词后缀 → explosion爆炸"},{"word":"explosive","ipa":"/ɪkˈsploʊsɪv/ ","pos":"adj.","def":"爆炸的，引起爆炸的；  n.炸药","sen":"The scientist was hurt by explosive liquid!","trans":"这个科学家被易爆的液体伤到了！","mne":"explos=explode爆炸 + ive表名词 → explosive炸药"},{"word":"export","ipa":"/ɪkˈspɔːrt/, /ˈekspɔːrt/","pos":"v.","def":"出口，输出；  n.出口，输出","sen":"Our company exports products to many different countries.","trans":"我们公司向许多国家出口货物。","mne":"ex出 + port拿，引申为港口 → 拿出港口 → 出口"},{"word":"exportation","ipa":"/ˌekspɔːrˈteɪʃn/","pos":"n.","def":"出口","sen":"Modern transportation makes exportation much easier.","trans":"现代运输工具使出口变得更加简单。","mne":""},{"word":"expose","ipa":"/ɪkˈspəʊz/","pos":"v.","def":"显露，暴露；揭露","sen":"Some cement fell from the wall, leaving the bricks exposed.","trans":"墙上的水泥掉下来后，砖块露了出来。","mne":"ex出，出去 + pose放 → 放出去 → expose暴露"},{"word":"exposure","ipa":"/ɪkˈspoʊʒər/","pos":"n.","def":"暴露；揭露，揭发","sen":"Because of exposure to the sun, the corn is scorched.","trans":"因为暴露在太阳底下，这根玉米被晒伤了。","mne":"ex出 ＋ pos放 ＋ ure名词后缀，表行为、状态 → exposure暴露，揭露"},{"word":"express","ipa":"/ɪkˈspres/","pos":"v.","def":"表达，表示；  adj.明确的；  n.快递；快车","sen":"I would like to express my love for you.","trans":"我想表达对你的喜爱。","mne":"ex出来 + press挤压 → 挤出来 → express表达"},{"word":"expression","ipa":"/ɪkˈspreʃn/","pos":"n.","def":"表情；表达；词，词组，措辞","sen":"She had a puzzled expression on her face when she saw the math problem.","trans":"当她看到那道数学题时，脸上露出了困惑的表情。","mne":"ex出来 + press挤压 + ion名词后缀 → expression表达；表情"},{"word":"extend","ipa":"/ɪkˈstend/","pos":"v.","def":"延伸；给予，表示；延长；提供","sen":"The highway extends all the way to the horizon.","trans":"这条公路向着地平线无限延伸。","mne":"ex出 + tend延伸 → 伸出去 → extend扩张"},{"word":"extended","ipa":"/ɪkˈstendɪd/","pos":"adj.","def":"延长的，伸展的","sen":"The shop now has extended hours until midnight.","trans":"这家商店现在的营业时间延长到了半夜12点。","mne":""},{"word":"extension","ipa":"/ɪkˈstenʃn/","pos":"n.","def":"延伸；扩展；电话分机","sen":"The extension of the tumor into surrounding tissues complicates surgical removal.","trans":"肿瘤向周围组织的延伸使手术切除变得复杂。","mne":"ex出 + tend伸展 + sion表名词 → 延展，扩张；延期"},{"word":"extensive","ipa":"/ɪkˈstensɪv/","pos":"adj.","def":"广泛的；广阔的；大量的","sen":"The rain led to extensive damage to the area.","trans":"雨水导致该地区遭受大面积洪水破坏。","mne":"ex向外 + tens延伸 + ive形容词后缀 → 向外伸展的 → extensive大面积的"},{"word":"extent","ipa":"/ɪkˈstent/","pos":"n.","def":"程度；长度；广度","sen":"The extent of the damage from the earthquake is massive.","trans":"这场地震的破坏程度太大了。","mne":"ex出 + tent伸展 → 伸出去的范围 → extent范围"},{"word":"external","ipa":"/ɪkˈstɜːrnl/","pos":"adj.","def":"外面的，外部的；外国的","sen":"This medicine is just for external use, so we can't spray it into our mouth.","trans":"这种药只能外用，因此我们不能往嘴里喷。","mne":"exter出去 + nal=al……的 → 出去的 → 在外面的  → external外部的"},{"word":"externally","ipa":"/ɪkˈstɜːrnəli/","pos":"adv.","def":"【航】外部地","sen":"The aircraft is externally inspected before each flight.","trans":"每次飞行前，都会对飞机进行外部检查。","mne":""},{"word":"extra","ipa":"/ˈekstrə/","pos":"adj.","def":"额外的，附加的；  adv.额外地；  n.额外的事务","sen":"Could you give me some extra ice cream?","trans":"你能再多给我一点儿冰激凌吗？","mne":"extra=out出去 → 出去的 → 余出的 → extra额外的"},{"word":"extraordinary","ipa":"/ɪkˈstrɔːrdəneri/","pos":"adj.","def":"非同寻常的；非凡的","sen":"Her little daughter has extraordinary musical talent.","trans":"她的小女儿在音乐方面天赋异禀。","mne":"extra超过 + ordinary普通的 → extraordinary特别的"},{"word":"extreme","ipa":"/ɪkˈstriːm/","pos":"adj.","def":"极端的；极限的；  n.极端","sen":"Extreme weather conditions destroyed the city.","trans":"极端天气状况摧毁了这座城市。","mne":"extr出去 + eme表最高级 → extreme极端的"},{"word":"extremely","ipa":"/ɪkˈstriːmli/","pos":"adv.","def":"极其，非常","sen":"Compared with the Earth, the Sun is extremely large.","trans":"和地球相比，太阳非常大。","mne":"extreme极端的 + ly表副词 → 过分地，极端地"},{"word":"eye","ipa":"/aɪ/","pos":"n.","def":"眼睛；  v.注视","sen":"The man has three eyes!","trans":"这个男的有三只眼睛！","mne":""},{"word":"eyesight","ipa":"./ˈaɪsaɪt/","pos":"n.","def":"视力","sen":"Your eyesight is terrible! You need glasses.","trans":"你视力太差了！你需要配眼镜。","mne":"eye眼睛 + sight眼光 → eyesight视力"},{"word":"face","ipa":"/feɪs/","pos":"n.","def":"脸部；  v.面对，面临；面对（困境）","sen":"The patient has a cut on her face which needs stitches.","trans":"病人的脸部有一处需要缝合的切口。","mne":"face=fac表示脸、面 → face脸，表面，外表"},{"word":"facility","ipa":"/fəˈsɪləti/","pos":"n.","def":"设施，设备；才能，资质；（供特定用途的）场所","sen":"The new sports facility includes a swimming pool, a gymnasium, and several tennis courts.","trans":"新的体育设施包括一个游泳池、一个体育馆和几个网球场。","mne":"facile简单的 + ity表名词 → 促进事务简化的设施或工具  → facility设施，设备"},{"word":"fact","ipa":"/fækt/","pos":"n.","def":"事实，现实；真相；实际","sen":"My photo proved the fact that the ghosts weren't real.","trans":"我的照片证明了一个事实：这些鬼都是假的。","mne":""},{"word":"factor","ipa":"/ˈfæktər/","pos":"n.","def":"因素；系数；  v.把…因素包括进去","sen":"An important factor for him when buying a car is its appearance.","trans":"车的外观是他买车时考虑的一个重要因素。","mne":"fact做，制作 + or表名词，人或物 → 促使人做的东西 → factor要素；动力"},{"word":"factory","ipa":"/ˈfæktəri/ /ˈfæktri/","pos":"n.","def":"工厂，制造厂","sen":"This chemical factory produces plastics.","trans":"这个化工厂生产塑料。","mne":"fact做 + ory场所，地点后缀 → 做东西的场所 → factory工厂"},{"word":"faculty","ipa":"/ˈfæklti/","pos":"n.","def":"能力，才能；全体教员；院系","sen":"The boy has the faculty to play the piano.","trans":"这个男孩有弹钢琴的能力。","mne":"facul做 + ty表名词 → 会做东西 → faculty能力"},{"word":"fade","ipa":"/feɪd/","pos":"v.","def":"逐渐消失；褪色，褪去","sen":"The trees were fading away into the mist.","trans":"树渐渐消失在薄雾中。","mne":""},{"word":"fail","ipa":"/feɪl/","pos":"v.","def":"失败； 不及格；衰退；  n.失败；不及格","sen":"The rocket failed to launch.","trans":"火箭发射失败了。","mne":""},{"word":"failure","ipa":"/ˈfeɪljər/","pos":"n.","def":"失败","sen":"He doesn't believe his failure in the EQ test.","trans":"他无法相信自己在情商测试中的失败。","mne":"fail犯错误，欺骗 + ure名词后缀 → 错误状态 → failure失败"},{"word":"faint","ipa":"/feɪnt/","pos":"v.","def":"晕倒；昏厥；  adj.（光、声、味）微弱的","sen":"The hot weather made him faint.","trans":"炎热的天气使他晕倒了。","mne":""},{"word":"fair","ipa":"/fer/","pos":"adj.","def":"合理的，公平的；相当的，尚好的；  n.集市，市场，交易会","sen":"Compared to that on the left, the drink on the right is being sold at a fair price.","trans":"相比左边的饮料，右边的饮料售价更合理。","mne":""},{"word":"fairly","ipa":"/ˈferli/","pos":"adv.","def":"相当地；公平地","sen":"The bag on the right looks fairly heavy.","trans":"右边那个书包看上去相当沉。","mne":"fair公平 + ly……地 → fairly公平地"},{"word":"faith","ipa":"/feɪθ/","pos":"n.","def":"宗教信仰；信心；信任","sen":"Many people go on an annual pilgrimage to this sacred place to express their faith.","trans":"很多人每年会到这个神圣的地方来参拜，以表达他们的信仰。","mne":""},{"word":"faithful","ipa":"/ˈfeɪθfl/","pos":"adj.","def":"忠诚的，忠实的","sen":"Dogs are the most faithful pets you can have.","trans":"狗是你可以拥有的最忠诚的宠物。","mne":"faith忠诚 + ful表形容词 → faithful忠诚的"},{"word":"faithfully","ipa":"/ˈfeɪθfəli/","pos":"adv.","def":"忠实地，忠诚地；忠诚地","sen":"This dog faithfully waits for its master to come home every day.","trans":"这只狗每天忠诚地等待他的主人回家。","mne":"faith忠实 ＋ ful...的 ＋ ly...地 → faithfully忠实地"},{"word":"fake","ipa":"/feɪk/","pos":"adj.","def":"假的，假装的，冒充的","sen":"Do you know which rabbit is the fake one?","trans":"你知道哪一只小兔子是假的吗？","mne":""},{"word":"fall","ipa":"/fɔːl/   ","pos":"v.","def":"落下；坠落；下降，减弱；  v.跌落；  n.落下；秋天","sen":"An apple fell from the tree and hit Newton.","trans":"苹果从树上落下并砸中了牛顿。","mne":""},{"word":"false","ipa":"/fɔːls/","pos":"adj.","def":"错误的","sen":"Is this question true or false?","trans":"这道题是对还是错？","mne":""},{"word":"fame","ipa":"/feɪm/","pos":"n.","def":"名声，声誉","sen":"The actor enjoys fame and loves the attention that it brings him.","trans":"这位男演员沉浸在名望中，并享受着由此带来的关注度。","mne":""},{"word":"familiar","ipa":"/fəˈmɪliər/","pos":"adj.","def":"熟悉的，通晓的；不拘礼节的；亲密的；随便的；  n.密友；常客；高级官吏的家属","sen":"Its owner's voice is very familiar to the dog.","trans":"狗对它主人的声音很熟悉。","mne":"famili家庭 + ar……的 → familiar熟悉的"},{"word":"family","ipa":"/ˈfæməli/","pos":"n.","def":"家庭；家族；  adj.家庭的，家族的","sen":"There are five people in my family.","trans":"我家里有五口人。","mne":""},{"word":"famine","ipa":"/ˈfæmɪn/","pos":"n.","def":"饥荒","sen":"These poor African kids suffer a lot from famine.","trans":"这些可怜的非洲儿童饱受饥荒之苦。","mne":"fam饿 + ine表名词 → famine饥荒"},{"word":"famous","ipa":"/ˈfeɪməs/ ","pos":"adj.","def":"著名的","sen":"When I go to America, I want to go and see the famous Statue of Liberty.","trans":"当我去美国的时候，我想去看著名的自由女神像。","mne":"fam=fame荣誉 + ous形容词后缀 → famous著名的"},{"word":"fan","ipa":"/fæn/","pos":"n.","def":"风扇，扇子；（影，球等）迷；  v.煽动，激起","sen":"In summer, she cools herself in front of an electric fan.","trans":"夏日里，她坐在电扇前让自己凉快些。","mne":""},{"word":"fancy","ipa":"/ˈfænsi/","pos":"n.","def":"幻想，想象力；喜爱；  adj.奢华的；昂贵的；  v.想要；想象，幻想；喜欢","sen":"Her childhood fancy was to become a famous singer.","trans":"她童年的幻想是成为一名著名歌手。","mne":""},{"word":"fantastic","ipa":"/fænˈtæstɪk/","pos":"adj.","def":"不可思议的","sen":"Welcome to this fantastic world where everything is made of tasty treats.","trans":"欢迎来到奇异世界，这里所有的东西都是甜食做的。","mne":""},{"word":"fantasy","ipa":"/ˈfæntəsi/","pos":"n.","def":"幻想，想象","sen":"She lives in a fantasy world where she imagines herself as a queen.","trans":"她生活在一个幻想世界里，把自己想象成女王。","mne":"fan=fancy幻想 + tasy名词后缀 → fantasy想象，幻想"},{"word":"far","ipa":"/fɑːr/","pos":"adv.","def":"（空间或时间）远，久远；  adj.远的，遥远的","sen":"Though we're far apart, you're always in my heart.","trans":"虽然我们相隔遥远，但你永远在我心中。","mne":""},{"word":"fare","ipa":"/fer/","pos":"n.","def":"交通费；票价；  v.（事情）进行得（好或坏）","sen":"She paid three dollars for the bus fare.","trans":"她付了三美元的公交车费。","mne":""},{"word":"farewell","ipa":"/ˌferˈwel/","pos":"n.","def":"再见；告别，离别","sen":"She said her farewell and drove off.","trans":"她说了句再见，就开车走了。","mne":"fare旅途 + well好的 → 祝路途愉快 → farewell再会；告别"},{"word":"farm","ipa":"/fɑːrm/","pos":"n.","def":"农场，饲养场","sen":"My family has just bought an organic farm—they believe in natural food.","trans":"我的家人刚刚买了块有机农场——他们相信自然生长的食物。","mne":""},{"word":"farmer","ipa":"/ˈfɑːrmər/","pos":"n.","def":"农场主；农民，农夫","sen":"Every day, the farmer checked the development of his crop fields.","trans":"这位农场主每天都会查看农田的生长情况。","mne":"farm务农 + er表人 → 务农的人 → farmer农民"},{"word":"farther","ipa":"/ˈfɑːrðər/","pos":"adv.","def":"更远地；  adj.更远的","sen":"We need to move farther to reach the destination.","trans":"我们需要再往前走才会到达目的地。","mne":""},{"word":"fascinate","ipa":"/ˈfæsɪneɪt/","pos":"v.","def":"使着迷","sen":"That girl is fascinated by the delicious food.","trans":"那个姑娘被美食迷得神魂颠倒。","mne":"fascin迷住 + ate动词后缀，使之成…… → fascinate使……入迷"},{"word":"fashion","ipa":"/ˈfæʃn/","pos":"n.","def":"时髦，风尚；  v.制作，塑造","sen":"He is trying to keep up with the latest fashion trend.","trans":"他在努力追随最新的时尚潮流。","mne":"fash放置，设置 + ion名词后缀 → fashion制作，塑造，时尚"},{"word":"fashionable","ipa":"/ˈfæʃnəbl/","pos":"adj.","def":"流行的，时髦的","sen":"Her dress in the Cannes Film Festival is so fashionable!","trans":"她在戛纳电影节上的着装太时髦了！","mne":"fashion时髦 + able……的 → fashionable时髦的"},{"word":"fast","ipa":"/fæst/","pos":"adj.","def":"快速的，迅速的，动作敏捷的","sen":"The car was going so fast! I could hardly see it!","trans":"那辆车开得太快了！我几乎看不见它了。","mne":""},{"word":"fasten","ipa":"/ˈfæsn/","pos":"v.","def":"扎牢；扣住","sen":"My mother is helping me fasten my seat belt.","trans":"我的妈妈正在帮我系安全带。","mne":"fast紧紧地 + en动词后缀 → fasten扎牢"},{"word":"fat","ipa":"/fæt/","pos":"adj.","def":"肥的，肥胖的；  n.【生】脂肪","sen":"You'll become fat if you drink too much soda.","trans":"如果喝太多汽水的话，你会长胖的。","mne":""},{"word":"fatal","ipa":"/ˈfeɪtl/","pos":"adj.","def":"致命的；灾难性的，毁灭性的","sen":"Some food like chocolate may be fatal to dogs.","trans":"有些食物，比如巧克力，对狗来说是致命的。","mne":""},{"word":"fate","ipa":"/feɪt/","pos":"n.","def":"命运","sen":"It was my fate to marry him.","trans":"我嫁给他是命中注定的。","mne":""},{"word":"father","ipa":"/ˈfɑːðər/","pos":"n.","def":"爸爸，父亲","sen":"A good father spends time with his kids.","trans":"好爸爸会花时间陪他的孩子。","mne":""},{"word":"fatigue","ipa":"/fəˈtiːɡ/","pos":"n.","def":"疲乏，劳累","sen":"Due to heavy fatigue, I keep falling asleep at the desk.","trans":"我很疲劳，所以直接趴桌上睡着了。","mne":"fat断裂 + ig做，驱动 + ue动词后缀 → fatigue快断裂的，接近极限点的 → fatigue疲乏，劳累"},{"word":"fault","ipa":"/fɔːlt/","pos":"n.","def":"责任，过错；【地质学】断层；  v.责备，挑错","sen":"It's the boy's fault that the window was broken.","trans":"窗户破了是这个男孩的错。","mne":""},{"word":"favor","ipa":"/ˈfeɪvər/","pos":"v.","def":"偏爱；  n.偏爱（=favour）；赞成","sen":"I need to become more healthy, so I would favor an apple over a burger.","trans":"我需要变得更健康，所以比起汉堡，我更偏好苹果。","mne":""},{"word":"favorable","ipa":"/ˈfeɪvərəbl/","pos":"adj.","def":"赞同的，称赞的；有利的，有助于...的","sen":"My colleagues are favorable to my creativity.","trans":"我的同事们对我的创意交口称赞。","mne":"favor赞同 + able……的 → favorable赞同的，有利的"},{"word":"favorite","ipa":"/'feɪvərɪt/","pos":"adj.","def":"最爱的（同favourite）；  n.最喜爱的人或物","sen":"I love all kinds of food, but my favorite food is hamburgers.","trans":"我喜欢各种各样的食物，但是最爱的还是汉堡。","mne":"favor喜爱 + ite表名词或形容词 → 最喜欢的人或物 → favorite最喜爱的"},{"word":"favour","ipa":"/ˈfeɪvər/","pos":"n.","def":"帮助，恩惠，好事；  v.偏爱，较喜欢；有利于","sen":"The man in white did the man in red a favour by helping him to climb up.","trans":"穿白色衣服的男人帮助穿红色衣服的男人爬上来，对他做了一个好事。","mne":""},{"word":"favourable","ipa":"/ˈfeɪvərəbəl/","pos":"adj.","def":"【财】有利的，良好的","sen":"The new tax policy is favourable for small businesses.","trans":"新的税收政策对小型企业有利。","mne":"favour赞成 + able…的 → favourable赞许的"},{"word":"favourite","ipa":"/ˈfeɪvərɪt/","pos":"adj.","def":"最喜欢的，中意的（=favorite）","sen":"My favourite pet is my dog, Lucy.","trans":"我最喜欢的宠物是我的狗狗，露西。","mne":""},{"word":"fax","ipa":"/fæks/","pos":"n.","def":"传真（机）","sen":"There is a fax machine and some paper documents on the table.","trans":"桌上有一台传真机和一些文件。","mne":""},{"word":"fear","ipa":"/fɪr/","pos":"v.","def":"害怕；敬畏；  n.害怕","sen":"The cat fears the mice running after it.","trans":"那只猫害怕追它的老鼠。","mne":""},{"word":"feasible","ipa":"/'fi:zəbl/","pos":"adj.","def":"【计】可行的；可行的，行得通的","sen":"The function is_solution_feasible checks if the given solution meets all the constraints and returns a boolean value.","trans":"函数is_solution_feasible检查给定的解决方案是否满足所有约束，并返回一个布尔值。","mne":"feas做 + ible能……的 → 能够做的 → feasible可行的"},{"word":"feather","ipa":"/ˈfeðər/","pos":"n.","def":"羽毛","sen":"This beautiful hat is made of feathers.","trans":"这顶漂亮的帽子是羽毛做的。","mne":""},{"word":"feature","ipa":"/ˈfitʃər/","pos":"n.","def":"特征，特点，特色；（报纸或杂志的）特写；  v.以……为特色；起重要作用，作为主要角色","sen":"The thick lips are a feature of Lord Bao.","trans":"厚嘴唇是包大人的一个特征。","mne":"feat做，制作 + ure名词后缀 → 做事的状态 → 做事特征 → feature面貌；特征"},{"word":"february","ipa":"/ˈfebrueri/","pos":"n.","def":"二月（略作Feb.）","sen":"February is a special month and only has 28 days this year.","trans":"二月份是一个特殊的月份，这一年的二月份仅有28天。","mne":""},{"word":"federal","ipa":"/ˈfedərəl/","pos":"adj.","def":"联邦制的；联邦政府的","sen":"The USA is a federal republic.","trans":"美国是一个联邦共和国。","mne":"feder=league联盟 + al表形容词 → federal联盟的，联邦的"},{"word":"fee","ipa":"/fiː/","pos":"n.","def":"费用","sen":"The bill shows the specific fees of the service.","trans":"账单显示了服务的各项具体费用。","mne":""},{"word":"feed","ipa":"/fiːd/","pos":"v.","def":"给（人或动物）食物，喂，饲养；  n.喂食，进食","sen":"I used to nurse my baby myself; now I just feed him out of the bottle.","trans":"我过去要亲自给宝宝喂奶，现在只要用瓶子喂他就行了。","mne":""},{"word":"feedback","ipa":"/ˈfiːdbæk/","pos":"n.","def":"反馈","sen":"A man gave his feedback by ticking a smile box.","trans":"一个男人通过在笑脸框里打钩给出了反馈。","mne":"feed向…提供 + back返回 → feedback反馈"},{"word":"feel","ipa":"/fiːl/","pos":"v.","def":"触，摸，摸起来；认为；  n.感受","sen":"He feels happy when feeling his wife's belly.","trans":"他摸着妻子的肚子，心里充满了喜悦。","mne":""},{"word":"feeling","ipa":"/ˈfiːlɪŋ/","pos":"n.","def":"感觉","sen":"She was overcome with a nice feeling.","trans":"一种美好的感觉占据了她的内心。","mne":"feel感觉 + ing行业，状态，行为 → feeling感情，感觉"},{"word":"fellow","ipa":"/ˈfeloʊ/","pos":"n.","def":"家伙，男人；同伴；同事；同辈；  adj.同类的，同伴的","sen":"Those two fellows are celebrating their success.","trans":"那两个男人在庆祝他们的成功。","mne":"fe钱 + llow放下 → 在合资企业中放下钱财的人 → fellow同事，伙伴"},{"word":"female","ipa":"/ˈfiːmeɪl/","pos":"adj.","def":"女性的；雌性的；  n.女子；雌性动物","sen":"This is a pink symbol representing female characteristics.","trans":"这是个代表女性特征的粉色标志。","mne":"fem=female女，妇女 + ale → female女的，雌性的动物；女子"},{"word":"fence","ipa":"/fens/","pos":"n.","def":"篱笆，围栏，栅栏；  v.击剑","sen":"The school is surrounded by a large fence.","trans":"学校被很大的围栏围住。","mne":""},{"word":"fertile","ipa":"/ˈfɜːrtl/","pos":"adj.","def":"肥沃的；多产的；能生育的","sen":"The corn grows well in this fertile land.","trans":"玉米苗在这片肥沃的土地上长得很好。","mne":"fert带来，拿来 + ile...的 → 能带来粮食 → fertile肥沃的"},{"word":"fertiliser","ipa":"/'fɜːtɪlaɪzə/","pos":"n.","def":"化肥，肥料（=fertilizer）","sen":"How much fertiliser does a large corn farm need?","trans":"一个大的玉米农场需要多少肥料？","mne":""},{"word":"fertilizer","ipa":"/ˈfɜːrtəlaɪzər/ ","pos":"n.","def":"肥料，化肥","sen":"She has many bags of fertilizer in her storage room.","trans":"她的储藏室里有许多袋肥料。","mne":"fertilize施肥 + er名词后缀，表示实施动作的人或物 → fertilizer肥料"},{"word":"festival","ipa":"/ˈfestɪvl/","pos":"n.","def":"节日；活动","sen":"Traditionally people spend time with their families during the Chinese Spring Festival.","trans":"人们历来在春节期间与家人共度时光。","mne":"fest节日；祝宴 +ival表名词 → festival节目，宴会"},{"word":"festive","ipa":"/ˈfestɪv/","pos":"adj.","def":"庆祝的，喜庆的，欢乐的，节日似的","sen":"The festive atmosphere was enhanced by the brilliant firework display.","trans":"绚丽烟花的绽放增强了节日的喜庆气氛。","mne":"fest节目+ive...的 → 表演节目的日子 → 节日 → 节日的"},{"word":"fetch","ipa":"/fetʃ/","pos":"v.","def":"取来；售得；  v.拿来；（去）拿来；  n.拿来，取来","sen":"\"Here, doggy! Fetch!\" I shouted while throwing the ball.","trans":"我一边扔球一边喊道：“小狗，取回来！”","mne":"fet=fed脚 + ch → 跑腿 → fetch取来"},{"word":"fever","ipa":"/ˈfiːvər/","pos":"n.","def":"发热","sen":"The girl is sick and has a high fever.","trans":"这个女孩生病了并且发高烧。","mne":""},{"word":"few","ipa":"/fjuː/","pos":"adj.","def":"有些；很少","sen":"There are few apples left in the basket.","trans":"篮子里剩下很少的苹果了。","mne":""},{"word":"fiber","ipa":"/ˈfaɪbər/","pos":"n.","def":"纤维（物质）（=fibre）","sen":"We can see the fibers of the rope under a magnifying glass.","trans":"在放大镜下，我们能看见这条绳子的纤维。","mne":""},{"word":"fibre","ipa":"/ˈfaɪbər/","pos":"n.","def":"纤维（=fiber）","sen":"We'll use these fibres to make clothing.","trans":"我们能用这些纤维来做衣服。","mne":""},{"word":"fiction","ipa":"/ˈfɪkʃn/","pos":"n.","def":"小说；虚构","sen":"This is a work of fiction about wizards and dragons.","trans":"这是一本关于巫师和龙的小说。","mne":"fict塑造，虚构 + ion名词后缀 → 虚构的故事 → fiction小说"},{"word":"field","ipa":"/fi:ld/","pos":"n.","def":"田野，田地；运动场；领域；场地；  v.处理，应付","sen":"There is a large field around the farm house.","trans":"农舍周围有一大片田野。","mne":""},{"word":"fierce","ipa":"/fɪrs/","pos":"adj.","def":"凶猛的，凶狠的","sen":"The tiger showing its sharp teeth looks so fierce.","trans":"这只露出锋利牙齿的老虎看上去真凶猛。","mne":""},{"word":"fifteen","ipa":"/ˌfɪfˈtiːn/","pos":"num.","def":"十五，十五个","sen":"My son will turn fifteen years old this year.","trans":"我儿子今年就要15岁了。","mne":"fif=five五 + teen十几 → fifteen十五"},{"word":"fifth","ipa":"/fɪfθ/","pos":"n.","def":"第五；五分之一","sen":"She finished fifth in the race.","trans":"她在比赛中获得第五名。","mne":"fif=five五 + th第… → fifth第五，五分之一"},{"word":"fifty","ipa":"/ˈfɪfti/","pos":"num.","def":"五十，五十个","sen":"My father is turning fifty today.","trans":"我父亲今天50岁了。","mne":"fif=five五 + ty十数 → fifty五十"},{"word":"fight","ipa":"/faɪt/","pos":"v.","def":"打架，打斗，搏斗；争吵；奋斗；  n.斗争；搏斗；比赛","sen":"\"Let's fight!\" the man said to the other player.","trans":"\"让我们战斗吧！\" 那个男人对另一位参赛选手说道。","mne":""},{"word":"figure","ipa":"/ˈfɪɡjər/","pos":"n.","def":"身形，身影；数字；人影，人物；  v.计算出；认为，认定；明白，理解","sen":"I saw a dark figure moving through quickly.","trans":"我看见一个黑色的身影快速穿过。","mne":""},{"word":"file","ipa":"/faɪl/","pos":"n.","def":"文件；  v.把……归档","sen":"Click here to open the file.","trans":"单击此处以打开文件。","mne":""},{"word":"fill","ipa":"/fɪl/","pos":"v.","def":"装满，注满，填满","sen":"The bottle is filled with juice.","trans":"这个瓶子里装满了果汁。","mne":""},{"word":"film","ipa":"/fɪlm/","pos":"n.","def":"电影；  v.拍摄，拍摄电影","sen":"This film tells of a love story that happened on a ship.","trans":"这部电影讲述了一个发生在船上的爱情故事。","mne":""},{"word":"filter","ipa":"/ˈfɪltər/","pos":"v.","def":"过滤，渗透；  n.过滤（器）","sen":"Each layer filters smaller particles from the air.","trans":"每一层过滤层都将空气中更小的微粒过滤出来。","mne":""},{"word":"final","ipa":"/ˈfaɪnl/","pos":"adj.","def":"最后的；决定性的；  n.决赛","sen":"The competition is in its final stage.","trans":"比赛进入了最后阶段。","mne":"fin结束 + al表形容词 → final最后的"},{"word":"finally","ipa":"/ˈfaɪnəli/","pos":"adv.","def":"最终地，最后地；最终，终于","sen":"He finally got served for drinks after queueing for one hour.","trans":"排了一小时队，他最后买到了饮料。","mne":"fin结束，范围 + ally表示方式、程度、状态 → finally最后"},{"word":"finance","ipa":"/ˈfaɪnæns/","pos":"v.","def":"资金供给，筹措资金；  n.金融","sen":"The old man financed a poor student to go to college.","trans":"老人资助那个贫困学生上大学。","mne":""},{"word":"financial","ipa":"/faɪˈnænʃl/","pos":"adj.","def":"金融的；财政的","sen":"This is one of the most famous financial cities in the world.","trans":"这是世界上最有名的金融城之一。","mne":"financ=finance金融 + ial属于……的 → financial财政的，金融的"},{"word":"find","ipa":"/faɪnd/","pos":"v.","def":"找到；发现；认为","sen":"You might find the criminals if you follow the footprints.","trans":"如果你跟着这些脚印，也许能找到罪犯！","mne":""},{"word":"finding","ipa":"/ˈfaɪndɪŋ/","pos":"n.","def":"发现，调查结果","sen":"This finding surprised the scientists.","trans":"这一发现令科学家们大吃一惊。","mne":"find发现 + ing构成抽象名词 → finding发现；调查的结果"},{"word":"fine","ipa":"/ˈfaɪn/","pos":"adj.","def":"好的；晴朗的；健康的；  n.罚款；  v.罚款","sen":"I can tell by the smell that this is a fine wine.","trans":"我能从气味辨别，这是好葡萄酒。","mne":""},{"word":"finger","ipa":"/ˈfɪŋɡər/","pos":"n.","def":"手指","sen":"\"Do not point your finger at me!\"","trans":"“不要用手指着我！”","mne":"fing五 + er名词后缀，人或物 → 人有五个手指 → finger手指"},{"word":"finish","ipa":"/ˈfɪnɪʃ/","pos":"v.","def":"完成；（使）结束","sen":"The girl finished first in the race.","trans":"女孩在赛跑中第一个完成比赛。","mne":"fin结束，范围 + ish单词后缀 → finish完成，结束"},{"word":"fire","ipa":"/ˈfaɪər/","pos":"n.","def":"火；  v.开火，射击；解雇；激发","sen":"There is a fire burning by the sea.","trans":"海边有一堆燃烧的火。","mne":""},{"word":"firm","ipa":"/fɜːrm/","pos":"n.","def":"公司；  adj.牢固的，稳固的；结实的","sen":"It's a small firm with only four employees.","trans":"这是一家只有四名员工的小公司。","mne":""},{"word":"firmly","ipa":"/ˈfɜːrmli/","pos":"adv.","def":"坚固地，稳固地；坚定地，坚决地","sen":"Partners in this deal hold hands firmly.","trans":"这笔交易中的伙伴们紧紧地握了手。","mne":"firm坚固的 + ly...地 → 坚固地"},{"word":"first","ipa":"/fɜːrst/","pos":"det.","def":"第一，首要的；  adj.第一（位）的，首要的；  adv.首先，第一；  num.第一","sen":"Crossing the finish line in first place is an amazing feeling.","trans":"第一个越过终点线是一种很棒的感觉。","mne":""},{"word":"fish","ipa":"/fɪʃ/","pos":"n.","def":"鱼（单复数同形）；鱼肉；  v.钓鱼","sen":"Fish have very simple lives.","trans":"鱼过着很简单的生活。","mne":""},{"word":"fit","ipa":"/fɪt/","pos":"v.","def":"使适合；合……的身；  adj.合适的；健康的","sen":"Let's put the last piece in. It fits perfectly!","trans":"让我们把最后一块放进去。它非常合适！","mne":""},{"word":"five","ipa":"/faɪv/","pos":"num.","def":"五，五个","sen":"Five is my favorite number.","trans":"5是我最喜欢的数字。","mne":""},{"word":"fix","ipa":"/fɪks/","pos":"v.","def":"修理；使固定；  n.方位确定，定位","sen":"He is fixing the car.","trans":"他在修车。","mne":""},{"word":"flag","ipa":"/flæɡ/","pos":"n.","def":"国旗，旗帜；  v.（以旗子）标出，标记","sen":"There are many flags flying in the air.","trans":"许多旗帜在空中飘扬。","mne":""},{"word":"flash","ipa":"/flæʃ/","pos":"n.","def":"闪光；  v.发火花；发出信号；  adj.一闪而过的","sen":"There was a blinding flash after I triggered the camera.","trans":"我摁下相机，一道炫目的闪光亮起。","mne":""},{"word":"flat","ipa":"/flæt/","pos":"adj.","def":"平坦的；扁平的；  n.平面；公寓；  adv.平直地","sen":"The road stretched ahead across the flat landscape.","trans":"公路向前延伸，经过一片平地。","mne":""},{"word":"flavor","ipa":"/ˈfleɪvər/","pos":"n.","def":"味道，风味；特点，特色；  v.给……调味","sen":"The yoghurt has a strawberry flavor.","trans":"这个酸奶是草莓味的。","mne":""},{"word":"flavour","ipa":"/ˈfleɪvər/","pos":"n.","def":"味道（=flavor）；特色；  v.给…调味，给…增添风趣","sen":"There are various flavours of ice cream.","trans":"这里有各种口味的冰淇淋。","mne":""},{"word":"flaw","ipa":"/flɔː/","pos":"n.","def":"瑕疵；缺点；错误","sen":"There is a small flaw in the blue and white porcelain vase.","trans":"这个青花瓷瓶上有个不起眼的瑕疵。","mne":""},{"word":"flexible","ipa":"/ˈfleksəbəl/","pos":"adj.","def":"易弯曲的，柔软的","sen":"The pencil is flexible enough to be knotted.","trans":"这支铅笔非常柔软，甚至可以打成结。","mne":"flex弯曲 + ible能……的 → 易曲的"},{"word":"flight","ipa":"/flaɪt/","pos":"n.","def":"航班；空中航行；楼梯的一段","sen":"The flight information is shown on the big screen.","trans":"航班信息显示在大屏幕上。","mne":""},{"word":"float","ipa":"/floʊt/","pos":"v.","def":"浮动，漂流，漂浮","sen":"The swans are floating on the water.","trans":"天鹅在水面漂浮。","mne":""},{"word":"flood","ipa":"/flʌd/","pos":"n.","def":"洪水；  v.淹没","sen":"The flood submerged the village and the farm.","trans":"这场洪水淹没了村庄和农场。","mne":""},{"word":"floor","ipa":"/flɔːr/","pos":"n.","def":"地板，地面；楼层","sen":"The room had no carpet so we could see the bare floor.","trans":"这间房子没有地毯所以我们能看见光秃秃的地板。","mne":""},{"word":"flour","ipa":"/ˈflaʊər/","pos":"n.","def":"面粉","sen":"There is a bag of flour.","trans":"这里有一包面粉。","mne":""},{"word":"flourish","ipa":"/ˈflɜːrɪʃ/","pos":"v.","def":"茂盛；繁荣，兴旺","sen":"Plants flourish with enough sunlight. ","trans":"植物有充足的阳光就会茂盛。","mne":"flour花 + ish使成为，表动词 → 开花 →flourish繁荣，兴旺"},{"word":"flow","ipa":"/floʊ/","pos":"v.","def":"流动；  n.流动","sen":"The river is flowing through the rocks.","trans":"河水在岩石间流动。","mne":""},{"word":"flower","ipa":"/ˈflaʊər/","pos":"n.","def":"花，花卉","sen":"There are colorful flowers in that place.","trans":"那里有五颜六色的花。","mne":""},{"word":"fluent","ipa":"/ˈfluːənt/","pos":"adj.","def":"（语言）讲得流利的；（文字）流畅熟练的","sen":"The rapper used his fluent English to complete the freestyle.","trans":"这个说唱歌手用他流利的英文完成了这段即兴说唱。","mne":"flu流动 + ent…的 → 流动的 → fluent流利的，流畅的"},{"word":"fluently","ipa":"/ˈfluːəntli/","pos":"adv.","def":"流利地；流畅地","sen":"The girl has a good memory and can recite the ancient poem fluently.","trans":"女孩的记忆力很好，能流利地背诵这首古诗。","mne":""},{"word":"fluid","ipa":"/ˈfluːɪd/","pos":"n.","def":"流体，液体；  adj.流动的","sen":"Water, milk, and oil are all fluids.","trans":"水、牛奶和油都是液体。","mne":"flu流动 ＋ id形容词后缀 → fluid流体，液体；流动的"},{"word":"fly","ipa":"/flaɪ/","pos":"v.","def":"飞，飞行，飞翔；  n.蝇，苍蝇","sen":"I'd like to fly up towards the sun, like an eagle.","trans":"我想像老鹰一样高高飞向太阳。","mne":""},{"word":"focus","ipa":"/ˈfoʊkəs/","pos":"v.","def":"集中；  n.焦点","sen":"He is trying to focus on the target.","trans":"他正在试着集中在目标上。","mne":""},{"word":"fog","ipa":"/fɔːɡ/","pos":"n.","def":"雾，烟雾，尘雾","sen":"The heavy fog covers the whole city.","trans":"大雾弥漫了整座城市。","mne":""},{"word":"foggy","ipa":"/ˈfɔːɡi/","pos":"adj.","def":"有雾的；模糊的","sen":"We got lost in the foggy weather.","trans":"我们在大雾天气里迷路了。","mne":""},{"word":"fold","ipa":"/foʊld/","pos":"v.","def":"折叠，对折；彻底失败；  n.褶皱","sen":"I fold the pink paper to make a paper heart.","trans":"我将这张粉色的纸折叠成一颗纸心。","mne":""},{"word":"folk","ipa":"/foʊk/","pos":"n.","def":"人们；民众；  adj.普通百姓的；民间的","sen":"The young folks are wearing traditional clothes.","trans":"年轻人们穿着传统服装。","mne":""},{"word":"follow","ipa":"/ˈfɑːloʊ/","pos":"v.","def":"遵循；追随","sen":"He followed the doctor's advice about when to take the medicine.","trans":"他听从了医生关于何时服药的建议。","mne":""},{"word":"following","ipa":"/ˈfɑːloʊɪŋ/","pos":"prep.","def":"随后，在……以后；  adj.接着的；下列的，下述的；  n.一批追随者","sen":"Following the beach volleyball, there will be a party.","trans":"沙滩排球之后将会有一场派对。","mne":"follow跟随 + ing表示行为、状态、情况及其他 → following接着的；下列的"},{"word":"fond","ipa":"/fɑːnd/","pos":"adj.","def":"喜欢的，喜爱的","sen":"He was fond of his girlfriend, always smiling at the sight of her.","trans":"他很喜欢自己的女朋友，一看见她就笑。","mne":""},{"word":"food","ipa":"/fuːd/","pos":"n.","def":"食物","sen":"When filming a food vlog, make sure the lighting highlights the colors of the dishes.","trans":"拍摄美食 vlog 时，确保灯光能突出菜肴的色彩。","mne":""},{"word":"fool","ipa":"/fuːl/","pos":"n.","def":"笨蛋，傻瓜；  v.玩弄","sen":"He is such a fool that he can't answer this question.","trans":"他连这个问题都答不出，真是个傻瓜。","mne":""},{"word":"foolish","ipa":"/ˈfuːlɪʃ/","pos":"adj.","def":"愚蠢的；傻乎乎的","sen":"It was foolish of the little dog to challenge the strong wolf.","trans":"小狗去挑战这只强壮的狼是很愚蠢的。","mne":"fool笨蛋 + ish像…一样 → foolish愚蠢的"},{"word":"foot","ipa":"/fʊt/","pos":"n.","def":"脚；(pl. feet)英尺","sen":"She is lying in the sun with bare feet.","trans":"她光着脚躺在阳光下。","mne":""},{"word":"football","ipa":"/ˈfʊtbɔːl/","pos":"n.","def":"足球运动；<美>橄榄球","sen":"Football is a popular sport around the world.","trans":"足球运动是一项在全球广受欢迎的体育项目。","mne":"foot脚 + ball球 → football足球比赛；足球"},{"word":"footprint","ipa":"/ˈfʊtprɪnt/","pos":"n.","def":"脚印，足迹","sen":"Footprints on the sand can help in tracing the location of the enemy.","trans":"沙滩上的脚印可以帮助追踪敌人的位置。","mne":""},{"word":"for","ipa":"/fɔːr/","pos":"prep.","def":"为了；  conj.因为","sen":"I make a card for my mom.","trans":"我给妈妈做一张卡片。","mne":""},{"word":"forbid","ipa":"/fərˈbɪd/","pos":"v.","def":"禁止；妨碍","sen":"We forbid smoking in the restaurant.","trans":"餐厅内禁止吸烟。","mne":"for反对；相反 + bid要求 → forbid禁止"},{"word":"force","ipa":"/fɔrs/","pos":"v.","def":"强迫；推动；促使，迫使；  n.力量；武力；势力","sen":"The child is being forced to have breakfast.","trans":"这个孩子正被迫吃早饭。","mne":""},{"word":"forceful","ipa":"/ˈfɔːrsfl/","pos":"adj.","def":"有说服力的；强烈的，有效的","sen":"She elaborated on several forceful proposals at the meeting.","trans":"她在会议上阐释了一些具有说服力的方案。","mne":""},{"word":"forecast","ipa":"/ˈfɔːrkæst/","pos":"n.","def":"预报；预言；  v.预报","sen":"The weather forecast says the weather next week will be terrible.","trans":"天气预报说下周的天气会很糟糕。","mne":"fore前面，预先 + cast投射 → 预先投射 → forecast预料，预测"},{"word":"forehead","ipa":"/ˈfɔːrhed/ /ˈfɔːrəd/","pos":"n.","def":"前额，前部","sen":"The boy smiled and pointed to his forehead.","trans":"男孩笑着指了指自己的前额。","mne":"fore前面，预先 + head头 → forehead前额"},{"word":"foreign","ipa":"/ˈfɔːrən/","pos":"adj.","def":"外国的，外来的","sen":"She has many foreign friends.","trans":"她有许多外国朋友。","mne":""},{"word":"foreigner","ipa":"/ˈfɔːrənər/","pos":"n.","def":"外国人","sen":"We have two new classmates, and they are foreigners!","trans":"我们班来了两个新同学，他们是外国人！","mne":"foreign外国的 + er名词后缀，人 → 外国人"},{"word":"foresee","ipa":"/fɔːrˈsiː/","pos":"v.","def":"预测，预料","sen":"He foresaw that his journey would be delayed by bad weather.","trans":"他预料到自己的旅程会被恶劣天气耽搁。","mne":"fore前面，预先 + see看见 → foresee预见，先见"},{"word":"forest","ipa":"/ˈfɔːrɪst/","pos":"n.","def":"森林，林区","sen":"The forest looks beautiful when the sun shines through the trees.","trans":"当阳光穿过树木时，整个森林看起来美极了。","mne":""},{"word":"forever","ipa":"/fərˈevər/","pos":"adv.","def":"永远","sen":"They turned into butterflies and stayed together forever.","trans":"他们变成了蝴蝶，会永远在一起。","mne":"for适合于 + ever永远 → forever永远，总是，老是"},{"word":"forget","ipa":"/fərˈɡet/","pos":"v.","def":"忘记，遗忘","sen":"He forgot to remove his key from the lock when he left his apartment.","trans":"他离开公寓时忘了把钥匙从门锁上拔下来。","mne":"for否定，相反 + get得到，想起 → 想不起来的 → forget忘记"},{"word":"forgettable","ipa":"/fərˈɡetəbl/","pos":"adj.","def":"容易被忘的；可忘记的","sen":"Don’t make forgettable mistakes with your password.","trans":"不要在密码上犯容易被遗忘的错误。","mne":""},{"word":"forgive","ipa":"/fərˈɡɪv/","pos":"v.","def":"原谅；宽恕","sen":"The kitty has forgiven its master for hugging other cats.","trans":"小猫原谅主人抱了别的猫。","mne":"for完全地 + give给予 → forgive饶恕"},{"word":"fork","ipa":"/fɔːrk/","pos":"n.","def":"叉，餐叉；分叉，分岔处，岔路；  v.叉起，耙成叉状；道路分叉","sen":"The fork is usually placed on the left side of the plate.","trans":"餐叉通常被放在餐盘的左侧。","mne":""},{"word":"form","ipa":"/fɔːrm/","pos":"n.","def":"形状；【计】表单，表格；  v.组织，建立","sen":"These pieces can make many different forms.","trans":"这些七巧板可以组成许多不同的形状。","mne":""},{"word":"formal","ipa":"/ˈfɔːrml/","pos":"adj.","def":"正式的；正规的，规范的","sen":"His job requires formal dress, such as smart shoes, a shirt and a tie.","trans":"他的工作需要正式的着装，比如讲究的鞋子、衬衫和领带。","mne":"form形式 + al…的 → formal正式的，正规的"},{"word":"format","ipa":"/ˈfɔːrmæt/","pos":"n.","def":"版式；格式；总体安排；  v.使格式化","sen":"The format of the newspaper is well arranged.","trans":"这份报纸排版十分整齐。","mne":"form形式 + at=ate表动词 → format使格式化"},{"word":"formation","ipa":"/fɔːrˈmeɪʃn/","pos":"n.","def":"队形；形成；组成","sen":"There are many different formations that soccer teams can play.","trans":"足球队可以采取很多不同的队形来比赛。","mne":"form形状 + ation表名词 → formation形成；形式"},{"word":"former","ipa":"/ˈfɔːrmər/","pos":"adj.","def":"以前的；前者的","sen":"The first photograph is our former headmaster.","trans":"第一张照片是我们的从前的校长。","mne":"form=fore先前 + er表人/物 → former前者"},{"word":"formula","ipa":"/ˈfɔːrmjələ/","pos":"n.","def":"【数】公式；配方；准则，方案","sen":"The formula for calculating the area of a rectangle is length times width.","trans":"计算矩形面积的公式是长度乘以宽度。","mne":"form形式 + ula表名词 → 形成模式的 → formula公式"},{"word":"forth","ipa":"/fɔːrθ/","pos":"adv.","def":"向前；离去","sen":"The turtle moved forth slowly.","trans":"海龟慢慢地向前移动。","mne":""},{"word":"fortunate","ipa":"/ˈfɔːrtʃənət/","pos":"adj.","def":"幸运的，吉利的","sen":"People believe that four-leaf clover is a fortunate symbol.","trans":"人们认为四叶草是幸运的象征。","mne":"fortun=fort运气 + ate…的 → fortunate幸运的"},{"word":"fortunately","ipa":"/ˈfɔːrtʃənətli/","pos":"adv.","def":"幸运地，幸亏","sen":"Fortunately, he actually won the lottery! One million dollars!","trans":"太幸运了，他中了彩票，那可是100万啊！","mne":"fortun=fortune力量，运气一个 + ate表示有……性质的 + ly表示如……的、有……特征的 → fortunately幸运地，幸亏"},{"word":"fortune","ipa":"/ˈfɔːrtʃən/","pos":"n.","def":"运气；命运，时运；财产","sen":"What a good fortune! I won the first prize.","trans":"运气真好！我中了一等奖。","mne":""},{"word":"forty","ipa":"/ˈfɔːrti/","pos":"num.","def":"四十","sen":"Congratulations on turning forty years old!","trans":"祝贺你满四十岁！","mne":"for=four四 + ty十数 → forty四十"},{"word":"forward","ipa":"/ˈfɔːrwərd/","pos":"adv.","def":"【数】向前，前向；向前，向将来；前进；向前地；  v.发送，寄；促进","sen":"This is the sign of forward and backward.","trans":"这是向前和向后的标志。","mne":"for前 ＋ ward向…... → forward向前；今后"},{"word":"fossil","ipa":"/ˈfɑːsl/","pos":"n.","def":"化石","sen":"There is a fossil of an ancient fish in the ground.","trans":"地里有一块古代鱼类的化石。","mne":""},{"word":"foster","ipa":"/ˈfɑːstər/","pos":"v.","def":"培养","sen":"Her parents play songs to foster her interest in music.","trans":"父母给她播放音乐，以培养她对音乐的兴趣。","mne":""},{"word":"found","ipa":"/faʊnd/","pos":"v.","def":"成立，建立，创办；发现，感到（find的过去式）","sen":"These two businessmen founded a new company together.","trans":"这两个商人一起创办了一家新公司。","mne":""},{"word":"foundation","ipa":"/faʊnˈdeɪʃn/","pos":"n.","def":"地基；基金会","sen":"A strong building needs a solid foundation.","trans":"一座坚固的建筑需要有稳固的地基。","mne":"found基础 + ation表名词 → foundation基础，地基"},{"word":"fountain","ipa":"/ˈfaʊntn/","pos":"n.","def":"泉水，喷泉","sen":"The fountain becomes so colorful at night.","trans":"在晚上，喷泉变得五彩缤纷。","mne":""},{"word":"four","ipa":"/fɔːr/","pos":"num.","def":"四","sen":"Even a child knows the number four. Do you?","trans":"连小孩子都知道数字四的意思。你知道吗？","mne":""},{"word":"fourteen","ipa":"/ˌfɔːrˈtiːn/","pos":"num.","def":"十四","sen":"February fourteen is Valentine's Day.","trans":"2月14日是情人节。","mne":"four四 + teen十几 → fourteen十四"},{"word":"fox","ipa":"/fɑːks/","pos":"n.","def":"狐狸；狡猾的人","sen":"The fox gave the boy flowers and sat beside him.","trans":"狐狸给了男孩花，并坐在他身边。","mne":""},{"word":"fraction","ipa":"/ˈfrækʃn/","pos":"n.","def":"部分，片段","sen":"The fraction in the chart is shown in red.","trans":"图表中那部分是用红色表示。","mne":"fract打碎 + ion名词后缀 → fraction部分；小片"},{"word":"frame","ipa":"/freɪm/","pos":"n.","def":"画框；构架；  v.构想出","sen":"The picture looks nice in this wooden frame.","trans":"这幅画在这个木质的画框里看起来很漂亮。","mne":""},{"word":"framework","ipa":"/ˈfreɪmwɝːk/","pos":"n.","def":"框架，结构","sen":"You can see the framework of the building so well at the moment.","trans":"你现在可以清楚地看见房子的框架。","mne":"frame框架 + work物 → framework框架"},{"word":"frank","ipa":"/fræŋk/","pos":"adj.","def":"坦白的，直率的","sen":"She was frank about the food in my teeth.","trans":"她很直率地告诉我我牙上有东西。","mne":""},{"word":"free","ipa":"/friː/","pos":"adj.","def":"自由的；免费的；  adv.自由地；免费地","sen":"After quitting my job, I feel free as a bird escaping its cage.","trans":"辞职以后，我感觉自己像一只逃出鸟笼的鸟。","mne":""},{"word":"freedom","ipa":"/ˈfriːdəm/","pos":"n.","def":"自由","sen":"The birds finally get their freedom. They are flying out of the cage.","trans":"鸟儿们终于自由了。它们正从笼子里飞出来。","mne":"free自由的 + dom状态或领域 → freedom自由"},{"word":"freeze","ipa":"/friːz/","pos":"v.","def":"冰冻，冻结；（使）冻住；  n.严寒，冻结","sen":"Water freezes at 0°C.","trans":"水在零摄氏度时会结冰。","mne":""},{"word":"frequency","ipa":"/ˈfriːkwənsi/","pos":"n.","def":"（声波或电磁波振动的）频率；频繁","sen":"The sounds had a high frequency.","trans":"声音的频率很高。","mne":""},{"word":"frequent","ipa":"/ˈfrikwənt/, /friˈkwɛnt/","pos":"adj.","def":"时常的，频繁的（读作/ˈfrikwənt/）","sen":"My daddy bothers me on a frequent basis.","trans":"我父亲经常来打扰我。","mne":"frequ挤在一起 + ent形容词后缀 -> frequent时常的，频繁的"},{"word":"frequently","ipa":"/ˈfriːkwəntli/","pos":"adv.","def":"频繁地","sen":"He went to the bathroom frequently after drinking too much water.","trans":"喝了太多水后，他频繁地去上厕所。","mne":"frequent经常的 ＋ ly...地 → frequently经常地，频繁地"},{"word":"fresh","ipa":"/freʃ/","pos":"adj.","def":"新鲜的；没经验的；  adv.刚刚，才","sen":"Eating fresh fruit is great for your health.","trans":"吃新鲜的水果对你的健康有益。","mne":""},{"word":"freshman","ipa":"/ˈfreʃmən/","pos":"n.","def":"大学一年级学生","sen":"Freshmen always have lots of things to do in their first few days at college.","trans":"在入学的头几天，新生们通常有很多事要做。","mne":"fresh新鲜 + man人 → freshman新手，生手"},{"word":"friday","ipa":"/ˈfraɪdeɪ/","pos":"n.","def":"星期五","sen":"It's finally Friday!","trans":"终于到星期五了！","mne":""},{"word":"friend","ipa":"/frend/","pos":"n.","def":"朋友","sen":"Gina is my best friend.","trans":"吉娜是我最好的朋友。","mne":""},{"word":"friendly","ipa":"/ˈfrendli/","pos":"adj.","def":"友好的，友爱的","sen":"Tom and his buddy are very friendly with each other.","trans":"汤姆和他的伙计互相很友好。","mne":"friend朋友+ly...的→友好的"},{"word":"friendship","ipa":"/ˈfrendʃɪp/","pos":"n.","def":"友谊；友情","sen":"I hope my college friendships will survive my college years.","trans":"我希望大学时代的友谊能够超越大学生活，延续下去。","mne":"friend朋友 ＋ ship名词后缀 → friendship友谊"},{"word":"frighten","ipa":"/ˈfraɪtn/","pos":"v.","def":"使惊恐，使害怕","sen":"My brother jumped out of the closet and frightened me.","trans":"我的弟弟从衣柜里跳出来，吓到我了。","mne":"fright惊恐 + en使… → frighten使惊恐"},{"word":"frightened","ipa":"/ˈfraɪtnd/","pos":"adj.","def":"受惊的，受恐吓的；害怕的","sen":"The boy was frightened by the sudden noise outside the window.","trans":"男孩被窗外的突然声响吓到了。","mne":"fright惊恐 + en表动词 + ed…的 → frightened受惊的，受恐吓的"},{"word":"frightening","ipa":"/ˈfraɪtnɪŋ/","pos":"adj.","def":"骇人的","sen":"OMG! Look at the frightening look of that wolf!","trans":"我的天！快看那狼多骇人！","mne":"fright惊恐+en表动词 + ing...的→frightening令人恐惧的"},{"word":"frog","ipa":"/frɑːɡ/","pos":"n.","def":"青蛙","sen":"The frog is jumping out of the water.","trans":"这只青蛙正跳出水面。","mne":""},{"word":"from","ipa":"/frəm/","pos":"prep.","def":"从…来，来自","sen":"The black pepper came from the Western Regions.","trans":"这些黑胡椒来自西域。","mne":""},{"word":"front","ipa":"/frʌnt/","pos":"n.","def":"前面，正面；  adj.前面的，正面的","sen":"I like to sit in the front so no one can block my view.","trans":"我喜欢坐在前排，这样一来就没有人能够挡住我的视线。","mne":""},{"word":"frost","ipa":"/frɔːst/","pos":"n.","def":"霜冻，严寒；  v.结霜","sen":"The leaves were covered with frost.","trans":"树叶覆盖上一层薄霜。","mne":""},{"word":"fruit","ipa":"/fruːt/","pos":"n.","def":"水果；成果，产物；  v.结果实","sen":"A basket of fruits is on the wooden table.","trans":"木桌上放了一篮水果。","mne":""},{"word":"frustrate","ipa":"/ˈfrʌstreɪt/","pos":"v.","def":"挫败；使沮丧","sen":"The five of them are frustrated by the loss of the game.","trans":"他们五个人因输掉比赛而感到挫败。","mne":"frustr犯错误 + ate做，造成 → frustrate挫败"},{"word":"fry","ipa":"/fraɪ/","pos":"v.","def":"油煎；油炸","sen":"It's easy to fry eggs; I can make two for you.","trans":"煎鸡蛋很容易，我可以给你做两个。","mne":""},{"word":"fuel","ipa":"/ˈfjuːəl/","pos":"n.","def":"燃料；  v.给……加燃料","sen":"I need to add fuel to my car.","trans":"我需要给我的车加燃料。","mne":""},{"word":"fulfil","ipa":"/fʊlˈfɪl/","pos":"v.","def":"实现，履行，实践（=fulfill）；满足…的要求","sen":"He has fulfilled his childhood dream of becoming an astronaut.","trans":"他实现了成为一名宇航员的童年梦想。","mne":""},{"word":"fulfill","ipa":"/fʊl'fɪl/","pos":"v.","def":"履行，实现，完成；满足，实现","sen":"She fulfilled her goals on the list.","trans":"她完成了清单上的目标。","mne":"ful完全，完整 + fill填满 → 完全填满 → fulfill实现，完成"},{"word":"fulfillment","ipa":"/fʊl'fɪlmənt/","pos":"n.","def":"成就，满足","sen":"The joy of victory is the ultimate fulfillment in life.","trans":"胜利的喜悦是生命的终极目标。","mne":"ful 完全的 + fill 装满，使充满 + ment 表示行为、行为的过程或结果 → fulfillment履行；实行"},{"word":"fulfilment","ipa":"/fʊlˈfɪlmənt/","pos":"n.","def":"成就感，满足感；实现","sen":"She got a sense of fulfilment from the good comments of her work.","trans":"她从对她工作的好评中获得了一种满足感。","mne":""},{"word":"full","ipa":"/fʊl/","pos":"adj.","def":"满的，充满的；  n.完全，全部；  adv.完全地，充分地，到最大程度","sen":"The cup on the left is full of water.","trans":"左侧的杯子中装满了水。","mne":""},{"word":"fun","ipa":"/fʌn/","pos":"n.","def":"娱乐，乐趣，快乐","sen":"They're all having fun at the party.","trans":"他们在派对上玩得很开心。","mne":""},{"word":"function","ipa":"/ˈfʌŋkʃən/","pos":"n.","def":"功能，作用，用途，机能；  v.工作，运转","sen":"This kind of bottle with holes has many useful functions.","trans":"这种带孔的瓶子有许多实用的功能。","mne":"funct活动 + ion表名词 → function功能"},{"word":"fund","ipa":"/fʌnd/","pos":"n.","def":"资金，基金；  v.拨款，提供资金","sen":"The fund was established to protect our environment.","trans":"这笔基金是为保护环境而设立的。","mne":"fund基础，创办事业的基础 → 底子，本钱 → fund基金"},{"word":"fundamental","ipa":"/ˌfʌndəˈmentl/","pos":"adj.","def":"基本的；至关重要的；基础的；  n.基本原理；基本规律","sen":"Among Maslow's needs, physiologic needs are people's most fundamental needs.","trans":"在马斯洛的需求中，生理需求是人最基本的需求。","mne":"fundament基础 + al形容词后缀 → fundamental基础的，基本的"},{"word":"funeral","ipa":"/ˈfjuːnərəl/","pos":"n.","def":"丧葬，葬礼","sen":"They are attending the funeral of the glacier.","trans":"他们正在参加冰川的葬礼。","mne":"funer葬礼 + al表名词 → funeral葬礼"},{"word":"funny","ipa":"/ˈfʌni/","pos":"adj.","def":"有趣的，好玩的；好笑的，滑稽的","sen":"It was so funny that he cried with laughter.","trans":"这太好笑了，他都笑出眼泪了。","mne":"fu趣味 + (n)y形容词后缀 → funny有趣的，好玩的"},{"word":"fur","ipa":"/fɜːr/","pos":"n.","def":"毛皮","sen":"A fur coat is very warm, but very expensive!","trans":"毛皮外套很温暖，但也很昂贵！","mne":""},{"word":"furnish","ipa":"/ˈfɜːrnɪʃ/","pos":"v.","def":"（用家具等）布置（房间、公寓等）；供应，提供","sen":"We furnished our room with very expensive furniture.","trans":"我们用非常昂贵的家具来装饰我们的房间。","mne":""},{"word":"furniture","ipa":"/ˈfɜːrnɪtʃər/","pos":"n.","def":"家具","sen":"All of his furniture came as a set.","trans":"他的所有家具都是成套的。","mne":"furni安置 + ture表名词 → furniture家具"},{"word":"further","ipa":"/ˈfɜːrðər/","pos":"adv.","def":"更远地；进一步；  adj.更多的，附加的；  v.促进，推动","sen":"Combined with advanced robotic technology, I can see further.","trans":"与先进的机器人技术结合，我能看得更远。","mne":"furth=forth向前，向前方 + er比较级 → 更前面的 → further更远的"},{"word":"furthermore","ipa":"/ˌfɜːrðərˈmɔːr/","pos":"adv.","def":"此外，而且","sen":"He broke his leg in the forest, furthermore, some strange creatures were watching him.","trans":"他在森林中摔断了腿，此外，一些奇怪的生物正盯着他。","mne":"further更远的 + more更多的 → furthermore此外，而且"},{"word":"future","ipa":"/ˈfjuːtʃər/","pos":"n.","def":"未来，将来；前途；  adj.将来的，未来的","sen":"I can see your future from this ball!","trans":"我能从这个球里看见你的未来！","mne":""},{"word":"gain","ipa":"/ɡeɪn/","pos":"v.","def":"获得；  n.增加","sen":"We can gain valuable knowledge by reading books.","trans":"我们能通过阅读获得宝贵的知识。","mne":""},{"word":"gallery","ipa":"/ˈɡæləri/","pos":"n.","def":"美术馆，画廊","sen":"Many people come to this gallery to see the famous pieces of art.","trans":"很多人来到美术馆欣赏这些著名的艺术作品。","mne":""},{"word":"game","ipa":"/ɡeɪm/","pos":"n.","def":"游戏；比赛","sen":"We had a good time playing the board game together.","trans":"我们一起玩桌游玩得很开心。","mne":""},{"word":"gap","ipa":"/ɡæp/","pos":"n.","def":"间隙，间隔；差距，差别","sen":"Please mind the gap between the train and the platform!","trans":"请当心列车与站台之间的间隙！","mne":""},{"word":"garage","ipa":"/ɡəˈrɑːdʒ/","pos":"n.","def":"车库；修车厂","sen":"There is a car parked in the garage.","trans":"有一辆车停在车库里。","mne":"gar掩盖，保护 + age名词后缀 → 遮挡和维修的地方 → garage车库，维修厂"},{"word":"garbage","ipa":"/ˈɡɑːrbɪdʒ/","pos":"n.","def":"垃圾；废物","sen":"A few bags of garbage are left on the street.","trans":"好几袋垃圾被丢在街上。","mne":""},{"word":"garden","ipa":"/ˈɡɑːrdn/","pos":"n.","def":"花园，菜园；  v.从事园艺","sen":"There are many flowers in the garden.","trans":"花园里有许多花。","mne":""},{"word":"gas","ipa":"/ɡæs/","pos":"n.","def":"气体；煤气；天然气","sen":"A cloud of gas is coming out from the chimney.","trans":"一团气体正从烟囱里冒出来。","mne":""},{"word":"gasoline","ipa":"/ˈɡæsəliːn/","pos":"n.","def":"<美>汽油","sen":"She is filling up her car with gasoline.","trans":"她正在给自己的车加油。","mne":"gasol液化气 + ine名词后缀 → gasoline(美)汽油"},{"word":"gate","ipa":"/ɡeɪt/","pos":"n.","def":"大门","sen":"The gate was closed, so we couldn't go in.","trans":"大门关上了，所以我们进不去。","mne":""},{"word":"gather","ipa":"/ˈɡæðər/","pos":"v.","def":"集合；聚集，召集","sen":"People gather around to listen to the girl's beautiful singing.","trans":"人们聚在一块，听女孩美妙的演唱。","mne":""},{"word":"gay","ipa":"/ɡeɪ/","pos":"adj.","def":"同性恋的；  n.同性恋者","sen":"This gay-themed movie tells the story of the emotional relationship between two men.","trans":"这部电影以同性恋为主题，讲述了两个男人之间的情感关系。","mne":""},{"word":"gene","ipa":"/dʒiːn/","pos":"n.","def":"基因","sen":"DNA consists of a large number of genes.","trans":"DNA包含大量的基因。","mne":""},{"word":"general","ipa":"/ˈdʒenrəl/","pos":"adj.","def":"普遍的，总的；大体的，大致的，笼统的；首席的，总管的；  n.将军","sen":"In general, trees are tall, green, and have brown bark.","trans":"一般来说，树木是又高又绿的，而且还有棕色的树皮。","mne":""},{"word":"generally","ipa":"/ˈdʒenərəli/","pos":"adv.","def":"一般地，通常；笼统地，概括地","sen":"The weather this week will be generally rainy.","trans":"这个星期的天气普遍有雨。","mne":"gener出生 + ally……地 → 出生具有普遍性 → 通常地；通常强调普遍性"},{"word":"generate","ipa":"/ˈdʒenəreɪt/","pos":"v.","def":"产生（热、电等能量）","sen":"A man is riding the bicycle to generate electricity.","trans":"一个男人骑着自行车来发电。","mne":"gener出生，产生 + ate做，造成 → generate发生，引起"},{"word":"generation","ipa":"/ˌdʒenəˈreɪʃn/ ","pos":"n.","def":"一代；一代人；产生，生成","sen":"My family includes three generations of people.","trans":"我们家三代同堂。","mne":"generate 产生，发生 + ion表名词 → 产生出的一代人 → generation一代；一代人"},{"word":"generous","ipa":"/ˈdʒenərəs/","pos":"adj.","def":"慷慨大方的；充裕的，宽厚的","sen":"The generous guy just gave the poor man some money. ","trans":"这个慷慨大方的人刚给了这个穷人一些钱。","mne":"gener出生，产生 + ous形容词后缀 → [不断]产生 → generous丰富的，慷慨的"},{"word":"genetic","ipa":"/dʒəˈnetɪk/","pos":"adj.","def":"遗传的；基因的","sen":"Once I saw her mother, I realized that her blonde hair must be genetic.","trans":"一看到她母亲，我就明白了她的金发是遗传的。","mne":"gen出生，产生 + etic与……相关的 → 与出生相关的 → genetic基因的，遗传学的"},{"word":"genius","ipa":"/ˈdʒiːniəs/","pos":"n.","def":"天才；天资，天赋","sen":"The musical genius was a composer even in childhood.","trans":"这位音乐天才小时候就是作曲家了。","mne":"gen=gene出生 + ius  → 出生就有  → genius天才"},{"word":"gentle","ipa":"/ˈdʒentl/","pos":"adj.","def":"温柔的，文雅的","sen":"He was very gentle and gave me his coat.","trans":"他很绅士，把他的外套给我了。","mne":""},{"word":"gentleman","ipa":"/ˈdʒentlmən/","pos":"n.","def":"绅士；有教养的人","sen":"\"Thank you. You are really a gentleman.\"","trans":"“谢谢。您真是一位绅士。”","mne":"gentle温和的 + man人 → gentleman绅士；有教养的人"},{"word":"gently","ipa":"/ˈdʒentli/","pos":"adv.","def":"温柔地，温和地","sen":"Children treat their toys gently.","trans":"孩子们对他们的玩具很温柔。","mne":"gent温和的 + ly...地 → gently轻轻地；温柔地，温和地"},{"word":"genuine","ipa":"/ˈdʒenjuɪn/","pos":"adj.","def":"真的；真正的；真诚的","sen":"Which one is the genuine painting of the famous artist?","trans":"哪一幅才是这位著名画家的真迹？","mne":"genu导致，产生 + ine形容词后缀 → 确实产生出的东西 → genuine真的，真正的"},{"word":"genuinely","ipa":"/ˈdʒenjuɪnli/","pos":"adv.","def":"由衷地；真正地","sen":"She was genuinely happy to see her old friend after so many years.","trans":"见到多年未见的老朋友，她由衷地感到高兴。","mne":""},{"word":"geography","ipa":"/dʒiˈɑːɡrəfi/","pos":"n.","def":"地理（学）；地貌，地势","sen":"Geography can help us know the world better.","trans":"学习地理可以让我们更好地了解世界。","mne":"geo地球 + graphy写，图 → geography地理，地理学"},{"word":"geometry","ipa":"/dʒiˈɑːmətri/","pos":"n.","def":"几何学","sen":"The little boy is so good at solving the mathematical problems of geometry.","trans":"这个小男孩很擅长解决几何类的数学问题。","mne":"geo地 + metry计量，测量 → 测量地面 → geometry几何学"},{"word":"gesture","ipa":"/ˈdʒestʃər/","pos":"n.","def":"手势，姿势；姿态","sen":"This gesture means they think you are very good.","trans":"这种手势表示他们认为你很棒。","mne":"gest带来，产生 + ure名词后缀 → 带来信息的动作 → gesture手势"},{"word":"get","ipa":"/ɡet/","pos":"v.","def":"得到，获得，赢得；收到，接到","sen":"They all get what they want.","trans":"他们都得到了他们想要的。","mne":""},{"word":"ghost","ipa":"/ɡoʊst/","pos":"n.","def":"鬼，鬼魂，幽灵","sen":"There are ghosts in movies and stories, but I don't think they are real.","trans":"电影和故事里有鬼魂，但我认为它们（在现实生活中）不是真的。","mne":""},{"word":"giant","ipa":"/ˈdʒaɪənt/","pos":"adj.","def":"巨大的，特大的；  n.伟人","sen":"The giant rock is naturally balanced.","trans":"这块巨大的石头保持着天然的平衡。","mne":""},{"word":"gift","ipa":"/ɡɪft/","pos":"n.","def":"天赋；礼物，赠品","sen":"She has a gift for math.","trans":"她有数学天赋。","mne":""},{"word":"girl","ipa":"/ɡɜːrl/","pos":"n.","def":"女孩","sen":"The girl with brown hair is so cute.","trans":"这个棕色头发的女孩太可爱了。","mne":""},{"word":"give","ipa":"/ɡɪv/","pos":"v.","def":"给","sen":"The child is giving the old man a piece of bread.","trans":"小孩给了那个老人一块面包。","mne":""},{"word":"given","ipa":"/ˈɡɪvn/","pos":"prep.","def":"考虑到；  adj.指定的，特定的；  v.给，给予（give的过去分词）","sen":"Given that she is only three years old, she can draw very well.","trans":"考虑到她只有三岁，她已经画得很好了。","mne":""},{"word":"glad","ipa":"/ɡlæd/","pos":"adj.","def":"高兴的，愉快的","sen":"I am glad to be sharing my speech with you today.","trans":"很高兴今天能给大家做演讲。","mne":""},{"word":"glance","ipa":"/ɡlæns/","pos":"v.","def":"看一下；  n.一瞥，扫视","sen":"I glanced at her, but she didn't notice.","trans":"我瞥了她一眼，但是她没有注意到。","mne":"glanc冰，光滑 + ance表名词，性质，状况 → 像冰上划过的光线 → glance一瞥，扫视"},{"word":"glass","ipa":"/ɡlæs/","pos":"n.","def":"玻璃杯；玻璃","sen":"She is drinking water from the glass.","trans":"她在喝玻璃杯中的水。","mne":""},{"word":"glimpse","ipa":"/ɡlɪmps/","pos":"n.","def":"一瞥；  v.一瞥，瞥见","sen":"Alice caught a quick glimpse of Wonderland through the tiny door.","trans":"爱丽丝透过小小的门匆匆瞥见了仙境。","mne":""},{"word":"global","ipa":"/ˈɡloʊbəl/","pos":"adj.","def":"全球的，全世界的","sen":"With the Internet, we can have a global network of friends.","trans":"有了互联网，我们可以和全世界的朋友联系。","mne":"glob地球 + al……的 → global全球的"},{"word":"globe","ipa":"/ɡloʊb/","pos":"n.","def":"地球，世界；球体，地球仪","sen":"Airplanes fly all over the globe, even over the poles.","trans":"飞机在全世界飞行，甚至会飞过两极上空。","mne":""},{"word":"glorious","ipa":"/ˈɡlɔːriəs/","pos":"adj.","def":"辉煌的，壮丽的；光荣的，荣耀的","sen":"The sunrise in the countryside is quite glorious.","trans":"乡间的日出非常壮丽。","mne":"glori=glory光荣 + ous形容词后缀 → glorious光荣的"},{"word":"glory","ipa":"/ˈɡlɔːri/","pos":"n.","def":"光荣，荣誉","sen":"The pupil is completely immersed in the glory of receiving a red scarf.","trans":"这个小学生完完全全沉浸在佩戴上红领巾的光荣感中。","mne":""},{"word":"glove","ipa":"/ɡlʌv/","pos":"n.","def":"手套","sen":"Gloves keep my fingers warm in winter.","trans":"手套使我的手指在冬天很暖和。","mne":""},{"word":"glow","ipa":"/ɡləʊ/","pos":"n.","def":"微弱稳定的光；喜悦，满足的心情；  v.发光，发出微光","sen":"The orange glow of the sunset is so beautiful!","trans":"夕阳的橘色光芒太美了！","mne":""},{"word":"go","ipa":"/ɡoʊ/","pos":"v.","def":"走；去","sen":"Don't go without me.","trans":"别丢下我走。","mne":""},{"word":"goal","ipa":"/ɡoʊl/","pos":"n.","def":"目标；（进球）得分","sen":"The boy's goal is to become as strong as the man in the poster.","trans":"男孩的目标是变得像海报里的男人一样强壮。","mne":""},{"word":"goat","ipa":"/ɡoʊt/","pos":"n.","def":"山羊","sen":"I love my pet goat even though it eats everything.","trans":"我爱我的宠物山羊，尽管它什么都吃。","mne":""},{"word":"god","ipa":"/ɡɑːd/","pos":"n.","def":"神","sen":"Poseidon was the God of the sea in ancient Greek myths.","trans":"波塞冬是古希腊神话中的海神。","mne":""},{"word":"gold","ipa":"/ɡoʊld/","pos":"n.","def":"黄金，金币；  adj.金色的","sen":"The boy made a lot of gold with his magic powers.","trans":"爱德华用炼金术做出了许多金子。","mne":""},{"word":"golden","ipa":"/ˈɡoʊldən/","pos":"adj.","def":"金黄色的；金色的；特别的，美好的","sen":"This is a golden egg.","trans":"这是一枚金蛋。","mne":"gold金子 + en由…制成的 → golden金色的"},{"word":"good","ipa":"/ɡʊd/","pos":"adj.","def":"好的，优秀的","sen":"She has figured out a good idea.","trans":"她想到了一个好主意。","mne":""},{"word":"goodbye","ipa":"/ˌɡʊdˈbaɪ/","pos":"int.","def":"再见（也作good bye）；  n.再见","sen":"Goodbye, see you tomorrow. ","trans":"拜拜，明天见。","mne":""},{"word":"goodness","ipa":"/ˈɡʊdnəs/","pos":"n.","def":"善良，美德；精髓；  int.天哪，哎呀","sen":"Taking care of the injured kittens shows her goodness.","trans":"照顾受伤的小猫展现了她善良的一面。","mne":"good好的 + ness表名词 → goodness善行，优良"},{"word":"goods","ipa":"/ɡʊdz/","pos":"n.","def":"货物，商品","sen":"The goods are sent to us every day.","trans":"每天，这些货物都会被寄送给我们。","mne":""},{"word":"goose","ipa":"/ɡuːs/","pos":"n.","def":"鹅；雌鹅；鹅肉","sen":"We can tell from the shape of its head that this is a goose.","trans":"我们可以根据它头部的形状断定这是一只鹅。","mne":""},{"word":"govern","ipa":"/ˈɡʌvərn/","pos":"v.","def":"统治，管理","sen":"The king governs his kingdom.","trans":"国王统治他的王国。","mne":""},{"word":"government","ipa":"/ˈɡʌvərnmənt/ ","pos":"n.","def":"政府；治理；政治","sen":"The offices of the local government are in this building.","trans":"当地政府的办公室就在这栋楼里。","mne":"govern统治 + ment表名词 → 政府"},{"word":"governor","ipa":"/ˈɡʌvərnər/","pos":"n.","def":"州长；总督","sen":"The governor is giving a speech.","trans":"这位州长正在发表演讲。","mne":"govern管理 + or名词后缀：人 → governor总督"},{"word":"grab","ipa":"/ɡræb/","pos":"v.","def":"抓住，抓取；  v.抓住；攫取","sen":"Babies love to grab your fingers.","trans":"婴儿喜欢抓住你的手指。","mne":""},{"word":"grace","ipa":"/ɡreɪs/","pos":"n.","def":"优美；优雅，高雅","sen":"She moves with the natural grace of a ballerina.","trans":"她的动作具有芭蕾舞演员的自然优雅。","mne":""},{"word":"graceful","ipa":"/ˈɡreɪsfl/","pos":"adj.","def":"优雅的，优美的，得体的","sen":"She is such a graceful and beautiful actress!","trans":"她是一个如此优雅美丽的演员！","mne":"grace优雅 + ful形容词后缀：…的 → graceful优雅的"},{"word":"grade","ipa":"/ɡreɪd/","pos":"n.","def":"年级；  v.给……分等级；给（试卷或作业）评分","sen":"I am in Class one, Grade three.","trans":"我在三年级一班。","mne":""},{"word":"gradual","ipa":"/ˈɡrædʒuəl/","pos":"adj.","def":"逐渐的；逐步的","sen":"The graph shows a gradual increase.","trans":"图表显示出了逐步的增长。","mne":"grad(e)等级 + ual形容词后缀 → gradual逐步的"},{"word":"gradually","ipa":"/ˈɡrædʒuəli/","pos":"adv.","def":"逐渐地，逐步地","sen":"Gradually, he becomes stronger and stronger.","trans":"渐渐地，他变得越来越强壮。","mne":"gradual逐步的 + ly…...地 → gradually逐步地"},{"word":"graduate","ipa":"/ˈgrædʒuˌeɪt/, /ˈgrædʒuət/","pos":"v.","def":"毕业；  n.毕业生","sen":"She graduated from university after four years' unforgettable life.","trans":"经过四年难忘的大学生活，她毕业了。","mne":"grad步 + uate使 → 完成所有步骤 → graduate毕业"},{"word":"graduation","ipa":"/ˌɡrædʒuˈeɪʃn/","pos":"n.","def":"毕业典礼","sen":"Graduation day is finally here! It’s time to celebrate our achievements.","trans":"毕业典礼终于到了！是时候庆祝我们的成就了。","mne":"grad步，级 + uat=ate做… + ion名词后缀 → 使升级并走出 → graduation毕业"},{"word":"grain","ipa":"/ɡreɪn/","pos":"n.","def":"谷物，谷粒；颗粒","sen":"There is a bag of grains on the table.","trans":"桌子上有一袋谷物。","mne":""},{"word":"grammar","ipa":"/ˈɡræmər/","pos":"n.","def":"语法，语法书","sen":"The English teacher is teaching grammar now.","trans":"英语老师现在正在教语法。","mne":"gramm=gram写，图 + ar表物 → 写的(规则） → grammar语法"},{"word":"grand","ipa":"/ɡrænd/","pos":"adj.","def":"壮丽的，宏伟的，宏大的；  n.一千美元；大钢琴","sen":"The hotel lobby was very impressive and grand.","trans":"这家酒店大堂气势宏伟，令人印象深刻。","mne":""},{"word":"grandfather","ipa":"/ˈɡrænfɑːðər/","pos":"n.","def":"爷爷，祖父；外公，外祖父","sen":"\"Grandfather is the father of your parent,\" the boy said.","trans":"“祖父就是你爸爸或你妈妈的父亲。”男孩说道。","mne":"grand宏伟的 + father父亲 → grandfather祖父，外祖父"},{"word":"grandmother","ipa":"/ˈɡrænmʌðər/","pos":"n.","def":"奶奶，祖母；外婆；外祖母（=grandma）","sen":"My grandmother gave me a candy cane.","trans":"我祖母给了我一个拐杖糖。","mne":"grand显赫的，最高的 + mother母亲 → grandmother祖母，外祖母"},{"word":"grant","ipa":"/ɡrænt/","pos":"v.","def":"允许，同意，准允；  n.拨款；补助金","sen":"The Subway Committee grants the blind permission to bring guide dogs on board.","trans":"地铁委员会允许盲人携带导盲犬上地铁。","mne":""},{"word":"graph","ipa":"/ɡræf/","pos":"n.","def":"（曲线）图，图表","sen":"He is sitting in front of a computer and reading a lot of graphs.","trans":"他正坐在电脑前看各种图表。","mne":""},{"word":"grasp","ipa":"/ɡræsp/","pos":"v.","def":"抓住，抓紧；领会，理解；  n.紧握","sen":"The baby grasped his mother's finger.","trans":"婴儿抓住了母亲的手指。","mne":""},{"word":"grass","ipa":"/ɡræs/  ","pos":"n.","def":"草，牧草；<俚>大麻；告密的人；  v.喂草，以牧草喂养；放牧；告发","sen":"It feels great to lie down on the grass.","trans":"躺在草地上感觉真好。","mne":""},{"word":"grateful","ipa":"/ˈɡreɪtfl/","pos":"adj.","def":"感激的；感谢的","sen":"Everyone was so grateful to the medical team that they lined the road, waving goodbye thankfully.","trans":"每个人都非常感谢医疗队。他们站在路边，满怀感激地挥手告别。","mne":"grate感激，高兴 + ful多…...的 → grateful感谢的；愉快的"},{"word":"gratitude","ipa":"/ˈɡrætɪtuːd/","pos":"n.","def":"感激，感谢","sen":"In the speech, she expressed great gratitude to her mother. ","trans":"她在演讲中表达了对母亲的无限感激。","mne":"grat(e)感谢 + itude名词后缀 → gratitude感激，感恩"},{"word":"grave","ipa":"/greɪv/, /ɡrɑːv/","pos":"n.","def":"墓；  adj.严肃的，庄重的；严重的","sen":"He went down on his knee in front of the two graves.","trans":"夏尔跪在爱德华兄弟的墓碑前。","mne":"grav重 + e → grave严重的；庄重的"},{"word":"gravity","ipa":"/ˈɡrævəti/","pos":"n.","def":"重力，引力；严重性","sen":"Things fall down because of gravity.","trans":"物体会因为重力坠落。","mne":"grav重 + ity名词后缀 → gravity庄重；地心吸力"},{"word":"gray","ipa":"/ɡreɪ/","pos":"adj.","def":"灰色的；暗淡的；  n.灰色，暗淡","sen":"My grandmother has a full head of gray hair.","trans":"我奶奶满头银发。","mne":""},{"word":"great","ipa":"/ɡreɪt/","pos":"adj.","def":"伟大的；极好的，极棒的；非常好的；  adv.（口语）好极了，很好地","sen":"Vincent van Gogh is one of the greatest painters in the history of Western art.","trans":"梵高是西方艺术史上最伟大的画家之一。","mne":""},{"word":"greedy","ipa":"/ˈɡriːdi/","pos":"adj.","def":"贪婪的，贪心的，贪吃的","sen":"The greedy dog also wants the bone in the water.","trans":"这只贪婪的狗狗还想要水里的骨头。","mne":"greed贪婪 + y…的 → greedy贪吃的，贪婪的，贪心的"},{"word":"green","ipa":"/ɡriːn/","pos":"adj.","def":"绿色的，青的，草绿色的；缺乏经验的；生的，未熟的；  n.绿色","sen":"The plant is green.","trans":"这个植物是绿色的。","mne":""},{"word":"greenhouse","ipa":"/ˈɡriːnhaʊs/","pos":"n.","def":"温室；暖房","sen":"Greenhouses are the best place to grow plants quickly.","trans":"温室是快速栽种植物的最好地方。","mne":"green绿色 + house屋子 → 温室，暖房"},{"word":"greet","ipa":"/ɡriːt/","pos":"v.","def":"问候，招呼；迎接","sen":"This gentleman takes his hat off to greet people.","trans":"这位绅士摘下他的帽子，向人们问好。","mne":""},{"word":"greeting","ipa":"/ˈɡriːtɪŋ/","pos":"n.","def":"问候，致敬；招呼","sen":"He exchanged greetings with his neighbor.","trans":"他和邻居互相问候。","mne":"greet问候 + ing名词后缀 → greeting问候，招呼，致敬"},{"word":"grey","ipa":"/ɡreɪ/","pos":"adj.","def":"灰色的（=gray）；  n.灰色","sen":"The grey T-shirt is more popular than the white one.","trans":"灰色的衬衫比白色的更受欢迎。","mne":""},{"word":"grip","ipa":"/ɡrɪp/","pos":"n.","def":"紧握，握力；握力；  v.握紧，抓牢","sen":"You'd better not lose your grip on the rock for your safety.","trans":"安全起见，你最好紧紧抓住那块石头。","mne":""},{"word":"grocer","ipa":"/ˈɡroʊsər/","pos":"n.","def":"食品杂货商","sen":"This grocer is very nice, he always gives me a discount.","trans":"这个食品杂货商超好，他总是给我打折。","mne":""},{"word":"grocery","ipa":"/ˈɡroʊsəri/","pos":"n.","def":"食品杂货店","sen":"The man works happily in this grocery store.","trans":"这个男人在这家杂货店工作得很开心。","mne":""},{"word":"gross","ipa":"/ɡroʊs/","pos":"adj.","def":"总的，毛重的；令人恶心的","sen":"The gross cost for all these things is very high.","trans":"这些东西的总成本很高。","mne":"gross=great大 → gross总共的"},{"word":"ground","ipa":"/ɡraʊnd/","pos":"n.","def":"地，地面；场地；理由，根据","sen":"The man is lying on the ground.","trans":"这个男人正躺在地上。","mne":""},{"word":"group","ipa":"/ɡruːp/","pos":"n.","def":"群，组","sen":"A group of people are sitting over here.","trans":"一群人在这儿坐着。","mne":""},{"word":"grow","ipa":"/ɡroʊ/   ","pos":"v.","def":"生长，成长；种植","sen":"If you wait, you can watch a plant grow.","trans":"你如果等待，你能看到一颗植物的成长。","mne":""},{"word":"growth","ipa":"/ɡroʊθ/","pos":"n.","def":"生长，成长，增长；增长","sen":"Plants need sunlight for growth.","trans":"植物需要阳光才能生长。","mne":"grow成长 + th名词后缀 → growth生长，增长"},{"word":"guarantee","ipa":"/ˌɡærənˈtiː/","pos":"v.","def":"【法】保证；  n.保证","sen":"To secure the loan John needs to find a third party who will guarantee his repayment.","trans":"为了获得贷款，约翰需要找到一个第三方来担保。","mne":""},{"word":"guard","ipa":"/ɡɑːrd/","pos":"n.","def":"警戒，保卫；  v.警惕；  v.保卫，守护","sen":"Guard is necessary if we want to catch the criminal.","trans":"如果我们想抓罪犯，保持警戒很有必要。","mne":""},{"word":"guess","ipa":"/ɡes/","pos":"v.","def":"猜测，估计；  n.猜测，猜想","sen":"The daughter wants her mother to guess the fruit by smell.","trans":"女儿想让她妈妈凭气味猜水果。","mne":""},{"word":"guest","ipa":"/ɡest/","pos":"n.","def":"客人，宾客；  v.做特邀嘉宾","sen":"We are waiting at the door for the arrival of our guests.","trans":"我们在门口等待客人的到来。","mne":""},{"word":"guidance","ipa":"/ˈɡaɪdns/","pos":"n.","def":"指导，引导","sen":"The coach is giving the players some guidance.","trans":"教练正在给球员们提供指导。","mne":"guid(e)指南 + ance名词后缀 → guidance指导"},{"word":"guide","ipa":"/ɡaɪd/","pos":"v.","def":"引导，指导；  n.指南，手册；向导；导游","sen":"The woman is guided by a guide dog.","trans":"这个女人正被导盲犬带着走。","mne":""},{"word":"guilt","ipa":"/ɡɪlt/","pos":"n.","def":"内疚；罪行","sen":"The boy is filled with guilt because he has broken the glass.","trans":"那个小男孩很内疚，因为他打碎了玻璃杯。","mne":""},{"word":"guilty","ipa":"/ˈɡɪlti/","pos":"adj.","def":"内疚的；负罪的","sen":"The dog felt very guilty for destroying the living room.","trans":"这只狗因为破坏了客厅而感到很内疚。","mne":"guilt内疚 + y...的 → guilty内疚的；有罪的"},{"word":"gum","ipa":"/ɡʌm/","pos":"n.","def":"口香糖；  v.在……涂树胶","sen":"My breath smells terrible. I need some gum.","trans":"我口气很难闻，我需要嚼点口香糖。","mne":""},{"word":"gun","ipa":"/ɡʌn/","pos":"n.","def":"枪，炮","sen":"The man looks cool with a gun in his hand.","trans":"这个拿枪的男人看起来太酷了。","mne":""},{"word":"gym","ipa":"/dʒɪm/","pos":"n.","def":"体育馆，健身房；体育，体操","sen":"There are many people exercising in the gym.","trans":"有很多人正在体育馆里运动。","mne":""},{"word":"gymnasium","ipa":"/dʒɪmˈneɪziəm/","pos":"n.","def":"体育馆，健身房","sen":"The most popular facility in that gymnasium is the treadmill.","trans":"跑步机是那家健身房里最受欢迎的器材。","mne":"gymn裸体的 + asium脱衣服锻炼的地方 → gymnasium体育馆"},{"word":"habit","ipa":"/ˈhæbɪt/","pos":"n.","def":"习惯","sen":"Make a habit of washing your hands after using the bathroom!","trans":"要养成上完厕所就洗手的习惯。","mne":""},{"word":"habitual","ipa":"/həˈbɪtʃuəl/","pos":"adj.","def":"习惯的","sen":"He is a habitual early riser who always gets up at 6 o'clock.","trans":"他习惯在清晨六点早起。","mne":"habit习惯 + ual形容词后缀 → habitual习惯的，惯常的"},{"word":"hair","ipa":"/her/","pos":"n.","def":"头发，毛发；毛","sen":"How did you get your hair so straight?","trans":"你是如何让你的头发这么直的？","mne":""},{"word":"half","ipa":"/hæf/","pos":"n.","def":"一半；  adj.一半的","sen":"I drank half of the orange juice.","trans":"我喝了一半橙汁。","mne":""},{"word":"halfway","ipa":"/ˌhæfˈweɪ/","pos":"adv.","def":"到一半，在中途","sen":"He is halfway up the stairs.","trans":"他上楼梯上到一半。","mne":""},{"word":"hall","ipa":"/hɔːl/","pos":"n.","def":"会堂，礼堂；大厅","sen":"The conference hall with red chairs is empty.","trans":"这个配有红色椅子的会堂空空荡荡的。","mne":""},{"word":"halt","ipa":"/hɔːlt/","pos":"v.","def":"暂停","sen":"The teacher halted the discussion to address a student's question.","trans":"老师暂停讨论来回答一个学生的问题。","mne":""},{"word":"hammer","ipa":"/ˈhæmər/","pos":"n.","def":"锤子；  v.锤击","sen":"I used a big hammer to push in the nail.","trans":"我用锤子来把钉子敲进去。","mne":""},{"word":"hand","ipa":"/hænd/","pos":"v.","def":"递，交；  n.手","sen":"She handed the gift to her friend.","trans":"她把礼物交给了她的朋友。","mne":""},{"word":"handicap","ipa":"/ˈhændikæp/","pos":"n.","def":"残疾，生理缺陷；障碍，阻碍；  v.使不利，妨碍","sen":"The soldier who has a handicap proudly stands with the others.","trans":"这位残疾士兵骄傲地和其他士兵站在一起。","mne":""},{"word":"handkerchief","ipa":"/ˈhæŋkərtʃɪf/","pos":"n.","def":"手帕；方巾","sen":"These handkerchiefs have flowers on them.","trans":"这些手帕上有绣花。","mne":""},{"word":"handle","ipa":"/ˈhændl/","pos":"n.","def":"柄，把手；  v.处理，解决","sen":"Turn the handle and the door will open.","trans":"转动把手，门就会开。","mne":"hand手 + le表示做某种动作时所使用的东西 → handle柄，把手"},{"word":"handsome","ipa":"/ˈhænsəm/","pos":"adj.","def":"英俊的，帅气的；（金额）相当大的，可观的，优厚的","sen":"The handsome man posed for pictures.","trans":"这位英俊的男子摆好姿势准备照相。","mne":"hand操作 + some一些 → 易于操作的，可用的 → handsome合适的，外形好的"},{"word":"handwriting","ipa":"/ˈhændraɪtɪŋ/","pos":"n.","def":"笔迹；书写，手写","sen":"His beautiful handwriting is easy to read.","trans":"他漂亮的笔迹清晰易读。","mne":"hand手 + writing写 → handwriting笔迹，书法"},{"word":"handy","ipa":"/ˈhændi/","pos":"adj.","def":"方便的","sen":"My daddy has many handy tools.","trans":"我爸爸有很多简便的工具。","mne":"hand手 + y形容词后缀 → handy手巧的，伸手可及的"},{"word":"hang","ipa":"/hæŋ/","pos":"v.","def":"悬挂，吊起；  n.悬挂；绞刑","sen":"A luxurious drop lamp is hanging on the ceiling.","trans":"一盏奢华的吊灯挂在天花板上。","mne":""},{"word":"happen","ipa":"/ˈhæpən/","pos":"v.","def":"发生","sen":"How did this horrible accident happen?","trans":"这次可怕的事故是如何发生的？","mne":"happ出现，是这种情况 + en动词后缀 → happen发生"},{"word":"happening","ipa":"/ˈhæpənɪŋ/","pos":"n.","def":"意外事件；偶然发生的事；  v.动词happen的现在分词形式","sen":"The police are asking her about the happening.","trans":"警察们正在向她询问事件。","mne":""},{"word":"happy","ipa":"/ˈhæpi/","pos":"adj.","def":"快乐的，高兴的","sen":"Look at her big smile! She is so happy.","trans":"快看她那大大的笑容，她真的很快乐。","mne":"happ机会，运气 + y...的 → 有运气的 → happy幸福的"},{"word":"harbor","ipa":"/'hɑːbə/","pos":"n.","def":"海港；  v.庇护","sen":"There are many boats in the harbor.","trans":"这个海港停靠着许多船只。","mne":"har军队，队伍 + bor保护，庇护所 → 保护地 → harbor避风港，海港"},{"word":"harbour","ipa":"/ˈhɑːrbər/","pos":"n.","def":"海港；  v.包庇，庇护；窝藏","sen":"The ships dock at the harbour.","trans":"这些船都停靠在港口。","mne":""},{"word":"hard","ipa":"/hɑːrd/","pos":"adj.","def":"坚硬的；困难的；  adv.努力地，艰难地，费力地","sen":"This climb's pretty hard—I hope I don't fall off.","trans":"攀岩好难，希望我别掉下去。","mne":""},{"word":"hardly","ipa":"/ˈhɑːrdli/","pos":"adv.","def":"几乎不，几乎没有","sen":"The man always stays at home and hardly goes out.","trans":"这个男人整天待在家，几乎不出门。","mne":"hard艰难 + ly...地 → ad.几乎不，简直不"},{"word":"hardship","ipa":"/ˈhɑːrdʃɪp/","pos":"n.","def":"困苦，苦难","sen":"An orphan faces a life of great hardship.","trans":"孤儿总要面对一个艰难的人生。","mne":"hard艰难的 + ship表情况 → 苦难"},{"word":"hardware","ipa":"/ˈhɑrdwer/","pos":"n.","def":"五金器具；（计算机）硬件","sen":"He bought a lot of hardware from that store.","trans":"他从那家店买了很多五金器具。","mne":"hard硬 + ware物件 → hardware五金器具"},{"word":"harm","ipa":"/hɑːrm/","pos":"v.","def":"伤害；  n.伤害，损害","sen":"Spending too much time on his smartphone may harm his eyes.","trans":"过度使用手机会伤害他的眼睛。","mne":""},{"word":"harmful","ipa":"/ˈhɑːrmfl/","pos":"adj.","def":"有害的","sen":"Poor posture can be very harmful to one's back.","trans":"错误的坐姿对人的背部非常有害。","mne":"harm伤害 + ful形容词后缀 → harmful有害的"},{"word":"harmonious","ipa":"/hɑːrˈmoʊniəs/","pos":"adj.","def":"和谐的；和睦的","sen":"A harmonious color palette can elevate your entire outfit effortlessly.","trans":"和谐的色彩搭配可以毫不费力地提升你的整体穿搭。","mne":"harmon(y)和谐 + ious形容词后缀 → harmonious和谐的"},{"word":"harmony","ipa":"/ˈhɑːrməni/","pos":"n.","def":"和谐；协调","sen":"The Yin-Yang is a symbol of harmony.","trans":"阴阳是和谐的一种象征。","mne":"harm=ar适合 + ony表名词 → 适合的心态 → harmony和谐"},{"word":"harness","ipa":"/hɑːrnɪs/ ","pos":"n.","def":"挽具，马具；  v.利用；治理（河流等）","sen":"The construction worker is wearing a safety harness around his body.","trans":"这名建筑工人身上拴着安全带。","mne":"har军队 + ness供给，供应 → harness提供给士兵的 → harness保护带；挽具"},{"word":"harsh","ipa":"/hɑːrʃ/","pos":"adj.","def":"刺耳的；严厉的；粗糙的；严酷的","sen":"The harsh noise woke me up.","trans":"刺耳的噪音把我吵醒了。","mne":""},{"word":"harvest","ipa":"/ˈhɑːrvɪst/ ","pos":"n.","def":"收成；  v.收割；获得；采集","sen":"The wheat harvest is very good this year.","trans":"今年小麦的收成很好。","mne":""},{"word":"haste","ipa":"/heɪst/","pos":"n.","def":"匆忙；仓促","sen":"They have to make haste to catch the flight.","trans":"他们必须赶快才能坐上飞机。","mne":""},{"word":"hat","ipa":"/hæt/","pos":"n.","def":"帽子（一般指有边的）","sen":"As it was sunny, she wore a hat while walking on the beach.","trans":"因为阳光明媚，她戴着帽子走在沙滩上。","mne":""},{"word":"hate","ipa":"/heɪt/","pos":"v.","def":"恨，憎恨；不喜欢，讨厌；  n.恨，憎恶","sen":"They hate each other.","trans":"他们憎恨彼此。","mne":""},{"word":"hatred","ipa":"/ˈheɪtrɪd/","pos":"n.","def":"憎恨","sen":"He has a lot of hatred for this terrible phone.","trans":"他对这个糟糕的手机有极大的怨恨。","mne":"hatr仇恨 + ed名词后缀 → hatred憎恶，憎恨，仇恨"},{"word":"have","ipa":"/hæv/","pos":"v.","def":"吃，喝","sen":"Let's have dinner together!","trans":"我们一起吃晚饭吧！","mne":""},{"word":"hazard","ipa":"/ˈhæzərd/","pos":"n.","def":"危险；  v.使冒险，冒险做","sen":"In big cities, there are always plenty of road hazards to watch out for.","trans":"在大城市里，我们总是有很多道路危险要注意。","mne":""},{"word":"he","ipa":"/hi/","pos":"pron.","def":"（主格）他","sen":"He is filling in his gender on the form.","trans":"他正在表格上填写他的性别。","mne":""},{"word":"head","ipa":"/hed/","pos":"n.","def":"头；上端；  v.领导; 主管；  adj.领头的","sen":"My head aches—maybe I think too much.","trans":"头好痛，也许是我用脑太多了。","mne":""},{"word":"headache","ipa":"/ˈhedeɪk/","pos":"n.","def":"头痛；令人头痛的事","sen":"The man is suffering from a headache.","trans":"这位男士正在遭受头痛的折磨。","mne":"head头 + ache疼痛 → headache头痛"},{"word":"heading","ipa":"/ˈhedɪŋ/","pos":"n.","def":"标题（用于文章或章节开头）；  v.head的现在分词","sen":"The heading of the newspaper is larger in size.","trans":"报纸的标题的字号大一些。","mne":"head头 + ing表名词 → 文章中在顶头的 → heading标题"},{"word":"headline","ipa":"/ˈhedlaɪn/","pos":"n.","def":"大字标题","sen":"I didn't read the story; I only saw the headline.","trans":"我没读这个故事，我只看了大字标题。","mne":"head头 + line字行 → 头一行字 → headline标题"},{"word":"headmaster","ipa":"/ˌhedˈmæstər/","pos":"n.","def":"校长（尤指私立学校的）","sen":"The headmaster is responsible for the management of this school.","trans":"这位校长负责管理这所学校。","mne":"head头 + master主人 → 学校里最高层的管理者 → headmaster英国中小学校长，男舍监"},{"word":"headquarters","ipa":"/ˈhedkwɔːrtərz/","pos":"n.","def":"总部，总局；司令部，指挥部","sen":"The EU headquarters is located in Brussels.","trans":"欧盟总部在布鲁塞尔。","mne":"head头 + quarter使驻扎 + s表地点 → 头脑聚集的地方 → 司令部；总部"},{"word":"heal","ipa":"/hiːl/","pos":"v.","def":"治愈；恢复，康复","sen":"The doctor's treatment has healed the wounded man.","trans":"医生的治疗已经让那个受伤的男人痊愈了。","mne":""},{"word":"health","ipa":"/helθ/","pos":"n.","def":"健康","sen":"Eating lots of fruits and vegetables is good for your health.","trans":"多吃蔬菜水果对你的健康是有益的。","mne":"heal未受伤的，完好的 + th抽象名词后缀 → health健康"},{"word":"healthy","ipa":"/ˈhelθi/","pos":"adj.","def":"健康的","sen":"These foods are healthy.","trans":"这些食物很健康。","mne":"health健康 + y ...的 → 健康的；有益健康的"},{"word":"heap","ipa":"/hiːp/","pos":"n.","def":"（一）堆；大量；  v.堆；堆积","sen":"Heaps of files are waiting to be classified.","trans":"有一大堆文件等待被归类。","mne":""},{"word":"hear","ipa":"/hɪr/","pos":"v.","def":"听见","sen":"He heard something shocking.","trans":"他听到了一些让人震惊的事情。","mne":""},{"word":"heart","ipa":"/hɑːrt/","pos":"n.","def":"心，心脏；内心","sen":"Kind people have big hearts.","trans":"善良的人们拥有博大的心。","mne":""},{"word":"heat","ipa":"/hiːt/","pos":"n.","def":"热度；【物理学】热；  v.加热，变热","sen":"This summer the heat is unusually high.","trans":"这个夏天热度真的是离奇的高。","mne":""},{"word":"heaven","ipa":"/ˈhevn/","pos":"n.","def":"天堂；天国","sen":"The cat went to heaven after it died.","trans":"这只猫死后去了天堂。","mne":""},{"word":"heavy","ipa":"/ˈhevi/","pos":"adj.","def":"重的；沉重的","sen":"Don't drop those containers-they're heavy!","trans":"当心别让这些集装箱掉下来，它们很重！","mne":""},{"word":"heel","ipa":"/hiːl/","pos":"n.","def":"足跟；脚后跟","sen":"These new shoes are rubbing my heels.","trans":"这些新鞋磨我的脚后跟。","mne":""},{"word":"height","ipa":"/haɪt/","pos":"n.","def":"高，高度","sen":"The woman is measuring her daughter's height.","trans":"这个女人正在给她女儿量身高。","mne":"heigh=high高的 + t(h)名词后缀，宽度或深度等 → height高度"},{"word":"heighten","ipa":"/ˈhaɪtn/","pos":"v.","def":"加强，增加，提高","sen":"The gloomy weather heightened the horrible atmosphere in the graveyard.","trans":"阴沉的天气增强了墓地的恐怖气氛。","mne":"height高度 + en变成 →加高，提高"},{"word":"hello","ipa":"/həˈləʊ/","pos":"int.","def":"喂（打电话时的招呼语）","sen":"Hello. Is that Jo? ","trans":"喂，是乔吗？","mne":""},{"word":"help","ipa":"/help/","pos":"n.","def":"帮助；  v.帮助","sen":"I offered her some help during the mountain climbing.","trans":"爬山的时候，我向她提供了帮助。","mne":""},{"word":"helpful","ipa":"/ˈhelpfl/","pos":"adj.","def":"有益的，有帮助的，有用的","sen":"It is helpful to use a stick to move the rock.","trans":"用棍子移动这块石头是有帮助的。","mne":"help帮助 + ful形容词后缀 → helpful肯帮忙的，给予帮助的"},{"word":"hen","ipa":"/hen/","pos":"n.","def":"母鸡","sen":"I want to keep a hen so I can eat fresh eggs.","trans":"我想养只母鸡，这样就能吃到新鲜的鸡蛋了。","mne":""},{"word":"hence","ipa":"/hens/","pos":"adv.","def":"因此","sen":"There is always someone stealing the corn; hence, a fence has been built.\n","trans":"总是有人偷玉米，因此一个篱笆修了起来。","mne":""},{"word":"her","ipa":"/hər/","pos":"pron.","def":"（宾格）她","sen":"I like her.","trans":"我喜欢她。","mne":""},{"word":"herd","ipa":"/hɜːrd/","pos":"n.","def":"兽群，牧群；  v.放牧，群集","sen":"Look! There is a herd of sheep!","trans":"看！这有一群羊！","mne":""},{"word":"here","ipa":"/hɪr/","pos":"adv.","def":"这里","sen":"We're always here for you.","trans":"我们在这里随时为你服务。","mne":""},{"word":"heritage","ipa":"/ˈherɪtɪdʒ/","pos":"n.","def":"遗产；继承物；传统","sen":"Embroidery is an important part of Chinese cultural heritage whose craft should be retained.","trans":"刺绣是中国文化遗产的重要组成部分，刺绣技艺应该保留下来。","mne":"herit继承 + age场所，物品 → 遗产"},{"word":"hero","ipa":"/ˈhɪroʊ/","pos":"n.","def":"英雄；勇士","sen":"He was praised as a hero for saving the child from the river.","trans":"他从河里救出了孩子，被大家称赞为英雄。","mne":""},{"word":"heroic","ipa":"/həˈrəʊɪk/","pos":"adj.","def":"英勇的；英雄的","sen":"An ordinary man may also make a heroic move.","trans":"一个普通人也能做出英勇的举动。","mne":"hero英雄 + ic形容词后缀 → heroic英雄的"},{"word":"hers","ipa":"/hɜːrz/","pos":"pron.","def":"她的，属于她的","sen":"It's not my homework; it is hers.","trans":"这不是我的作业，是她的。","mne":""},{"word":"herself","ipa":"/hɜːrˈself/","pos":"pron.","def":"她自己","sen":"She can do everything all by herself.","trans":"她能自己搞定所有事情。","mne":"her她 + self自己 → herself她自己"},{"word":"hesitate","ipa":"/ˈhezɪteɪt/ ","pos":"v.","def":"犹豫；踌躇","sen":"She hesitated to take the clothes of her choice.","trans":"她很犹豫要不要买下自己选的衣服。","mne":"hes粘+ itate表动词 → hesitate脚被粘住，犹豫"},{"word":"hey","ipa":"/heɪ/","pos":"int.","def":"嗨","sen":"Hey! How are you?","trans":"嗨！你怎么样？","mne":""},{"word":"hi","ipa":"/haɪ/","pos":"excl.","def":"喂；嗨（表示问候）","sen":"We say \"hi! \" when we meet somebody.","trans":"我们在遇到别人的时候说“嗨！”。","mne":""},{"word":"hide","ipa":"/haɪd/","pos":"v.","def":"隐藏；躲藏；隐瞒；  n.（尤指买卖用的）兽皮","sen":"The boy is hiding inside the big box.","trans":"男孩就藏在这个大箱子里。","mne":""},{"word":"high","ipa":"/haɪ/","pos":"adj.","def":"高的；  adv.高","sen":"This mountain is very high.","trans":"这座山很高。","mne":""},{"word":"highlight","ipa":"/ˈhaɪlaɪt/","pos":"v.","def":"突出，强调，高亮","sen":"You should highlight all the most important parts of the text.","trans":"你应该标记出课文中所有最重要的部分。","mne":"high高 + light亮 → highlight高亮"},{"word":"highly","ipa":"/ˈhaɪli/","pos":"adv.","def":"高度地，非常，赞许地","sen":"I highly recommend you today's special dish.","trans":"我强烈向你们推荐今天的特别菜。","mne":"high高 + ly表副词  → highly高度地，非常"},{"word":"highway","ipa":"/ˈhaɪweɪ/","pos":"n.","def":"公路","sen":"We are enjoying the beautiful scenery as we drive along the highway.","trans":"我们沿着高速公路开车，享受着美丽的风景。","mne":"high[引]主要的 + way路 → highway公路，大路"},{"word":"hill","ipa":"/hɪl/","pos":"n.","def":"小山，山岗","sen":"There is a red house on the top of that green hill.","trans":"在那绿色小山的山顶上有一所红房子。","mne":""},{"word":"him","ipa":"/hɪm/","pos":"pron.","def":"（宾格）他","sen":"The teacher is pointing at him.","trans":"老师正指着他。","mne":""},{"word":"himself","ipa":"/hɪmˈself/","pos":"pron.","def":"他自己","sen":"He can do many things all by himself.","trans":"他能自己搞定所有事情。","mne":"him他 + self自己，反身后缀 → himself他自己"},{"word":"hinder","ipa":"/ˈhɪndər/","pos":"v.","def":"阻碍","sen":"The heavy traffic might hinder our arrival at the meeting on time.","trans":"交通堵塞可能会让我们无法准时到达会议。","mne":""},{"word":"hint","ipa":"/hɪnt/","pos":"n.","def":"暗示，示意；攻略，提示","sen":"She made a gesture to hint that there was no problem.","trans":"她用手势示意一切都没问题。","mne":""},{"word":"hire","ipa":"/ˈhaɪər/","pos":"v.","def":"雇用，聘用；租用","sen":"When will the company decide who to hire?","trans":"公司什么时候决定要雇用谁？","mne":""},{"word":"his","ipa":"/hɪz/","pos":"det.","def":"他的","sen":"He looks really cool next to his sports car.","trans":"他站在自己的跑车旁边，看起来酷毙了！","mne":""},{"word":"historic","ipa":"/hɪˈstɔːrɪk/","pos":"adj.","def":"有历史意义的，历史上著名的","sen":"He is reading this book which recounts the historic victory of his country years ago.","trans":"他正在看的这本书记录了多年前他的国家取得的历史性胜利。","mne":"histor=history历史 + ic形容词，...的 → 有历史意义的"},{"word":"historical","ipa":"/hɪˈstɔːrɪkl/","pos":"adj.","def":"历史的，有关历史的","sen":"This book is all about historical buildings in China.","trans":"这是一本关于中国历史建筑的书。","mne":"histor历史 + ical形容词后缀……的 → historical有关历史的"},{"word":"history","ipa":"/ˈhɪstri/ ","pos":"n.","def":"历史，历史学","sen":"This poster shows the history of different methods of transportation.","trans":"这张海报展示了各种交通方式的发展历史。","mne":"histor过去发生的事 + y表名词 → history历史；个人经历"},{"word":"hit","ipa":"/hɪt/","pos":"v.","def":"打击；碰撞，撞击；袭击；到达（某地）；  n.击打；碰撞","sen":"He hit him in the face.","trans":"他打了他的脸。","mne":""},{"word":"hobby","ipa":"/ˈhɑːbi/ ","pos":"n.","def":"业余爱好","sen":"Fishing is my hobby, so I often go to the lake on weekends.","trans":"我的爱好是钓鱼，所以我周末常去湖边。","mne":""},{"word":"hold","ipa":"/hoʊld/","pos":"v.","def":"举办，举行，召开；持有（观点）；抓住；容纳，包含；  n.控制","sen":"Our school is holding a sports meeting.","trans":"我们学校正在举办运动会。","mne":""},{"word":"hole","ipa":"/hoʊl/","pos":"n.","def":"孔，洞","sen":"A hole in the heart can lead to abnormal blood flow between chambers.","trans":"心脏上的孔可能导致心脏腔室间的血流异常。","mne":""},{"word":"holiday","ipa":"/ˈhɑːlədeɪ/","pos":"n.","def":"节日，假期，休假日；法定假日，公共节日","sen":"People are enjoying their holiday from work.","trans":"人们享受着他们的假日。","mne":"hol神圣 + i + day日子 → holiday节假日"},{"word":"hollow","ipa":" /ˈhɑːloʊ/","pos":"adj.","def":"空洞的；中间空的，空心的；  n.洞；孔","sen":"Overworking makes him feel hollow.","trans":"过度工作让他感到空虚。","mne":"hol=kel掩盖，隐藏，保存 + low → 可隐藏的地方 → hollow空心的，洞"},{"word":"home","ipa":"/hoʊm/","pos":"n.","def":"家，家庭；  adv.在家，到家；  adj.家的；  v.回家","sen":"The family was happy at home.","trans":"这家人待在家里很开心。","mne":""},{"word":"homeland","ipa":"/ˈhoʊmlænd/","pos":"n.","def":"家园，故乡；祖国","sen":"After settling abroad for many years, he missed his homeland terribly.","trans":"在国外定居多年后，他无比思念自己的故乡。","mne":"home家 + land土地 → homeland 祖国"},{"word":"homeless","ipa":"/ˈhoʊmləs/","pos":"adj.","def":"无家可归的","sen":"The homeless dog wishes he had a family.","trans":"这只流浪狗希望有个家。","mne":"home家 ＋ less表形容词，无…的 → homeless无家可归的"},{"word":"homework","ipa":"/ˈhoʊmwɜːrk/","pos":"n.","def":"家庭作业","sen":"The tutor helped the children with their homework.","trans":"这个家教辅导孩子们完成了作业。","mne":"home家庭 + work工作 → homework家庭作业"},{"word":"honest","ipa":"/ˈɑːnɪst/","pos":"adj.","def":"诚实的，正直的；正直的；坦率的","sen":"Before giving testimony, the witness has to pledge herself to being honest.","trans":"作证之前，证人必须发誓所言皆实。","mne":"hon=honor荣誉，尊严 + est → honest诚实的"},{"word":"honey","ipa":"/ˈhʌni/","pos":"n.","def":"蜜，蜂蜜；亲爱的，宝贝（爱称）","sen":"Add more honey if you have a sweet tooth.","trans":"如果你喜欢吃甜的，就多加点蜂蜜。","mne":""},{"word":"honor","ipa":"/'ɑːnər/ ","pos":"n.","def":"荣誉；荣幸；尊敬","sen":"Receiving the gold medal is my honor.","trans":"获得金牌是我的荣幸。","mne":""},{"word":"honorable","ipa":"/ˈɑːnərəbl/","pos":"adj.","def":"荣誉的；可敬的","sen":"At this honorable moment, he got his master's degree.","trans":"在这个荣耀时刻，他获得了他的硕士学位。","mne":"honor荣誉 + able…的 → honorable光荣的，高尚的"},{"word":"honour","ipa":"/ˈɑːnər/","pos":"n.","def":"荣誉；荣幸；尊敬；  v.尊敬","sen":"Holding a post graduate degree is a matter of honour and pride.","trans":"拿到硕士学位是一件光荣并值得自豪的事情。","mne":""},{"word":"honourable","ipa":"/ˈɑːnərəbl/","pos":"adj.","def":"可敬的，值得钦佩的；荣誉的，光荣的","sen":"The guy who rides on the horse is an honourable knight.","trans":"骑马的人是一名值得钦佩的骑士。","mne":"honour光荣 + able...的 → 光荣的，诚实的"},{"word":"hope","ipa":"/hoʊp/","pos":"n.","def":"希望；期望；  v.希望，期望（某事发生）","sen":"My hope is to go to a world-famous university one day.","trans":"我希望有一天能上一所世界著名的大学。","mne":""},{"word":"hopeful","ipa":"/ˈhoʊpfl/","pos":"adj.","def":"有希望的","sen":"It is still hopeful for the man in yellow to win.\n","trans":"穿黄色衣服的人仍然有希望获胜。","mne":"hope希望 + ful形容词后缀 → hopeful有希望的"},{"word":"hopeless","ipa":"/ˈhoʊpləs/","pos":"adj.","def":"绝望的","sen":"I feel hopeless. This job is not easy.","trans":"我绝望了，这个工作真不简单。","mne":"hope希望 + less表形容词，无……的 → hopeless无希望的"},{"word":"horizon","ipa":"/həˈraɪzn/","pos":"n.","def":"地平线；范围；眼界，见识","sen":"The sun is slowly rising from the horizon.","trans":"太阳从地平线上缓缓升起。","mne":""},{"word":"horrible","ipa":"/ˈhɔːrəbl/","pos":"adj.","def":"可怕的","sen":"I did not expect to see such a horrible scene on the phone.","trans":"我没料到会在手机上看到这么恐怖的场景。","mne":"horr发抖，恐惧 + ible......的 → 令人发抖的 → horrible可怕的"},{"word":"horror","ipa":"/ˈhɔːrər/","pos":"n.","def":"恐惧","sen":"He screamed in horror when he saw the monster.","trans":"看到怪物时，他惊恐地尖叫了起来。","mne":"horr（因惊吓或发怒）毛发竖起 + or引申词义厌恶 -> horror惊恐"},{"word":"horse","ipa":"/hɔːrs/","pos":"n.","def":"马","sen":"The black horse is running on the beach.","trans":"这匹黑马正在沙滩上奔跑。","mne":""},{"word":"horsepower","ipa":"/ˈhɔːrspaʊər/","pos":"n.","def":"马力","sen":"The maximum output of this engine is two hundred horsepower.","trans":"这台发动机的最大输出功率是200马力。","mne":""},{"word":"hospitable","ipa":"/ˈhɑːspɪtəbl/","pos":"adj.","def":"好客的","sen":"He was very hospitable to the guests when they came to his house.","trans":"有人来访时，他表现得十分好客。","mne":"hospit客人 ＋ able形容词后缀，…的 → 待客，好客 → hospitable好客的，招待周到的，殷勤的"},{"word":"hospital","ipa":"/ˈhɑspɪtl/","pos":"n.","def":"医院","sen":"The patient was taken to the hospital for treatment.","trans":"病人被带进医院进行治疗。","mne":"hospit客人 + al名词词尾 → 客气对待病人的地方 → hospital医院"},{"word":"host","ipa":"/hoʊst/ ","pos":"n.","def":"宿主，主人；节目主持人；  v.主持，主办","sen":"Viruses need a living host to reproduce and cause infection.","trans":"病毒需要活的宿主来繁殖并引起感染。","mne":""},{"word":"hostile","ipa":"/ˈhɑːstl/","pos":"adj.","def":"怀有敌意的；敌对的，敌方的","sen":"They're hostile towards each other in the fight for MVP.","trans":"流川枫和樱木为了争夺MVP而对彼此充满了敌意。","mne":"host(=hostis)敌人 + ile……的 → 有敌意的 → hostile敌意的"},{"word":"hostility","ipa":"/hɑːˈstɪləti/","pos":"n.","def":"虐待，敌意；敌对","sen":"The dog shows his hostility to strangers.","trans":"狗狗对陌生人满是敌意。","mne":"host敌人 + ility表名词 → hostility敌对"},{"word":"hot","ipa":"/hɑːt/","pos":"adj.","def":"热的，烫的，炎热的","sen":"I enjoy a cup of hot coffee with my breakfast.","trans":"早餐我享用了一杯热咖啡。","mne":""},{"word":"hotel","ipa":"/hoʊˈtel/  ","pos":"n.","def":"酒店，旅馆","sen":"This is a five-star hotel.","trans":"这是一家五星级酒店。","mne":"hot=host客人 ＋ el表名词 → hotel客人住的地方"},{"word":"hour","ipa":"/ˈaʊər/","pos":"n.","def":"小时","sen":"I get a break at one o'clock—only an hour to go!","trans":"一点的时候我可以休息一下，只有一个小时！","mne":""},{"word":"house","ipa":"/haʊs/, /haʊz/","pos":"n.","def":"房屋，住宅","sen":"I have a small house model in the palm of my hand.","trans":"我手上放了一个小的房子模型。","mne":""},{"word":"household","ipa":"/ˈhaʊshoʊld/","pos":"n.","def":"家庭；  adj.家庭的；家喻户晓的","sen":"I grew up in a large household.","trans":"我生长在一个大家庭中。","mne":"house家 + hold持有，拥有 → household家庭"},{"word":"housewife","ipa":"/ˈhaʊswaɪf/","pos":"n.","def":"家庭主妇","sen":"The housewife is ironing the clothes with her child.","trans":"这个家庭主妇正在和她的孩子一起熨衣服。","mne":"house屋子 + wife妻子 → 家庭主妇 → housewife家庭主妇"},{"word":"how","ipa":"/haʊ/","pos":"adv.","def":"如何；怎样；到何种地步；多么","sen":"How do you bake a cake？","trans":"你如何烤蛋糕？","mne":""},{"word":"however","ipa":"/haʊˈevər/","pos":"adv.","def":"然而，不过，但是；无论如何，不管多么","sen":"He got a great test score; however, he's still upset.","trans":"他考了个好成绩，然而他还是不开心。","mne":"how怎样 + ever永远，表强调 → however然而；不管怎样"},{"word":"huge","ipa":"/hju:dʒ/","pos":"adj.","def":"巨大的","sen":"There is a huge yellow duck floating on the lake.","trans":"有一只大黄鸭漂在湖上。","mne":""},{"word":"human","ipa":"/ˈhjuːmən/ ","pos":"adj.","def":"人的，人类的；  n.人","sen":"Water is important for the human body. ","trans":"水对人体很重要。","mne":"hum 土，地 + an名词后缀：属于...的 → 传说人是由土造出的 → human 人类"},{"word":"humanity","ipa":"/hjuːˈmænəti/","pos":"n.","def":"人性；人类；人道，慈爱","sen":"What binds mankind together is our common humanity.","trans":"将人类联系在一起的是我们共同的人性。","mne":"human人类 + ity名词后缀 → humanity人性，人类"},{"word":"humble","ipa":"/ˈhʌmbl/","pos":"adj.","def":"谦逊的；虚心的；卑微的","sen":"She praised him with many compliments, but he was humble and denied them.","trans":"她说了很多恭维话赞扬莱纳德，但莱纳德很谦虚地拒绝了。","mne":"hum土地 + ble形容词后缀 → 接近地面 → humble谦恭的"},{"word":"humor","ipa":"/ˈhjuːmər/","pos":"n.","def":"幽默；幽默，诙谐；  v.迎合，迁就，顺应","sen":"This funny kids' cartoon is full of humor.","trans":"这部有趣的儿童卡通片十分幽默。","mne":""},{"word":"humorous","ipa":"/ˈhjuːmərəs/","pos":"adj.","def":"幽默的，搞笑的","sen":"This guy was so humorous and made everyone laugh.","trans":"这个人很幽默，把大家都逗笑了。","mne":"humor幽默 + ous…...的 → humorous富于幽默的，诙谐的"},{"word":"humour","ipa":"/ˈhjuːmər/","pos":"n.","def":"幽默；诙谐；  v.迁就；迎合","sen":"This funny kids' cartoon is full of humour.","trans":"这部有趣的儿童卡通片十分幽默。","mne":""},{"word":"hundred","ipa":"/ˈhʌndrəd/","pos":"num.","def":"百，百个","sen":"Whose face is on the hundred-dollar bill?","trans":"一百元美钞上是谁的头像？","mne":""},{"word":"hunger","ipa":"/ˈhʌŋɡər/","pos":"n.","def":"饥饿；  v.（使）饥饿；渴望","sen":"He wants a hamburger to satisfy his hunger.","trans":"他想吃个汉堡来缓解饥饿。","mne":""},{"word":"hungry","ipa":"/ˈhʌŋɡri/","pos":"adj.","def":"饥饿的；渴望的","sen":"I'm not really hungry, just a small piece of pizza would be fine for me.","trans":"我不是很饿，给我一小块比萨就好。","mne":"hunger饥饿 + y形容词后缀 → hungry饥饿的"},{"word":"hunt","ipa":"/hʌnt/","pos":"v.","def":"打猎；寻找，搜寻","sen":"The man is hunting a reindeer.","trans":"这名男子正在狩猎驯鹿。","mne":""},{"word":"hunter","ipa":"/ˈhʌntər/","pos":"n.","def":"猎人","sen":"The man with a hound is an experienced hunter.","trans":"这个带着猎犬的男人是个经验丰富的猎人。","mne":"hunt打猎 ＋ er名词后缀 → hunter猎人"},{"word":"hurry","ipa":"/ˈhɜːri/","pos":"n.","def":"匆忙","sen":"It seems that everyone in this city is always in a hurry.","trans":"在这座城市似乎每个人都总是行色匆匆。","mne":""},{"word":"hurt","ipa":"/hɜːrt/","pos":"v.","def":"使受伤；弄伤，弄痛；感到疼痛；  adj.受伤的，受损的","sen":"The girl hurt her leg while running.","trans":"这个女生跑步的时候伤到了腿。","mne":""},{"word":"husband","ipa":"/ˈhʌzbənd/","pos":"n.","def":"丈夫","sen":"Doesn't my husband look great in his new suit?","trans":"我的丈夫穿上了他的新西装，看起来不帅么？","mne":"hus=house房屋 + band居住，住户 → husband丈夫"},{"word":"hydrogen","ipa":"/ˈhaɪdrədʒən/","pos":"n.","def":"氢","sen":"Hydrogen is commonly used as a medical gas in respiratory therapy.","trans":"氢气常被作为医疗气体用于呼吸治疗。","mne":"hydro水 + gen产生 → hydrogen氢"},{"word":"ice","ipa":"/aɪs/","pos":"n.","def":"冰；  v.冰冻，结冰","sen":"She is holding some ice in her hands.","trans":"她手里捧着一些冰。","mne":""},{"word":"ice-cream","ipa":"/'aɪskriːm/","pos":"n.","def":"冰淇淋","sen":"I've ordered two bowls of ice-cream.","trans":"我点了两碗冰淇淋。","mne":""},{"word":"idea","ipa":"/aɪˈdiːə/","pos":"n.","def":"想法，主意；思想，概念","sen":"He came up with a good idea to solve that problem.","trans":"他想到了一个好主意来解决那个问题。","mne":""},{"word":"ideal","ipa":"/aɪˈdiːəl/","pos":"adj.","def":"理想的；完美的；空想的；观念的；  n.理想；典范；目标","sen":"An ideal weekend is to lie on the sofa, watching TV and eating snacks.","trans":"一个理想周末是躺在沙发上看电视、吃零食。","mne":"ide思想，观点 + al名词后缀 → 对未来的想法 → ideal理想的"},{"word":"idealistic","ipa":"/ˌaɪdiəˈlɪstɪk/","pos":"adj.","def":"理想主义的","sen":" She has an idealistic vision of a world where everyone works together in harmony.","trans":"她对一个人人和谐合作的世界抱有理想主义的愿景。","mne":""},{"word":"identical","ipa":"/aɪˈdɛntɪkəl/","pos":"adj.","def":"【化】相同的","sen":"These two chemical reactions generate identical products.","trans":"这两个化学反应生成的产物是相同的。","mne":"ident相同 + ical…的 → identical一样的"},{"word":"identification","ipa":"/aɪˌdentɪfɪˈkeɪʃn/","pos":"n.","def":"识别；鉴定，验明；身份证明","sen":"To unlock this phone, it requires your fingerprint for identification.","trans":"需要识别你的指纹才能打开这个手机。","mne":"identif=identify鉴定 + ication表名词 → identification鉴定"},{"word":"identify","ipa":"/aɪˈdentɪfaɪ/","pos":"v.","def":"识别出；认出；确定，鉴定","sen":"Your fingerprints are so unique that they can help the police identify you.","trans":"你的指纹是独一无二的，所以它们可以帮助警察识别出你的身份。","mne":""},{"word":"identity","ipa":"/aɪˈdentəti/","pos":"n.","def":"身份；特性；一致","sen":"He took out his identity card to show who he was.","trans":"他掏出身份证来表明自己是谁。","mne":"ident相同 + ity表名词 → identity一致；身份"},{"word":"idle","ipa":"/ˈaɪdl/","pos":"v.","def":"无所事事；  adj.懒散的","sen":"I don't want to idle around. I need a case.","trans":"我不想懒懒散散。我需要个案子。","mne":""},{"word":"if","ipa":"/ɪf/","pos":"conj.","def":"如果，倘若；当","sen":"If it is a sunny day, I will go out.If not, I will stay at home.","trans":"如果这是一个晴天，我就出去玩。如果不是，我就呆在家。","mne":""},{"word":"ignorance","ipa":"/ˈɪɡnərəns/","pos":"n.","def":"无知；愚昧","sen":"I am embarrassed by my complete ignorance of history.","trans":"我对历史一无所知，这让我很难堪。","mne":"i不 ＋ gnor知道 ＋ ance名词后缀 → ignorance无知，愚昧"},{"word":"ignorant","ipa":"/ˈɪɡnərənt/","pos":"adj.","def":"无知的，愚昧的","sen":"He remains ignorant of these reports and tables.","trans":"他对这些报表一无所知。","mne":"i不 + gnor知道 + ant形容词后缀 → ignorant无知的"},{"word":"ignore","ipa":"/ɪɡˈnɔːr/","pos":"v.","def":"忽略；不理睬，佯装未见","sen":"The boy's parents ignored him as they were doing their own things.","trans":"男孩的父母忽略了他，只顾着自己的事。","mne":""},{"word":"ill","ipa":"/ɪl/","pos":"adj.","def":"生病的，不适的；坏的，不好的","sen":"The girl is ill; she is resting on the sofa.","trans":"这个女孩生病了，她正在沙发上休息。","mne":""},{"word":"illegal","ipa":"/ɪˈliːɡl/","pos":"adj.","def":"非法的","sen":"Occupying a bus lane is illegal.","trans":"占用公交车道是违法的。","mne":"il不，无 + legal合法的 → illegal非法的"},{"word":"illness","ipa":"/ˈɪlnəs/","pos":"n.","def":"疾病","sen":"He has an illness, but he still has to work.","trans":"他生病了，但仍然要工作。","mne":"ill有病的 + ness名词后缀 → illness疾病"},{"word":"illustrate","ipa":"/ˈɪləstreɪt/","pos":"v.","def":"（用示例、图画等）说明，解释","sen":"Our manager illustrated the sales with colorful charts.","trans":"我们的经理用一些彩色的图表解释了我们的销售量。","mne":"il=in在内，进入 + lustr照亮 + ate表动词  → 照亮内部（大脑） → illustrate举例说明，阐明"},{"word":"illustration","ipa":"/ˌɪləˈstreɪʃn/","pos":"n.","def":"插图","sen":"The book's illustrations of fruits help me to recognize them.","trans":"这本书里的水果插图帮我认出那些水果。","mne":"il 使 + lustr =light光亮 + ation表名词 → 使...光亮 → 说明"},{"word":"image","ipa":"/ˈɪmɪdʒ/","pos":"n.","def":"形象；图像；影像；想象","sen":"He is describing the image of the thief to the police.","trans":"他正在向警方描述小偷的形象。","mne":"imag=imagine想象 ＋ e → 头脑里想象的 → image像；形象"},{"word":"imaginary","ipa":"/ɪˈmædʒɪneri/","pos":"adj.","def":"想象的，虚构的","sen":"In my imaginary world, I am a princess who lives in a big castle.","trans":"在我的幻想世界里，我是一个住在大城堡里的公主。","mne":"imagin想象 + ary形容词后缀 → imaginary想象中的"},{"word":"imagination","ipa":"/ɪˌmædʒɪˈneɪʃn/","pos":"n.","def":"想象力","sen":"Writers need a great imagination to create wonderful stories.","trans":"作家需要很好的想象力才能创造出美妙的故事。","mne":"imagin想象 + ation名词后缀 → imagination想象"},{"word":"imagine","ipa":"/ɪˈmædʒɪn/ ","pos":"v.","def":"想象，幻想；设想，猜想；认为","sen":"The girl imagines a universe in the book.","trans":"小女孩想象书中有宇宙。","mne":"imag=image图像 + ine……的 → 有关图像的 → imagine想象"},{"word":"imaging","ipa":"/ˈɪmɪdʒɪŋ/","pos":"n.","def":"成像","sen":"Imaging technology is vital in modern medical practice.","trans":"成像技术在现代医学实践中非常重要。","mne":""},{"word":"imitate","ipa":"/ˈɪmɪteɪt/","pos":"v.","def":"模仿；  v.仿效","sen":"The boy is imitating the signature move of his favorite character.","trans":"这个男孩在模仿他最喜欢的角色标志动作。","mne":"imit想象，相象 + ate做 → 做得相象 → imitate模仿"},{"word":"imitation","ipa":"/ˌɪmɪˈteɪʃn/","pos":"n.","def":"模仿；仿制品","sen":"The girl applies the lipstick in imitation of her mother.","trans":"这个小女孩模仿她妈妈抹口红。","mne":"imit表示“想象，相像” + ation 名词后缀 → 想象后制造出的 → 仿制品"},{"word":"immediate","ipa":"/ɪˈmiːdiət/","pos":"adj.","def":"立刻的；紧邻的；紧迫的，当下的","sen":"You should take immediate action when facing problems.","trans":"面对问题时，你应该立即采取行动。","mne":"im不 + mediate间接的 → immediate直接的"},{"word":"immediately","ipa":"/ɪˈmiːdiətli/","pos":"adv.","def":"马上，立即；即刻，立即","sen":"\"Yes, sir. I'll be there immediately!\"","trans":"“是，长官。我马上就来！”","mne":"immediate立即的 + ly…地 → immediately立即，马上"},{"word":"immense","ipa":"/ɪˈmens/","pos":"adj.","def":"巨大的，广大的","sen":"Compared with the immense universe, our planet is so small.","trans":"与浩瀚无垠的宇宙相比，我们的星球是如此渺小。","mne":"im不 + mense测量 → 无法测量的 → immense巨大的"},{"word":"immigrant","ipa":"/ˈɪmɪɡrənt/ ","pos":"n.","def":"移民，外侨","sen":"Immigrants bring cultural diversity.","trans":"移民带来了文化多样性。","mne":"im向内，进入 + migr迁移 + ant表示人；形容词 → immigrant外来的移民；移入国内的"},{"word":"immigrate","ipa":"/ˈɪmɪɡreɪt/","pos":"v.","def":"移居入境","sen":"He is filling in the visa application form and plans to immigrate.","trans":"他正在填写签证申请表，准备移民。","mne":"im向内 + migrate移居 → immigrate移居国内"},{"word":"immune","ipa":"/ɪˈmjuːn/","pos":"adj.","def":"免疫的；不受影响的","sen":"People who exercise often are proven to have stronger immune systems.","trans":"经常锻炼的人被证实会有更强的免疫系统。","mne":"im不 + mun服务 + e  → 免除服务  → immune免疫的"},{"word":"impact","ipa":"/ˈɪmpækt/","pos":"n.","def":"影响；冲击力；碰撞，冲击（读作/ˈɪmˌpækt/）；  v.有影响（读作/ɪmˈpækt/）","sen":"The continuous heavy rain had a big impact on transport.","trans":"持续的暴雨对交通造成了严重的影响。","mne":"im进入 + pact紧的 → 紧紧进入人心的力量 → impact影响力"},{"word":"impartial","ipa":"/ɪmˈpɑrʃəl/","pos":"adj.","def":"公平的，不偏不倚的","sen":"A judge should guarantee that the trial is impartial.","trans":"法官应该保证审判是公平的。","mne":"im不，无，非 + partial不公平的 → impartial公平的"},{"word":"impatience","ipa":"/ɪmˈpeɪʃns/","pos":"n.","def":"不耐烦，急躁","sen":"Her impatience is growing as she's already waited for an hour.","trans":"她已经等了一个小时，所以变得越来越不耐烦了。","mne":""},{"word":"impatient","ipa":"/ɪmˈpeɪʃnt/","pos":"adj.","def":"不耐烦的；急躁的","sen":"He had been waiting for twenty minutes and he was getting impatient.","trans":"他已经等了二十分钟，有点不耐烦了。","mne":"im不 + patient有耐心的 → impatient不耐烦的"},{"word":"implement","ipa":"/ˈɪmplɪment/","pos":"v.","def":"实施，执行；  n.工具，器具","sen":"The hospital decided to implement a new infection control protocol.","trans":"医院决定实施一项新的感染控制方案。","mne":"im进 + ple满，填满 + ment指动作本身 → 装入并填满 → implement完成，实施"},{"word":"implication","ipa":"/ˌɪmplɪˈkeɪʃn/","pos":"n.","def":"暗示；含义；牵连，卷入","sen":"She expressed her desire for the cookie by implication.","trans":"她含蓄地表达了想吃饼干的想法。","mne":"im进 + plic重叠，折叠 + ation名词后缀 → [说话]进入重叠 → implication连累；含蓄"},{"word":"implicit","ipa":"/ɪmˈplɪsɪt/","pos":"adj.","def":"隐含的；完全的，绝对的","sen":"These emojis have implicit meanings.","trans":"这些表情符号具有隐含意义。","mne":"im向内，进入 + plicit重叠 → 不直说 → implicit含蓄的，不讲明的"},{"word":"imply","ipa":"/ɪmˈplaɪ/","pos":"v.","def":"暗示；暗指；意味着","sen":"The light implies that there is somebody in the house.","trans":"灯光暗示房子里有人。","mne":"im进入 + ply重叠，折叠 → 重叠表达 → imply 暗示，意味"},{"word":"import","ipa":"/ˈɪmpɔ:rt/, /ɪmˈpɔːrt/","pos":"v.","def":"进口；  n.进口；含义，意义；重要性（读作/ˈɪmˌpɔrt/）","sen":"The goods on this ship were imported from overseas.","trans":"这艘船上的货物是从海外进口的。","mne":"im向内，进入 + port拿，运 → 拿进港口 → import进口"},{"word":"importance","ipa":"/ɪmˈpɔːrtns/","pos":"n.","def":"重要性","sen":"Wi-Fi is of great importance to people as it becomes a basic need.","trans":"Wi-Fi对人们很重要，它已经成了一项基本需求。","mne":"im进 + port拿，运 + ance名词后缀 → 带有意义的状态 → importance重要性"},{"word":"important","ipa":"/ɪmˈpɔːrtnt/","pos":"adj.","def":"重要的，重大的","sen":"You have an important message.","trans":"你有一条重要的消息。","mne":"import重要的 + ant具有…性质的 → important重要的；有势力的"},{"word":"impose","ipa":"/ɪmˈpoʊz/","pos":"v.","def":"把……强加给；强制实行，强迫接受","sen":"The government imposed a ban on single-use plastics to protect the environment.","trans":"政府为保护环境强加了对一次性塑料的禁令。","mne":"im进入 + pose放 → impose强加"},{"word":"impossible","ipa":"/ɪmˈpɑːsəbl/","pos":"adj.","def":"不可能（存在或做到）的","sen":"It's almost impossible for her to push that massive rock.","trans":"她要推动那块巨大的石头几乎不可能。","mne":"im不，无，非 + possible可能的 → impossible不可能的"},{"word":"impress","ipa":"/ɪmˈpres/","pos":"v.","def":"给……留下深刻印象；使牢记，使铭记","sen":"She impressed the foreigners with her costume.","trans":"身着古装的她给外国人留下了深刻印象。","mne":"im入，向内 + press挤压 → 压进去 → 印入头脑 → impress 使有印象，使铭记"},{"word":"impression","ipa":"/ɪmˈpreʃn/","pos":"n.","def":"印象，感觉，感想","sen":"She left a good impression on the interviewer.","trans":"她给这位面试官留下了好印象。","mne":"im在...内 + press压 + ion名词后缀 -> impression印象"},{"word":"impressive","ipa":"/ɪmˈpresɪv/ ","pos":"adj.","def":"给人深刻印象的","sen":"The acrobatic performance left an impressive impact on the audience.","trans":"杂技表演给观众留下了很深刻的印象。","mne":"impress印象 + ive形容词后缀 → 有印象的 → impressive印象深刻的"},{"word":"improve","ipa":"/ɪmˈpruːv/","pos":"v.","def":"改进，改善；提高","sen":"We should keep improving ourselves all the time.","trans":"我们应该一直提升自己。","mne":"im强化前缀 + prove利润，有利 → 增加有利之处 → improve提高，改善"},{"word":"improvement","ipa":"/ɪmˈpruːvmənt/","pos":"n.","def":"改进，改善，进步","sen":"I hope our sales show some improvement soon.","trans":"我希望我们的销售很快会有所改善。","mne":"improve改善 + ment名词后缀 → improvement 改善"},{"word":"impulse","ipa":"/ˈɪmpʌls/","pos":"n.","def":"冲动；脉冲","sen":"These things were an impulse purchase on November 11th by him.","trans":"这些东西是他在“双十一”那天一时冲动买下来的。","mne":"im向内，进入 + pulse跳动 → 冲动"},{"word":"in","ipa":"/ɪn/","pos":"prep.","def":"在（某段时间）内","sen":"I usually read books in the evening.","trans":"我通常在晚上看书。","mne":""},{"word":"inadequate","ipa":"/ɪnˈædɪkwət/","pos":"adj.","def":"不足够的，不充分的，不适当的；不够好的","sen":"The small amount of food is inadequate for two people.","trans":"食物太少了，不够两个人吃。","mne":"in不 + ad加强意义 + equ平均 + ate……的 → 不充足的，不适当的"},{"word":"incentive","ipa":"/inˈsɛntɪv/","pos":"n.","def":"【财】激励，刺激；刺激，鼓励；动机","sen":"It is becoming increasingly common for companies to use their shares, or the right to acquire them, as a form of incentive.","trans":"公司将股份或获得股份的权利作为一种激励形式的做法越来越普遍。","mne":"in向内，进入 + cent唱歌 + ive名词后缀 → 把精神唱进去 → incentive激励"},{"word":"inch","ipa":"/ɪntʃ/","pos":"n.","def":"英寸；少许，少量","sen":"An inch is about two and a half centimeters.","trans":"一英寸大约是2.5厘米。","mne":""},{"word":"incident","ipa":"/ˈɪnsɪdənt/","pos":"n.","def":"事件；事变，（军事）冲突","sen":"The headmaster is talking to the two boys about the classroom incident.","trans":"校长正在和这两个男孩谈论教室事件。","mne":"in进入 + cid降临 + ent表名词 → incident偶然事件"},{"word":"incline","ipa":"/ˈɪnˌklaɪn/, /ɪnˈklaɪn/","pos":"n.","def":"倾斜，斜坡，斜面（读作/ˈɪnˌklaɪn/）；  v.使倾斜，使倾向于（读作/ɪnˈklaɪn/）","sen":"The small ball is on an incline and could hit the big ball.","trans":"小球在斜面的一端，可能会撞向大球。","mne":"in使 + clin倾斜 + e → incline 倾斜，斜坡"},{"word":"inclined","ipa":"/ɪnˈklaɪnd/","pos":"adj.","def":"斜着的","sen":"They installed a new inclined access ramp for wheelchairs.","trans":"他们为了方便轮椅通行安装了一个新的斜坡道。","mne":"inclin=incline趋势+ed形容词后缀 → 趋向于…的"},{"word":"include","ipa":"/ɪnˈkluːd/","pos":"v.","def":"包括，列入，包含","sen":"Elephants, frogs and birds can be included in the category of \"animals\".","trans":"大象、青蛙和鸟可以列入“动物”这个类别里。","mne":"in进入 + clude关闭 → 关进去 → include包括"},{"word":"inclusion","ipa":"/ɪnˈkluːʒn/","pos":"n.","def":"包含；内含物","sen":"The inclusion of a first-aid kit in the trip supplies was essential.","trans":"将急救箱纳入出行用品中是很有必要的。","mne":""},{"word":"inclusive","ipa":"/ɪnˈkluːsɪv/","pos":"adj.","def":"包含全部费用的；包容的","sen":"This tour is inclusive of all tickets.      ","trans":" 这次旅游包含所有门票。","mne":"in进入 + clus关闭 + ive形容词后缀 → 包括在内的"},{"word":"income","ipa":"/ˈɪnkʌm/","pos":"n.","def":"收入，收益","sen":"The workers' income isn't as much as they expected.","trans":"工人们的工资没有他们预期的高。","mne":"in 向内，进入 + come来 → 收入；收益；进款"},{"word":"inconsistent","ipa":"/ˌɪnkənˈsɪstənt/","pos":"adj.","def":"不一致的，前后矛盾的","sen":"His views about her were always changing, so inconsistent!","trans":"他对她的感情总是在变化，太前后矛盾了！","mne":""},{"word":"incorporate","ipa":"/ɪnˈkɔːrpəreɪt/","pos":"v.","def":"包含","sen":"The app update incorporates many new features and improvements.","trans":"这款应用程序的更新加入了许多新功能和改进。","mne":"in向内，进入 + corpor团体 + ate动词后缀 → 成为团体 → incorporate合并，并入"},{"word":"increase","ipa":"/ɪnˈkriːs/, /ˈɪŋkriːs/","pos":"v.","def":"增加，增长，增多；  n.增强，提高（读作/ˈɪŋkriːs/）；增加","sen":"The population has increased dramatically in recent years.","trans":"近年来，人口急剧增加。","mne":"in向内 + crease生长 → increase增加"},{"word":"increasingly","ipa":"/ɪnˈkriːsɪŋli/","pos":"adv.","def":"日益，越来越多地","sen":"Snow increasingly accumulated on the ground.","trans":"地上的积雪越来越多。","mne":"in加强 ＋ creas=grow增长 ＋ ing...的 ＋ ly...地 → increasingly日益，越来越多地"},{"word":"indeed","ipa":"/ɪnˈdiːd/","pos":"adv.","def":"的确，当然，确实；真正地","sen":"I indeed lost sleep last night.","trans":"我昨晚的确失眠了。","mne":"in在...内 + deed行为 → indeed的确"},{"word":"indefinite","ipa":"/ɪnˈdefɪnət/","pos":"adj.","def":"不清楚的，模糊的；无限的","sen":"Which door should he go through? The answer is indefinite.","trans":"他应该通过哪扇门？答案是不确定的。","mne":"in无 + defin=define确定 + ite形容词后缀 → 不确定的"},{"word":"independence","ipa":"/ˌɪndɪˈpendəns/","pos":"n.","def":"（国家的）独立","sen":"It is from Britain that America gained its independence.","trans":"美国是从英国获得独立的。","mne":"in不 + depend依靠 + ence名词后缀 → 不依靠 → independence独立，自主"},{"word":"independent","ipa":"/ˌɪndɪˈpendənt/","pos":"adj.","def":"独立的，自立的；  n.无党派者","sen":"He is learning to be independent in the face of a challenge.","trans":"他在学习独立面对挑战。","mne":"in不 + depend依靠 + ent……的 → 不依靠的 → independent独立的"},{"word":"index","ipa":"/ˈɪndeks/","pos":"n.","def":"指数；指标；索引","sen":"The stock index rises and falls all the time. Invest cautiously.","trans":"股票指数总是起伏不定，投资请谨慎。","mne":"in进入 + dex显示，宣告 → index指数"},{"word":"indicate","ipa":"/ˈɪndɪkeɪt/","pos":"v.","def":"表明","sen":"Can you guess what the line chart indicates?","trans":"你能猜到这张折线图说明了什么吗？","mne":"in进入 + dic说话，断言 + ate使，造成 → 说进去 → indicate指示，指明"},{"word":"indication","ipa":"/ˌɪndɪˈkeɪʃn/","pos":"n.","def":"迹象；指示；表明","sen":"The green arrow is an indication showing that you're allowed to turn left.","trans":"绿箭头表明你可以往左拐。","mne":"in向内，进入 + dic说话，断言 + ation名词后缀 → 指示，指出，表示"},{"word":"indifference","ipa":"/ɪnˈdɪfrəns/","pos":"n.","def":"冷淡，不关心","sen":"He rolled his eyes to show his indifference.","trans":"他翻了翻白眼来显示他的冷淡。","mne":"indiffer=indifferent漠不关心的 + ence名词后缀 → 不关心"},{"word":"indifferent","ipa":"/ɪnˈdɪfrənt/  ","pos":"adj.","def":"不感兴趣的，不关心的","sen":"The staff were indifferent about the new plan put forward by their boss.","trans":"员工们对老板提出的新计划漠不关心。","mne":"in不，无，非 + different不同的 → 与众不同的 → indifferent冷漠的"},{"word":"indispensable","ipa":"/ˌɪndɪˈspensəbl/","pos":"adj.","def":"不可缺少的","sen":"He has become an indispensable member of our project group.","trans":"他已成为我们项目组不可缺少的一员。","mne":"in表否定 + dis向外 + pens=pense称重 + able能...的 → 不能够按重量向外分发的 → indispensable必不可少的"},{"word":"individual","ipa":"/ˌɪndɪˈvɪdʒuəl/","pos":"adj.","def":"个别的；个人的；  n.个人","sen":"The teacher is the individual person not wearing a uniform in this graduation photo.","trans":"老师是这张毕业照里唯一没穿校服的人。","mne":"in不，非 + divid分开，分割 + ual → 不可分割的 → individual个人，独立的个体"},{"word":"indoors","ipa":"/ˌɪnˈdɔːrz/","pos":"adv.","def":"在室内，在屋里","sen":"This golf course also allows you to play golf indoors.","trans":"这种高尔夫球场让你在室内也能打高尔夫。","mne":"in进入 + door门 + s表副词 → indoors在屋内"},{"word":"induce","ipa":"/ɪnˈduːs/","pos":"v.","def":"引导，劝诱","sen":"The leader gave a speech to induce his staff to work harder.","trans":"领导发表讲话，引导员工更加努力地工作。","mne":"in进入+duce引导，带来→引进去→劝诱，诱导"},{"word":"industrial","ipa":"/ɪnˈdʌstriəl/","pos":"adj.","def":"工业的；产业的","sen":"The industrial area gives out lots of smoke every day.","trans":"这个工业区每天排放大量浓烟。","mne":"industrial=industry工业 + ial有...性质的 → a.工业的；产业的"},{"word":"industrialise","ipa":"/ɪn'dʌstrɪəlaɪz/","pos":"v.","def":"(使)工业化","sen":"They wanted to industrialise their nation.","trans":"他们想使国家工业化。","mne":""},{"word":"industrialize","ipa":"/ɪnˈdʌstriəlaɪz/","pos":"v.","def":"(使)工业化","sen":"The big city has been completely industrialized.","trans":"这个大城市已经实现了工业化。","mne":""},{"word":"industry","ipa":"/ˈɪndəstri/","pos":"n.","def":"工业，产业；行业；勤劳","sen":"Heavy industry is important for our economy. ","trans":"重工业对于我们的经济很重要。","mne":"indu在..中 + stry构建，传播 → 在...中建设 → industry工业，勤劳"},{"word":"inevitable","ipa":"/ɪnˈevɪtəbl/","pos":"adj.","def":"不可避免的，必然的","sen":"It is inevitable for people to get old.","trans":"人变老是不可避免的。","mne":"in不 + evit避免 + able形容词后缀, 可...的 → 不可避免的，必然的"},{"word":"infant","ipa":"/ˈɪnfənt/","pos":"n.","def":"幼儿，婴儿；  adj.婴儿的；初期的，初创的","sen":"The infant in the duck towel is laughing happily.","trans":"裹在鸭子毛巾里的小婴儿笑得真开心。","mne":"in不 + fant说话 →不能说话的 → infant婴儿的"},{"word":"infect","ipa":"/ɪnˈfekt/","pos":"v.","def":"传染，感染；使受影响","sen":"You are sick! Put the mask on, or you will infect others.","trans":"你生病了！ 把口罩戴上，不然你会传染给别人的。","mne":"in进入 + fect做 → 做进去，传染进去 → infect传染，感染"},{"word":"infection","ipa":"/ɪnˈfekʃn/","pos":"n.","def":"感染；传染","sen":"This poor guy has a really terrible lung infection.","trans":"这个可怜的家伙受到了很严重的肺部感染。","mne":"infect传染 + ion表名词 → infection传染"},{"word":"infectious","ipa":"/ɪnˈfekʃəs/","pos":"adj.","def":"有传染性的，易传染的；具有感染力的","sen":"The disease is highly infectious and spreads rapidly among children.","trans":"这种疾病传染性很强，在儿童中传播很快。","mne":"in进入 + fect做 + infect做进去=传染 + ious……的 → infectious传染的"},{"word":"infer","ipa":"/ɪnˈfɜːr/","pos":"v.","def":"推断；暗示","sen":"He infers from the thick black smoke that there is a fire.","trans":"他根据滚滚黑烟推断出这里发生了火灾。","mne":"in进入+ fer带来，拿来 → 带进[意义] → 推理，推断"},{"word":"inference","ipa":"/ˈɪnfərəns/","pos":"n.","def":"【数】推断，推论；推断","sen":"By applying mathematical inferences, students can solve complex problems more effectively.","trans":"通过应用数学推理，学生们可以更有效地解决复杂问题。","mne":"in在...内 + fer携带 + ence名词后缀 -> inference推断"},{"word":"inferior","ipa":"/ɪnˈfɪriər/","pos":"adj.","def":"（等级、地位等）低等的；低劣的","sen":"He makes me feel I'm inferior to him.","trans":"他让我感觉在他面前低人一等。","mne":"infer推断 + ior表形容词，较…的 → 轻易推断出的 → inferior低下的"},{"word":"infinite","ipa":"/ˈɪnfɪnət/","pos":"adj.","def":"无限的，无穷的","sen":"We live in an infinite universe that might have no boundaries.","trans":"我们生活在一个可能没有边界的无限宇宙中。","mne":"in无 + fin结束，范围 + ite有……的 → 没有范围的 → 无限的"},{"word":"inflation","ipa":"/ɪnˈfleɪʃn/","pos":"n.","def":"通货膨胀；（充气后）膨胀","sen":"Because of the inflation, we could buy less fruit with the same money.","trans":"因为通货膨胀，我们用同样的钱只能买到更少的水果。","mne":"in进 + flat吹 + ion表名词 → 充气；通货膨胀"},{"word":"influence","ipa":"/ˈɪnfluəns/","pos":"n.","def":"影响，作用；  v.影响，作用","sen":"His mother was a main influence on his becoming a pianist.","trans":"他成为一名钢琴家主要是受了他母亲的影响。","mne":"in进入 + flu流动 + ence名词后缀 → 流入 → influence影响"},{"word":"influential","ipa":"/ˌɪnfluˈenʃl/","pos":"adj.","def":"有极大影响力的","sen":"He is such an influential star that many people copy his look.","trans":"他是一位很有影响力的明星，许多人都在模仿他的穿着。","mne":"in进入+flu流动+ent+ial…的→流入，影响现有状态→influential有影响的"},{"word":"inform","ipa":"/ɪnˈfɔːrm/","pos":"v.","def":"告知，通知","sen":"The penguin informed everyone of the rule.","trans":"企鹅向所有人宣布了这项规定。","mne":"in进 + form形状 → 进入形式 → inform正式通知"},{"word":"information","ipa":"/ˌɪnfɚˈmeɪʃn/","pos":"n.","def":"信息；情报，资料","sen":"The Internet is my main source of getting information about other countries.","trans":"因特网是我获取其他国家信息的主要来源。","mne":"inform通知 + ation动作化名词后缀 → information 信息"},{"word":"infrastructure","ipa":"/ˈɪnfrəstrʌktʃər/","pos":"n.","def":"基础设施","sen":"A good infrastructure includes transport, communications, etc.","trans":"完善的基础设施包括交通、通信等。","mne":"infra下，低 ＋ struct建立 ＋ ure名词后缀 → infrastructure下部结构，基础设施"},{"word":"ingredient","ipa":"/ɪnˈɡriːdiənt/ ","pos":"n.","def":"成分；【化】成分，配料；成分，构成要素","sen":"The main ingredient in this medication is acetaminophen.","trans":"这种药的主要成分是对乙酰氨基酚。","mne":"in进入 + gred走 + ient → 走进去的，成为其中一部分 → ingredient成份，因素"},{"word":"inhabit","ipa":"/ɪnˈhæbɪt/","pos":"v.","def":"居住于；栖息于","sen":"Primitive tribes used to inhabit these forests.","trans":"原始部落过去居住在森林里。","mne":""},{"word":"inhabitant","ipa":"/ɪnˈhæbɪtənt/","pos":"n.","def":"居民，住户","sen":"This small town has many inhabitants.","trans":"小镇上有很多居民。","mne":"in使 + habit居住 + ant表示人 → 住户，居民"},{"word":"inherent","ipa":"/ɪnˈhɪrənt/","pos":"adj.","def":"生来就有的；内在的，固有的","sen":"Many believe that curiosity is inherent in children.","trans":"很多人认为好奇是儿童的天性。","mne":"in里面 + her粘附 + ent有...性质的 → 天生与身体内连着 → 天赋的，生来的"},{"word":"inherit","ipa":"/ɪnˈherɪt/","pos":"v.","def":"经遗传而得（特性等）；继承","sen":"The baby inherited his father's curly hair.","trans":"小宝宝遗传了父亲的卷发。","mne":"in在...内 + herit继承 → inherit经遗传而得"},{"word":"initial","ipa":"/ɪˈnɪʃl/","pos":"adj.","def":"字首的；最初的，开始的；  n.（单词）首字母；  v.用姓名的首字母签名于","sen":"The initial letter of this word is \"a.\"","trans":"这个单词的首字母是“a”。","mne":"in进入 + it行走 + ial形容词后缀 → 走进 → initial开始的，最初的"},{"word":"initially","ipa":"/ɪˈnɪʃəli/","pos":"adv.","def":"最初；【航】最初 ，一开始","sen":"People initially lived in caves; now they live in houses.","trans":"人们最初住在山洞里，现在住在房子里。","mne":"initial最初的 + ly……地 → initially最初，开头"},{"word":"initiate","ipa":"/ɪˈnɪʃiˌeɪt/, /ɪˈnɪʃiɪt/","pos":"v.","def":"开始，发动（读作/ɪˈnɪʃiˌeɪt/）；传授","sen":"The boy initiated the war by launching a missile.","trans":"小男孩发射导弹发动了这场战争。","mne":"in进入 + ire＝iti去 + iate表动词 → initiate开始，发动"},{"word":"initiative","ipa":"/ɪˈnɪʃətɪv/","pos":"n.","def":"主动权，主动性；倡议","sen":"Her boyfriend took the initiative and cleaned up after they all had dinner.","trans":"她男朋友在他们吃完晚饭后主动打扫了卫生。","mne":"in进入 + it行走 + iat开始 + ive名词后缀 → initiative主动"},{"word":"inject","ipa":"/ɪnˈdʒekt/","pos":"v.","def":"给……注射；注入","sen":"\"Does this hurt?\" the doctor asked as she injected her patient with antibiotics.","trans":"“痛吗？”医生一边给患者注射抗生素一边问。","mne":"in向内，进入 + ject投掷，扔 → 扔进去 → 注射"},{"word":"injection","ipa":"/ɪnˈdʒekʃn/","pos":"n.","def":"注射，注入","sen":"The woman in his arms was ready for her injection.","trans":"在美马怀里的灭已经做好了接受注射的准备。","mne":"inject注射 + ion名词后缀 → injection 注射"},{"word":"injure","ipa":"/ˈɪndʒər/","pos":"v.","def":"伤害，使受伤","sen":"The worker injured himself at the construction site.","trans":"这名工人在工地上受伤了。","mne":""},{"word":"injury","ipa":"/ˈɪndʒəri/ ","pos":"n.","def":"损伤；【航】伤害","sen":"The man got a knee injury when playing soccer.","trans":"踢足球时，这个男人的膝盖受伤了。","mne":"in不，相反 + jur公正，法律 + y表名词 → 违背法律的不公正行为 → injury伤害"},{"word":"ink","ipa":"/ɪŋk/","pos":"n.","def":"墨水，油墨；  v.给……上油墨","sen":"I used ink to write some nice Spring Festival wishes.","trans":"我用墨水写了些春节祝福。","mne":"in使... + k烧 → ink墨水"},{"word":"inn","ipa":"/ɪn/","pos":"n.","def":"客栈，小旅馆","sen":"This traditional inn is surrounded by trees.","trans":"这个传统的小旅店被绿树环绕。","mne":""},{"word":"inner","ipa":"/ˈɪnər/","pos":"adj.","def":"内部的，里面的；内心的","sen":"The inner core of the Earth is made up of iron and nickel.","trans":"地球内部的核心由铁和镍组成。","mne":""},{"word":"innocence","ipa":"/ˈɪnəsns/","pos":"n.","def":"天真无邪，单纯；清白，无罪","sen":"Nothing compares to the innocence of a child.","trans":"什么也比不上孩子的天真无邪。","mne":"in无 ＋ noc伤害，毒 ＋ ence名词后缀 → innocence无害；天真"},{"word":"innocent","ipa":"/ˈɪnəsnt/","pos":"adj.","def":"天真的，单纯的；无辜的，清白的；无罪的","sen":"The child had an innocent smile that made everyone around her feel happy.","trans":"这孩子有着天真无邪的笑容，让周围的每个人都感到快乐。","mne":"in无 + noc伤害，毒 + ent形容词后缀 → innocent无害的"},{"word":"innovation","ipa":"/ˌɪnəˈveɪʃn/","pos":"n.","def":"创新，革新","sen":"The age of innovation has already come to us.","trans":"创新时代正在向我们走来。（走进新时代~）","mne":"in进入 + nov新 + ation名词后缀 → innovation创新"},{"word":"innovative","ipa":"/ˈɪnəveɪtɪv/","pos":"adj.","def":"创新的，革新的","sen":"This girl always comes up with new and innovative ideas!","trans":"这女孩儿总能想出一些具有创新意义的新点子！","mne":"in进入 + nov新的 + ative形容词后缀，…的 → 革新的，创新的"},{"word":"input","ipa":"/ˈɪnpʊt/","pos":"n.","def":"【计算机】输入；  v.【数】输入","sen":"The mouse and the keyboard are input devices.","trans":"鼠标和键盘是输入设备。","mne":"in往里 + put放 → input输入"},{"word":"inquire","ipa":"/ɪn'kwaɪər/","pos":"v.","def":"打听，询问；调查","sen":"The policeman is inquiring about the escaped prisoner's whereabouts.","trans":"警察正在询问逃犯的行踪。","mne":"in进入 + quire寻求，询问 → 追问到里面去 → inquire盘问，追究"},{"word":"inquiry","ipa":"/ˈɪnkwəri/","pos":"n.","def":"调查；询问","sen":"Let's conduct an inquiry into the origin of this question mark.","trans":"让我们来对问号的由来进行一项调查。","mne":"inquir询问 + y名词后缀 → inquiry调查"},{"word":"insect","ipa":"/ˈɪnsekt/ ","pos":"n.","def":"昆虫","sen":"There are many kinds of insects, such as butterflies, bees and ants.","trans":"昆虫有很多种类，例如蝴蝶、蜜蜂和蚂蚁。","mne":"in进入 + sect切，割 → 昆虫一节一节如被切开一样 → insect昆虫"},{"word":"insert","ipa":"/ɪnˈsɜrt/, /ˈɪnˌsɜrt/","pos":"v.","def":"插入，嵌入（读作/ɪnˈsɜrt/）","sen":"I am inserting my USB flash drive into the laptop.","trans":"我正在将我的U盘插入笔记本电脑中。","mne":"in进入 + sert加入，插入 → 加入进来 → insert插入"},{"word":"inside","ipa":"/ˌɪnˈsaɪd/","pos":"n.","def":"【数】内部；里面，内部；  adj.里面的；  adv.在（或向）里面，在内部","sen":"Inside the circle is a flower.","trans":"这个圆的内部是一朵花。","mne":"in向内，进入 + side边 → inside内部，里面"},{"word":"insight","ipa":"/ˈɪnsaɪt/","pos":"n.","def":"深刻的理解，洞察力；见识","sen":"He really has an insight into math.","trans":"他对数学真的有很深刻的见解。","mne":"in进入 + sight眼光 → 眼光看进去 → 洞察力"},{"word":"insist","ipa":"/ɪnˈsɪst/","pos":"v.","def":"坚持要求；坚持认为","sen":"His mother insists that he should put on his warm pants.","trans":"男孩的妈妈坚持要他穿秋裤。","mne":"in加强 + sist站立 → 一直站 → insist坚持；硬要"},{"word":"inspect","ipa":"/ɪnˈspekt/","pos":"v.","def":"检查，审查；视察","sen":"He is inspecting the shop for a hygiene check.","trans":"他正在对这家店铺进行卫生检查。","mne":"in内 + spect看 → 看进去 → 视察"},{"word":"inspection","ipa":"/ɪnˈspekʃn/","pos":"n.","def":"检查，细看；查看","sen":"The mechanic gave the car a thorough inspection according to the check list.","trans":"技工根据检查清单对汽车进行了一次全面检查。","mne":"inspect视察 + ion表名词 → 视察；认真看"},{"word":"inspire","ipa":"/ɪnˈspaɪər/ ","pos":"v.","def":"激励，鼓舞；激发灵感；启示","sen":"My father inspired my confidence to become an astronaut from an early age.","trans":"父亲从小就激发了我成为宇航员的信心。","mne":"in进 + spir呼吸 + e强调 → 吸气进去，引申为鼓励 → inspire鼓励"},{"word":"instal","ipa":"/ɪn'stɔːl/","pos":"v.","def":"安装，设置（同install）","sen":"My dad helped me to instal the new cabinets in the kitchen.","trans":"我爸帮我在厨房安装了一个新橱柜。","mne":""},{"word":"install","ipa":"/ɪnˈstɔːl/","pos":"v.","def":"安装，安置；使就职","sen":"The man installed a ceiling fan.","trans":"这个男人把吊扇装上了。","mne":"in进 + stall放 → 放进去 → install安装"},{"word":"installation","ipa":"/ˌɪnstəˈleɪʃn/","pos":"n.","def":"安装，装置","sen":"The installation of the air conditioning was a little difficult.","trans":"安装空调有一些难度。","mne":"install安装 + ation名词后缀 → installation安装"},{"word":"installment","ipa":" /ɪnˈstɔːlmənt/","pos":"n.","def":"分期付款","sen":"I have to pay for my car in monthly installments.","trans":"我用每月分期付款的方式买了车。","mne":"in不 + stall停止 + ment名词后缀→ 不停地送钱 → installment分期付款"},{"word":"instalment","ipa":"/ɪnˈstɔːlmənt/","pos":"n.","def":"分期付款；（连载作品或分集戏剧等的）一部分","sen":"We prefer to pay for things over 12 monthly instalments.","trans":"我们更愿意12个月分期付款。","mne":""},{"word":"instance","ipa":"/ˈɪnstəns/","pos":"n.","def":"例子，实例，事例；情况，场合","sen":"Earthquakes, in some instances, can be devastating, whereas in others they might be quite mild.","trans":"地震在一些情况下可能是毁灭性的，但在另一些情况下则影响较小。","mne":"in=inside在里面 ＋ st=stand站立 ＋ ance构成名词：表性质、状况等 → 站在里面，属于某事物内，以身为例 → instance例子"},{"word":"instant","ipa":"/ˈɪnstənt/","pos":"n.","def":"瞬间；  adj.立即的","sen":"The mother caught her baby the instant he fell.","trans":"那位母亲在孩子掉下的瞬间接住了他。","mne":"in进入 + st站立 + ant…的 → 站进来的 → instant紧急的"},{"word":"instantly","ipa":"/ˈɪnstəntli/","pos":"adv.","def":"立即地；  conj.一…就…","sen":"The beauty of this camera is that the photo is ready instantly.","trans":"这台相机的妙处在于照片立即可得。","mne":"instant立即的 + ly副词后缀 → instantly立即地"},{"word":"instead","ipa":"/ɪnˈsted/","pos":"adv.","def":"代替，顶替；更换；反而","sen":"Have some healthy food instead of hamburgers.","trans":"吃点健康的食品，别吃汉堡包了。","mne":"in进入，使 + stead位置 → instead代替"},{"word":"instinct","ipa":"/ˈɪnstɪŋkt/","pos":"n.","def":"本能，天性；天分，天资；直觉","sen":"Even well-fed cats will kill mice because of their hunting instincts.","trans":"即使喂得很饱的猫也会捉老鼠，因为它们有捕食老鼠的天性。","mne":"in内 + stinct刺激 → 内在的刺激 → instinct本能 "},{"word":"institute","ipa":"/ˈɪnstɪtuːt/","pos":"n.","def":"学院，专科学院，研究院（或所）；学会；机构；  v.建立，设立，制定","sen":"A lot of top scientists are working in this institute of medical biology.","trans":"许多顶尖的科学家在这家医用生物学的研究院工作。","mne":"in内部 + stitut建立 + e → 建立在内部的 → 学院；制定，设立"},{"word":"institution","ipa":"/ˌɪnstɪˈtuːʃn/","pos":"n.","def":"机构；制度；惯例；习俗","sen":"This English language training institution is very popular with parents and their children alike.","trans":"这家英语培训机构很受家长和孩子们的欢迎。","mne":"in在......里 + stitut建立 + ion名词后缀 → institution机构"},{"word":"instruct","ipa":"/ɪnˈstrʌkt/","pos":"v.","def":"教导；指示；通知","sen":"My mom instructs me how to play golf.","trans":"我妈妈教我怎么打高尔夫球。","mne":"in进 + struct建立 → 把知识建立进去 → instruct指导"},{"word":"instruction","ipa":"/ɪnˈstrʌkʃn/","pos":"n.","def":"说明，说明书；指导；指令，命令；指示","sen":"She follows the instructions to take her medicine.","trans":"她按照说明书的指示服药。","mne":"instruct指导 + ion名词后缀 → instruction指导"},{"word":"instructive","ipa":"/ɪnˈstrʌktɪv/","pos":"adj.","def":"有教育意义的","sen":"The little boy learned from this instructive book that it is wrong to lie.","trans":"这个小男孩从这本有教育意义的书中学到了说谎是错误的。","mne":"in进 + struct建立 + ive形容词后缀 → 把知识建立进去 → instructive有益的；教育性的"},{"word":"instrument","ipa":"/ˈɪnstrəmənt/ ","pos":"n.","def":"乐器；工具；仪器；手段","sen":"Guitar, violin, drum, and piano are all musical instruments.","trans":"吉他、小提琴、鼓和钢琴都是乐器。","mne":"in内 + stru=struct建立 + ment表名词 → 内部结构 → instrument仪器；工具"},{"word":"insult","ipa":"/ɪnˈsʌlt/, /ˈɪnsʌlt/","pos":"v.","def":"侮辱；  n.侮辱的言辞或行为","sen":"The customer insulted the ice cream seller by throwing the money to the ground.","trans":"这个顾客把钱丢在地上，以此来侮辱卖冰激凌的小贩。","mne":"in进入 + sult跳 → 踩到别人的脸上 → insult侮辱"},{"word":"insurance","ipa":"/ɪnˈʃʊrəns/","pos":"n.","def":"保险；保险费；保险业","sen":"Insurance can offer financial protection against loss as a result of an accident.","trans":"保险能够提供经济上的保护，赔偿因事故造成的损失。","mne":"insur保证 + ance名词后缀 → insurance保险"},{"word":"insure","ipa":"/ɪnˈʃʊr/","pos":"v.","def":"为……投保","sen":"I insure my car against accident and theft.","trans":"我为我的车上了事故险和偷盗险。","mne":"in进入 + sure肯定 → 进入肯定 → 保险"},{"word":"integrate","ipa":"/ˈɪntɪˌɡreɪt/","pos":"v.","def":"（使）成为一体，（使）合并；（使）加入，融入群体","sen":"Our department's four teams must integrate together to work on new projects.","trans":"我们部门的四个小组必须合力推进新项目。","mne":"integr完整 ＋ ate使… → 使…完整 → integrate使一体，使结合"},{"word":"integrity","ipa":"/ɪnˈteɡrəti/","pos":"n.","def":"正直，真诚；完整","sen":"The judge has a strong sense of integrity.","trans":"这位法官有强烈的正直感。","mne":"integr完整 + ity表名词 → integrity完整，完全"},{"word":"intellectual","ipa":"/ˌɪntəˈlektʃuəl/","pos":"adj.","def":"聪明的；需用智力的；  n.知识分子","sen":"The intellectual girl is familiar with all the math formulas.","trans":"这个聪明的女孩熟知所有的数学公式。","mne":"intel在...之间 + lectu选，挑选 + al形容词后缀 -> intellectual聪明的"},{"word":"intelligence","ipa":"/inˈtelɪdʒəns/","pos":"n.","def":"智力；理解力；情报","sen":"Einstein was a man of great intelligence.","trans":"爱因斯坦是一个智商很高的人。","mne":"intel在…中间 + lig选择，收集 + ence名词后缀 → 从中选出好的 → 智力"},{"word":"intelligent","ipa":"/ɪnˈtelɪdʒənt/","pos":"adj.","def":"有智慧的，聪明的","sen":"If you are as intelligent as this scientist, you may change the world.","trans":"如果你像这位科学家那么聪明，你就有可能改变世界。","mne":"intellig知识界 + ent表示具有……性质的 → intelligent智能型的，聪明的"},{"word":"intend","ipa":"/ɪnˈtend/","pos":"v.","def":"打算；计划","sen":"The boy intends to use the money he saved to buy a new skateboard.","trans":"男孩打算用存下来的钱买一块新的滑板。","mne":"in内 + tend伸展；扩大 → 内心伸出 → intend打算"},{"word":"intense","ipa":"/ɪnˈtens/","pos":"adj.","def":"强烈的；紧张的","sen":"People are having an intense training in the gym.","trans":"人们正在健身房里进行着高强度的的训练。","mne":"in使 + tense延伸 → 使拉长，绷紧 → intense剧烈的，强烈的"},{"word":"intensify","ipa":"/ɪnˈtensɪfaɪ/","pos":"v.","def":"增强","sen":"The microphone intensifies the loudness of my voice.","trans":"麦克风能扩大我说话的音量。","mne":"in使 + tens延伸 + ify动词后缀 → intensify变猛烈；加强"},{"word":"intensity","ipa":"/ɪnˈtensəti/","pos":"n.","def":"强度；强烈，剧烈","sen":"Light of high intensity may blind your eyes.","trans":"强光线可能会闪瞎你的双眼。","mne":"in 加强 + tens伸展 + ity表名词 → 拉紧 → 强烈，剧烈"},{"word":"intensive","ipa":"/ɪnˈtensɪv/","pos":"adj.","def":"加强的；密集的","sen":"The intensive study for the college entrance exam made him exhausted.","trans":"高考强化训练让他精疲力竭。","mne":"intens强烈的 + ive形容词后缀 → intensive加强的"},{"word":"intensively","ipa":"/ɪnˈtensɪvli/","pos":"adv.","def":"集中地","sen":"He studied intensively for the exam to ensure he would pass.","trans":"他为考试进行了密集的复习，以确保能够通过。","mne":""},{"word":"intention","ipa":"/ɪnˈtenʃn/","pos":"n.","def":"目的，意图","sen":"I have an intention of buying a house, so I must start saving money now.","trans":"我一心想买房，所以我现在必须开始存钱了。","mne":"intent意图 + ion表名词 → 有意图做某事 → intention有意图，故意"},{"word":"interact","ipa":"/ˌɪntərˈækt/ ","pos":"v.","def":"交流，互动；互相作用，互相影响","sen":"You need to interact with people in business.","trans":"做生意，你就得与人交流。","mne":"inter互相 + act行动 → interact交流，沟通"},{"word":"interaction","ipa":"/ˌɪntərˈækʃn/","pos":"n.","def":"相互作用；互动","sen":"The interaction between students and teachers is important in teaching.","trans":"师生之间的相互作用在教学中很重要。","mne":"inter相互 + action行动 → 相互行动 → interaction互动"},{"word":"interest","ipa":"/ˈɪntrəst/ ","pos":"n.","def":"兴趣；利益；利息","sen":"His interest is to read comics.","trans":"他的兴趣是看漫画。","mne":"inter表示“在…之间，相互 + est表示最高级“最……” → 兴趣；利益；利息"},{"word":"interested","ipa":"/ˈɪntrəstɪd/","pos":"adj.","def":"感兴趣的","sen":"The baby seems to be interested in the school bus.","trans":"小宝宝似乎对这辆校车很感兴趣。","mne":"interest兴趣 ＋ ed形容词后缀 → 感觉有兴趣的 → interested感兴趣的"},{"word":"interesting","ipa":"/ˈɪntrəstɪŋ/","pos":"adj.","def":"有趣的，吸引人的","sen":"Watching cartoons is more interesting for the little baby.","trans":"对于这个小宝宝来说，看动画片更有趣。","mne":"interest对...有兴趣 + ing形容词或现在分词后缀 → interesting有趣的"},{"word":"interfere","ipa":"/ˌɪntərˈfɪr/","pos":"v.","def":"干涉，妨碍","sen":"Let it fall. Don't interfere with the process.","trans":"让它倒下去。别去干涉这个过程。","mne":"inter在…之间 + fer带来，拿来 + e → interfere干涉，干预；妨碍"},{"word":"interference","ipa":"/ˌɪntərˈfɪrəns/","pos":"n.","def":"干涉；介入；（电波的）干扰","sen":"Interference refers to unnecessary interruption.","trans":"干涉指的是不必要的打扰。","mne":"interfere干涉 + ence表名词 → interference干涉"},{"word":"interior","ipa":"/ɪnˈtɪriər/","pos":"adj.","def":"内部的；  n.内部","sen":"The interior furnishing of the living room is very delicate.","trans":"客厅的内部装潢十分精致。","mne":"inter内 + ior表形容词，较...的 → interior内部的"},{"word":"intermediate","ipa":"/ˌɪntərˈmiːdiət/","pos":"adj.","def":"中间的；中级的","sen":"The toy in the middle is of intermediate size.","trans":"中间的玩具尺寸适中。","mne":"inter在…之间，相互 + medi中间 + ate做、造成 → intermediate中间的；中级的"},{"word":"internal","ipa":"/ɪnˈtɝːnəl/","pos":"adj.","def":"体内的，内部的；  n.内部器官","sen":"The picture shows humans' major internal organs.","trans":"这张图展示了人体主要的内脏器官。","mne":"intern=inter在…之内 + al属于...的 → internal内的；国内的"},{"word":"internally","ipa":"/ɪnˈtɜːrnəli/","pos":"adv.","def":"【航】内部地","sen":"The engine has been internally inspected and ready for takeoff.","trans":"发动机已经通过内部检查，准备起飞。","mne":""},{"word":"international","ipa":"/ˌɪntərˈnæʃnəl/","pos":"adj.","def":"国际的，世界的","sen":"All of them are international students from different countries.","trans":"他们都是来自不同国家的国际学生。","mne":"inter在…之间，相互 + national国家的 → international国际的"},{"word":"internet","ipa":"/ˈɪntərnet/","pos":"n.","def":"因特网；互联网","sen":"We can get news on the Internet.","trans":"我们可以在互联网上获取新闻。","mne":""},{"word":"interpret","ipa":"/ɪnˈtɜːrprət/","pos":"v.","def":"口译；解读；解释；  v.把……理解（解释）为","sen":"I interpreted his words into English.","trans":"我把他的话口译成了英文。","mne":"inter相互 + pret表达 → 语言之间相互表达 → interpret口译"},{"word":"interpretation","ipa":"/ɪnˌtɜːrprɪˈteɪʃn/","pos":"n.","def":"口译；理解，解释","sen":"His English-Chinese interpretation is strange; I doubt if it is correct.","trans":"他将英文翻译成了很奇怪的中文，我怀疑他翻得不对。","mne":"inter在…之间，相互 + pret预先 + ation名词后缀 → 相互之间预先了解 → interpretation口译；解释"},{"word":"interrupt","ipa":"/ˌɪntəˈrʌpt/","pos":"v.","def":"打断；打扰；打岔","sen":"Their conversation was interrupted by a knock at the door.","trans":"他们的谈话被敲门声打断了。","mne":"inter在…中间 + rupt断裂 → 在讲话中间打断 → interrupt打断"},{"word":"interruption","ipa":"/ˌɪntəˈrʌpʃən/","pos":"n.","def":"打扰；【财】中断，打断","sen":"He wore a pair of headphones to prevent his friend's interruption.","trans":"他戴了一副耳机，防止他朋友的打扰。","mne":"inter 从中间 + rupt 打破 + ion 名词后缀 → interruption 打扰"},{"word":"interval","ipa":"/ˈɪntərvl/","pos":"n.","def":"间隔；中场休息，幕间休息","sen":"This clock only shows fifteen-second intervals.","trans":"这个表只能显示15秒的时间间隔。","mne":"inter在内，中间 + val墙 → 两堵墙之间的空间 → interval间隔，间歇"},{"word":"intervene","ipa":"/ˌɪntərˈviːn/","pos":"v.","def":"介入，调停","sen":"They only stopped fighting when the teacher intervened.","trans":"当老师介入时，他们才停止打架。","mne":"inter在…之间，相互 + ven走 + e → 走在二者之间 → intervene干涉"},{"word":"intervention","ipa":"/ˌɪntərˈvenʃn/","pos":"n.","def":"干涉，干预；介入；调停","sen":"The man's intervention stops the dominos.","trans":"这名男子的干预阻止了多米诺骨牌。","mne":"inter在…之间，相互 + ven走 + tion名词后缀 → intervention干涉，干预"},{"word":"interview","ipa":"/ˈɪntərvjuː/","pos":"n.","def":"面试；  v.面试","sen":"During the job interview, the man seemed nervous.","trans":"在求职面试过程中，这位男士似乎很紧张。","mne":"inter互相 + view看见 → interview会见"},{"word":"interviewer","ipa":"/ˈɪntərvjuːər/","pos":"n.","def":"面试官；采访者","sen":"The interviewer is looking at his resume to ask questions.","trans":"面试官正看着他的简历提问。","mne":"inter相互 ＋ view观察 ＋ er人 → interview面试 ＋ er人 → interviewer会见者；面谈者"},{"word":"intimate","ipa":"/ˈɪntɪmət/","pos":"adj.","def":"亲密的，密切的；详细的","sen":"They are very intimate friends.","trans":"她们是非常亲密的朋友。","mne":"intim内心的 + ate……的 → 内心的 → 亲近的；不说出口的 → intimate亲密的"},{"word":"into","ipa":"/ˈɪntuː/","pos":"prep.","def":"进入，到……里面","sen":"This sign means that you are allowed to get into this room.","trans":"这个标志表明允许你进入这个房间。","mne":""},{"word":"introduce","ipa":"/ˌɪntrəˈduːs/ ","pos":"v.","def":"介绍；传入，引进","sen":"They introduced themselves to each other.","trans":"他们相互问候。","mne":"intro向内，入内 + duce引 → 引进 → introduce引入，介绍"},{"word":"introduction","ipa":"/ˌɪntrəˈdʌkʃn/","pos":"n.","def":"介绍；引进；引言","sen":"The teacher gave a brief introduction to herself.","trans":"老师做了一个简要的自我介绍。","mne":"intro向内，入内 + duc引导 + tion名词后缀，表状态 → 引进的行为 → introduction介绍；引进"},{"word":"invade","ipa":"/ɪnˈveɪd/","pos":"v.","def":"侵略，侵入；渗透","sen":"The wolves invaded the sheep family.","trans":"狼群入侵了绵羊家族。","mne":"in进 + vad行走 + e → 走进去 → invade侵略"},{"word":"invaluable","ipa":"/ɪnˈvæljuəbl/","pos":"adj.","def":"非常宝贵的，极为有用的","sen":"The pirate found a chest full of invaluable treasures.","trans":"那个海盗找到了一个装满无价之宝的箱子。","mne":"in不 + valu价值 + able形容词后缀 → invaluable无法估价的"},{"word":"invariable","ipa":"/ɪnˈveriəbl/","pos":"adj.","def":"不变的","sen":"It is an invariable fact that the Moon moves around the Earth.","trans":"月球绕地球转是一个不变的事实。","mne":""},{"word":"invasion","ipa":"/ɪnˈveɪʒn/","pos":"n.","def":"侵略，入侵","sen":"An alien invasion would be a nightmare to human beings.","trans":"对于人类而言，外星人入侵将是一个噩梦。","mne":"in进 ＋ vas走 ＋ ion表名词 → 进入把人赶走 → invasion入侵，侵略"},{"word":"invent","ipa":"/ɪnˈvent/","pos":"v.","def":"发明；  v.创造","sen":"He invented a pair of special shoes which allowed people to walk on water.","trans":"他发明了一双特殊的鞋子，人们可以穿着它在水上行走。","mne":""},{"word":"invention","ipa":"/ɪnˈvenʃn/","pos":"n.","def":"发明，发明物","sen":"He's a wise person who has some great inventions.","trans":"睿智的他有很多杰出的发明。","mne":"invent发明，创造 + ion名词后缀 → invention发明"},{"word":"inventor","ipa":"/ɪnˈventər/ ","pos":"n.","def":"发明家；发明者","sen":"Thanks to the inventor of the telephone, we can talk anytime anywhere.","trans":"多亏了电话的发明者，我们才能随时随地地聊天。","mne":"invent发明 + or名词后缀，表示人 → inventor发明者"},{"word":"invest","ipa":"/ɪnˈvest/","pos":"v.","def":"投资；投入","sen":"He decided to invest in the real estate market.","trans":"他决定投资房地产市场。","mne":"in进 + vest衣服 → 把衣服中的钱放进事业中 → invest投资"},{"word":"investigate","ipa":"/ɪnˈvestɪɡeɪt/ ","pos":"v.","def":"调查，查明；研究","sen":"He's investigating the footprints, searching for clues to help solve the case.","trans":"他正在研究脚印，寻找线索来帮助破案。","mne":"in进入 + vestig脚印，踪迹 + ate动词后缀 → 根据踪迹调查 → 调查"},{"word":"investigation","ipa":"/ɪnˌvestɪˈɡeɪʃn/","pos":"n.","def":"调查，调查研究","sen":"The biologist conducted an investigation into the species of birds in the forest.","trans":"生物学家对这片森林中鸟的种类进行了调查。","mne":"in向内，进入 + vestig脚印，踪迹 + ation名词后缀，表示行为、状态、过程 → 调查研究"},{"word":"investment","ipa":"/ɪnˈvestmənt/","pos":"n.","def":"投资","sen":"Buying house property is a common type of investment nowadays.","trans":"购买房产是当今一种常见的投资方式。","mne":"invest投资 + ment表名词 → investment投资"},{"word":"invisible","ipa":"/ɪnˈvɪzəbl/ ","pos":"adj.","def":"无形的；看不见的，不为人注意的","sen":"A green clean environment is a form of invisible resource.","trans":"绿色、干净的环境是一种无形的资源。","mne":"in不 + vis看 + ible形容词后缀 → 看不见的，无形的"},{"word":"invitation","ipa":"/ˌɪnvɪˈteɪʃn/","pos":"n.","def":"邀请","sen":"I got an invitation to my friend's wedding.","trans":"我收到了朋友的婚礼邀请。","mne":"invit=invite邀请 + ation表行为 → 邀请"},{"word":"invite","ipa":"/ɪnˈvaɪt/","pos":"v.","def":"邀请；招致（读作/ɪnˈvaɪt/）","sen":"The house agent invited us in to have a look at the house.","trans":"房屋中介邀请我们进去看一下这栋房子。","mne":""},{"word":"involve","ipa":"/ɪnˈvɑːlv/","pos":"v.","def":"卷入，使参与；牵涉","sen":"I involved myself in working with them.","trans":"我加入他们一起工作。","mne":"in向内，进入 + volve=volv旋转，卷 → 使……卷入进去 → involve使卷入，牵涉"},{"word":"inward","ipa":"/ˈɪnwərd/","pos":"adv.","def":"向自己，向内心；  adj.向内的；内心的，精神的","sen":"Yoga may help you look inward to purify your mind.","trans":"瑜伽可以帮助你审视内心从而净化你的心灵。","mne":"in向内 + ward向…… → inward向内的"},{"word":"iron","ipa":"/ˈaɪərn/","pos":"v.","def":"熨烫（衣物）；  n.熨斗；铁；  adj.坚强的；铁的","sen":"I have an interview tomorrow, so I need to iron my shirt.","trans":"明天我有一个面试，所以要把衬衣熨一熨。","mne":""},{"word":"ironic","ipa":"/aɪˈrɑːnɪk/","pos":"adj.","def":"讽刺的","sen":"It's ironic that the bird is standing on the \"no birds\" sign.","trans":"讽刺的是，这只鸟正好站在“禁鸟”牌子上。","mne":"iron铁制的，残酷的 ＋ ic药 → ironic讽刺的"},{"word":"irrational","ipa":"/ɪˈræʃənl/","pos":"adj.","def":"无理性的，失去理智的；不合理的","sen":"It seems irrational to spend all your money on new shoes.","trans":"把所有钱都花在买新鞋子上是不理智的。","mne":"ir不，无 + rational合理的 → irrational不合理的"},{"word":"irregular","ipa":"/ɪˈreɡjələr/","pos":"adj.","def":"（形状、图案等）不规则的；不合法的，不道德的","sen":"The stone is in an irregular shape.","trans":"这块石头呈不规则形状。","mne":"ir不，无 ＋ regular规则的 → irregular不规则的"},{"word":"irrigation","ipa":"/ˌɪrɪˈɡeɪʃn/","pos":"n.","def":"灌溉","sen":"The farmers have a new irrigation system to water the fields.","trans":"农民们有了新的灌溉系统来浇灌农田。","mne":"irriga=irrigate灌溉 + tion表名词 → irrigation灌溉"},{"word":"island","ipa":"/ˈaɪlənd/","pos":"n.","def":"岛，岛屿","sen":"I would love to go on holiday to a small island in the middle of the sea.","trans":"我想去大海中间的小岛度假。","mne":""},{"word":"isolate","ipa":"/ˈaɪsəleɪt/","pos":"v.","def":"使隔离；使孤立","sen":"The old man built a huge fence to isolate himself from his neighbors.","trans":"老人筑起了一道巨大的篱笆，将自己与邻居隔绝开来。","mne":"isol岛 + ate表动词 → 使成为岛 → 孤立"},{"word":"issue","ipa":"/ˈɪʃuː/","pos":"n.","def":"问题；议题，话题；发行物；  v.发行；公布，发布","sen":"Food standards for fish are an important issue being talked about in the news.","trans":"鱼类食用标准成了最近新闻讨论的重要问题。","mne":"is=ire行走 + sue=ex出，向外  → 向外走  → issue发行；流出"},{"word":"it","ipa":"/ɪt/","pos":"pron.","def":"它","sen":"We can use \"it\" to refer to an animal or an object.","trans":"我们可以用它这个词来指代一个动物或一个物体。","mne":""},{"word":"item","ipa":"/ˈaɪtəm/","pos":"n.","def":"物品；一条，一则；条款，项目","sen":"Here are a variety of office items, such as a laptop and a telephone.","trans":"这儿有各种各样的办公用品，比如笔记本电脑和电话。","mne":""},{"word":"its","ipa":"/ɪts/","pos":"det.","def":"它的","sen":"Its eyes are very big.","trans":"它的眼睛很大。","mne":""},{"word":"itself","ipa":"/ɪtˈself/","pos":"pron.","def":"它自己","sen":"This cat cooks dinner for itself.","trans":"这只猫在给自己做晚餐。","mne":""},{"word":"jacket","ipa":"/ˈdʒækɪt/","pos":"n.","def":"短上衣，夹克衫","sen":"These four jackets are different in both color and style.","trans":"这四件夹克衫的颜色和风格都不同。","mne":""},{"word":"jam","ipa":"/dʒæm/","pos":"n.","def":"果酱；  v.（使）阻塞，使塞满","sen":"She spread some jam on the bread.","trans":"她给面包涂上了果酱。","mne":""},{"word":"january","ipa":"/ˈdʒænjueri/","pos":"n.","def":"一月","sen":"January always has 31 days.","trans":"一月份总是31天。","mne":""},{"word":"jazz","ipa":"/dʒæz/","pos":"n.","def":"爵士乐","sen":"Jazz music has become popular all over the world.","trans":"爵士乐在全球流行了。","mne":""},{"word":"jealous","ipa":"/ˈdʒeləs/","pos":"adj.","def":"妒忌的，妒羡的","sen":"The dog was jealous that his friend had ice cream.","trans":"这只狗嫉妒他的朋友有冰淇淋。","mne":"jeal=zeal热心 + ous形容词后缀 → 对…热心而得不到 → jealous妒忌的"},{"word":"jeans","ipa":"/dʒiːnz/","pos":"n.","def":"牛仔裤","sen":"I'm glad I put on a comfortable pair of jeans today.","trans":"今天我很高兴，因为我穿了一条舒服的牛仔裤。","mne":""},{"word":"jeep","ipa":"/dʒiːp/","pos":"n.","def":"吉普车","sen":"This man is driving a jeep with luggage strapped to the roof.","trans":"这个人开着一辆吉普车，行李捆在车顶上。","mne":""},{"word":"jet","ipa":"/dʒet/","pos":"n.","def":"喷气式飞机；  v.乘坐喷气式飞机","sen":"Most long-distance travel is done by jet plane.","trans":"大多数长途旅行会使用喷气式飞机。","mne":""},{"word":"jewel","ipa":"/ˈdʒuːəl/","pos":"n.","def":"宝石","sen":"This necklace is made of beautiful jewels.","trans":"这个项链是由漂亮的宝石做的。","mne":""},{"word":"jewellery","ipa":"/ˈdʒuːəlri/","pos":"n.","def":"（=jewelry）珠宝，镶嵌有宝石之饰物","sen":"The jewellery looks so pretty and fancy.","trans":"这些珠宝看起来既漂亮又精致。","mne":""},{"word":"jewelry","ipa":"/ˈdʒuːəlri/","pos":"n.","def":"珠宝","sen":"My husband gave me a box of jewelry as a wedding gift.","trans":"我的丈夫送给我一盒子珠宝当作结婚礼物。","mne":"jewel珠宝 + ry表名词 → jewelry珠宝；珠宝类"},{"word":"job","ipa":"/dʒɑːb/","pos":"n.","def":"工作","sen":"Tom could choose from any number of jobs: fireman, businessman, doctor, builder, or cook!","trans":"汤姆可以选择以下的工作：消防员、商人、医生、建筑工人或者厨师！","mne":""},{"word":"join","ipa":"/dʒɔɪn/","pos":"v.","def":"连接，结合","sen":"When they join the four pieces together, it will make a square.","trans":"当他们把这四块拼图拼起来时，就成了一个正方形。","mne":""},{"word":"joint","ipa":"/dʒɔɪnt/","pos":"n.","def":"关节；接合处；  adj.联合的，共同的；共有的","sen":"She felt a sudden pain in her knee joint.","trans":"她感到膝关节突然一阵疼痛。","mne":""},{"word":"joke","ipa":"/dʒoʊk/","pos":"n.","def":"笑话；玩笑；  v.讲笑话，开玩笑","sen":"His jokes always make people laugh.","trans":"他讲的笑话总是使人哈哈大笑。","mne":""},{"word":"journal","ipa":"/ˈdʒɜːrnl/","pos":"n.","def":"日志，日记；定期刊物，杂志","sen":"The man writes everything down in his journal.","trans":"这个人把发生的事情都记在日记里。","mne":"journ日期 + al名词后缀 → 带有日期的读本 → journal日期，杂志"},{"word":"journalist","ipa":"/ˈdʒɜːrnəlɪst/","pos":"n.","def":"新闻记者","sen":"The journalist is carrying a microphone and a camera.","trans":"这位记者带着一个话筒和一台相机。","mne":"journal报纸，刊物 + ist人 → 写新闻文章的人 → journalist新闻记者"},{"word":"journey","ipa":"/ˈdʒɜːrni/ ","pos":"n.","def":"（尤指长途）旅行，旅程；  v.旅行","sen":"The family is going on a journey soon.","trans":"这家人马上要去旅行。","mne":"journ日期 + ey表名词 → 按日期计算的行程 → journey旅行，旅程"},{"word":"joy","ipa":"/dʒɔɪ/","pos":"n.","def":"欢乐，高兴，喜悦，乐事","sen":"The father and his son played with joy.","trans":"这对父子在一起愉快地玩耍。","mne":""},{"word":"judge","ipa":"/dʒʌdʒ/","pos":"n.","def":"法官；裁判员；  v.判决，审判","sen":"The judge will decide whether you are guilty or not.","trans":"法官会决定你到底有没有罪。","mne":""},{"word":"judgement","ipa":"/ˈdʒʌdʒmənt/","pos":"n.","def":"判决","sen":"The court's judgement is that he is innocent.","trans":"法院的判决认为他是无罪的。","mne":"judge判断 + ment表名词 → judgement判断，判决"},{"word":"judgment","ipa":"/'dʒʌdʒmənt/","pos":"n.","def":"判断；判决，审判","sen":"Caring too much about other's words will affect your judgment.","trans":"太在意别人说的话会影响你的判断。","mne":"judg判断 + ment名词后缀 → judgment判断，判断力"},{"word":"juice","ipa":"/dʒuːs/","pos":"n.","def":"（水果等）汁，果汁","sen":"Fresh orange juice tastes better than the kind you can buy in a store.","trans":"新鲜的橙汁比商店买的好喝多了。","mne":""},{"word":"july","ipa":"/dʒuˈlaɪ/","pos":"n.","def":"七月","sen":"It's July 1st. The summer holiday begins today!","trans":"今天是7月1日，暑假从今天开始啦！","mne":""},{"word":"jump","ipa":"/dʒʌmp/","pos":"v.","def":"跳","sen":"She was so happy that she jumped for joy.","trans":"她高兴得都跳起来了。","mne":""},{"word":"june","ipa":"/dʒuːn/","pos":"n.","def":"六月","sen":"Children's Day falls on June 1st.","trans":"儿童节在六月一日。","mne":""},{"word":"jungle","ipa":"/ˈdʒʌŋɡl/","pos":"n.","def":"（热带）丛林","sen":"The little boy is exploring in the jungle.","trans":"这个小男孩正在丛林里探险。","mne":""},{"word":"junior","ipa":"/ˈdʒuːniər/","pos":"adj.","def":"（年级、地位、职位等）低的；年少的；  n.（高中或大学的）三年级学生；青少年","sen":"Students study more subjects when going to junior high school.","trans":"进入初中后，学生需要学习更多科目。","mne":""},{"word":"junk","ipa":"/dʒʌŋk/","pos":"n.","def":"垃圾，废旧物品","sen":"The area is full of junk that they no longer want.","trans":"这儿有很多他们不再需要的废品。","mne":""},{"word":"jury","ipa":"/ˈdʒʊri/","pos":"n.","def":"陪审团","sen":"The lawyer is showing the evidence to the jury.","trans":"律师正在向陪审团展示证据。","mne":"jur发誓，法律 + y名词后缀 → 发誓的人 → jury陪审团"},{"word":"just","ipa":"/dʒʌst/","pos":"adv.","def":"仅仅，只不过；恰好；  adj.公正的；正当的；合理的","sen":"She keeps telling herself: \"It's just a movie.\"","trans":"她一直在对自己说：“这只不过是一个电影。”","mne":""},{"word":"justice","ipa":"/ˈdʒʌstɪs/","pos":"n.","def":"公平，公正；审判；审判员","sen":"Everyone can seek justice in court.","trans":"每个人都可以在法庭上寻求公正。","mne":"just公正的 + ice表名词 → justice正义"},{"word":"justify","ipa":"/ˈʤʌstəˌfaɪ/","pos":"v.","def":"证明……正确或有理；辩解，辩护；证明合法，替...... 辩护","sen":"He is trying to justify his rude behavior.","trans":"他正试图为自己粗鲁的行为辩解。","mne":"just公正的 + ify使成为 → justify证明…正当"},{"word":"keen","ipa":"/kiːn/","pos":"adj.","def":"热切的；敏锐的；急迫的，强烈的","sen":"The little boy is always very keen on helping others.","trans":"这个小男孩总是非常热衷于帮助别人。","mne":""},{"word":"keep","ipa":"/kiːp/","pos":"v.","def":"继续；保持；保留","sen":"She keeps studying even at bedtime.","trans":"就算到睡觉时间了，她也继续学习。","mne":""},{"word":"kettle","ipa":"/ˈketl/ ","pos":"n.","def":"壶，水壶","sen":"I am boiling water in a kettle to make tea.","trans":"我把壶里的水烧开来泡茶。","mne":""},{"word":"key","ipa":"/kiː/","pos":"n.","def":"钥匙；键；  adj.关键的，主要的","sen":"The man in the white T-shirt is holding his keys.","trans":"穿白色T恤的男人拿着他的钥匙。","mne":""},{"word":"keyboard","ipa":"/ˈkiːbɔːrd/","pos":"n.","def":"键盘","sen":"I can't focus on my work with such a lovely keyboard.","trans":"这么可爱的键盘简直让我不能专心工作了。","mne":"key键 + board板子 → keyboard键盘"},{"word":"kick","ipa":"/kɪk/","pos":"v.","def":"踢；踢腿；  n.踢","sen":"The soccer player kicked the ball into the net. Goal!","trans":"这个足球运动员把球踢进了网里，得分了！","mne":""},{"word":"kid","ipa":"/kɪd/","pos":"n.","def":"小孩，儿童；  v.开玩笑，欺骗","sen":"Those kids are happily playing in the playground.","trans":"小孩子们正在操场上快乐地玩耍。","mne":""},{"word":"kill","ipa":"/kɪl/","pos":"v.","def":"杀死；导致死亡","sen":"They look like they are ready to kill someone.","trans":"他们看起来准备去杀人。","mne":""},{"word":"kilo","ipa":"/ˈkiːloʊ/","pos":"n.","def":"公斤（等于kilogram）；千克","sen":"How many kilos can you lift at the gym?","trans":"在健身房你能举起多少公斤？","mne":""},{"word":"kilogram","ipa":"/ˈkɪləɡræm/","pos":"n.","def":"千克；公斤；千克","sen":"One kilogram is equal to two catties.","trans":"一千克等于两斤。","mne":"kilo一千 + gram克 → kilogram一千克，公斤"},{"word":"kilogramme","ipa":"/'kɪləˌgræm/","pos":"n.","def":"公斤（=kilogram）","sen":"One kilogramme is about 2.2 pounds.","trans":"一公斤大约是2.2磅。","mne":"kilo千 + gramme克 → kilogramme公斤"},{"word":"kilometer","ipa":"/kɪˈlɑ:mɪtər/","pos":"n.","def":"千米，公里","sen":"The service area is roughly ten kilometers away from us.","trans":"服务区域离我们大约有10公里。","mne":"kilo一千 + meter米 → kilometer一千米，公里"},{"word":"kilometre","ipa":"/kɪˈlɑːmɪtər/","pos":"n.","def":"<英> 公里=<美> kilometer；千米","sen":"There is a bend in the road 2.5 kilometres from here.","trans":"离这里2.5公里的路上有一处弯道。","mne":"kilo一千 + metre米 → kilometre千米，公里"},{"word":"kind","ipa":"/kaɪnd/","pos":"adj.","def":"善良的，仁慈的，亲切的，和蔼的；  n.种类","sen":"She's a kind young woman who always helps others.","trans":"她是个善良的年轻人，总是帮助别人。","mne":""},{"word":"kindness","ipa":"/ˈkaɪndnəs/","pos":"n.","def":"好意；仁慈，善良","sen":"He always encourages others out of his kindness.","trans":"眼镜兄很友好，常常鼓励别人。","mne":"kind仁慈的 + ness表名词 → kindness仁慈"},{"word":"king","ipa":"/kɪŋ/","pos":"n.","def":"国王，君主","sen":"A king is just an ordinary man who is born into a royal family.","trans":"国王也就是个生于皇室的普通人。","mne":""},{"word":"kingdom","ipa":"/ˈkɪŋdəm/","pos":"n.","def":"王国","sen":"The lion rules the animal kingdom with the help of his friends.","trans":"狮子在朋友们的帮助下统治动物王国。","mne":"king国王 + dom状态或领域 → kingdom王国"},{"word":"kiss","ipa":"/kɪs/ ","pos":"v.","def":"吻，接吻；  n.吻","sen":"The man kissed his wife goodbye before heading off to war.","trans":"这个男人在出征前吻别了他的妻子。","mne":""},{"word":"kitchen","ipa":"/ˈkɪtʃɪn/","pos":"n.","def":"厨房","sen":"The kitchen is clean and modern.","trans":"这个厨房整洁而现代。","mne":""},{"word":"kite","ipa":"/kaɪt/","pos":"n.","def":"风筝","sen":"The little boy is running to fly his colorful kite.","trans":"这个小男孩正跑着放他的彩色风筝。","mne":""},{"word":"knee","ipa":"/niː/","pos":"n.","def":"膝盖","sen":"Coach, I hurt my knee! Do we have some ice to put on it?","trans":"教练，我伤到了膝盖！我们有冰块来敷吗？","mne":""},{"word":"kneel","ipa":"/niːl/","pos":"v.","def":"跪，跪下，跪着","sen":"He kneels in front of his master to show respect.","trans":"他跪在主人面前以示尊重。","mne":""},{"word":"knife","ipa":"/naɪf/","pos":"n.","def":"刀，匕首，餐刀(pl. knives)","sen":"A knife is used to cut things up.","trans":"刀是用来切东西的。","mne":""},{"word":"knock","ipa":"/nɑːk/","pos":"v.","def":"敲击；重击；  n.敲，敲门","sen":"Before entering, you should knock on the door.","trans":"进去之前，你应该先敲门。","mne":""},{"word":"knot","ipa":"/nɑːt/","pos":"n.","def":"绳结，结合，树的节；  v.打结","sen":"In the Stone Age people tied knots in ropes to count.","trans":"在石器时代人们曾在绳子上打结来计数。","mne":""},{"word":"know","ipa":"/noʊ/","pos":"v.","def":"知道","sen":"You always know the answer—give someone else a chance.","trans":"你总是知道答案，给其他人一个机会吧。","mne":""},{"word":"knowledge","ipa":"/ˈnɑːlɪdʒ/","pos":"n.","def":"知识，学识；知道，了解","sen":"Children are able to learn more quickly and retain more knowledge than adults.","trans":"相比大人，小孩子学得更快，记的知识更多。","mne":"know知道 + ledge框架 → knowledge知识"},{"word":"lab","ipa":"/læb/","pos":"n.","def":"实验室，研究室","sen":"This lab has lots of equipment for experiments.","trans":"这间实验室有许多实验仪器。","mne":""},{"word":"label","ipa":"/ˈleɪbl/","pos":"n.","def":"标签；  v.用标签标明","sen":"She is holding the label of the shirt.","trans":"她正拿着衬衫的标签。","mne":""},{"word":"labor","ipa":"/'leɪbər/","pos":"n.","def":"劳动，劳力；劳工；分娩；  v.劳动，苦干；分娩阵痛","sen":"This woman's labor in the fields is tireless.","trans":"这位妇女在地里不知疲倦地劳动。","mne":""},{"word":"labour","ipa":"/ˈleɪbər/","pos":"n.","def":"（体力）劳动；分娩；  v.劳动","sen":"Many people make a living by doing manual labour.","trans":"许多人靠从事繁重的劳动谋生。","mne":""},{"word":"lack","ipa":"/læk/","pos":"n.","def":"缺乏，不足；  v.缺乏","sen":"The area is in an extreme lack of water resources.","trans":"这个地区极度缺乏水资源。","mne":""},{"word":"ladder","ipa":"/ˈlædər/","pos":"n.","def":"梯子","sen":"I climbed up the ladder to change the light bulb.","trans":"我爬上梯子换灯泡。","mne":"lad倚靠 + der名词后缀 → 倚靠放置的东西 → ladder梯子"},{"word":"lady","ipa":"/ˈleɪdi/","pos":"n.","def":"女士，夫人","sen":"The young lady is smiling.","trans":"这位年轻女士在微笑。","mne":"la面包 + dy女仆 → 部落中做面包的女人 → lady女士"},{"word":"lag","ipa":"/læɡ/","pos":"v.","def":"落后，滞后；  n.（两事件之间的）时间间隔","sen":"He tends to lag during long races.","trans":"他在长距离赛跑时常常落后。","mne":""},{"word":"lake","ipa":"/leɪk/","pos":"n.","def":"湖泊","sen":"The lake lies in the pretty green valley.","trans":"这个湖位于美丽的绿色山谷中。","mne":""},{"word":"lamp","ipa":"/læmp/","pos":"n.","def":"灯，台灯","sen":"An oil lamp burned in darkness.","trans":"一盏油灯在黑暗中燃烧。","mne":""},{"word":"land","ipa":"/lænd/","pos":"n.","def":"陆地，土地；大地；  v.（使）降落；（使）着陆，降落","sen":"This land is covered with green grass.","trans":"这片土地上长满了青草。","mne":""},{"word":"landlady","ipa":"/ˈlændleɪdi/","pos":"n.","def":"女房东","sen":"I paid the rent to the landlady.","trans":"我把租金付给了女房东。","mne":"land土地 ＋ lady女士 → landlady女房东；女地主"},{"word":"landlord","ipa":"/ˈlændlɔːrd/","pos":"n.","def":"房东，地主，老板","sen":"A landlord receives rent from a leased property.","trans":"房东从出租的房产中收取租金。","mne":"land土地 + lord主 → landlord地主"},{"word":"lane","ipa":"/leɪn/","pos":"n.","def":"小径；巷；航道；行车道","sen":"There is a narrow bicycle lane beside the lake.","trans":"湖边有一条窄窄的自行车道。","mne":""},{"word":"language","ipa":"/ˈlæŋɡwɪdʒ/ ","pos":"n.","def":"语言，语言文字","sen":"People from different countries speak different languages.","trans":"不同国家的人讲不同的语言。","mne":"langu语言 + age表示状态、情况及其他 → language语言，语言课程"},{"word":"lap","ipa":"/læp/","pos":"n.","def":"（坐下时的）大腿部；（跑道的）一圈；  v.轻拍","sen":"A little cat is sleeping on the old lady's lap.","trans":"一只小猫在老太太的大腿上睡觉。","mne":""},{"word":"large","ipa":"/lɑːrdʒ/","pos":"adj.","def":"大的","sen":"She has a very large cup.","trans":"她有一个非常大的杯子。","mne":""},{"word":"largely","ipa":"/ˈlɑːrdʒli/","pos":"adv.","def":"大部分地，主要地；大量地","sen":"The users of this product are largely female.","trans":"这个产品的用户大多数为女性。","mne":"large大的 + ly...地 -> largely大部分地"},{"word":"laser","ipa":"/ˈleɪzər/","pos":"n.","def":"激光","sen":"His laser-like eyes saw right through me.","trans":"他激光般的双眼直接看穿了我。","mne":""},{"word":"last","ipa":"/læst/","pos":"adj.","def":"最后的，仅剩下的；  det.最近的；  adv.最后，终于；最近，上次；  v.持续，坚持","sen":"This is the last piece of the puzzle.","trans":"这是拼图缺失的最后一块。","mne":""},{"word":"late","ipa":"/leɪt/","pos":"adj.","def":"迟的，晚的；已故的，去世不久的；  adv.迟，晚","sen":"Oh, no! I'm late for work!","trans":"噢，不！我上班迟到了！","mne":""},{"word":"lately","ipa":"/ˈleɪtli/","pos":"adv.","def":"最近，不久前，近来","sen":"Lately, the temperature keeps going above 40°C.","trans":"最近的气温一直超过40摄氏度。","mne":"late最近的 + ly……地 → lately最近，不久前"},{"word":"later","ipa":"/ˈleɪtər/","pos":"adv.","def":"后来；  adj.接近末期的","sen":"I'll call you later after the meeting.","trans":"会议结束后我再打给你。","mne":""},{"word":"latest","ipa":"/ˈleɪtɪst/","pos":"adj.","def":"最近的，最新的","sen":"He is reading the latest news in the newspaper.","trans":"他正在阅读报纸上的最新消息。","mne":"lat=late最近 + est表示最高级“最……” → latest最近的，最新的"},{"word":"latter","ipa":"/ˈlætər/","pos":"n.","def":"后者；  adj.后面的，后者的","sen":"When asked which he would prefer, an apple or a pizza, the boy chose the latter.","trans":"当被问到更喜欢苹果还是比萨时，男孩选择了后者。","mne":"latt=late迟的，晚的 + er表名词 → 较迟的人  → latter后者"},{"word":"laugh","ipa":"/læf/","pos":"v.","def":"笑，发笑；  n.笑；笑声","sen":"She couldn't stop laughing because she had the love of the king.","trans":"咖妃一想到皇上对她的恩宠就笑得合不拢嘴。（这后宫佳丽三千，皇上就偏偏宠我一人~）","mne":""},{"word":"laughter","ipa":"/ˈlæftər/","pos":"n.","def":"笑，笑声","sen":"She burst into laughter while chatting with an old friend.","trans":"和老朋友聊天，她开怀大笑起来。","mne":""},{"word":"launch","ipa":"/lɔːntʃ/","pos":"v.","def":"发射；创办，开始从事；  n.（游艇、汽艇）下水","sen":"They launch the rocket into the sky.","trans":"他们向空中发射火箭。","mne":""},{"word":"laundry","ipa":"/ˈlɔːndri/","pos":"n.","def":"洗衣物，洗衣物的活；要洗的衣服","sen":"The young man is doing laundry at home.","trans":"这个年轻人正在家洗衣服。","mne":"laund=launder洗衣 + ry场地 → 洗衣房"},{"word":"lavatory","ipa":"/ˈlævətɔːri/","pos":"n.","def":"厕所，盥洗室；厕所","sen":"The lavatory in the middle is for the disabled.","trans":"中间的厕所是给残疾人用的。","mne":"lav洗，冲洗 + atory场所 → 冲洗的地方 → lavatory洗手间"},{"word":"law","ipa":"/lɔː/","pos":"n.","def":"法律，法学；规律，定理，惯例","sen":"Nobody is above the law.","trans":"没有人能凌驾于法律之上。","mne":""},{"word":"lawn","ipa":"/lɔːn/","pos":"n.","def":"草坪；草地","sen":"I often take care of my lawn to keep it nice and green.","trans":"我常常精心打理我的草坪，让它看起来美观而又葱郁。","mne":""},{"word":"lawyer","ipa":"/ˈlɔːjər/ ","pos":"n.","def":"律师","sen":"The group of lawyers are sitting in the courtroom.","trans":"这群律师正坐在法庭里。","mne":"law法律 + yer表示人 → lawyer律师，法律家"},{"word":"lay","ipa":"/leɪ/","pos":"v.","def":"搁放，放置；下蛋；躺（lie的过去式）；  adj.外行的","sen":"The mother carefully lays the baby on the bed.","trans":"妈妈小心地把婴儿放到床上。","mne":""},{"word":"layer","ipa":"/ˈleɪər/  ","pos":"n.","def":"层；层次","sen":"The cake is made up of many colorful layers.","trans":"这块蛋糕有五颜六色的许多层。","mne":"lay放置 + er → layer把…分层堆放，层次"},{"word":"layout","ipa":"/ˈleɪˌaʊt/","pos":"n.","def":"布局；（版面）设计","sen":"The picture shows the layout of the flat.","trans":"这张图展示了这套公寓的布局。","mne":"lay放置 + out在外部 → layout布局，安排"},{"word":"lazy","ipa":"/ˈleɪzi/","pos":"adj.","def":"懒惰的，懒散的","sen":"He is too lazy to go to school.","trans":"他太懒了，不想去上学。","mne":""},{"word":"lead","ipa":"/liːd/, /led/","pos":"v.","def":"领导，带领，率领；导致，使得；  n.领先地位；铅（读作/led/）","sen":"Few people lead; many people follow.","trans":"少数人领导；多数人跟随。","mne":""},{"word":"leader","ipa":"/ˈliːdər/","pos":"n.","def":"领导；领袖，指挥者","sen":"The workers are happy to follow and work for their team leader.","trans":"员工们乐意跟随他们的小组领导工作。","mne":"lead领导 + er人 → leader领袖，领导"},{"word":"leadership","ipa":"/ˈliːdərʃɪp/","pos":"n.","def":"领导，领导地位；领导能力","sen":"Under his leadership, they made it to the top!","trans":"他们在他的领导下登上了山顶！","mne":"lead 带领 + er 表人 + ship资格 → leadership领导"},{"word":"leading","ipa":"/ˈliːdɪŋ/","pos":"adj.","def":"首位的，居前的；卓著的，显赫的","sen":"The leading cyclist was starting to pull away from the rest.","trans":"领先的骑手渐渐甩开了其他人。","mne":"lead领导 + ing...的 → leading指导的；最主要的"},{"word":"leaf","ipa":"/liːf/","pos":"n.","def":"叶","sen":"The picture shows different kinds of leaves.","trans":"图片里展示了各种各样的树叶。","mne":""},{"word":"league","ipa":"/liːɡ/","pos":"n.","def":"社团；联盟；  v.使……结盟，与……联合","sen":"You are so good! You should join our soccer league!","trans":"你很厉害！你应该加入我们的足球社团！","mne":""},{"word":"leak","ipa":"/liːk/","pos":"v.","def":"漏；泄露；  n.漏洞","sen":"The pipe leaks and the water flows everywhere.","trans":"水管漏水，水流得到处都是。","mne":""},{"word":"lean","ipa":"/liːn/","pos":"v.","def":"倾斜；依赖；倚靠；  adj.萧条的，不景气的","sen":"These two men are leaning forward.","trans":"这两个男人的身体向前倾斜着。","mne":""},{"word":"leap","ipa":"/liːp/","pos":"v.","def":"跳跃，跃过；  n.跳跃","sen":"He leaped over the really big gap between the buildings.","trans":"展博跃过了两栋楼之间的间隙。","mne":""},{"word":"learn","ipa":"/lɜːrn/","pos":"v.","def":"学习，学会；得知","sen":"I learn more from the books in the library than I do in school.","trans":"我从图书馆的书上学到的比在学校学到的多。","mne":""},{"word":"learned","ipa":"/ˈlɜːrnɪd/, /lɜːrnd/","pos":"adj.","def":"有学问的","sen":"This dog is very well learned. He can even read books!","trans":"这只狗很有学问，它甚至会看书。","mne":"learn学习 + ed形容词后缀 → learned有学问的"},{"word":"learner","ipa":"/ˈlɜːrnər/","pos":"n.","def":"学习者","sen":"This woman is a language learner—she loves to learn languages!","trans":"这个女人是个语言学习者——她喜欢学习语言！","mne":""},{"word":"learning","ipa":"/ˈlɜːrnɪŋ/","pos":"n.","def":"学习","sen":"Mom often helps me with my learning.","trans":"妈妈经常在学习上给我帮助。","mne":"learn学习 + ing行业，状态，行为 → learning学问"},{"word":"lease","ipa":"/liːs/","pos":"v.","def":"出租；  n.租约","sen":"He leased a car for his road trip.","trans":"他为公路旅行租了一辆车。","mne":""},{"word":"least","ipa":"/liːst/","pos":"adj.","def":"【数】最小的，最少的；  adv.最少地，最小地；  n.最小，最少量","sen":"1 is the least in these three numbers.","trans":"这三个数中1是最小的数字。","mne":""},{"word":"leather","ipa":"/ˈleðər/","pos":"n.","def":"皮革","sen":"The sofa and pillow are covered in real leather.","trans":"沙发和枕头都是真皮做的。","mne":""},{"word":"leave","ipa":"/liːv/","pos":"v.","def":"留下；离开；  n.休假","sen":"There was some trash left in the stadium after the match.","trans":"比赛结束后，体育场内留下了一些垃圾。","mne":""},{"word":"lecture","ipa":"/ˈlektʃər/","pos":"n.","def":"演讲；讲课；  v.演讲；讲课；教训","sen":"He gave a lecture in front of many people.","trans":"他在很多人面前发表了演讲。","mne":"lect讲，读 + ure名词后缀 → 公开讲说 → lecture讲课；讲座"},{"word":"left","ipa":"/left/","pos":"v.","def":"离开（leave的过去式和过去分词）；  n.左边；  adj.左边的；  adv.在左边","sen":"My girlfriend left and went back to her job in another city.","trans":"我的女朋友离开了，回到另一个城市工作。","mne":""},{"word":"leg","ipa":"/leɡ/","pos":"n.","def":"腿，腿部","sen":"This App can make the dog's legs look longer.","trans":"这款应用能让狗狗的腿看起来更长。","mne":""},{"word":"legal","ipa":"/ˈliːɡl/","pos":"adj.","def":"合法的，法定的，法律的","sen":"Now I have my driver's license; it's legal for me to drive on the road.","trans":"我现在有驾照了，可以合法上路了。","mne":"leg法律 + al形容词后缀 → legal法律的"},{"word":"legend","ipa":"/ˈledʒənd/ ","pos":"n.","def":"传说，神话；传奇故事（或人物）","sen":"This film reimagines the legend of Ne Zha with a fresh perspective.","trans":"这部影片以全新视角重塑了哪吒的传奇故事。","mne":"leg讲，读 + end表名词 → 讲出的东西 → 传奇故事；引申为地图的图例"},{"word":"legitimacy","ipa":"/lɪˈdʒɪtɪməsi/","pos":"n.","def":"可信度；合法性；合理","sen":"No one doubts the legitimacy of fishing here.","trans":"没人怀疑在这儿钓鱼的合法性。","mne":""},{"word":"legitimate","ipa":"/ lɪˈʤɪtəmət /","pos":"adj.","def":"【财】合法的，正当的；  v.合法","sen":"Placement is the initial disposal of the proceeds of criminal activity into apparently legitimate business activity or property.","trans":"安置是将犯罪活动的收益最初处置为表面上合法的商业活动或财产。","mne":"legiti=law法律 + mate 表动词 → legitimate使合法"},{"word":"leisure","ipa":"/ˈliːʒər/","pos":"n.","def":"闲暇，休闲","sen":"In their leisure time, they like to play board games to relax themselves.","trans":"闲暇时候，她们喜欢玩棋类游戏来放松自己。","mne":""},{"word":"lend","ipa":"/lend/","pos":"v.","def":"借给（某人钱或东西）；借出；（银行）贷（款）","sen":"She lends her classmate a pen.","trans":"她借给她同学一支钢笔。","mne":""},{"word":"length","ipa":"/leŋθ/ ","pos":"n.","def":"长度","sen":"The ruler is 15 cm in length.","trans":"这把尺子长15厘米。","mne":"leng长 + th名词后缀 → length长度"},{"word":"lens","ipa":"/lenz/","pos":"n.","def":"透镜；镜片","sen":"A magnifying glass uses a convex lens.","trans":"放大镜使用凸透镜。","mne":""},{"word":"less","ipa":"/les/","pos":"adv.","def":"更少地；  n.较少数，较少量；  adj.更小的","sen":"When you get older, it is very likely you are less hairy.","trans":"当你年纪变大，很可能你的头发会变少。","mne":""},{"word":"lesson","ipa":"/ˈlesn/","pos":"n.","def":"课程；教训，经验","sen":"We have an English lesson today.","trans":"我们今天有一节英语课。","mne":""},{"word":"lest","ipa":"/lest/","pos":"conj.","def":"惟恐；以免；担心","sen":"She set many alarms the previous night, lest she be late again.","trans":"她睡前设了超多闹钟，以免再次迟到。","mne":"les=less更少的 + t=the → the less that比...少 → lest唯恐，以免"},{"word":"let","ipa":"/let/","pos":"v.","def":"让；允许；出租","sen":"Let me clean the classroom.","trans":"让我来打扫教室吧。","mne":""},{"word":"letter","ipa":"/ˈletər/","pos":"n.","def":"信；字母","sen":"I love getting letters in the mailbox.","trans":"我喜欢在邮箱里收到信。","mne":""},{"word":"level","ipa":"/ˈlevl/","pos":"n.","def":"水平，标准，等级；  v.瞄准；  adj.等高的；平坦的","sen":"Players are separated into three levels in this game.","trans":"玩家们在这个游戏中被分为三个等级。","mne":""},{"word":"liable","ipa":"/ˈlaɪəbl/","pos":"adj.","def":"（for）有责任的；（to）会……的，有……倾向的","sen":"You committed the crime, and now you're liable for the consequences!","trans":"你犯了罪，所以现在你要对后果负责。","mne":"lia捆绑，捆扎 + ble形容词后缀 → 与...绑定的 → liable有责任的，有可能的"},{"word":"liberal","ipa":"/ˈlɪbərəl/","pos":"adj.","def":"心胸宽阔的；自由主义的；慷慨的；  n.自由主义者","sen":"She has a liberal attitude toward different cultures.","trans":"她对不同文化持有心胸宽广的态度。","mne":"liber自由 + al形容词后缀 → liberal自由的"},{"word":"liberate","ipa":"/ˈlɪbəreɪt/","pos":"v.","def":"解放，释放","sen":"She felt her heart liberated together with the birds.","trans":"她感到自己的心随着鸟儿一起解放了。","mne":"liber自由 + ate动词后缀 → 使…自由 → liberate解放，释放"},{"word":"liberation","ipa":"/ˌlɪbəˈreɪʃn/","pos":"n.","def":"解放","sen":"The liberation of Paris marked a turning point in World War II.","trans":"巴黎的解放标志着二战的一个转折点。","mne":"liber自由 + ation名词后缀 → 使自由 → liberation解放；释放"},{"word":"liberty","ipa":"/ˈlɪbərti/","pos":"n.","def":"自由","sen":"The bird flew from the cage and got liberty.","trans":"这只鸟飞出了鸟笼，得到了自由。","mne":"liber自由的 + ty表名词 → liberty自由"},{"word":"librarian","ipa":"/laɪˈbreriən/","pos":"n.","def":"图书馆馆长，图书管理员","sen":"The helpful librarian helped me find the books I needed.","trans":"那位热心的图书管理员帮我找到了我需要的书。","mne":"libr书 + arian表示人 → 图书馆馆长；图书管理员"},{"word":"library","ipa":"/ˈlaɪˌbreri/","pos":"n.","def":"图书馆，藏书室","sen":"We can find many books in the library.","trans":"我们可以在图书馆找到很多书。","mne":"libr表示书 + ary构成名词，表示与...有关的地方 → library图书馆"},{"word":"licence","ipa":"/ˈlaɪsns/","pos":"n.","def":"许可证，执照","sen":"See! I told you I have a driving licence!","trans":"看吧！我都跟你说了我有驾照的！","mne":"licen=allow允许 + ce → licence特许，许可证"},{"word":"license","ipa":"/ˈlaɪsns/","pos":"n.","def":"执照；许可证；  v.发许可证；发执照","sen":"You need a driving license before you can drive on the road.","trans":"开车上路前，你要先有驾照。","mne":"licen=allow允许 + se表名词 → license批准，许可"},{"word":"lie","ipa":"/laɪ/","pos":"v.","def":"躺，平卧；撒谎；欺骗；  n.谎话，谎言","sen":"She lies down on the sofa, and takes a short break from her work.","trans":"她放下工作，躺在沙发上休息一会儿。","mne":""},{"word":"life","ipa":"/laɪf/","pos":"n.","def":"生活，生存；生命；一生，人生","sen":"My life changes a lot after having a baby.","trans":"有了孩子后，我的生活改变了很多。","mne":""},{"word":"lifetime","ipa":"/ˈlaɪftaɪm/","pos":"n.","def":"一生，终生，寿命","sen":"They have been friends for the whole lifetime.","trans":"她们是一辈子的好朋友。","mne":"life生命 + time时间 → lifetime一生"},{"word":"lift","ipa":"/lɪft/","pos":"v.","def":"（使）升起，举起；  n.免费搭车；<英>电梯","sen":"She lifted the heavy box with both hands.","trans":"她用双手举起那个沉重的箱子。","mne":""},{"word":"light","ipa":"/laɪt/","pos":"v.","def":"点火，照亮；  n.光亮；灯；  adj.明亮的；浅色的；轻的","sen":"She is lighting a candle.","trans":"她正在点蜡烛。","mne":" "},{"word":"lightning","ipa":"/ˈlaɪtnɪŋ/","pos":"n.","def":"闪电","sen":"Oh my God! A bolt of lightning is striking my house.","trans":"我的天哪！一道闪电击中了我的房子。","mne":"light光 + ning……的 → lightning闪电；闪电般的，快速的"},{"word":"like","ipa":"/laɪk/","pos":"v.","def":"喜欢；  prep.像","sen":"These two girls like to sing.","trans":"这两个女孩喜欢唱歌。","mne":""},{"word":"likely","ipa":"/ˈlaɪkli/","pos":"adj.","def":"有可能的","sen":"If you see dark clouds, it's likely that it will rain.","trans":"如果你看到乌云，可能会下雨。","mne":"like可能 + ly……的/地 → likely可能的，很可能"},{"word":"likewise","ipa":"/ˈlaɪkwaɪz/","pos":"adv.","def":"同样地，此外","sen":"The big man hates the small man; likewise, the small man hates the big man.","trans":"这个大个子讨厌这个小个子。同样地，这个小个子也讨厌这个大个子。","mne":"like相像 + wise方向，状态 → likewise同样地"},{"word":"limb","ipa":"/lɪm/","pos":"n.","def":"肢体；树枝","sen":"She lost a limb from an illness, but she can still run!","trans":"她因为疾病失去了一条腿，但她还可以跑步。","mne":""},{"word":"lime","ipa":"/laɪm/","pos":"n.","def":"石灰，氧化钙；酸橙","sen":"Acidity in soil can be neutralized by spreading lime on it.","trans":"土壤的酸性可以通过在它上面撒石灰来中和。","mne":""},{"word":"limit","ipa":"/ˈlɪmɪt/","pos":"n.","def":"限制；  v.限制","sen":"The car should follow the speed limit.","trans":"汽车应该按限速行驶。","mne":"lim门槛，限制 + it名词后缀 → limit限制"},{"word":"limitation","ipa":"/ˌlɪmɪˈteɪʃn/","pos":"n.","def":"限制，局限性","sen":"There's a limitation on what it can see.","trans":"它的视野被限制了。","mne":"limit限制 + ation名词后缀 → limitation限制"},{"word":"limited","ipa":"/ˈlɪmɪtɪd/ ","pos":"adj.","def":"有限的；  v.受限制的","sen":"On this diet, you can only eat a very limited amount of food.","trans":"在这项饮食计划中，你只能吃一点点食物。","mne":"lim门槛，限制 + it放出 + ed形容词后缀 → 放出限制 → limited有限的"},{"word":"line","ipa":"/laɪn/","pos":"n.","def":"线，线条；路线；行","sen":"There is a yellow line in the middle of the road.","trans":"道路中间有条黄线。","mne":""},{"word":"link","ipa":"/lɪŋk/","pos":"n.","def":"链接；  v.连接；联系；把……连接起来","sen":"Click the link and buy the backpack from this online store.","trans":"点击链接来这个线上商城买个双肩包吧。","mne":""},{"word":"lion","ipa":"/ˈlaɪən/","pos":"n.","def":"狮子","sen":"The lion is standing proudly, facing the sun.","trans":"这头狮子面向太阳骄傲地站着。","mne":""},{"word":"lip","ipa":"/lɪp/","pos":"n.","def":"嘴唇，唇状物；边沿；  v.接吻；说话；拍打","sen":"Her lips are the most beautiful part of her face.","trans":"她的嘴唇是她脸上最漂亮的部位。","mne":""},{"word":"liquid","ipa":"/ˈlɪkwɪd/","pos":"n.","def":"液体，液态物；  adj.液体的，液态的","sen":"Liquid, like water, can flow freely.","trans":"液体，比如说水，可以自由地流动。","mne":"liqu湿 + id表形容词 → liquid流体的，液态的"},{"word":"liquor","ipa":"/ˈlɪkər/","pos":"n.","def":"酒","sen":"This bar sells a wide variety of liquor.","trans":"这个酒吧出售各式各样的酒。","mne":"liqu=liquid液体 + or表名词 → liquor酒；酒精饮料"},{"word":"list","ipa":"/lɪst/","pos":"n.","def":"【计】列表；名单","sen":"A 'list' is a data structure that can store a collection of items, and supports adding and removing items.","trans":"“列表”是一种数据结构，可以存储一组项目，并支持添加和删除项目。","mne":""},{"word":"listen","ipa":"/ˈlɪsn/","pos":"v.","def":"听话","sen":"Listen to what I'm saying, please.","trans":"请听我说的话。","mne":"list听 + en动词后缀 → listen听，倾听"},{"word":"liter","ipa":"/ˈliːtər/","pos":"n.","def":"升，公升","sen":"This bottle can be filled with 2 liters of Coke.","trans":"这个瓶子可以装两升可乐。","mne":""},{"word":"literacy","ipa":"/ˈlɪtərəsi/","pos":"n.","def":"识字；读写能力；有文化","sen":"John has developed literacy and numeracy skills by self-learning.","trans":"通过自学，约翰已经能够识字和算数了。","mne":"liter文字,字母 + acy表名词 → 认字，有文化"},{"word":"literal","ipa":"/ˈlɪtərəl/","pos":"adj.","def":"字面上的","sen":"In contracts all word meanings are literal, whereas in literature they can be figurative.","trans":"合同中所有文字都是字面意思，然而在文学中它们可能有比喻意义。","mne":"liter文字，字母 + al形容词后缀 → literal文字上的，字面上的"},{"word":"literally","ipa":"/ˈlɪtərəli/","pos":"adv.","def":"字面上；逐字地；确实地","sen":"He translated the sentence literally.","trans":"他逐字逐句地翻译。","mne":"literal字面的，原文的 + ly副词后缀 → literally逐字地"},{"word":"literary","ipa":"/ˈlɪtəreri/","pos":"adj.","def":"文学的，文学上的","sen":"She put many famous literary books on her bookshelf.","trans":"她在书架上放了很多文学名著。","mne":"liter文字，字母 + ary形容词后缀 → literary文学的"},{"word":"literature","ipa":"/ˈlɪtrətʃər/","pos":"n.","def":"文学；文学作品","sen":"These four books are the classics of Chinese literature.","trans":"这四本书是中国文学的经典。","mne":"litera=letter文字，字母 + ture状态 → 文字状态 → literature文学"},{"word":"litre","ipa":"/ˈliːtər/","pos":"n.","def":"（=liter）升【容量单位】","sen":"The bottle contains a litre of milk.","trans":"这个瓶子装了一升牛奶。","mne":""},{"word":"little","ipa":"/ˈlɪtl/","pos":"adj.","def":"小的；少的","sen":"This little house is even smaller than my thumb.","trans":"这座小房子还没有我的拇指大。","mne":"lit小的 + tle形容词后缀 → little小的"},{"word":"live","ipa":"/lɪv/, /laɪv/","pos":"v.","def":"生活；居住（读作 /lɪv/）；活着，生存；  adj.现场的（读作 /laɪv/）","sen":"Fish can't live without water.","trans":"没了水，鱼儿无法存活。","mne":""},{"word":"lively","ipa":"/ˈlaɪvli/","pos":"adj.","def":"富有活力的；活泼的；生机勃勃的；生动的","sen":"These lively children are jumping for joy.","trans":"这些充满活力的孩子快乐地蹦蹦跳跳。","mne":"live活 + ly表形容词 → lively活跃的"},{"word":"living","ipa":"/ˈlɪvɪŋ/","pos":"n.","def":"生活，生计；  adj.活的","sen":"He makes shoes for a living.","trans":"他靠制作鞋子为生。","mne":"liv生活 ＋ ing名词后缀 → living生活，生计"},{"word":"load","ipa":"/loʊd/","pos":"v.","def":"装载；输入，载入（数据或程序）；  n.负载，负荷","sen":"The worker is loading the goods into the truck.","trans":"这个工人正在将货物装进卡车。","mne":""},{"word":"loaf","ipa":"/loʊf/","pos":"n.","def":"一条（面包）；  v.虚度光阴","sen":"The loaf of bread has been cut into slices.","trans":"这条面包被切成了很多片。","mne":""},{"word":"loan","ipa":"/loʊn/","pos":"n.","def":"贷款；  v.借贷","sen":"He is applying for a loan so that he can afford to buy the house.","trans":"他正在申请一笔贷款，这样他就买得起房子了。","mne":""},{"word":"local","ipa":"/ˈloʊkəl/ ","pos":"adj.","def":"本地的，地方的；局域的","sen":"The local people have their own clothing and culture.","trans":"当地人有自己的服装和文化。","mne":"loc地方 + al形容词后缀 → local地方的，局部的"},{"word":"locate","ipa":"/ˈloʊkeɪt/","pos":"v.","def":"找出……的位置；使……坐落于，位于，处于；找出……的精确位置","sen":"We have located the robber; he's currently waiting by the river.","trans":"我们已经找到了劫匪的位置，他现在就在河边等着。","mne":"loc地方 + ate表动词 → 找到地方 → locate探明；查出"},{"word":"location","ipa":"/loʊˈkeɪʃn/","pos":"n.","def":"位置，地点","sen":"I found the location on the map.","trans":"我在地图上找到了这个位置。","mne":"loc地方 + ation行为、状态、过程 → location位置，场所"},{"word":"lock","ipa":"/lɑːk/","pos":"v.","def":"锁上；  n.锁","sen":"The door is locked, so we can't get in.","trans":"这扇门锁上了，所以我们进不去。","mne":""},{"word":"lodge","ipa":"/lɑːdʒ/","pos":"n.","def":"小屋，小舍；  v.存放，保管；正式提出","sen":"We stayed in a cozy wooden lodge at the foot of the snow-capped mountain.","trans":"我们住在雪山脚下的一座舒适木屋里。","mne":""},{"word":"log","ipa":"/lɔːɡ/","pos":"n.","def":"原木；航海日志；  v.伐木","sen":"The logs are put on top of each other.","trans":"这些原木被堆在一起。","mne":""},{"word":"logic","ipa":"/ˈlɑːdʒɪk/","pos":"n.","def":"逻辑，推理","sen":"Speaking with clear logic allows people to understand your ideas better.","trans":"讲话逻辑清晰能让人们更好地理解你的想法。","mne":"log说话 + ic名词后缀 → 说话的学问 → logic逻辑学"},{"word":"logical","ipa":"/ˈlɑːdʒɪkl/","pos":"adj.","def":"合乎逻辑的；合理的","sen":"Logical thinking requires a step-by-step thought process.","trans":"逻辑思维需要循序渐进的思维过程。","mne":"log说话 + ic表名词 + al形容词后缀 → logical符合逻辑的"},{"word":"lonely","ipa":"/ˈloʊnli/","pos":"adj.","def":"孤独的；荒凉的","sen":"The girl felt so lonely in this empty house.","trans":"女孩一个人在这空荡的房间里，觉得非常孤独。","mne":"lone孤独的 + ly…地 → lonely孤独的；荒凉的"},{"word":"long","ipa":"/lɔːŋ/","pos":"adj.","def":"长的；  adv.长久地，长期地；  v.渴望，极想","sen":"Her beautiful blonde hair is long and curly.","trans":"她的美丽金发又长又卷。","mne":""},{"word":"look","ipa":"/lʊk/","pos":"v.","def":"看","sen":"I looked at myself in the mirror before work.","trans":"上班前我照了照镜子。","mne":""},{"word":"loom","ipa":"/luːm/","pos":"n.","def":"织布机","sen":"The girl is operating the loom to weave the cloth.","trans":"这个女孩正在用织布机织布。","mne":""},{"word":"loose","ipa":"/luːs/","pos":"v.","def":"松开；  adj.（衣服等）宽松的；不牢固的","sen":"I loosed my tie after a long day in the office.","trans":"在办公室工作一天后，我松了松领带。","mne":""},{"word":"loosely","ipa":"/ˈluːsli/","pos":"adv.","def":"宽松地，松散地","sen":"The ripped jeans fit loosely around his waist.","trans":"破洞牛仔裤松松地围在他的腰上。","mne":"loose松的 ＋ ly...地 → loosely宽松地，松散地"},{"word":"loosen","ipa":"/ˈluːsn/","pos":"v.","def":"松开，解开","sen":"I loosen my tie after a long day in the office.","trans":"在办公室工作一天后，我松了松领带。","mne":"loos(e)宽松的 + en动词后缀：使变成 → loosen使松弛"},{"word":"lord","ipa":"/lɔːrd/","pos":"n.","def":"君主；上帝","sen":"The three people are lords of different lands.","trans":"他们三人（囧、乔弗里和龙妈）是不同国度的领主。","mne":""},{"word":"lorry","ipa":"/ˈlɔːri/","pos":"n.","def":"货车，卡车；运货汽车","sen":"All the stuff was carried in the lorry.","trans":"所有货物都搬上卡车了。","mne":""},{"word":"lose","ipa":"/luːz/","pos":"v.","def":"失去；遗失，丢失；（在竞争或比赛中）输掉","sen":"He is losing weight by running.","trans":"他正通过跑步来减肥。","mne":""},{"word":"loss","ipa":"/lɔːs/","pos":"n.","def":"【计】损失；亏损，损失","sen":"The model's loss value was extremely high, indicating a large discrepancy between the predictions and actual results.","trans":"模型的损失值非常高，这表明预测结果和实际结果之间存在很大的差距。","mne":""},{"word":"lot","ipa":"/lɑːt/","pos":"n.","def":"（某人的）生活状况，命运；  adv.（与形容词和副词连用）很；非常","sen":"The volunteers come to improve the lot of the poor in the community.","trans":"志愿者们来改善社区内穷人们的生活状况。","mne":""},{"word":"loud","ipa":"/laʊd/","pos":"adj.","def":"大声的，吵闹的；响亮的；  adv.大声地","sen":"Shut up! Your voice is too loud.","trans":"闭嘴！你太吵了。","mne":""},{"word":"loudly","ipa":"/ˈlaʊdli/","pos":"adv.","def":"大声地，响亮地；高声地","sen":"Her dad called her loudly for lunch.","trans":"她爸爸大声地叫她去吃午饭。","mne":""},{"word":"love","ipa":"/lʌv/","pos":"n.","def":"爱","sen":"You can't define the love between two people; you can only feel it.","trans":"你无法定义两人之间的爱，你只能去感受。","mne":""},{"word":"lovely","ipa":"/ˈlʌvli/","pos":"adj.","def":"美丽的，可爱的","sen":"The baby had lovely eyes.","trans":"宝宝有一双可爱的眼睛。","mne":"love爱 + ly表形容词 → lovely可爱的"},{"word":"low","ipa":"/loʊ/","pos":"adj.","def":"低的，矮的，少的","sen":"When temperatures are this low, it's best to just stay inside.","trans":"当气温这么低时，最好待在室内。","mne":""},{"word":"lower","ipa":"/ˈloʊər/","pos":"v.","def":"降低，减少；  adj.下方的，底部的","sen":"I need to lower the volume of the radio, or it will wake up the baby.","trans":"我得把收音机的声音调小一点，不然会把宝宝吵醒。","mne":"low低 + er比较级 → 使...更低 → lower降低，减少"},{"word":"loyal","ipa":"/ˈlɔɪəl/","pos":"adj.","def":"忠心的，忠诚的；（顾客）忠实的","sen":"Dogs are always loyal to their owners.","trans":"狗总是对它们的主人很忠心。","mne":"loy法律 + al表形容词 → loyal忠心的"},{"word":"loyalty","ipa":"/ˈlɔɪəlti/","pos":"n.","def":"忠诚，忠心","sen":"That dog's loyalty deserves recognition.","trans":"狗狗的忠诚应该得到赞扬。","mne":"loyal忠诚的 + ty名词后缀 → loyalty忠诚，忠心"},{"word":"luck","ipa":"/lʌk/","pos":"n.","def":"运气；好运，幸运","sen":"He kissed the lottery hoping for good luck.","trans":"他亲了一下彩票祈求好运。","mne":""},{"word":"lucky","ipa":"/ˈlʌki/ ","pos":"adj.","def":"幸运的；好运的","sen":"He is very lucky to win the jackpot in the lottery! ","trans":"他非常幸运地中了彩票大奖！","mne":"luck幸运 + y…的 → lucky幸运的；吉祥的"},{"word":"luggage","ipa":"/ˈlʌɡɪdʒ/","pos":"n.","def":"行李；衣箱","sen":"College students may bring a lot of luggage with them when they go home for vacation.","trans":"大学生放假回家可能会带很多行李。","mne":"lug拖，拽 + 双写g + age表名词 → luggage行李"},{"word":"lump","ipa":"/lʌmp/","pos":"n.","def":"肿块；团，块；  v.把……归并在一起；使成块","sen":"There is a lump on his neck.","trans":"他脖子上有一个肿块。","mne":""},{"word":"lunch","ipa":"/lʌntʃ/","pos":"n.","def":"午餐","sen":"When we make a big sale, our boss invites us all to lunch.","trans":"当我们做成一单大生意时，我们老板会请我们去吃午餐。","mne":""},{"word":"lung","ipa":"/lʌŋ/","pos":"n.","def":"肺","sen":"Lungs are the organs responsible for breathing.","trans":"肺是负责呼吸的器官。","mne":""},{"word":"luxury","ipa":"/ˈlʌkʃəri/","pos":"adj.","def":"奢侈的，豪华的；  n.奢侈品","sen":"This luxury car looks so expensive.","trans":"这辆豪华车看起来很贵。","mne":""},{"word":"machine","ipa":"/məˈʃiːn/ ","pos":"n.","def":"机器，机械装置","sen":"A machine can dig a hole much faster than a person.","trans":"机器挖洞比人要快得多。","mne":"mach机器 + ine表名词 → machine机器"},{"word":"machinery","ipa":"/məˈʃiːnəri/","pos":"n.","def":"机器，机关","sen":"The machinery in the factory is used to assemble automobiles.","trans":"这个工厂里的机器是用来装配汽车的。","mne":"machin机器 + ery表示场所、地点、工作处 → machinery机器，机关，结构"},{"word":"mad","ipa":"/mæd/","pos":"adj.","def":"精神错乱的；生气的，狂怒的","sen":"The scientist is like a mad man.","trans":"这个科学家就像一个疯子。","mne":""},{"word":"madam","ipa":"/ˈmædəm/","pos":"n.","def":"夫人；女士","sen":"Madam, is there anything I can get for you?","trans":"女士，有什么可以帮您么？","mne":""},{"word":"magazine","ipa":"/ˈmæɡəziːn/","pos":"n.","def":"杂志，期刊","sen":"The girl spent her afternoon reading a magazine.","trans":"这个女孩读着杂志度过了午后时光。","mne":""},{"word":"magic","ipa":"/ˈmædʒɪk/  ","pos":"adj.","def":"有魔力的，魔术的；  n.魔术，戏法","sen":"The man took the rabbit out from this magic hat.","trans":"这男人从这顶魔术帽中拎出了只兔子。","mne":"mag=mage魔术师 + ic…术 → magic魔术"},{"word":"magnet","ipa":"/ˈmæɡnət/","pos":"n.","def":"磁铁，吸铁石","sen":"Magnet can attract paper clips.","trans":"磁铁能吸起回形针。","mne":""},{"word":"magnetic","ipa":"/mæɡˈnetɪk/ ","pos":"adj.","def":"有磁性的；有吸引力的","sen":"The magnet attracts the iron balls because it is magnetic.","trans":"磁铁吸住了铁球，因为磁铁是有磁性的。","mne":"magnet磁石 + ic形容词，…的 → magnetic有磁性的"},{"word":"magnificent","ipa":"/mæɡˈnɪfɪsnt/","pos":"adj.","def":"宏伟的，壮丽的，极好的","sen":"They are some of the most magnificent landmarks in the world.","trans":"它们是世界上最宏伟的几处地标性建筑。","mne":"magn大 + ific的 + ent…的 → magnificent壮丽的，宏伟的"},{"word":"maid","ipa":"/meɪd/","pos":"n.","def":"女仆；少女，未婚女子","sen":"The maid is doing a great job of cleaning the house.","trans":"女仆正在做得很好的清洁工作。","mne":""},{"word":"mail","ipa":"/meɪl/","pos":"n.","def":"邮件，信件；  v. 邮寄","sen":"She is going to check her inbox for any new mail.","trans":"她准备查看邮箱是否有新邮件。","mne":""},{"word":"main","ipa":"/meɪn/","pos":"adj.","def":"主要的，最重要的","sen":"The main stream of this river leads to the sea.","trans":"这条河的干流通向大海。","mne":""},{"word":"mainland","ipa":"/ˈmeɪnlænd/","pos":"n.","def":"大陆","sen":"The mainland of this country is an island.","trans":"这个国家的大陆是一个岛屿。","mne":"main主要的 + land陆地 → mainland大陆"},{"word":"mainly","ipa":"/ˈmeɪnli/","pos":"adv.","def":"主要地，大体上；大部分地","sen":"He spends his money on many things, but mainly on food and drink.","trans":"他把钱花在很多东西上，但主要是饮食方面。","mne":""},{"word":"maintain","ipa":"/meɪnˈteɪn/","pos":"v.","def":"保持，维持；坚称，坚持认为","sen":"It's so hard to maintain this position for a long time!","trans":"保持这个动作这么久太难啦!","mne":"main手 + tain拿 → 用手拿住 → maintain维持"},{"word":"maintenance","ipa":"/ˈmeɪntənəns/","pos":"n.","def":"维修；维护；保持；保养","sen":"The boy is performing maintenance checks on his robot.","trans":"男孩正在检修他的机器人。","mne":"main手 + ten拿住 + ance表名词 → 用手拿住 → maintenance维持"},{"word":"major","ipa":"/ˈmeɪdʒər/","pos":"adj.","def":"主要的；较多的；  n.主修（科目）；成年人；陆军少校；  v.主修","sen":"A major cause of lung cancer is smoking.","trans":"导致肺癌的一个主要原因是吸烟。","mne":"maj大 + or...的 → major较大的，主要的"},{"word":"majority","ipa":"/məˈdʒɔːrəti/","pos":"n.","def":"大多数，大部分","sen":"The majority thinks it's a good plan, but I don't think so.","trans":"大多数人认为这是一个好的计划，但我不这么认为。","mne":"major主要的 + ity表名词 → majority大多数"},{"word":"make","ipa":"/meɪk/","pos":"v.","def":"做，制作，制造；使得，使……变得","sen":"Time to make pizza for lunch!","trans":"到做午餐披萨的时间了！","mne":""},{"word":"male","ipa":"/meɪl/","pos":"adj.","def":"男性的，雄性的；  n.男性，雄性","sen":"The male deer has big horns on its head.","trans":"雄鹿头上有大的鹿角。","mne":""},{"word":"mall","ipa":"/mɔːl/","pos":"n.","def":"购物商场","sen":"The mall is very big, and it has five floors.","trans":"这个商场很大，有五层楼。","mne":""},{"word":"man","ipa":"/mæn/","pos":"n.","def":"人","sen":"All men are born equal.","trans":"人人生而平等。","mne":""},{"word":"manage","ipa":"/ˈmænɪdʒ/","pos":"v.","def":"管理；设法做成；完成（困难的事）","sen":"He managed his time well to complete all of his tasks.","trans":"他将自己的时间管理得非常好，完成了他的所有任务。","mne":"man手工，亲手 + age → 动手操作 → manage管理"},{"word":"management","ipa":"/ˈmænɪdʒmənt/","pos":"n.","def":"管理者；经营，管理，处理","sen":"The management team is having a regular meeting.","trans":"管理部门正在开例行会议。","mne":"manage管理 + ment表名词 → management管理"},{"word":"manager","ipa":"/ˈmænɪdʒər/ ","pos":"n.","def":"经理，管理人","sen":"The manager has some employees under her.","trans":"这名经理手下管理着一些员工。","mne":"man手 + age表名词 + er表人 → 用手进行管理的人 → manager经理"},{"word":"mankind","ipa":"/mænˈkaɪnd/","pos":"n.","def":"人类；男人","sen":"Mankind's duty is to protect the Earth for future generations.","trans":"人类的责任是为后代保护地球。","mne":"man人 + kind 种类 → mankind人类"},{"word":"manner","ipa":"/ˈmænər/","pos":"n.","def":"（复数）礼仪，礼貌；方式，方法；态度，举止","sen":"It's bad manners to speak while you are eating.","trans":"一边吃饭一边说话是不礼貌的举止。","mne":""},{"word":"manual","ipa":"/ˈmænjuəl/","pos":"adj.","def":"手工的；手的；手动的；  n.手册；指南，说明书","sen":"He enjoys doing manual work in his garden on weekends.","trans":"他喜欢周末在花园里做手工活。","mne":"manu手 + al形容词后缀 → manual手工的；手册"},{"word":"manufacture","ipa":"/ˌmænjuˈfæktʃər/","pos":"v.","def":"（批量）生产，制造；编造，捏造；  n.制造业","sen":"This factory uses machines to manufacture goods.","trans":"这家工厂用机器制造产品。","mne":"manu手 + fact做，制作 + ure名词后缀 → 手做 → manufacture制造业（机器发明前用手做）"},{"word":"manufacturer","ipa":"/ˌmænjuˈfæktʃərər/","pos":"n.","def":"制造商","sen":"Our company is a large manufacturer of household goods.","trans":"我们公司是一家大型日用品制造商。","mne":"manufactur制造 + er名词后缀：人 → manufacturer制造商"},{"word":"many","ipa":"/ˈmeni/","pos":"adj.","def":"许多的，大量的","sen":"I've wrapped so many gifts for Christmas.","trans":"我把这么多圣诞节礼物都包好了。","mne":""},{"word":"map","ipa":"/mæp/","pos":"n.","def":"地图","sen":"We are going to mark the route of our family trip on the map.","trans":"我们要在地图上标出家庭旅行的路线。","mne":""},{"word":"march","ipa":"/mɑːrtʃ/","pos":"v.","def":"行军，前进；  v.使行军；  n.行军，游行示威","sen":"The music band is marching on the street for festival celebration.","trans":"为了庆祝节日，这支乐队正在街上游行。","mne":""},{"word":"margin","ipa":"/ˈmɑːrdʒən/","pos":"n.","def":"页边的空白，边缘；余地，备用的时间（或空间，金钱等）；（获胜者在时间或票数上领先的）幅度，差额，差数","sen":"I often make notes in the margin.","trans":"我经常在页边空白处做笔记。","mne":""},{"word":"marine","ipa":"/məˈriːn/  ","pos":"adj.","def":"海洋的；海军的","sen":"There're numerous forms of marine life in the sea.","trans":"海里生活着为数众多的海洋生物。","mne":"mar海洋 + ine的 → marine海的"},{"word":"mark","ipa":"/mɑːrk/","pos":"v.","def":"在……上做记号；打分数；  n.污点，痕迹；记号，标记；分数","sen":"I'm going to mark our meeting on the calendar.","trans":"我打算在日历上把我们开会的日子标记出来。","mne":""},{"word":"market","ipa":"/ˈmɑːrkɪt/","pos":"n.","def":"市场；商场；销路；行情","sen":"Market research helps businesses understand consumer preferences.","trans":"市场调研帮助企业了解消费者偏好。","mne":""},{"word":"marriage","ipa":"/ˈmærɪdʒ/","pos":"n.","def":"婚姻；结婚","sen":"After they exchanged rings, the couple entered into marriage.","trans":"交换戒指之后，这对新人迈入了婚姻。","mne":"marri=marry结婚 + age状态，总称 → marriage结婚"},{"word":"married","ipa":"/ˈmærid/","pos":"adj.","def":"已婚的，夫妇的","sen":"We're getting married today! We're so happy!","trans":"我们今天结婚，幸福极了！","mne":"marri=marry结婚 + ed已……的 → married已婚的"},{"word":"marry","ipa":"/ˈmæri/","pos":"v.","def":"结婚","sen":"They finally married. The story has a happy ending.","trans":"最终，他们结婚了。结局皆大欢喜。","mne":""},{"word":"marvellous","ipa":"/ˈmɑːrvələs/","pos":"adj.","def":"不可思议的，惊奇的，极好的，绝妙的","sen":"This theme park is a marvellous place for both adults and children.","trans":"这个主题公园极好，老少皆宜。","mne":"marvell奇迹的 + ous……的 → marvellous绝妙的；了不起的"},{"word":"marvelous","ipa":"/ˈmɑːrvələs/","pos":"adj.","def":"叹为观止的，令人惊奇的；极好的","sen":"\"It is the most marvelous fireworks show!\" the girl exclaimed.","trans":"“这是最叹为观止的烟花表演！”这个女孩惊叹道。","mne":"marvel奇迹 + ous……的 → marvelous奇迹般的；了不起的"},{"word":"marxism","ipa":"/ˈmɑːrksɪzəm/","pos":"n.","def":"马克思主义","sen":"Marxism and capitalism are very different economic ideas.","trans":"马克思主义和资本主义是两种非常不同的经济理论。","mne":""},{"word":"marxist","ipa":"/ˈmɑːrksɪst/","pos":"adj.","def":"马克思主义的；  n.马克思主义者","sen":"Last semester I took a class on Marxist economics.","trans":"上个学期我选了马克思主义经济学的课程。","mne":"Marx马克思 + ist……主义的 → Marxist马克思主义的"},{"word":"mask","ipa":"/mæsk/","pos":"n.","def":"面具；遮蔽物；伪装；  v.隐藏；掩盖，掩饰；伪装","sen":"His mask covers the lower half of his face.","trans":"他的面罩遮住了脸的下半部分。","mne":""},{"word":"mass","ipa":"/mæs/","pos":"n.","def":"大量，一堆；质量；团，块，堆；  v.聚集；  adj.大量的；大批的","sen":"A mass of people are waiting.","trans":"一大群人在等待。","mne":""},{"word":"massive","ipa":"/ˈmæsɪv/","pos":"adj.","def":"巨大的；大规模的","sen":"The massive statue is a popular tourist attraction in Sichuan province.","trans":"这座巨大的雕像是四川省有名的旅游景点。","mne":"mass大块，大团 + ive表形容词 → massive巨大的，大规模的"},{"word":"master","ipa":"/ˈmæstər/","pos":"n.","def":"主人；硕士；  v.精通","sen":"The dog and its master are close to each other.","trans":"这条狗和它的主人很亲密。","mne":""},{"word":"match","ipa":"/mætʃ/","pos":"n.","def":"比赛；火柴；  v.（使）相配，配对","sen":"No. 10 is a real fan-favorite who works tirelessly every match.","trans":"10号球员是球迷的最爱，每场比赛他都不知疲倦地踢球。","mne":""},{"word":"mate","ipa":"/meɪt/","pos":"n.","def":"配偶；朋友，伙伴","sen":"My mate and I can look at each other for a long time.","trans":"我的伴侣跟我可以互看彼此很久。","mne":""},{"word":"material","ipa":"/məˈtɪriəl/","pos":"n.","def":"材料，原料；  adj.物质的，客观存在的","sen":"She has prepared the cooking material for lunch.","trans":"她已经准备好了午餐的烹饪原料。","mne":"mater=mother母亲，起源 + ial → 各种物品的起源 → 原材料"},{"word":"math","ipa":"/mæθ/","pos":"n.","def":"数学","sen":"The teacher is writing math equations on the blackboard.","trans":"老师正在黑板上写一些数学方程式。","mne":""},{"word":"mathematical","ipa":"/ˌmæθəˈmætɪkl/","pos":"adj.","def":"数学的","sen":"She is good at solving mathematical puzzles.","trans":"她很擅长解答数学难题。","mne":"mathemat数学 + ic……的 + al……的 → mathematical数学的，数学上的"},{"word":"mathematics","ipa":"/ˌmæθəˈmætɪks/","pos":"n.","def":"（=maths）数学","sen":"She is solving a mathematics problem.","trans":"她正在解答一道数学题。","mne":"mathemat=mathematic数学的 + ics名词后缀 → mathematics数学"},{"word":"maths","ipa":"/mæθs/","pos":"n.","def":"数学","sen":"They are doing some maths questions.","trans":"他们正在做一些数学题。","mne":""},{"word":"matter","ipa":"/ˈmætər/","pos":"n.","def":"事情，问题；物质；  v.要紧","sen":"They're talking about the matter that happened last week.","trans":"他们正在谈论上周发生的那件事情。","mne":""},{"word":"mature","ipa":"/məˈtʃʊr/ ","pos":"adj.","def":"成熟的；到期的；明白事理的；  v.使成熟；  v.成熟","sen":"The lion is now mature enough to go hunting alone.","trans":"这头狮子现在已经成熟到可以独自捕猎了。","mne":""},{"word":"maximise","ipa":"/'mæksəmaɪz/","pos":"v.","def":"把...增加到最大限度","sen":"The company aims to maximise its profits this year.","trans":"公司今年的目标是使利润增加到最大限度。","mne":""},{"word":"maximize","ipa":"/ˈmæksɪmaɪz/","pos":"v.","def":"最大化，最大限度的利用","sen":"Doctors should maximize the use of available resources to improve patient care.","trans":"医生应最大限度地利用现有资源来提升患者护理质量。","mne":"maxi大 ＋ mize使 → maximize使最大化"},{"word":"maximum","ipa":"/ˈmæksɪməm/","pos":"n.","def":"最大值；最大限度；  adj.最大的","sen":"It will reach 300 km/h which is the maximum.","trans":"速度将达到最大值每小时300千米。","mne":"maxi=max大的 + mum表名词 → maximum最大的"},{"word":"may","ipa":"/meɪ/","pos":"n.","def":"五月","sen":"We like May, because we can have many days-off.","trans":"我们喜欢五月，因为可以有很多假期。","mne":""},{"word":"maybe","ipa":"/ˈmeɪbi/","pos":"adv.","def":"可能，大概，也许","sen":"She's thinking that maybe she's ready for a baby.","trans":"她在想，也许她已经准备好要一个孩子了。","mne":""},{"word":"mayor","ipa":"/ˈmeɪər/","pos":"n.","def":"市长","sen":"The mayor is giving a speech on the stage.","trans":"市长正在台上讲话。","mne":"may=maj大 + or人 → 大人 → mayor市长"},{"word":"me","ipa":"/miː/","pos":"pron.","def":"（宾格）我","sen":"Who is the little boy in the photo? It's me.","trans":"照片上的小男孩是谁？是我。","mne":""},{"word":"meal","ipa":"/miːl/","pos":"n.","def":"一餐，一顿饭","sen":"The family enjoyed a tasty meal.","trans":"这家人享受了一顿美餐。","mne":""},{"word":"mean","ipa":"/miːn/","pos":"adj.","def":"吝啬的；  v.表示，意思是，意味着；  n.平均值，中庸","sen":"He's too mean to share his snacks with me.","trans":"他太吝啬了，不肯把零食分给我吃。","mne":""},{"word":"meaning","ipa":"/ˈmiːnɪŋ/","pos":"n.","def":"意思，含义","sen":"This word has so many different meanings.","trans":"这个单词有很多不同的意思。","mne":"mean意思 + ing表示行为、状态、情况及其他 → meaning意义，意思"},{"word":"means","ipa":"/miːnz/","pos":"n.","def":"方法，手段","sen":"Students travel to school by many means, such as by bus or on foot.","trans":"学生去学校的方式有很多种，例如坐公交或者步行。","mne":""},{"word":"meantime","ipa":"/ˈmiːntaɪm/","pos":"n.","def":"同时；期间；  adv.在此期间","sen":"The movie starts in 10 minutes; in the meantime, let's get some popcorn.","trans":"电影还有十分钟才开场，在此期间我们先去买点爆米花吧。","mne":"mean平均 + time时间 → meantime当时，在那当中，同时"},{"word":"meanwhile","ipa":"/ˈmiːnwaɪl/","pos":"adv.","def":"同时，与此同时；  n.其间","sen":"The hare decided to take a rest; meanwhile, the tortoise kept moving.","trans":"兔子决定休息一下，与此同时，乌龟还在继续前进。","mne":"mean用意 + while同时 → meanwhile同时，当时"},{"word":"measure","ipa":"/ˈmeʒər/","pos":"v.","def":"量，测量；计量；估量；  n.措施，方法；计量标准；测量，尺寸","sen":"The boy is measuring the size of the turtle.","trans":"男孩正在测量这只乌龟的大小。","mne":"meas计量，测量 + ure名词后缀 → measure测量，测定"},{"word":"measurement","ipa":"/ˈmeʒərmənt/","pos":"n.","def":"衡量，测量；尺寸","sen":"The woman wanted to know her waist measurement.","trans":"这个女人想知道自己腰围。","mne":"measure计量，测量 + ment表名词 → measurement衡量，测量；尺寸"},{"word":"meat","ipa":"/miːt/","pos":"n.","def":"肉，肉类（“肉类”复数meats）","sen":"Vegetables are fine, but I prefer eating meat.","trans":"蔬菜是不错，但是我还是更喜欢吃肉。","mne":""},{"word":"mechanic","ipa":"/məˈkænɪk/","pos":"n.","def":"机械师，机械修理工","sen":"The mechanic is repairing something at the bottom of the car.","trans":"这个机修工在修理车底的某个部位。","mne":"mech机器 + an人 + ic人 → mechanic机械师"},{"word":"mechanical","ipa":"/məˈkænɪkl/","pos":"adj.","def":"机械的，机械学的，机械性的；机械似的，呆板的","sen":"We can use this mechanical claw to pick up dolls.","trans":"我们可以用这个机械爪来抓娃娃。","mne":"mechanic机械工，技工 + al形容词后缀 → 机械相关的 → mechanical机械的，机械学的"},{"word":"mechanics","ipa":"/məˈkænɪks/","pos":"n.","def":"力学；机械学","sen":"Mechanics is the science of movement and forces.","trans":"力学是一门与运动和力有关的学科。","mne":"mechan=machine机械 + ics学科 → mechanics机械学，力学"},{"word":"mechanism","ipa":"/ˈmekənɪzəm/","pos":"n.","def":"机械装置；机制，原理","sen":"A watch's mechanism is very complicated.","trans":"手表内部的机械装置是很复杂的。","mne":"mechanic机械的 + ism主义，思想 → mechanism机械装置"},{"word":"medal","ipa":"/ˈmedl/","pos":"n.","def":"奖牌，勋章","sen":"These gold medals are symbols of honor.","trans":"这些金牌是荣誉的象征。","mne":""},{"word":"media","ipa":"/ˈmiːdiə/","pos":"n.","def":"媒体（medium的复数形式）","sen":"These days we get information from all kinds of different media.","trans":"如今，我们从各种不同的媒体获取信息。","mne":""},{"word":"medical","ipa":"/ˈmedɪkl/","pos":"adj.","def":"医学的，医疗的","sen":"There is a lot of medical equipment in the operating room.","trans":"手术室里有很多医疗器材。","mne":"medic医师 + al...的 → medical医学的"},{"word":"medicine","ipa":"/ˈmedɪsn/","pos":"n.","def":"药；医学","sen":"He was given medicine from the doctor to help him cure his disease.","trans":"医生给了他一些药来治病。","mne":"medic医师＋ ine名词后缀 → 跟医师有关的 → medicine医学，内科学"},{"word":"medium","ipa":"/ˈmiːdiəm/","pos":"adj.","def":"中等的，中号的；适中的；  n.手段，方法；媒体","sen":"I'd like a medium-sized television.","trans":"我想要一台中等尺寸的电视机。","mne":"medi中间 + um表名词 → medium中间物，媒介"},{"word":"meet","ipa":"/miːt/","pos":"v.","def":"满足；遇见","sen":"This production chain ensures that the supply of milk meets the demands.","trans":"这条生产链保证了牛奶的供应满足需求。","mne":""},{"word":"meeting","ipa":"/ˈmiːtɪŋ/","pos":"n.","def":"会议；会面；会议","sen":"The business group is having a meeting.","trans":"那个商业团队正在开会。","mne":"meet开会 + ing名词后缀 → meeting聚集，会合"},{"word":"melon","ipa":"/ˈmelən/ ","pos":"n.","def":"瓜","sen":"They served different kinds of melons.","trans":"他们提供了不同种类的瓜。","mne":""},{"word":"melt","ipa":"/melt/","pos":"v.","def":"融化；熔化","sen":"Ice will melt and turn into water if it's hot enough.","trans":"如果温度足够高，冰就会融化变成水。","mne":"mel软 + t → 变软 → 融化"},{"word":"member","ipa":"/ˈmɛmbər/","pos":"n.","def":"【财】成员；会员","sen":"The criteria for team effectiveness are both fulfilment of task objectives and member satisfaction.","trans":"团队效率的标准既包括任务目标的完成情况，也包括成员的满意度。","mne":""},{"word":"memo","ipa":"/ˈmemoʊ/","pos":"n.","def":"备忘录","sen":"I put memos everywhere to remind me of things that I must do.","trans":"我把备忘录放得到处都是，以提醒自己必须做的事。","mne":""},{"word":"memorandum","ipa":"/ˌmeməˈrændəm/","pos":"n.","def":"便签，备忘录；【财】备忘录，便笺","sen":"Did you get the memorandum about the meeting tomorrow?","trans":"你拿到明天会议的便签了吗？","mne":"memor记忆 ＋ andum东西 → [帮助]记的东西 → memorandum备忘录"},{"word":"memorial","ipa":"/məˈmɔːriəl/","pos":"n.","def":"纪念物，纪念碑，纪念仪式；  adj.纪念的","sen":"The memorial of Confucius is built to remind us of his achievements.","trans":"修建孔子纪念碑是为了让我们记住他的成就。","mne":"memor记忆 + ial形容词后缀，…的 → memorial记忆的；纪念物，纪念日"},{"word":"memorise","ipa":"/'meməraɪz/","pos":"v.","def":"记住","sen":"We try to memorise our notes before an exam.","trans":"我们试图在考试前记住我们的笔记。","mne":""},{"word":"memorize","ipa":"/ˈmeməraɪz/","pos":"v.","def":"熟记，记忆，记住","sen":"The girl is memorizing words to prepare for the coming test.","trans":"为了准备即将到来的考试，这个女孩正在记单词。","mne":"memor记忆 + ize动词后缀 → 记住，熟记"},{"word":"memory","ipa":"/ˈmeməri/","pos":"n.","def":"回忆；记忆","sen":"We keep this love in a photograph. We made this memories for ourselves.","trans":"我们将爱存储在相片里，制造只属于我们的回忆。（Photograph - Ed Sheeran）","mne":"memor记忆 + y → memory记忆，记忆力"},{"word":"mend","ipa":"/mend/","pos":"v.","def":"修理，缝补；治愈；  n.痊愈；改进","sen":"The man is trying to mend the damaged roof.","trans":"这个男人正在尝试修补被损坏的屋顶。","mne":""},{"word":"mental","ipa":"/ˈmentl/","pos":"adj.","def":"精神的；心理的","sen":"He is seeing a doctor for his mental health.","trans":"他因精神健康问题正在看医生。","mne":"ment思考，神智 + al...的 → mental精神的"},{"word":"mention","ipa":"/ˈmenʃn/","pos":"v.","def":"提到，提及；  n.谈到，提及","sen":"She mentioned her child during their conversation.","trans":"她在谈话中提到了她的孩子。","mne":"ment思考，神智 + ion名词后缀 → 有思考 → mention想到，提到"},{"word":"menu","ipa":"/ˈmenjuː/","pos":"n.","def":"（尤指餐馆的）菜单","sen":"The boy is looking at the menu to choose which dessert to order.","trans":"这个小男孩在看着菜单，选择该点哪个甜品。","mne":""},{"word":"merchant","ipa":"/ˈmɜːrtʃənt/","pos":"n.","def":"商人","sen":"The fruit merchant gave me a good price on tomatoes.","trans":"水果商给我的西红柿价格很实惠。","mne":"merch交易 + ant表示人 → merchant商人"},{"word":"mercy","ipa":"/ˈmɜːrsi/","pos":"n.","def":"仁慈，怜悯","sen":"The farmer shows his mercy to the snake.","trans":"农夫向蛇展现了他的仁慈。","mne":""},{"word":"mere","ipa":"/mɪr/","pos":"adj.","def":"仅仅的；纯粹的","sen":"He was late by mere seconds, yet he was fined 200 yuan.","trans":"他迟到了仅仅几秒钟，就被罚了200元。","mne":""},{"word":"merely","ipa":"/ˈmɪrli/","pos":"adv.","def":"只是，仅仅，只不过","sen":"Don't worry. It's merely a minor injury.","trans":"别担心。只是一点轻伤。","mne":"mere仅仅 + ly……的 → adv.仅仅，只不过"},{"word":"merit","ipa":"/ˈmerɪt/","pos":"n.","def":"优点；价值；功绩；  v.值得；应得","sen":"A merit of this phone is that the excellent camera can clearly capture the moon.","trans":"这款手机的优点之一是它出色的拍照功能可以清晰地捕捉月亮的样子。","mne":""},{"word":"merry","ipa":"/ˈmeri/","pos":"adj.","def":"欢乐的，愉快的","sen":"I wish you a merry Christmas!","trans":"祝你圣诞快乐！","mne":""},{"word":"mess","ipa":"/mes/","pos":"n.","def":"凌乱，脏乱，杂乱；  v.弄脏，弄乱","sen":"The living room is in a mess after a party.","trans":"一场聚会后，客厅里乱糟糟的。","mne":""},{"word":"message","ipa":"/ˈmesɪdʒ/","pos":"n.","def":"【计】消息；消息，信息，留言；  v.发消息","sen":"I feel frustrated when I see error messages.","trans":"每次看到报错消息我都很难受。","mne":"mess送出 + age表名词 → 送出的信息 → message消息，信息"},{"word":"metal","ipa":"/ˈmetl/","pos":"n.","def":"金属，合金，金属制品","sen":"He crafted her a metal rose from old airplane parts.","trans":"他用旧飞机零件为她制作了一朵金属玫瑰。","mne":""},{"word":"meter","ipa":"/ˈmiːtər/","pos":"n.","def":"米（=metre）；公尺；计，表，仪表；  v.用仪表测量","sen":"The swimming pool is only one meter deep, so don't jump in.","trans":"这个游泳池只有一米深，所以别跳进去。","mne":""},{"word":"method","ipa":"/ˈmeθəd/","pos":"n.","def":"方法","sen":"Let me show you the methods to get curly hair.","trans":"让我来给你展示弄卷发的方法。","mne":""},{"word":"metre","ipa":"/ˈmiːtə/","pos":"n.","def":"【物】米；计量器，计量仪表","sen":"The speed of light is approximately 299,792 kilometres per second, or 299,792,458 metres per second.","trans":"光速大约是每秒299,792公里，或者每秒299,792,458米。","mne":"met测量 + re → 测量所用的单位 → metre米，公尺"},{"word":"metric","ipa":"/ˈmetrɪk/","pos":"adj.","def":"米制的，公制的","sen":"Centimeters are a main feature of the metric system.","trans":"厘米是公制系统的主要特征之一。","mne":"metr计量，测量 + ic形容词后缀 → metric公制的，米制的"},{"word":"microphone","ipa":"/ˈmaɪkrəfoʊn/","pos":"n.","def":"话筒，麦克风","sen":"The woman speaks with her microphone.","trans":"这位女士用麦克风讲话。","mne":"micro小 + phone声音 → 小声音变大声音 → microphone麦克风"},{"word":"microscope","ipa":"/ˈmaɪkrəskoʊp/","pos":"n.","def":"显微镜","sen":"I can see really tiny things through this microscope.","trans":"我可以用这台显微镜看到很小的东西。","mne":"micro微，小 + scope看 → 看小东西 → microscope显微镜"},{"word":"middle","ipa":"/ˈmɪdl/","pos":"n.","def":"中部，中间；  adj.中部的，中间的","sen":"This is my mom and my daughter, and that's me, in the middle.","trans":"这是我妈妈和我女儿，在中间的就是我。","mne":""},{"word":"midnight","ipa":"/ˈmɪdnaɪt/","pos":"n.","def":"子夜，午夜","sen":"When the clock shows 12 at night, it is midnight.","trans":"当时钟在晚上显示12点时，那便是午夜。","mne":""},{"word":"might","ipa":"/maɪt/","pos":"aux.","def":"或许；  v.可能，也许（may的过去式）；  n.力量，威力","sen":"I think it might rain later, so I should take an umbrella.","trans":"我想一会儿或许会下雨，所以我应该带把伞。","mne":""},{"word":"migration","ipa":"/maɪˈɡreɪʃn/ ","pos":"n.","def":"【计】（数据库）迁移；迁徙，迁移","sen":"The migration is used to create a new 'users' table with the specified columns.","trans":"迁移被用来创建一个新的'users'表，带有指定的列。","mne":"migr迁移 + ation表示行为、情况 → migration迁移；移民；移动"},{"word":"mild","ipa":"/maɪld/ ","pos":"adj.","def":"清淡的；轻微的","sen":"I would love a bowl of mild chicken soup right now.","trans":"我现在想要一碗清淡的鸡汤。","mne":""},{"word":"mile","ipa":"/maɪl/","pos":"n.","def":"英里","sen":"The road sign says the service station is 72 miles away.","trans":"路标指示离下一个服务区还有72英里。","mne":""},{"word":"military","ipa":"/ˈmɪləteri/","pos":"adj.","def":"军事的；  n.军队","sen":"University freshmen are required to participate in military training.","trans":"大学新生要参加军训。","mne":"milit兵 + ary……的 → military军人的，军队的"},{"word":"milk","ipa":"/mɪlk/","pos":"n.","def":"（牛或羊等的）奶；  v.挤奶","sen":"Drinking one glass of milk each day is good for your health.","trans":"每天喝一杯牛奶有益于你的健康。","mne":""},{"word":"mill","ipa":"/mɪl/","pos":"n.","def":"磨坊，碾磨机，制造厂；  v.碾，磨，（毫无目的地）乱转","sen":"It is a mill once used for corn flour production.","trans":"这是一个曾经用来生产玉米粉的磨坊。","mne":""},{"word":"millimeter","ipa":"/ˈmɪlimiːtər/","pos":"n.","def":"毫米","sen":"The thickness of a single coin is one millimeter.","trans":"一枚硬币的厚度是一毫米。","mne":"milli千，千分之一 + meter米 → millimeter千分之一米"},{"word":"millimetre","ipa":"/ˈmɪlimiːtər/","pos":"n.","def":"毫米（=millimeter）","sen":"10 millimetres is equivalent to 1 centimetre.","trans":"十毫米等于一厘米。","mne":""},{"word":"million","ipa":"/ˈmɪljən/","pos":"num.","def":"百万；  n.一百万","sen":"The businessman holds one million dollars in his arms.","trans":"这个商人怀里抱着一百万美元。","mne":""},{"word":"mind","ipa":"/maɪnd/","pos":"n.","def":"头脑，思想，心智；  v.介意","sen":"Here's a hard question for you: Are your mind and your brain the same thing?","trans":"问你一个难题：你的思想和你的头脑是同一个东西吗？","mne":""},{"word":"mindset","ipa":"/ˈmaɪndset/","pos":"n.","def":"思维模式；心态","sen":"People with a growth mindset believe that learning from failure can lead to future success.","trans":"有着成长型思维模式的人相信，从失败中学习可以通向未来的成功。","mne":""},{"word":"mine","ipa":"/maɪn/ ","pos":"n.","def":"矿，矿山；地雷；  v.开采，采矿","sen":"Will he find any gold in the mine?","trans":"他能在矿里找到金子吗？","mne":""},{"word":"mineral","ipa":"/ˈmɪnərəl/ ","pos":"adj.","def":"矿物的；  n.矿物，矿物质","sen":"We should drink more mineral water—it's good for our health.","trans":"我们应该多喝矿泉水，这对我们的健康有好处。","mne":""},{"word":"minimal","ipa":"/ˈmɪnɪməl/","pos":"adj.","def":"最小的；最低限度的","sen":"The damage caused by the criminal was minimal.","trans":"罪犯造成的损坏很小。","mne":"minim小 + al形容词后缀 → minimal最小的"},{"word":"minimum","ipa":"/ˈmɪnɪməm/","pos":"adj.","def":"最少的，最低（限度）的；  n.最低限度，最小量","sen":"In theory, the minimum temperature is minus 273.15 degrees Celsius.","trans":"理论上说，最低温度是零下273.15摄氏度。","mne":"minim小 + um名词后缀，表物 → minimum最小量"},{"word":"minister","ipa":"/ˈmɪnɪstər/","pos":"n.","def":"部长，大臣；牧师","sen":"The government minister is giving a speech.","trans":"政府部长在演讲。","mne":"mini小 + ster名词后缀，人 → 小人 → 古代大臣称自己是“小人” → minister部长，大臣"},{"word":"ministry","ipa":"/ˈmɪnɪstri/","pos":"n.","def":"（政府的）部，内阁；（全体）牧师","sen":"Governments have many different ministries, such as the Ministry of Health.","trans":"政府设有许多不同的部门，比如卫生部。","mne":"ministr=minister部长 + y表名词 → minister部长 + y表名词 → ministry（政府的）部"},{"word":"minor","ipa":"/ˈmaɪnər/ ","pos":"adj.","def":"较小的；次要的；轻微的；（音乐）小调的；  n.未成年人","sen":"It was just a minor injury.","trans":"这只是一个小伤。","mne":"min小 ＋ or表物 → minor较小的；较少的"},{"word":"minority","ipa":"/maɪˈnɔːrəti/","pos":"n.","def":"少数民族；未成年","sen":"The two ladies of an ethnic minority group wear colorful clothes.","trans":"这两位少数民族妇女穿着鲜艳的服饰。","mne":"minor小或少 + ity名词后缀 → 少的状态 → minority少数"},{"word":"minus","ipa":"/ˈmaɪnəs/","pos":"prep.","def":"减，减去；  adj.负的；  n.减号；负数；缺点","sen":"Seven minus one is six.","trans":"7减1等于6。","mne":"min小 + us用 → 变少 → minus减去"},{"word":"minute","ipa":"/ˈmɪnɪt/, /maɪˈnuːt/","pos":"n.","def":"分钟；片刻；  adj.微小的，极小的","sen":"It's going to be 12 o'clock in 5 minutes.","trans":"5分钟后就到12点。","mne":"min小 + ute名词或形容词后缀 → 小的 → minute一分钟；微小的"},{"word":"miracle","ipa":"/ˈmɪrəkl/ ","pos":"n.","def":"奇迹","sen":"This mystic light swirling over my hands is a miracle.","trans":"这束在我手掌间萦绕的神秘光线是一个奇迹。","mne":"mir惊奇 + acle物品，状态 → miracle奇迹"},{"word":"mirror","ipa":"/ˈmɪrər/","pos":"n.","def":"镜子；  v.反射，反映","sen":"The old woman is looking into the mirror.","trans":"这个老奶奶正在照镜子。","mne":"mirr惊奇，看 + or表名词 → 能看见自己而感到惊奇 → mirror镜子"},{"word":"miserable","ipa":"/ˈmɪzrəbl/","pos":"adj.","def":"痛苦的，悲惨的\t","sen":"The man feels tired and miserable.","trans":"这个男人感到疲倦和痛苦。","mne":"miser可怜 + able……的 → miserable可怜的"},{"word":"miserably","ipa":"/ˈmɪzrəbli/","pos":"adv.","def":"痛苦地；彻底地","sen":"He failed the exam and felt miserably disappointed.","trans":"他考试失利了，彻底地陷入了失望。","mne":""},{"word":"misery","ipa":"/ˈmɪzəri/","pos":"n.","def":"痛苦，悲惨，不幸","sen":"She is trapped in her misery.","trans":"她被自己的痛苦困住了。","mne":"miser可怜的 ＋ y表名词 → misery可怜，可悲"},{"word":"mislead","ipa":"/ˌmɪsˈliːd/","pos":"v.","def":"把……带错路，使误入歧途；误导，使误信，欺骗","sen":"The wrong map misleads him to the suburbs.","trans":"这张错误的地图使他误入郊区。","mne":"mis错误，坏 + lead领导 → mislead使误入岐途"},{"word":"miss","ipa":"/mɪs/","pos":"v.","def":"怀念，思念；错过；遗漏；  n.女士，小姐，年轻未婚女子","sen":"This little girl misses her father who is working in the city.","trans":"这个小女孩很想念在城里务工的爸爸。","mne":""},{"word":"missing","ipa":"/ˈmɪsɪŋ/","pos":"adj.","def":"失踪的；缺少的；缺失的","sen":"One of the puzzles is missing.","trans":"其中一个拼图丢失了。","mne":"miss消失，错过 + ing形容词或动名词后缀 → missing失踪的，缺少的"},{"word":"mission","ipa":"/ˈmɪʃən/","pos":"n.","def":"任务，使命；代表团，使团","sen":"The soldiers are carrying out the mission.","trans":"士兵们正在执行任务。","mne":"miss送，放出 + ion名词后缀 → 送出 → mission派遣"},{"word":"mist","ipa":"/mɪst/","pos":"n.","def":"薄雾","sen":"The forest is covered in mist.","trans":"这片森林被薄雾覆盖。","mne":""},{"word":"mistake","ipa":"/mɪˈsteɪk/","pos":"n.","def":"错误，过失；  v.误解，弄错","sen":"The little boy made a mistake in his math homework.","trans":"这个小男孩在数学作业中犯了一个错误。","mne":"mis错误，坏 + take拿 → 拿错 → mistake错误"},{"word":"misunderstand","ipa":"/ˌmɪsʌndərˈstænd/","pos":"v.","def":"误解，误会","sen":"She misunderstood the grocery seller's words.","trans":"她误解了商贩的话。","mne":"mis错误，坏 + understand理解 → misunderstand误解"},{"word":"misunderstanding","ipa":"/ˌmɪsʌndərˈstændɪŋ/","pos":"n.","def":"误解，误会，不和","sen":"His description showed a complete misunderstanding of this book.","trans":"他的描述表示他完全误解了这本书。","mne":"mis错误 ＋ under引申为in ＋ stand站 ＋ ing表名词 → mis错误 ＋ understand站在里面=理解 ＋ ing表名词 → misunderstanding误解"},{"word":"mix","ipa":"/mɪks/","pos":"v.","def":"混合；使结合；混淆；  n.结合；混合，混音","sen":"Candies of different flavors are mixed together.","trans":"不同口味的糖果混在了一起。","mne":""},{"word":"mixture","ipa":"/ˈmɪkstʃər/","pos":"n.","def":"混合；混合物，混合剂（或液）","sen":"This fruit salad is a great mixture of different fruits.","trans":"这份水果沙拉是一份含多种水果的大杂烩。","mne":"mix混合 + ture表名词 → mixture混合物"},{"word":"mobile","ipa":"/ˈməʊbl/","pos":"adj.","def":"可移动的，活动的；多变的","sen":"The professor will show you how to use the mobile phone.","trans":"这位教授会给你演示如何使用手机。","mne":"mob动 + ile能…的 → mobile活动的，可动的"},{"word":"mode","ipa":"/moʊd/","pos":"n.","def":"模式；方式；模式","sen":"The camera has many different modes.","trans":"这台照相机有很多种不同的拍摄模式。","mne":""},{"word":"model","ipa":"/ˈmɑːdl/","pos":"n.","def":"模型；模特；模范，榜样，典型；  v.当模特；（用黏土、木头等）做……的造型，塑造","sen":"The girl is looking at her model house happily.","trans":"女孩正开心地看着她的房子模型。","mne":""},{"word":"moderate","ipa":"/ˈmɑːdərət/","pos":"adj.","def":"中等的，适中的；温和的，稳健的；  v.使减轻，使缓和（读作/ˈmɑdərˌeɪt/）；  n.温和主义者；稳健的人","sen":"The yellow area indicates moderate power output.","trans":"黄色区域表示中等功率输出。","mne":"moder方式，模式，风度 + ate形容词后缀 → 做事有风度 → moderate适度的"},{"word":"modern","ipa":"/ˈmɑːdərn/ ","pos":"adj.","def":"当代的，现代的，现代化的；时髦的","sen":"Smart phones are common tools in modern life.","trans":"在现代生活中，智能手机是常用的工具。","mne":"mod采取适当措施，以某种方式 + ern形容词后缀 → modern现代的"},{"word":"modest","ipa":"/ˈmɑːdɪst/","pos":"adj.","def":"谦虚的；端庄的","sen":"These two businessmen may be rich, but they're still very modest.","trans":"这两位企业家也许富有，但他们仍然很谦虚。","mne":"mod模式 + est → 采取合适的模式 → modest谦虚的"},{"word":"modification","ipa":"/ˌmɑːdɪfɪˈkeɪʃn/","pos":"n.","def":"改造，修改；【化】改进，修改","sen":"He's making a big modification to the car.","trans":"他正在对车子进行一次大的改造。","mne":"mod方式，模式，风度 + ification名词后缀 → 修正"},{"word":"modify","ipa":"/ˈmɑːdɪˌfaɪ/","pos":"v.","def":"更改，改造；修饰，限定","sen":"This car has been modified to make it even faster.","trans":"这辆车已经被改装过，以便它跑得更快。","mne":"mod方式，模式 + ify…化 → 规范化 → modify修改"},{"word":"moist","ipa":"/mɔɪst/","pos":"adj.","def":"（表面）潮湿的，湿润的","sen":"The grass is moist due to last night's heavy rain.","trans":"因为昨晚的大雨，草地湿漉漉的。","mne":""},{"word":"moisture","ipa":"/ˈmɔɪstʃər/","pos":"n.","def":"湿气；潮湿","sen":"The machine on the table adds moisture to the air.","trans":"桌上的机器能增加空气中的湿气。","mne":"moist潮湿的 + ure名词后缀，表行为、状态 → moisture潮湿，湿度"},{"word":"mom","ipa":"/mɑːm/","pos":"n.","def":"妈妈","sen":"She is the mom of these two little girls.","trans":"她是这两个小女孩的妈妈。","mne":""},{"word":"moment","ipa":"/ˈmoʊmənt/","pos":"n.","def":"瞬间，片刻","sen":"The girl is using her phone to capture the moment.","trans":"这个女孩正在用手机记录这个瞬间。","mne":""},{"word":"mommy","ipa":"/ˈmɑːmi/","pos":"n.","def":"妈咪","sen":"The baby likes being with its mommy.","trans":"宝宝喜欢和妈妈呆在一起。","mne":""},{"word":"monday","ipa":"/ˈmʌndeɪ/","pos":"n.","def":"星期一","sen":"Today is Monday.","trans":"今天是星期一。","mne":"Mon=moon月亮 + day日 → 神话中月亮为太阳之妻，一星期第一天是星期日献给太阳的 → Monday星期一"},{"word":"money","ipa":"/ˈmʌni/  ","pos":"n.","def":"金钱，财富","sen":"Money, money, money, always money—it's a rich man's world.","trans":"钱钱钱！到处都是钱！——这就是有钱人的世界啊。","mne":""},{"word":"monitor","ipa":"/ˈmɑːnɪtər/","pos":"n.","def":"监视器；班长；显示器；  v.监控；监视","sen":"The monkey monster was watching the chosen kids on the monitors.","trans":"猩猩兽在监视器上观察被选召的孩子。","mne":""},{"word":"monkey","ipa":"/ˈmʌŋki/","pos":"n.","def":"猴子","sen":"That silly monkey is always so curious.","trans":"这个蠢猴子总是那么好奇。","mne":""},{"word":"month","ipa":"/mʌnθ/","pos":"n.","def":"月","sen":"There are twelve months in a year.","trans":"一年有12个月。","mne":"moon月 + th名词后缀 → month月"},{"word":"monthly","ipa":"/ˈmʌnθli/","pos":"adj.","def":"每月的，每月一次的；  adv.每月一次，按月；  n.月刊","sen":"I have to keep up with my monthly house payments.","trans":"我必须每月付清房租。","mne":"month月 + ly形容词后缀，...的 → monthly每月的"},{"word":"monument","ipa":"/ˈmɑːnjumənt/ ","pos":"n.","def":"纪念碑；历史遗迹，遗址","sen":"The Washington Monument stands in the center of Washington, D.C.","trans":"华盛顿纪念碑矗立在华盛顿特区中心。","mne":"monu警告，提醒 + ment名词后缀 → 提醒的东西 → 纪念碑"},{"word":"mood","ipa":"/muːd/","pos":"n.","def":"情绪，心情；氛围，气氛","sen":"\"I'm in a good mood today,\" she said with a smile.","trans":"“我今天心情很好。”她微笑着说。","mne":""},{"word":"moon","ipa":"/muːn/","pos":"n.","def":"月球，月亮","sen":"The moon rises so big and bright over the sea.","trans":"月亮在海面上升起，它又大又亮。","mne":""},{"word":"moral","ipa":"/ˈmɔːrəl/","pos":"adj.","def":"道德（上）的，道义的；  n.寓意；道德，品行","sen":"To return the money you found or not, it's a moral dilemma.","trans":"捡到的钱要不要还回去，这是一个道德难题。","mne":"mor道德 + al…...的 → moral道德的"},{"word":"morality","ipa":"/məˈræləti/","pos":"n.","def":"道德，道德观","sen":"Talking on a mobile phone while watching a movie shows a lack of morality.","trans":"看电影时接电话表现出缺乏道德。","mne":"mor道德 + ality表示状态、情况、性质 → morality道德观"},{"word":"more","ipa":"/mɔːr/","pos":"adj.","def":"更多（的）","sen":"We all keep trying to earn more money.","trans":"我们都试着多赚钱。","mne":""},{"word":"moreover","ipa":"/mɔːrˈoʊvər/","pos":"adv.","def":"此外，而且","sen":"His work is busy; moreover, an interview and two calls are waiting for him.","trans":"他工作很忙，此外，还有一个面试和两通电话在等着他。","mne":"more此外 + over越过 → moreover再者，此外"},{"word":"morning","ipa":"/ˈmɔːrnɪŋ/   ","pos":"n.","def":"【数】早晨；早晨，上午","sen":"We learn math in the morning.","trans":"我们早晨学数学。","mne":"morn早上 + ing名词后缀 → morning早上"},{"word":"mortgage","ipa":"/ˈmɔːrɡɪdʒ/","pos":"n.","def":"【财】抵押；  v.抵押","sen":"There is the issue of mortgage interest relief which is available in some countries.","trans":"有些国家还提供抵押贷款利息减免。","mne":"mort死 + gage抵押品 → mortgage抵押"},{"word":"mosquito","ipa":"/məˈskiːtoʊ/","pos":"n.","def":"蚊子","sen":"There is a mosquito on my arm!","trans":"我的手臂上有只蚊子！","mne":"mos蚊虫，苍蝇 + quito → mosquito蚊子"},{"word":"most","ipa":"/moʊst/","pos":"adj.","def":"【数】最多的；  adv.最","sen":"Who has the most pencils in the class?","trans":"谁拥有这个班级里最多的铅笔？","mne":""},{"word":"mostly","ipa":"/ˈmoʊstli/","pos":"adv.","def":"大多；主要地；通常","sen":"The cake is mostly made of cream.","trans":"这个蛋糕大部分是奶油做的。","mne":""},{"word":"mother","ipa":"/ˈmʌðər/","pos":"n.","def":"母亲，妈妈","sen":"The mother watches over her baby.","trans":"这位母亲照看她的宝贝。","mne":""},{"word":"motion","ipa":"/ˈmoʊʃn/","pos":"n.","def":"运动，移动；提议","sen":"The slow motion clearly shows how he dodges the bullets.","trans":"慢动作清楚地展现了他是如何躲过子弹的。","mne":"mot=move移动 + ion名词后缀 → motion运动"},{"word":"motivate","ipa":"/ˈmoʊtɪveɪt/","pos":"v.","def":"激励；成为……的动机；促进；促使；激发","sen":"Praise from a teacher can always motivate students.","trans":"来自老师的夸赞经常能激励学生。","mne":"motiv运动的 + ate表动词 → motivate促动；激励，激发"},{"word":"motive","ipa":"/ˈmoʊtɪv/","pos":"n.","def":"动机，目的；  adj.发动的，运动的；  v.引发，促进，激发","sen":"His motive for participating in the competition was to win the championship.","trans":"他参加比赛的动机是拿冠军。","mne":"mot移动 + ive名词后缀 → motive动机"},{"word":"motor","ipa":"/ˈmoʊtər/","pos":"n.","def":"马达，发动机","sen":"This is the motor of the four-wheel drive.","trans":"这是这辆四驱车的马达。","mne":"mot移动，动 + or表示物 → motor发动机，电动机"},{"word":"mount","ipa":"/maʊnt/","pos":"v.","def":"骑上；登上；爬上；增长；  n.山；峰","sen":"He mounted his horse and rode away.","trans":"他飞身上马，疾驰而去。","mne":""},{"word":"mountain","ipa":"/ˈmaʊntn/","pos":"n.","def":"山，山脉；大堆","sen":"There is much snow on the mountain.","trans":"山上有很多雪。","mne":"mount登上 + ain名词后缀 → mountain山"},{"word":"mouse","ipa":"/maʊs/","pos":"n.","def":"鼠；鼠标","sen":"The mouse lives in a hole in the wall.","trans":"这只老鼠住在一个墙洞里。","mne":""},{"word":"mouth","ipa":"/maʊθ/","pos":"n.","def":"嘴","sen":"The dentist could see her mouth was full of perfect white teeth.","trans":"牙医可以看到她嘴里都是洁白的牙齿。","mne":""},{"word":"move","ipa":"/muːv/ ","pos":"v.","def":"移动；（使）改变位置；  n.迁居","sen":"He's using a truck to help him move house.","trans":"他正用卡车帮他搬家。","mne":""},{"word":"movement","ipa":"/ˈmuːvmənt/","pos":"n.","def":"动作；（交响乐的）乐章","sen":"Dancing is the art of movement.","trans":"舞蹈是动作的艺术。","mne":"move动 + ment表名词 → movement运动"},{"word":"movie","ipa":"/ˈmuːvi/","pos":"n.","def":"（多用于美语）电影","sen":"We are going to see an open-air movie.","trans":"我们准备看一场露天电影。","mne":"mov移动 + ie表名词，小东西或人 → movie电影"},{"word":"much","ipa":"/mʌtʃ/","pos":"adj.","def":"许多的，大量的","sen":"He has too much work to do.","trans":"他的工作太多了。","mne":""},{"word":"mud","ipa":"/mʌd/","pos":"n.","def":"泥","sen":"Oh no! I think we are stuck in the mud!","trans":"哦，不！我想我们被困在泥里了！","mne":""},{"word":"multiple","ipa":"/ˈmʌltɪpl/","pos":"adj.","def":"多种多样的；  n.倍数","sen":"There are multiple types of fruit to choose from.","trans":"这里有各式各样的水果可供选择。","mne":"multi很多 + ple满 → 多的 → multiple多功能的，多样的"},{"word":"multiply","ipa":"/ˈmʌltɪplaɪ/","pos":"v.","def":"【数】乘；增加，倍增；繁殖","sen":"To find the area of a rectangle, multiply its length by its width.","trans":"要找到矩形的面积，把它的长度乘以宽度。","mne":"multi很多 + ply重叠 → 变多 → multiply乘，繁殖"},{"word":"mum","ipa":"/mʌm/","pos":"adj.","def":"守密的，沉默的；  n.妈妈，母亲（=mom）","sen":"The boy asked her to keep mum while the cat was sleeping.","trans":"男孩让她保持安静，小猫正在睡觉。","mne":""},{"word":"municipal","ipa":"/mjuːˈnɪsɪpl/","pos":"adj.","def":"市政的；市的","sen":"This beautiful building is home to the municipal government of San Francisco.","trans":"这个漂亮的建筑是旧金山市政府所在地。","mne":"muni为社区提供的服务，职责 + cip抓，拿 + al表形容词 → municipal市政的"},{"word":"murder","ipa":"/ˈmɜːrdər/","pos":"n.","def":"谋杀，凶杀；谋杀罪；  v.谋杀，凶杀","sen":"The ox chef was arrested for murder by the chicken policeman.","trans":"牛厨师因为谋杀而被鸡警察逮捕。","mne":"murd死 + er → murder谋杀"},{"word":"muscle","ipa":"/ˈmʌsl/","pos":"n.","def":"肌肉；实力，影响力","sen":"She has strong muscles from working out regularly.","trans":"她因为经常锻炼，肌肉很结实。","mne":"mus老鼠 + cle小的 → 肌肉的形状和收缩像小老鼠 → muscle肌肉"},{"word":"museum","ipa":"/mjuˈziːəm/","pos":"n.","def":"博物馆，博物院，展览馆","sen":"There are many pieces of art in the museum.","trans":"博物馆里有很多艺术作品。","mne":"muse文艺、音乐 + um名词后缀，表场所 → museum博物馆"},{"word":"music","ipa":"/ˈmjuːzɪk/","pos":"n.","def":"音乐，乐曲","sen":"Let's put some music on!","trans":"让我们放点儿音乐吧！","mne":"mus音乐 ＋ ic...学 → music音乐"},{"word":"musical","ipa":"/ˈmjuːzɪkl/","pos":"adj.","def":"音乐的；悦耳的；擅长音乐的；对音乐感兴趣的；有音乐才能的，喜欢音乐的；  n.音乐片；音乐剧","sen":"The guitar is a musical instrument which is hard to learn.","trans":"吉他是一种难学的乐器。","mne":"mus娱乐，音乐 + ical…的 → musical音乐的；和谐的"},{"word":"musician","ipa":"/mjuˈzɪʃn/","pos":"n.","def":"音乐家，作曲家","sen":"The musician is playing beautiful music.","trans":"这位音乐家在演奏美妙的音乐。","mne":"mus音乐，娱乐 + ician表专家，从事某职业的人 → musician音乐家"},{"word":"must","ipa":"/mʌst/","pos":"auxv.","def":"应该，必须；（表示很可能或符合逻辑）一定；  n.必须做的事；必不可少的事物","sen":"You must leave the game!","trans":"你必须离开比赛！","mne":""},{"word":"mutual","ipa":"/ˈmjuːtʃuəl/","pos":"adj.","def":"互相的；共同的","sen":"Good communication can build a bridge of mutual understanding.","trans":"良好的沟通能架起一座相互理解的桥梁。","mne":"mut变 + ual形容词后缀 → 你变我也变 → mutual相互的"},{"word":"my","ipa":"/maɪ/","pos":"det.","def":"（I的所有格）我的","sen":"Look at my new T-shirt!","trans":"看看我的新T恤！","mne":""},{"word":"myself","ipa":"/maɪˈself/","pos":"pron.","def":"我自己","sen":"I finished all the work by myself!","trans":"我自己完成了所有工作！","mne":""},{"word":"mysterious","ipa":"/mɪˈstɪriəs/ ","pos":"adj.","def":"神秘的","sen":"Oh my God! A mysterious man is running in my yard!","trans":"天哪！一个神秘人正在我的院子里跑！","mne":"mystery神秘 + ious表形容词 -> mysterious神秘的"},{"word":"mystery","ipa":"/ˈmɪstəri/ ","pos":"n.","def":"神秘（感）；神秘的事物；谜","sen":"Why did it turn green? It's a mystery. ","trans":"为什么它变绿了？这是一个谜。","mne":""},{"word":"nail","ipa":"/neɪl/","pos":"n.","def":"指甲，爪；  v.将……钉牢，钉住；固定","sen":"I got diverse patterns on my nails from the nail salon.","trans":"我去美甲沙龙给指甲做了不同的图案。","mne":""},{"word":"name","ipa":"/neɪm/","pos":"v.","def":"提名，任命","sen":"The chairman named him as his successor. ","trans":"主席任命他为自己的继任者。","mne":""},{"word":"namely","ipa":"/ˈneɪmli/","pos":"adv.","def":"即，也就是","sen":"She took two classes this morning, namely, English and Maths.","trans":"她今天上午上了两节课，即英语课和数学课。","mne":"name名字 + ly副词和形容词后缀 → 顾名思义，如名字所说 → namely即，也就是"},{"word":"narrow","ipa":"/ˈnæroʊ/","pos":"adj.","def":"狭窄的，窄小的；  v.（使）变窄","sen":"The fat man is wondering how to pass through the narrow alley.","trans":"那个胖子正在纠结如何才能穿过那条窄巷。","mne":""},{"word":"nation","ipa":"/ˈneɪʃn/","pos":"n.","def":"民族，国家","sen":"These flags represent different nations.","trans":"这些国旗代表着不同的国家。","mne":"nat出生的 + ion名词后缀 → 出生之处 → nation国家"},{"word":"national","ipa":"/ˈnæʃnəl/ ","pos":"adj.","def":"国家的，民族的；  n.（某国的）公民","sen":"Baseball is the national game of the U.S.","trans":"棒球是美国的国民运动。","mne":"nat出生的 + ion名词后缀 + al…的 → 出生地的 → national国家的，民族的"},{"word":"nationality","ipa":"/ˌnæʃəˈnæləti/","pos":"n.","def":"国籍；民族","sen":"People of all nationalities come together for the Olympic Games.","trans":"所有国家的人们为奥运会欢聚一堂。","mne":"national国家的 + ity名词后缀；性质 → nationality国籍"},{"word":"nationwide","ipa":"/ˌneɪʃnˈwaɪd/","pos":"adj.","def":"全国范围的，全国性的；  adv.在全国","sen":"Our company is in the process of a nationwide business expansion.","trans":"我们企业正在经历全国范围内的业务扩展。","mne":"nation国家的 + wide 广泛的 → nationwide全国范围的"},{"word":"native","ipa":"/ˈneɪtɪv/ ","pos":"adj.","def":"本地的；天赋的；  n.本地人；土著","sen":"The native people are wearing their own traditional clothes.","trans":"当地人穿着自己的传统服装。","mne":"nat出生 + ive名词后缀 → native本地人"},{"word":"natural","ipa":"/ˈnætʃrəl/","pos":"adj.","def":"天然的，大自然的","sen":"There are more green trees in the natural environment than in the urban environment.","trans":"自然环境中的绿树比城市环境中的多。","mne":"natur自然 + al形容词后缀…...的 → natural自然（界）的"},{"word":"naturally","ipa":"/ˈnætʃrəli/","pos":"adv.","def":"自然地，天然地；当然地","sen":"Some people have naturally frizzy hair.","trans":"有的人天生卷发。","mne":"natur=nature自然 + ally副词后缀 → 自然地"},{"word":"nature","ipa":"/ˈneɪtʃər/","pos":"n.","def":"大自然；天性","sen":"She loves being surrounded by nature.","trans":"她喜欢被大自然包围。","mne":"nat出生的 + ure状态 → 出生状态 → nature天性"},{"word":"naval","ipa":"/ˈneɪvl/","pos":"adj.","def":"海军的，军舰的","sen":"The naval branch of the military is concerned with protecting the oceans.","trans":"军队的海军部门负责保护领海的安全。","mne":"nav船 + al形容词后缀 → naval船的；海军的"},{"word":"navigation","ipa":"/ˌnævɪˈɡeɪʃn/","pos":"n.","def":"导航，领航；航行，航海","sen":"The rat uses navigation to find the cheese.","trans":"这只老鼠用导航为自己寻找那块奶酪。","mne":"nav船 + ig走 + ation表名词 → navigation航行；航海术；导航"},{"word":"navy","ipa":"/ˈneɪvi/","pos":"n.","def":"海军；海军部队；藏青色","sen":"I am now a navy officer and ready to protect our country. ","trans":"我现在是一名海军军官，已做好准备保护祖国。","mne":"nav船 + y表名词 → navy海军"},{"word":"near","ipa":"/nɪr/","pos":"adv.","def":"近，接近；  adj.近的；  prep.在......附近，靠近，接近","sen":"She is not herself. She came near to a breakdown.","trans":"她身体不舒服，简直要崩溃了。","mne":""},{"word":"nearby","ipa":"/ˌnɪrˈbaɪ/","pos":"adj.","def":"附近的，邻近的；  adv.在附近","sen":"My phone can exchange information with any smart phone that is nearby.","trans":"我的手机可以跟附近任何智能手机交换信息。","mne":"near附近 + by旁边 → nearby附近的"},{"word":"nearly","ipa":"/ˈnɪrli/","pos":"adv.","def":"将近，几乎，差不多","sen":"The ball nearly went in!","trans":"那个球差点儿就进了！","mne":"near接近 + ly……的 → nearly差不多；密切地"},{"word":"neat","ipa":"/niːt/","pos":"adj.","def":"整洁的；有条理的","sen":"This house is very neat.","trans":"这个房间很整洁。","mne":""},{"word":"necessarily","ipa":"/ˌnesəˈserəli/","pos":"adv.","def":"必定","sen":"The biggest diamond in the shop necessarily commands the highest price.","trans":"这家店里最大的这颗钻石必定售价最贵。","mne":"necessari必要的 + ly表示如...的、有...特征的 → necessarily必然，必定"},{"word":"necessary","ipa":"/ˈnesəseri/","pos":"adj.","def":"必需的，必要的；必然的，势必的","sen":"A boat is necessary to get across the river.","trans":"要过河就得有船。","mne":"necess必要 + ary表示有……性质的 → necessary必要的；必然的"},{"word":"necessity","ipa":"/nəˈsesəti/","pos":"n.","def":"必需品；需要","sen":"Air conditioner is an absolute necessity in this climate.","trans":"在这种气候下，空调是绝对的必需品。","mne":"necess不可或缺的 + ity名词后缀 → necessity必要性；必需品"},{"word":"neck","ipa":"/nek/","pos":"n.","def":"【医】颈部；脖子，颈","sen":"A stiff neck can be a symptom of various conditions, such as muscle strain or meningitis.","trans":"颈部僵硬可能是各种病症的症状，如肌肉拉伤或脑膜炎。","mne":""},{"word":"need","ipa":"/niːd/","pos":"v.","def":"需要；必需；  n.需要，必须","sen":"The baby girl badly needs her mother.","trans":"这个小女孩非常需要她的妈妈。","mne":""},{"word":"needle","ipa":"/ˈniːdl/","pos":"n.","def":"针","sen":"All you need to sew clothing is a needle and thread.","trans":"你缝衣服所需要的就是针和线。","mne":""},{"word":"negative","ipa":"/ˈneɡətɪv/","pos":"adj.","def":"消极的，负面的；否定的；  n.否定，否定词；底片","sen":"He received too many negative comments from others.","trans":"他收到了太多负面的评价。","mne":"negat否认 + ive形容词后缀 → 否认的"},{"word":"neglect","ipa":"/nɪˈɡlekt/","pos":"v.","def":"疏于照料，忽视；不予重视，疏忽；  n.疏忽，忽视","sen":"The parents neglected their child and kept quarrelling.","trans":"那对父母忽视了他们的孩子，一直在吵架。","mne":"neg没有 + lect选 → 没有选出来 → neglect疏忽"},{"word":"negotiate","ipa":"/nɪˈɡəʊʃieɪt/","pos":"v.","def":"谈判，磋商，商议","sen":"They are negotiating some details of the cooperation.","trans":"他们正在商议合作的细节。","mne":"negoti协商 + ate动词后缀 → negotiate谈判，协商"},{"word":"neighbor","ipa":"/'neɪbə/","pos":"n.","def":"邻居，邻人（=neighbour）","sen":"We live in the same apartment block, so we are neighbors.","trans":"我们住在同一栋楼，所以我们是邻居。","mne":"neigh附近 + bor居民 → neighbor邻居"},{"word":"neighborhood","ipa":"/ˈneɪbərhʊd/","pos":"n.","def":"社区，街区，邻近地区；街区，邻里","sen":"The houses in this neighborhood all look the same.","trans":"这个社区的房子都一模一样。","mne":"neighbor邻居 + hood名词后缀 → neighborhood与某处邻近的地区"},{"word":"neighbour","ipa":"/ˈneɪbər/","pos":"n.","def":"邻居，邻人","sen":"All my neighbours live in the neighborhood.","trans":"我所有的邻居都住在这个社区里。","mne":""},{"word":"neighbourhood","ipa":"/ˈneɪbərhʊd/","pos":"n.","def":"社区；邻近地区（=neighborhood）；街区，居民区；城区","sen":"I live in a friendly neighbourhood where everyone knows each other.","trans":"我住在一个友好的社区里，那里每个人都互相认识。","mne":"neighbour邻居 + hood名词后缀 → neighbourhood社区"},{"word":"neither","ipa":"/ˈnaɪðər, ˈniːðər/","pos":"pron.","def":"两者都不；  conj.也不；  adj.两者都不的；  adv.既不……也不……","sen":"He tasted both dishes and decided neither was delicious.","trans":"他两盘菜都尝了尝，觉得两个都不好吃。","mne":"ne不，没有 + ither两者中的一个 → neither两者都不"},{"word":"nephew","ipa":"/ˈnefjuː/","pos":"n.","def":"侄子，外甥","sen":"I can't wait to meet my nephew!","trans":"我等不及去见我外甥了。","mne":""},{"word":"nerve","ipa":"/nɜːrv/","pos":"n.","def":"神经；胆量，勇气","sen":"There are many nerves in the brain.","trans":"大脑里有许多神经。","mne":""},{"word":"nervous","ipa":"/ˈnɜːrvəs/","pos":"adj.","def":"紧张的，焦虑不安的；神经系统的，神经方面的","sen":"The father is nervous about his wife and their unborn baby during the delivery.","trans":"这位父亲对分娩期间妻子和未出生宝宝的状况感到紧张不安。","mne":"nerve神经 + ous…...的 → 与神经有关的 → nervous紧张的"},{"word":"nest","ipa":"/nest/","pos":"n.","def":"巢；鸟窝；温床；  v.筑巢；嵌入","sen":"Most birds lay their eggs in their nests.","trans":"大多数鸟儿把蛋生在它们的巢穴里。","mne":""},{"word":"net","ipa":"/net/","pos":"n.","def":"球网；网，网状物","sen":"The sports net is too high for small children.","trans":"球网对小孩子来说太高了。","mne":""},{"word":"network","ipa":"/ˈnetwɜːrk/","pos":"n.","def":"网络；关系网；网状系统","sen":"The Internet is basically a network of billions of computers.","trans":"互联网其实就是连接数十亿台电脑的网络。","mne":"net网 + work操作 → network网络"},{"word":"neutral","ipa":"/ˈnuːtrəl/","pos":"adj.","def":"中立的；中性的","sen":"He remained neutral in the disagreement, not taking either side.","trans":"他在这场争吵中保持中立，不偏袒任何一方。","mne":"neutr=neuter中性的 + al属于……的 → 中立的；中性的"},{"word":"neutralise","ipa":"/'njuːtrəˌlaɪz/","pos":"v.","def":"中和，使...中立","sen":"The alkali was added to the acid to neutralise it.","trans":"加入碱来中和酸。","mne":""},{"word":"neutralize","ipa":"/ˈnuːtrəlaɪz/","pos":"v.","def":"使无效，消除；宣布中立，使中立化","sen":"She tried to neutralize the negative effects of staying up late with eye cream.","trans":"她试图用眼霜来消除熬夜带来的负面影响。","mne":"neutr中间，中和 + al……的 + ize动词后缀，……化 → 使中和"},{"word":"never","ipa":"/ˈnevər/","pos":"adv.","def":"从不，永不","sen":"Elephants, cows, and pigs will never fly.","trans":"大象、奶牛和猪永远不会飞。","mne":"ne不 + ever从来 → 从来不 → never从不"},{"word":"nevertheless","ipa":"/ˌnevərðəˈles/","pos":"adv.","def":"然而，不过；尽管如此","sen":"Our defeat was expected but it is disappointing nevertheless.","trans":"我们的失败是意料中的事，尽管如此，它还是令人失望。","mne":"never从不 + theless无……的 → nevertheless然而"},{"word":"new","ipa":"/nuː/","pos":"adj.","def":"新的，新来的，新开始的","sen":"The man loves his new motorbike!","trans":"这个男人超爱他的新摩托车！","mne":""},{"word":"news","ipa":"/nuːz/","pos":"n.","def":"新闻，消息","sen":"I try to keep up with the latest news about developments in our industry.","trans":"我会努力跟上行业发展的最新动态。","mne":""},{"word":"newsletter","ipa":"/ˈnuːzleɪtər/","pos":"n.","def":"时事通讯，业务通讯","sen":"I couldn’t read the foreign newsletter, but the headline seemed like big news.","trans":"虽然我看不懂外语简讯，但这个头条似乎是个重大新闻。","mne":"news新闻 + letter信 → newsletter 时事通讯"},{"word":"newspaper","ipa":"/ˈnuːzpeɪpər/","pos":"n.","def":"报纸；报（纸）","sen":"This clever little dog can read a newspaper!","trans":"这只聪明的小狗竟然在看报纸！","mne":"news新闻 + paper纸 → newspaper报纸"},{"word":"next","ipa":"/nekst/","pos":"adj.","def":"下一个的，接下来的；  adv.其次，然后，随后；紧接着","sen":"They are discussing the next step of the plan.","trans":"他们正在讨论计划的下一步。","mne":""},{"word":"nice","ipa":"/naɪs/","pos":"adj.","def":"令人愉快的；好看的，美好的","sen":"We have a nice time at the park.\t","trans":"我们在公园里度过了一段愉快的时光。","mne":""},{"word":"niece","ipa":"/niːs/","pos":"n.","def":"侄女，外甥女","sen":"My niece is my sibling's daughter.","trans":"我的侄女或外甥女就是我兄弟姐妹的女儿。","mne":""},{"word":"night","ipa":"/naɪt/","pos":"n.","def":"夜晚","sen":"When night falls, the moon begins to shine.","trans":"夜幕降临，月亮开始照耀大地。","mne":""},{"word":"nine","ipa":"/naɪn/","pos":"num.","def":"九个","sen":"Nine apples are in this picture.","trans":"图片上画了九个苹果。","mne":""},{"word":"nineteen","ipa":"/ˌnaɪnˈtiːn/","pos":"num.","def":"十九，十九个","sen":"I'm nineteen years old now!","trans":"我现在十九岁啦！","mne":"nine九 + teen十 → nineteen十九"},{"word":"ninety","ipa":"/ˈnaɪnti/","pos":"num.","def":"九十","sen":"Will you live to ninety years old?","trans":"你会活到90岁吗？","mne":"nine九 + ty十 → ninety九十"},{"word":"ninth","ipa":"/naɪnθ/","pos":"num.","def":"第九","sen":"I got my nine gifts on my ninth birthday.","trans":"我在九岁生日时得到了9份礼物。","mne":""},{"word":"no","ipa":"/noʊ/","pos":"adv.","def":"不，不是；  int.不，不要","sen":"\"No, I don't want any junk food,\" she said.","trans":"她说：\"不，我不想吃任何的垃圾食品。”","mne":""},{"word":"noble","ipa":"/ˈnoʊbl/","pos":"adj.","def":"贵族的，高贵的；  n.贵族成员","sen":"The woman in the expensive dresses comes from a noble family.","trans":"这位穿着昂贵衣服的女人出身高贵。","mne":""},{"word":"nobody","ipa":"/ˈnoʊbədi/","pos":"pron.","def":"没有人","sen":"After school, there was nobody in the classroom.","trans":"放学后，教室空无一人。","mne":"no无 ＋ body人 → nobody谁也不；无人"},{"word":"nod","ipa":"/nɑːd/","pos":"v.","def":"点头；打盹；  n.点头","sen":"To nod in agreement, lean your head forward a little.","trans":"点头同意时，要稍微前倾头部。","mne":""},{"word":"noise","ipa":"/nɔɪz/","pos":"n.","def":"【护】噪声","sen":"Exposure to loud noise can cause noise-induced hearing loss, which may be temporary or permanent.","trans":"暴露于高分贝噪音中可能会导致噪音性听力损失，这种损失可能是暂时的或者永久的。","mne":""},{"word":"noisy","ipa":"/ˈnɔɪzi/  ","pos":"adj.","def":"喧闹的","sen":"It's so noisy outside. I can't stand this kind of environment!","trans":"外面太吵了。我受不了这样的环境了！","mne":"nois=noise喧闹 + y形容词后缀 → noisy喧闹的，嘈杂的"},{"word":"none","ipa":"/nʌn/","pos":"pron.","def":"没有（一人或一物）","sen":"I wish I could offer you some cake but there's none left.","trans":"我很想请你吃蛋糕，但是没有了。","mne":"n=no没有 + one一个人 → none没有一个人"},{"word":"nonsense","ipa":"/ˈnɑːnsens/","pos":"n.","def":"废话，胡说","sen":"What you're saying is nonsense.","trans":"你说的话就是胡话。","mne":"non无 + sense感觉，意义 → nonsense无意义"},{"word":"noon","ipa":"/nuːn/","pos":"n.","def":"正午，中午","sen":"It's noon, and the sun is at its highest point.","trans":"现在是中午，太阳正处于最高点。","mne":""},{"word":"nor","ipa":"/nɔːr/","pos":"conj.","def":"也不；  adv.也不","sen":"Neither my sister nor I like eggs.","trans":"我和我的妹妹都不喜欢吃鸡蛋。","mne":"n不 + or或者 → nor也不"},{"word":"normal","ipa":"/ˈnɔːrml/","pos":"adj.","def":"正常的，一般的","sen":"I was glad when the doctor told me my heart beat was normal.","trans":"当医生告诉我我的心跳是正常的时候，我非常开心。","mne":"norm规则，规范 + al形容词后缀 → 有规范的 → normal正常的"},{"word":"normally","ipa":"/ˈnɔːrməli/","pos":"adv.","def":"通常，正常地","sen":"Primary schools are normally open from Monday to Friday.","trans":"通常来说，小学在周一到周五上课。","mne":"norm规则，规范 ＋ ally表示方式、程度、状态、“…地” → normally通常，正常地"},{"word":"north","ipa":"/nɔːrθ/","pos":"n.","def":"北；北方；  adj.北方的","sen":"They are driving north towards the mountains.","trans":"他们朝着山，往北开去。","mne":""},{"word":"northeast","ipa":"/ˌnɔːrθˈiːst/","pos":"n.","def":"东北；  adj.位于东北的","sen":"The compass is pointing to the northeast.","trans":"指南针指向东北。","mne":"north北 + east东 → northeast东北"},{"word":"northern","ipa":"/ˈnɔːrðərn/","pos":"adj.","def":"北部的，北方的，有北方特征的","sen":"This kind of bear can be found in northern areas.","trans":"这种熊通常出没在北方地区。","mne":"north北 + ern形容词后缀 → northern 北方的"},{"word":"northwest","ipa":"/ˌnɔːrθˈwest/","pos":"n.","def":"西北方；  adj.在西北的；  adv.在西北","sen":"Our ship is heading in a northwest direction.","trans":"我们的船在朝着西北方前行。","mne":"north北方 + west西方 → northwest西北；位于西北的"},{"word":"nose","ipa":"/nəʊz/","pos":"n.","def":"鼻子","sen":"The dog has a very sensitive nose.","trans":"这只狗的鼻子非常灵敏。","mne":"nos=nas鼻子 + e后缀 → nose鼻子"},{"word":"not","ipa":"/nɑːt/","pos":"adv.","def":"不，不是，没有","sen":"That's a deer, not a horse.","trans":"那是一只鹿，不是一匹马。","mne":""},{"word":"note","ipa":"/noʊt/","pos":"n.","def":"笔记，记录；便条；注释；提醒；单音，音调；纸币，钞票；  v.注意；记录","sen":"I take notes in class with my notebook.","trans":"我用笔记本做课堂笔记。","mne":""},{"word":"notebook","ipa":"/ˈnoʊtbʊk/","pos":"n.","def":"笔记本","sen":"I like to use colorful stickers to mark the important pages in my notebook.","trans":"我喜欢用彩色便利贴在笔记本的重要页面上做标记。","mne":"note笔记 + book书 → notebook笔记本，期票簿"},{"word":"nothing","ipa":"/ˈnʌθɪŋ/","pos":"pron.","def":"没有东西，没有任何事","sen":"There's nothing in this box.","trans":"盒子里什么也没有。","mne":"no没有 ＋ thing东西 → nothing没有东西，没有任何事"},{"word":"notice","ipa":"/ˈnoʊtɪs/","pos":"n.","def":"告示，通知；  v.注意到，意识到；预告","sen":"The girl puts the notice on the bulletin board.","trans":"女孩把告示张贴在公告栏上。","mne":"not知道 + ice名词后缀 → notice 通知"},{"word":"noticeable","ipa":"/ˈnoʊtɪsəbl/","pos":"adj.","def":"明显的，显著的","sen":"It was noticeable that the rabbit's friend was in the snake's stomach.","trans":"显而易见的是，小兔子的朋友在蛇的肚子里。","mne":"notice注意，表示行为 + able可...的 → noticeable引人注目的"},{"word":"notify","ipa":"/ˈnoʊtɪfaɪ/","pos":"v.","def":"通知，告知","sen":"The employee was notified that he was fired.","trans":"这个员工被告知他被解雇了。","mne":"not知道，注意 + ify动词后缀 → 给予注意 → notify通告"},{"word":"noun","ipa":"/naʊn/","pos":"n.","def":"名词","sen":"A noun refers to a person, a place or a thing.","trans":"名词可以指一个人、一处地点或者一样东西。","mne":""},{"word":"novel","ipa":"/ˈnɑːvl/","pos":"n.","def":"小说，长篇故事；  adj.新奇的，新颖的","sen":"He loves reading novels and these two are his favorites.","trans":"他喜欢读小说，这两本是他最喜欢的。","mne":"nov新的 + el名词后缀 → 新的故事 → novel小说"},{"word":"november","ipa":"/noʊˈvembər/","pos":"n.","def":"十一月","sen":"November is the eleventh month of the year.","trans":"十一月是一年的第十一个月。","mne":""},{"word":"now","ipa":"/naʊ/","pos":"adv.","def":"现在","sen":"I will be healthier starting now.","trans":"从现在开始我将更健康。","mne":""},{"word":"nowadays","ipa":"/ˈnaʊədeɪz/","pos":"adv.","def":"现在，当今","sen":"Nowadays, smartphones are more advanced than this old cellphone.","trans":"如今，智能手机比这种旧手机先进多了。","mne":"nowaday现在 + s表副词 → 现今，当今"},{"word":"nowhere","ipa":"/ˈnoʊwer/","pos":"adv.","def":"任何地方都不","sen":"He looked everywhere in the room, but the key was nowhere to be found.","trans":"他在房间里到处找，但哪里都找不到钥匙。","mne":"no无 + where哪里 → nowhere无处"},{"word":"nuclear","ipa":"/ˈnuːkliər/","pos":"adj.","def":"核能的；原子能的；细胞核的","sen":"A single nuclear power plant can provide energy for the whole city.","trans":"一个核电站能为一整座城市提供能源。","mne":"nucleus核 + ar形容词后缀 → nuclear核能的"},{"word":"nucleus","ipa":"/ˈnuːkliəs/","pos":"n.","def":"原子核，核心，细胞核","sen":"The nucleus is the center of the atom.","trans":"原子核就是原子的中心。","mne":"nucle 核液 + us 用 → nucleus核，核心"},{"word":"number","ipa":"/ˈnʌmbər/","pos":"n.","def":"数字；号码","sen":"In total there are 10 numbers here.","trans":"这里总共有10个数字。","mne":""},{"word":"numerous","ipa":"/ˈnuːmərəs/","pos":"adj.","def":"为数众多的，许多的","sen":"The stadium is filled with numerous sports fans.","trans":"体育场里坐满了体育爱好者。","mne":"numer数 + ous形容词后缀 → numerous无数的，许多的"},{"word":"nurse","ipa":"/nɜːrs/","pos":"n.","def":"护士；保姆；  v.护理，照顾；哺乳","sen":"The nurse is looking after the patient.","trans":"护士正在照顾病人。","mne":""},{"word":"nursery","ipa":"/ˈnɜːrsəri/","pos":"n.","def":"托儿所；苗圃；  adj.幼儿教育的","sen":"I drop off my kids at the nursery before I go to work.","trans":"上班之前，我把孩子们送去了托儿所。","mne":"nurse照顾 + ry名词后缀 → nursery托儿所"},{"word":"nut","ipa":"/nʌt/","pos":"n.","def":"坚果；螺母，螺帽；疯子，怪人","sen":"Nuts are a source of vitamin E for the body.","trans":"坚果是人体所需维生素E的一个来源。","mne":""},{"word":"nutrition","ipa":"/nuˈtrɪʃn/","pos":"n.","def":"营养；滋养","sen":"Proper nutrition is very important for growing children.","trans":"适当的营养对于成长中的孩子非常重要。","mne":"nutri营养 + tion表名词 → 营养；滋养"},{"word":"o'clock","ipa":"/əˈklɑːk/","pos":"adv.","def":"......点钟","sen":"I have to be at work by ten o'clock, so I'm already a few minutes late.","trans":"我必须在十点钟之前上班，我已经迟到了几分钟了。","mne":""},{"word":"obese","ipa":"/əʊˈbiːs/","pos":"adj.","def":"肥胖的","sen":"Eating too much made her so obese.","trans":"莫妮卡以前吃很多长很胖。","mne":"obes肥 + e强调 → obese肥胖的"},{"word":"obesity","ipa":"/oʊˈbiːsəti/","pos":"n.","def":"肥胖；【医】肥胖症","sen":"The man suffers from obesity and lives an unhealthy lifestyle.","trans":"那个患有肥胖症的男人过着一种不健康的生活。","mne":"obes肥胖的 + ity 指具备某种性质 → n.肥胖，肥大"},{"word":"obey","ipa":"/əʊˈbeɪ/, /əˈbeɪ/","pos":"v.","def":"服从，顺从，遵守","sen":"The dog always obeys its master.","trans":"这只狗总是服从它的主人。","mne":"ob去 + ey听，听见 → obey听从"},{"word":"object","ipa":" /ˈɑːbdʒekt/, /əbˈdʒekt/ ","pos":"n.","def":"物体；宾语；目标；  v.提出……作为反对的理由","sen":"UFO is the short form of Unidentified Flying Object.","trans":"UFO是“不明飞行物体”的简写。","mne":"ob朝向 + ject扔 → object目标，物体"},{"word":"objection","ipa":"/əbˈdʒɛkʃn/","pos":"n.","def":"反对；反对，异议","sen":"Despite a formal objection from one member state, the resolution was adopted by the council.","trans":"尽管一个成员国提出了正式反对，但该决议还是获得了理事会的通过。","mne":"ob反对 ＋ ject投掷，扔 ＋ ion名词后缀 → objection反对"},{"word":"objective","ipa":"/əbˈdʒektɪv/","pos":"n.","def":"目标，目的；  adj.客观的","sen":"His objective is to find the One Piece!","trans":"他的目标是找到那件宝物！","mne":"ob反对 + ject投掷，扔 + ive形容词后缀 → 反对扔的 → objective客观的；目标"},{"word":"obligation","ipa":"/ˌɑːblɪˈɡeɪʃn/","pos":"n.","def":"义务，责任","sen":"If you want to own a pet, you must fulfill all the associated obligations.","trans":"如果你想拥有一只宠物，你就必须履行所有的相关义务。","mne":"obligat使负义务 + ion名词后缀 → 有义务 → obligation责任"},{"word":"oblige","ipa":"/əˈblaɪdʒ/","pos":"v.","def":"（以法律、义务等）迫使，使感激","sen":"Taxpayers are obliged to pay taxes by law.","trans":"纳税人有义务依法交税。","mne":"ob去 + lig绑 + e  → 去绑住某人  → oblige迫使"},{"word":"observation","ipa":"/ˌɑːbzərˈveɪʃn/","pos":"n.","def":"观察；遵守；监视","sen":"Telescope observation revealed many secrets about the star.","trans":"望远镜观测揭开了关于这颗恒星的许多秘密。","mne":"ob在前 + serve观看 + tion名词后缀 → observation观察，遵守"},{"word":"observe","ipa":"/əbˈzɜːrv/","pos":"v.","def":"观察；说，评论；庆祝，纪念","sen":"It observes the stars at night.","trans":"它在夜色中观察着星星。","mne":"ob在...之前 + serve照看，保证安全 → observe观察"},{"word":"observer","ipa":"/əbˈzɜːrvər/","pos":"n.","def":"观察者","sen":"The little boy wants to become a star observer in the future.","trans":"这个小男孩以后想成为一名观星者。","mne":"ob加强意义 + serv保持 + er表示人,行为的主动者，做某事的人 → 观察员，观测者"},{"word":"obsess","ipa":"/əbˈses/","pos":"v.","def":"迷住，使着迷，使烦扰","sen":"She is obsessed with taking selfies.","trans":"她沉迷于自拍。","mne":""},{"word":"obsession","ipa":"/əbˈseʃn/","pos":"n.","def":"着迷；困扰","sen":"His obsession with cars is obvious.","trans":"他对汽车的痴迷显而易见。","mne":"ob在…中 ＋ sess坐 ＋ ion表名词，构成抽象名词 → 坐在中间 → obsession入迷，入迷"},{"word":"obstacle","ipa":"/ˈɑːbstəkl/","pos":"n.","def":"障碍物","sen":"The bunny jumps over the obstacles.","trans":"小兔子跳过了这些障碍物。","mne":"ob逆，倒，加强意义 + st站立 + acle名词后缀 → 反着站的东西 → obstacle障碍物"},{"word":"obtain","ipa":"/əbˈteɪn/","pos":"v.","def":"获得","sen":"The policeman is obtaining evidence.","trans":"这个警察正在取证。","mne":"ob向前 + tain抓 → obtain获得"},{"word":"obvious","ipa":"/ˈɑːbviəs/","pos":"adj.","def":"明显的，显而易见的","sen":"It is obvious that he ate the cake.","trans":"很明显是他吃了蛋糕。","mne":"ob逆，倒，加强状态 + vi=way道路 + ous形容词后缀 → 在路上逆行很容易被发现 → obvious明显的，显而易见"},{"word":"obviously","ipa":"/ˈɑːbviəsli/","pos":"adv.","def":"明显地","sen":"He's obviously far taller than me.","trans":"他明显比我高。","mne":""},{"word":"occasion","ipa":"/əˈkeɪʒn/","pos":"n.","def":"场合，时候，活动；时机，机会；  v.引起；导致","sen":"In China, New Year's Eve is an important family occasion.","trans":"在中国，除夕夜是重要的家庭团聚时刻。","mne":"oc加强 + cas降临 + ion 表名词 → 突然落下的瞬间 → occasion时机；场合"},{"word":"occasional","ipa":"/əˈkeɪʒənl/","pos":"adj.","def":"偶然的；偶尔的；临时的","sen":"The lucky farmer's discovery of the treasure was occasional.","trans":"那个幸运的农民偶然发现了宝藏。","mne":"oc使 ＋ cas落下 ＋ ion名词后缀 ＋ al…的 → occasional偶然的，非经常的"},{"word":"occupation","ipa":"/ˌɑkjuˈpeɪʃn/","pos":"n.","def":"占领，占据；职业；消遣","sen":"During the war, the occupation of strategic locations was crucial for victory.","trans":"战争期间，占领战略要地对取胜至关重要。","mne":"oc表强调 + cup拿，抓，握住 + ation表名词 → 占领，占据；职业"},{"word":"occupy","ipa":"/ˈɑːkjupaɪ/","pos":"v.","def":"占据，占领；任职，执政","sen":"The mouse almost occupies the whole chair. ","trans":"这只老鼠几乎把整把椅子都给占了。","mne":"oc再次 + cupy抓 → 抓住地盘 → occupy占领"},{"word":"occur","ipa":"/əˈkɜːr/","pos":"v.","def":"发生；出现，存在","sen":"Car accidents usually occur very quickly.","trans":"车祸通常发生在一瞬间。","mne":"oc向 + cur 跑 → 某个方向跑 → occur发生"},{"word":"occurrence","ipa":"/əˈkɜːrəns/","pos":"n.","def":"发生，出现","sen":"Given that whale sightings are a rare occurrence, these guys are very lucky!","trans":"考虑到目睹鲸鱼的事件极少出现，这些人可真是幸运！","mne":"occur发生 + r + ence名词后缀 → occurrence 发生"},{"word":"ocean","ipa":"/ˈoʊʃn/","pos":"n.","def":"海洋，洋，大海","sen":"Between Asia and America lies the world's largest ocean—the Pacific Ocean.","trans":"位于亚洲和美洲之间的是世界上最大的海洋——太平洋。","mne":""},{"word":"october","ipa":"/ɑːkˈtoʊbər/","pos":"n.","def":"十月","sen":"October is my favorite month of the year.","trans":"十月是一年中我最喜欢的月份。","mne":""},{"word":"odd","ipa":"/ɑːd/","pos":"adj.","def":"奇怪的；古怪的；奇数的","sen":"It's odd that the wolf simply jumps over the lamb instead of eating it.","trans":"奇怪的是，狼只是从羔羊身上跳过，没有吃掉它。","mne":""},{"word":"of","ipa":"/əv/","pos":"prep.","def":"属于......；关于......","sen":"This picture is of my family.","trans":"这是我的全家福。","mne":""},{"word":"off","ipa":"/ɔːf/","pos":"prep.","def":"离开；脱落，落下；  adv.离开；（切）断；  int.走开；  adj.空闲的","sen":"Please keep off the grass.","trans":"请勿践踏草坪。","mne":""},{"word":"offence","ipa":"/əˈfens/","pos":"n.","def":"冒犯；犯罪","sen":"His words caused offence to his friend.","trans":"他说的话对他的朋友造成了冒犯。","mne":""},{"word":"offend","ipa":"/əˈfend/","pos":"v.","def":"冒犯；违反（法律、规定等）","sen":"Comments from online haters offended her.","trans":"网络喷子的言论冒犯了她。","mne":"of反对 + fend打击 → 一再打击 → offend冒犯，得罪"},{"word":"offense","ipa":"/əˈfɛns/, /ˈɔˌfɛns/","pos":"n.","def":"犯罪，冒犯，过错，触怒，犯规（读作/əˈfɛns/）","sen":"The dog takes offense at its owner and looks angry.","trans":"狗狗被主人惹恼了，看起来十分生气。","mne":""},{"word":"offensive","ipa":"/əˈfensɪv/","pos":"adj.","def":"冒犯的，无礼的；攻击性的","sen":"It's offensive to invade someone's privacy.","trans":"侵犯别人的隐私是很冒犯的行为。","mne":"of反对 + fens保护 + ive名词后缀 → 反对保护 → 侵犯 → 冒犯"},{"word":"offer","ipa":"/ˈɔfər/","pos":"v.","def":"提供；主动提出，自愿给予；  n.提供；提议；报价，发盘","sen":"The woman offers the man a gift.","trans":"这个女人给了男人一份礼物。","mne":"of一再 + fer带来 → 一再带来 → offer提供"},{"word":"office","ipa":"/ˈɑːfɪs/","pos":"n.","def":"办公室","sen":"I like office work—I can wear smart clothes and stay indoors.","trans":"我喜欢在办公室工作——可以穿得干净整洁而且不用外出。","mne":"of=opi工作 + fic做 + e名词后缀 → office办公室"},{"word":"officer","ipa":"/ˈɑːfɪsər/","pos":"n.","def":"官员；高级职员；军官","sen":"The two officers have both agreed on the latest policy.","trans":"两名官员对最新的政策达成了共识。","mne":"office办公室 + er表人 → 坐办公室的人 → officer警官，官员"},{"word":"official","ipa":"/əˈfɪʃl/","pos":"n.","def":"官员；  adj.官方的","sen":"The government official signed an important document at his desk.","trans":"政府官员在桌上签署了一个重要文件。","mne":"offic官方的 + ial属于……的 → 官方的，法定的"},{"word":"often","ipa":"/ˈɔːfn/","pos":"adv.","def":"经常，时常，屡次","sen":"It often rains in London.","trans":"伦敦经常下雨。","mne":""},{"word":"oftentimes","ipa":"/ˈɔːfntaɪmz/","pos":"adv.","def":"屡次，常常","sen":"Oftentimes, I have trouble getting up early.","trans":"我常常很难早起。","mne":""},{"word":"oil","ipa":"/ɔɪl/","pos":"n.","def":"石油","sen":"Oil is sometimes called black gold.","trans":"石油有时会被称为黑色的黄金。","mne":""},{"word":"ok","ipa":"/oʊˈkeɪ/","pos":"adj.","def":"好的；还不错的；很好的","sen":"OK! No problem!","trans":"好的！没问题！","mne":""},{"word":"okay","ipa":"/oʊˈkeɪ/","pos":"adj.","def":"不错的；  adv.可以；  int.行","sen":"This clay tastes okay.","trans":"这块泥土尝起来还可以。","mne":""},{"word":"old","ipa":"/oʊld/","pos":"adj.","def":"年纪大的，老的；旧的","sen":"Though you are old, I will always love you.","trans":"虽然你老了，我也永远爱你。","mne":""},{"word":"olympics","ipa":"/oʊˈlɪmpɪks/","pos":"n.","def":"奥林匹克运动会","sen":"I will be in Beijing for the next Summer Olympics.","trans":"我将参加在北京举行的下届夏季奥运会。","mne":""},{"word":"omit","ipa":"/əˈmɪt/","pos":"v.","def":"删去，省去，忽略；遗漏","sen":"You should omit those repeated words in the article.","trans":"你应该把文章里那些重复的词删掉。","mne":"o表强调 + mit放手，送出 → omit除；省略"},{"word":"on","ipa":"/ɑːn/","pos":"prep.","def":"在……上","sen":"There's a phone on the desk.","trans":"桌上有一部手机。","mne":""},{"word":"once","ipa":"/wʌns/","pos":"conj.","def":"一旦，一...就；  n.一次；  adv.以前，曾经","sen":"Once they knew the price of that house, they decided to take it.","trans":"他们一知道那房子的价格，就决定买下它。","mne":"on=one一 + ce次 → 一次"},{"word":"one","ipa":"/wʌn/","pos":"num.","def":"一，一个","sen":"We only have one planet.","trans":"我们只有一个星球。","mne":""},{"word":"oneself","ipa":"/wʌnˈself/","pos":"pron.","def":"亲自","sen":"One can celebrate one's birthday by oneself.","trans":"独自一人也可以庆祝自己的生日。","mne":"one一人 + self自己 → oneself自身，亲自"},{"word":"ongoing","ipa":"/ˈɑːnɡoʊɪŋ/","pos":"adj.","def":"仍在进行的","sen":"They are having an ongoing argument.","trans":"他们正争论不休。","mne":""},{"word":"onion","ipa":"/ˈʌnjən/","pos":"n.","def":"洋葱","sen":"She is slicing the onion with a knife.","trans":"她正在用刀切洋葱。","mne":""},{"word":"online","ipa":"/ˈɑːnlaɪn/","pos":"adj.","def":"在线的，联网的；  adv.在线地；在线","sen":"Online shopping provides a more convenient way of shopping.","trans":"网络购物是一种更方便的购物途径。","mne":""},{"word":"only","ipa":"/ˈoʊnli/","pos":"adj.","def":"唯一的，仅有的；  adv.只，仅仅","sen":"She is the only one on the road.","trans":"她是路上唯一的行人。","mne":"one一 + ly表形容词 → only唯一的"},{"word":"onto","ipa":"/ˈɑːntu/","pos":"prep.","def":"到...之上，向...之上，朝...之上","sen":"He stepped onto the bamboo raft.","trans":"他踏上了竹筏。","mne":""},{"word":"open","ipa":"/ˈoʊpən/","pos":"v.","def":"打开，开门；  adj.开放的；营业的；  n.户外，野外","sen":"Why did you open so many books?","trans":"你为什么翻开那么多本书？","mne":""},{"word":"opening","ipa":"/ˈəʊpənɪŋ/","pos":"n.","def":"开口；开始；职位空缺；  adj.开始的，开场的","sen":"We can escape the cave through this opening.","trans":"我们可以从这个开口逃出洞穴。","mne":"open开启 + ing名词后缀 → opening开幕，开口"},{"word":"opera","ipa":"/ˈɑːprə/","pos":"n.","def":"歌剧","sen":"The woman is performing a wonderful opera on the stage.","trans":"那位女士正在舞台上表演一场精彩的歌剧。","mne":""},{"word":"operate","ipa":"/ˈɑːpəreɪt/","pos":"v.","def":"做手术；运转；操作","sen":"The doctors are operating on the patient.","trans":"医生们正在给病人做手术。","mne":"oper工作 + ate表示做、造成 → 行动起来 → operate操作；施行手术"},{"word":"operation","ipa":"/ˈɑːpəˈreɪʃən/","pos":"n.","def":"手术；运转，运行","sen":"The doctors are performing the operation carefully.","trans":"医生们在小心地做手术。","mne":"operat操作 + ion名词后缀 → operation操作"},{"word":"operational","ipa":"/ˌɑːpəˈreɪʃənl/","pos":"adj.","def":"操作的，运转的","sen":"The machine is operational, sir — you can turn it on now.","trans":"机器可以使用了，先生。现在您可以打开它了。","mne":"oper工作 + ation表名词 + al…的 → 能操作使用的 → operational操作的"},{"word":"operator","ipa":"/ˈɑːpəreɪtər/","pos":"n.","def":"（电话）接线员；操作人员","sen":"Ask for the operator—she’ll know the right phone number.","trans":"你可以询问接线员，她知道正确的电话号码。","mne":"oper工作 + ator表示做...工作的人或物 → operator操作人员，接线员"},{"word":"opinion","ipa":"/əˈpɪnjən/","pos":"n.","def":"意见，看法，观点","sen":"Different people have different opinions about the same thing.","trans":"不同的人对于同样的事物有不同的看法。","mne":"opin想，判断 + ion表名词 → opinion看法"},{"word":"opponent","ipa":"/əˈpoʊnənt/","pos":"n.","def":"对手，敌手，对抗者","sen":"The boxer punched his opponent severely！","trans":"这个拳击手痛击对手！","mne":"op反 + pon放置 + ent形容词后缀 → 反着放 → 对立的；对手"},{"word":"opportunity","ipa":"/ˌɑːpərˈtuːnəti/","pos":"n.","def":"机会，良机；时机","sen":"Look at the shooting stars! Let's seize the opportunity to make a wish.","trans":"看，有流星！让我们抓住机会来许个愿吧。","mne":"opportun有机会的 + ity名词后缀 → opportunity机会"},{"word":"oppose","ipa":"/əˈpoʊz/","pos":"v.","def":"反对；反抗","sen":"The boy opposes his father's smoking and tells him to stop.","trans":"男孩反对父亲吸烟，并告诉他不要抽了。","mne":"op反 + pose放 → oppose反对"},{"word":"opposite","ipa":"/ˈɑːpəzɪt/","pos":"adj.","def":"相反的；对立的；对面的；  adv.对立地；反面地；  n.对立物；反面，对立面","sen":"She is running in the opposite direction of all the others.","trans":"她正朝着与其他所有人相反的方向跑。","mne":"oppos反对 + ite形容词后缀 → opposite反对的，反的"},{"word":"opposition","ipa":"/ˌɑːpəˈzɪʃn/","pos":"n.","def":"反对","sen":"They both have shown their opposition to the other direction.","trans":"他们同时表示了对去往另一个方向的反对。","mne":""},{"word":"opt","ipa":"/ɑːpt/","pos":"v.","def":"选择","sen":"She opted for music class because she just wasn't interested in any others.","trans":"她选择了音乐课，因为她对其他课都不感兴趣。","mne":""},{"word":"optimal","ipa":"/ˈɑːptɪməl/","pos":"adj.","def":"最佳的，最适的；最佳的，最理想的","sen":"The doctor adjusted the medication dose to achieve optimal therapeutic effects.","trans":"医生调整了药物剂量以获得最佳治疗效果。","mne":"optim最好 + al表示属于...的、具有...性质的 → adj.最佳的；最理想的"},{"word":"optimism","ipa":"/ˈɑːptɪmɪzəm/","pos":"n.","def":"乐观，乐观主义","sen":"His optimism always brings himself confidence and happiness.","trans":"他的乐观总会给他带来自信与快乐。","mne":"optim最好 + ism主义 → optimism乐观主义"},{"word":"optimistic","ipa":"/ˌɑːptɪˈmɪstɪk/","pos":"adj.","def":"乐观的","sen":"She stays optimistic, despite her condition.","trans":"即使身体很差，她也始终保持乐观。","mne":"optim最好 + ist人 + ic…的 → optimistic乐观的"},{"word":"option","ipa":"/ˈɑːpʃn/","pos":"n.","def":"选择，选项","sen":"You have two options for lunch, pasta or pizza.","trans":"午饭你有两种选择：要么吃意面，要么吃比萨。","mne":"opt选择 + ion名词后缀 → 选择"},{"word":"optional","ipa":"/ˈɑːpʃənəl/","pos":"adj.","def":"可选择的；非强制的","sen":"The optional subjects are usually more interesting.","trans":"选修课通常更有意思。","mne":"opt选择 + ion表名词 + al形容词后缀 → optional可任意选择的"},{"word":"or","ipa":"/ɔːr/","pos":"conj.","def":"或；否则","sen":"Which fruit is your favorite, apple or peach?","trans":"你最喜欢哪种水果，苹果还是桃子？","mne":""},{"word":"oral","ipa":"/ˈɔrəl/","pos":"adj.","def":"口腔的；口头的，口语的","sen":"The dentist recommended an oral examination every six months.","trans":"牙医建议每六个月进行一次口腔检查。","mne":""},{"word":"orange","ipa":"/ˈɔːrɪndʒ/   ","pos":"adj.","def":"橙色的，橘色的；  n.橙色；橘子，橙子","sen":"The sofa is orange.","trans":"这个沙发是橘色的。","mne":""},{"word":"orchestra","ipa":"/ˈɔːrkɪstrə/","pos":"n.","def":"管弦乐队","sen":"The orchestra is playing in a big theater.","trans":"这支管弦乐队正在大剧院里演奏。","mne":"orches舞蹈 + tra地点 → 古希腊剧院里搞歌唱配乐的人站的地方，引申为搞配乐的一群人 → n.管弦乐队"},{"word":"order","ipa":"/ˈɔːrdər/","pos":"n.","def":"【数】顺序；条理；订单；指令，命令；【生】目；  v.订购；命令；点餐；安排，整理","sen":"What's the order of three?","trans":"三是第几个数呢？","mne":""},{"word":"orderly","ipa":"/ˈɔːrdərli/","pos":"adj.","def":"有秩序的，整齐的，有条不紊的","sen":"Put the files in an orderly sequence.","trans":"把这些文件按一定的顺序放好。","mne":"order顺序 + ly副词后缀 → orderly 依次的，有序的"},{"word":"ordinary","ipa":"/ˈɔːrdəˌneri/","pos":"adj.","def":"普通的，平凡的，平常的","sen":"I'm just an ordinary man.","trans":"我只是一个普通的男人。","mne":"ordin排列，安排 + ary → 按安排定好的 → ordinary普通的，平常的"},{"word":"organ","ipa":"/ˈɔːrɡən/ ","pos":"n.","def":"器官；风琴；机关，机构","sen":"The heart, brain and lungs are examples of vital organs in the human body.","trans":"心脏、大脑、肺等是人体内的重要器官。","mne":""},{"word":"organic","ipa":"/ɔːrˈɡænɪk/","pos":"adj.","def":"有机的；器官的","sen":"I hate studying organic chemistry, but I must if I want to become a doctor.","trans":"我讨厌学有机化学，但如果我想成为一个医生的话，我就必须学。","mne":"organ器官 + ic形容词...的 → 器官的"},{"word":"organisation","ipa":"/ˌɔːrɡənəˈzeɪʃn/","pos":"n.","def":"团体，机构；组织体制","sen":"Our organisation has contacts all around the world.","trans":"我们的机构在全球都有联系。","mne":"organis（e）组织 + ation表名词 → organisation组织，团体"},{"word":"organise","ipa":"/ˈɔːrɡənaɪz/","pos":"v.","def":"安排，组织（=organize）","sen":"The boss hired an assistant to help organise her daily schedule.","trans":"老板雇佣了一名助手来帮忙安排她的日常行程。","mne":""},{"word":"organism","ipa":"/ˈɔːrɡənɪzəm/","pos":"n.","def":"生物体，有机体；有机体，生物；有机的组织","sen":"This powerful antibiotic can kill a wide range of harmful organisms.","trans":"这种强效抗生素能杀灭多种有害生物体。","mne":"organ器官 + ism主义 → organism有机体"},{"word":"organization","ipa":"/ˌɔːrɡənəˈzeɪʃn/","pos":"n.","def":"组织，体制，团体，机构","sen":"I'm the leader of this organization.","trans":"我是这个组织的领导。","mne":"organ器官，组织 + ization表名词，发展过程 → organization组织"},{"word":"organize","ipa":"/ˈɔːrɡənaɪz/","pos":"v.","def":"整理；组织；安排；筹办","sen":"He is trying to organize the papers. ","trans":"他在努力整理文件。","mne":"organ器官 + ize动词后缀 → organize组织，整理"},{"word":"orient","ipa":"/ˈɔːrient/","pos":"v.","def":"定……的方位；使适应；使朝向；  n.【the Orient】东方","sen":"I used a compass to orient myself.","trans":"我用指南针来帮我确定方向。","mne":"ori升起，开始 ＋ ent形容词后缀 → [太阳]升起的 → orient东方的"},{"word":"orientation","ipa":"/ˌɔːriənˈteɪʃən/","pos":"n.","def":"(任职、上学等之前的) 情况介绍；训练；定向，方向","sen":"New employees are given an orientation by the company.","trans":"公司对新员工进行任职培训。","mne":"orient东方 + ation名词后缀 → 向东方 → orientation定位"},{"word":"origin","ipa":"/ˈɔːrɪdʒɪn/","pos":"n.","def":"起源；由来，来源；出身","sen":"The origin of humankind is still mysterious, but we think our ancestors lived in the trees.","trans":"虽然人类的起源仍然是谜，但是我们认为我们的祖先生活在树上。","mne":"origin=orig升起，开始 → [生命]开始 → origin起源"},{"word":"original","ipa":"/əˈrɪdʒənl/","pos":"adj.","def":"原始的，最初的；有独创性的，独创的；  n.原件；原作","sen":"This is the original manuscript of the famous novel.","trans":"这是这部著名小说的原稿。","mne":"origin起源 + al形容词后缀 → original原始的，独创的"},{"word":"other","ipa":"/ˈʌðər/","pos":"adj.","def":"其他的，另外的","sen":"No, I don't want to buy apples. I want some other fruit.","trans":"不，我不想买苹果。我想买点儿其他的水果。","mne":"o超过 + ther形容词比较级后缀 → other其他的，另外的"},{"word":"otherwise","ipa":"/ˈʌðərwaɪz/","pos":"adv.","def":"否则；除此之外；在其他方面，另，亦","sen":"Take care! Otherwise you will fall down!","trans":"小心！不然你会摔倒！","mne":"other另外的 + wise方向，状态 → otherwise要不然"},{"word":"ought to","ipa":"/ˈɔːt tu/","pos":"phr.","def":"应该","sen":"When you study, you ought to sit up straight.","trans":"学习时，你应该身体坐直。","mne":""},{"word":"our","ipa":"/'aʊər/","pos":"det.","def":"我们的","sen":"Our car is white while his car is blue.","trans":"我们的车是白色的，而他的车是蓝色的。","mne":""},{"word":"ours","ipa":" /aʊrz/","pos":"pron.","def":"我们的","sen":"The world is ours, so we should protect it.","trans":"这个世界是我们的，所以我们应该保护它。","mne":""},{"word":"ourselves","ipa":"/ɑːrˈselvz/","pos":"pron.","def":"我们自己","sen":"We took this picture of ourselves.","trans":"我们给自己拍了这张照片。","mne":""},{"word":"out","ipa":"/aʊt/","pos":"adv.","def":"（表示不在原状态）脱离；外，超过，出，向外；（从…里）出来","sen":"I feel left out of the group.","trans":"我感觉被落单了。","mne":""},{"word":"outbreak","ipa":"/ˈaʊtbreɪk/","pos":"n.","def":"（战争、疾病等坏事的）爆发，突然发生","sen":"The soldiers were adequately prepared for the outbreak of war.","trans":"战士们在战争爆发前做了充分的准备。","mne":"out向外 + break破裂 → 向外破裂 → outbreak爆发"},{"word":"outcome","ipa":"/ˈaʊtkʌm/","pos":"n.","def":"结果，后果","sen":"The outcome of the boxing game was a draw.","trans":"拳击比赛的结果是个平局。","mne":"out出 + come来 → outcome结果"},{"word":"outdoors","ipa":"/ˌaʊtˈdɔːrz/","pos":"adv.","def":"在户外，在野外；  n.户外，野外，郊外","sen":"She went outdoors for some fresh air.","trans":"她到户外去呼吸新鲜空气。","mne":"outdoor户外 + s表副词 → outdoors在户外"},{"word":"outlet","ipa":"/ˈaʊtlet/","pos":"n.","def":"出口；表现机会，发泄方法；折扣店","sen":"Water came out of the wall through several outlets.","trans":"水从墙上的几个出口中排了出来。","mne":"out外、出 + let名词后缀 → outlet出口；排出"},{"word":"outline","ipa":"/ˈaʊtlaɪn/","pos":"n.","def":"外形，轮廓；概要；  v.描绘，画出……的轮廓","sen":"The girl drew an outline of the model.","trans":"这个女孩画出了模特的轮廓。","mne":"out外 + line线条 → outline轮廓"},{"word":"outlook","ipa":"/ˈaʊtlʊk/","pos":"n.","def":"景色，风光；观点；前景","sen":"The outlook of the mountains is very grand.","trans":"群山的景色非常壮观。","mne":"out胜过，超过 + look看 → outlook观点，看法，展望"},{"word":"output","ipa":"/ˈaʊtpʊt/","pos":"n.","def":"产量；  v.输出","sen":"The oven's output is 48 loaves per hour.","trans":"这个烤炉的产量是每小时48条面包。","mne":"out出 + put放 → output产出"},{"word":"outside","ipa":"/ˌaʊtˈsaɪd/, /ˈaʊtˌsaɪd/","pos":"adv.","def":"在户外，在外面，向外面；  n.外表，外（表）面（读作/ˈaʊtˌsaɪd/）；外部；  adj.外部的，外面的","sen":"I like my kids to play outside on the grass.","trans":"我喜欢孩子们到外面的草地上玩耍。","mne":"out外，出 + side旁边 → outside在外边"},{"word":"outstanding","ipa":"/aʊtˈstændɪŋ/","pos":"adj.","def":"杰出的，出众的；未解决的，未完成的","sen":"He is an outstanding example of entrepreneurs.","trans":"他是企业家中的杰出代表。","mne":"outstand突出 + ing形容词后缀 → outstanding突出的，杰出的"},{"word":"outward","ipa":"/ˈaʊtwərd/","pos":"adj.","def":"外面的","sen":"We all enjoy this outward journey.","trans":"我们都很享受这次户外旅行。","mne":"out外边 + ward向…… → outward向外的，向外"},{"word":"outwards","ipa":"/ˈaʊtwərdz/","pos":"adv.","def":"向外地","sen":"The water flows outwards from the pipe.","trans":"水从管道中向外流。","mne":"out外 + wards表方向 → 向外地"},{"word":"oven","ipa":"/ˈʌvn/","pos":"n.","def":"烤箱","sen":"This oven is energy efficient and has multiple cooking modes.","trans":"这个烤箱能效高，且有多种烹饪模式。","mne":""},{"word":"over","ipa":"/ˈoʊvər/","pos":"adv.","def":"结束；越过","sen":"By the time we arrived the party was over.","trans":"我们到达时派对已经结束了。","mne":""},{"word":"overall","ipa":"/ˈoʊvərˌɔl/, /oʊvərˈɔl/","pos":"adj.","def":"全面的，全部的；  adv.一般来说，大致上","sen":"A good student should maintain overall development.","trans":"三好学生应该全面发展。","mne":"over覆盖 + all全部 → 覆盖全部 → overall全部的，全面的"},{"word":"overcoat","ipa":"/ˈoʊvərkoʊt/","pos":"n.","def":"长大衣","sen":"This overcoat keeps me warm and comfortable in winter.","trans":"这件大衣让我冬天保持温暖和舒适。","mne":"over在上，在外 + coat衣服 → 在衣服上的衣服 → overcoat外套"},{"word":"overcome","ipa":"/ˌoʊvərˈkʌm/","pos":"v.","def":"克服；战胜","sen":"The passenger overcame his fear of taking a flight.","trans":"这位乘客克服了他坐飞机的恐惧。","mne":"over在上 + come来 → 来到上面 → overcome战胜，克服"},{"word":"overhead","ipa":"/ˈoʊvərhed/","pos":"adv.","def":"在头顶，在上面；  adj.头顶上的","sen":"Look！There is a plane flying overhead.","trans":"看，有一架飞机正在头顶上飞！","mne":"over在上 + head头 → overhead在头顶上的"},{"word":"overhear","ipa":"/ˌoʊvərˈhɪr/","pos":"v.","def":"无意中听到，偷听到","sen":"This father overheard his children talking.","trans":"这位父亲偶然听到了他儿女的谈话。","mne":"over在外 + hear听到 → 无意中听到,偷听到"},{"word":"overload","ipa":"/ˌoʊvərˈloʊd/","pos":"v.","def":"使超载，使过载；  n.过重负担","sen":"That bicycle is overloaded, and it's so dangerous.","trans":"这辆自行车超载了，这太危险了。","mne":"over过度、太甚 + load负载，装载 → 使超载，超过负荷"},{"word":"overlook","ipa":"/ˌoʊvərˈlʊk/","pos":"v.","def":"忽视，未注意到","sen":"He's so busy on his computer that he's totally overlooked his son.","trans":"他忙着看电脑，全然忽视了他的儿子。","mne":"over在上，在外 + look看 → 在上面看 → 俯视；疏忽"},{"word":"overnight","ipa":"/ˌoʊvərˈnaɪt/, /ˈoʊvərˌnaɪt/","pos":"adv.","def":"整夜，一夜之间，突然（读作/ˌoʊvərˈnaɪt/）；  adj.突然的；夜间的","sen":"The man worked overnight to finish the work on time.","trans":"这个男人为了按时完工，一整晚都在加班。","mne":"over越过 + night夜 → overnight一夜；突然"},{"word":"overseas","ipa":"/ˌoʊvərˈsiːz/","pos":"adv.","def":"在海外；  adj.外国的；海外的","sen":"We export the goods overseas.","trans":"我们把货物出口到海外。","mne":"over越过 + sea海洋 + s → overseas海外"},{"word":"overstate","ipa":"/ˌoʊvərˈsteɪt/","pos":"v.","def":"夸大","sen":"He is overstating what really happened to gain people's sympathy.","trans":"他为了博得大家的同情而夸大了事实。","mne":""},{"word":"overtake","ipa":"/ˌoʊvərˈteɪk/","pos":"v.","def":"超过，赶上","sen":"The flying car could easily overtake the racing car.","trans":"这辆飞车可以轻松超过那辆赛车。","mne":"over越过 + take得到 → 追上,超过"},{"word":"overweight","ipa":"/ˌoʊvərˈweɪt/","pos":"adj.","def":"超重的；  n.超重","sen":"The girl with yellow hair is overweight.","trans":"这个黄头发的女孩超重了。","mne":"over过度 + weight重量 → overweight超重的"},{"word":"overwhelming","ipa":"/ˌoʊvərˈwelmɪŋ/","pos":"adj.","def":"压倒性的；巨大的","sen":"The red team won an overwhelming victory against the blue team in the election.","trans":"红队在选举中战胜了蓝队，取得了压倒性的胜利。","mne":"over过度 + whelm压倒 + ing形容词后缀 → overwhelming势不可挡的，压倒的"},{"word":"owe","ipa":"/oʊ/","pos":"v.","def":"归功于；欠（债、情）；欠钱","sen":"I owe my full mark to this phone app!","trans":"我把我的满分归功于这个手机应用！","mne":""},{"word":"own","ipa":"/oʊn/","pos":"v.","def":"有，拥有；  adj.自己的，本人的","sen":"She owns this workshop. She's the boss.","trans":"她拥有这间工作室，她就是老板。","mne":""},{"word":"owner","ipa":"/ˈoʊnər/","pos":"n.","def":"所有者，物主，主人","sen":"He is the owner of this famous noodle stand.","trans":"手打是有名的一乐拉面馆的拥有者。","mne":""},{"word":"ownership","ipa":"/ˈoʊnərʃɪp/","pos":"n.","def":"所有权","sen":"The couple have the certificate to prove their ownership of this house.","trans":"这对夫妻拥有房产证可以证明他们对这栋房子的所有权。","mne":"owner所有者 + ship表名词 → ownership所有(权)，所有制"},{"word":"ox","ipa":"/ɑːks/","pos":"n.","def":"公牛","sen":"The strong ox is angry now.","trans":"这头强壮的公牛现在很生气。","mne":""},{"word":"oxygen","ipa":"/ˈɑːksɪdʒən/","pos":"n.","def":"氧；氧气，氧","sen":"Oxygen is essential for cellular respiration in the human body.","trans":"氧气对人体细胞呼吸至关重要。","mne":"oxy含氧的 + gen出生，产生 → 氧气"},{"word":"pace","ipa":"/peɪs/","pos":"n.","def":"步伐；速度；  v.踱步","sen":"They were walking at a fast pace.","trans":"他们正在快步走。","mne":""},{"word":"pack","ipa":"/pæk/","pos":"v.","def":"收拾，打包；把......包起来；塞满，挤满；  n.行李；背包；小盒，小包；群","sen":"The boy is packing his clothes for the trip.","trans":"这个男孩在打包旅行需要的衣物。","mne":""},{"word":"package","ipa":"/ˈpækɪdʒ/","pos":"n.","def":"包裹；一揽子，一整套；  v.将……包装好","sen":"I received a package with a card.","trans":"我收到一个带卡片的包裹。","mne":"pack包裹 + age表物 → package包裹"},{"word":"packet","ipa":"/ˈpækɪt/","pos":"n.","def":"小袋，小包装","sen":"This packet of potato chips has been opened.","trans":"这袋薯片已经被打开了。","mne":"pack包捆 + et小东西→ packet小包"},{"word":"page","ipa":"/peɪdʒ/","pos":"n.","def":"页，页面","sen":"Please turn your book to the next page.","trans":"请把书翻到下一页。","mne":""},{"word":"pain","ipa":"/peɪn/","pos":"n.","def":"痛，痛苦；努力，劳苦","sen":"He is suffering great pain in his neck and back.","trans":"他感觉脖颈和后背特别疼。","mne":""},{"word":"painful","ipa":"/ˈpeɪnfl/","pos":"adj.","def":"疼痛的；痛苦的；艰难的","sen":"Oow! I hit my foot on the table! It's so painful!","trans":"噢！我的脚撞到桌子了！疼死了！","mne":"pain疼痛 + ful形容词后缀 → painful痛苦的"},{"word":"paint","ipa":"/peɪnt/","pos":"v.","def":"给…刷涂料，给……刷油漆；绘画；描绘；  n.油漆；颜料","sen":"I will paint my wall green.","trans":"我要把墙壁涂成绿色。","mne":""},{"word":"painter","ipa":"/ˈpeɪntər/","pos":"n.","def":"画家","sen":"The painter is painting a picture.","trans":"画家正在画画。","mne":"paint画画 + er表人 → 漆工，画家，绘画者"},{"word":"painting","ipa":"/ˈpeɪntɪŋ/","pos":"n.","def":"绘画；画作，油画","sen":"The kid is focused on her painting of a small house.","trans":"这个孩子正专注于她那幅画着小房子的绘画作品。","mne":"paint画 + ing表名词 → painting画作，绘画"},{"word":"pair","ipa":"/per/ ","pos":"n.","def":"一对，一双；  v.（使）成对，配对","sen":"A pair of parrots will be happier than a lonely one.","trans":"一对鹦鹉会比一只鹦鹉要幸福。","mne":""},{"word":"palace","ipa":"/ˈpæləs/","pos":"n.","def":"宫殿","sen":"The first snow this winter covered the palace in a blanket of white.","trans":"今年冬天的初雪给这座宫殿盖上了一层雪白的毯子。","mne":""},{"word":"pale","ipa":"/peɪl/","pos":"adj.","def":"苍白的，灰白的；浅色的，淡色的","sen":"Recent stress from work left him pale.","trans":"近期的工作压力使他脸色苍白。","mne":""},{"word":"palm","ipa":"/pɑːm/","pos":"n.","def":"手掌，手心；棕榈树","sen":"She showed me the flower in her palm.","trans":"她给我看了她手心里的花。","mne":""},{"word":"pamphlet","ipa":"/ˈpæmflət/","pos":"n.","def":"小册子","sen":"The pamphlet will explain how our product works.","trans":"这本小册子介绍了产品的工作原理。","mne":"pam所有 + phlet热爱，亲爱的 -> 给喜欢的人的情书 -> 小册子"},{"word":"panel","ipa":"/ˈpænl/","pos":"n.","def":"讨论小组，专家咨询组","sen":"The candidate was selected by the panel.","trans":"候选人是由讨论小组选出的。","mne":""},{"word":"paper","ipa":"/ˈpeɪpər/","pos":"n.","def":"纸；报纸；试卷，论文","sen":"I like to make notes on a small piece of paper.","trans":"我喜欢在小纸片上做笔记。","mne":""},{"word":"parade","ipa":"/pəˈreɪd/  ","pos":"n.","def":"游行；  v.游行，（使）列队行进","sen":"The New Year parade in Chinatown is always a popular event.","trans":"在唐人街举办的新年大游行总是一项受人欢迎的活动。","mne":""},{"word":"paragraph","ipa":"/ˈpærəɡræf/","pos":"n.","def":"（文章的）段，节","sen":"Please summarize the main point of this paragraph.","trans":"请总结这一段的大意。","mne":"para旁、靠近、外 + graph=write，表示写，图 → 靠近图表旁边的文字 → (文章的)段，节"},{"word":"parallel","ipa":"/ˈpærəlel/","pos":"adj.","def":"平行的；相似的","sen":"The boy drew parallel lines in his exercise book.","trans":"这个男孩在他的练习本上画平行线。","mne":"para在旁边 + llel互相 → parallel平行的"},{"word":"parameter","ipa":"/pəˈræmɪtər/","pos":"n.","def":"参（变）数；参量；决定因素；界限","sen":"The math is very complicated; there are all kinds of parameters you need to take into account.","trans":"这种数学问题很复杂，有各种参数需要考虑。","mne":"para=beside ＋ meter=measure计量，测量等 → parameter参（变）数；参量"},{"word":"parcel","ipa":"/ˈpɑːrsl/","pos":"n.","def":"包裹；  v.打包，裹好","sen":"\"I have some parcels for you,\" said the mailman.","trans":"“有您的一些包裹。”邮递员说道。","mne":"par部分 + cel表名词 → 小包裹 → parcel包裹"},{"word":"pardon","ipa":"/ˈpɑːrdn/","pos":"v.","def":"赦免，原谅，宽恕；  excl.请再说一遍；  n.赦免，原谅；原谅；宽恕","sen":"The emperor pardoned the prisoner.","trans":"皇帝赦免了那个囚犯。","mne":""},{"word":"parent","ipa":"/ˈperənt/","pos":"n.","def":"父亲或母亲","sen":"The parents raised their son in a loving environment.","trans":"父母在充满爱的环境中养育了他们的孩子。","mne":"par生产，生出孩子 + ent表名词 → parent父母"},{"word":"park","ipa":"/pɑːrk/","pos":"n.","def":"公园；园区；  v.停车","sen":"Let's go for a walk in the park.","trans":"我们去公园散散步吧。","mne":""},{"word":"parliament","ipa":"/ˈpɑrləmənt/","pos":"n.","def":"国会；议会","sen":"These are the Houses of Parliament in London.","trans":"这是伦敦的议会大厦。","mne":"parlia=parley会谈 + ment表名词 → 议员们谈论政府的地方 → 议会，国会"},{"word":"part","ipa":"/pɑːrt/","pos":"n.","def":"部分，组成部分；零件；角色，份儿，作用；  v.分离，分开；分开","sen":"You can have part of the watermelon; I'll eat the rest.","trans":"你可以吃一部分西瓜，我吃剩下的。","mne":""},{"word":"partial","ipa":"/ˈpɑːrʃl/","pos":"adj.","def":"偏爱的，特别喜欢的；偏袒的，不公平的，有偏见的","sen":"She is more partial to sweet foods than savory foods.","trans":"比起咸的食物，她更偏爱吃甜食。","mne":"part部分 + ial形容词后缀 → partial部分的，偏心的"},{"word":"participant","ipa":"/pɑːrˈtɪsɪpənt/","pos":"n.","def":"参与者，参加者","sen":"Every participant focused on the lecture.","trans":"每个参与者都聚精会神地听了演讲。","mne":"parti准备 + cip拿，抓，握住 + ant名词后缀，表示人 → participant参与者"},{"word":"participate","ipa":"/pɑːrˈtɪsɪˌpeɪt/","pos":"v.","def":"参加","sen":"The teacher is happy when her students participate in class discussions.","trans":"当学生们参与课堂讨论时，老师很开心。","mne":"parti=part部分，分开 + cip抓住 + ate动词后缀 → 抓住机会成为其中一部分 → 参加"},{"word":"participation","ipa":"/partɪsɪˈpeɪʃən/","pos":"n.","def":"参与；参加","sen":"Classroom participation will be an important part of students' grades.","trans":"课堂参与将是学生成绩考核里很重要的一项。","mne":"parti部分 + cip 拿，握住 + ation 表名词 → 抓住部分 → 参与"},{"word":"particular","ipa":"/pərˈtɪkjələr/","pos":"adj.","def":"特别的，不寻常的；格外的；挑剔的，讲究的；  n.细节；详细资料","sen":"I chose five particular people.","trans":"我选出了五个与众不同的人。","mne":"partic少量 + ular形容词后缀 → particular特别的"},{"word":"particularly","ipa":"/pərˈtɪkjələrli/","pos":"adv.","def":"特别地，尤其","sen":"This guy particularly likes eating meat.","trans":"这个男人尤其爱吃肉。","mne":"particular特别的 + ly...地 → 有自己的部分地 → particularly特别地"},{"word":"partly","ipa":"/ˈpɑːrtli/","pos":"adv.","def":"部分地，在一定程度上","sen":"The girl's face is partly hidden by the lute.","trans":"女孩儿的脸被琵琶遮住了一部分。","mne":"part部分 + ly表副词 → partly部分地"},{"word":"partner","ipa":"/ˈpɑːrtnər/","pos":"n.","def":"伙伴，搭档；合伙人","sen":"We are all partners here. Let's work together to finish the job.","trans":"我们是好搭档，让我们齐心协力完成工作吧。","mne":"part部分，分开 + ner人 → 分开合作的人 → partner伙伴，搭档"},{"word":"party","ipa":"/ˈpɑːrti/","pos":"n.","def":"派对，聚会；政党，党派","sen":"Everyone had a great time at my birthday party.","trans":"在我的生日聚会上每个人都玩得很开心。","mne":""},{"word":"pass","ipa":"/pæs/","pos":"v.","def":"（时间）流逝；给，传递；通过；  n.及格","sen":"Time passed quickly.","trans":"时光飞逝。","mne":""},{"word":"passage","ipa":"/ˈpæsɪdʒ/","pos":"n.","def":"通道，走廊；段落；（文章）章节，段落","sen":"People with suitcases are walking through the passage.","trans":"人们提着箱子正从通道里走过。","mne":"pass通过 + age名词后缀，可表地点 → 可通过的地方 → 通道，走廊"},{"word":"passenger","ipa":"/ˈpæsɪndʒər/","pos":"n.","def":"乘客，旅客","sen":"All the passengers are seated and ready for the trip.","trans":"乘客们已经坐好了，准备开始旅程。","mne":"pass通过 + enger人 → 通过的人 → passenger乘客"},{"word":"passer-by","ipa":"/ˌpæsər ˈbaɪ/","pos":"n.","def":"过客，过路人","sen":"Some passers-by had seen the car accident.","trans":"一些路人目睹了这场车祸。","mne":""},{"word":"passion","ipa":"/ˈpæʃn/","pos":"n.","def":"强烈的情感，激情","sen":"He shouted \"Passion!\" and conveyed the idea that \"passion changes lives.\"","trans":"他高喊 “激情！”，并传达了 “激情改变生活 ”的理念。","mne":"pass感情 + ion名词后缀 → passion热情，激情"},{"word":"passionate","ipa":"/ˈpæʃənət/","pos":"adj.","def":"充满热情的","sen":"He always gets so passionate while playing the guitar.","trans":"弹吉他的时候，他总是充满了激情。","mne":"passion激情 + ate形容词后缀 → passionate热烈的"},{"word":"passive","ipa":"/ˈpæsɪv/","pos":"adj.","def":"被动的；消极的；  n.被动语态","sen":"Passive smoking causes great harm to children and pregnant women.","trans":"被动吸烟会对儿童和孕妇造成很大的伤害。","mne":"pass忍受，受苦 + ive表形容词 → passive消极的；被动的"},{"word":"passport","ipa":"/ˈpæspɔːrt/","pos":"n.","def":"护照；途径，手段","sen":"I got many stamps on my passport.","trans":"我的护照上盖了很多章。","mne":"pass通过 + port港口 → 通过港口的凭证 → passport护照"},{"word":"past","ipa":"/pæst/","pos":"n.","def":"过去；  prep.过，超过；（时间）晚于；  adv.经过；  adj.过去的，结束的","sen":"We usually used public telephones in the past.","trans":"过去我们通常使用公用电话。","mne":""},{"word":"paste","ipa":"/peɪst/","pos":"v.","def":"粘贴；  n.糊状物，糨糊","sen":"I'm pasting wallpaper to the wall.","trans":"我正在把墙纸粘贴到墙上。","mne":""},{"word":"pat","ipa":"/pæt/","pos":"v.","def":"轻拍，抚摸；  n.轻拍，抚摸","sen":"He patted the dog affectionately.","trans":"他亲切地拍了拍那只狗。","mne":""},{"word":"patch","ipa":"/pætʃ/","pos":"n.","def":"补丁；  v.打补丁","sen":"I tore a hole in my pants, so I sewed a patch over it.","trans":"我的裤子撕破了一个洞，所以我打了一个补丁在上面。","mne":""},{"word":"path","ipa":"/pæθ/","pos":"n.","def":"道路；小路","sen":"There are many trees on both sides of the path.","trans":"道路两旁有很多树。","mne":""},{"word":"patience","ipa":"/ˈpeɪʃns/ ","pos":"n.","def":"耐心，忍耐","sen":"He's losing his patience after waiting so long.","trans":"他等得有点不耐烦了。","mne":"pati忍受 + ence表示性质、状态 → 能忍受 → patience忍耐，容忍，耐心"},{"word":"patient","ipa":"/ˈpeɪʃnt/","pos":"n.","def":"病人，患者；  adj.有耐性的，能容忍的","sen":"As a nurse, I love to work closely with my patients.","trans":"作为一名护士，我喜欢近距离接触我的病人。","mne":"pati忍受 + ent表名词，...的人 → 正在受苦的人 → patient病人"},{"word":"pattern","ipa":"/ˈpætərn/","pos":"n.","def":"图案，花样，式样；模式；典范；版式；样品；  v.形成图案；促成（某种行为模式）","sen":"The pattern consists of many different colored triangles.","trans":"这个图案由许多不同颜色的三角形组成。","mne":""},{"word":"pause","ipa":"/pɔːz/","pos":"v.","def":"暂停播放；暂停，中止；  n.中止，暂停","sen":"I clicked on the screen and paused the video.","trans":"我点击按钮暂停了视频。","mne":""},{"word":"pay","ipa":"/peɪ/","pos":"v.","def":"支付，偿还；付出；  n.工资","sen":"He paid for his coffee and bread.","trans":"他付了咖啡和面包的钱。","mne":""},{"word":"payment","ipa":"/ˈpeɪmənt/","pos":"n.","def":"付钱；报酬","sen":"The clever dog made the payment for the bone itself.","trans":"这只聪明的狗自己购买了骨头。","mne":"pay付款 + ment表示行为、行为的过程或结果 → 支付，支付的款项"},{"word":"peace","ipa":"/piːs/","pos":"n.","def":"和平；平静","sen":"This kind of bird always stands for peace.","trans":"这种鸟一直代表着和平。","mne":"pea固定 + ce名词后缀 → peace和平，无战争"},{"word":"peaceful","ipa":"/ˈpiːsfl/","pos":"adj.","def":"平静的，安宁的","sen":"The chaos around him couldn't shake his peaceful mind.","trans":"周遭的喧嚣无法动摇他内心的宁静。","mne":"peace和平 + ful…的 → peaceful和平的"},{"word":"peak","ipa":"/piːk/ ","pos":"n.","def":"山顶；最高峰，顶点；  v.使……达到顶峰；  adj.最高度的；高峰时期的","sen":"The peak of the mountain is covered by snow.","trans":"山顶被积雪覆盖。","mne":""},{"word":"pear","ipa":"/per/","pos":"n.","def":"梨，梨子，梨树","sen":"The pears are yellow and ripe.","trans":"梨子黄了、成熟了。","mne":""},{"word":"peasant","ipa":"/ˈpeznt/","pos":"n.","def":"农民；农夫；庄稼人；小耕农","sen":"This is a peasant living in the old times.","trans":"这是一位生活在旧时代的农民。","mne":"peas乡村 + ant表正在进行 → 住在乡村的 →peasant农民；乡下人"},{"word":"peculiar","ipa":"/pɪˈkjuːliər/","pos":"adj.","def":"奇怪的，古怪的","sen":"These mooncakes' flavors are very peculiar.","trans":"这些月饼的口味很奇怪。","mne":"peculi特有 + ar……的 → peculiar特有的"},{"word":"pen","ipa":"/pen/","pos":"n.","def":"笔，钢笔；围栏，畜栏","sen":"Sign this with a pen, please.","trans":"请用钢笔在这儿签字。","mne":""},{"word":"penalty","ipa":"/ˈpenəlti/","pos":"n.","def":"惩罚，处罚","sen":"The driver is facing a penalty for not wearing his seatbelt.","trans":"这名司机因未系安全带而面临处罚。","mne":"penal刑事的 + ty名词后缀 → penalty 刑罚，罚金"},{"word":"pencil","ipa":"/ˈpensl/","pos":"n.","def":"铅笔","sen":"I use a pencil to do math.","trans":"我用铅笔做数学计算。","mne":""},{"word":"penetrate","ipa":"/ˈpenətreɪt/","pos":"v.","def":"刺穿，穿透；进入；了解","sen":"The apple was penetrated with an arrow.","trans":"这个苹果被一支箭射穿了。","mne":"pen 几乎 + etr穿过 + ate 动词后缀 → penetrate刺穿；渗入"},{"word":"penny","ipa":"/ˈpeni/","pos":"n.","def":"美分","sen":"His parents give the little boy a penny a day.","trans":"小男孩的父母每天给他一美分。","mne":""},{"word":"pension","ipa":"/ˈpenʃn/","pos":"n.","def":"养老金，抚恤金；退休金","sen":"The old lady gets her pension every month.","trans":"那个老年女士每个月都会得到养老金。","mne":"pens花费 + ion名词后缀 → 政府给老年人等花费的钱 → pension养老金"},{"word":"people","ipa":"/ˈpiːpl/","pos":"n.","def":"人，人们，人类（person的复数）；人民，民众","sen":"There are many different people in the world.","trans":"世界上有许多不同的人。","mne":""},{"word":"per","ipa":"/pər/","pos":"prep.","def":"每，每一","sen":"You are allowed to drive at 80 kilometers per hour on this road.","trans":"你可以在这条路上以每小时最快80公里的速度行驶。","mne":""},{"word":"perceive","ipa":"/pərˈsiːv/","pos":"v.","def":"察觉；看待，理解","sen":"Some patients perceive pain differently due to individual sensitivity.","trans":"由于个人敏感性不同，有些病人对疼痛的感知也不同。","mne":"per通过 + ceive抓住 → perceive觉察，发觉"},{"word":"percent","ipa":"/pərˈsent/","pos":"n.","def":"百分比，比例，部分；百分之……","sen":"The green part takes up 70 percent of the pie chart.","trans":"绿色部分占据了饼状图的70%。","mne":"per每一 + cent一百 → percent百分比"},{"word":"percentage","ipa":"/pərˈsentɪdʒ/","pos":"n.","def":"百分比；百分率","sen":"The percentage of the green part is 60%.","trans":"绿色部分的百分比为60%。","mne":"percent百分之几 + age状态，总称 → 百分比"},{"word":"perfect","ipa":"/ˈpɜːrfɪkt/, /pərˈfekt/","pos":"adj.","def":"极好的；准确的；  v.使完美（读作/pərˈfekt/）","sen":"Baicizhan is a perfect English study application.","trans":"百词斩是一款极好的英语学习应用程序。","mne":"per全 + fect做 → perfect完美的"},{"word":"perform","ipa":"/pərˈfɔːrm/","pos":"v.","def":"表演；执行；【法】履行；表现","sen":"A band is performing on the stage.","trans":"一支乐队正在舞台上表演。","mne":"per完全 + form提供 → 提供完全提供、展现自己 → perform表演、表现"},{"word":"performance","ipa":"/pərˈfɔrməns/","pos":"n.","def":"表演，演出；表现；执行；性能","sen":"The audience was amazed by her great stage performance.","trans":"观众对她精彩的舞台表演赞叹不已。","mne":"perform表演 + ance表名词 → performance表演"},{"word":"perhaps","ipa":"/pərˈhæps/","pos":"adv.","def":"或许，可能","sen":"The girl perhaps had a bad dream.","trans":"这个女孩可能做了噩梦。","mne":"per全部 + hap机会，运气 + s表复数 → 全是机会 → perhaps也许，可能"},{"word":"period","ipa":"/ˈpɪriəd/","pos":"n.","def":"时期","sen":"He became a math teacher over a period of four years.","trans":"他花了四年的时间成了一名数学老师。","mne":"peri周围，靠近 ＋ od道路 → period周期"},{"word":"permanent","ipa":"/ˈpɜːrmənənt/","pos":"adj.","def":"永久的，永恒的","sen":"The love between them was permanent, enduring the test of time.","trans":"他们之间的爱情是永久的，经得起时间的考验。","mne":"per贯穿，自始至终 + man留住 + ent形容词后缀 → 永久留住 → permanent永恒的"},{"word":"permissible","ipa":"/pərˈmɪsəbl/","pos":"adj.","def":"容许的","sen":"Smoking is permissible in this area.","trans":"该区域允许吸烟。","mne":"permiss=permit允许 + ible形容词后缀 → permissible可允许的"},{"word":"permission","ipa":"/pərˈmɪʃn/ ","pos":"n.","def":"允许，同意","sen":"My mother gave me her permission to go to the party.","trans":"我母亲允许我去参加聚会。","mne":"permi=permit允许 + ssion名词后缀 → permission允许，同意"},{"word":"permit","ipa":"/ˈpɜrˌmɪt/, /pərˈmɪt/","pos":"v.","def":"许可；  n.许可证；执照（读作/ˈpɜrˌmɪt/）","sen":"Only the invited are permitted to enter the room.","trans":"只有受邀人士才被允许进入这个房间。","mne":"per始终 + mit送，放出 → 始终放出来 → 许可"},{"word":"persist","ipa":"/pərˈsɪst/","pos":"v.","def":"坚持，固执；持续","sen":"Although the water is cold, we persist in going forward.","trans":"尽管水很凉，我们还是坚持前进。","mne":"per贯穿，自始至终 + sist站 → 站到最后 → persist坚持"},{"word":"persistent","ipa":"/pərˈsɪstənt/","pos":"adj.","def":"持续的；坚持的","sen":"There will be persistent rain this month.","trans":"本月会有持续降雨。","mne":"persist坚持 + ent形容词后缀 → persistent坚持的"},{"word":"person","ipa":"/ˈpɜːrsn/","pos":"n.","def":"人；个人","sen":"This person is drinking coffee with her friend.","trans":"这个人正在和她的朋友一起喝咖啡。","mne":""},{"word":"personal","ipa":"/ˈpɜːrsənl/","pos":"adj.","def":"个人的，私人的","sen":"He is riding his personal bike.","trans":"他正在骑他自己的自行车。","mne":"person人 ＋ al...的 → personal个人的"},{"word":"personnel","ipa":"/ˌpɜːrsəˈnel/","pos":"n.","def":"全体人员，职员；人事部门","sen":"We will arrange the training for personnel.","trans":"我们将安排全体人员培训。","mne":"personn=person人 + el表名词 → 全体人员"},{"word":"perspective","ipa":"/pərˈspektɪv/","pos":"n.","def":"【财】观点；（对事物的）合理判断，正确认识；远景","sen":"From a financial perspective the decision to invest in stocks needs a thorough analysis.","trans":"从财务角度看，决定投资股票需要进行彻底的分析。","mne":"per贯穿，自始至终 + spect看 + ive名词后缀 → 看透了 → perspective透视"},{"word":"persuade","ipa":"/pərˈsweɪd/","pos":"v.","def":"劝说；使相信","sen":"He is trying to persuade his friend to go on a roller coaster with him.","trans":"他正试图说服他的朋友和他一起坐过山车。","mne":"per贯穿，自始至终 + suade劝 → 一直劝 → persuade劝说"},{"word":"pessimist","ipa":"/ˈpesɪmɪst/","pos":"n.","def":"悲观主义者","sen":"Unlike his positive friend, the pessimist thought the weather would get worse.","trans":"和他那个乐观的朋友不同，这个悲观主义者觉得天气会变差。","mne":"pessim=pessimism悲观 + ist主义 → pessimist悲观主义者"},{"word":"pessimistic","ipa":"/ˌpesɪˈmɪstɪk/","pos":"adj.","def":"悲观的","sen":"The pessimistic man always expects the worst.","trans":"这个悲观的人总是把什么事情都想得很糟。","mne":"pessi=pes底部的 + mistic关于……的 → pessimistic悲观的；厌世的"},{"word":"pet","ipa":"/pet/","pos":"n.","def":"宠物；宠儿；  v.宠爱，爱抚；  adj.宠爱的，钟爱的","sen":"This hamster is his pet.","trans":"这只仓鼠是他的宠物。","mne":""},{"word":"petrol","ipa":"/ˈpetrəl/","pos":"n.","def":"<英>汽油","sen":"\"Please fill my car up with petrol!\" the driver said.","trans":"司机说：“麻烦给我的车加满油！”","mne":""},{"word":"petroleum","ipa":"/pəˈtroʊliəm/","pos":"n.","def":"石油","sen":"The marine drilling platform is used for the exploitation of petroleum and gas.","trans":"海上钻井平台用于油气开发。","mne":"petr石 + oleum油 → petroleum石油"},{"word":"phase","ipa":"/feɪz/","pos":"n.","def":"相位；阶段；  v.分阶段进行","sen":"Using a phase inverter pedal for guitar can create interesting tonal variations in your playing.","trans":"在吉他上使用相位倒置踏板可以在演奏中创造有趣的音色变化。","mne":""},{"word":"phenomenon","ipa":"/fəˈnɑːmɪnən/","pos":"n.","def":"现象；杰出的人","sen":"The Northern Lights are a wonderful natural phenomenon.","trans":"北极光是一种奇妙的自然现象。","mne":"phen显示 + omen预兆 + on表示抽象名词 → 显示预兆 → phenomenon现象"},{"word":"philosopher","ipa":"/fəˈlɑːsəfər/","pos":"n.","def":"哲学家","sen":"This is a statue of an ancient Greek philosopher.","trans":"这是一尊古希腊哲学家的雕塑。","mne":"philo爱 + soph智慧 + er者 → 爱智慧的人 → philosopher哲学家，思想家"},{"word":"philosophy","ipa":"/fəˈlɑːsəfi/","pos":"n.","def":"哲学，哲学体系","sen":"I often think about the meaning of life and other questions of philosophy.","trans":"我常常思考生命的意义以及其他哲学问题。","mne":"philo爱 + sophy智慧 → 爱与智慧 → philosophy哲学"},{"word":"phone","ipa":"/foʊn/","pos":"n.","def":"电话；  v.（给……）打电话","sen":"They are all using their phones.","trans":"他们都在玩自己的手机。","mne":"phon声音 + e → phone电话"},{"word":"photo","ipa":"/ˈfoʊtoʊ/","pos":"n.","def":"照片，相片（=photograph）","sen":"Smile please, I am taking a photo of you.","trans":"请笑一笑，我在给你拍照片呢。","mne":""},{"word":"photograph","ipa":"/ˈfoʊtəɡræf/","pos":"n.","def":"照片；  v.照相，摄影；  v.为……拍照","sen":"Here are all of my travel photographs.","trans":"这些都是我旅行拍的照片。","mne":"photo光 + graph写，图 → 用光写 → photograph相片"},{"word":"phrase","ipa":"/freɪz/","pos":"n.","def":"短语，词组；  v.措辞","sen":"A phrase is a group of words that forms part of a sentence.","trans":"短语是构成句子一部分的一组词。","mne":""},{"word":"physical","ipa":"/ˈfɪzɪkəl/","pos":"adj.","def":"身体上的；物理的，物理学的；物质的；  n.体格检查","sen":"Physical exercise is good for your body and mind.","trans":"体育锻炼有益于你的身心健康。","mne":"physic自然，自然科学 + cal表形容词 → 大自然中本身就存在的 → physical身体的，物理的"},{"word":"physician","ipa":"/fɪˈzɪʃn/","pos":"n.","def":"内科医生","sen":"My physician told me to eat more fruits and vegetables.","trans":"我的内科医生告诉我要多吃水果和蔬菜。","mne":"phys生理领域 + ician表专家，从事某职业的人 → physician内科医生"},{"word":"physicist","ipa":"/ˈfɪzɪsɪst/","pos":"n.","def":"物理学者，物理学家","sen":"Einstein is a great physicist.","trans":"爱因斯坦是个伟大的物理学家。","mne":"physic物理 + ist做...的人 → physicist物理学家"},{"word":"physics","ipa":"/ˈfɪzɪks/","pos":"n.","def":"物理（学）","sen":"He is teaching physics in the classroom.","trans":"他正在教室里教物理。","mne":""},{"word":"piano","ipa":"/piˈænoʊ/","pos":"n.","def":"钢琴","sen":"I love music and piano.","trans":"我喜欢音乐和钢琴。","mne":""},{"word":"pick","ipa":"/pɪk/","pos":"v.","def":"挑选；采摘","sen":"He picked out the block from the middle of the row.","trans":"他挑出了这排中间的木块。","mne":""},{"word":"picnic","ipa":"/ˈpɪknɪk/","pos":"n.","def":"野餐；  v.野餐","sen":"The family enjoyed a nice picnic outside.","trans":"这一家人在室外享用了一顿很好的野餐。","mne":""},{"word":"picture","ipa":"/ˈpɪktʃər/","pos":"n.","def":"照片，图片；画，图画；  v.想象，设想；描述","sen":"We took a group picture in front of this famous attraction in Rome.","trans":"我们在罗马的这个著名景点前拍了一张合照。","mne":"pict描画 + ure名词后缀 → picture图画，照片"},{"word":"pie","ipa":"/paɪ/","pos":"n.","def":"派，果馅饼","sen":"May I have a slice of the blueberry pie?","trans":"可以给我一片蓝莓派吗？","mne":""},{"word":"piece","ipa":"/piːs/","pos":"n.","def":"块，碎块；片；件；  v.凑合","sen":"The yellow cup smashed into pieces.","trans":"这个黄杯子碎成了很多块。","mne":""},{"word":"pierce","ipa":"/pɪrs/","pos":"v.","def":"穿（孔）","sen":"He pierced his ears.","trans":"他穿了耳洞。","mne":""},{"word":"pig","ipa":"/pɪɡ/","pos":"n.","def":"猪","sen":"What a cute little pig!","trans":"多可爱的小猪！","mne":""},{"word":"pigeon","ipa":"/ˈpɪdʒɪn/","pos":"n.","def":"鸽子","sen":"The pigeon is taking a rest in the tree.","trans":"这只鸽子正在树上休息。","mne":""},{"word":"pile","ipa":"/paɪl/","pos":"v.","def":"堆积；  n.堆；摞","sen":"I piled up the soldiers I defeated on top of each other.","trans":"阿卡丽把她打败的士兵一个接一个堆起来。","mne":""},{"word":"pill","ipa":"/pɪl/","pos":"n.","def":"药丸，药","sen":"The woman is taking some pills as she is ill.","trans":"这个女人因为生病了，正在服用一些药丸。","mne":""},{"word":"pillar","ipa":"/ˈpɪlər/","pos":"n.","def":"柱，台柱，栋梁","sen":"These pillars hold the roof up.","trans":"这些柱子支撑起屋顶。","mne":""},{"word":"pillow","ipa":"/ˈpɪloʊ/","pos":"n.","def":"枕头","sen":"I love sleeping with soft pillows.","trans":"我爱枕着软软的枕头入睡。","mne":""},{"word":"pilot","ipa":"/ˈpaɪlət/","pos":"n.","def":"飞行员","sen":"He has dreamed of being a pilot since he was a little boy.","trans":"他从小就梦想成为一名飞行员。","mne":"pil=ped脚 + ot名词后缀 → pilot飞行员，领航员"},{"word":"pin","ipa":"/pɪn/","pos":"n.","def":"大头针；别针；  v.别住，钉住，固定住","sen":"Be careful, there’s a pin on the floor.","trans":"小心，地上有一枚大头针。","mne":""},{"word":"pinch","ipa":"/pɪntʃ/ ","pos":"v.","def":"捏；  n.捏","sen":"The nurse will gently pinch the patient's skin to check for dehydration.","trans":"护士会轻轻捏一下病人的皮肤来检查是否脱水。","mne":""},{"word":"pine","ipa":"/paɪn/","pos":"n.","def":"松树；  v.（因死亡、离别等）难过","sen":"The pine tree is a symbol of Mount Huangshan.","trans":"松树是黄山的标志之一。","mne":""},{"word":"pink","ipa":"/pɪŋk/","pos":"adj.","def":"粉红色的；  n.粉红色","sen":"The princess wears a pink dress.","trans":"公主穿着一条粉色的裙子。","mne":""},{"word":"pioneer","ipa":"/ˌpaɪəˈnɪr/ ","pos":"n.","def":"先锋，先驱；  v.开辟，首倡","sen":"He's a pioneer in climbing, that is, the first man to reach the summit.","trans":"他是登山的先锋，即第一个到达山顶的人。","mne":"pion=ped脚 + eer表示人  → 用脚走路的人  → pioneer先锋"},{"word":"pipe","ipa":"/paɪp/","pos":"n.","def":"管子，导管；烟斗；  v.用管子输送","sen":"These pipes are made of plastic, so they are very light.","trans":"这些管子是塑料做的，所以它们非常轻。","mne":""},{"word":"pirate","ipa":"/ˈpaɪrət/","pos":"n.","def":"海盗；  v.盗印","sen":"The pirate found an island to bury the stolen treasure.","trans":"海盗发现了一个小岛来埋藏他偷来的宝藏。","mne":"pir坏的 + ate做 → 做坏事 → pirate抢夺，引申为海盗"},{"word":"pitch","ipa":"/pɪtʃ/ ","pos":"v.","def":"投掷，扔；扎营；  n.（足球等的）球场；程度，强度，高度；音高；沥青，柏油","sen":"The player pitched the ball to me.","trans":"球员把球向我掷了过来。","mne":""},{"word":"pity","ipa":"/ˈpɪti/","pos":"n.","def":"同情；怜悯","sen":"The psychologist showed pity for the girl.","trans":"心理学家对女孩深表同情。","mne":""},{"word":"place","ipa":"/pleɪs/","pos":"n.","def":"地方，地点","sen":"Berlin is one place that I would like to go to.","trans":"柏林是一个我想去的地方。","mne":""},{"word":"plague","ipa":"/pleɪɡ/","pos":"n.","def":"瘟疫；  v.折磨","sen":"The Black Plague took thousands of lives away in the Middle Ages.","trans":"在中世纪，黑死病夺走了成千上万条生命。","mne":"plag击打 + ue  → 击打（使苦恼） → plague烦扰"},{"word":"plain","ipa":"/pleɪn/","pos":"n.","def":"平原；  adj.朴素的，不做修饰的；简单明了的","sen":"A plain is a flat landform at low altitude.","trans":"平原是一种位于低海拔的平坦地貌。","mne":""},{"word":"plan","ipa":"/plæn/","pos":"n.","def":"计划，打算；  v.计划，打算","sen":"They made a plan to renovate the living room.","trans":"他们制定了一个计划来装修客厅。","mne":""},{"word":"plane","ipa":"/pleɪn/","pos":"n.","def":"飞机；平面","sen":"The plane is taking off at sunset.","trans":"飞机在日落时分起飞。","mne":""},{"word":"planet","ipa":"/ˈplænɪt/","pos":"n.","def":"行星","sen":"There are 8 major planets in our solar system.","trans":"太阳系中有八大行星。","mne":""},{"word":"plant","ipa":"/plænt/","pos":"n.","def":"植物；发电厂；设备；工厂；  v.种植；安置；放置","sen":"There are many different kinds of green plants.","trans":"这里有许多不同种类的绿色植物。","mne":""},{"word":"plastic","ipa":"/ˈplæstɪk/","pos":"n.","def":"塑料，塑料制品；  adj.塑料的","sen":"All of this food packaging is made of plastic.","trans":"这些食品包装都是塑料做的。","mne":"plast塑造 + ic……的 → 可塑的"},{"word":"plate","ipa":"/pleɪt/","pos":"n.","def":"盘子，碟子","sen":"I can put much food on this big plate.","trans":"我可以在这个大盘子里放很多食物。","mne":""},{"word":"platform","ipa":"/ˈplætˌfɔrm/ ","pos":"n.","def":"站台；讲台","sen":"The train is passing platform 4.","trans":"列车正在经过4号站台。","mne":"plat平坦 + form形状 → 形状平的地方 → 平台，月台"},{"word":"play","ipa":"/pleɪ/","pos":"v.","def":"玩；演奏；扮演；（使）播放；  n.戏剧，剧本；比赛","sen":"The children are playing in the park.","trans":"孩子们正在公园里玩耍。","mne":""},{"word":"player","ipa":"/ˈpleɪər/","pos":"n.","def":"玩家；运动员；参赛选手，队员","sen":"The player has just won a game.","trans":"这个玩家刚刚赢得了一场游戏。","mne":"play比赛，游戏 + er表人 → player选手，队员"},{"word":"playground","ipa":"/ˈpleɪɡraʊnd/","pos":"n.","def":"（学校的）操场，运动场；（公园的）游乐场；游乐区","sen":"The students are having fun on the playground after class.","trans":"下课后，学生们在操场上玩耍。","mne":"play比赛 + ground场地 → playground操场，运动场"},{"word":"pleasant","ipa":"/ˈpleznt/","pos":"adj.","def":"令人愉快的，舒适的；宜人的","sen":"Her pleasant smile has lit up my day.","trans":"她明媚的笑容照亮了我的一天。","mne":"pleas=please快乐 ＋ ant形容词词尾 → pleasant令人愉快的，舒适的"},{"word":"please","ipa":"/pliːz/","pos":"int.","def":"请","sen":"Please give me some more food. I'm really hungry.","trans":"请再给我一些食物吧，我真的很饿。","mne":""},{"word":"pleased","ipa":"/pliːzd/","pos":"adj.","def":"高兴的，满意的","sen":"The children were pleased to play role-play.","trans":"孩子们在角色扮演中玩得很开心。","mne":"pleas高兴 + ed形容词后缀 → pleased高兴的"},{"word":"pleasing","ipa":"/ˈpliːzɪŋ/","pos":"adj.","def":"使人满意的","sen":"She finds the bunch of flowers very pleasing.","trans":"她觉得这束花让她很满意。","mne":"pleas=please愉快 + ing形容词后缀 → 令人愉快的"},{"word":"pleasure","ipa":"/ˈpleʒər/","pos":"n.","def":"愉快，乐事","sen":"The little girl takes pleasure in eating cakes.","trans":"这个小女孩从吃蛋糕中获得快乐。","mne":"pleas=please令人高兴的 + ure名词后缀，表行为、状态 → pleasure愉快"},{"word":"pledge","ipa":"/pledʒ/","pos":"n.","def":"保证，誓约；  v.使保证，使发誓；抵押，典当","sen":"Holding his sword and kneeing down, he made his pledge.","trans":"雪诺手持宝剑，跪倒在地，宣誓将生命与荣耀献给守夜人。","mne":""},{"word":"plentiful","ipa":"/ˈplentɪfl/","pos":"adj.","def":"丰富的；充分的","sen":"The fruits and vegetables are plentiful!","trans":"水果和蔬菜好丰富啊！","mne":"plenti=plenty足够 + ful…的 → plentiful丰富的，充足的，大量的"},{"word":"plenty","ipa":"/ˈplenti/","pos":"pron.","def":"大量，丰富；  n.充裕","sen":"We have plenty of fruits and vegetables.","trans":"我们有充足的水果和蔬菜。","mne":"plen满 ＋ ty表名词 → plenty大量，丰富"},{"word":"plot","ipa":"/plɑːt/","pos":"n.","def":"情节；小块土地；故事情节；  v.密谋；绘图；为小说写情节","sen":"She is crafting a romantic plot for her story.","trans":"她正在为故事构思一个浪漫的情节。","mne":""},{"word":"plug","ipa":"/plʌɡ/","pos":"n.","def":"插头；塞子；  v.封堵；宣传","sen":"The robot is charging from the plug on his back.","trans":"初号机通过背后的插头充电。","mne":""},{"word":"plural","ipa":"/ˈplʊrəl/","pos":"n.","def":"复数；  adj.复数的","sen":"The word 'fish' can be singular or plural.","trans":"fish这个词可以是单数也可以是复数。","mne":"plur=plus更多的 + al表形容词 → plural复数的"},{"word":"plus","ipa":"/plʌs/","pos":"prep.","def":"加，加上；  n.加号；有利因素；  conj.此外，而且，况且；  adj.正的；（分数后）加，略高；多的","sen":"One plus one equals two. Hopefully you knew that.","trans":"一加一等于二，希望你知道这个。","mne":""},{"word":"pocket","ipa":"/ˈpɑːkɪt/","pos":"n.","def":"口袋，兜，衣袋；  adj.袖珍的；  v.把……装入口袋","sen":"I put my phone into my pocket.","trans":"我把手机放进我的口袋里了。","mne":"pock袋 + et=ellus小  → 小袋子  → pocket口袋"},{"word":"poem","ipa":"/ˈpoʊəm/","pos":"n.","def":"诗，韵文，诗体文","sen":"This great poem was written by Li Bai.","trans":"这首名诗是李白写的。","mne":""},{"word":"poet","ipa":"/ˈpoʊət/","pos":"n.","def":"诗人","sen":"He is one of the most famous poets in Chinese history.","trans":"他是中国历史上最著名的诗人之一。","mne":""},{"word":"point","ipa":"/pɔɪnt/","pos":"n.","def":"意义；点；（试图表达的）观点，看法；  v.指向，指出；表明","sen":"What was the point of playing the piano to a cow?","trans":"对牛弹琴的意义何在？","mne":""},{"word":"poison","ipa":"/ˈpɔɪzn/","pos":"n.","def":"毒物，毒药，毒素；  v.毒死，毒害","sen":"Don't drink that poison. It will kill you.","trans":"不要喝那瓶毒药，它会把你毒死的。","mne":""},{"word":"poisonous","ipa":"/ˈpɔɪzənəs/ ","pos":"adj.","def":"引起中毒的，有毒的","sen":"Some varieties of mushrooms are poisonous.","trans":"有些品种的蘑菇是有毒的。","mne":"poison毒 + ous…的 → poisonous有毒的"},{"word":"pole","ipa":"/poʊl/","pos":"n.","def":"杆子，棍，杖；（行星的）极，地极","sen":"The wire pole holds the cables.","trans":"电线杆支撑着电缆。","mne":""},{"word":"police","ipa":"/pəˈliːs/","pos":"n.","def":"警察，警方；  v.维持治安，管辖，监督","sen":"We know he's a police because of his car and uniform.","trans":"我们根据他的车子和制服得知他是一位警察。","mne":""},{"word":"policeman","ipa":"/pəˈliːsmən/","pos":"n.","def":"警察(pl. policemen)","sen":"The policeman is chasing a thief.","trans":"警察正在抓小偷。","mne":"police警察 + man人 → policeman警察"},{"word":"policy","ipa":"/ˈpɑːləsi/","pos":"n.","def":"政策，方针","sen":"The policy in this company forbids employees to have relationships with each other.","trans":"这家公司的政策禁止员工之间谈恋爱。","mne":"polic国家，城市 + y名词后缀 → 用以管理国家的依据 → policy政策"},{"word":"polish","ipa":"/ˈpɑlɪʃ/, /ˈpoʊlɪʃ/","pos":"v.","def":"磨光，擦亮；润饰，使优美；  n.上光剂","sen":"The car needs to be polished regularly.","trans":"这辆车需要定期抛光。","mne":"pol光滑 + ish动词词尾 → polish抛光，擦亮"},{"word":"polite","ipa":"/pəˈlaɪt/","pos":"adj.","def":"有礼貌的，客气的；文雅的","sen":"This polite girl gave her seat to an old lady.","trans":"这个有礼貌的女孩把自己的座位让给了一位老太太。","mne":"pol光滑 + ite…的 → polite有礼貌的"},{"word":"political","ipa":"/pəˈlɪtɪkl/","pos":"adj.","def":"政治的","sen":"The young man is giving a political speech to the public.","trans":"这个年轻人在向公众发表一场政治演说。","mne":"polit国家，城市 + ical...的 → political政治的，政治上的"},{"word":"politics","ipa":"/ˈpɑːlətɪks/","pos":"n.","def":"政治，政治事务；政治学","sen":"He is so keen on politics that he participates in many public events.","trans":"他是如此热衷于政治，因此他参加了很多公众活动。","mne":"polit城市，公民 + ics与...有关的 → politics政治"},{"word":"poll","ipa":"/poʊl/","pos":"n.","def":"民意测验；投票；  v.获得（票数）","sen":"The organization is conducting a poll.","trans":"该组织正在进行一项民意测验。","mne":""},{"word":"pollute","ipa":"/pəˈluːt/","pos":"v.","def":"污染，弄脏；玷污，亵渎","sen":"Few fish can survive in this polluted river.","trans":"在这条受污染的河里，很少有鱼能存活下来。","mne":""},{"word":"pollution","ipa":"/pəˈluːʃn/","pos":"n.","def":"污染物，污染","sen":"Pollution from the factories made the sky turn gray.","trans":"工厂带来的污染使天空变成了灰色。","mne":"pollut污染 + ion表示行为、行为的过程或结果、情况、状态 → pollution污染"},{"word":"pond","ipa":"/pɑːnd/","pos":"n.","def":"池塘","sen":"The duck dived into the pond.","trans":"鸭子一头扎进了池塘。","mne":""},{"word":"pool","ipa":"/pu:l/","pos":"n.","def":"泳池，水塘；  v.集中资源（或材料）；合伙","sen":"There is a big swimming pool in the park.","trans":"公园里有个超大的游泳池。","mne":""},{"word":"poor","ipa":"/pɔːr/","pos":"adj.","def":"贫穷的；可怜的；不足的，缺少的","sen":"The poor homeless man begged for money on the street.","trans":"这个可怜的无家可归的男人在街上乞讨。","mne":""},{"word":"pop","ipa":"/pɑːp/","pos":"n.","def":"砰的一声爆破声；流行音乐，流行歌曲；汽水；  v.发出（砰的响声）；  adj.流行的，大众的","sen":"I hit it with the car door yesterday. And I heard a pop, and then some sloshing(晃动的) sound when I walk.","trans":"我昨天用车门撞到它了。然后我听到“砰”的一声，之后我走路的时候就听到一些晃动的声音。","mne":""},{"word":"popular","ipa":"/ˈpɑːpjələr/","pos":"adj.","def":"大众喜爱的，广受欢迎的；大众的，流行的","sen":"This guy is so popular. He received thousands of \"likes\" on social media.","trans":"这个人非常受欢迎，他在社交媒体上收到了数千个“赞”。","mne":"popul=people人 + ar形容词后缀 → 被很多人喜欢的 → popular受欢迎的"},{"word":"popularity","ipa":"/ˌpɑːpjuˈlærəti/","pos":"n.","def":"流行，普及","sen":"Jeans have regained popularity.","trans":"牛仔裤再度流行。","mne":"popul人民 + ar……的 + popular流行的 + ity表名词 → popularity流行"},{"word":"population","ipa":"/ˌpɑːpjuˈleɪʃn/","pos":"n.","def":"（地区、国家等的）人口","sen":"The world population is about eight billion.","trans":"全世界大概有80亿人口。","mne":"popul人民 + ation表示行为、状态 → population全体居民，人口"},{"word":"porcelain","ipa":"/ˈpɔːrsəlɪn/","pos":"n.","def":"瓷，瓷器","sen":"I use a porcelain pot to serve my tea.","trans":"我用瓷壶来泡茶。","mne":""},{"word":"pork","ipa":"/pɔːrk/","pos":"n.","def":"猪肉","sen":"I bought some pork from the supermarket.","trans":"我从超市买了些猪肉。","mne":""},{"word":"port","ipa":"/pɔːrt/","pos":"n.","def":"港，港口，口岸","sen":"There are hundreds of containers in the port.","trans":"港口有成百上千的集装箱。","mne":""},{"word":"portable","ipa":"/ˈpɔrtəbl/","pos":"adj.","def":"便携的；  n.便携机","sen":"I prefer portable computers—they're more convenient.","trans":"我更喜欢手提电脑——它们更方便。","mne":"port拿，运 + able能…的 → portable可携带的"},{"word":"portion","ipa":"/ˈpɔːrʃn/","pos":"n.","def":"一部分；  v.把……分成若干份","sen":"Every month the couple manage to save a small portion of their salaries.","trans":"这对夫妇每个月都设法从他们的工资里省下一小部分钱。","mne":"port + ion名词后缀 → portion一部分"},{"word":"portrait","ipa":"/ˈpɔrtrət/","pos":"n.","def":"肖像","sen":"This is a portrait of a man.","trans":"这是一幅男子的肖像。","mne":""},{"word":"pose","ipa":"/poʊz/","pos":"n.","def":"姿势；  v.造成，形成；  v.引起；  v.摆造型","sen":"She makes a cute pose for the camera.","trans":"她对着镜头做了一个可爱的姿势。","mne":"pos放 + e → 摆放造型 → pose姿势"},{"word":"position","ipa":"/pəˈzɪʃn/","pos":"n.","def":"姿势；职位；位置；地位；  v.安置","sen":"He says he thinks better in that position, but I'm not so sure he does.","trans":"他说他保持那种姿势时能更好地思考，但是我不是很确定他能做到。","mne":"posit放(本身是一个单词，意为“认为，肯定”) + ion名词后缀 → 放出的[立场] → position立场"},{"word":"positive","ipa":"/ˈpɑːzətɪv/","pos":"adj.","def":"积极的，乐观的","sen":"He faces every situation with a positive attitude.","trans":"不管面对什么情形，他的心态都很积极。","mne":"posit肯定 + ive形容词后缀 → positive肯定的；积极的"},{"word":"possess","ipa":"/pəˈzes/","pos":"v.","def":"拥有，占有","sen":"She finally possesses an apartment of her own.","trans":"她终于拥有了属于自己的公寓。","mne":"pos有权力的 + sess坐下 → possess拥有"},{"word":"possession","ipa":"/pəˈzeʃn/","pos":"n.","def":"所有物；财产","sen":"My house is my most expensive possession.","trans":"我的房子是我最贵重的财产。","mne":"pos能 + sess坐 + ion表名词，构成抽象名词 → 能坐在上面 → possession拥有"},{"word":"possibility","ipa":"/ˌpɑːsəˈbɪləti/","pos":"n.","def":"可能性","sen":"The possibility that I grab the black ball is fifty percent.","trans":"我抓到黑球的可能性是50%。","mne":"poss可能 + ibility表名词 → possibility可能；可能的事"},{"word":"possible","ipa":"/ˈpɑːsəbl/","pos":"adj.","def":"可能的；可能发生、存在的","sen":"The base tries to find out if it's possible there are aliens in the universe.","trans":"这个基地试图弄清宇宙中是否有外星人存在。","mne":"poss能够的 + ible能...的，表形容词 → possible可能的"},{"word":"possibly","ipa":"/ˈpɑːsəbli/","pos":"adv.","def":"也许，或许；可能地","sen":"Possibly, I can really get a surprise!","trans":"也许我真的可以得到一个惊喜！","mne":"poss可能 + ibly...地 → possibly可能地；也许"},{"word":"post","ipa":"/poʊst/","pos":"v.","def":"邮寄；公布；  n.邮政；职位","sen":"She is posting the letter.","trans":"她正在寄信。","mne":"po向前 + st使稳固，站立 → 直立的事物 → post柱，岗位"},{"word":"postage","ipa":"/ˈpoʊstɪdʒ/","pos":"n.","def":"邮费，邮资","sen":"The postage depends on the weight of your goods.","trans":"邮费由你的物品重量决定。","mne":"post邮件，邮政 + age表状态 → 邮寄需要费用 → postage邮资"},{"word":"postcard","ipa":"/ˈpoʊstkɑːrd/","pos":"n.","def":"明信片","sen":"My sister always sends me a postcard from whatever new country she visits.","trans":"我姐姐每新到一个国家都会给我寄明信片。","mne":"post邮件，邮政 + card卡片 → 邮寄的卡片 → postcard明信片"},{"word":"poster","ipa":"/ˈpoʊstər/","pos":"n.","def":"海报；招贴","sen":"They are hanging up a poster.","trans":"他们正在挂一张海报。","mne":"post招贴，海报 + er名词后缀 → poster招贴画，海报"},{"word":"postman","ipa":"/ˈpoʊstmən/","pos":"n.","def":"邮递员(pl. postmen)","sen":"It's the postman with some love letters—or are they bills?","trans":"邮递员手里拿的是情书还是账单呢？","mne":"post邮件，邮政 + man人 → postman邮递员"},{"word":"postpone","ipa":"/poʊˈspoʊn/","pos":"v.","def":"推迟，延缓","sen":"I need to postpone my to-do lists.","trans":"我需要推迟我的待办事项。","mne":"post在后面 + pon放 + e → 放到后面 → postpone推迟"},{"word":"posture","ipa":"/ˈpɑːstʃər/","pos":"n.","def":"姿势；看法；态度；  v.装模作样","sen":"My mom always told me to keep a straight posture.","trans":"我妈妈总提醒我保持挺直的姿势。","mne":"pos放置，摆放 + ture名词后缀 → 摆出的姿势 → posture姿势，姿态"},{"word":"pot","ipa":"/pɑːt/","pos":"n.","def":"锅；（陶）罐，（陶）壶，瓶；容器；  v.把...栽入盆中","sen":"He could hear the pot bubbling on the stove.","trans":"他能听到炉子上的锅冒泡的声音。","mne":""},{"word":"potato","ipa":"/pəˈteɪtoʊ/","pos":"n.","def":"马铃薯，土豆","sen":"There are several fresh potatoes in the field.","trans":"田里有几个新鲜的土豆。","mne":""},{"word":"potential","ipa":"/pəˈtenʃl/","pos":"n.","def":"潜力，潜能；  adj.潜在的，可能的","sen":"Just like the pony, we all have the potential to improve.","trans":"正如这匹小马一样，我们都有进步的潜力。","mne":"potent能力，动力 + ial……的 → 由“能力”引申为“潜力” → potential潜力"},{"word":"pound","ipa":"/paʊnd/","pos":"n.","def":"英镑；  v.（连续）猛击，捣碎","sen":"Pound sterling is the national currency of the United Kingdom.","trans":"英镑是英国的国家货币。","mne":""},{"word":"pour","ipa":"/pɔːr/","pos":"v.","def":"注，倒，灌；倾泻","sen":"The milk is being poured into the glass.","trans":"牛奶正被倒进玻璃杯里。","mne":""},{"word":"poverty","ipa":"/ˈpɑːvərti/","pos":"n.","def":"贫穷；贫乏","sen":"Many people live in poverty nowadays.","trans":"现今有很多人生活在贫困之中。","mne":""},{"word":"powder","ipa":"/ˈpaʊdər/","pos":"n.","def":"粉末；细面；  v.抹粉；洒粉于，使变成粉 ","sen":"The white powder is flour which can be used to make bread.","trans":"这种白色的粉末是面粉，可以用来做面包。","mne":""},{"word":"power","ipa":"/ˈpaʊər/","pos":"n.","def":"力量；权力；幂；  v.提供动力","sen":"He has great power to lift such a heavy barbell.","trans":"他力气很大，能举起如此重的杠铃。","mne":""},{"word":"powerful","ipa":"/ˈpaʊərfl/","pos":"adj.","def":"强有力的，强大的；有权势的，有影响力的；很有效的","sen":"He lifts us up easily with his powerful arms.","trans":"他用强健的手臂轻松地把我们举起来了。","mne":"power力量 + ful表形容词，“有…的” → powerful有力的"},{"word":"practical","ipa":"/ˈpræktɪkl/","pos":"adj.","def":"实用的，可行的；实际的，实践的","sen":"Sneakers are more practical than boots for runners.","trans":"对于跑步者来说，运动鞋比靴子更实用。","mne":"pract实践 + ical…的 → 实践的 → practical实践的"},{"word":"practically","ipa":"/ˈpræktɪkli/","pos":"adv.","def":"几乎；实际上；简直","sen":"The glass is practically empty.","trans":"这杯子快空了。","mne":""},{"word":"practice","ipa":"/ˈpræktɪs/","pos":"v.","def":"练习；  n.练习","sen":"The little girl practices yoga with her mom every day.","trans":"小女孩每天都和妈妈一起练习瑜伽。","mne":"pract实践 + ice表名词，行为，状态 → practice实践"},{"word":"practise","ipa":"/ˈpræktɪs/","pos":"v.","def":"练习；实践","sen":"You had better practise for your big fight tomorrow!","trans":"你最好为明天的大决战练习。","mne":""},{"word":"praise","ipa":"/preɪz/","pos":"v.","def":"赞扬；赞扬，歌颂；  n.称赞，表扬","sen":"She was happy because her boss praised her.","trans":"她很开心，因为她的老板表扬了她。","mne":""},{"word":"pray","ipa":"/preɪ/ ","pos":"v.","def":"祈祷，祈求，企盼；请求，恳求","sen":"She prays for lifelong health and well-being for herself and her family.","trans":"她祈祷自己和家人一生平安顺遂。","mne":""},{"word":"precaution","ipa":"/prɪˈkɔːʃn/","pos":"n.","def":"预防措施","sen":"We wear masks as a precaution against catching a cold.","trans":"我们戴口罩来预防感冒。","mne":"pre…前的，预先 + caution小心 → 预先小心 → precaution预防措施"},{"word":"precede","ipa":"/prɪˈsiːd/","pos":"v.","def":"发生在……之前，先于；在前面，领先","sen":"Dinner was preceded by a short prayer.","trans":"吃饭前先进行一个简短的祈祷。","mne":"pre在...之前 + cede去，走 → precede先于"},{"word":"preceding","ipa":"/prɪˈsidɪŋ/","pos":"adj.","def":"在前的，在先的","sen":"Click this button to browse the preceding text.","trans":"点击这个按钮以浏览前文。","mne":"pre预先 + ced走 + ing形容词后缀，…的 → preceding在前的，在先的"},{"word":"precious","ipa":"/ˈpreʃəs/","pos":"adj.","def":"珍贵的，宝贵的","sen":"Precious gems like diamonds are very valuable.","trans":"钻石之类的珍贵宝石是很贵重的。","mne":"prec价值 + ious形容词后缀 → 有价值的 → precious珍贵的"},{"word":"precise","ipa":"/prɪˈsaɪs/","pos":"adj.","def":"精确的；恰好的","sen":"This instrument gives precise measurements.","trans":"这台仪器显示出精确的测量结果。","mne":"pre…前的，预先 + cise切 → 预先切好的 → precise精确的"},{"word":"precisely","ipa":"/prɪˈsaɪsli/","pos":"adv.","def":"精确地；恰恰","sen":"This device can precisely measure the diameter of the bolt.","trans":"这个仪器能精确地测量出这个螺栓的直径。","mne":"precise精确 ＋ ly...地 → precise提前切开=精确的 ＋ ly...地 → precisely精确地"},{"word":"precision","ipa":"/prɪˈsɪʒn/","pos":"n.","def":"精确；精密度","sen":"This is a precision tool for measurements.","trans":"这个仪器用于精密测量。","mne":"pre预先 + cis切 + ion表名词 → 预先切好 → 精密，正确"},{"word":"predict","ipa":"/prɪˈdɪkt/","pos":"v.","def":"预测，预知","sen":"He predicted this stock would experience an increase in a few days.","trans":"他预测该股票过几天会涨。","mne":"pre…前的，预先 + dict说 → 预先说 → 预言"},{"word":"prediction","ipa":"/prɪˈdɪkʃn/","pos":"n.","def":"预测，预言","sen":"The manager showed his prediction for the year to his team.","trans":"经理向他的团队展示了他对今年情况的预测。","mne":"pre预先 + dict说预言 + ion名词 → prediction预告"},{"word":"preface","ipa":"/ˈprefəs/","pos":"n.","def":"序言，前言，开端","sen":"The book's preface was a good introduction to the main text.","trans":"书的前言是对主要内容的一个很好的介绍。","mne":"pre前面 + face脸，面 → 前脸 → preface前言，序言"},{"word":"prefer","ipa":"/prɪˈfɜːr/","pos":"v.","def":"更喜欢；宁愿","sen":"The girl prefers vegetables to cake.","trans":"比起蛋糕，小女孩更喜欢蔬菜。","mne":"pre预先 + fer拿，携带 → 预先带好 → prefer更喜欢"},{"word":"preferable","ipa":"/ˈprefrəbl/","pos":"adj.","def":"更合适的，更好的","sen":"Rice is acceptable, but fish is preferable!","trans":"吃米饭是可以接受的，但是吃鱼当然更好！","mne":"prefer更喜欢 ＋ able…的 → preferable更好的"},{"word":"preference","ipa":"/ˈprefrəns/","pos":"n.","def":"偏爱，喜好；偏好；优先（权）","sen":"I have a preference for fruits over sweets.","trans":"比起糖果，我更喜欢水果。","mne":"pre预先 + fer带来，拿来 + ence名词后缀 → 预先带来的行为 → 偏爱，优先权"},{"word":"prejudice","ipa":"/ˈpredʒədɪs/","pos":"n.","def":"偏见，成见；  v.使抱有偏见","sen":"The other elephants held a prejudice against him because of his giant ears.","trans":"其他大象因他的大耳朵而对其抱有偏见。","mne":"pre预先 + judice判断 → 预先判断 → 偏见"},{"word":"preliminary","ipa":"/prɪˈlɪmɪneri/","pos":"adj.","def":"初步的，预备的","sen":"The preliminary drawings of the building are already finished.","trans":"建筑的初步图稿已经完成。","mne":"pre预先 + limin门槛，限制 + ary形容词后缀 → 入门以前 → preliminary初步的"},{"word":"preparation","ipa":"/ˌprepəˈreɪʃn/","pos":"n.","def":"准备，预备","sen":"She made a lot of preparation for the unborn baby.","trans":"她为还没出生的宝宝做了很多准备。","mne":"prepar = prepare准备 ＋ ation名词后缀 → preparation准备"},{"word":"prepare","ipa":"/prɪˈper/","pos":"v.","def":"准备（食物、物品）；使做好准备；把......预备好","sen":"Dad helps me prepare my school bag every morning.","trans":"爸爸每天早上帮我准备书包。","mne":"pre预先 + pare准备 → 预先准备预先准备好 → prepare准备"},{"word":"prescribe","ipa":"/prɪˈskraɪb/","pos":"v.","def":"给……开药；  v.【计】规定","sen":"The doctor prescribed me some medicine for my cold.","trans":"医生针对我的感冒给我开了一些药。","mne":"pre预先 + scribe写 → 预先写好药量 → prescribe开药方；命令"},{"word":"prescription","ipa":"/prɪˈskrɪpʃn/","pos":"n.","def":"处方；处方，药方","sen":"You can pick up your prescription at the pharmacy after your consultation.","trans":"看完医生后，你可以去药房拿处方药。","mne":"pre预先 + script写 + ion名词后缀 → prescription处方"},{"word":"presence","ipa":"/ˈprezns/","pos":"n.","def":"出席，到场","sen":"Every morning the teacher checks the presence of students in class.","trans":"老师每天早上都在课堂上检查学生的出勤情况。","mne":"pres前 + ence名词后缀 → presence出席，到场"},{"word":"present","ipa":"/ˈprezənt/","pos":"n.","def":"礼物，赠品（读作/ˈprezənt/）；  v.颁发，授予（/prɪˈzent/）；  adj.出席的/ˈprezənt/","sen":"The girl gave me a carefully wrapped present.","trans":"女孩给了我一份精心包装好的礼物。","mne":"pres前 + ent名词后缀 → present礼物，赠送物"},{"word":"preserve","ipa":"/prɪˈzɜːrv/ ","pos":"v.","def":"贮存，保鲜；保存；保护；  n.保护区","sen":"You can preserve food by putting it into the refrigerator.","trans":"你可以把食物放进冰箱保鲜。","mne":"pre预先 + serve保持 → 预先保留 → preserve保存"},{"word":"president","ipa":"/ˈprezɪdənt/","pos":"n.","def":"总统；院长；会长，校长；总裁","sen":"All of them are American presidents.","trans":"他们都是美国总统。","mne":"presid=preside主持，担任主席 + ent人 → president总统"},{"word":"press","ipa":"/pres/","pos":"v.","def":"（尤指用手）按，压；  n.新闻界；出版社","sen":"Press the button on the phone to make a call.","trans":"按电话上的按键来打电话。","mne":""},{"word":"pressure","ipa":"/ˈpreʃər/","pos":"n.","def":"压力；压迫，[物] 压强；  v.对……施加压力","sen":"The pressure of the giant pear is unbearable.","trans":"这个大梨的压力实在是难以承受。","mne":"press挤压 + ure名词后缀，表行为、状态 → pressure压力"},{"word":"pretend","ipa":"/prɪˈtend/","pos":"v.","def":"假装，装扮；自称","sen":"I pretended to study hard, but actually I chatted on my phone.","trans":"我假装很努力地学习，但是实际上我在手机上聊天。","mne":"pre提前 + tend延伸 → 提前伸出想好借口 → pretend假装，借口"},{"word":"pretty","ipa":"/ˈprɪti/","pos":"adj.","def":"漂亮的，俊俏的；  adv.很，颇，相当","sen":"I'm the most loyal fan of these pretty boys.","trans":"我是这几个俊俏的男孩最忠实的粉丝。","mne":""},{"word":"prevail","ipa":"/prɪˈveɪl/","pos":"v.","def":"战胜；流行，普遍存在","sen":"\"Hah! I've finally prevailed!\" shouted the girl in red.","trans":"“哈！我终于赢了！”红衣女大叫道。","mne":"pre预先 + vail强壮 → 能够领先强壮者的获胜 → prevail胜，优胜"},{"word":"prevent","ipa":"/prɪˈvent/","pos":"v.","def":"防止，阻止；预防；阻碍","sen":"The mother prevented her child from eating sweets.","trans":"妈妈不让她的小孩吃糖。","mne":"pre预先 + vent来 → 抢先一步，防止别人 → prevent防止，阻止"},{"word":"previous","ipa":"/ˈpriːviəs/","pos":"adj.","def":"先前的","sen":"People no longer use the old fashioned devices used in previous times.","trans":"人们不再使用以前的老式设备。","mne":"pre以前 + vi路[引申为走] + ous……的 → 以前走过的 → previous先的，前的"},{"word":"previously","ipa":"/ˈpriːviəsli/","pos":"adv.","def":"先前，在此之前","sen":"This place was previously a wasteland.","trans":"这个地方以前是一片荒地。","mne":""},{"word":"price","ipa":"/praɪs/","pos":"n.","def":"价格，价钱；  v.标价","sen":"I like to go shopping during sales when the prices are low.","trans":"我喜欢在打折的时候去买东西，那个时候价格很便宜。","mne":""},{"word":"pride","ipa":"/praɪd/","pos":"n.","def":"自豪；骄傲；  v.使得意；为……自豪","sen":"The parents took pride in their son's graduation.","trans":"父母为儿子的毕业感到很自豪。","mne":""},{"word":"primarily","ipa":"/praɪˈmerəli/","pos":"adv.","def":"主要地","sen":"The air is primarily made up of Nitrogen.","trans":"空气主要是由氮气构成的。","mne":""},{"word":"primary","ipa":"/ˈpraɪˌmeri/","pos":"adj.","def":"初等教育的；最初的；首要的；  n.首选；<美>初选","sen":"Children usually go to primary school at the age of 6.","trans":"通常小孩子6岁就上小学了。","mne":"prim第一，主要的 + ary形容词后缀 → 第一的，最开始的 → primary最初的；根本的"},{"word":"prime","ipa":"/praɪm/","pos":"adj.","def":"最好的，一流的；首要的，主要的","sen":"Our number one priority is to offer our guests prime service.","trans":"我们的首要任务是给客人提供最好的服务。","mne":"prim第一，主要的 + e → prime首要的"},{"word":"primitive","ipa":"/ˈprɪmətɪv/","pos":"adj.","def":"原始的；简陋的","sen":"Primitive men made fire by themselves since they had no electricity.","trans":"原始人没有电，只能自己生火。","mne":"prim=prime最初的，原始的 + itive形容词后缀 → primitive原始的"},{"word":"prince","ipa":"/prɪns/","pos":"n.","def":"王子","sen":"Prince George is the second in line to the British throne.","trans":"乔治王子是英国王位的第二顺位继承人。","mne":""},{"word":"princess","ipa":"/ˈprɪnses/","pos":"n.","def":"公主；王妃","sen":"The princess had a pet pony.","trans":"公主有一匹宠物马。","mne":"princ王子 + ess表示女性（人）或雌性（动物） → princess公主，王妃"},{"word":"principal","ipa":"/ˈprɪnsəpəl/","pos":"n.","def":"校长；【法】本金；  adj.主要的，首要的","sen":"Our principal gives a speech at our graduation ceremony.","trans":"校长在我们的毕业典礼上致辞。","mne":"prin主要的 + cip拿，抓，握住 + al形容词后缀 → principal主要的；首要的"},{"word":"principle","ipa":"/ˈprɪnsəpl/","pos":"n.","def":"原则；原理","sen":"Our business success is based on four fundamental principles.","trans":"我们生意的成功基于四项基本原则。","mne":"prin第一，首要 + ciple拿，抓紧 → principle原则"},{"word":"print","ipa":"/prɪnt/","pos":"v.","def":"打印；印刷；  n.印刷行业","sen":"This machine can print any pattern.","trans":"这台机器可以印刷出任何图案。","mne":""},{"word":"prior","ipa":"/ˈpraɪər/","pos":"adj.","def":"优先的；在...的前面","sen":"At the crossroads, school buses have a prior right to pass.","trans":"在十字路口，校车有优先通行权。","mne":"pr=pri先，前 + ior表形容词  → 较先的  → prior优先的；事先的"},{"word":"priority","ipa":"/praɪˈɔːrəti/","pos":"n.","def":"优先考虑的事；优先权","sen":"These priority seats are reserved for the elderly, the disabled and pregnant women.","trans":"这些优先座位是留给老年人、残疾人和孕妇的。","mne":"prior优先 + ity名词后缀 → priority优先（权），重点"},{"word":"prison","ipa":"/ˈprɪzn/","pos":"n.","def":"监狱；监禁","sen":"This prison has been abandoned for many years.","trans":"这座监狱已被废弃多年了。","mne":"pris拿住，抓住 + on表名词 → 抓人之地 → prison监狱"},{"word":"prisoner","ipa":"/ˈprɪznər/","pos":"n.","def":"囚犯，俘虏；拘留犯","sen":"The people with the striped uniforms were kept as prisoners.","trans":"这些穿着条纹衣服的人是被关押的囚犯。","mne":"prison监狱 ＋ er表示人，行为的主动者，做某事的人 → prisoner囚犯"},{"word":"privacy","ipa":"/ˈpraɪvəsi/","pos":"n.","def":"隐私","sen":"We can protect our personal privacy by enabling pin codes on our phones.","trans":"我们可以通过给手机加密来保护我们的个人隐私。","mne":"priv单个 + acy名词后缀 → 个人的 → privacy隐私"},{"word":"private","ipa":"/ˈpraɪvət/","pos":"adj.","def":"私人的","sen":"Do not enter! This is Mr. Dog's private property.","trans":"禁止进入！这是狗先生的私人住宅。","mne":"priv个人的 + ate使成为 → 私人的"},{"word":"privilege","ipa":"/ˈprɪvəlɪdʒ/","pos":"n.","def":"特权，优待；荣幸","sen":"He enjoys the privilege of fast check-in at the airport he owns.","trans":"他享有在他的机场里快速登机的特权。","mne":"privi单个 + lege法律 → 有个人法律 → privilege特权"},{"word":"prize","ipa":"/praɪz/","pos":"n.","def":"奖品，奖励；  adj.得奖的；  v.珍视","sen":"Finally, he won the first prize.","trans":"最终，他获得了一等奖。","mne":""},{"word":"probable","ipa":"/ˈprɑːbəbl/","pos":"adj.","def":"很可能的","sen":"The smaller dog is the probable one that damaged my shoes.","trans":"很有可能是这只体型较小的狗弄坏了我的鞋。","mne":"prob测试，证明 + able能…的 → 能证明的 → probable可能的"},{"word":"probably","ipa":"/ˈprɑːbəbli/","pos":"adv.","def":"或许，大概；很可能，几乎肯定","sen":"It will probably rain later, so I brought my umbrella.","trans":"一会儿很有可能要下雨，所以我带了雨伞。","mne":"probab=probable可能的 + ly表副词 → probably或许，大概"},{"word":"problem","ipa":"/ˈprɑːbləm/","pos":"n.","def":"难题；困难；问题","sen":"I need to ponder this problem carefully.","trans":"我需要仔细思考这个难题。","mne":"pro向前 + blem扔，投掷 → 扔在前面，提出难题 → problem问题"},{"word":"procedure","ipa":"/prəˈsiːdʒər/","pos":"n.","def":"步骤；程序；手续","sen":"There're three steps in the procedure of hot-dog production.","trans":"热狗的生产过程包括三个步骤。","mne":"pro在前 + ced行走 + ure名词后缀 → 在前面走完的 → procedure程序；手续"},{"word":"proceed","ipa":"/proʊˈsiːd/","pos":"v.","def":"前进，行进；继续进行","sen":"The girl proceeded only after the traffic light turned green.","trans":"绿灯亮起之后，这个女孩才开始往前走。","mne":"pro向前 + ceed行走，前进 → 向前走 → proceed前进"},{"word":"process","ipa":"/ˈprɑːses/ ","pos":"n.","def":"步骤，过程；进程；做事方法；工序；  v.加工；处理","sen":"Follow the process to create a cute paw-shaped ice cream.","trans":"按照这个步骤来做可爱的爪爪冰激凌吧。","mne":""},{"word":"procession","ipa":"/prəˈseʃn/","pos":"n.","def":"队伍，行列，列队行进","sen":"The procession of these yellow chickens seems endless.","trans":"这支由小黄鸡组成的队伍看起来没有尽头。","mne":"pro 向前，在前 + cess 行走，前进 + ion 表示行为、过程或结果 → n.队伍，行列"},{"word":"proclaim","ipa":"/prəˈkleɪm/","pos":"v.","def":"宣告；声明，声称","sen":"He proclaimed the outcome of the negotiations on behalf of his company.","trans":"他代表公司宣告了谈判的结果。","mne":"pro在前 + claim呼喊，叫喊 → 在前面喊 → proclaim公布"},{"word":"produce","ipa":"/prəˈdu:s/","pos":"v.","def":"产生（读作/prəˈdu:s/）；生产，制造；导致；  n.农产品（读作/ˈprɑːduːs/）","sen":"The picking of tomatoes grown by oneself produces a feeling of well-being.","trans":"采摘自己种的西红柿会产生一种幸福感。","mne":"pro向前 + duce引导，带来 → 引向前 → produce生产"},{"word":"product","ipa":"/ˈprɑːdʌkt/","pos":"n.","def":"产品，制品；产物；产品，成果","sen":"These products are made of milk.","trans":"这些产品都是由牛奶制成的。","mne":"pro向前 + duct引导，带来 → 引出的东西 → product产物，产品"},{"word":"production","ipa":"/prəˈdʌkʃn/","pos":"n.","def":"生产；产量；生成，产生","sen":"Thousands of cars are under production in this factory.","trans":"数以千计的汽车在这家工厂进行生产。","mne":"product生产 + ion名词后缀 → production生产"},{"word":"productivity","ipa":"/ˌproʊdʌkˈtɪvəti/","pos":"n.","def":"效率；生产力","sen":"The productivity of the machine is ten bottles a day.","trans":"这台机器每天能生产十个瓶子。","mne":"product产品 ＋ ivity表名词 → productivity生产力，生产活动"},{"word":"profession","ipa":"/prəˈfeʃn/","pos":"n.","def":"职业；行业","sen":"The four people have different professions.","trans":"这四个人有着不同的职业。","mne":"pro在前面 + fess说 + ion表名词 → 在前面说话 → profession职业"},{"word":"professional","ipa":"/prəˈfeʃənl/","pos":"adj.","def":"职业的；  n.专业人员；专业人士","sen":"My parents want me to have a professional career, but which profession should I choose?","trans":"父母希望我步入职业生涯，但是我应该选哪个职业呢？","mne":"profession职业 + al……的 → professional职业的"},{"word":"professor","ipa":"/prəˈfesər/ ","pos":"n.","def":"（学院或大学的）教员；（尤指高职称的）教授","sen":"The man standing in front of the whiteboard is a professor.","trans":"站在白板前的男人是一位教授。","mne":"pro在前面 ＋ fess说 ＋ or人 → 在前面说话的人 → professor教授"},{"word":"proficient","ipa":"/prəˈfɪʃnt/","pos":"adj.","def":"精通的，熟练的","sen":"Despite his young age, the boy is already proficient in seven languages.","trans":"这个男孩小小年纪就精通七国语言。","mne":"pro向前，在前 + fici做 + ent形容词后缀 → 做在别人前面 → proficient精通的"},{"word":"profit","ipa":"/ˈprɑːfɪt/","pos":"n.","def":"利润，盈利；益处；  v.得益，有益于","sen":"His business is finally turning a profit.","trans":"他的生意终于开始盈利了。","mne":"pro很多… + fit做 → 做很多 → profit利润，收益"},{"word":"profitable","ipa":"/ˈprɑːfɪtəbl/","pos":"adj.","def":"有利润的；有益的","sen":"Planting trees can be a profitable investment into your future.","trans":"种植树木是一项对你的未来有利的投资。","mne":"pro前 + fit做，制作 + able能...的 → 能提前做好的 → profitable有利润的"},{"word":"profound","ipa":"/prəˈfaʊnd/","pos":"adj.","def":"深刻的，深远的；渊博的；深奥的","sen":"Reading can bring a profound impact on one's development.","trans":"阅读对一个人的成长有着深刻的影响。","mne":"pro前面 + found基础 → 有基础在前面 → profound有根基的，深刻的"},{"word":"program","ipa":"/ˈproʊɡræm/ ","pos":"n.","def":"程序；节目；  v.编写程序","sen":"Leave me alone! I'm trying to write a program on the computer.","trans":"让我一个人待会儿！我正尝试在电脑上写代码。","mne":"pro在前 + gram写，图 → 在前面写好 → program计划；提纲"},{"word":"programme","ipa":"/ˈproʊɡræm/","pos":"n.","def":"节目，电视节目；计划；程序；  v.计划","sen":"The whole family is watching its favourite TV programme.","trans":"所有的家庭成员一起看着他们最爱的电视节目。","mne":"pro很多 + gram写 + me → programme程序，编程"},{"word":"progress","ipa":"/ˈprɑːɡres/, /prəˈɡres/","pos":"n.","def":"进步；前进（读作/ˈprɑːɡres/）；  v.进展（读作/prəˈɡres/）；发展","sen":"The chart showed that we were making progress, selling more every year.","trans":"这张图表说明我们在取得进步，销量一年高于一年。","mne":"pro向前，在前 + gress走 → 向前走 → progress进步"},{"word":"progressive","ipa":"/prəˈɡresɪv/","pos":"adj.","def":"先进的；进步的；  n.进步人士","sen":"This hospital introduced progressive medical methods.","trans":"这家医院引进了先进的医疗方法。","mne":"pro向前 + gress走 + ive表形容词 → progressive进步的"},{"word":"prohibit","ipa":"/prəˈhɪbɪt/","pos":"v.","def":"禁止","sen":"The law prohibits spitting in public.","trans":"该法令禁止在公共场合随地吐痰。","mne":"pro向前，提前 + hibit拿住，握住 → 在前面拿住 → prohibit阻止，禁止"},{"word":"project","ipa":"/ˈprɑːdʒekt/, /prəˈdʒekt/","pos":"n.","def":"项目，工程，习作项目；  v.投射；计划，规划；突出，伸出","sen":"The housing project is going on well as planned.","trans":"这个住宅工程正在如期进展。","mne":"pro向前，在前 + ject扔 → 扔向前面 → project投射"},{"word":"prominent","ipa":"/ˈprɑːmɪnənt/","pos":"adj.","def":"突出的，杰出的","sen":"The statue in the plaza depicted a prominent figure from our school's history.","trans":"广场上的雕像刻画的是我们学校历史上一位杰出人物。","mne":"pro向前，在前 + min伸 + ent形容词后缀 → 向前伸出 → prominent杰出的"},{"word":"promise","ipa":"/ˈprɑːmɪs/","pos":"n.","def":"诺言；成功的迹象；吉兆；  v.预示","sen":"We make a promise by pulling each other's little finger.","trans":"我们拉钩来许下承诺。","mne":"pro前面 + mise送，放出 → 在做事前送出的话 → promise承诺，允诺"},{"word":"promote","ipa":"/prəˈmoʊt/ ","pos":"v.","def":"升职；促进；宣传；推销","sen":"He was very good at his job, so his boss promoted him to a higher position.","trans":"他工作表现很棒，所以他的老板让他升职了。","mne":"pro向前，在前 + mot动 + e → 向前动 → promote促进"},{"word":"promotion","ipa":"/prəˈmoʊʃən/","pos":"n.","def":"提拔，晋升；提升；促销；促进","sen":"He got a promotion and is now the CEO of the company.","trans":"他在工作中得到了晋升，现在是这家公司的首席执行官。","mne":"pro向前 + mot移动 + ion名词后缀 → 促进；升级"},{"word":"prompt","ipa":"/prɑːmpt/","pos":"v.","def":"敦促，促使，激励；  adj.迅速的，及时的；  n.提示","sen":"My phone prompts me to get out of bed and finish my paper!","trans":"我的手机敦促我起床写论文！","mne":"pro先，前 + mpt=empt拿 → 最先拿到的 → prompt迅速的，及时的"},{"word":"pronoun","ipa":"/ˈproʊnaʊn/","pos":"n.","def":"代词","sen":"If you don't want to say a name, you can just use a pronoun like \"he\" or \"him\".","trans":"如果你不想说名字，你可以只用“他”这种代词。","mne":"pro代替 + noun名字，名词 → pronoun代词"},{"word":"pronounce","ipa":"/prəˈnaʊns/","pos":"v.","def":"发音；发表，宣布","sen":"Open your mouth wide when you pronounce this sound.","trans":"发这个音时，嘴巴要张大。","mne":"pro在前 + nounce讲话，说出 → 在嘴前讲话 → pronounce发音"},{"word":"pronunciation","ipa":"/prəˌnʌnsiˈeɪʃn/","pos":"n.","def":"发音；读音","sen":"These different mouth shapes can help us practice our pronunciation.","trans":"这些不同的嘴型能够帮助我们练习发音。","mne":"pro在前 + nunci讲话，说出 + ation名词后缀 → pronunciation发音"},{"word":"proof","ipa":"/pruːf/","pos":"n.","def":"证据，证明；  v.校对","sen":"The surveillance cameras provided clear proof of many cases.","trans":"监控摄像头为许多案件提供了明确的证据。","mne":""},{"word":"proper","ipa":"/ˈprɑːpər/","pos":"adj.","def":"适合的，适用的；恰当的","sen":"You should wear a proper outfit at a cocktail party. ","trans":"你要选一套合适的服装去参加鸡尾酒会。","mne":""},{"word":"properly","ipa":"/ˈprɑːpərli/","pos":"adv.","def":"适当地；得体地；正确地","sen":"It's important to adjust your sitting posture properly.","trans":"适当地调整坐姿很重要。","mne":"proper恰当的 + ly...地 → properly正确地；恰当地"},{"word":"property","ipa":"/ˈprɑpərti/","pos":"n.","def":"房产；财产；特性；性能","sen":"He had finally saved enough money to buy a property.","trans":"他终于攒了足够的钱来置办一处房产。","mne":"proper拥有 + ty名词后缀 → 个人拥有的 → property房产"},{"word":"proportion","ipa":"/prəˈpɔːrʃn/","pos":"n.","def":"比例；部分；相称；  v.使成比例；分配","sen":"The proportion shows we should eat more vegetables and fruits to keep healthy.","trans":"该比例显示，我们应该多吃蔬菜和水果来保持健康。","mne":"pro前面 + port 部分，分开 + ion名词后缀 → 成分其中一部分 → proportion比例"},{"word":"proposal","ipa":"/prəˈpoʊzl/","pos":"n.","def":"求婚；建议；提案","sen":"That guy made a proposal to his girlfriend with a diamond ring.","trans":"那位男士手拿钻戒，向他的女朋友求婚。","mne":"pro向前 + pos放 + al名词后缀 → 向前放 → proposal提建议"},{"word":"propose","ipa":"/prəˈpoʊz/","pos":"v.","def":"提议；  v.求婚","sen":"He sincerely proposed a date, hoping to ring in the New Year with the girl.","trans":"他真诚地提议约会，希望能与女孩一起迎接新年。","mne":"pro向前 + pose放置 → 向前呈，呈出 → propose提出，提议"},{"word":"prospect","ipa":"/ˈprɑːspekt/","pos":"n.","def":"前景，展望；希望；  v.勘探","sen":"She has excellent career prospects with her diverse skills and experience.","trans":"凭借多样的技能和经验，她拥有广阔的职业前景。","mne":"pro向前，在前 + spect看 → 向前看 → prospect前景"},{"word":"prosper","ipa":"/ˈprɑːspər/","pos":"v.","def":"使繁荣；使成功","sen":"With more and more wealth and development, the city continues to prosper.","trans":"随着越来越多的财富和发展机会，城市持续繁荣。","mne":"pro前面 + sper希望 → 希望在前面 → prosper繁荣"},{"word":"prosperity","ipa":"/prɑːˈsperəti/","pos":"n.","def":"繁荣；繁荣，兴旺，发达","sen":"Economic policies focused on innovation can lead to national prosperity.","trans":"专注于创新的经济政策能带来国家繁荣。","mne":"prosper繁荣 + ity表名词 → prosperity繁荣昌盛"},{"word":"prosperous","ipa":"/ˈprɑːspərəs/","pos":"adj.","def":"繁荣的","sen":"We are fortunate to live in a prosperous country where opportunities abound and peace is taken for granted.","trans":"我们很幸运，生活在一个充满机遇、繁荣富强的国家，安宁和谐已是寻常。","mne":"pro向前 ＋ sper希望 ＋ ous形容词后缀 → 带着希望向前 → prosperous兴旺的"},{"word":"protect","ipa":"/prəˈtekt/ ","pos":"v.","def":"保护；防护","sen":"Builders should wear professional equipment to protect themselves.","trans":"建筑工人需要穿着专业装备来保护自己。","mne":"pro在前面 + tect盖上，保护 → 在前面盖上 → protect保护；防止"},{"word":"protection","ipa":"/prəˈtekʃn/","pos":"n.","def":"保护，防卫","sen":"Everyone should get involved in environmental protection.","trans":"每个人都应该投身到环境保护工作中来。","mne":"protect保护，防止 + ion表名词 → protection保护"},{"word":"protective","ipa":"/prəˈtektɪv/","pos":"adj.","def":"防护的，保护的","sen":"Construction workers must wear protective equipment.","trans":"建筑工人必须穿戴防护装备。","mne":"protect保护 + ive形容词后缀 → protective保护的，防护的"},{"word":"protein","ipa":"/ˈprəʊtiːn/","pos":"n.","def":"蛋白质","sen":"You can get protein from eggs, beans, and meat.","trans":"你可以从鸡蛋、豆类以及肉类中获取蛋白质。","mne":"prote第一的，原本的 + in化学中的构词成分 → 化学物质中基础的成分 → protein蛋白质"},{"word":"protest","ipa":"/ˈprəʊtest/","pos":"v.","def":"抗议；反对（读作/proʊˈtɛst/）；  n.抗议（读作/ˈproʊˌtɛst/）","sen":"Raising fists and flags is a symbol of protesting something.","trans":"举起拳头和旗帜是抗议的一种标志。","mne":"pro在前面 + test证据 → 向前作证 → protest抗议，坚决声明"},{"word":"proud","ipa":"/praʊd/","pos":"adj.","def":"骄傲的，自豪的","sen":"He's proud of himself because everyone thinks he did a great job!","trans":"他为自己骄傲，因为大家都觉得他做得很棒！","mne":""},{"word":"prove","ipa":"/pruːv/","pos":"v.","def":"证明，证实","sen":"It takes one second to say \"I do,\" but a lifetime to prove it.","trans":"说一句“我愿意”只用一秒，可证明它却需要一辈子。","mne":"pro在前面 + ve成为 → 成为先决条件，以证实某事存在 → prove证明，证实"},{"word":"proverb","ipa":"/ˈprɑːvɜːrb/","pos":"n.","def":"谚语","sen":"The dog chasing the mouse reminded the old man of a Chinese proverb.","trans":"狗追老鼠的场景使这位老人想起了一句中国谚语。","mne":"pro前面 + verb词语 → 古人的言语 → proverb谚语"},{"word":"provide","ipa":"/prəˈvaɪd/","pos":"v.","def":"提供，供给","sen":"This restaurant provides free juice.","trans":"这家餐厅提供免费果汁。","mne":"pro提前 + vid看 + e → 提前看好 → provide预备；提供"},{"word":"provided","ipa":"/prəˈvaɪdɪd/","pos":"conj.","def":"如果，以……为条件；  v.提供（provide的过去式）","sen":"You may watch TV, provided your homework is finished first.","trans":"如果你先把家庭作业做完，你就可以看电视了。","mne":""},{"word":"province","ipa":"/ˈprɑːvɪns/","pos":"n.","def":"省；领域，部门；知识(或职责)范围","sen":"This is a famous tourist spot in Sichuan Province.","trans":"这是四川省的一处著名旅游景点。","mne":"pro向前，在前 + vinc征服 + e → province被向前征服了的（土地）→ 省；领域"},{"word":"provision","ipa":"/prəˈvɪʒn/","pos":"n.","def":"必需品；（法律等的）条款；预备，存粮；规定","sen":"We set out with enough provisions to last the trip.","trans":"我们带上足够维持整场旅行的必需品后就出发了。","mne":"pro提前 + vis看 + ion名词后缀 → provision预备"},{"word":"psychological","ipa":"/ˌsaɪkəˈlɑdʒɪkəl/","pos":"adj.","def":"心理的，心理学的","sen":"The professor is explaining a famous psychological experiment to his students.","trans":"教授正在向学生们解释一个著名的心理学实验。","mne":"psycho=psych灵魂 + logical…学的 → psychological心理的，心理学的"},{"word":"psychology","ipa":"/saɪˈkɑːlədʒi/","pos":"n.","def":"心理学；心理","sen":"I study psychology to learn about how people think.","trans":"我学心理学是为了了解人们如何思考。","mne":"psych灵魂 + ology……学 → psychology心理学，心理状态"},{"word":"public","ipa":"/ˈpʌblɪk/","pos":"n.","def":"公众，民众；  adj.公众的","sen":"The public are gathering on the street.","trans":"民众在街上聚集。","mne":"publ人民 + ic...的 → public公开的，公众的"},{"word":"publication","ipa":"/ˌpʌblɪˈkeɪʃn/","pos":"n.","def":"出版，发行；出版物；公布","sen":"Once the publication process is complete, the book will be available to buy.","trans":"出版流程一完成，就可以买到这本书了。","mne":"public公众的 + ation名词后缀 → 让公众都看到 → publication出版"},{"word":"publicly","ipa":"/ˈpʌblɪkli/","pos":"adv.","def":"公开地；公然地","sen":"He delivered his speech publicly to spread the information.","trans":"他公开发表演讲来传播信息。","mne":""},{"word":"publish","ipa":"/ˈpʌblɪʃ/","pos":"v.","def":"出版；公布","sen":"She hopes that her book will be published so everyone can buy it.","trans":"她希望自己的书能够出版，这样每个人都可以购买。","mne":"publ公众 + ish动词后缀 → 使面向公众 → publish出版"},{"word":"pull","ipa":"/pʊl/","pos":"v.","def":"拉，拖，扯，拔","sen":"She pulls the woman toward her.","trans":"她把那名女子拉向自己。","mne":""},{"word":"pulse","ipa":"/pʌls/","pos":"n.","def":"脉搏；（电子）脉冲；  v.（使）跳动，搏动，震动","sen":"The doctor takes the patient's pulse to determine her illness.","trans":"医生通过把脉来判断病人的病情。","mne":""},{"word":"punch","ipa":"/pʌntʃ/","pos":"v.","def":"以拳痛击；  n.拳打","sen":"She punched her opponent fiercely in the face.","trans":"她用拳头猛击对手的脸。","mne":""},{"word":"punctual","ipa":"/ˈpʌŋktʃuəl/","pos":"adj.","def":"准时的，守时的","sen":"I'm always punctual; I'm never late for work.","trans":"我总是很守时，上班从来不迟到。","mne":"punct点 + ual…的 → 总能踩准点的 → punctual严守时刻的；准时的"},{"word":"punish","ipa":"/ˈpʌnɪʃ/","pos":"v.","def":"惩罚，处罚","sen":"He punished the player by showing the red card.","trans":"他亮出红牌以惩罚一名球员。","mne":"pun处罚 + ish动词后缀 → punish惩罚"},{"word":"punishment","ipa":"/ˈpʌnɪʃmənt/","pos":"n.","def":"惩罚，处罚","sen":"A harsh punishment can do more harm than good.","trans":"严厉的惩罚会弊大于利。","mne":"punish惩罚 + ment表名词 → punishment处罚"},{"word":"pupil","ipa":"/ˈpjuːpl/","pos":"n.","def":"学生，小学生；瞳孔","sen":"The pupils are walking to school.","trans":"小学生们走路去学校。","mne":""},{"word":"purchase","ipa":"/ˈpɜːrtʃəs/","pos":"v.","def":"购买；  n.购买；购买的东西","sen":"The shirt is so cheap that I really want to purchase it.","trans":"这件T恤太便宜了，我真的想买。","mne":"pur向前 + chase追逐 → purchase购买"},{"word":"pure","ipa":"/pjʊr/","pos":"adj.","def":"纯的，纯净的；纯粹的","sen":"The water in the glass looks very pure.","trans":"杯中的水看起来非常纯净。","mne":""},{"word":"purple","ipa":"/ˈpɜːrp(ə)l/","pos":"n.","def":"紫色；  adj.紫色的","sen":"Purple is my favorite color.","trans":"紫色是我最喜欢的颜色。","mne":""},{"word":"purpose","ipa":"/ˈpɜːrpəs/","pos":"n.","def":"目的，意图","sen":"His purpose for exercising is to get more muscles.","trans":"他健身的目的是为了练出更多的肌肉。","mne":"pur始终 + pose放 → 始终放的东西 → purpose目的，意图"},{"word":"purse","ipa":"/pɜːrs/","pos":"n.","def":"钱包（尤指女用的），小钱袋，手袋；资金，财源","sen":"All my money is in my purse.","trans":"我所有的钱都在我的小钱包里。","mne":""},{"word":"pursue","ipa":"/pərˈsuː/","pos":"v.","def":"追赶；追求；追究","sen":"The police were pursuing the two thieves who had stolen a woman's purse.","trans":"警察正在追赶那两个小偷，他们偷了一个女人的钱包。","mne":"pur=pro向前 + sue跟随 → pursue追求"},{"word":"pursuit","ipa":"/pərˈsuːt/","pos":"n.","def":"追赶，跟踪","sen":"She followed in pursuit of her friend.","trans":"她在后面追赶着她的朋友。","mne":"pursu=pursue追求 + it名词后缀，表抽象名词 → pursuit追求"},{"word":"push","ipa":"/pʊʃ/","pos":"v.","def":"推；逼迫；  n.推，推力","sen":"I ran out of gas, so my wife made me get out and push the car.","trans":"我的车没汽油了，所以被妻子赶下来推车。","mne":""},{"word":"put","ipa":"/pʊt/","pos":"v.","def":"放，摆","sen":"I put this green vase on the table.","trans":"我把这个绿色的花瓶放到了桌子上。","mne":""},{"word":"puzzle","ipa":"/ˈpʌzl/ ","pos":"n.","def":"难题；谜，智力游戏；  v.使迷惑，迷惑","sen":"As a test, he asked the girl to draw a puzzle.","trans":"柯布让阿德里安设计一个迷宫以作测试。（《盗梦空间》）","mne":""},{"word":"qualification","ipa":"/ˌkwɑːlɪfɪˈkeɪʃn/","pos":"n.","def":"资格证明","sen":"It requires a nursing qualification to become a nurse.","trans":"当护士需要护士资格证。","mne":"qual=quality质量 + ification表名词 → qualification资格证明"},{"word":"qualified","ipa":"/ˈkwɑːlɪfaɪd/","pos":"adj.","def":"有资格的；合格的，胜任的；保留的；  v.取得…的资格","sen":"She is a qualified teacher.","trans":"她是一位有资格的老师。","mne":"qualif=qualify资格 + ied形容词后缀 → qualified有资格的"},{"word":"qualify","ipa":"/ˈkwɑːlɪfaɪ/","pos":"v.","def":"胜任，使具有资格；  v.（使）合格","sen":"His skills qualify him for his work.","trans":"他的技能让他能够胜任这份工作。","mne":"quali=quality质量 + fy动词后缀 → 使...有高质量 → qualify胜任，使具有资格"},{"word":"quality","ipa":"/ˈkwɑ:ləti/","pos":"n.","def":"质量；素质，品德；品质","sen":"The quality of this spoon is too terrible!","trans":"这勺子的质量太差了！","mne":"qual资格 + ity表名词 → quality质量；品质，特性"},{"word":"quantity","ipa":" /ˈkwɑːntəti/","pos":"n.","def":"数量，数额；大量，许多","sen":"The woman received a large quantity of beautiful roses.","trans":"这位女士收到了许多美丽的玫瑰。","mne":"quant多少，数量 + ity表名词 → quantity量，数量"},{"word":"quarantine","ipa":"/ˈkwɔːrəntiːn/","pos":"n.","def":"检疫期；  v.检疫；隔离","sen":"We've sealed off this area following quarantine protocol.","trans":"我们按检疫规程封锁了这个区域。","mne":"quarant检疫 + ine表示抽象名词 → quarantine隔离检查"},{"word":"quarrel","ipa":"/ˈkwɔːrəl/","pos":"n.","def":"争吵，口角；  v.争吵，争论","sen":"They had a heated quarrel last night.","trans":"他们昨晚发生了一场激烈的争吵。","mne":"quarr=quer抱怨 + el人，集体 → 几个人同时抱怨对方的不好 → quarrel争吵"},{"word":"quarter","ipa":"/ˈkwɔːrtər/","pos":"n.","def":"四分之一； 一个季度； 一刻钟；地区；  v.把……四等分","sen":"This stopwatch shows that a quarter of a minute has passed.","trans":"这块秒表显示已经过去了十五秒。","mne":"quart四 + er名词后缀 → quarter四分之一；一刻钟"},{"word":"queen","ipa":"/kwiːn/","pos":"n.","def":"王后，女王","sen":"The queen in a long red dress stands beside the king.","trans":"王后身着一袭红裙，站在国王身旁。","mne":""},{"word":"question","ipa":"/ˈkwestʃən/","pos":"n.","def":"疑问，问题；  v.正式提问，询问；怀疑","sen":"I have so many questions about everything.","trans":"我对很多东西都有疑问。","mne":"quest寻求，询问 + ion名词后缀 → question疑问"},{"word":"queue","ipa":"/kjuː/","pos":"n.","def":"队，行列；  v.排队等候","sen":"There is a long queue of hundreds of people.","trans":"数以百计的人排起了长队。","mne":"que=cue尾巴 + ue → 形成尾巴状的一条 → queue行列，排队"},{"word":"quick","ipa":"/kwɪk/","pos":"adj.","def":"快的；迅速的，快捷的","sen":"The pace of life in the city can be very quick.","trans":"城市的生活节奏是非常快的。","mne":""},{"word":"quiet","ipa":"/ˈkwaɪət/","pos":"adj.","def":"安静的","sen":"Please be quiet.","trans":"请保持安静。","mne":""},{"word":"quit","ipa":"/kwɪt/","pos":"v.","def":"辞职；戒掉；离开（工作职位、学校等）","sen":"The office worker was so happy after he quit his job.","trans":"这名公司职员辞掉工作后感到很开心。","mne":" "},{"word":"quite","ipa":"/kwaɪt/","pos":"adv.","def":"很，非常；相当，完全；非常","sen":"My hair is quite soft and smooth without any special effects.","trans":"我的头发很柔很顺，毫无特技呢。","mne":""},{"word":"quotation","ipa":"/kwoʊˈteɪʃn/","pos":"n.","def":"引文，引语，语录；行情，行市；报价，牌价","sen":"People often use quotations from Shakespeare.","trans":"人们经常引用莎士比亚的文字。","mne":"quot=quote引用 + ation表行为 → 引文，引语"},{"word":"quote","ipa":"/kwoʊt/","pos":"v.","def":"引用；报价；【法】报价；  n.引语，引文","sen":"She often quotes Shakespeare to support her arguments.","trans":"她经常引用莎士比亚的语句来支持她的论点。","mne":""},{"word":"rabbit","ipa":"/ˈræbɪt/","pos":"n.","def":"兔子，（野）兔","sen":"Would you like a pet rabbit?","trans":"你想要一只宠物兔吗？","mne":""},{"word":"race","ipa":"/reɪs/ ","pos":"n.","def":"人种，种族；竞赛，赛跑；  v.参加竞赛；全速行进","sen":"There are many different races in this world.","trans":"海贼王的世界里有很多不同的人种（鱼人，小人，普通人种，巨人）。","mne":""},{"word":"racial","ipa":"/ˈreɪʃl/","pos":"adj.","def":"种族的","sen":"There are many different racial groups in this world.","trans":"这个世界有许多不同的种族群体。","mne":"rac(e)种族 + ial形容词后缀 → racial种族的"},{"word":"radar","ipa":"/ˈreɪdɑːr/","pos":"n.","def":"雷达，无线电探测器","sen":"We saw the airplane with radar before we could see it with our own eyes.","trans":"在肉眼能看到飞机前，我们就能用雷达探测到它了。","mne":""},{"word":"radiate","ipa":"/ˈreɪdieɪt/","pos":"v.","def":"辐射，发出（光或热）；辐射，发出光或热","sen":"The sun radiates light and heat towards the earth.","trans":"太阳向地球发出光和热。","mne":"radi光线 + ate造成、使之成…… → radiate辐射，（使）从中心发散"},{"word":"radiation","ipa":"/ˌreɪdiˈeɪʃn/ ","pos":"n.","def":"辐射；放射线","sen":"Don't get close to radiation if you are not in a protective suit.","trans":"没有穿防辐射服就不要靠近辐射物。","mne":"radi辐射 + ation表示行为、状态、过程、结果 → radiation辐射能"},{"word":"radical","ipa":"/ˈrædɪkl/","pos":"adj.","def":"彻底的，根本的；激进的；  n.激进分子","sen":"Over the centuries, we have seen some radical changes in fashion.","trans":"几个世纪以来，我们目睹了时尚领域的根本变化。","mne":"radic根 + al……的 → radical根本的，基本的"},{"word":"radio","ipa":"/ˈreɪdioʊ/","pos":"n.","def":"收音机；无线电；（无线电）广播节目","sen":"The woman is listening to the radio with a cup of coffee in her hand.","trans":"这位女士手端着咖啡，正在听收音机。","mne":""},{"word":"rag","ipa":"/ræɡ/","pos":"n.","def":"抹布，破布，碎布","sen":"She used a rag to clean the window.","trans":"她在用抹布擦玻璃窗。","mne":""},{"word":"rage","ipa":"/reɪdʒ/","pos":"n.","def":"极怒；流行","sen":"He was totally in a rage when he saw the message.","trans":"看到那条信息时，他完全暴怒了。","mne":""},{"word":"railroad","ipa":"/ˈreɪlroʊd/","pos":"n.","def":"铁路；  v.迫使某人做某事","sen":"I'm afraid of flying, so I usually use the railroad to travel.","trans":"我怕坐飞机，所以我长途旅行都选择坐火车（铁路运输）。","mne":"rail铁轨 + road路 → railroad铁路"},{"word":"railway","ipa":"/ˈreɪlweɪ/","pos":"n.","def":"铁路，铁道","sen":"I like to travel by taking the high-speed railway, because it's very fast.","trans":"我喜欢坐高铁出去旅游，因为特别快。","mne":""},{"word":"rain","ipa":"/reɪn/","pos":"n.","def":"雨，雨水；  v.下雨","sen":"This guy is singing in the rain.","trans":"这个男人在大雨中唱着歌。","mne":""},{"word":"rainbow","ipa":"/ˈreɪnboʊ/","pos":"n.","def":"虹，彩虹","sen":"A rainbow arched across the sky.","trans":"一道彩虹横跨天际。","mne":"rain雨 + bow弓 → rainbow彩虹"},{"word":"raise","ipa":"/reɪz/","pos":"v.","def":"举起，抬高；提升；筹集，筹（钱）；增加；提高；加薪","sen":"The kitten raises his friend up to steal the fish.","trans":"这只小猫咪把朋友举起来偷鱼。","mne":""},{"word":"random","ipa":"/ˈrændəm/","pos":"adj.","def":"随机的；任意的；  n.随意，胡乱","sen":"It's just a random series of numbers.","trans":"这就是一系列随机的数字。","mne":""},{"word":"randomly","ipa":"/ˈrændəmli/","pos":"adv.","def":"任意地；随便地","sen":"This is a prize wheel that spins randomly.","trans":"这是一个抽奖转盘。","mne":""},{"word":"range","ipa":"/reɪndʒ/ ","pos":"n.","def":"一系列；【计】范围；山脉；  v.（在一定范围内）变化","sen":"People use different facial expressions to show a range of emotions.","trans":"人们用不同的面部表情来展示一系列的情绪。","mne":""},{"word":"rank","ipa":"/ræŋk/","pos":"n.","def":"等级，级别；军队中的官阶；地位；行列；  v.排列；把……分等级，属于某个等级；  adj.繁茂的；难闻的，讨厌的","sen":"They got different ranks after performing.","trans":"他们在表演后得到了不同的等级。","mne":""},{"word":"rapid","ipa":"/ˈræpɪd/","pos":"adj.","def":"迅速的；急促的","sen":"The train is traveling at a rapid pace.","trans":"火车正在急速行驶。","mne":""},{"word":"rapidly","ipa":"/ˈræpɪdli/","pos":"adv.","def":"迅速地，快速地","sen":"The river flows rapidly.","trans":"这条河水流湍急。","mne":"rapid迅速 ＋ ly副词后缀表示状态、程度、方式 → rapidly迅速地；很快地"},{"word":"rare","ipa":"/rer/","pos":"adj.","def":"（肉）半熟的；罕见的，难得的","sen":"He likes eating rare steak, which is bloody and red in the middle.","trans":"他喜欢吃那种中间呈血红色的一分熟牛排。","mne":""},{"word":"rarely","ipa":"/ˈrerli/","pos":"adv.","def":"很少，难得","sen":"It rarely snows in Chengdu.","trans":"成都很少下雪。","mne":"rare稀少的 + ly……的 → rarely很少，难得"},{"word":"rat","ipa":"/ræt/","pos":"n.","def":"老鼠，耗子","sen":"Look! The three rats are waving to us.","trans":"看，这三只老鼠在跟我们挥手。","mne":""},{"word":"rate","ipa":"/reɪt/","pos":"v.","def":"评估；定等级，评级；认为；评估，估量；  n.率，比率；速度，速率；价格，价钱","sen":"The air quality of this city is rated as poor.","trans":"该市的空气质量被评为差。","mne":""},{"word":"rather","ipa":"/ˈræðər/","pos":"adv.","def":"相当；宁愿（would rather）","sen":"It's rather cold today.","trans":"今天相当冷。","mne":""},{"word":"ratio","ipa":"/ˈreɪʃioʊ/","pos":"n.","def":"比率，比例","sen":"The ratio of boys to girls is about 2 to 1 in the club.","trans":"这个社团的男女比率大概是2比1。","mne":"rati=rate比率 + o表名词，状态 → ratio比率，比"},{"word":"rational","ipa":"/ˈræʃənl/","pos":"adj.","def":"理性的，理智的；合理的","sen":"She remained rational in the face of a heavy workload.","trans":"她在面对繁重的工作时依然保持理智。","mne":"ration定量，计算 + al……的 → 通过计算的 → rational合理的"},{"word":"raw","ipa":"/rɔ:/","pos":"adj.","def":"生的，未煮过的；未加工的","sen":"The beef on the wooden board is raw.","trans":"木板上的牛肉是生的。","mne":""},{"word":"ray","ipa":"/reɪ/","pos":"n.","def":"光线；光束","sen":"Part of the sun's rays are blocked by clouds.","trans":"一部分太阳光线被云层挡住了。","mne":""},{"word":"reach","ipa":"/riːtʃ/","pos":"v.","def":"到达；抵达","sen":"Using the red ladder, I can reach the top.","trans":"我能用这架红色的梯子到达顶部。","mne":""},{"word":"react","ipa":"/riˈækt/","pos":"v.","def":"反应","sen":"Different people react differently when watching a movie.","trans":"看电影时，不同的人有不同的反应。","mne":"re相反、反对 + act行动，做 → react起反应；有影响"},{"word":"reaction","ipa":"/riˈækʃn/","pos":"n.","def":"反应","sen":"The audience have different reactions to the same movie.","trans":"对于同一部电影，观众们有着不同的反应。","mne":"re相反，“反” + act行动，“应” + ion名词后缀 → reaction反应"},{"word":"read","ipa":"/ri:d/","pos":"v.","def":"读，朗读","sen":"The young lady is reading a book in the library.","trans":"这位年轻的女士正在图书馆读书。","mne":""},{"word":"readily","ipa":"/ˈredɪli/","pos":"adv.","def":"欣然地；容易地","sen":"The girl readily accepted his invitation to go to the live music show.","trans":"女孩欣然接受了他提出的去看现场音乐表演的邀请。","mne":"readi=ready准备好的，情愿的 + ly……地 → readily乐意地，欣然地；容易地"},{"word":"ready","ipa":"/ˈredi/","pos":"adj.","def":"准备好的；现成的；  v.预备，准备","sen":"He is ready to run.","trans":"他准备好起跑了。","mne":""},{"word":"real","ipa":"/ˈriːəl/","pos":"adj.","def":"真实的，实际存在的；真的；真正的，名副其实的","sen":"The mirror did not show his real reflection.","trans":"这个镜子没有反映出他真实的样子。","mne":""},{"word":"realisation","ipa":"/ˌriːələˈzeɪʃn/","pos":"n.","def":"认识，领会，实现","sen":"The building is the realisation of his creative design.","trans":"这座建筑实现了他创造性的设计。","mne":"realize看到真的=意识到 + ation表名词 → realisation认识，领会"},{"word":"realise","ipa":"/ˈriːəlaɪz/","pos":"v.","def":"实现（=realize）；  v.认识到","sen":"She worked hard to realise her dream of becoming a doctor.","trans":"她努力工作，实现了成为医生的梦想。","mne":""},{"word":"realistic","ipa":"/ˌriːəˈlɪstɪk/","pos":"adj.","def":"现实的，实际的","sen":"The realistic chance of winning the prize draw is very low.","trans":"赢得抽奖的现实可能性极低。","mne":"real真的 + istic...的 → 逼真的"},{"word":"reality","ipa":"/riˈæləti/","pos":"n.","def":"现实，实际；事实","sen":"The photo without filter makes me realize the reality.","trans":"没有滤镜的照片使我认清了现实。","mne":"real真实的 + ity名词后缀 → reality现实，真实"},{"word":"realization","ipa":"/ˌriːələˈzeɪʃn/","pos":"n.","def":"认识，领会，领悟，实现","sen":"I suddenly had a realization that I forgot to lock the door.","trans":"我突然意识到我忘记锁门啦。","mne":"realiz（e）看到真实=意识到 + ation表名词 → realization意识到"},{"word":"realize","ipa":"/ˈriːəlaɪz/","pos":"v.","def":"认识到，意识到（=realise）；实现；意识到","sen":"\"So that's how the word is spelled!\" the little boy finally realized.","trans":"“原来这个单词是这样拼写的！”小男孩终于意识到了这一点。","mne":"real真实的 + ize表动词 → realize实现"},{"word":"really","ipa":"/ˈriːəli/","pos":"adv.","def":"事实上，真正地","sen":"I don't see the point in it really.","trans":"我真的不理解这到底有什么意义。","mne":"real真实的 + ly表副词 → really真正地"},{"word":"rear","ipa":"/rɪr/","pos":"adj.","def":"背面的；后面的；  v.抚养","sen":"I could only see a tree in my rear-view mirror.","trans":"从后视镜里我只能看到一棵树。","mne":""},{"word":"reason","ipa":"/ˈriːzn/","pos":"n.","def":"原因，理由；理性；  v.论证，推理，劝说","sen":"The reason why he's late for school is that he stayed up late doing homework last night.","trans":"他迟到的原因是昨晚熬夜写作业了。","mne":""},{"word":"reasonable","ipa":"/ˈriːznəbl/","pos":"adj.","def":"合理的","sen":"He bought the apples at a reasonable price.","trans":"他用合理的价格买了苹果。","mne":"reason合理 + able形容词后缀，具有某种性质的 → 合理的，通情达理的"},{"word":"rebel","ipa":"/rɪˈbel/, /ˈrebl/","pos":"v.","def":"造反，反抗，反叛；  n.叛逆者；造反者","sen":"The little boy often rebels against his mother.","trans":"这个小男孩经常反抗他的母亲。","mne":"re相反 + bel斗争 → 反打 → 反叛 → rebel反抗，造反"},{"word":"recall","ipa":"/rɪˈkɔːl/","pos":"v.","def":"回想起，记起，回忆；召回","sen":"Looking at the photo, she recalled the old time with her husband.","trans":"看着这张照片，她回忆起和丈夫的旧时光。","mne":"re回，向后 + call呼唤 → recall召回，回忆"},{"word":"receipt","ipa":"/rɪˈsiːt/","pos":"n.","def":"收据，收条","sen":"Check all your receipts when you pay your taxes.","trans":"当你交税时，一定要检查所有收据。","mne":"re一再，重新 + ceipt收 → receipt收据"},{"word":"receive","ipa":"/rɪˈsiːv/","pos":"v.","def":"收到，得到","sen":"I received a thank-you note from my good friend.","trans":"我从好朋友那里收到了一张感谢卡。","mne":"re再 + ceiv抓，拿 + e后缀 → 再次拿到 → receive得到，收到"},{"word":"receiver","ipa":"/riˈsiːvər/","pos":"n.","def":"听筒；接管人","sen":"The man is holding the receiver of the phone.","trans":"这个男人正手拿着电话听筒。","mne":"re回，向后 + ceiv拿，抓，握住 + er名词后缀 → receiver接收器"},{"word":"recent","ipa":"/ˈriːsnt/","pos":"adj.","def":"最近的","sen":"These are my recent photos.","trans":"这些是我最近拍的照片。","mne":"re再 + cent新鲜的，年轻的 → recent最近的"},{"word":"recently","ipa":"/ˈriːsntli/","pos":"adv.","def":"最近地","sen":"He recently spent some time on the beach and got a tan.","trans":"他最近在海滩上待了一段时间，晒黑了。","mne":"recent最近 + ly表副词 → recently最近"},{"word":"reception","ipa":"/rɪˈsepʃn/","pos":"n.","def":"前台，接待处；招待会","sen":"The young couple got their room key at the reception of the hotel.","trans":"这对年轻的夫妇在酒店前台拿到了他们房间的钥匙。","mne":"re回，向后 + cept拿，握住 + ion名词后缀 → 接收"},{"word":"receptionist","ipa":"/rɪˈsepʃənɪst/","pos":"n.","def":"接待员","sen":"As soon as I walked in, the hotel receptionist greeted me with a big smile.","trans":"我一走进去，宾馆接待员就满脸笑容地表示欢迎。","mne":"re重复、重新 ＋ cept拿，抓，握住 ＋ ion表名词 ＋ ist从事某种职业的人 → receptionist接待员；传达员"},{"word":"recession","ipa":"/rɪˈseʃ(ə)n/","pos":"n.","def":"（经济）衰退，不景气；后退，撤回","sen":"During a recession, there's less money in the economy to spend on goods or investments.","trans":"在经济衰退期间，用于购买商品或投资的资金减少了。","mne":"re回，向后 + cess行走，前进 + ion名词后缀 → 走回去 → recession撤退；（经济）衰退，不景气"},{"word":"recognise","ipa":"/'rekəɡnaɪz/","pos":"v.","def":"识别出；辨认出","sen":"The little boy recognised his mother in the photo.","trans":"小男孩从照片上认出了他的妈妈。","mne":"re再 + co一起 + gnise知道 → recognise认出"},{"word":"recognition","ipa":"/ˌrekəɡˈnɪʃn/","pos":"n.","def":"认识；识别；承认，认可","sen":"There is a growing recognition of this actress in the world.","trans":"世界上有越来越多的人认识到这个女演员。","mne":"re一再，重新 + cogn知道 + ition名词后缀 → 认出，承认，识别"},{"word":"recognize","ipa":"/ˈrekəɡnaɪz/","pos":"v.","def":"认出，辨别；  v.意识到","sen":"The little boy recognized his mother in the photo.","trans":"小男孩认出了照片里的妈妈。","mne":"re再，重新 + cogn知道 + ize使 → 再次知道 → recognize认出来"},{"word":"recommend","ipa":"/ˌrekəˈmend/   ","pos":"v.","def":"推荐，介绍；劝告，建议","sen":"The snack was highly recommended by the actress.","trans":"这名女演员极力推荐这款零食。","mne":"re加强 + commend推荐 → recommend推荐"},{"word":"recommendation","ipa":"/ˌrekəmenˈdeɪʃn/","pos":"n.","def":"推荐；建议","sen":"Based on your preference, my recommendation is this historical fiction book.","trans":"根据你的喜好，我推荐你这本历史小说。","mne":"recommend推荐 + ation表名词 → recommendation推荐"},{"word":"record","ipa":"/riˈkɔrd/, /ˈrekərd/ ","pos":"n.","def":"记录；唱片（读作/ˈrekərd/）；  v.记录（读作/rɪˈkɔrd/）；录制","sen":"He holds the NBA record for the highest score of 100 points in a single game.","trans":"张伯伦保持着NBA单场最高一百分的得分记录。","mne":"re再 + cord心脏 → 一再放在心上 → record记录"},{"word":"recorder","ipa":"/rɪˈkɔːrdər/","pos":"n.","def":"录音机；记录员","sen":"The old man is making a voice memo with a recorder.","trans":"老人正在用录音机做语音备忘录。","mne":"record记录，录音 + er表示人或物 → recorder记录者；录音机"},{"word":"recover","ipa":"/rɪˈkʌvər/","pos":"v.","def":"痊愈，恢复健康；恢复；收回；换回；重新获得；重新找到","sen":"He has recovered well from his foot injury.","trans":"他的脚伤已经痊愈了。","mne":"re重新 + cover盖住 → recover重新获得"},{"word":"recovery","ipa":"/rɪˈkʌvəri/","pos":"n.","def":"痊愈；恢复，复苏","sen":"She made a quick recovery from her back injury.","trans":"她的背上的伤很快就痊愈了。","mne":"recover痊愈 ＋ y名词后缀 → recovery恢复，痊愈"},{"word":"recruit","ipa":"/rɪˈkruːt/","pos":"v.","def":"招募（新兵），招收（新成员）；  n.新兵，新成员","sen":"Student clubs recruit new members every year.","trans":"学生社团每年都会招收新成员。","mne":"re再 + cru成长 + it名词后缀 → recruit新兵"},{"word":"recycle","ipa":"/ˌriːˈsaɪkl/","pos":"v.","def":"回收利用","sen":"We should recycle trash by putting it into different bins.","trans":"我们应当通过把垃圾扔进分类垃圾桶中来将其回收再利用。","mne":"re一再，重新 + cycle圆，环 → recycle再循环；回收"},{"word":"red","ipa":"/red/  ","pos":"adj.","def":"红色的；脸红的","sen":"I like red apples better than green ones.","trans":"与青苹果相比，我更喜欢红苹果。","mne":""},{"word":"reduce","ipa":"/rɪˈduːs/","pos":"v.","def":"减少，减小，降低","sen":"The price of this phone is reduced to 998 yuan in the sale.","trans":"这款手机的价格在促销中降至998元。","mne":"re向后 + duc引导 → 向后引导 → reduce减少；缩小；降低"},{"word":"reduction","ipa":"/rɪˈdʌkʃn/","pos":"n.","def":"下降，减少","sen":"Due to a downturn in business, he had to consider a reduction in staff numbers.","trans":"由于生意不景气，他不得不考虑裁员。","mne":"reduc=reduce减少 + tion名词后缀 → reduction减少，缩减"},{"word":"refer","ipa":"/rɪˈfɝːr/","pos":"v.","def":"参考；把……描述为；谈及，提到","sen":"When cooking a new recipe, I always refer to the cookbook.","trans":"在烹饪新菜时，我总要查阅烹饪书。","mne":"re再次 + fer带来，拿来 → 再次带来 → refer提到；指点"},{"word":"referee","ipa":"/ˌrefəˈriː/","pos":"n.","def":"主裁判；推荐人，介绍人；裁判员，仲裁者","sen":"Our team disagreed with the referee's offside call.","trans":"我们的队伍不同意主裁判的越位判罚。","mne":""},{"word":"reference","ipa":"/ˈrefrəns/","pos":"n.","def":"参考；提及；推荐信","sen":"The student working on his paper is taking references from books.","trans":"这个写论文的学生正在翻书作为参考。","mne":"re再次 + fer带来，拿来 + ence名词后缀 → 再次拿来用的 → reference参考；引证"},{"word":"refine","ipa":"/rɪˈfaɪn/","pos":"v.","def":"改进，改善；精炼","sen":"She refines the design of the car to make it travel faster.","trans":"她改进了这辆车的设计，使它行驶得更快。","mne":"re表强调 + fine使变好 → refine改进"},{"word":"reflect","ipa":"/rɪˈflekt/","pos":"v.","def":"倒映；反映；仔细思考；反思，反省","sen":"The mountains are reflected in the water.","trans":"群山倒映在水中。","mne":"re回，向后 + flect弯曲 → 反弯曲 → reflect反射"},{"word":"reflection","ipa":"/rɪˈflekʃən/ ","pos":"n.","def":"反省，沉思；反映；反射","sen":"After long reflection, he still does not know what to do.","trans":"长时间沉思后，他仍然不知道做什么。","mne":"re反 + flect弯曲 + ion名词后缀 → reflection反射；思考"},{"word":"reform","ipa":"/rɪˈfɔːrm/","pos":"n.","def":"改革；  v.改革；改造","sen":"The first emperor of Qin unified currency as part of his reforms.","trans":"秦始皇在其改革中统一了货币。","mne":"re再次 + form形状 → 再形成 → reform改造"},{"word":"refresh","ipa":"/rɪˈfreʃ/","pos":"v.","def":"使恢复精神；刷新；使清新","sen":"The long sleep had refreshed her.","trans":"一场酣睡使她又精力充沛。","mne":"re重新，再 + fresh新鲜 → refresh恢复精神，提神"},{"word":"refreshment","ipa":"/rɪˈfreʃmənt/","pos":"n.","def":"茶点；（会议或旅行期间提供的）饮料，点心","sen":"Feel free to enjoy the refreshments on the table that we prepared for you.","trans":"请尽情享用桌上我们为您准备的茶点。","mne":"re再 ＋ fresh清新的 ＋ ment表物 → refreshment茶点"},{"word":"refrigerator","ipa":"/rɪˈfrɪdʒəreɪtər/","pos":"n.","def":"冰箱，冷藏库","sen":"Mom put a pot of soup into the refrigerator.","trans":"妈妈把一锅汤放进了冰箱。","mne":"re加强意义 + friger冷的 + (at)or表示物 → 可以重复使食品冷冻的东西→ refrigerator冰箱，冷藏库"},{"word":"refuse","ipa":"/rɪˈfju:z/, /ˈrefju:s/","pos":"v.","def":"拒绝，谢绝；抵制；  n.废料；垃圾","sen":"This boy is refusing to eat vegetables.","trans":"这个男孩子正拒绝吃蔬菜。","mne":"re回 + fuse流，泻 → 向回流 → refuse拒绝"},{"word":"regard","ipa":"/rɪˈɡɑːrd/","pos":"n.","def":"尊敬；问候；  v.看待；认为；注视","sen":"I have a very high regard for this teacher.","trans":"我很尊敬这位老师。","mne":"re表强调 + gard看，注意 → regard关注"},{"word":"regarding","ipa":"/rɪˈɡɑːrdɪŋ/","pos":"prep.","def":"关于","sen":"His speech would address important issues regarding environmental pollution.","trans":"他的演讲将涉及关于环境污染的重要问题。","mne":""},{"word":"regardless","ipa":"/rɪˈɡɑːrdləs/","pos":"adv.","def":"不顾；  adj.不顾的，不管的","sen":"She goes running regardless of the cold weather.","trans":"不论天气有多冷，她都去跑步。","mne":"regard注意 + less表形容词，无……的 → regardless不注意的"},{"word":"region","ipa":"/ˈriːdʒən/","pos":"n.","def":"地区，区域，地带","sen":"Milk is produced in these regions.","trans":"这些地区生产牛奶。","mne":"reg统治 + ion名词后缀 → 统治区域 → 辖区 → region地区"},{"word":"regional","ipa":"/ˈriːdʒənl/","pos":"adj.","def":"地区性的","sen":"The resort is surrounded by extensive national and regional parklands.","trans":"那个度假胜地被广阔的国家和地区绿地所环绕。","mne":""},{"word":"register","ipa":"/ˈredʒɪstər/ ","pos":"v.","def":"注册；（仪表等）显示；  n.登记表，注册表","sen":"The athletes are registering for a half-marathon around the park.","trans":"运动员们正在登记，报名参加环绕公园的半程马拉松。","mne":"re回 + gist携带 + er → register注册"},{"word":"registration","ipa":"/ˌredʒɪˈstreɪʃn/","pos":"n.","def":"登记，注册，挂号","sen":"Registration is free and easy! Click here to sign up!","trans":"注册免费又轻松！点击这里开始注册！","mne":"re再次 ＋ gistr=gister带来，产生 ＋ ation表过程 → registration记录，注册"},{"word":"regret","ipa":"/rɪˈɡret/","pos":"n.","def":"遗憾；懊悔；  v.对……感到后悔，对...感到遗憾；惋惜","sen":"With deep regret, he realized that he had made the wrong choice.","trans":"他带着深深的遗憾意识到自己做出了错误的选择。","mne":"re表强调 + gret哭泣，流泪 → regret后悔"},{"word":"regular","ipa":"/ˈreɡjələr/","pos":"adj.","def":"定期的，有规律的；通常的，平常的；  n.常客","sen":"We have a regular meeting on every Monday morning.","trans":"我们每个星期一早晨都有例会。","mne":"reg国王 + ular……的 → 国王统治的 → regular规则的"},{"word":"regularly","ipa":"/ˈreɡjələrli/","pos":"adv.","def":"经常，定期地；有规律地；正常地","sen":"We meet regularly to discuss the progress of the project.","trans":"我们定期会面，讨论工程的进展情况。","mne":"regular通常的 + ly……地 → regularly有规律地"},{"word":"regulate","ipa":"/ˈreɡjuleɪt/","pos":"v.","def":"管理，控制；调节","sen":"This guy's duty is to regulate the traffic.","trans":"这个人的职责是管理交通。","mne":"regul规则 ＋ ate表动词 → regulate管理，控制，调整"},{"word":"regulation","ipa":"/regjəˈleɪʃən/","pos":"n.","def":"【财】规则，法规；【法】条例；管理","sen":"Financial regulation ensures the stability of the market.","trans":"金融监管确保市场的稳定。","mne":"regul规则、统治 + ation表名词 → 有规则的 → regulation规则，规章"},{"word":"regulatory","ipa":"/ˈreɡjələtɔːri/","pos":"adj.","def":"管理的，监管的","sen":"It's important to have a regulatory framework for traffic safety.","trans":"建立一个交通安全管理框架很重要。","mne":"regulat=regulate规则，统治 + ory...的 → adj.管理的；控制的；调整的"},{"word":"reinforce","ipa":"/ˌriːɪnˈfɔːrs/","pos":"v.","def":"加强；增援；加固","sen":"We reinforced the structure of the building with steel rods.","trans":"我们用钢筋加固了这栋建筑的结构。","mne":"re再次 + in加强 + force强大，力量 → 再次增加力量 → reinforce加强，巩固"},{"word":"reject","ipa":"/rɪˈdʒekt/","pos":"v.","def":"拒绝，排斥；抵制；驳回；  n.次品","sen":"The girl rejected an incoming call from an unknown number.","trans":"这个女孩拒绝了一个未知号码打来的电话。","mne":"re回 + ject投掷，扔 → 扔回来 → reject拒绝"},{"word":"relate","ipa":"/rɪˈleɪt/","pos":"v.","def":"相关，有联系；讲述；涉及，关于；（对别人的处境、问题等）认同，理解","sen":"The doctor said my lung problems relate to my smoking habit.","trans":"医生说我肺部的问题和我吸烟的习惯有关。","mne":"re回 + late拉 → 拉回来 → relate叙述，使联系"},{"word":"related","ipa":"/rɪˈleɪtɪd/","pos":"adj.","def":"有关的，相关的","sen":"Going bald is related to many factors, one of which is lack of sleep.","trans":"脱发与多种因素有关，比如缺乏睡眠。","mne":""},{"word":"relation","ipa":"/rɪˈleɪʃn/","pos":"n.","def":"关系，联系；家属，亲属","sen":"They have built a business relation; they're partners from now on.","trans":"他们建立了商业关系；从现在开始，他们就是合作伙伴了。","mne":"relat=relate关联 + ion名词后缀 → relation关系；联系；家属"},{"word":"relationship","ipa":"/rɪˈleɪʃnʃɪp/","pos":"n.","def":"关系","sen":"These five people have different relationships with each other.","trans":"这五个人之间有不同的关系。","mne":"relation关系 + ship表名词 →（亲属）关系"},{"word":"relative","ipa":"/ˈrelətɪv/","pos":"n.","def":"亲戚，家人，亲属；  adj.相对的；相比较而言的","sen":"The family tree shows all my relatives.","trans":"这张家谱展示了我所有的亲戚。","mne":"relat=relate联系 + ive名词后缀，表人 → 亲戚"},{"word":"relax","ipa":"/rɪˈlæks/","pos":"v.","def":"放松","sen":"Taking a bath is a good way to relax.","trans":"泡澡是一种很好的放松方式。","mne":"re重新 + lax松 → 重新松开 → relax放松，宽心"},{"word":"release","ipa":"/rɪˈliːs/","pos":"v.","def":"释放；发布，发行；  n.释放；发布","sen":"The prisoner was released after his sentence was complete.","trans":"这个囚犯服完刑后被释放了。","mne":"re向后 + lease松开 → 释放，发布"},{"word":"relevant","ipa":"/ˈreləvənt/","pos":"adj.","def":"相关的；有意义的","sen":"The suggestion given was relevant to our problem.","trans":"给出的这个建议与解决我们的问题相关。","mne":"re表强调 + lev举起，减轻 + ant表形容词 → 能减轻的，起作用的 → relevant有关的；适宜的"},{"word":"reliable","ipa":"/rɪˈlaɪəbl/","pos":"adj.","def":"可靠的，可信赖的","sen":"My mobile phone is very reliable!","trans":"我的手机相当靠得住！","mne":"reli=rely依靠 + able表形容词，…的 → reliable可靠的"},{"word":"relief","ipa":"/rɪˈliːf/","pos":"n.","def":"安慰；缓解；减轻；救济，援助；（不快过后的）宽慰，轻松","sen":"To the relief of the patient, the doctor told him everything was fine.","trans":"令这位病人感到安慰的是，医生告诉他一切都正常。","mne":"re再 + lief提高，变轻 → relief减轻，轻松"},{"word":"relieve","ipa":"/rɪˈliːv/","pos":"v.","def":"减轻；缓解","sen":"A nice massage will relieve your back pain.","trans":"舒服的按摩可以缓解你背部的疼痛。","mne":"re再 + lieve提高，变轻 → 再轻 → relieve减轻"},{"word":"religion","ipa":"/rɪˈlɪdʒən/","pos":"n.","def":"宗教信仰；虔诚的追求","sen":"His religion taught him to be kind.","trans":"他的宗教信仰教他要善良。","mne":"relig=rely依赖 + ion名词后缀 → 用来依赖的 → religion宗教，宗教信仰"},{"word":"religious","ipa":"/rɪˈlɪdʒəs/","pos":"adj.","def":"虔诚的；宗教的","sen":"He is a religious believer; he goes to church every week.","trans":"他是一名虔诚的教徒，每周都会去教堂做礼拜。","mne":""},{"word":"reluctant","ipa":"/rɪˈlʌktənt/","pos":"adj.","def":"不情愿的；勉强的","sen":"The dog was reluctant to take a bath.","trans":"狗狗不愿意去洗澡。","mne":"re相反 + luct努力 + ant…的 → reluctant不情愿的"},{"word":"rely","ipa":"/rɪˈlaɪ/","pos":"v.","def":"依赖，依靠；信赖","sen":"I often rely on instant food because I am so bad at cooking.","trans":"我经常吃速食，因为我不擅长烹饪。","mne":""},{"word":"remain","ipa":"/rɪˈmeɪn/","pos":"v.","def":"剩余；逗留；  link-v.保持；  n.剩余物（复数）；遗迹；残骸","sen":"Only one puppy remained in the cage as the others were sold.","trans":"笼子里只剩下一只小狗，其他的都售出了。","mne":"re回 + main逗留 → 回来留下 → remain剩余"},{"word":"remains","ipa":"/rɪˈmeɪnz/","pos":"n.","def":"（人或动物的）尸体，遗体；  v.剩余，留下（remain的第三人称单数）","sen":"The scientists found the remains of a dinosaur.","trans":"科学家发现了一只恐龙的遗骸。","mne":"re向后 + mains留下 → remains剩余物"},{"word":"remark","ipa":"/rɪˈmɑːrk/","pos":"n.","def":"评论；谈论；言论；  v.注意；议论；评论","sen":"The man got different remarks.","trans":"这个人得到了不同的评论。","mne":"re再 + mark记号，符号 → 再做记号 → remark评点，评论"},{"word":"remarkable","ipa":"/rɪˈmɑːrkəbl/","pos":"adj.","def":"显著的，非凡的，卓越的；不寻常的","sen":"Alex's performance has been remarkable in recent months.","trans":"亚历克斯这几个月的业绩非常出色。","mne":"re再 + mark记号，符号 + able能...的 → 再做记号 → remarkable值得注意的"},{"word":"remedy","ipa":"/ˈremədi/","pos":"n.","def":"治疗；  v.纠正；治疗","sen":"The doctor is trying to find the best remedy for injured Amumu.","trans":"医生正努力研究阿木木的最佳治疗方案。","mne":"re再 + med救治 → 再次救治 → remedy治疗，补救"},{"word":"remember","ipa":"/rɪˈmembər/","pos":"v.","def":"记得，想起；记住","sen":"I still remember the day he asked me to marry him.","trans":"我还记得他向我求婚那天的情景。","mne":"re再 + member记忆 → 再记得 → remember记得，记住"},{"word":"remind","ipa":"/rɪˈmaɪnd/","pos":"v.","def":"提醒","sen":"The alarm clock reminds me that I have a meeting this afternoon.","trans":"闹钟提醒我今天下午有一个会议。","mne":"re再 + mind思考，神智 → 再次思考 → remind提醒"},{"word":"remote","ipa":"/rɪˈmoʊt/ ","pos":"n.","def":"遥控器；  adj.关系远的；微乎其微的","sen":"You need a remote to turn on the air conditioner.","trans":"你需要遥控器才能打开空调。","mne":"re远离+ mot移动 → 逐渐向远处移动 → remote偏远的"},{"word":"remove","ipa":"/rɪˈmuːv/","pos":"v.","def":"去除；脱去，摘下；免除","sen":"Use the other end of the hammer to remove nails.","trans":"用锤子的另一端拔除钉子。","mne":"re往回 + move移动 → remove移除"},{"word":"render","ipa":"/ˈrendər/","pos":"v.","def":"提供，给予；（以某种方式）表达，表现；翻译","sen":"The kind teacher rendered a lot of financial assistance to her poor students.","trans":"善良的老师为贫困生提供了很多经济援助。","mne":"rend给 + er表动词 → 给 → render使成为，给予"},{"word":"renew","ipa":"/rɪˈnuː/","pos":"v.","def":"更新；重新开始","sen":"My landlord renewed my lease at the end of the year.","trans":"我的房东在年底续签了我的租约。","mne":"re再次 + new使变新，恢复 → renew更新"},{"word":"renovate","ipa":"/ˈrenəveɪt/","pos":"v.","def":"修复，修整","sen":"They are going to renovate the old furniture.","trans":"他们准备将旧家具整修一番。","mne":"re重新 + nov新的 + ate造成 → 重新翻新 → renovate翻新"},{"word":"rent","ipa":"/rent/","pos":"n.","def":"租金；  v.租","sen":"I have to pay rent on my house every month.","trans":"我得每月支付我的房租。","mne":""},{"word":"repair","ipa":"/rɪˈper/","pos":"v.","def":"修理；修补，修缮；  n.修理，修补，修缮","sen":"Two workers are trying to repair that car.","trans":"那两个工人正试着修好那辆车。","mne":"re再 + pair回到最初状态 → 重新恢复正常 → repair修理"},{"word":"reparable","ipa":"/'repərəbəl/","pos":"adj.","def":"可修缮的","sen":"Fortunately, the damage to his car was reparable. ","trans":"幸运的是，他的车受到的损伤是可以修缮的。","mne":"repar=repair修缮 ＋ able形容词后缀，可...的 → reparable可修缮的；可补偿的"},{"word":"repay","ipa":"/rɪˈpeɪ/","pos":"v.","def":"偿还（钱款或债务）；报答","sen":"I repay the loan which I borrowed for my new house in monthly installments.","trans":"我每个月都要还买新房的分期贷款。","mne":"re回 + pay支付，偿还 → repay偿还"},{"word":"repeat","ipa":"/rɪˈpiːt/","pos":"v.","def":"重复；重做","sen":"The song repeats the same line over and over.","trans":"这首歌反反复复重复着同一句。","mne":"re再，重新 + peat追寻，努力 → 重新努力一次 → repeat重复，重做"},{"word":"repeatedly","ipa":"/rɪˈpiːtɪdli/ ","pos":"adv.","def":"重复地；屡次地，再三地","sen":"He repeatedly said no to the other two.","trans":"他重复地对另外两人说“不”。","mne":"repeat重复 + ed + ly副词后缀 → repeatedly屡次地"},{"word":"repetition","ipa":"/ˌrepəˈtɪʃn/","pos":"n.","def":"重复，反复","sen":"The repetition of turning the screws made him very bored.","trans":"反复拧螺丝使他感到非常厌倦。","mne":"re再 + pet追求 + tion表名词 → repetition重复"},{"word":"repetitive","ipa":"/rɪˈpetətɪv/","pos":"adj.","def":"重复的，反复的","sen":"Could you please stop asking repetitive questions?","trans":"你能不能别老问我一样的问题？","mne":"re再次，反复 + pet寻求，力争 + itive形容词后缀→repetitive反复的，重复的"},{"word":"replace","ipa":"/rɪˈpleɪs/","pos":"v.","def":"代替，接替；放回","sen":"Robots are gradually replacing factory workers.","trans":"机器人正在逐渐代替工厂的工人。","mne":"re重新 + place放，地方 → 重新放 → replace代替"},{"word":"replacement","ipa":"/rɪˈpleɪsmənt/","pos":"n.","def":"代替物；更换","sen":"The new bulb is the replacement for the old one.","trans":"这个新灯泡是旧灯泡的替代品。","mne":"replace复职；代替 + ment表名词 → replacement替代"},{"word":"reply","ipa":"/rɪˈplaɪ/","pos":"v.","def":"答复；  n.答复，回答","sen":"He is replying to messages on the phone.","trans":"他正在回复手机上的信息。","mne":"re反 + ply重叠，折叠 → 叠回去 → reply回答"},{"word":"report","ipa":"/rɪˈpɔːrt/","pos":"v.","def":"报告，汇报；报道；  n.【航】报告；报道","sen":"The woman is reporting the progress of the project to her team.","trans":"这个女人正在向团队汇报项目进展。","mne":"re回 + port拿，带 → 把消息、情况等带回来 → report报告，汇报"},{"word":"reporter","ipa":"/rɪˈpɔːrtər/","pos":"n.","def":"记者","sen":"The reporter brought us the latest news.","trans":"这位记者为我们带来了最新的消息。","mne":"re回 + port拿 + er表人 → reporter记者，通讯员"},{"word":"represent","ipa":"/ˌreprɪˈzent/","pos":"v.","def":"象征；代表；表示；描述，展现；阐明；说明","sen":"This hand gesture represents love.","trans":"这个手势象征着爱。","mne":"re加强语气 + pre前面 + sent存在 → represent象征，代表，展现"},{"word":"representation","ipa":"/ˌrɛprɪˈzɛnˈteɪʃən/","pos":"n.","def":"代表；表现，呈现","sen":"All the animal representations have attended this international conference.","trans":"动物代表们都出席了此次国际会议。","mne":"re反对 ＋ pre提前 ＋ sent感觉 ＋ ation名词后缀 → 反对预先提出的东西 → representation抗议；代表（权）"},{"word":"representative","ipa":"/ˌreprɪˈzentətɪv/","pos":"n.","def":"代表；  adj.典型的，有代表性的","sen":"They chose her as their representative to speak for them.","trans":"他们选她作为代表发声。","mne":"represent代表 + ative形容词后缀 → representative代表性的"},{"word":"reproduce","ipa":"/ˌriːprəˈduːs/","pos":"v.","def":"繁殖；复制；复印","sen":"Crocodiles reproduce by laying eggs on land.","trans":"鳄鱼通过在陆地上产卵来繁殖后代。","mne":"re一再，重新 + produce生产 → reproduce再生产，再造"},{"word":"reproduction","ipa":"/ˌriːprəˈdʌkʃn/","pos":"n.","def":"生殖；繁殖；复制","sen":"Reproduction is essential for the continuation of all living species.","trans":"生殖对于所有生物物种的延续至关重要。","mne":"re一再，重新 ＋ product产品 ＋ ion名词后缀 → reproduction再生产"},{"word":"republic","ipa":"/rɪˈpʌblɪk/","pos":"n.","def":"共和国，共和政体","sen":"France is a republic.","trans":"法国是一个共和国。","mne":"re事情，事务 + public公众  → 与公众相关的事务  → republic共和国"},{"word":"reputation","ipa":"/ˌrepjuˈteɪʃn/","pos":"n.","def":"名誉，名声","sen":"He has a good reputation among sportsmen since he always wins.","trans":"因为经常赢得比赛，所以他在运动员当中有很高的声誉。","mne":"re再 + put想起 + ation名词后缀 → 让人再想起 → reputation声誉"},{"word":"request","ipa":"/rɪˈkwest/","pos":"n.","def":"（正式或礼貌的）请求；要求；  v.请求，要求；要求，请求","sen":"His father agreed to his request for a Superman costume.","trans":"他父亲同意了他想要一套超人服装的请求。","mne":"re再 + quest寻求，询问 → 再寻求 → request要求"},{"word":"require","ipa":"/rɪˈkwaɪər/","pos":"v.","def":"要求，规定","sen":"The worker is required by law to wear a helmet to work.","trans":"法律规定工人佩戴安全头盔进行工作。","mne":"re再 + quire寻求，询问 → 再寻求 → require请求"},{"word":"requirement","ipa":"/rɪˈkwaɪərmənt/","pos":"n.","def":"要求；必要条件","sen":"The job has strict requirements for experience.","trans":"这份工作对经验有严格的要求。","mne":"re再，重复 + quir寻求，询问 + e + ment表示行为、行为的过程或结果 → 需要；要求"},{"word":"rescue","ipa":"/ˈreskjuː/","pos":"v.","def":"营救，解救；  n.营救，解救","sen":"The brave puppy successfully rescued the kitten trapped in the gap.","trans":"勇敢的小狗成功救出了被埋在缝隙中的小猫。","mne":""},{"word":"research","ipa":" /rɪˈsɜːtʃ/ /ˈriːsɜːrtʃ/","pos":"n.","def":"研究，调查；探索；  v.研究，调查","sen":"She's conducting some research in order to write her new book.","trans":"为了撰写她的新书，她正在进行一些研究。","mne":"re表强调 + search寻找 → research研究"},{"word":"resemblance","ipa":"/rɪˈzembləns/","pos":"n.","def":"相似","sen":"There is a remarkable resemblance between him and his brother, Pete.","trans":"他和他的弟弟皮特之间有着惊人的相似之处。","mne":"re一再，重新 + sembl相像 + ance名词后缀，表性质 → resemblance相像"},{"word":"resemble","ipa":"/rɪˈzembl/","pos":"v.","def":"类似，相似","sen":"These two men resemble each other, so it's hard to tell them apart.","trans":"这两个男人长得很相似，难以区分谁是谁。","mne":"re表强调 + semble相类似，一样 → resemble类似"},{"word":"resent","ipa":"/rɪˈzent/","pos":"v.","def":"愤恨，憎恶","sen":"After quarreling over and over, the couple resented each other.","trans":"在一次又一次的争吵之后，这对夫妻互相怨恨起来。","mne":"re向后，相反 + sent感觉 → 反感 → resent不满，忿恨"},{"word":"reservation","ipa":"/ˌrezərˈveɪʃn/","pos":"n.","def":"（住处、席位的）预订；保留意见","sen":"The couple had a reservation, so the table was saved for them.","trans":"这对夫妇已经预订过了，所以餐厅为他们保留了桌子。","mne":"reserv保存 + ation名词后缀 → reservation保存；预定"},{"word":"reserve","ipa":"/rɪˈzɜːrv/","pos":"n.","def":"储备；储备金；保护区；  v.保留；预订；储备","sen":"He has an emergency reserve of food stored at home.","trans":"他在家里有一个存放食物的紧急储备库。","mne":"re再 + serve服务，保持 → 再留住 → reserve预定"},{"word":"reside","ipa":"/rɪˈzaɪd/","pos":"v.","def":"居住","sen":"This type of crab resides inside shells.","trans":"这种螃蟹住在贝壳里面。","mne":"re再 + side坐 → 再坐之地 → reside居住"},{"word":"residence","ipa":"/ˈrezɪdəns/","pos":"n.","def":"住宅；居住","sen":"Their residence is equipped with a large swimming pool.","trans":"他们的住宅配有一个很大的游泳池。","mne":"re再 + sid坐 + ence名词后缀 → residence居住；住宅"},{"word":"resident","ipa":"/ˈrezɪdənt/","pos":"n.","def":"居民；  adj.居住的；常驻的","sen":"The residents here like to interact with each other.","trans":"这儿的居民喜欢相互交流。","mne":"resid=reside居住 + ent人 → resident居民"},{"word":"resign","ipa":"/rɪˈzaɪn/","pos":"v.","def":"辞职，放弃","sen":"She was not happy working for this company and finally decided to resign.","trans":"她在这家公司工作得不开心，最终决定辞职。","mne":"re再 + sign签名 → 再次签名 → resign辞职"},{"word":"resist","ipa":"/rɪˈzɪst/","pos":"v.","def":"抵抗，抵制","sen":"The girl on a diet managed to resist the temptation of hamburgers.","trans":"这个正在节食的女孩抵制住了汉堡包的诱惑。","mne":"re向后，相反 + sist站 → 反着站 → resist反抗，抵抗"},{"word":"resistance","ipa":"/rɪˈzɪstəns/","pos":"n.","def":"抵抗；阻力","sen":"The enemy gave up without resistance.","trans":"敌军没有抵抗就投降了。","mne":"re反 + sist站立 + ance名词后缀 → resistance反抗；抵抗力"},{"word":"resistant","ipa":"/rɪˈzɪstənt/","pos":"adj.","def":"有抵抗力的","sen":"This watch is resistant to water.","trans":"这块手表具有防水性能。","mne":"re向后，相反 + sist站 + ant…的 → 站在反方向上 → resistant抵抗的"},{"word":"resolution","ipa":"/ˌrezəˈluːʃn/ ","pos":"n.","def":"决心，决定，坚定；分辨率；决议；解决","sen":"She made a resolution to read all of these English novels in just one week.","trans":"她下定决心要在一周内读完所有这些英文小说。","mne":"re不 + solut松开 + ion名词后缀，构成抽象名词 → 不解决就不松开 → resolution决心；溶解"},{"word":"resolve","ipa":"/rɪˈzɑːlv/","pos":"n.","def":"决心；坚定的信念","sen":"Nothing shakes his resolve of passing the test!","trans":"没有什么能动摇他想通过考试的决心！","mne":"re再 + solve解决 → resolve决心"},{"word":"resort","ipa":"/rɪˈzɔːrt/","pos":"n.","def":"度假胜地；诉诸，凭借，求助；应急措施；可首先（或最后）采取的手段；  v.诉诸，采用","sen":"We will stay on a beach resort for our next holiday.","trans":"下个假期我们将去一个海滨度假胜地。","mne":"re再一次 + sort出去 → resort度假胜地"},{"word":"resource","ipa":"/ˈriːsɔːrs/","pos":"n.","def":"资源；财力；物力；谋略","sen":"We depend on the Earth's resources to survive.","trans":"我们依靠地球提供的资源生存。","mne":""},{"word":"respect","ipa":"/rɪˈspekt/   ","pos":"n.","def":"敬重；  v.敬重，尊敬","sen":"They bow to their customers as a sign of respect.","trans":"他们会对客人鞠躬，以示尊重。","mne":"re再 + spect看 → 再看一眼 → respect尊敬"},{"word":"respectable","ipa":"/rɪˈspektəbl/","pos":"adj.","def":"值得尊敬的；体面的，雅观的","sen":"Being a teacher is regarded as a respectable profession.","trans":"教师是值得尊敬的职业。","mne":"respect 尊敬 + able 可...的 形容词后缀→ respectable 值得尊敬的"},{"word":"respectful","ipa":"/rɪˈspektfl/","pos":"adj.","def":"表示尊敬的","sen":"He behaves in a respectful way.","trans":"他的举止彬彬有礼。","mne":"respect尊敬 + ful……的 → respectful充满敬意的"},{"word":"respective","ipa":"/rɪˈspektɪv/","pos":"adj.","def":"分别的；各自的","sen":"After the party, we went back into our respective rooms.","trans":"派对结束后，我们回到了各自的房间。","mne":"re回 + spect看 + ive形容词后缀 → 回头看自己 → respective各自的"},{"word":"respectively","ipa":"/rɪˈspektɪvli/","pos":"adv.","def":"各自；分别","sen":"The twins, Kate and Kimberley, received a toy car and a doll respectively.","trans":"凯特和金伯莉这对双胞胎姐妹分别收到了玩具车和洋娃娃作为礼物。","mne":"respective回头看（自己）=各自的 + ly……地 → respectively各自地"},{"word":"respond","ipa":"/rɪˈspɑːnd/","pos":"v.","def":"回答，回复；回应；回答","sen":"When the boy gives orders to the man, he always responds with \"Yes, my lord.\"","trans":"当男孩向男人下命令时，男人总是回答：“遵命，我的主人。”","mne":"re回 + spond承诺 → 承诺回去 → 回答 → respond回答；反应"},{"word":"response","ipa":"/rɪˈspɑːns/","pos":"n.","def":"响应；回应；回答，答复","sen":"The students raised their hands in response to the teacher's question.","trans":"同学们举起手来回答老师的提问。","mne":"re回，向后 + sponse承诺 → response回答；答应"},{"word":"responsibility","ipa":"/rɪˌspɑːnsəˈbɪləti/ ","pos":"n.","def":"责任，义务；职责","sen":"We have a responsibility to take care of our parents.","trans":"我们有责任照顾父母。","mne":"re再、重复 ＋ spons承诺 ＋ ibility抽象名词词尾 → responsibility责任，责任心；职责，义务"},{"word":"responsible","ipa":"/rɪˈspɑːnsəbl/","pos":"adj.","def":"负责的，可靠的，有责任的","sen":"The dog was responsible for this mess.","trans":"这只狗要对这片混乱负责。","mne":"respons回应 + ible能...的 → 能回应的 → responsible有责任的"},{"word":"rest","ipa":"/rest/","pos":"v.","def":"休息，放松；依赖，倚靠；  n.休息，休息时间；剩余部分；静止，休止","sen":"He is resting his head on the girl's legs.","trans":"他把头枕在女孩腿上休息。","mne":""},{"word":"restaurant","ipa":"/ˈrestrɑːnt/","pos":"n.","def":"餐厅，餐馆","sen":"It is expensive to eat at this fancy restaurant.","trans":"在这家高档餐厅吃饭很贵。","mne":""},{"word":"restoration","ipa":"/ˌrestəˈreɪʃn/","pos":"n.","def":"恢复；归还；整修，修复","sen":"The restoration of the temple to its former glory will take a long while.","trans":"要使这座寺庙恢复往日的辉煌还需要很长时间。","mne":"restor恢复 + ation表示行为、情况、状态、过程、结果 → restoration恢复"},{"word":"restore","ipa":"/rɪˈstɔːr/","pos":"v.","def":"恢复","sen":"We hope to restore the garden to its former beauty.","trans":"我们希望把花园恢复到它原来的美丽模样。","mne":"re重新 + sto站稳，使坚定 + re → 重新回到状态 → restore恢复"},{"word":"restrain","ipa":"/rɪˈstreɪn/","pos":"v.","def":"抑制（愤怒等），控制","sen":"She tried hard to restrain her anger. ","trans":"她努力克制住自己的怒火。","mne":"re回 + strain拉紧，压 → restrain抑制，限制"},{"word":"restrict","ipa":"/rɪˈstrɪkt/","pos":"v.","def":"限制；约束","sen":"A combination lock can restrict others from prying into their privacy.","trans":"密码锁可以限制别人偷窥自己的隐私。","mne":"re回 + strict拉紧，压 → 拉回来 → 限制"},{"word":"restriction","ipa":"/rɪˈstrɪkʃn/","pos":"n.","def":"限制，约束","sen":"There is a restriction on fishing here.","trans":"这里限制垂钓。","mne":"re回 + strict拉紧，压 + ion表名词 → restriction限制"},{"word":"result","ipa":"/rɪˈzʌlt/","pos":"n.","def":"结果，成效；  v.导致","sen":"An A+ is the best possible result. Good work!","trans":"A+是能得到的最好成绩。真棒！","mne":"re反问 + sult跳 → 反馈回来 → result结果"},{"word":"resultant","ipa":"/rɪˈzʌltənt/","pos":"adj.","def":"作为结果的","sen":"His muscular body is the resultant effect from his tough workout regime.","trans":"他的好身材是严格锻炼的结果。","mne":"result结果 + ant属于……的，具有……的 → resultant作为结果的，因而发生的"},{"word":"resume","ipa":"/ˈrezjumeɪ/, /rɪˈzum/","pos":"n.","def":"简历（读作/ˈrezjumeɪ/）；  v.继续说；继续进行","sen":"The HR team are examining the resumes of the interviewees.","trans":"人力资源团队正在审核应聘者的简历。","mne":"re再次 + sume拿走，取走 → resume继续进行"},{"word":"retail","ipa":"/ˈriːteɪl/","pos":"n.","def":"零售；  v.零售","sen":"The retail trade is booming because of the application of online payment.","trans":"由于线上支付的应用，零售业正在蓬勃发展。","mne":"re在后面 + tail切割，修剪 → 分割出单个 → retail零售"},{"word":"retailer","ipa":"/ˈriːteɪlər/","pos":"n.","def":"零售商","sen":"This retailer sells many kinds of products.","trans":"这个零售商销售各种各样的商品。","mne":"re再 + tail剪，割 + er表示人 → retailer零售商"},{"word":"retain","ipa":"/rɪˈteɪn/","pos":"v.","def":"保持，保留，保存","sen":"Hot water can retain its heat for hours in the vacuum cup.","trans":"热水能在保温杯里保持温度好几个小时。","mne":"re回 + tain握住 → 拿回来 → retain保留"},{"word":"retire","ipa":"/rɪˈtaɪər/","pos":"v.","def":"退休；退役","sen":"My grandfather retired at 60 and raised a bird.","trans":"我爷爷60岁退休，并养了一只鸟。","mne":"re回，向后 + tire拉 → 拉回去撤离 → retire退休"},{"word":"retirement","ipa":"/rɪˈtaɪərmənt/","pos":"n.","def":"退休，退休生活","sen":"He took up gardening as a hobby in his retirement.","trans":"他退休后喜欢上了园艺。","mne":"re回、向后 + tire 疲劳 + ment表示行为、行为的过程或结果 → 退休，引退，退却，撤退"},{"word":"retreat","ipa":"/rɪˈtriːt/","pos":"v.","def":"撤退，撤离；退却，后退；  n.撤退，退却；退隐处，静居处","sen":"He retreated from the battle with a little girl.","trans":"男枪带着小女孩(安妮)从战斗中撤退。","mne":""},{"word":"return","ipa":"/rɪˈtɝːn/","pos":"v.","def":"返回；归还；  n.返回","sen":"Return to where you came from.","trans":"从哪儿来回哪儿去。","mne":"re回，向后 + turn转 → return回来，返回"},{"word":"reveal","ipa":"/rɪˈviːl/","pos":"v.","def":"揭示；透露；显示","sen":"He opened the curtain to reveal a landscape painting.","trans":"他掀开帘布，露出一幅风景画。","mne":"re相反 + veal=veil盖上 → 与掩盖相反 → reveal揭露"},{"word":"revenue","ipa":"/ˈrevənuː/","pos":"n.","def":"税收，（公司或组织的）收益","sen":"The report shows a significant rise in revenue this year.","trans":"报告显示，今年的税收大幅上升。","mne":"re回 + venue来 → 回来的东西 → revenue收入"},{"word":"reverse","ipa":"/riˈvərs/","pos":"v.","def":"颠倒，反转（顺序）；倒（车）；撤销，废除；  n.逆向，逆转；  adj.相反的；反面的","sen":"Now that you have a job and I don't, our situations are reversed.","trans":"你找到了工作，我倒没有工作了，我们的情况正好颠倒过来。","mne":"re向后，相反 + verse转 → reverse反转，颠倒"},{"word":"reversely","ipa":"/rɪ'vɜːslɪ/","pos":"adv.","def":"相对地","sen":"The temperature rose during the day, but reversely, it dropped sharply after sunset.","trans":"白天气温上升，但相反地，日落后气温急剧下降。","mne":""},{"word":"review","ipa":"/rɪˈvjuː/","pos":"v.","def":"复习；回顾；评论；检查；  n.评论；复习；检讨；检查","sen":"The girl is reviewing her homework for tomorrow's important test.","trans":"那个女孩在为明天的重要考试复习。","mne":"re再、重复 + view看 → review再检查，复习"},{"word":"revise","ipa":"/rɪˈvaɪz/","pos":"v.","def":"修改；温习（功课）；修订","sen":"She is revising her paper according to the advice given by her teacher.","trans":"她正在根据老师给的意见修改论文。","mne":"re一再，重新 + vise看 → 再看一遍 → revise修正"},{"word":"revision","ipa":"/rɪˈvɪʒn/","pos":"n.","def":"修改；复习","sen":"He made a lot of revisions in her novel.","trans":"他对她的小说做了很多的修改。","mne":"re再 + vis看 + ion表名词 → 校订本"},{"word":"revival","ipa":"/rɪˈvaɪvl/","pos":"n.","def":"复苏，复兴","sen":"The tourist hotspot enjoyed a dramatic revival once the epidemic had faded away.","trans":"传染病消失后，这个旅游胜地又恢复了兴旺景象。","mne":"re一再，重新 + viv生命 + al名词后缀，…的 → 复活"},{"word":"revive","ipa":"/rɪˈvaɪv/","pos":"v.","def":"使复苏，恢复","sen":"A single green sapling revived itself in the rotten tree stump.","trans":"一棵绿色小树苗在腐烂的树桩里重新长了出来。","mne":"re再，重新 + vive生命 → revive恢复；（使）复苏"},{"word":"revolt","ipa":"/rɪˈvoʊlt/","pos":"v.","def":"反抗，叛乱；（使）厌恶；  n.厌恶","sen":"Will robots revolt against humans in the future?","trans":"机器人会在未来反抗人类吗？","mne":"re向后，相反 + volt转 → 态度反转 → revolt反抗，造反"},{"word":"revolution","ipa":"/ˌrevəˈluːʃn/","pos":"n.","def":"革命，改革","sen":"A revolution in science and technology has changed the way that we communicate.","trans":"科技革命已经改变了我们的通信方式。","mne":"re重新 + volut旋转，卷 + ion名词后缀 → 重新旋转 → 革命，变革"},{"word":"revolutionary","ipa":"/ˌrevəˈluːʃəneri/","pos":"adj.","def":"革命性的；革命的","sen":"In the past 100 years China's transport has undergone a revolutionary change.","trans":"近百年来，中国的交通方式经历了革命性的变化。","mne":"revolution革命 + ary表形容词 → revolutionary革命性的"},{"word":"revolve","ipa":"/rɪˈvɑːlv/","pos":"v.","def":"（使）旋转；转动；围绕，环绕","sen":"This merry-go-round is revolving at a high speed.","trans":"旋转木马正在以很快的速度转动着。","mne":"re再 + volv旋转，卷 + e → 再转一次 → 旋转；循环"},{"word":"reward","ipa":"/rɪˈwɔːrd/","pos":"n.","def":"奖品，奖励；回报，报答；  v.报答，回报","sen":"I got a reward for my hard work.","trans":"我因努力工作获得了报酬。","mne":""},{"word":"rhythm","ipa":"/ˈrɪðəm/","pos":"n.","def":"节奏；韵律","sen":"Only with a good sense of rhythm can he play this game well.","trans":"想玩好这个游戏，他必须要有很强的节奏感。","mne":""},{"word":"ribbon","ipa":"/ˈrɪbən/","pos":"n.","def":"缎带，丝带；带状物","sen":"This is a red roll of ribbon.","trans":"这是一卷红丝带。","mne":""},{"word":"rice","ipa":"/raɪs/","pos":"n.","def":"米饭","sen":"I'll cook rice for dinner.","trans":"晚餐我会煮米饭。","mne":""},{"word":"rich","ipa":"/rɪtʃ/","pos":"adj.","def":"富有的；肥沃的；油腻的","sen":"The rich couple decided to sail around the world after they retired.","trans":"这一对富裕的夫妻决定在退休后去环游世界。","mne":""},{"word":"rid","ipa":"/rɪd/","pos":"v.","def":"使去掉；使摆脱；  adj.得到解脱的","sen":"The stain can be easily rid of.","trans":"这个污渍很容易去除。","mne":""},{"word":"ride","ipa":"/raɪd/","pos":"v.","def":"骑（车），乘；  n.骑，驾驶；乘坐（游乐设施）","sen":"When I ride my bike, I always wear a helmet for safety.","trans":"当我骑自行车时，为了安全我总会戴安全帽。","mne":""},{"word":"ridiculous","ipa":"/rɪˈdɪkjələs/","pos":"adj.","def":"可笑的，荒谬的","sen":"He looked ridiculous in that oversized suit.","trans":"他穿着那套大得不合身的西装，看起来很滑稽。","mne":"ridi取笑 + cul + ous表形容词 → ridiculous可笑的"},{"word":"right","ipa":"/raɪt/","pos":"adj.","def":"右边的；正确的；  n.权利；右边；  adv.正确地；直接地，径直地","sen":"This green traffic light tells us it is OK to turn right.","trans":"绿灯意味着我们可以右转了。","mne":""},{"word":"rigid","ipa":"/ˈrɪdʒɪd/","pos":"adj.","def":"坚硬的；严格的","sen":"My hard hat is so rigid that even a Nokia phone can't crack it!","trans":"我的安全帽很坚硬，即使诺基亚手机也砸不碎！","mne":""},{"word":"rigorous","ipa":"/ˈrɪɡərəs/","pos":"adj.","def":"严格的","sen":"The rigorous training prepared students well for the challenges ahead.","trans":"严格的训练让学生们为未来的挑战做好了充分准备。","mne":"rigor严格 + ous……的 → rigorous严厉的"},{"word":"ring","ipa":"/rɪŋ/","pos":"n.","def":"环（状物），小圈；戒指；  v.打电话","sen":"He is about to throw the ring.","trans":"他准备把这个环给丢出去了。","mne":""},{"word":"ripe","ipa":"/raɪp/","pos":"adj.","def":"熟的，成熟的","sen":"When bananas become ripe, they turn yellow.","trans":"香蕉成熟的时候，颜色就会变黄。","mne":""},{"word":"rise","ipa":"/raɪz/","pos":"v.","def":"升起，上升，上涨；  n.增长","sen":"The bright sun rises on the horizon.","trans":"明亮的太阳从地平线上升起。","mne":""},{"word":"risk","ipa":"/rɪsk/","pos":"v.","def":"冒……的危险；  n.风险","sen":"The fireman risks his life by rushing into the fire.","trans":"消防员冒着生命危险冲进火场。","mne":""},{"word":"rival","ipa":"/ˈraɪvl/","pos":"n.","def":"竞争对手","sen":"The two lions are rivals and will fight each other to become the new leader.","trans":"这两只狮子是竞争对手，它们为了成为新的头领即将展开战斗。","mne":"riv河 + al表名词 → 由“河”引申为“流动，跑 → 一起跑 → rival竞争者"},{"word":"river","ipa":"/ˈrɪvər/","pos":"n.","def":"河，江","sen":"This river brings fresh water from the mountains.","trans":"河流从山里带来了淡水。","mne":""},{"word":"road","ipa":"/roʊd/","pos":"n.","def":"道路；公路","sen":"We will be driving on this road for a while.","trans":"我们要在这条路上开一会儿。","mne":""},{"word":"roar","ipa":"/rɔːr/","pos":"n.","def":"吼叫声，轰鸣声；  v.咆哮；吼叫","sen":"The tiger let out a mighty roar on the cliff.","trans":"这只老虎在山崖上发出威猛的怒吼。","mne":""},{"word":"roast","ipa":"/roʊst/","pos":"v.","def":"烤（通常指烤肉、大块蔬菜）；  n.烤肉；  adj.烤的，烘的","sen":"Roast the chicken with herbs for a flavorful dinner.","trans":"用香草烤鸡，晚餐更美味。","mne":""},{"word":"rob","ipa":"/rɑːb/","pos":"v.","def":"抢劫，盗取，抢夺","sen":"The man has robbed the bank.","trans":"那个人抢劫了银行。","mne":""},{"word":"robber","ipa":"/ˈrɑːbər/","pos":"n.","def":"强盗，盗贼","sen":"The robber tried to take the man's bag.","trans":"强盗想要抢这个人的包。","mne":""},{"word":"robbery","ipa":"/ˈrɑːbəri/","pos":"n.","def":"抢掠，抢夺；盗窃","sen":"I saw a bank robbery.","trans":"我目击了一场银行抢劫案。","mne":"robb=rob抢 + ery行为，情况 → robbery抢劫"},{"word":"robot","ipa":"/ˈroʊbɑːt/","pos":"n.","def":"机器人","sen":"In the future, we all will have robot assistants.","trans":"未来，我们都会有机器人助手。","mne":""},{"word":"rock","ipa":"/rɑːk/","pos":"n.","def":"岩石，石头；  v.摇晃","sen":"There were many large rocks on the seashore.","trans":"海边有许多大块的岩石。","mne":""},{"word":"rocket","ipa":"/ˈrɑːkɪt/","pos":"n.","def":"火箭，火箭弹；  v.猛涨","sen":"The red rocket is flying over the clouds.","trans":"红色的火箭在云层上飞行。","mne":""},{"word":"rod","ipa":"/rɑːd/","pos":"n.","def":"（船）杆，棒","sen":"I hope this fishing rod is strong enough to catch a big fish.","trans":"但愿这鱼竿足够结实，可以钓起来大鱼。","mne":""},{"word":"role","ipa":"/roʊl/","pos":"n.","def":"角色；作用；职责，职能","sen":"The actress played challenging roles in many different TV series.","trans":"这名女演员在不同的电视剧里尝试了具有挑战性的角色。","mne":""},{"word":"roll","ipa":"/roʊl/","pos":"v.","def":"滚动，转动；  n.翻滚","sen":"The kid is rolling the snowball to make it bigger.","trans":"小孩正在滚雪球，使它变得更大。","mne":""},{"word":"roller","ipa":"/ˈroʊlər/","pos":"n.","def":"滚柱，滚筒，滚轴","sen":"A roller can be used to paint a wall faster than a paintbrush.","trans":"用滚筒刷墙比用漆刷刷墙快。","mne":"roll滚 + er表示物 → roller滚柱，滚筒，滚轴"},{"word":"romantic","ipa":"/roʊˈmæntɪk/","pos":"adj.","def":"浪漫的","sen":"On Valentine's Day, couples often go for a romantic dinner.","trans":"情人节这天，情侣们通常会出去吃一顿浪漫的晚餐。","mne":"roman浪漫 + tic……的 → romantic浪漫的"},{"word":"roof","ipa":"/ruːf/","pos":"n.","def":"屋顶；顶部；  v.覆盖，给……盖屋顶","sen":"There's a window and a chimney on this roof.","trans":"屋顶上有一扇窗户和一个烟囱。","mne":""},{"word":"room","ipa":"/ruːm/","pos":"n.","def":"房间；空间","sen":"There are four rooms inside this apartment.","trans":"这座公寓里有四个房间。","mne":""},{"word":"root","ipa":"/ruːt/","pos":"v.","def":"生根；  n.根，根茎，根部；根源","sen":"The tree deeply roots in the soil.","trans":"这棵树深深地扎根于土壤之中。","mne":""},{"word":"rope","ipa":"/roʊp/","pos":"n.","def":"绳子，绳索；粗绳","sen":"How thick a rope do we need?","trans":"我们需要多粗的绳子？","mne":""},{"word":"rose","ipa":"/roʊz/","pos":"n.","def":"玫瑰，蔷薇；  v.rise的过去式","sen":"The rose is deep red.","trans":"这种玫瑰是深红色的。","mne":""},{"word":"rotate","ipa":"/ˈroʊteɪt/","pos":"v.","def":"以……轴转动，使旋转；轮流，轮换","sen":"She can rotate the stick very well.","trans":"小樱可以很熟练地转动魔法棒。","mne":"rot轮子，转 + ate使 → 旋转"},{"word":"rotation","ipa":"/roʊˈteɪʃn/","pos":"n.","def":"【数】旋转；旋转；循环，轮流","sen":"When the spinner finishes a rotation, it stops in a color zone.","trans":"当转盘完成一次旋转后，它会停在一个颜色区域。","mne":"rot轮，转 + ation名词后缀 → 旋转；轮流，循环"},{"word":"rough","ipa":"/rʌf/","pos":"adj.","def":"粗糙的；大致的，粗略的","sen":"The hands of the farmer are rough.","trans":"这个农民的手很粗糙。","mne":""},{"word":"round","ipa":"/raʊnd/","pos":"adj.","def":"圆的，球形的；  prep.在…周围，包围；  n.圆，圆形物；  v.（使）成圆形","sen":"The shape of the earth is round.","trans":"地球是圆的。","mne":""},{"word":"rouse","ipa":"/raʊz/","pos":"v.","def":"唤醒，唤起","sen":"My husband likes to rouse me with a gentle touch in the morning.","trans":"每天早上，我丈夫喜欢轻轻地推醒我。","mne":""},{"word":"route","ipa":"/ruːt/, /raʊt/","pos":"n.","def":"路线；途径","sen":"This blue line is the quickest route to get there.","trans":"这条蓝色的线是到那儿最快的路线。","mne":""},{"word":"routine","ipa":"/ruːˈtiːn/","pos":"n.","def":"常规；  adj.例行的，惯例的","sen":"Going to school and reading books are parts of her daily routine.","trans":"上学和看书是她日常生活的一部分。","mne":"rout(e)路线 + ine形容词后缀 → 路线设置好的 → routine常规的，例行的"},{"word":"row","ipa":"/roʊ/","pos":"n.","def":"排；  v.划船","sen":"Please follow me, our bus is parked in the third row.","trans":"请跟我来，我们的巴士停在第三排。","mne":""},{"word":"royal","ipa":"/ˈrɔɪəl/","pos":"adj.","def":"王室的，皇家的；盛大的，高贵的","sen":"The king wears his royal clothes.","trans":"国王穿着他的御用衣服。","mne":""},{"word":"rub","ipa":"/rʌb/","pos":"v.","def":"揉","sen":"I like it when she rubs my forehead, since I have bad headaches.","trans":"我喜欢她揉我的前额，因为我有严重的头痛。","mne":""},{"word":"rubber","ipa":"/ˈrʌbər/","pos":"n.","def":"橡皮；橡胶制品，胶鞋；橡皮擦","sen":"Wear rubber gloves to do dirty work.","trans":"戴上橡胶手套来做脏活。","mne":"rub擦 + b + er名词后缀：物 → rubber橡皮"},{"word":"rubbish","ipa":"/ˈrʌbɪʃ/","pos":"n.","def":"垃圾，废物","sen":"Please put your rubbish in the bag.","trans":"请把你的垃圾放在这个袋子里。","mne":""},{"word":"rude","ipa":"/ruːd/","pos":"adj.","def":"粗鲁的，无礼的","sen":"It's very rude to jump the queue.","trans":"插队是很不礼貌的。","mne":""},{"word":"ruin","ipa":"/ˈruːɪn/","pos":"v.","def":"毁灭，毁坏；  n.废墟","sen":"Our village was totally ruined by the UFO lasers.","trans":"不明飞行物用射线完全摧毁了我们的村庄。","mne":""},{"word":"rule","ipa":"/ruːl/","pos":"n.","def":"【数】规则；统治，管辖；  v.统治，控制；支配；裁决","sen":"In mathematics, the rule of addition is important to learn.","trans":"在数学里，学习加法规则是非常重要的。","mne":""},{"word":"ruler","ipa":"/ˈruːlər/","pos":"n.","def":"尺子；统治者，管理者","sen":"This is a ruler that can measure in both inches and centimeters.","trans":"这把尺子既有英寸刻度，又有厘米刻度。","mne":"rule统治、管理 + er表人 → ruler统治者、直尺"},{"word":"rumor","ipa":"/ˈruːmər/","pos":"n.","def":"谣言","sen":"Stop spreading rumors!","trans":"别再散播谣言了！","mne":""},{"word":"rumour","ipa":"/ˈruːmər/","pos":"n.","def":"【财】谣言；  v.谣传，传闻","sen":"The grapevine is notoriously inaccurate and can carry morale-damaging rumours.","trans":"小道消息是出了名的不准确，可能会传播损害士气的谣言。","mne":""},{"word":"run","ipa":"/rʌn/","pos":"v.","def":"跑步，奔跑；  v.经营，管理","sen":"She ran across the street as fast as she could.","trans":"吴妍珠拼尽全力向马路对面的（姜哲）跑去。","mne":""},{"word":"rural","ipa":"/ˈrʊrəl/","pos":"adj.","def":"乡村的，田园的","sen":"The rural area is beautiful and peaceful.","trans":"乡村的环境是美好而宁静的。","mne":"rur农村 + al表形容词 → rural乡村的"},{"word":"rush","ipa":"/rʌʃ/","pos":"v.","def":"冲，奔；匆忙做；  n.冲，急速行进","sen":"I'll have to rush to the canteen; otherwise there'll be nothing left.","trans":"我得冲向食堂，不然什么吃的都没有了。","mne":""},{"word":"rust","ipa":"/rʌst/","pos":"v.","def":"生锈；氧化；  n.锈","sen":"This old car has already rusted.","trans":"这辆旧车已经生锈了。","mne":""},{"word":"sack","ipa":"/sæk/","pos":"n.","def":"一袋；开除，解雇；  v.解雇；掠夺","sen":"The old woman is carrying a sack of rubbish.","trans":"老妇人正拿着一袋垃圾。","mne":""},{"word":"sacrifice","ipa":"/ˈsækrɪfaɪs/","pos":"v.","def":"牺牲；奉献；献祭；  n.牺牲；祭品","sen":"The kiwi sacrificed his life to protect his family and friends.","trans":"为了保护家人和朋友，这只猕猴桃牺牲了自己的生命。","mne":"sacri神圣 + fice做，制作 → 为神做的东西 → sacrifice祭品；牺牲"},{"word":"sad","ipa":"/sæd/","pos":"adj.","def":"难过的，悲伤的，忧愁的","sen":"The boy is sad because he feels misunderstood.","trans":"男孩很难过，觉得自己不被理解。","mne":""},{"word":"sadness","ipa":"/ˈsædnəs/","pos":"n.","def":"悲伤，悲哀","sen":"The boy looked at the ice cream on the ground with great sadness.","trans":"这个男孩看着地上的冰激凌，非常伤心。","mne":"sad悲伤 + ness名词后缀 →  sadness悲哀"},{"word":"safe","ipa":"/seɪf/","pos":"adj.","def":"安全的","sen":"The gold will be very safe here.","trans":"把金条放这里会很安全的。","mne":""},{"word":"safeguard","ipa":"/ˈseɪfɡɑːrd/","pos":"v.","def":"保护，维护","sen":"The job of the guards is to safeguard the money.","trans":"这些警卫的职责是保护财产安全。","mne":"safe安全的 + guard保护 → 保护，维护"},{"word":"safety","ipa":"/ˈseɪfti/","pos":"n.","def":"安全，平安","sen":"Safety is important when cycling. Remember to wear a helmet!","trans":"骑车的时候安全很重要，记得戴上头盔！","mne":"safe安全 + ty表名词 → 安全"},{"word":"sail","ipa":"/seɪl/","pos":"v.","def":"航行；  n.帆","sen":"The big boat sails off into the sunset.","trans":"这艘大船朝着落日航行。","mne":""},{"word":"sailor","ipa":"/ˈseɪlər/","pos":"n.","def":"水手，海员","sen":"The sailor has been out to sea for several months.","trans":"水手已经出海几个月了。","mne":"sail航行 + or名词后缀，表示人 → sailor水手，海员"},{"word":"sake","ipa":"/seɪk/; /ˈsɑːki/","pos":"n.","def":"理由","sen":"He wears the helmet for safety's sake.","trans":"出于安全考虑，他戴着头盔。","mne":""},{"word":"salad","ipa":"/ˈsæləd/","pos":"n.","def":"（生吃的）蔬菜色拉，沙拉","sen":"I'm on a diet, so I'll just have a salad. Thanks!","trans":"我正在减肥，所以我只吃沙拉，谢谢！","mne":"sal盐 + ad名词后缀 → 用盐腌渍的食品 → salad色拉，沙拉"},{"word":"salary","ipa":"/ˈsæləri/ ","pos":"n.","def":"工资，薪水","sen":"They are receiving their monthly salary from Lord Bao.","trans":"他们正在包大人那儿领每月工资。","mne":"sal盐 + ary名词后缀 → salary工资（古代工钱以盐多少计算）"},{"word":"sale","ipa":"/seɪl/","pos":"n.","def":"出售，销售；销售额","sen":"The house sale is made when the key is handed over to the buyer.","trans":"当钥匙交到买家手中时，房屋买卖就完成了。","mne":""},{"word":"salesman","ipa":"/ˈseɪlzmən/","pos":"n.","def":"男推销员，男售货员","sen":"The salesman told us the details about the house for sale.","trans":"那个销售员告诉我们关于在售房屋的细节。","mne":"sales销售 + man人 → salesman售货员，推销员"},{"word":"salt","ipa":"/sɔːlt/","pos":"n.","def":"盐，食盐；  v.加盐于，用盐腌","sen":"Adding salt gives the dish more flavor.","trans":"加盐可以让菜肴更有滋味。","mne":""},{"word":"salutation","ipa":"/ˌsæljuˈteɪʃn/ ","pos":"n.","def":"招呼","sen":"Salutations come in many forms, such as shaking hands, waving, or a simple Hello.","trans":"打招呼的方式多种多样：握手、挥手，或者是简单的一句“你好”。","mne":"salut=salute问候 ＋ ation名词后缀 → salutation称呼；问候"},{"word":"same","ipa":"/seɪm/","pos":"adj.","def":"【数】相同的","sen":"These two squares are the same size.","trans":"这两个正方形的大小是相同的。","mne":"sam同一的 + e → same相同的"},{"word":"sample","ipa":"/ˈsæmpl/","pos":"n.","def":"(用于检验、分析的) 试样，样品；  adj.样品的，作为例子的；  v.抽样检查；抽取……的试样","sen":"I'll need a sample of your blood to see if you're sick.","trans":"我需要你的血样来确定你是不是生病了。","mne":"s分开 + ample拿 → 分开拿出 → sample标本"},{"word":"sand","ipa":"/sænd/","pos":"n.","def":"沙；  v.用砂纸打磨","sen":"The children are playing in the sand.","trans":"孩子们在沙滩上玩。","mne":""},{"word":"sandwich","ipa":"/ˈsænwɪtʃ/","pos":"n.","def":"三明治，夹肉面包","sen":"The kids were really happy when I made them each a sandwich for lunch.","trans":"当我给孩子们每人做了一个三明治当午餐时，他们好开心。","mne":""},{"word":"satellite","ipa":"/ˈsætəlaɪt/ ","pos":"n.","def":"人造卫星","sen":"This space satellite transmits TV signals to Earth.","trans":"这颗人造卫星把电视信号传输到地球。","mne":"sate足够，全部 + llite去 → 全速前进 → 跟随者，随从\nfollow → 人造卫星"},{"word":"satisfaction","ipa":"/ˌsætɪsˈfækʃn/","pos":"n.","def":"满足，满意","sen":"I gave their service a good rating to show my satisfaction.","trans":"我给了好评来表示我对他们的服务很满意。","mne":"satis足够，饱足 + faction名词后缀 → satisfaction满足"},{"word":"satisfactory","ipa":"/ˌsætɪsˈfæktəri/","pos":"adj.","def":"令人满意的","sen":"The little boy had a satisfactory service at the barber shop.","trans":"小男孩在理发店得到了令他满意的服务。","mne":"satis足够 + fact做 + ory表形容词 → satisfactory令人满意的"},{"word":"satisfied","ipa":"/ˈsætɪsfaɪd/","pos":"adj.","def":"感到满意的","sen":"The girl is very satisfied with the pizza.","trans":"这个女孩对披萨很满意。","mne":""},{"word":"satisfy","ipa":"/ˈsætɪsfaɪ/","pos":"v.","def":"满足；（使）满意","sen":"The boy went to a fast food restaurant to satisfy his desire for a hamburger.","trans":"男孩去快餐店满足了自己想吃汉堡包的欲望。","mne":"satis足够，饱足 + fy化 → satisfy使…满足"},{"word":"saturday","ipa":"/ˈsætərdeɪ/","pos":"n.","def":"星期六","sen":"Saturday is the first day of the weekend.","trans":"星期六是周末的第一天。","mne":"Satur=Saturn土星日，土曜日 + day天，日 → Saturday星期六"},{"word":"save","ipa":"/seɪv/","pos":"v.","def":"将（计算机上的信息）存盘，保存；节省，节约；拯救，挽救；  prep.除...外","sen":"Don't forget to save your work regularly.","trans":"不要忘记经常存盘。","mne":""},{"word":"saving","ipa":"/ˈseɪvɪŋ/","pos":"n.","def":"节省，节约","sen":"You can get a 70% savings over the regular price for clothes on sale.","trans":"在打折时购买衣服，可以比平时节省70%的钱。","mne":"sav(e)节省 + ing名词后缀 → saving节省"},{"word":"say","ipa":"/seɪ/","pos":"v.","def":"说","sen":"Why did you have to say it so loudly?","trans":"你为啥要说这么大声？","mne":""},{"word":"saying","ipa":"/ˈseɪɪŋ/ ","pos":"n.","def":"格言，警句，谚语","sen":"I hope the saying \"No pain, no gain\" isn't true.","trans":"我希望“没有付出，就没有收获”这句谚语说的不是真的。","mne":""},{"word":"scale","ipa":"/skeɪl/","pos":"n.","def":"天平，磅秤；刻度，尺度，标度；等级，级别，等级体系；鳞片，鳞状物；规模；比例，比例尺；  v.攀登","sen":"Stand on the weighing scale to get your weight.","trans":"站在体重秤上来测你的体重吧。","mne":""},{"word":"scan","ipa":"/skæn/","pos":"v.","def":"扫描；浏览；细看；  n.扫描；浏览","sen":"He is scanning the Chinese character for collecting cards.","trans":"他正在扫描这个汉字来集卡。","mne":""},{"word":"scarce","ipa":"/skers/","pos":"adj.","def":"缺乏的，不足的；稀少的，罕见的","sen":"Oil is becoming increasingly scarce on Earth.","trans":"地球上的石油已经变得越来越匮乏了。","mne":""},{"word":"scarcely","ipa":"/ˈskersli/","pos":"adv.","def":"几乎不；刚刚；决不","sen":"His grandfather can scarcely hear his grandson speaking. ","trans":"他祖父几乎听不到他孙子说的话。","mne":""},{"word":"scare","ipa":"/sker/","pos":"v.","def":"使害怕，惊吓；  n.惊恐，恐慌","sen":"The one thing that scares me most is giant mice.","trans":"最让我害怕的一样东西就是巨大的老鼠。","mne":""},{"word":"scary","ipa":"/ˈskeri/","pos":"adj.","def":"可怕的，恐怖的，吓人的","sen":"The house seems scary at night.","trans":"那栋房子晚上看起来很恐怖。","mne":""},{"word":"scatter","ipa":"/ˈskætər/","pos":"v.","def":"（使）分散，撒开，散播","sen":"The kid's room has toys scattered all over the ground.","trans":"儿童房里的玩具散落满地。","mne":""},{"word":"scene","ipa":"/siːn/","pos":"n.","def":"景象；现场；地点","sen":"The sunset over the road created quite a beautiful scene.","trans":"道路尽头的日落创造了一幅唯美的景象。","mne":""},{"word":"scenery","ipa":"/ˈsiːnəri/","pos":"n.","def":"风景；景色","sen":"The leaves turn yellow in autumn, which provides some beautiful scenery.","trans":"树叶在秋天变黄，平添了许多美景。","mne":"scen场景 + ery表场所，地点 → scenery风景，舞台布景"},{"word":"scenic","ipa":"/ˈsiːnɪk/","pos":"adj.","def":"风景优美的","sen":"These scenic islands are the perfect place to go traveling.","trans":"这些景色优美的岛屿是旅行的绝佳地点。","mne":"scen=scene情景 + ic形容词，...的 → 自然景色的"},{"word":"scent","ipa":"/sent/","pos":"n.","def":"气味；  v.察觉；嗅到","sen":"She loves the scent of the sunflower.","trans":"她喜欢向日葵的味道。","mne":""},{"word":"sceptical","ipa":"/ˈskeptɪkl/","pos":"adj.","def":"怀疑的，不相信的（同skeptical）","sen":"That doesn't sound right; I'm sceptical.","trans":"那听起来不对，我不相信。","mne":"scept=skept怀疑 + ic表示人 + al ...的 → sceptic=skeptic怀疑者 + al...的 → sceptical（也作skeptical）表示怀疑的"},{"word":"scepticism","ipa":"/ˈskeptɪsɪzəm/","pos":"n.","def":"怀疑态度；怀疑论","sen":"They have some scepticismabout the new product’s effectiveness \t","trans":"他们对这款新产品的效果存有一些怀疑。","mne":""},{"word":"schedule","ipa":"/ˈskedʒuːl/","pos":"n.","def":"时间表，计划表；  v.预订，安排","sen":"According to my schedule, I will go shopping on Monday afternoon.","trans":"根据我的日程表，星期一下午我会去购物。","mne":""},{"word":"scheme","ipa":"/skiːm/","pos":"n.","def":"方案，计划；阴谋，诡计；  v.图谋，密谋","sen":"Our scheme for the next game is a 4-4-2 formation.","trans":"我们队下一场比赛的方案是使用442阵型。","mne":""},{"word":"scholar","ipa":"/ˈskɑːlər/","pos":"n.","def":"学者","sen":"She's so young, but she's quite a little scholar.","trans":"她很年轻，但是已经是一个小小的学者了。","mne":"schol学派 + ar名词后缀，人 → scholar学者"},{"word":"scholarship","ipa":"/ˈskɑːlərʃɪp/","pos":"n.","def":"奖学金；学问","sen":"She is an excellent student so she gets the scholarship every year.","trans":"她是一位优秀的学生，所以每年她都能得到奖学金。","mne":"scholar学者 + ship表名词 → scholarship学问，学识"},{"word":"school","ipa":"/skuːl/","pos":"n.","def":"学校；  v.教育","sen":"I've met a lot of friends at school.","trans":"我在学校结识了很多朋友。","mne":""},{"word":"science","ipa":"/ˈsaɪəns/","pos":"n.","def":"科学","sen":"Physics and Chemistry are two different areas of science.","trans":"物理和化学是科学的两个不同领域。","mne":"sci知道 + ence名词后缀 → science科学；学科"},{"word":"scientific","ipa":"/ˌsaɪənˈtɪfɪk/","pos":"adj.","def":"科学的","sen":"Be very careful when doing scientific experiments.","trans":"做科学实验时一定要小心。","mne":"sci知道 + ent……的 + ific表形容词 → 知道的很多的 → 科学的"},{"word":"scientist","ipa":"/ˈsaɪəntɪst/ ","pos":"n.","def":"科学家","sen":"They are distinguished scientists in the fields of biology and physics.","trans":"他们是生物和物理领域杰出的科学家。","mne":"scient有知识的 + ist从事某种职业的人 → scientist科学家"},{"word":"scissors","ipa":"/ˈsɪzərz/","pos":"pl.","def":"剪刀","sen":"I use scissors to cut her hair.","trans":"我用剪刀为她剪头发。","mne":""},{"word":"scold","ipa":"/skoʊld/","pos":"v.","def":"怒骂，责骂，训斥","sen":"The mother scolds her child.","trans":"那位母亲斥责她的小孩。","mne":""},{"word":"scope","ipa":"/skoʊp/","pos":"n.","def":"瞄准镜；范围；广袤，地域","sen":"A scope helps the shooter aim at great distances.","trans":"瞄准镜有助于射手进行远距离瞄准。","mne":""},{"word":"score","ipa":"/skɔːr/","pos":"n.","def":"得分，分数；二十；乐谱；  v.得分","sen":"Each judge gave him a full score.","trans":"每个评委都给他打了满分。","mne":""},{"word":"scratch","ipa":"/skrætʃ/","pos":"v.","def":"（屏幕等）刮花；  n.抓痕，擦伤","sen":"I accidentally scratched the screen of my phone when I was exploring the ancient ruins.","trans":"当我在探索古遗址时，不小心刮花了手机的屏幕。","mne":""},{"word":"scream","ipa":"/skriːm/","pos":"v.","def":"（因愤怒或恐惧）高声喊、尖叫；尖叫着说出","sen":"This cute animal is screaming in fear. ","trans":"这只可爱的动物因为害怕而尖叫。","mne":""},{"word":"screen","ipa":"/skrin/","pos":"n.","def":"屏幕，荧屏；  v.遮蔽","sen":"The movie theater's screen is so large!","trans":"这个电影院的银幕好大！","mne":""},{"word":"screw","ipa":"/skruː/","pos":"n.","def":"螺丝；  v.拧紧；  v.用螺钉固定；把…拧紧","sen":"At each turn, the screw goes further into this piece of wood.","trans":"每转一圈，螺丝就会往这块木头里钻得更深。","mne":"shr切割 + w → screw螺丝，螺旋"},{"word":"sea","ipa":"/siː/","pos":"n.","def":"海洋，海域","sen":"The sea looks so calm today.","trans":"今天，这片海看起来很平静。","mne":""},{"word":"seal","ipa":"/siːl/","pos":"n.","def":"印章；海豹；  v.封（信封）；密封","sen":"He pressed the official seal onto the envelope and nobody else could open it.","trans":"他在信封上盖上了火漆印，没有其他人可以打开它。","mne":""},{"word":"search","ipa":"/sɜ:rtʃ/","pos":"n.","def":"搜索；  v.搜索；搜寻","sen":"The policeman is carrying out a search for the lost item.","trans":"这名警察正在进行搜索，寻找遗失的物品。","mne":""},{"word":"season","ipa":"/ˈsiːzn/","pos":"n.","def":"季（节）；  v.给……调味；风干（木柴）","sen":"There are four seasons in a year.","trans":"一年有四个季节。","mne":"sea播种 + son → 影响播种的时间 → season季节"},{"word":"seat","ipa":"/siːt/","pos":"n.","def":"座位；  v.使坐下","sen":"This theater only has sixty seats.","trans":"这个电影院只有六十个座椅。","mne":""},{"word":"second","ipa":"/ˈsekənd/","pos":"n.","def":"第二名；秒；片刻；  adj.第二的；  adv.第二，其次","sen":"The second got a silver medal.","trans":"第二名获得了一枚银牌。","mne":""},{"word":"secondary","ipa":"/ˈsekənderi/","pos":"adj.","def":"第二的；次要的","sen":"He took the silver medal, which is secondary in importance.","trans":"他获得了银牌，位列第二。","mne":"second第二 + ary…的 → secondary第二的；次要的"},{"word":"secret","ipa":"/ˈsiːkrət/","pos":"n.","def":"秘密；  adj.秘密的，保密的","sen":"She is telling her friend a surprising secret!","trans":"她正在告诉她朋友一个惊人的秘密！","mne":"se分开 + cret区别 → 分开来放 → secret秘密"},{"word":"secretary","ipa":"/ˈsekrəteri/","pos":"n.","def":"秘书；部长，大臣","sen":"As a secretary, she is responsible for answering phone calls and taking notes.","trans":"作为一名秘书，她负责接听电话和做记录。","mne":""},{"word":"section","ipa":"/ˈsekʃn/","pos":"n.","def":"部分；章节；区域","sen":"This chart can be divided into six sections of different sizes.","trans":"这个图表可以分成六个大小不同的部分。","mne":"sect切，割 + ion名词后缀 → 切开；部门"},{"word":"sector","ipa":"/ˈsektər/","pos":"n.","def":"（经济等的）行业；部门；扇形，扇区","sen":"This country's economy has three different sectors: manufacturing, agriculture, and services.","trans":"这个国家的经济有三个不同的行业：制造业、农业和服务业。","mne":"sect切 + or名词后缀 → sector部门"},{"word":"secure","ipa":"/sɪˈkjʊr/","pos":"v.","def":"保护；使安全；（经过努力）获得；  adj.安全的；有把握的，确切的","sen":"The anti-virus software can secure our computers.","trans":"防毒软件可以保护我们的电脑。","mne":"se免于 + cure忧虑 → secure保护"},{"word":"security","ipa":"/sɪˈkjʊrəti/","pos":"n.","def":"安全；保护措施；债券；抵押物；保障，保护","sen":"You must go through the security check at the airport.","trans":"在机场，你必须通过安全检查。","mne":"secur安全的 + ity名词后缀 → security安全；证券"},{"word":"see","ipa":"/siː/","pos":"v.","def":"看","sen":"He can see very far.","trans":"他可以看得很远。","mne":""},{"word":"seed","ipa":"/siːd/","pos":"n.","def":"【生】种子；种子，籽；  v.播种，结籽","sen":"A seed contains the genetic information of a plant.","trans":"一颗种子包含了植物的遗传信息。","mne":""},{"word":"seek","ipa":"/siːk/","pos":"v.","def":"寻找；寻求","sen":"Let's play hide-and-seek!","trans":"让我们来玩捉迷藏吧！","mne":""},{"word":"seem","ipa":"/siːm/","pos":"v.","def":"似乎，好像，看来","sen":"Judging by the clouds, it seems that it will rain.","trans":"根据这云层判断，似乎要下雨。","mne":""},{"word":"seize","ipa":"/siːz/","pos":"v.","def":"抓住，逮捕；夺取，攻占","sen":"They seized one another by the wrist.","trans":"他们相互抓住了对方的手腕。","mne":""},{"word":"seldom","ipa":"/ˈseldəm/","pos":"adv.","def":"很少，不常；  adj.不常的；稀少的","sen":"It seldom rains in the desert.","trans":"沙漠里很少下雨。","mne":""},{"word":"select","ipa":"/səˈlekt/","pos":"v.","def":"选择，挑选；  adj.精选的，选择的","sen":"Which dress do you think I should select?","trans":"你觉得我应该选哪条裙子？","mne":"se分开 + lect选 → 选出分开 → select选择"},{"word":"selection","ipa":"/sɪˈlɛkʃən/","pos":"n.","def":"可供挑选的商品","sen":"Our nursery offers a selection of spring flowers of many different colors.","trans":"我们的苗圃里有各种颜色的春季花卉可供挑选。","mne":"se分开 + lect选择，收集 → select分开选=选择 + ion表名词 → 选择"},{"word":"self","ipa":"/self/","pos":"n.","def":"自己，自我，自身","sen":"She thinks she can find her true self in the mirror.","trans":"她认为她在镜子里能找到真正的自己。","mne":""},{"word":"selfish","ipa":"/ˈselfɪʃ/","pos":"adj.","def":"自私的","sen":"He's so selfish, always hogging the toys.","trans":"他太自私了，总是独占着玩具。","mne":"self自己 + ish形容词后缀 → selfish自私的"},{"word":"sell","ipa":"/sel/","pos":"v.","def":"出售，卖","sen":"She sells eggs on the street.","trans":"她在这条街上卖鸡蛋。","mne":""},{"word":"semester","ipa":"/sɪˈmestər/","pos":"n.","def":"学期；半学年","sen":"A school year often contains two semesters.","trans":"一学年通常包含两个学期。","mne":"se=sex六 + mester=mensis月  → 六个月（约一个学期）  → semester学期"},{"word":"semiconductor","ipa":"/ˌsemikənˈdʌktər/","pos":"n.","def":"半导体","sen":"Semiconductor is an important material to make chips.","trans":"半导体是做芯片的重要材料。","mne":"semi半 ＋ conduct传导＋ or名词后缀，表物 → semiconductor半导体"},{"word":"seminar","ipa":"/ˈsemɪnɑːr/","pos":"n.","def":"研讨会","sen":"A teacher and some students are holding a math seminar.","trans":"一位老师和一些学生正在开数学研讨会。","mne":""},{"word":"senate","ipa":"/ˈsenət/","pos":"n.","def":"参议院，上院","sen":"Several politicians are talking in front of the United States Senate.","trans":"几个政治家在美国参议院前面交谈。","mne":"sen老 + ate名词后缀  → 参议院，上议院，古罗马的元老院议员"},{"word":"send","ipa":"/send/","pos":"v.","def":"发送；送，寄","sen":"She sends a message to her friend.","trans":"她给她的朋友发了一条信息。","mne":""},{"word":"senior","ipa":"/ˈsiːniər/","pos":"adj.","def":"资格老的，地位较高的；年长的；  n.（大学或高中）毕业生；长辈；上司","sen":"He is saluting the senior officer.","trans":"他正在向长官敬礼。","mne":"sen年老 + ior表示人 → 上年纪的人 → senior长辈"},{"word":"sensation","ipa":"/senˈseɪʃn/","pos":"n.","def":"感觉；知觉；轰动","sen":"The hot sun is causing a burning sensation on her shoulders.","trans":"炙热的太阳让她的肩膀产生了灼热感。","mne":"sens感觉 + ation 表示行为、状态、结果 → sensation（感官的）感觉能力"},{"word":"sense","ipa":"/sens/","pos":"n.","def":"感官；  v.觉得，意识到","sen":"I'm blind, but I can read this book by using my sense of touch.","trans":"我是盲人，但是我能用我的触觉来读这本书。","mne":""},{"word":"sensible","ipa":"/ˈsensəbl/","pos":"adj.","def":"明智的，理智的；可觉察的；合理的","sen":"It's a sensible choice to take only a few things when going climbing.","trans":"轻装上阵去爬山是一个明智的选择。","mne":"sens感觉 + ible形容词后缀，能…的 → sensible能感觉的，明智的"},{"word":"sensitive","ipa":"/ˈsensətɪv/","pos":"adj.","def":"敏感的；灵敏的","sen":"His teeth are sensitive to ice cream.","trans":"他的牙齿对冰淇淋很敏感。","mne":"sens感觉 + itive形容词后缀 → sensitive敏感的"},{"word":"sentence","ipa":"/ˈsentəns/","pos":"v.","def":"判决；  n.句子；判决","sen":"The judge sentenced him to life in prison.","trans":"法官判决他终身监禁。","mne":"sent（感觉/判断） + ence（名词化） → 原指“思想表达”，后分化为“句子”和“判决”两义"},{"word":"separate","ipa":"/ˈseprət/","pos":"adj.","def":"分开的；独立的；  v.使分开，分离","sen":"They stood in separate places, facing away from each other.","trans":"他们站在分开的地方，背对着彼此。","mne":"separ分离 + ate形容词后缀具有...的 → separate分离的；个别的"},{"word":"september","ipa":"/sepˈtembər/","pos":"n.","def":"九月","sen":"September 5th is my birthday. It's coming soon!","trans":"9月5日是我的生日，就快要到了！","mne":"Septem七 + ber → 古罗马的七月，历法修改后沿用成了九月 → September公历九月"},{"word":"sequence","ipa":"/ˈsiːkwəns/","pos":"n.","def":"顺序，次序","sen":"Arrange the files in sequence.","trans":"按顺序排列文件。","mne":"sequ跟随 + ence名词后缀 → sequence连续发生，连续"},{"word":"series","ipa":"/ˈsɪriz/","pos":"n.","def":"一连串；系列，系列节目；系列片；连续比赛，系列比赛","sen":"A series of coinciding incidents resulted in the glass-breaking.","trans":"一连串巧合的事件导致玻璃被打碎。","mne":""},{"word":"serious","ipa":"/ˈsɪriəs/","pos":"adj.","def":"认真的，严肃的；严重的；庄重的","sen":"He is always very serious while working.","trans":"他工作时总是很认真。","mne":""},{"word":"servant","ipa":"/ˈsɜːrvənt/","pos":"n.","def":"佣人，仆人","sen":"The servant served them with drinks.","trans":"这个佣人给他们送上了饮料。","mne":"serv服务，保持 ＋ ant表示人 → servant仆人；公务员"},{"word":"serve","ipa":"/sɜːrv/","pos":"v.","def":"服务；招待；供应；服役","sen":"Wearing a smile, the man served us a plate of Chinese pancake.","trans":"那名男子面带微笑，为我们端上了一盘中式煎饼。","mne":""},{"word":"service","ipa":"/ˈsɜːrvɪs/","pos":"n.","def":"服务；公共服务事业（或系统）；维修保养","sen":"The cleaning lady provides a range of cleaning services.","trans":"这位清洁女工提供一系列清洁服务。","mne":"serv服务 + ice表名词，行为，状态 → service服务"},{"word":"session","ipa":"/ˈseʃn/","pos":"n.","def":"会议；会期；（法庭的）开庭；一段时间的（活动）","sen":"An important session was held on investment policies.","trans":"一个关于投资政策的重要会议召开了。","mne":"ses=sed坐下 + sion名词后缀 → 需要坐下的情况 → session会议"},{"word":"set","ipa":"/set/","pos":"v.","def":"设置；（小心地）放置；  n.一套，一副，一批；【数】集合；  adj.固定的，规定的，固执的","sen":"She set the alarm for 7 a.m. before going to bed.","trans":"她在睡觉前把闹钟设置到了早上7点。","mne":""},{"word":"settle","ipa":"/ˈsetl/","pos":"v.","def":"安顿；结束（争论）；解决；调停","sen":"He built himself a house and decided to settle there.","trans":"他给自己修建了一所房子，并决定在那里安顿下来。","mne":""},{"word":"settlement","ipa":"/ˈsetlmənt/ ","pos":"n.","def":"协议；解决；定居点","sen":"The two sides shook hands on the settlement.","trans":"双方握手，协议达成。","mne":"settle解决，安居 + ment表示行为、行为的过程或结果 → settlement解决"},{"word":"seven","ipa":"/ˈsevn/","pos":"num.","def":"七，七个","sen":"The candle on the birthday cake is in the shape of a seven.","trans":"蛋糕上的蜡烛是7的形状。","mne":""},{"word":"seventeen","ipa":"/ˌsevnˈtiːn/","pos":"num.","def":"十七岁的，十七（个）的","sen":"I need the ball number seventeen to win the lottery.","trans":"要想赢得彩票大奖，我还需要一个17号球。","mne":"seven七 + teen十 → 十七"},{"word":"seventy","ipa":"/ˈsevnti/","pos":"num.","def":"七十，七十个","sen":"Seventy years is a long time.","trans":"七十年是很长的一段时间。","mne":"seven七 + ty十 → seventy七十"},{"word":"several","ipa":"/ˈsevrəl/","pos":"det.","def":"几个，一些；  adj.各自的，分别的","sen":"I have several apples for you!","trans":"我给你准备了几个苹果！","mne":"se分离 + veral准备好 → several各自的"},{"word":"severe","ipa":"/sɪˈvɪr/，/səˈvɪr/","pos":"adj.","def":"极为恶劣的；严重的；严厉的；艰难的","sen":"It's hard for people to walk in such severe weather conditions.","trans":"在如此恶劣的天气条件下，人们走得很艰难。","mne":"sever诚恳 + e → severe严肃的，严厉的"},{"word":"sew","ipa":"/soʊ/","pos":"v.","def":"缝，缝纫；缝补","sen":"She uses the machine to sew a new dress.","trans":"她用机器缝制一条新裙子。","mne":""},{"word":"sex","ipa":"/seks/","pos":"n.","def":"性别","sen":"The application form asks for your sex.","trans":"这张申请表需要填上您的性别。","mne":""},{"word":"shade","ipa":"/ʃeɪd/","pos":"n.","def":"阴凉处；遮光物；阴影；  v.遮蔽（光线）","sen":"I am standing in the shade of a tree. It's cooler here.","trans":"我站在树荫下，这儿凉快些。","mne":""},{"word":"shadow","ipa":"/ˈʃædoʊ/ ","pos":"n.","def":"影子；阴影；  v.把影子投在……；盯梢","sen":"I could see the boy's shadow on the ground as he played soccer.","trans":"这个男孩踢球的时候，我能看到他在地上的影子。","mne":"shade阴影，影子 + ow后缀 → shadow影子"},{"word":"shake","ipa":"/ʃeɪk/","pos":"v.","def":"摇动；  n.摇；颤抖","sen":"Shake the bottle well before drinking.","trans":"饮用前请摇晃瓶子。","mne":""},{"word":"shall","ipa":"/ʃæl/, /ʃəl/","pos":"v.","def":"提供建议或征求意见，要不要？","sen":"Shall we dance together?","trans":"我们一起跳个舞吧？","mne":""},{"word":"shallow","ipa":"/ˈʃæloʊ/","pos":"adj.","def":"浅的；肤浅的","sen":"The boy is swimming in the shallow pool.","trans":"这个男孩在浅水池里游泳。","mne":""},{"word":"shame","ipa":"/ʃeɪm/","pos":"n.","def":"羞愧；  v.使羞愧（或惭愧）","sen":"He felt a deep sense of shame because he cheated in the exam.","trans":"他因考试作弊而深感羞愧。","mne":""},{"word":"shameless","ipa":"/ˈʃeɪmləs/","pos":"adj.","def":"无耻的，不知廉耻的","sen":"It is shameless to shout loudly in public.","trans":"在公众场合大声吼叫是无耻的行为","mne":""},{"word":"shape","ipa":"/ʃeɪp/","pos":"n.","def":"形状，样子；身材；  v.使形成，塑造","sen":"Put your hands together to make a heart shape.","trans":"把你的手放在一起比个心形。","mne":""},{"word":"share","ipa":"/ʃer/","pos":"v.","def":"分享，共享；分配，均分；  n.股份，股东","sen":"Would you like to share some ice cream with me?","trans":"你想和我一起分享冰激凌吗？","mne":""},{"word":"shareholder","ipa":"/ˈʃerhoʊldər/","pos":"n.","def":"股东","sen":"A significant decision, it requires the approval of our shareholders.","trans":"这是一个重大决定，需要得到我们股东的批准。","mne":"share股份 + holder持有人 → shareholder股东"},{"word":"sharp","ipa":"/ʃɑːrp/","pos":"adj.","def":"锋利的，尖锐的；敏锐的；  adv.锐利地","sen":"This knife is so sharp that it can easily slice the apple.","trans":"这把刀好锋利啊，切苹果超级容易。","mne":""},{"word":"shave","ipa":"/ʃeɪv/","pos":"v.","def":"剃（须发），刮脸；  n.剃须，修面","sen":"The man is shaving in front of the mirror.","trans":"这个男人正在镜子前刮胡子。","mne":""},{"word":"she","ipa":"/ʃi/","pos":"pron.","def":"（主格）她","sen":"She is a pretty woman.","trans":"她是美女。","mne":""},{"word":"sheep","ipa":"/ʃiːp/","pos":"n.","def":"绵羊（单复数同形）","sen":"Sheep are raised to produce wool.","trans":"人们养羊是为了产羊毛。","mne":""},{"word":"sheer","ipa":"/ʃɪr/","pos":"adj.","def":"纯粹的；陡峭的","sen":"She answered these questions correctly by sheer luck.","trans":"她这几道题是全凭运气答对的。","mne":""},{"word":"sheet","ipa":"/ʃiːt/","pos":"n.","def":"被单；纸张；薄片，薄板","sen":"I like the white sheet since it looks clean.","trans":"我喜欢这个白床单，因为它看起来很干净。","mne":""},{"word":"shelf","ipa":"/ʃelf/","pos":"n.","def":"架子，搁板","sen":"There are many books on the shelf.","trans":"架子上放了很多书。","mne":""},{"word":"shell","ipa":"/ʃel/","pos":"n.","def":"壳，外壳；炮弹；  v.剥壳；炮击；给……去壳","sen":"The egg shell broke in half.","trans":"蛋壳破成了两半。","mne":""},{"word":"shelter","ipa":"/ˈʃeltər/","pos":"n.","def":"避难所；遮蔽物；庇护处；  v.遮蔽，庇护","sen":"Someone used branches to make a shelter in the woods.","trans":"有人用树枝在树林里搭了个躲避处。","mne":"shel盾 + ter群，队 → shelter躲避处"},{"word":"shield","ipa":"/ʃiːld/","pos":"n.","def":"盾牌；  v.保护","sen":"The knight fights with a sword and shield.","trans":"骑士挥舞着宝剑和盾牌战斗。","mne":""},{"word":"shift","ipa":"/ʃɪft/","pos":"v.","def":"换挡；改换，替换；转移；  n.轮班","sen":"You have to shift gears as you drive around the corner.","trans":"你开车驶过拐角时要换挡。","mne":""},{"word":"shine","ipa":"/ʃaɪn/","pos":"v.","def":"照耀，闪光；擦亮","sen":"The sun is shining in the sky.","trans":"太阳在天空中熠熠闪光。","mne":""},{"word":"ship","ipa":"/ʃɪp/","pos":"n.","def":"（大）船，舰；  v.装上船，运送","sen":"The ship is carrying a lot of goods.","trans":"这艘船装着大量货物。","mne":""},{"word":"shipment","ipa":"/ˈʃɪpmənt/","pos":"n.","def":"装载的货物；运输，装运","sen":"I'm waiting for the shipment coming from India.","trans":"我在等待从印度运来的货物。","mne":"ship船 + ment表名词 → shipment装船，装运"},{"word":"shirt","ipa":"/ʃɜːrt/","pos":"n.","def":"（尤指男式的）衬衫","sen":"He always has to wear a shirt and tie to work.","trans":"他总是穿衬衫打领带去工作。","mne":""},{"word":"shock","ipa":"/ʃɑːk/ ","pos":"v.","def":"使……震惊，使惊讶；使……震动；  n.震惊；震动；休克","sen":"She was shocked to see how much her stock value had fallen.","trans":"看到股票跌了这么多，她真是惊呆了！","mne":""},{"word":"shocking","ipa":"/ˈʃɑːkɪŋ/","pos":"adj.","def":"令人震惊的，骇人听闻的","sen":"My mobile phone bill this month was shocking!","trans":"我这个月的电话账单太令人震惊了！","mne":""},{"word":"shoe","ipa":"/ʃuː/","pos":"n.","def":"鞋","sen":"There are two pairs of sports shoes on the floor.","trans":"地上有两双运动鞋。","mne":""},{"word":"shoot","ipa":"/ʃuːt/","pos":"v.","def":"射击，射伤；射门","sen":"The instructor taught the girl how to shoot a pistol.","trans":"教练教了女孩儿怎样用手枪射击。","mne":""},{"word":"shop","ipa":"/ʃɑːp/","pos":"n.","def":"商店；  v.购物","sen":"We are buying fruits in a shop.","trans":"我们正在商店里买水果。","mne":""},{"word":"shore","ipa":"/ʃɔːr/","pos":"n.","def":"岸；滨；海滨","sen":"He swam to the shore.","trans":"他朝岸边游去。","mne":""},{"word":"short","ipa":"/ʃɔːrt/","pos":"adj.","def":"短的；矮的","sen":"Short hair is in style now.","trans":"现在很流行短发。","mne":""},{"word":"shortage","ipa":"/ˈʃɔːrtɪdʒ/","pos":"n.","def":"短缺，不足，缺少","sen":"The child is experiencing a shortage of water.","trans":"这个孩子正面临水的短缺。","mne":"short短 + age名词形式 → 不足，缺少"},{"word":"shortcoming","ipa":"/ˈʃɔːrtkʌmɪŋ/","pos":"n.","def":"短处，缺点","sen":"A shortcoming of this kind of dog is that their legs are too short.","trans":"这种狗的缺点是它们的腿太短了。","mne":"short短的 + coming来到 → shortcoming短处，缺点"},{"word":"shortly","ipa":"/ˈʃɔːrtli/","pos":"adv.","def":"不久，立刻","sen":"The note on the door said that they would be back shortly.","trans":"门上的纸条写着他们不久就会回来。","mne":"short短的 + ly……地 → 立刻，马上，不久；简单；"},{"word":"shorts","ipa":"/ʃɔːrts/","pos":"n.","def":"短裤","sen":"When the weather is warm, it's time to wear shorts.","trans":"天气暖和时，就是穿短裤的时候了。","mne":""},{"word":"shot","ipa":"/ʃɑːt/","pos":"n.","def":"击球，投球；射击，枪声","sen":"\"Nice shot!\" I said as she hit the ball.","trans":"”好球！“她击球时我说。","mne":""},{"word":"should","ipa":"/ʃʊd/","pos":"aux.","def":"应该","sen":"When you are working, you should sit up straight.","trans":"工作时，你应该挺身坐直。","mne":""},{"word":"shoulder","ipa":"/ˈʃoʊldər/","pos":"n.","def":"肩膀；  v.肩负，承担","sen":"The old man has pain in his shoulder.","trans":"这位老年人肩膀疼。","mne":""},{"word":"shout","ipa":"/ʃaʊt/","pos":"v.","def":"呼喊，大声说，叫","sen":"He cupped his hands around his mouth and shouted loudly.","trans":"他将双手拢在嘴边，大声呼喊。","mne":""},{"word":"show","ipa":"/ʃoʊ/","pos":"v.","def":"展示；（提供事实、信息）证明，表明；  n.演出；节目；展览；显示，表现","sen":"The girl is showing the photocards she's collected.","trans":"这个女生在展示她收集的小卡。","mne":""},{"word":"shower","ipa":"/ˈʃaʊər/","pos":"n.","def":"淋浴，淋浴器；阵雨；  v.淋浴，淋湿","sen":"The cat is happy to take a shower.","trans":"小猫在快乐地洗淋浴。","mne":""},{"word":"shrink","ipa":"/ʃrɪŋk/","pos":"v.","def":"退缩；收缩","sen":"The girl shrank back, covering her face because of the horror movie.","trans":"女孩因为害怕恐怖片，挡住脸向后缩。","mne":"shr扭转，弯曲 + ink → shrink收缩"},{"word":"shut","ipa":"/ʃʌt/","pos":"v.","def":"关上，闭上；  adj.关闭的，合拢的","sen":"Shut the door, please.","trans":"请把门关上。","mne":""},{"word":"shy","ipa":"/ʃaɪ/","pos":"adj.","def":"羞怯的；腼腆的；胆怯的，迟疑的","sen":"They are both shy on the first date.","trans":"第一次约会时，他们俩都很害羞。","mne":""},{"word":"sick","ipa":"/sɪk/","pos":"adj.","def":"生病的，有病的；不舒服的；恶心的，想吐的","sen":"The sick boy fell asleep in the bed.","trans":"这个生病的男孩在床上睡着了。","mne":""},{"word":"side","ipa":"/saɪd/","pos":"n.","def":"边；旁边；面","sen":"There are many trees on both sides of the river.","trans":"小河两边的岸上有许多树。","mne":""},{"word":"sideways","ipa":"/ˈsaɪdweɪz/","pos":"adv.","def":"向侧面地；  adj.斜着的","sen":"I am sliding the curtain open sideways.","trans":"我正在将窗帘向侧面拉开。","mne":"side边 + ways方向 → 斜向一边地 "},{"word":"sigh","ipa":"/saɪ/","pos":"v.","def":"叹息，叹气；  n.叹气，叹息","sen":"He sighed with relief after a whole day's busy work.","trans":"经过一天繁忙的工作，他舒了一口气。","mne":""},{"word":"sight","ipa":"/saɪt/","pos":"n.","def":"视力；景象，情景；  v.看见","sen":"My dog's sight is better with these binoculars.","trans":"用了望远镜，我的狗视力更好了。","mne":""},{"word":"sightseeing","ipa":"/ˈsaɪtsiːɪŋ/","pos":"n.","def":"游览；观光","sen":"I like to go sightseeing around seaside towns.","trans":"我喜欢游览海滨小镇。","mne":"sight眼光 + see看 + ing名词后缀 → 用眼看 → 观光，游览"},{"word":"sign","ipa":"/saɪn/ ","pos":"n.","def":"记号，符号；标志；标牌，指示牌；手势；迹象；  v.签名；签字；使眼色；做暗号；做手势；签署","sen":"Rick left the sign for him so that he could follow up.","trans":"瑞克给他留下了记号让他能够跟上队伍。","mne":""},{"word":"signal","ipa":"/ˈsɪɡnəl/","pos":"n.","def":"信号；标志；  v.标志；发信号","sen":"There's no signal in the mountains.","trans":"山里没有信号。","mne":"sign标志 + al名词/形容词后缀 → signal信号/显要的"},{"word":"signature","ipa":"/ˈsɪɡnətʃər/","pos":"n.","def":"签名，署名","sen":"The boy wrote his father's signature at the bottom of paper.","trans":"男孩在试卷下面签下了他爸爸的名字。","mne":"signa=sign记号 + ture表名词 → 签名"},{"word":"significance","ipa":"/sɪɡˈnɪfɪkəns/","pos":"n.","def":"意义，含义；重要性","sen":"The wedding anniversary is of great significance to the couple.","trans":"结婚纪念日对这对夫妻来说意义重大。","mne":"signific=signify有重要性的 + ance名词后缀 → significance重要性；意义"},{"word":"significant","ipa":"/sɪɡˈnɪfɪkənt/","pos":"adj.","def":"有重大意义的，重要的；意味深长的；显著的","sen":"It was a significant day because we got married on that day.","trans":"那是一个具有重大意义的日子，因为我们在那天结婚了。","mne":"signify使...闻名 + icant表形容词 -> significant有重大意义的"},{"word":"significantly","ipa":"/sɪɡˈnɪfɪkəntli/","pos":"adv.","def":"显著地；有重大意义地","sen":"The company's profits have significantly increased in the last two years.","trans":"这家公司的利润在过去两年里显著增加了。","mne":"sign记号，信号 ＋ ific产生…的 ＋ ant形容词后缀 ＋ ly副词后缀 → significant有象征意义的 ＋ ly副词后缀 → significantly意味深长地"},{"word":"silence","ipa":"/ˈsaɪləns/","pos":"n.","def":"寂静，无声，沉默；  v.使沉默","sen":"They sat face to face in silence.","trans":"他们默然对坐。","mne":""},{"word":"silent","ipa":"/ˈsaɪlənt/","pos":"adj.","def":"沉默的，不说话的；  n.无声电影","sen":"We should keep silent in the library.","trans":"在图书馆里我们应当保持安静。","mne":""},{"word":"silk","ipa":"/sɪlk/ ","pos":"n.","def":"丝，丝绸","sen":"The white silk looks so soft.","trans":"这块白色丝绸看上去真柔软。","mne":""},{"word":"silly","ipa":"/ˈsɪli/","pos":"adj.","def":"傻的，愚蠢的；（尤指像小孩一样）可笑的，荒唐的","sen":"Silly to wear a down coat on a hot summer day.","trans":"大热天穿羽绒服，太傻了。","mne":""},{"word":"silver","ipa":"/ˈsɪlvər/","pos":"n.","def":"银；银器；  adj.银色的；  v.镀银于，使……成银色","sen":"The silver necklace tarnished over time.","trans":"银项链随着时间流逝变暗了。","mne":""},{"word":"similar","ipa":"/ˈsɪmələr/","pos":"adj.","def":"相似的；类似的","sen":"They are wearing the similar hats.","trans":"她们戴了一样的帽子。","mne":"simil一样 + ar……的 → similar同样的，相似的"},{"word":"similarity","ipa":"/ˌsɪməˈlærəti/","pos":"n.","def":"【化】相似点","sen":"The similarity between water and hydrogen peroxide is that both are made up of hydrogen and oxygen.","trans":"水和过氧化氢的相似点在于，它们都是由氢和氧构成的。","mne":"similar相似的 + ity名词后缀 → similarity类似"},{"word":"similarly","ipa":"/ˈsɪmələrli/","pos":"adv.","def":"类似地，相似地","sen":"The group of teenagers are dressed similarly.","trans":"这群年轻人的穿着很相似。","mne":"similar相似的 + ly表副词 → similarly相似地"},{"word":"simple","ipa":"/ˈsɪmpl/","pos":"adj.","def":"简单的，易于理解的；朴素的","sen":"You can solve this problem—it's simple!","trans":"你可以解决这个问题的，它很简单！","mne":"sim一个，一起 + ple重叠 → 只有一个重叠在一起 → simple简单的"},{"word":"simplify","ipa":"/ˈsɪmplɪfaɪ/","pos":"v.","def":"【化】简化","sen":"The process of photosynthesis can be simplified into two stages: light-dependent reactions and light-independent reactions.","trans":"光合作用的过程可以简化为两个阶段：依赖光的反应和不依赖光的反应。","mne":"simple简单 + -fy动词词尾 → 使简化"},{"word":"simply","ipa":"/ˈsɪmpli/","pos":"adv.","def":"简单地；仅仅，只不过；简直","sen":"My room is just simply furnished because I'm not at home very often.","trans":"我的房间陈设简单，因为我不常在家。","mne":"simpl=simple简单的 + (l)y表副词 → simply简单地"},{"word":"simulate","ipa":"/ˈsɪmjuleɪt/","pos":"v.","def":"模仿；假装","sen":"The playful child simulates his cat's movements.","trans":"顽皮的小孩模仿猫咪的动作。","mne":"simul相类似，一样 + ate动词后缀 → 做得相像 → simulate模仿"},{"word":"simultaneous","ipa":"/ˌsaɪmlˈteɪniəs/","pos":"adj.","def":"同时的","sen":"I'm good at handling simultaneous tasks to improve my work efficiency.","trans":"我擅长处理同时进行的任务以提高我的工作效率。","mne":"simult=simul一样，相同 + aneous有……性质的 → [时间]相同的"},{"word":"simultaneously","ipa":"/ˌsaɪmlˈteɪniəsli/","pos":"adv.","def":"同时地","sen":"The file has been simultaneously sent to all team members.","trans":"文件被同时发送给所有的组员。","mne":"simultaneous同时发生的 + ly副词后缀 → simultaneously同时发生地"},{"word":"since","ipa":"/sɪns/","pos":"conj.","def":"由于；既然","sen":"The ground is quite wet since it rained yesterday. ","trans":"由于昨天下雨了，所以地面非常潮湿。","mne":""},{"word":"sincere","ipa":"/sɪnˈsɪr/","pos":"adj.","def":"真诚的，诚恳的","sen":"She bowed to show her sincere thanks to her classmate.","trans":"她鞠躬表示她对同学的诚挚的谢意。","mne":"sin同样的 + cere成长 -> 一同成长，关系密切 -> 真诚的"},{"word":"sincerely","ipa":"/sɪnˈsɪrli/","pos":"adv.","def":"真诚地","sen":"The robot sincerely hopes to make friends with humans.","trans":"这个机器人真心希望和人类做朋友。","mne":"sincere真实的 + ly副词后缀 → sincerely真诚地"},{"word":"sing","ipa":"/sɪŋ/","pos":"v.","def":"唱，歌唱；演唱","sen":"The girl is singing.","trans":"这女孩正在唱歌。","mne":""},{"word":"singer","ipa":"/ˈsɪŋər/","pos":"n.","def":"歌手","sen":"The singer is recording a song in the recording studio.","trans":"歌手正在录音棚里录歌。","mne":"sing唱歌 + er人 → singer歌唱家"},{"word":"single","ipa":"/ˈsɪŋɡl/","pos":"adj.","def":"单个的，单独的；未婚的；单身的；  n.单程票","sen":"There is a single shoe on the ground.","trans":"地上有一只单独的鞋。","mne":""},{"word":"singular","ipa":"/ˈsɪŋɡjələr/","pos":"adj.","def":"单独的，单个的","sen":"There is a singular red flower amongst a bed of yellow ones.","trans":"在黄色的花丛中有一朵红色的花。","mne":"singul=single单一 + ar……的 → singular单独的"},{"word":"sink","ipa":"/sɪŋk/","pos":"n.","def":"水槽，洗碗池；  v.（使）下沉，（使）降低，（使）沉没","sen":"I am washing the dishes in the sink.","trans":"我正在洗水槽里的餐具。","mne":""},{"word":"sir","ipa":"/sɜːr/","pos":"n.","def":"先生","sen":"Please call me \"Sir\" when you talk to me!","trans":"当你跟我说话时，请称呼“先生”。","mne":""},{"word":"sister","ipa":"/ˈsɪstər/","pos":"n.","def":"姐妹，姐，妹","sen":"The girl is the little boy's sister.","trans":"这个女孩是小男孩的姐姐。","mne":"sis自己的 + ter女性 → 与自己关系密切的女性 → sister姐妹"},{"word":"sit","ipa":"/sɪt/","pos":"v.","def":"坐","sen":"The little girl is sitting on the ground.","trans":"小女孩坐在地上。","mne":""},{"word":"site","ipa":"/saɪt/ ","pos":"n.","def":"场所；位置","sen":"Builders are working at the construction site.","trans":"建筑工人们正在工地上干活。","mne":""},{"word":"situation","ipa":"/ˌsɪtʃuˈeɪʃn/","pos":"n.","def":"形势，局面；情况，场景","sen":"It's hard to choose which way to go in this situation.","trans":"这种情形下很难选择该走哪条路。","mne":"situat位于 + ion名词后缀 → situation地理位置"},{"word":"six","ipa":"/sɪks/","pos":"num.","def":"六，六个","sen":"These are my six favorite drinks.","trans":"这是我最喜爱的六种饮品。","mne":""},{"word":"sixteen","ipa":"/ˌsɪksˈtiːn/","pos":"num.","def":"十六，十六个","sen":"She got a special gift when she turned sixteen years old.","trans":"当她年满16岁时，收到了一份特殊的礼物。","mne":"six六 + teen十几 → sixteen十六"},{"word":"sixty","ipa":"/ˈsɪksti/","pos":"num.","def":"六十，六十个","sen":"My grandmother turned sixty years old today.","trans":"我祖母今天60岁了。","mne":"six六 + ty十 → sixty六十"},{"word":"size","ipa":"/saɪz/","pos":"n.","def":"大小，尺寸；尺码","sen":"These shoes come in different sizes: medium, small and large.","trans":"这些鞋子有不同的尺寸：中号、小号和大号。","mne":""},{"word":"skate","ipa":"/skeɪt/","pos":"v.","def":"滑冰，溜冰，滑（滑板）；  n.冰鞋","sen":"The little boy is skating by himself.","trans":"这个小男孩一个人在滑冰。","mne":""},{"word":"skeptical","ipa":"/ˈskeptɪkl/","pos":"adj.","def":"表示怀疑的","sen":"I'm skeptical that the weasel did not come here merely to extend his greetings.","trans":"我怀疑那只黄鼠狼不仅是来这里表达问候的。","mne":"skept怀疑 + ical表形容词 → skeptical怀疑的"},{"word":"skepticism","ipa":"/sˈkɛptɪˌsɪzəm/","pos":"n.","def":"怀疑；怀疑论","sen":"My skepticism of other people's motives has almost always been well-founded!","trans":"我对他人动机的怀疑基本都是有依据的！","mne":"skeptic怀疑者 + ism...主义 → skepticism怀疑论"},{"word":"sketch","ipa":"/sketʃ/","pos":"n.","def":"素描；速写；  v.速写；简述","sen":"The artist is doing a sketch of the living room.","trans":"这位画家正在画一幅客厅的素描。","mne":""},{"word":"sketchy","ipa":"/ˈsketʃi/","pos":"adj.","def":"概略的，粗略的","sen":"Your agenda for the meeting today is a little sketchy.","trans":"今天你的会议日程有点儿粗略。","mne":"sketch略图 ＋ y...的 → sketchy粗略的"},{"word":"skilful","ipa":"/ˈskɪlfl/","pos":"adj.","def":"灵巧的，娴熟的","sen":"You're a very skilful juggler!","trans":"你是一个娴熟的（扔球）杂技人。","mne":""},{"word":"skill","ipa":"/skɪl/","pos":"n.","def":"技能；技巧；技巧，技术，能力","sen":"I have many skills - juggling balls is just one of them.","trans":"我有很多技能，杂耍球仅仅是其中之一。","mne":""},{"word":"skilled","ipa":"/skɪld/","pos":"adj.","def":"熟练的，有技能的","sen":"The man is skilled at dealing with all kinds of things.","trans":"这个男人可以熟练地处理各种事务。","mne":"skill技术 + ed有……的 → 有技术的 → 熟练的"},{"word":"skillful","ipa":"/ˈskɪlfl/","pos":"adj.","def":"娴熟的；灵巧的","sen":"They're very skillful skateboarders!","trans":"他们是技术极其娴熟的滑板运动员！","mne":"skill技术 + ful…的 → 有技术的 → skillful熟练的"},{"word":"skim","ipa":"/skɪm/","pos":"v.","def":"撇去；略读；掠过，滑过","sen":"There are 100 different ways to skim off the top.","trans":"有上百种不同的方法能够从中获利。","mne":""},{"word":"skin","ipa":"/skɪn/","pos":"n.","def":"【医】皮肤；兽皮，毛皮；皮，外皮；  v.剥皮","sen":"Exposure to the sun's ultraviolet rays can damage the skin and increase the risk of skin cancer.","trans":"暴露在太阳的紫外线下会损害皮肤，增加患皮肤癌的风险。","mne":""},{"word":"skirt","ipa":"/skɜːrt/","pos":"n.","def":"短裙；  v.位于……的边缘","sen":"She looks great in that skirt.","trans":"她穿那条短裙真好看。","mne":""},{"word":"sky","ipa":"/skaɪ/","pos":"n.","def":"天空","sen":"There are white clouds in the blue sky.","trans":"蓝蓝的天空中飘着白色的云朵。","mne":""},{"word":"slam","ipa":"/slæm/","pos":"v.","def":"砰地关上；猛烈抨击","sen":"He slams the door as he leaves.","trans":"他走的时候，砰的一声把门关上了。","mne":""},{"word":"slave","ipa":"/sleɪv/","pos":"n.","def":"奴隶；  v.奴隶般地工作，苦干","sen":"These slaves are chained together.","trans":"这几个奴隶被锁在了一起。","mne":""},{"word":"slavery","ipa":"/ˈsleɪvəri/ ","pos":"n.","def":"奴隶制；奴隶身份","sen":"Lincoln announced that slavery should be abolished.","trans":"林肯宣布奴隶制应被废除。","mne":"slav=slave奴隶 + ery表行为，身份 → slavery奴隶身份"},{"word":"sleep","ipa":"/sliːp/","pos":"n.","def":"【护】睡眠；  v.睡觉","sen":"Adequate sleep is essential for patient recovery.","trans":"充足的睡眠对患者的康复至关重要。","mne":""},{"word":"sleeve","ipa":"/sliːv/","pos":"n.","def":"袖子","sen":"In winter, I prefer shirts with long sleeves.","trans":"冬天，我比较喜欢穿长袖衬衫。","mne":""},{"word":"slice","ipa":"/slaɪs/","pos":"n.","def":"切片；薄片；份额，部分；  v.把……切成片","sen":"A thin slice of the tissue was examined under the microscope.","trans":"一小片组织切片在显微镜下进行了检查。","mne":""},{"word":"slide","ipa":"/slaɪd/","pos":"v.","def":"使滑动；滑落；  n.幻灯片；滑梯","sen":"You can slide your finger across the screen to unlock your phone.","trans":"你可以在屏幕上滑动手指来解锁你的手机。","mne":""},{"word":"slight","ipa":"/slaɪt/","pos":"adj.","def":"轻微的，微小的；纤细的，瘦弱的；少量的；  n.轻视，蔑视","sen":"There's a slight imperfection on this antique teapot.","trans":"这个古董茶壶上面有一个小瑕疵。","mne":""},{"word":"slightly","ipa":"/ˈslaɪtli/","pos":"adv.","def":"稍微，轻微地；略微","sen":"She is slightly taller than her brother.","trans":"她比她弟弟略微高一点。","mne":"slight轻微的 + ly ...地 →  些微地，轻微地；纤细地"},{"word":"slim","ipa":"/slɪm/","pos":"adj.","def":"苗条的；细长的；微小的","sen":"Ever since she started eating a healthy diet, she has had a very slim figure.","trans":"自从开始健康饮食，她的身材就变得很苗条了。","mne":""},{"word":"slip","ipa":"/slɪp/","pos":"v.","def":"滑倒，跌落；滑落；溜走；  n.溜走；滑倒；疏忽，小错误","sen":"The floor is wet—make sure you don't slip and fall.","trans":"地板很湿，请注意不要滑倒。","mne":""},{"word":"slippery","ipa":"/ˈslɪpəri/","pos":"adj.","def":"滑的；狡猾的","sen":"Watch out! The ground is slippery!","trans":"小心！地面很滑！","mne":"slip滑（重读闭音节，双写p） + er名词词尾 + y形容词词尾→ slippery滑的，使人滑跤的"},{"word":"slope","ipa":"/sloʊp/","pos":"n.","def":"斜坡；斜度；坡度；  v.倾斜；成斜坡","sen":"This little slope is for people in wheelchairs.","trans":"这个小斜坡是供坐轮椅的人使用的。","mne":""},{"word":"slow","ipa":"/sloʊ/","pos":"adj.","def":"缓慢的；迟钝的","sen":"The video loading speed is very slow.","trans":"视频加载速度很慢。","mne":""},{"word":"small","ipa":"/smɔːl/","pos":"adj.","def":"小的","sen":"This is a small model of my real house.","trans":"这是我房子的一个小模型。","mne":""},{"word":"smart","ipa":"/smɑːrt/","pos":"adj.","def":"聪明的，机灵的；时髦的，衣着讲究的；  v.难过，烦恼","sen":"The girl is so smart that she can solve very difficult physics problems.","trans":"这个女孩很聪明，她能解很难的物理题。","mne":""},{"word":"smell","ipa":"/smel/","pos":"n.","def":"气味；嗅觉；  v.嗅，闻（......的气味），闻到","sen":"The smell of this flower is so good.","trans":"这花的气味真是好闻。","mne":""},{"word":"smile","ipa":"/smaɪl/","pos":"v.","def":"微笑；  n.微笑","sen":"She smiled warmly at me.","trans":"她对我温暖地笑了。","mne":""},{"word":"smoke","ipa":"/smoʊk/","pos":"v.","def":"抽（烟）；冒烟；  n.抽烟","sen":"The man is smoking and blowing smoke into the air.","trans":"那个人正在抽烟，向空中吐烟。","mne":""},{"word":"smooth","ipa":"/smuːð/","pos":"adj.","def":"光滑的，平滑的；平稳的；  v.使......光滑；使......平稳","sen":"She said the taste of the chocolate is as smooth as silk. Give me some!","trans":"她说这种巧克力的口感如丝绸般柔滑，给我一点儿尝尝！","mne":""},{"word":"smuggle","ipa":"/ˈsmʌɡl/","pos":"v.","def":"走私；非法偷运","sen":"They often smuggle things at night.","trans":"他们常常在夜晚走私物品。","mne":""},{"word":"snack","ipa":"/snæk/","pos":"n.","def":"零食，小吃，快餐；点心","sen":"Besides snacks, this place has coffee.","trans":"除了小吃，这里还有咖啡。","mne":""},{"word":"snake","ipa":"/sneɪk/","pos":"n.","def":"蛇","sen":"This is a cute cartoon snake.","trans":"这是一条可爱的卡通蛇。","mne":""},{"word":"snow","ipa":"/snoʊ/  ","pos":"v.","def":"下雪；  n.雪","sen":"She opened the door and it was snowing outside.","trans":"小樱打开了大门，外面正飘着雪。","mne":""},{"word":"snowy","ipa":"/ˈsnəʊi/","pos":"adj.","def":"多雪的","sen":"Today is a snowy day, Children are building a snowman together","trans":"今天是个多雪的日子，小朋友们正在一起堆雪人","mne":"snow雪 + y形容词后缀 → snowy下雪的"},{"word":"so","ipa":"/soʊ/","pos":"adv.","def":"如此，这么，那么；  conj.所以；  adj.真的，事实如此的，如此的，整齐的","sen":"I am so late!","trans":"我太迟了。","mne":""},{"word":"so-called","ipa":"/ˌsoʊ ˈkɔːld/","pos":"adj.","def":"所谓的，号称的","sen":"They serve so-called Chinese food.","trans":"他们提供所谓的中国菜。","mne":"so用这种方式 + called称呼的 → so-called所谓的"},{"word":"soak","ipa":"/soʊk/","pos":"v.","def":"浸泡；吸收，吸入；  n.浸泡","sen":"Before cooking dried beans, don't forget to soak them in water for a few hours.","trans":"在烹饪干豆子之前，不要忘了将它们浸泡在水中几个小时。","mne":""},{"word":"soap","ipa":"/soʊp/","pos":"n.","def":"肥皂","sen":"I use a piece of soap to wash my hands.","trans":"我用肥皂洗手。","mne":""},{"word":"soar","ipa":"/sɔːr/","pos":"v.","def":"高飞，翱翔","sen":"It's wonderful to soar in the sky like a bird.","trans":"像小鸟一样在天空中翱翔真是太棒了。","mne":"s=ex向外 + oar空气 → 升至空中 → soar高飞"},{"word":"social","ipa":"/ˈsoʊʃl/ ","pos":"adj.","def":"社交的；社会的；  n.社交聚会","sen":"People chat and post things on social media platforms. ","trans":"人们在社交媒体上聊天和发照片。","mne":"soc社会 + ial形容词后缀 → 社会的"},{"word":"society","ipa":"/səˈsaɪəti/","pos":"n.","def":"社会；社团","sen":"In a modern society many people can live peacefully.","trans":"在现代社会中，许多人都可以和平地生活。","mne":"socie=social社会 + ty表名词 → society社会，社团"},{"word":"sociologist","ipa":"/ˌsoʊsiˈɑːlədʒɪst/","pos":"n.","def":"社会学家","sen":"Sociologists study the development of human society and human interactions.","trans":"社会学家研究人类社会的发展和人际交往。","mne":"soci=social社会的 ＋ ologist...学家 → sociologist社会学家"},{"word":"sock","ipa":"/sɑːk/","pos":"n.","def":"短袜","sen":"She is wearing socks of two different colors on her feet.","trans":"她脚上穿着两只不同颜色的袜子。","mne":""},{"word":"soda","ipa":"/ˈsoʊdə/","pos":"n.","def":"苏打水，汽水","sen":"Soda water is good for your health.","trans":"苏打水对健康有好处。","mne":""},{"word":"sofa","ipa":"/ˈsoʊfə/","pos":"n.","def":"（长）沙发","sen":"She lies on the sofa, reading a book.","trans":"她躺在沙发上看书。","mne":""},{"word":"soft","ipa":"/sɔːft/  ","pos":"adj.","def":"软的，柔软的；细嫩的，光滑的；  n.柔软的东西；  adv.柔软地，柔和地","sen":"This material looks so soft.","trans":"这种材质看起来很柔软。","mne":""},{"word":"software","ipa":"/ˈsɔftwer/","pos":"n.","def":"软件","sen":"I have a lot of software on my smart phone.","trans":"我手机上装了很多软件。","mne":"soft软的 + ware物件 → software软件"},{"word":"soil","ipa":"/sɔɪl/","pos":"n.","def":"泥土，土壤","sen":"He is holding some soil in his hands.","trans":"他手里捧着一些泥土。","mne":""},{"word":"soldier","ipa":"/ˈsoʊldʒər/","pos":"n.","def":"士兵，军人","sen":"The soldier stands on the watchtower looking into the distance.","trans":"士兵站在瞭望塔上眺望远方。","mne":""},{"word":"sole","ipa":"/soʊl/","pos":"n.","def":"脚底，鞋底，袜底；  adj.独有的","sen":"She is having the sole of her foot massaged.","trans":"她正在按摩足底。","mne":"sol单独 ＋ e → sole单独的，唯一的"},{"word":"solemn","ipa":"/ˈsɑːləm/","pos":"adj.","def":"严肃的；庄严的，隆重的","sen":"He gave a salute with a solemn expression.","trans":"他在敬礼时，脸上神情严肃。","mne":"sol全部 + emn=ann年  → 每年都发生的（节日） → solemn庄重的，隆重的"},{"word":"solid","ipa":"/ˈsɑːlɪd/","pos":"adj.","def":"坚固的；固体的；可靠的；  n.立方体；固体","sen":"This turtle’s shell is solid enough to protect itself.","trans":"这个乌龟(龙龟)的背壳相当坚硬，足以保护她自己。","mne":""},{"word":"solution","ipa":"/səˈluːʃən/","pos":"n.","def":"解决办法；答案，解答；溶液；溶解","sen":"I think the other plan is a better solution.","trans":"我觉得另一个方案是更好的解决办法。","mne":"solut解开；溶解 + ion名词后缀，构成抽象名词 → 溶解；解决"},{"word":"solve","ipa":"/sɑːlv/","pos":"v.","def":"解决，处理","sen":"He helped the girl solve the math problem.","trans":"他帮女孩解答了这道数学题。","mne":"so反身代词 + lv松开，分开 + e → solve解决"},{"word":"some","ipa":"/sʌm/","pos":"det.","def":"一些，某些","sen":"The woman is putting some sugar in her coffee.","trans":"女人正往她的咖啡里加入一些糖。","mne":""},{"word":"somebody","ipa":"/ˈsʌmbədi/","pos":"pron.","def":"某人","sen":"Somebody sends me the flowers, but I don't know who he is.","trans":"某人给我送了花，可是我不知道他是谁。","mne":"some有些 + body人 → somebody某人，有人"},{"word":"somehow","ipa":"/ˈsʌmhaʊ/","pos":"adv.","def":"出于某种原因，不知怎么地；以某种方式","sen":"He looked different somehow.","trans":"不知怎么的，他看上去变了。","mne":""},{"word":"someone","ipa":"/ˈsʌmwʌn/","pos":"pron.","def":"有人，某人","sen":"Someone left the pen on the desk.","trans":"有人把笔落在桌上了。","mne":"some某些 + one一个 → someone某人"},{"word":"someplace","ipa":"/ˈsʌmpleɪs/","pos":"adv.","def":"在某处","sen":"His playmates are planning to hide someplace.","trans":"他的玩伴正打算躲到某处去。","mne":""},{"word":"something","ipa":"/ˈsʌmθɪŋ/","pos":"pron.","def":"某事物","sen":"Here, there is something in the box for you.","trans":"给，盒子里有给你的一些东西。","mne":"some有些 + thing事 → 一些事情 → something某事，某物"},{"word":"sometime","ipa":"/ˈsʌmtaɪm/","pos":"adv.","def":"在某一时候；  adj.以前的","sen":"Although I failed the exam, I believe that I will make it sometime.","trans":"虽然我考试失败了，但我相信总有一天我会成功的。","mne":"some某 + time时间 → sometime在某一时侯"},{"word":"sometimes","ipa":"/ˈsʌmtaɪmz/","pos":"adv.","def":"有时，间或","sen":"Sometimes, the weather will change every day.","trans":"有的时候，天气每天都在变。","mne":"sometime某一时间的 ＋ s表副词 → 某一时间 → sometimes有时"},{"word":"somewhat","ipa":"/ˈsʌmwʌt/","pos":"adv.","def":"有点儿，稍微","sen":"The old-style restaurant is somewhat pricier than the street ones.","trans":"这家老字号饭店的价格比街边饭店的稍贵。","mne":""},{"word":"somewhere","ipa":"/ˈsʌmwer/","pos":"adv.","def":"某处，某地","sen":"My pen must be somewhere in this classroom.","trans":"我的笔一定在教室的某个地方。","mne":"some某个 + where哪里 → somewhere在某处"},{"word":"son","ipa":"/sʌn/","pos":"n.","def":"儿子","sen":"My son is so cute!","trans":"我儿子真可爱！","mne":""},{"word":"song","ipa":"/sɔːŋ/","pos":"n.","def":"歌曲","sen":"We all sang a song together on New Year's Day.","trans":"在元旦我们一起唱了一首歌。","mne":""},{"word":"soon","ipa":"/suːn/","pos":"adv.","def":"立刻，不久；很快，马上","sen":"It'll soon be the New Year.","trans":"马上就到新年了。","mne":""},{"word":"sophisticated","ipa":"/səˈfɪstɪkeɪtɪd/","pos":"adj.","def":"精密的；复杂的；老练的","sen":"This machine is quite sophisticated.","trans":"这台机器是非常精密的。","mne":"soph智慧 + istic……的 + at＝ate做，造成 + ed……的 → 有智慧的 → sophisticated老于世故的，精致复杂的"},{"word":"sore","ipa":"/sɔːr/","pos":"adj.","def":"疼痛的，酸痛的；恼火的；  n.痛处","sen":"Ugh! My back feels so sore!","trans":"啊！我的背好酸啊！","mne":""},{"word":"sorrow","ipa":"/ˈsɔːrəʊ/","pos":"n.","def":"悲伤；伤心事","sen":"Her tears are full of sorrow.","trans":"她的眼泪充满悲伤。","mne":""},{"word":"sorrowful","ipa":"/ˈsɑːroʊfl/","pos":"adj.","def":"充满悲伤的，悲哀的，伤心的","sen":"The girl by the window looked very sorrowful.","trans":"窗边的女孩看起来充满悲伤。","mne":"sorrow悲伤 + ful形容词后缀 → sorrowful悲哀的"},{"word":"sorry","ipa":"/ˈsɑːri/","pos":"adj.","def":"抱歉的，歉疚的；  int.对不起，很抱歉","sen":"I'm sorry I called you fat - you're hardly fat at all, please forgive me!","trans":"很抱歉我说你胖，你一点都不胖，请原谅我！","mne":""},{"word":"sort","ipa":"/sɔːrt/","pos":"v.","def":"把……分类，整理，挑选；  n.种类，类别","sen":"I sorted the books into piles of big ones and small ones.","trans":"我将书按大小分成了几摞。","mne":""},{"word":"soul","ipa":"/soʊl/","pos":"n.","def":"灵魂","sen":"Piano and drum are the core musical instruments in soul music.","trans":"钢琴和鼓是灵魂乐的核心乐器。","mne":""},{"word":"sound","ipa":"/saʊnd/","pos":"n.","def":"声音，声响；  v.听起来；  adj.健全的，完好的；合理的；可靠的","sen":"The sound coming from the speakers was very loud.","trans":"喇叭里传出来的声音很大。","mne":""},{"word":"soup","ipa":"/suːp/","pos":"n.","def":"汤","sen":"This is a bowl of chicken soup.","trans":"这是一碗鸡汤。","mne":""},{"word":"source","ipa":"/sɔːrs/","pos":"n.","def":"来源；出处；河的源头；知情人士，提供消息者","sen":"The lake is the source of the river.","trans":"这片湖是这条河的发源地。","mne":"sou=sub从下往上 + rce引导 → source来源；出处"},{"word":"south","ipa":"/saʊθ/","pos":"n.","def":"南；南方；  adj.南方的，南部的；  adv.向南方，在南方","sen":"Penguins live in the far south.","trans":"企鹅生活在遥远的南方。","mne":""},{"word":"southern","ipa":"/ˈsʌðərn/","pos":"adj.","def":"南部的，南方的","sen":"He lives in the southern part of the city.","trans":"他住在城市的南边。","mne":"south南 + ern...方向的 → 南方的"},{"word":"souvenir","ipa":"/ˈsuːvənɪr/ /ˈsuːvənɪr/","pos":"n.","def":"纪念品","sen":"I bought a handmade bell as a souvenir for my friend.","trans":"我给朋友买了一个手工铃铛作为纪念品。","mne":""},{"word":"sow","ipa":"/soʊ/","pos":"v.","def":"播种；种；散布","sen":"He is sowing seeds into the soil.","trans":"他正在往土里播种。","mne":""},{"word":"space","ipa":"/speɪs/","pos":"n.","def":"【护】空间；外层空间，太空","sen":"In nursing, it's important to maintain personal space.","trans":"在护理中，保持个人空间非常重要。","mne":""},{"word":"spacecraft","ipa":"/ˈspeɪskræft/ ","pos":"n.","def":"宇宙飞船；航天器","sen":"The spacecraft is used to explore the unknown area in space.","trans":"宇宙飞船是用来探索宇宙中的未知区域的。","mne":"space宇宙 + craft小船 → spacecraft航天器，宇宙飞船"},{"word":"spade","ipa":"/speɪd/","pos":"n.","def":"铁锹；黑桃（扑克）","sen":"He used a spade to dig a hole for the new tree.","trans":"他用铁锹挖了个坑来种新树。","mne":""},{"word":"span","ipa":"/spæn/","pos":"n.","def":"跨度；时间段；持续时间；小范围，短距离；  v.持续，贯穿（时间）；横跨；包括","sen":"The bridge's span is about half a kilometer.","trans":"这座大桥的跨距大约是500米。","mne":""},{"word":"spare","ipa":"/sper/","pos":"adj.","def":"备用的；多余的，空闲的；瘦的；  n.备用品；  v.抽出，腾出","sen":"Prepare a spare pen for your exam.","trans":"为考试准备一支备用的笔。","mne":""},{"word":"sparingly","ipa":"/ˈsperɪŋli/","pos":"adv.","def":"节俭地，有节制地","sen":"One way of becoming rich is to spend money sparingly.","trans":"一个致富方式就是节俭开支。","mne":""},{"word":"spark","ipa":"/spɑːrk/","pos":"n.","def":"火花，火星；  v.发出火花","sen":"There are many sparks coming out during the work.","trans":"在作业时有很多火星飞溅出来。","mne":""},{"word":"speak","ipa":"/spiːk/","pos":"v.","def":"说话，谈及；发言，演讲","sen":"When he speaks, everybody else listens carefully.","trans":"他说话的时候别人都在认真地听。","mne":""},{"word":"special","ipa":"/ˈspeʃl/","pos":"adj.","def":"特别的；附加的，额外的","sen":"Their wedding anniversary was a very special day to them.","trans":"结婚纪念日对他们来说是特别的一天。","mne":"speci种类 + al…的 → 比其他种类好的 → special特别的"},{"word":"specialisation","ipa":"/sˌpɛʃəlɪˈzeɪʃən/","pos":"n.","def":"【财】专业化","sen":"Excessive specialisation isolates the individual in his or her work and inhibits not only social contacts with work mates, but knowledge generation.","trans":"过度的专业化使个人在工作中孤立无援，不仅阻碍了与同事的社会交往，也阻碍了知识的创造。","mne":""},{"word":"specialise","ipa":"/ˈspeʃəlaɪz/","pos":"v.","def":"专门从事，专攻","sen":"We specialise in studying the characteristics of different plants.","trans":"我们专门研究不同植物的特性。","mne":"special特别的 + ise动词后缀 → specialise专门研究"},{"word":"specialist","ipa":"/ˈspeʃəlɪst/","pos":"n.","def":"专科医生；专家","sen":"They are the specialists in our hospital.","trans":"他们是我们医院的专家。","mne":"special特别的 + ist表示人 → 特殊的人，有特别专长的人 → specialist专家"},{"word":"specialization","ipa":"/ˌspɛʃələˈzeɪʃən/","pos":"n.","def":"专业性，专业化","sen":"The scientist's specialization is in physics.","trans":"这个科学家的特长是物理。","mne":"special特殊的 + ization……化 → specialization特殊化"},{"word":"specialize","ipa":"/ˈspɛʃəˌlaɪz/","pos":"v.","def":"专门研究，专门从事","sen":"The store specializes in selling hiking gear.","trans":"这家店专门卖登山设备。","mne":"special特别的 + ize……化 → 特殊化"},{"word":"specially","ipa":"/ˈspeʃəli/","pos":"adv.","def":"专门地；特别地","sen":"The door was specially made for the giraffe.","trans":"这个门是专门为长颈鹿做的。","mne":"special特别的 + ly副词后缀 → specially特别地，专门地"},{"word":"species","ipa":"/ˈspiːʃiːz/ ","pos":"n.","def":"种类；物种","sen":"There are tens of thousands of different species of birds in the world.","trans":"世界上有数万种各不相同的鸟。","mne":"speci外观 +es → species物种"},{"word":"specific","ipa":"/spəˈsɪfɪk/","pos":"adj.","def":"具体的；明确的；特定的","sen":"The teacher asked for a specific example to illustrate the concept.","trans":"老师要求举一个具体的例子来说明这个概念。","mne":"speci种类 + fic制造，做 → 做某种东西 → specific具体的"},{"word":"specification","ipa":"/ˌspesɪfɪˈkeɪʃn/","pos":"n.","def":"规格","sen":"The product does not match the specification listed on your website.","trans":"产品与你们网站上列出的规格不符。","mne":"specific具体的 + ation表名词 → specification具体说明"},{"word":"specify","ipa":"/ˈspesɪfaɪ/","pos":"v.","def":"详细说明","sen":"If you want to achieve your goals, it's important to specify them clearly.","trans":"如果你想达到目标，清晰详细地说明这些目标很重要。","mne":"speci外观，种类+ fy表动词 → 归类 →  指定，详细说明"},{"word":"specimen","ipa":"/ˈspesɪmən/","pos":"n.","def":"标本；样本，样品","sen":"This exhibit contains various specimens of butterfly.","trans":"这件展览品中包含了各种蝴蝶标本。","mne":"speci仔细看 + men人 → 需要人仔细观察的东西 → specimen样本"},{"word":"spectator","ipa":"/ˈspekteɪtər/","pos":"n.","def":"观众；旁观者","sen":"Thousands of spectators watched the tennis match.","trans":"成千上万的观众观看了这场网球比赛。","mne":"spect看 + ator名词后缀：人 → 看的人 → spectator观众"},{"word":"speculate","ipa":"/ˈspekjuleɪt/","pos":"v.","def":"推测，猜测；投机，做投机买卖","sen":"He speculated about future trends in the stock market.","trans":"他推测了股市的未来趋势。","mne":"specul环顾 + ate动词后缀 → 看准了 → speculate思考，投机"},{"word":"speech","ipa":"/spiːtʃ/","pos":"n.","def":"演说，讲话，发言","sen":"The public speaker looks confident during his speech.","trans":"这位发言人在他演讲时看上去胸有成竹。","mne":""},{"word":"speechless","ipa":"/ˈspiːtʃləs/","pos":"adj.","def":"无语的","sen":"She was speechless after seeing the countdown of the pop-up ad.","trans":"在看到广告倒计时后，她无语了。","mne":""},{"word":"speed","ipa":"/spiːd/","pos":"n.","def":"速度，速率；  v.加速","sen":"The train is traveling at a speed of 300 km/h.","trans":"列车的运行速度是每小时300千米。","mne":""},{"word":"spell","ipa":"/spel/","pos":"v.","def":"拼写；招致；意味着；  n.一段时间；魅力","sen":"Sometimes we can play word games to learn how to spell.","trans":"有时候我们能通过玩拼字游戏来学会拼写。","mne":""},{"word":"spelling","ipa":"/ˈspelɪŋ/","pos":"n.","def":"拼写；拼法","sen":"The spelling of that word is so easy. B-O-Y, boy!","trans":"那个单词的拼写很简单，B-O-Y，boy！","mne":"spell拼写 + ing名词后缀 → spelling拼写法，拼法"},{"word":"spend","ipa":"/spend/","pos":"v.","def":"花费，用钱；度过，消磨","sen":"I spend too much money on clothes!","trans":"我在买衣服上花了太多的钱。","mne":""},{"word":"spending","ipa":"/ˈspendɪŋ/","pos":"n.","def":"支出，花销","sen":"The girl is planning her spending in detail.","trans":"这个女孩正在详细计划她的开支。","mne":""},{"word":"sphere","ipa":"/sfɪr/","pos":"n.","def":"球；领域","sen":"The world is not flat; it is a sphere.","trans":"世界不是平的，而是一个球体。","mne":""},{"word":"spill","ipa":"/spɪl/","pos":"v.","def":"使流出，涌流；（人群）涌出；  n.溢出，溅出","sen":"Oh no! I've spilled the green nail polish.","trans":"哦不！我把这瓶绿色的指甲油弄洒了。","mne":""},{"word":"spin","ipa":"/spɪn/","pos":"v.","def":"（使）旋转；疾驰；纺织；  n.高速旋转","sen":"The top spins across the floor.","trans":"陀螺在地板上旋转。","mne":""},{"word":"spirit","ipa":"/ˈspɪrɪt/","pos":"n.","def":"精神，心灵；情绪；烈酒（spirits）；灵魂；  v.（秘密地或神秘地）带走","sen":"The dove with olive branch symbol captures the spirit of peace and friendship.","trans":"鸽子衔橄榄枝的标志象征和平友爱的精神。","mne":"spir呼吸 + it名词 → spirit精神"},{"word":"spiritual","ipa":"/ˈspɪrɪtʃuəl/","pos":"adj.","def":"精神（上）的","sen":"Watching the sun set peacefully was a spiritual experience.","trans":"平静地看着太阳落下是一种很好的精神体验。","mne":"spirit精神 + ual形容词后缀  → spiritual精神的"},{"word":"spite","ipa":"/spaɪt/","pos":"n.","def":"恶意，怨恨；  v.刁难，欺侮","sen":"The dog peed on his master's bed out of spite.","trans":"出于怨恨，这只狗尿在了主人的床上。","mne":""},{"word":"splash","ipa":"/splæʃ/","pos":"v.","def":"泼洒，溅，使成斑驳状","sen":"The man's dancing makes the water splash everywhere.","trans":"世勋跳起舞来水花四溅。","mne":""},{"word":"splendid","ipa":"/ˈsplendɪd/","pos":"adj.","def":"壮观的，辉煌的，华丽的；极好的，出色的","sen":"The palace looks really splendid at night.","trans":"这座宫殿在夜晚看起来格外壮丽。","mne":"splend光辉 + id形容词后缀 → splendid辉煌的，华丽的"},{"word":"split","ipa":"/splɪt/","pos":"n.","def":"裂缝；劈裂，劈开；碎片；  v.分开","sen":"There's a split on the wall.","trans":"墙上有一条裂缝。","mne":""},{"word":"spoil","ipa":"/spɔɪl/","pos":"v.","def":"溺爱；毁坏；  v.（食物）变质；  n.战利品，赃物","sen":"The grandparents spoil their grandchild by doing everything for him.","trans":"爷爷奶奶太宠他们的孙子了，恨不得替他把所有事都做了。","mne":""},{"word":"sponsor","ipa":"/ˈspɑːnsər/","pos":"n.","def":"赞助商；  v.赞助；主办","sen":"The sponsors are threatening to rip up their contracts!","trans":"赞助商威胁要取消合约！","mne":""},{"word":"spontaneous","ipa":"/spɑːnˈteɪniəs/","pos":"adj.","def":"【财】自发的","sen":"Remote work during the pandemic, which took away opportunities to have spontaneous discussions, led to meeting creep.","trans":"在疫情期间的远程工作，由于无法进行自发讨论，导致了会议的过度增多。","mne":"spont=spond承诺 + aneous表形容词 → 自内心承诺 → 自愿的"},{"word":"spoon","ipa":"/spuːn/","pos":"n.","def":"勺","sen":"Could you please pass me the spoon?","trans":"你能把勺子递给我吗？","mne":""},{"word":"sport","ipa":"/spɔːrt/","pos":"n.","def":"运动","sen":"He can play various sports.","trans":"他擅长多种运动。","mne":"s远离 + port带走，越过 → 不思考严肃的问题 → sport运动，娱乐"},{"word":"sportsman","ipa":"/ˈspɔːrtsmən/","pos":"n.","def":"运动员","sen":"Your father was quite a sportsman in his younger days.","trans":"你父亲年轻的时候是个运动健将。","mne":"sports运动 + man人 → sportsman运动员"},{"word":"spot","ipa":"/spɑːt/","pos":"n.","def":"点，斑点；（通常为圆形的）斑点，斑块；污点；  v.看见，注意到，发现","sen":"This type of dog has many black spots.","trans":"这种狗的身上有很多黑色的斑点。","mne":""},{"word":"spouse","ipa":"/spaʊs/","pos":"n.","def":"配偶，夫妇；  v.和…结婚","sen":"The young spouses planned to travel abroad.","trans":"这对年轻夫妇计划去国外旅行。","mne":""},{"word":"spray","ipa":"/spreɪ/","pos":"n.","def":"喷雾；  v.喷洒","sen":"The girl uses a pepper spray to protect herself.","trans":"女孩用辣椒水喷雾来防身。","mne":""},{"word":"spread","ipa":"/spred/","pos":"v.","def":"抹，敷；伸开，伸展；  n.散布，传播","sen":"I like to spread butter on the bread before making a sandwich.","trans":"做三明治之前，我喜欢在面包上涂点黄油。","mne":""},{"word":"spring","ipa":"/sprɪŋ/","pos":"n.","def":"春天；弹簧；泉，泉源；  v.反弹，跳，跃","sen":"In China, the flying swallows are the sign of spring.","trans":"在中国，飞燕是春天的标志。","mne":""},{"word":"spur","ipa":"/spɜːr/","pos":"v.","def":"激励，鞭策","sen":"My colleagues always spur me to work harder.","trans":"我的同事们经常激励我工作更努力。","mne":""},{"word":"spy","ipa":"/spaɪ/","pos":"v.","def":"暗中监视（或侦察）；发现；  n.间谍，密探","sen":"The man was hiding in the bush to spy on them.","trans":"这个男人正躲在灌木丛里监视他们。","mne":""},{"word":"square","ipa":"/skwer/","pos":"n.","def":"广场；正方形；  v.把……弄成正方形；  adj.正方形的；直角的；平方的","sen":"This square is a nice, quiet place to take a walk.","trans":"这个广场安静宜人，是个散步的好地方。","mne":""},{"word":"squeeze","ipa":"/skwiːz/","pos":"v.","def":"（常指用手）挤压；挤进，塞进；  n.压榨","sen":"She squeezes the toothpaste onto the toothbrush.","trans":"她把牙膏挤到牙刷上。","mne":""},{"word":"stabilise","ipa":"/'steɪblˌaɪz/","pos":"v.","def":"(使)稳定","sen":"A student placed sandbags to stabilise the display board before the presentation.","trans":"一名学生在展示前放置沙袋使展板稳固。","mne":""},{"word":"stability","ipa":"/stəˈbɪlɪti/","pos":"n.","def":"稳定，稳定性","sen":"Walking a tightrope requires extreme stability.","trans":"走钢丝需要极强的稳定性。","mne":"st=stable稳定的 + ability能力 → stability稳定性"},{"word":"stabilize","ipa":"/ˈsteɪbəlaɪz/","pos":"v.","def":"（使）稳定","sen":"The meat prices stabilized after a volatile first half of the year.","trans":"经历上半年的动荡之后，肉类价格稳定了下来。","mne":"stabil=stable稳定的 + ize使成为… → stabilize（使）稳定，（使）稳固"},{"word":"stable","ipa":"/ˈsteɪbl/","pos":"adj.","def":"稳定的；安定的；稳重的；  n.马厩","sen":"The price finally became stable after some ups and downs.","trans":"物价在一阵起伏后终于变稳定了。","mne":"st站立 + able能…的 → 能站的 → stable稳定的"},{"word":"staff","ipa":"/stæf/","pos":"n.","def":"工作人员，全体职员；拐杖；  v.为……配备职员","sen":"The doctors and nurses are important members of the hospital staff.","trans":"医生和护士都是重要的医院职员。","mne":""},{"word":"stage","ipa":"/steɪdʒ/","pos":"n.","def":"舞台；阶段；  v.举行；上演","sen":"The students are playing music on the stage.","trans":"学生们正在舞台上演奏音乐。","mne":"sta表示“站，立” + ge表名词 → stage舞台；戏剧；阶段"},{"word":"stagger","ipa":"/ˈstæɡər/","pos":"v.","def":"蹒跚；  n.蹒跚","sen":"The old woman staggered toward the hospital.","trans":"老妇人蹒跚地走向医院。","mne":""},{"word":"stagnant","ipa":"/ˈstæɡnənt/","pos":"adj.","def":"不流动的；停滞的","sen":"The stagnant pond is covered by algae.","trans":"死水池塘被藻类所覆盖。","mne":"stagn站 + ant形容词后缀 → 站着不走 → 停滞的"},{"word":"stain","ipa":"/steɪn/","pos":"n.","def":"污渍，污迹；  v.弄脏；玷污；染色","sen":"Oh dear! Look at that big red stain on his shirt.","trans":"天哪！看他衬衫上那一大块红色的污渍。","mne":""},{"word":"stair","ipa":"/ster/","pos":"n.","def":"楼梯；梯级","sen":"The stairs ascend in a graceful curve.","trans":"这个楼梯呈优美的曲线上升。","mne":""},{"word":"stamp","ipa":"/stæmp/","pos":"n.","def":"印，章；邮票；跺脚；  v.盖印；跺脚","sen":"The stamp on the pig shows the acceptable quality of it.","trans":"猪身上盖的章表示猪的质量合格。","mne":""},{"word":"stand","ipa":"/stænd/","pos":"v.","def":"站立；忍受","sen":"My dog can stand on two feet and she can even put on her own shoes!","trans":"我的狗能双脚站立，它甚至能自己穿鞋！","mne":""},{"word":"standard","ipa":"/ˈstændərd/","pos":"n.","def":"标准，规格；  adj.标准的，规范的","sen":"Passport photos have strict standards.","trans":"护照照片有着严格的标准。","mne":"stand站立 + ard=hard坚硬的 → standard标准"},{"word":"standardisation","ipa":"/ˌstændədaɪ'zeɪʃən/","pos":"n.","def":"标准化","sen":"Standardisation makes the workspace organized.","trans":"标准化让工作空间变得井然有序。","mne":""},{"word":"standardise","ipa":"/'stændədˌaɪz/","pos":"v.","def":"使标准化；使合标准","sen":"We should standardise the testing process.","trans":"我们应该把测试流程标准化。","mne":""},{"word":"standardization","ipa":"/ˌstændərdəˈzeɪʃn/","pos":"n.","def":"标准化","sen":"The standardization of education means that every child has the same education.","trans":"教育标准化意味着每个孩子都能接受同样的教育。","mne":""},{"word":"standardize","ipa":"/ˈstændərdaɪz/","pos":"v.","def":"使标准化；使合乎标准","sen":"The factory standardized the shape of the products on the conveyor belt.","trans":"工厂对传送带上的产品的形状进行标准化加工。","mne":"standard标准 + ize使成为 → 使标准化"},{"word":"standpoint","ipa":"/ˈstændpɔɪnt/","pos":"n.","def":"观点，立场","sen":"The two ministers held conflicting standpoints on war issue.","trans":"两位大臣在战争问题上持有相反的观点。","mne":"stand立 + point点 → standpoint立场，观点"},{"word":"star","ipa":"/stɑːr/","pos":"n.","def":"星，恒星；明星，名角；  v.主演","sen":"There are many happy stars.","trans":"这里有很多快乐的星星。","mne":""},{"word":"stare","ipa":"/ster/","pos":"v.","def":"盯，凝视；  n.注视","sen":"She secretly stared at others from behind the window.","trans":"她在窗户后面偷偷地盯着别人。","mne":""},{"word":"start","ipa":"/stɑːrt/","pos":"v.","def":"开始（做某事）；  n.开始","sen":"With so much homework to do, I'd better get started right now!","trans":"有那么多作业要做，我最好马上就开始！","mne":""},{"word":"starvation","ipa":"/stɑːrˈveɪʃn/","pos":"n.","def":"饥饿","sen":"The drought resulted in the starvation of many animals.","trans":"干旱导致许多动物挨饿。","mne":"starv使挨饿 + ation名词后缀 → starvation饥饿"},{"word":"starve","ipa":"/stɑːrv/","pos":"v.","def":"挨饿；饿死","sen":"This polar bear is starving because it doesn't have enough food to eat.","trans":"这只北极熊快饿死了，因为它没有足够的食物吃。","mne":""},{"word":"state","ipa":"/steɪt/","pos":"n.","def":"【化】状态；国家，政府；州，邦；  v.说明，陈述；  adj.国家的，州的，邦的","sen":"The state of an atom in a molecule refers to its electron configuration.","trans":"分子中原子的状态是指其电子配置。","mne":"stat站立 + e强调 → state国家，状态"},{"word":"statement","ipa":"/ˈsteɪtmənt/ ","pos":"n.","def":"声明；陈述","sen":"The company made a statement confirming that the couple would be fired.","trans":"这家公司发表声明，确定这对情侣将被辞退。","mne":"state陈述 + ment表名词 → 站着说话 → statement声明立场"},{"word":"static","ipa":"/ˈstætɪk/","pos":"adj.","def":"静电的；静态的；静止的；  n.静电，静电干扰","sen":"Her hair was full of static electricity.","trans":"她头发上的静电很强。","mne":"stat站 + ic...的 → static静止的"},{"word":"station","ipa":"/ˈsteɪʃn/","pos":"n.","def":"车站","sen":"The train at the station is about to leave.","trans":"车站里停着的火车快要出发了。","mne":"sta=stand站 + tion表名词 → (车)站，台"},{"word":"statistic","ipa":"/stəˈtɪstɪk/","pos":"n.","def":"统计数值","sen":"These statistics can help analyze the stock market.","trans":"这些数据有助于分析股市。","mne":"stat站 + istic名词后缀，学科 → 站着去计算数据的学科 → statistic统计学"},{"word":"statistical","ipa":"/stəˈtɪstɪkl/","pos":"adj.","def":"统计的，统计学的","sen":"The statistical data shows that most people cannot afford a house.","trans":"这项统计数据表明大多数人买不起房子。","mne":"stat站，立 + istical……的 → 统计的，统计学的"},{"word":"statue","ipa":"/ˈstætʃuː/","pos":"n.","def":"雕像；雕塑；雕像；塑像","sen":"The angel statue is carved out of stone.","trans":"这座天使雕像由石头雕刻而成。","mne":""},{"word":"status","ipa":"/ˈsteɪtəs/, /ˈstætəs/","pos":"n.","def":"地位；身份；状态","sen":"Cats held a high status in ancient Egypt.","trans":"猫在古埃及有很高的地位。","mne":"stat站着 + us名词后缀 → 站着 → status地位"},{"word":"stay","ipa":"/steɪ/","pos":"v.","def":"保持；继续是；  n.停留，逗留 ；逗留，延缓","sen":"Some shops stay open 24 hours a day.","trans":"一些商店24小时营业。","mne":""},{"word":"steady","ipa":"/ˈstedi/","pos":"adj.","def":"坚定的，扎实的；稳定的，平稳的；稳重的，可靠的","sen":"The stone house is quite steady under the extreme weather.","trans":"石屋在极端天气下非常稳固。","mne":"stead稳定 + y表形容词  → steady坚定的"},{"word":"steal","ipa":"/stiːl/","pos":"v.","def":"偷盗，窃取","sen":"The thief is trying to steal his wallet.","trans":"小偷正试图偷他的钱包。","mne":""},{"word":"steam","ipa":"/stiːm/","pos":"n.","def":"蒸汽，水蒸气；  v.蒸","sen":"Steam is coming from the pot. Turn off the stove!","trans":"水蒸气正在往锅外冒，关火吧！","mne":""},{"word":"steamer","ipa":"/ˈstiːmər/","pos":"n.","def":"蒸锅","sen":"These yummy baozi are being cooked in the steamer. ","trans":"美味的包子在蒸笼里蒸着。","mne":"steam蒸汽 + er名词后缀 → 汽船"},{"word":"steel","ipa":"/stiːl/","pos":"n.","def":"钢，钢铁","sen":"Steel can be used to reinforce concrete in the construction of buildings.","trans":"在建造房屋时，钢铁可以用于加固混凝土。","mne":""},{"word":"steep","ipa":"/stiːp/","pos":"adj.","def":"急剧的；陡峭的；  v.浸，泡","sen":"There was a steep rise in prices.","trans":"价格急剧上涨。","mne":""},{"word":"steer","ipa":"/stɪr/","pos":"v.","def":"驾驶；控制，引导；掌握方向盘，掌舵","sen":"Be cautious when you steer a car.","trans":"驾驶时，请务必谨慎。","mne":""},{"word":"stem","ipa":"/stem/","pos":"n.","def":"茎，（树）干；  v.阻止；起源于","sen":"The boy is climbing along the stem to reach the clouds.","trans":"爬上花茎，男孩儿就可以触摸到云朵了。","mne":""},{"word":"step","ipa":"/step/","pos":"n.","def":"脚步，脚步声；步骤，阶段；台阶；步伐；  v.踩；走，举步","sen":"He's so excited to see his baby girl take her first step.","trans":"看到他的宝贝女儿迈出第一步，他激动极了。","mne":""},{"word":"stereo","ipa":"/ˈsterioʊ/","pos":"n.","def":"立体声（装置）；  adj.立体声的","sen":"You must listen to the song in stereo to really appreciate the music.","trans":"你一定要用立体声设备听歌，这样才能真正地欣赏音乐。","mne":""},{"word":"stereotype","ipa":"/ˈsteriətaɪp/","pos":"n.","def":"刻板印象；老套的模式，陈规","sen":"There is a stereotype about successful business man: dark suit and fancy watch.","trans":"人们对于成功商人有种刻板印象：深色西装和昂贵的手表。","mne":"stereo立体 + type模式 → stereotype陈规，老套"},{"word":"stick","ipa":"/stɪk/","pos":"v.","def":"粘贴；刺，戳，扎；  n.棍，棒，条","sen":"The woman is sticking a paper-cut on the window.","trans":"这位女士正将一张剪纸贴在窗户上。","mne":""},{"word":"sticky","ipa":"/ˈstɪki/","pos":"adj.","def":"黏的，黏糊糊的","sen":"The glue on her hand is so sticky.","trans":"她手上的胶水好黏啊。","mne":"stick粘，粘 + y…的 → sticky粘性的"},{"word":"stiff","ipa":"/stɪf/","pos":"adj.","def":"僵直的，酸痛的","sen":"\"My back is so stiff!\" the athlete complained.","trans":"“我的背好酸痛啊！” 这位运动员抱怨道。","mne":""},{"word":"still","ipa":"/stɪl/","pos":"adv.","def":"还，仍；(虽然…）还是；  adj.静止的","sen":"He has been exercising for 3 months, but he still weighs over 90 kilograms.","trans":"他锻炼了三个月，但体重还是超过90公斤。","mne":""},{"word":"stimulate","ipa":"/ˈstɪmjuleɪt/","pos":"v.","def":"刺激（身体部位等）；激励，鼓舞","sen":"The onions stimulate my eyes to tear up.","trans":"洋葱刺激了我的眼睛使其流泪。","mne":"stimul刺激 + ate使 → stimulate刺激"},{"word":"sting","ipa":"/stɪŋ/","pos":"v.","def":"叮；刺；  n.（因被刺而引起的）疼痛；刺","sen":"A bee stung me on the arm and it really hurt!","trans":"一只蜜蜂叮了我的胳膊一下，真疼！","mne":""},{"word":"stir","ipa":"/stɜːr/","pos":"v.","def":"搅拌，搅动；激发（兴趣）","sen":"The lady is stirring the coffee.","trans":"这位女士正在搅拌咖啡。","mne":""},{"word":"stock","ipa":"/stɑːk/","pos":"n.","def":"股票；库存，存货清单；家畜；  v.储存；存货","sen":"Many types of stocks are displayed on the large screen.","trans":"大屏幕上显示着多种类型的股票。","mne":""},{"word":"stocking","ipa":"/ˈstɑːkɪŋ/","pos":"n.","def":"长（筒）袜","sen":"Stockings can be a great way to keep warm.","trans":"长筒袜可以起到很好的保暖作用。","mne":"stock树干，筒状物 + ing名词后缀 → stock腿 + ing名词后缀 → stocking长筒袜"},{"word":"stomach","ipa":"/ˈstʌmək/","pos":"n.","def":"胃，胃口；  v.吃得下；忍受","sen":"We should eat healthy food if we want a strong stomach.","trans":"想拥有强健的胃，我们就应该健康饮食。","mne":""},{"word":"stone","ipa":"/stoʊn/","pos":"n.","def":"石头","sen":"These stones come from a river and have been rounded by the water.","trans":"这些石头是从河里捞出来的，已经被流水打磨圆润了。","mne":""},{"word":"stop","ipa":"/stɑːp/","pos":"v.","def":"停止；阻止；  n.停止；车站","sen":"The road worker held up his hand to stop the car.","trans":"修路工人举手让车停下来。","mne":""},{"word":"storage","ipa":"/ˈstɔːrɪdʒ/","pos":"n.","def":"储存，储藏；仓库","sen":"The huge refrigerator has lots of storage space!","trans":"这台大冰箱有很多储存空间！","mne":"stor=store保存 + age行为 → 贮存，保管"},{"word":"store","ipa":"/stɔr/","pos":"n.","def":"商店；仓库；储存品；  v.贮藏，储存，积蓄","sen":"I took my son to the grocery store to buy some food.","trans":"我带着儿子去杂货店买了一些食物。","mne":""},{"word":"storey","ipa":"/ˈstɔːri/","pos":"n.","def":"层，楼层","sen":"This is a six-storey apartment.","trans":"这是一个六层的公寓。","mne":""},{"word":"storm","ipa":"/stɔːrm/","pos":"n.","def":"暴风雨，暴风雪","sen":"Run! The storm is coming!","trans":"快跑，暴风雨就要来了。","mne":""},{"word":"story","ipa":"/ˈstɔːri/","pos":"n.","def":"故事，小说；谎言，假话","sen":"She is reading a story to her kids.","trans":"她正给自己的孩子们讲故事呢。","mne":""},{"word":"stove","ipa":"/stoʊv/","pos":"n.","def":"炉子，火炉，电炉","sen":"Turn off the stove, or the food will be overcooked.","trans":"快把炉子关掉，不然食物要煮过头了。","mne":""},{"word":"straight","ipa":"/streɪt/","pos":"adj.","def":"直的；坦诚的；  adv.直接地","sen":"The road is very straight.","trans":"这条路很直。","mne":""},{"word":"strain","ipa":"/streɪn/","pos":"n.","def":"负担，压力；  v.拉紧，使......变紧张","sen":"The long working hours were a strain on my neck.","trans":"长时间工作让我的脖子感到有压力。","mne":""},{"word":"strange","ipa":"/streɪndʒ/","pos":"adj.","def":"奇怪的；陌生的","sen":"The rock has a strange shape.","trans":"这块岩石形状奇特。","mne":""},{"word":"stranger","ipa":"/ˈstreɪndʒər/ ","pos":"n.","def":"陌生人；新来者","sen":"Kids, be careful of strangers offering candy!","trans":"小朋友，小心拿糖给你吃的陌生人！","mne":"strang陌生的 + er人 → stranger陌生人；新来者"},{"word":"strategic","ipa":"/strəˈtiːdʒɪk/","pos":"adj.","def":"战略（上）的，对全局有重要意义的，关键的","sen":"Shanghai is of strategic importance to the international trade of China.","trans":"上海这座城市对中国的国际贸易具有重要的战略意义。","mne":"strateg战略 + ic形容词后缀 → strategic战略(上)的"},{"word":"strategy","ipa":"/ˈstrætədʒi/","pos":"n.","def":"策略，计谋","sen":"I like strategy games that require deep thinking, like chess.","trans":"我喜欢需要深思熟虑的策略性游戏，比如国际象棋。","mne":"strat军队 + egy名词后缀 → 军队需要战略 → strategy战略；策略"},{"word":"straw","ipa":"/strɔː/","pos":"n.","def":"吸管；稻草，麦秆","sen":"Why do you need two straws for one drink?","trans":"你一杯饮料为什么要两根吸管？","mne":""},{"word":"stream","ipa":"/stri:m/","pos":"n.","def":"小河，溪；流；  v.流出","sen":"There is a small stream running through the forest.","trans":"有一条小溪从森林中流过。","mne":""},{"word":"street","ipa":"/striːt/","pos":"n.","def":"大街，街道","sen":"There are no people on the street at night.","trans":"到了晚上，街上就空无一人。","mne":""},{"word":"strength","ipa":"/streŋθ/","pos":"n.","def":"体力，力气，力量；长处；实力","sen":"The man is flipping a heavy tire to build his strength.","trans":"这名男子翻转沉重的轮胎来增强力量。","mne":"streng=strong强壮的 + th抽象名词 → strength力量"},{"word":"strengthen","ipa":"/ˈstreŋθn/","pos":"v.","def":"增强","sen":"She keeps training every day to strengthen her arms.","trans":"她每天坚持锻炼来使手臂变强壮。","mne":"strength力量 + en动词后缀  → strengthen加强"},{"word":"stress","ipa":"/stres/","pos":"n.","def":"压力；紧张；强调；重读，重音；  v.强调","sen":"The business team is under great stress from work.","trans":"这个商务团队因工作压力很大。","mne":""},{"word":"stretch","ipa":"/stretʃ/","pos":"v.","def":"伸展，延伸，张开；  n.伸展，张开","sen":"He stretches his arm out while singing.","trans":"他一边唱歌一边把手臂伸展开。","mne":"stre=str扭转，拉紧 + tch动词后缀 → 向不同方向发力 → stretch伸展，张开"},{"word":"strict","ipa":"/strɪkt/","pos":"adj.","def":"严厉的；（条例、法规等）严格的","sen":"The teacher is strict during the exam.","trans":"老师监考非常严格。","mne":""},{"word":"strike","ipa":"/straɪk/  ","pos":"v.","def":"击打；袭击；罢工；  n.罢工；打击；袭击","sen":"Strike the ball flat and hard to knock it out of the stadium.","trans":"用力朝水平方向击球，就能把球打出场外。","mne":""},{"word":"striking","ipa":"/ˈstraɪkɪŋ/","pos":"adj.","def":"吸引人的，容貌出众的；显著的，突出的","sen":"The most striking feature of this cat is its long snow-white hair.","trans":"这只猫最吸引人的是它雪白的长毛。","mne":"strik=strike攻击 + ing形容词后缀 → 攻击 → striking惹人注目的"},{"word":"string","ipa":"/strɪŋ/","pos":"n.","def":"弦；细绳；一串","sen":"A violin has four strings.","trans":"小提琴有四根弦。","mne":""},{"word":"strip","ipa":"/strɪp/","pos":"v.","def":"脱衣服；剥去；  n.长条","sen":"Please strip off your clothes for the medical exam.","trans":"请脱掉你的衣服配合体检。","mne":""},{"word":"stripe","ipa":"/straɪp/","pos":"n.","def":"条纹；类型，类别","sen":"The zebra has black and white stripes on its body.","trans":"斑马身上有黑白相间的条纹。","mne":""},{"word":"strive","ipa":"/straɪv/","pos":"v.","def":"努力，奋斗","sen":"They will strive for what they want.","trans":"他们会为自己想要的东西而奋斗。","mne":""},{"word":"stroke","ipa":"/stroʊk/","pos":"n.","def":"击打；中风；  v.击打；轻抚","sen":"He hit the ball cleanly with a beautiful stroke.","trans":"他利落地击球，打出漂亮的一击。","mne":""},{"word":"strong","ipa":"/strɔːŋ/","pos":"adj.","def":"强壮的；强烈的；猛烈的","sen":"The strong man has a muscular body.","trans":"这个强壮的男人有着一身健壮的肌肉。","mne":""},{"word":"structure","ipa":"/ˈstrʌktʃər/","pos":"n.","def":"建筑物；结构；  v.精心组织；系统安排","sen":"There are so many new structures going up.","trans":"许多新的建筑正在兴建。","mne":"struct建立 + ure表名词 → structure构造；结构"},{"word":"struggle","ipa":"/ˈstrʌɡl/","pos":"v.","def":"奋斗，拼搏；挣扎；  n.奋斗；斗争","sen":"She's struggling to reach the top of the cliff.","trans":"她为了自己登顶的目标而奋斗。","mne":""},{"word":"stubborn","ipa":"/ˈstʌbərn/","pos":"adj.","def":"顽固的；倔强的；难对付的","sen":"The stubborn man covered his ears and refused to listen.","trans":"这个顽固的男人捂着耳朵拒绝听人讲话。","mne":"stub树桩、树墩 + orn形容词后缀 → stubborn顽固的，执拗的"},{"word":"student","ipa":"/ˈstuːdnt/","pos":"n.","def":"学生","sen":"The students are reading books.","trans":"学生们正在看书。","mne":"stud=study学习 + ent人 → student学生"},{"word":"studio","ipa":"/ˈstuːdioʊ/","pos":"n.","def":"摄影棚；录音室，录像室；工作室","sen":"In the studio, the model and the photographer are working.","trans":"摄影棚里模特和摄影师正在工作。","mne":"studi=study学习 + o表名词，物 → 工作室"},{"word":"study","ipa":"/ˈstʌdi/","pos":"v.","def":"学习；研究；  n.学习；研究；书房","sen":"Sorry I can't go out with you, I have to study for the exam.","trans":"抱歉我不能跟你出去玩，我还要准备考试呢。","mne":""},{"word":"stuff","ipa":"/stʌf/","pos":"n.","def":"东西；原料；  v.把……塞进；装满","sen":"We keep all of the baby's stuff in his bedroom.","trans":"我们把婴儿的所有东西都放在他的卧室里。","mne":""},{"word":"stupid","ipa":"/ˈstuːpɪd/","pos":"adj.","def":"愚蠢的，笨的","sen":"The donkey made a stupid mistake.","trans":"这头驴犯了一个愚蠢的错误。","mne":"stup笨，麻木 ＋ id形容词，“如…的” → stupid笨的"},{"word":"style","ipa":"/staɪl/","pos":"n.","def":"风格；样式；设计；作风","sen":"She dresses in a cozy and sunny style.","trans":"她的穿衣风格休闲又阳光。","mne":""},{"word":"stylish","ipa":"/ˈstaɪlɪʃ/","pos":"adj.","def":"时尚的，漂亮的","sen":"Even a dog can be very stylish.","trans":"狗也能打扮得很时尚。","mne":"styl=style风格 + ish形容词后缀 → 有风格的 → stylish流行的"},{"word":"subject","ipa":"/ˈsʌbdʒɪkt/,  /ˈsʌbdʒekt/","pos":"n.","def":"学科，科目；实验对象；主题；话题，主题","sen":"English was my favorite subject in school.","trans":"英语是我上学时最喜欢的科目。","mne":"sub在…下面 + ject投掷，扔 → 扔下去 → 服从的，扔下去让大家讨论的主题 → subject主题"},{"word":"submarine","ipa":"/ˈsʌbməriːn/","pos":"n.","def":"潜水艇；  adj.水底的，海底的","sen":"Submarines can travel underwater.","trans":"潜水艇可以在水下航行。","mne":"sub在下面 + marine海洋的 → 在海下面 → submarine海底的；潜水艇"},{"word":"submerge","ipa":"/səbˈmɜːrdʒ/","pos":"v.","def":"沉没，淹没","sen":"The car was almost submerged by the floodwater!","trans":"汽车就快被洪水淹没了！","mne":"sub在下面 + merge沉 → submerge淹没"},{"word":"submission","ipa":"/səbˈmɪʃn/","pos":"n.","def":"屈服，服从；提交，呈递","sen":"The knight kneeled and handed over his sword to show his submission.","trans":"这位骑士单膝跪地并交出自己的宝剑以示屈服。","mne":"sub下面 + miss送，放出 + ion名词后缀 → 放在下面 → submission屈服"},{"word":"submit","ipa":"/səbˈmɪt/","pos":"v.","def":"提交；呈递；屈服，使...服从","sen":"The man is submitting the report to his boss.","trans":"这个男人正在把报告递交给他的老板。","mne":"sub下面 + mit放出，发送 → 从下面送出 → submit提交、呈递"},{"word":"subsequent","ipa":"/ˈsʌbsɪkwənt/","pos":"adj.","def":"随后的；后来的","sen":"The giant wave was responsible for the subsequent sinking of the ship.","trans":"巨浪是船随后沉没的主要原因。","mne":"sub在后面 + sequ跟随 + ent形容词后缀 → subsequent随后的"},{"word":"subsidy","ipa":"/ˈsʌbsədi/","pos":"n.","def":"补助金，津贴","sen":"The government provided a subsidy for the entrepreneurs.","trans":"政府为创业者提供了补贴。","mne":"subsid减弱 + y名词后缀 → 拨款以减低公共事业消费 → subsidy补贴"},{"word":"substance","ipa":"/ˈsʌbstəns/","pos":"n.","def":"物质；实质；主旨；物品","sen":"Substances like water have three different forms.","trans":"像水这样的物质们有三种不同的形态。","mne":"sub下面 + st站立 + ance表名词 → 站在下面的东西 → substance物质；本质"},{"word":"substantial","ipa":"/səbˈstænʃl/","pos":"adj.","def":"大量的","sen":"The store provided substantial discounts on all clothes.","trans":"这家店给所有衣服都打了大幅度的折扣。","mne":"sub下面 + stan站立 + tial形容词后缀 → 作为基本存在的 → substantial重大的，大量的"},{"word":"substitute","ipa":"/ˈsʌbstɪˌtut/","pos":"v.","def":"代替；  n.替代物；替代者","sen":"You should substitute fruits for sweets.","trans":"你应该用水果代替甜食。","mne":"sub在下面，副手，次一等 + stitute创建，建立 → 建在下面 → substitute代替，候补"},{"word":"subtle","ipa":"/ˈsʌtl/","pos":"adj.","def":"微妙的","sen":"There is a subtle change in his weight.","trans":"他的体重有细微的变化。","mne":"sub在...下面 + tle网 → subtle不明显的"},{"word":"subtract","ipa":"/səbˈtrækt/","pos":"v.","def":"减去，减掉；扣除","sen":"If you subtract 3 from 5, you get 2.","trans":"5减去3等于2。","mne":"sub在下面 + tract抽 → 抽去 → 减去，去掉"},{"word":"suburb","ipa":"/ˈsʌbɜːrb/","pos":"n.","def":"郊区","sen":"In the suburbs, there are fewer houses and more trees.","trans":"郊区房子少，但是树多。","mne":"sub在下面，次一等 + urb城市 → suburb郊区，郊外"},{"word":"subway","ipa":"/ˈsʌbweɪ/","pos":"n.","def":"地铁","sen":"He takes the subway to work every day.","trans":"他每天乘地铁上班。","mne":"sub在下 + way道路 → subway地下通道，地铁"},{"word":"succeed","ipa":"/səkˈsiːd/","pos":"v.","def":"成功，达到目的；继承","sen":"I succeeded in shooting three arrows in the center of the target.","trans":"我成功地将三支箭射中了靶心。","mne":"suc在…下面 + ceed走 → 从下走到上面 → succeed成功"},{"word":"success","ipa":"/səkˈses/","pos":"n.","def":"成功，成就；胜利","sen":"The success of reaching the top of the mountain brought him great joy.","trans":"成功登上山顶让他无比喜悦。","mne":"suc在……下面 + cess行走 → 在后面跟着前人走 → success成功；胜利"},{"word":"successful","ipa":"/səkˈsesfl/","pos":"adj.","def":"有成就的；出人头地的","sen":"He was a successful businessman and brought great changes to our phones.","trans":"他是一位成功的商人，给我们的手机带来了极大的变化。","mne":"suc在下面 + cess行走，前进 + ful…的 → success成功 + ful…的 → successful成功的，有成就的"},{"word":"succession","ipa":"/səkˈsɛʃən/","pos":"n.","def":"一连串；连续，继续；继承权","sen":"A succession of horses passed us in the forest.","trans":"森林中，一匹匹马从我们身边经过。","mne":"suc紧接着 + cess前进 + ion名词后缀 → succession接连，一系列"},{"word":"successive","ipa":"/səkˈsesɪv/","pos":"adj.","def":"接连的；继承的","sen":"Dominoes fall down in a successive way.","trans":"多米诺骨牌接二连三地倒下了。","mne":"suc在…下面 + cess行走 + ive形容词后缀 → 接着后面走的 → 连续的"},{"word":"such","ipa":"/sʌtʃ/","pos":"det.","def":"这样的，那样的，此类的","sen":"Look! Such a beautiful view.","trans":"看！这是多美的景色啊！","mne":""},{"word":"suck","ipa":"/sʌk/","pos":"v.","def":"吸吮","sen":"The newborn began to suck milk from the bottle immediately.","trans":"新生儿立刻开始用奶瓶吸吮牛奶。","mne":""},{"word":"sudden","ipa":"/ˈsʌdn/","pos":"adj.","def":"突然的，忽然的","sen":"The boy was scared by the sudden burst of the balloon.","trans":"气球突然爆了，吓了男孩一跳。","mne":"sud达到 + den去 → 突然到来的事情 → sudden立即，突然"},{"word":"suddenly","ipa":"/ˈsʌdənli/","pos":"adv.","def":"突然地，猛地","sen":"Suddenly, my friend surprised me from behind.","trans":"我的朋友突然从后面给我来了个惊喜。","mne":"sudden突然的 ＋ ly...地 → suddenly突然地"},{"word":"suffer","ipa":"/ˈsʌfər/","pos":"v.","def":"感到（疼痛）","sen":"He suffers from a bad toothache.","trans":"他牙痛得厉害。","mne":"suf在下 + fer负重 → suffer承受"},{"word":"suffering","ipa":"/ˈsʌfərɪŋ/","pos":"n.","def":"苦楚；疼痛，苦难；折磨","sen":"My father’s suffering is getting serious.","trans":"爸爸的痛苦越来越严重。","mne":"suf在下面 + fer带 + ing表名词 → suffer带到下面去受苦 + ing表名词 → suffering受难"},{"word":"sufficient","ipa":"/səˈfɪʃnt/","pos":"adj.","def":"足够的，充足的","sen":"The animal has sufficient food for the winter.","trans":"这只动物有充足的食物来过冬。","mne":"suffic足以 + ient形容词后缀 → sufficient 足够的"},{"word":"sugar","ipa":"/ˈʃʊɡər/","pos":"n.","def":"糖；食用糖；  v.加糖于","sen":"I'd like a spoonful of sugar in my coffee.","trans":"我想在我的咖啡里放一勺糖。","mne":""},{"word":"suggest","ipa":"/səˈdʒest/","pos":"v.","def":"建议，提议；使人想起；暗示","sen":"You look terrible! I suggest you go to see a doctor.","trans":"你看起来糟透了！我建议你去看医生。","mne":"sug在下面 + gest带来，产生 → 从下面带上来 → suggest建议"},{"word":"suggestion","ipa":"/səˈdʒestʃən/","pos":"n.","def":"建议，意见","sen":"The shopping guide gives her some suggestions about the skirt.","trans":"导购给了她一些选裙子的建议。","mne":"sug=sub在下面 + gest带来，产生 + ion表名词 → 从下面产生的建议 → suggestion建议，意见"},{"word":"suit","ipa":"/suːt/","pos":"n.","def":"西服，套装；服装；诉讼；  v.适合；相配","sen":"The businessman is wearing a gray suit.","trans":"这位商人穿着一套灰色的西装。","mne":""},{"word":"suitable","ipa":"/ˈsuːtəbl/","pos":"adj.","def":"合适的，适宜的","sen":"That's a suitable dress for the party.\n","trans":"那件裙子适合参加派对。","mne":"suit适合 + able……的 → suitable合适的，适宜的"},{"word":"suite","ipa":"/swiːt/","pos":"n.","def":"（旅馆的）套间；组曲；一套家具","sen":"This suite is big enough for a whole family to live in.","trans":"这间套房足够一家人住了。","mne":""},{"word":"sum","ipa":"/sʌm/","pos":"n.","def":"全部，总和；算术；  v.概括","sen":"The sum of one and one is two.","trans":"一加一的和是二。","mne":""},{"word":"summarise","ipa":"/'sʌməˌraɪz/","pos":"v.","def":"概括，总结","sen":"I think the speaker summarised the theory quite nicely.","trans":"我认为发言人很好的概括了这个原理。","mne":""},{"word":"summarize","ipa":"/ˈsʌməraɪz/","pos":"v.","def":"作概括；概括；总结","sen":"I don’t want to read the whole thing. Could you just summarize the book for me?","trans":"我不想再看这个东西了，你能就帮我概括一下这本书吗？","mne":"summar总，加 + ize动词后缀 → summarize概括"},{"word":"summary","ipa":"/ˈsʌm.ər.i/","pos":"n.","def":"摘要，总结","sen":"I made a summary of this article.","trans":"我对这篇文章做了一下总结。","mne":"summ总数 + ary表名词 → 内容总和 → summary摘要"},{"word":"summer","ipa":"/ˈsʌmər/","pos":"n.","def":"夏季","sen":"It's fun to relax at the beach in the summer.","trans":"夏天在沙滩上放松很有趣。","mne":""},{"word":"summit","ipa":"/ˈsʌmɪt/","pos":"n.","def":"山顶，顶点；  adj.最高级的；政府首脑的","sen":"He eventually climbed to the summit of the mountain.","trans":"他终于爬到了峰顶。","mne":""},{"word":"sun","ipa":"/sʌn/","pos":"n.","def":"太阳；阳光","sen":"The sun is going down.","trans":"太阳逐渐落山了。","mne":""},{"word":"sunday","ipa":"/ˈsʌndeɪ/","pos":"n.","def":"星期天，周日","sen":"We don't have to go to school on Sunday. Let's play!","trans":"周日不上学，咱们去玩儿吧！","mne":"Sun日 + day天 → Sunday星期日"},{"word":"sunlight","ipa":"/ˈsʌnlaɪt/","pos":"n.","def":"阳光，日光","sen":"The sunlight brightens the green field.","trans":"阳光照亮了绿地。","mne":"sun太阳 + light光亮 → sunlight日光"},{"word":"sunny","ipa":"/ˈsʌni/","pos":"adj.","def":"阳光充足的，阳光明媚的","sen":"The blue sky means that today is a sunny day.","trans":"蓝蓝的天空表明今天是个晴天。","mne":"sun太阳 + n + y形容词后缀 → sunny晴朗的"},{"word":"sunrise","ipa":"/ˈsʌnraɪz/","pos":"n.","def":"日出；朝霞","sen":"I got up early today and saw a beautiful sunrise.","trans":"我今天早起看了美丽的日出。","mne":"sun太阳 + rise升起 → 太阳升起来 → sunrise日出"},{"word":"sunset","ipa":"/ˈsʌnset/","pos":"n.","def":"日落，傍晚","sen":"The sunset on the river looks amazing tonight.","trans":"今天傍晚，河上的日落美不胜收。","mne":"sun太阳 + set落 → sunset 日落"},{"word":"sunshine","ipa":"/ˈsʌnʃaɪn/","pos":"n.","def":"日光，日照","sen":"The sunshine broke through the clouds.","trans":"阳光穿透了云层。","mne":"sun太阳 + shine光亮 → sunshine日光，日照"},{"word":"super","ipa":"/ˈsuːpər/","pos":"adj.","def":"超级的；极好的","sen":"Superman has all kinds of super powers, like flying and super strength!","trans":"超人有各种各样的超能力，比如飞行和超级力量。","mne":""},{"word":"superficial","ipa":"/ˌsuːpərˈfɪʃl/","pos":"adj.","def":"表面的；肤浅的","sen":"The house may look new, but it's all superficial.","trans":"这栋房子看起来很新，但这只是表面现象。","mne":"super在…上面 + fic做 + ial形容词后缀 → 在表面上做 → 肤浅"},{"word":"superior","ipa":"/suːˈpɪriər/","pos":"n.","def":"上级；  adj.（级别/重要性）更高的；更好的","sen":"The people on the left have to listen to their superior.","trans":"左边的人得听从他们的上司。","mne":"super在上面 + ior表形容词，较…的 → superior在上面的，超越的"},{"word":"supermarket","ipa":"/ˈsuːpərmɑːrkɪt/","pos":"n.","def":"超市","sen":"You can buy a lot of things in the supermarket.","trans":"你可以在超市买到很多东西。","mne":"super超级 + market市场 → supermarket超市"},{"word":"supervise","ipa":"/ˈsuːpərvaɪz/","pos":"v.","def":"监督；指导；管理","sen":"It is absurd to supervise the students studying in the classroom like this.","trans":"像这样监督教室里学习的学生是荒唐可笑的。","mne":"super在…上面 + vise看 → 在上面看 → 临视 → supervise监督"},{"word":"supervision","ipa":"/ˌsuːpərˈvɪʒn/","pos":"n.","def":"监督，管理","sen":"The young staff member worked hard under the supervision of his boss.","trans":"这位年轻的职员在老板的监督下努力工作。","mne":"supervis监督 + ion名词后缀 → supervision监督"},{"word":"supper","ipa":"/ˈsʌpər/","pos":"n.","def":"晚餐","sen":"Have you had supper?","trans":"你吃过晚饭了吗？","mne":""},{"word":"supplement","ipa":"/ˈsʌplɪmənt/","pos":"n.","def":"增补，补充物，保健品；附录，增刊；  v.补充（读作/ˈsʌpləˌmɛnt/）","sen":"You should take these herbal supplements once a day.","trans":"你应该一天服用一次这些草本保健品。","mne":"sup在下面，次要 + ple满，填满 + ment名词后缀 → 增加次要的心填满 → 增补"},{"word":"supply","ipa":"/səˈplaɪ/ ","pos":"n.","def":"供应，供应量；供给；  v.供给","sen":"The farmer has an adequate supply of milk.","trans":"农场主有充足的牛奶供应。","mne":"sup在下面 + ply填充，充满 → 填充下去 → 供应[下去]，补给"},{"word":"support","ipa":"/səˈpɔːrt/","pos":"v.","def":"支援；支撑；  n.支持；支撑物","sen":"Doctors and resources are being sent from other areas to support this province.","trans":"其他地区派遣医生、运送物资来支援这个省。","mne":"sup在…下面 + port带 → 带来支持 → support支持"},{"word":"suppose","ipa":"/səˈpoʊz/","pos":"v.","def":"认为；设想，推想","sen":"I suppose that I can be back before nine o'clock.","trans":"我想我九点前能回来。","mne":"sup在……下面 + pose放 → 放下去想 → suppose猜想，推测"},{"word":"supreme","ipa":"/suːˈpriːm/","pos":"adj.","def":"至高的","sen":"The king is the supreme leader of the country.","trans":"国王是国家里至高无上的领导者。","mne":""},{"word":"sure","ipa":"/ʃʊr/","pos":"adv.","def":"（表示同意）当然，确实地，无疑地；  adj.肯定的；确信的","sen":"I am sure that the tortoise can win because the rabbit is still asleep.","trans":"我确信乌龟可以赢得这场比赛，因为兔子还在睡觉呢。","mne":""},{"word":"surface","ipa":"/ˈsɜːrfɪs/","pos":"n.","def":"表面，表层；  v.显露","sen":"There is some oil on the surface of the soup.","trans":"汤的表面有一些油。","mne":"sur超过，在上面 + face脸面 → surface表面"},{"word":"surgeon","ipa":"/ˈsɜːrdʒən/","pos":"n.","def":"外科医生","sen":"My surgeon decided to give me an operation.","trans":"我的外科医生决定给我动手术。","mne":"sur手 + geon工作，去做 → surgeon外科医生"},{"word":"surgery","ipa":"/ˈsɜːrdʒəri/","pos":"n.","def":"外科手术","sen":"They are performing surgery on a patient now.","trans":"他们正在给一位病人做外科手术。","mne":"surger=surgeon外科医生 + y名词后缀 → surgery外科，外科手术"},{"word":"surpass","ipa":"/sərˈpæs/","pos":"v.","def":"胜过；超出，超过","sen":"The turtle surpassed the rabbit in the running race.","trans":"乌龟在跑步比赛中超过了兔子。","mne":"sur超过，在上面 + pass通过 → 在上面通过 → surpass超过"},{"word":"surprise","ipa":"/sərˈpraɪz/ ","pos":"v.","def":"使惊奇，使诧异，使感到意外","sen":"She was extremely surprised at the size of the woman's muscles.","trans":"麦克斯看到那个女人的肌肉，整个人都方（huang）了！","mne":"sur突然 + prise拿住，抓住 → 突然被抓住 → surprise吃惊"},{"word":"surrender","ipa":"/səˈrendər/","pos":"v.","def":"投降","sen":"Surrender your worries and embrace the joy of the present.","trans":"放下焦虑，拥抱当下的美好。","mne":"sur下面 + render给予 → 给到下面 → [把枪]放下 → surrender投降"},{"word":"surround","ipa":"/səˈraʊnd/","pos":"v.","def":"包围；  v.围绕","sen":"Tall trees surround the lake.","trans":"高大的树木环绕着湖泊。","mne":"sur在···上 + round圆的 → surround围绕"},{"word":"surroundings","ipa":"/səˈraʊndɪŋz/","pos":"pl.","def":"周围的事物；环境","sen":"The village's surroundings are mostly forests and green lands.","trans":"村庄的周围主要是森林和绿地。","mne":"sur随后 + round圆圈 + ings表名词 → surroundings周围的事物，环境"},{"word":"survey","ipa":"/ˈsɜrˌveɪ/","pos":"n.","def":"调查；  v.鉴定；测量，勘测","sen":"The old lady is taking a survey.","trans":"这位年老的女士正在做调查。","mne":"sur在上面 + vey看 → 从上面看 → survey调查"},{"word":"survival","ipa":"/sərˈvaɪvl/","pos":"n.","def":"生存；存活；幸存；残存物","sen":"She taught me survival skills in the wild, like how to start a fire in the forest.","trans":"她教了我野外求生的技能，比如如何在森林里生火。","mne":"survive幸存 + al名词后缀 → survival生存，存活"},{"word":"survive","ipa":"/sərˈvaɪv/ ","pos":"v.","def":"幸存，存活；存活；  v.生存，活着","sen":"The girl survived the shipwreck.","trans":"这个女孩在海难中幸存了下来。","mne":"sur超过 + vive活 → survive存活"},{"word":"survivor","ipa":"/sərˈvaɪvər/","pos":"n.","def":"生还者；幸存者","sen":"Most of the survivors of the Titanic disaster were women and children.","trans":"泰坦尼克号沉没事件中的大多数幸存者是女性和儿童。","mne":"surviv=survive幸存，生还 + or 名词后缀,表示人 → 生还者, 残存"},{"word":"suspect","ipa":"/ˈsʌspekt/, /səˈspekt/","pos":"n.","def":"犯罪嫌疑人，可疑分子；  v.怀疑，猜疑；  adj.可疑的","sen":"The suspect is talking with his lawyer.","trans":"犯罪嫌疑人正在和他的律师谈话。","mne":"sus在…下面 + pect看 → (偷偷地)在下面看 → suspect怀疑；嫌疑犯，可疑分子"},{"word":"suspend","ipa":"/səˈspend/","pos":"v.","def":"悬挂，吊；暂停","sen":"These lights are suspended on the ceiling.","trans":"这些灯被吊在天花板上。","mne":"sus在…下 + pend挂 → 挂在下面 → suspend吊，悬挂"},{"word":"suspicion","ipa":"/səˈspɪʃən/","pos":"n.","def":"怀疑，嫌疑，猜疑","sen":"The two men raised the suspicion of the policeman.","trans":"这两个人引起了警察的怀疑。","mne":"su=sus下面 + spic环顾，检查 + ion表名词 → 在下面看 → 怀疑"},{"word":"suspicious","ipa":"/səˈspɪʃəs/","pos":"adj.","def":"可疑的；怀疑的，猜疑的","sen":"The policeman found the man's behavior suspicious.","trans":"警察发现这个人的行为很可疑。","mne":"suspici怀疑 + ous形容词后缀 → suspicious猜疑的"},{"word":"sustain","ipa":"/səˈsteɪn/","pos":"v.","def":"支撑，承受；维持（生命）；使保持","sen":"Get up! The chair can't sustain your weight anymore!","trans":"快起来！这把椅子快承受不住你的重量了！","mne":"sus在…下面 + tain握住 → 在下面握住 → 支撑，承受"},{"word":"sustainable","ipa":"/səˈsteɪnəbl/","pos":"adj.","def":"可持续的","sen":"We promote sustainable jewelry practices, using recycled materials.","trans":"我们倡导可持续的珠宝制作实践，使用回收材料。","mne":"sustain支持 + able可…的 → sustainable可以忍受的；足可支撑的"},{"word":"swallow","ipa":"/ˈswɑ:ləʊ/ ","pos":"v.","def":"吞下；相信；  n.吞咽；燕子","sen":"She always lifts her head when swallowing pills.","trans":"她总是会在吞药片的时候抬起头。","mne":""},{"word":"swear","ipa":"/swer/","pos":"v.","def":"发誓，郑重地说，保证；咒骂","sen":"I swear I'm telling the truth.","trans":"我发誓我讲的是实话。","mne":""},{"word":"sweat","ipa":"/swet/","pos":"v.","def":"出汗；  n.汗水","sen":"I sweat a lot whenever I get to work.","trans":"每次去上班，我都会出很多汗。","mne":""},{"word":"sweater","ipa":"/ˈswetər/","pos":"n.","def":"毛衣，厚运动衫，羊毛衫，针织套衫","sen":"She likes this red sweater. It can keep her warm.","trans":"她喜欢这件红色毛衣。它能帮她保暖。","mne":"sweat汗 + er表物 → 穿着会出汗的 → sweater厚运动衫"},{"word":"sweep","ipa":"/swiːp/","pos":"v.","def":"扫，打扫，清扫；席卷，迅速传播；  n.清扫；打扫范围","sen":"The floor is so dirty! I need to sweep it.","trans":"地板太脏了！我需要扫扫。","mne":""},{"word":"sweet","ipa":"/swiːt/","pos":"adj.","def":"甜；  n.糖果，甜食","sen":"I'm savouring a sweet and fruity cocktail.","trans":"我正在品尝一款甜而果味浓郁的鸡尾酒。","mne":""},{"word":"swift","ipa":"/swɪft/","pos":"adj.","def":"迅速的，敏捷的，立刻的；敏捷的；  n.雨燕","sen":"The cheetah is the swiftest land animal.","trans":"猎豹是跑得最快的陆地动物。","mne":""},{"word":"swim","ipa":"/swɪm/","pos":"v.","def":"游泳","sen":"Two girls swam in the pool.","trans":"小丸子和小玉在游泳池里面游了泳。","mne":""},{"word":"swing","ipa":"/swɪŋ/","pos":"v.","def":"摇荡，摆动；使摇摆，使转动，使转向；  n.秋千","sen":"He swings in the forest from tree to tree.","trans":"他在丛林的树间荡来荡去。","mne":""},{"word":"switch","ipa":"/swɪtʃ/","pos":"n.","def":"开关；  v.转换","sen":"There are so many switches in your home! Which one turns on the lights?","trans":"你家有这么多开关，哪一个能把灯打开？","mne":""},{"word":"sword","ipa":"/sɔːrd/","pos":"n.","def":"剑，刀","sen":"He is holding his wooden sword to the air.","trans":"他正把木剑举向空中。","mne":""},{"word":"symbol","ipa":"/ˈsɪmbəl/ ","pos":"n.","def":"象征；符号，标记；标志","sen":"Doves are the symbol of peace.","trans":"鸽子是和平的象征。","mne":"sym共同，相同 + bol抛 → 共同抛出的标志 → 象征"},{"word":"symbolic","ipa":"/sɪmˈbɑːlɪk/","pos":"adj.","def":"象征的；符号的","sen":"The red cross is symbolic of medical care.","trans":"红十字标志象征着医疗援救。","mne":"symbol标志 + ic形容词后缀 → symbolic 象征的"},{"word":"symbolise","ipa":"/'sɪmbəlaɪz/","pos":"v.","def":"象征；以符号表示=symbolize","sen":"This gesture symbolises that you did a good job.","trans":"该手势象征着你干的不错。","mne":""},{"word":"symbolize","ipa":"/ˈsɪmbəlaɪz/","pos":"v.","def":"象征，用符号表现","sen":"These three icons symbolize unhappiness for most young people.","trans":"这三个图标对大多数年轻人来说象征着不快乐。","mne":"symbol符合 ＋ ize动词后缀 → 共同抛出标志 → symbolize用符号表示；象征"},{"word":"sympathise","ipa":"/'sɪmpəˌθaɪz/","pos":"v.","def":"共鸣，体谅；同情","sen":"I really sympathised with him who was depressed for failing the exam.","trans":"他考试不及格心情十分沮丧，我十分感同身受。","mne":""},{"word":"sympathize","ipa":"/ˈsɪmpəθaɪz/","pos":"v.","def":"同情，同感，共鸣","sen":"I sympathize with him, patting him on the shoulder.","trans":"我很同情他，拍了拍他的肩膀。","mne":"sym共同 + path感情 + ize动词后缀 → sympathize情感共鸣"},{"word":"sympathy","ipa":"/ˈsɪmpəθi/","pos":"n.","def":"同情；同感；慰问","sen":"He felt a lot of sympathy for the dog and gave it a bone.","trans":"他很同情那条狗并给了它一根骨头。","mne":"sym共同 + pathy感情 → sympathy同情"},{"word":"symptom","ipa":"/ˈsɪmptəm/","pos":"n.","def":"症状；征兆","sen":"Flu symptoms include a headache, a sore throat, and a fever.","trans":"流感的症状包括头痛、嗓子痛和发烧。","mne":"sym一起 + ptom落下 → symptom症状"},{"word":"synthetic","ipa":"/sɪnˈθetɪk/","pos":"adj.","def":"合成的；合成的，人造的","sen":"This sweater is made of synthetic fibers.","trans":"这件毛衣是由合成纤维制成的。","mne":"syn共同 + the=thesis放置 + tic形容词后缀 → 放一起 → synthetic合成的"},{"word":"system","ipa":"/ˈsɪstəm/","pos":"n.","def":"系统；体系","sen":"There are eight planets in our solar system.","trans":"我们的太阳系中有八大行星。","mne":"sy一起 + stem使立住 → system系统"},{"word":"systematic","ipa":"/ˌsɪstəˈmætɪk/","pos":"adj.","def":"系统的，有条理的；成体系的","sen":"The building has a very systematic design, with every part repeated.","trans":"这个建筑有系统化的设计，每个部分都有重复。","mne":"system系统 + atic…的 → 有系统的"},{"word":"table","ipa":"/ˈteɪbəl/","pos":"n.","def":"桌子，台子；表格；  v.搁置","sen":"The meeting room had a large table big enough for fifteen people to sit around.","trans":"这间会议室有一个大桌子，足够坐下十五个人。","mne":""},{"word":"tablet","ipa":"/ˈtæblət/","pos":"n.","def":"药片；平板电脑；碑，匾","sen":"I take a tablet when I have a headache.","trans":"我一头痛就会吃一片药。","mne":""},{"word":"tackle","ipa":"/ˈtækl/","pos":"v.","def":"对付，处理，解决（难题）；（足球等比赛中）阻截；  n.阻截，阻截队员","sen":"The firefighters are tackling the blaze.","trans":"消防队员们正在努力扑灭大火。","mne":""},{"word":"tag","ipa":"/tæɡ/ ","pos":"n.","def":"标签；  v.连接，合并","sen":"I always look for a sale tag to get a lower price.","trans":"我总是在寻找降价标签以得到更低的价格。","mne":""},{"word":"tail","ipa":"/teɪl/","pos":"n.","def":"尾巴；  v.紧跟，尾随","sen":"The horse's long tail lifted up into the air as it ran.","trans":"马的长尾巴随着其奔跑的步伐甩向空中。","mne":""},{"word":"tailor","ipa":"/ˈteɪlər/","pos":"n.","def":"裁缝；  v.调整……使适应；定做","sen":"The tailor measured him for a new suit.","trans":"裁缝为他量身定做了一套新西装。","mne":"tail剪，割 + or表名词 → tailor裁缝"},{"word":"take","ipa":"/teɪk/","pos":"v.","def":"带；接受；花费（时间），占用……时间","sen":"Please take your bag.","trans":"请带上你的书包。","mne":""},{"word":"tale","ipa":"/teɪl/ ","pos":"n.","def":"故事，传说","sen":"He stayed up late at night just to finish reading the tale.","trans":"他晚上熬夜，就是为了能看完这个故事。","mne":""},{"word":"talent","ipa":"/ˈtælənt/  ","pos":"n.","def":"天赋，才能；天才，人才","sen":"This baby showed great talent as he was playing the piano.","trans":"这个宝宝弹钢琴的时候展现出超强的天赋。","mne":""},{"word":"talk","ipa":"/tɔːk/","pos":"v.","def":"讲话；  n.谈话","sen":"They are talking to each other to share ideas.","trans":"他们正在聊天以分享想法。","mne":""},{"word":"tall","ipa":"/tɔːl/","pos":"adj.","def":"身材高的，高大的","sen":"How did you grow so tall?","trans":"你是怎么长到这么高的？","mne":""},{"word":"tame","ipa":"/teɪm/","pos":"adj.","def":"驯服的，温顺的；  v.驯服","sen":"Don't worry, this lion is tame—it won't hurt you.","trans":"别担心，这只狮子很温驯，它不会伤害你的。","mne":""},{"word":"tank","ipa":"/tæŋk/","pos":"n.","def":"大容器，大罐；坦克；水槽，池塘","sen":"The man is checking the large yellow tank.","trans":"这个人正在检查这个黄色的大罐子。","mne":""},{"word":"tap","ipa":"/tæp/","pos":"n.","def":"水龙头；轻敲；  v.监听，窃听 (电话)；轻叩，轻敲；刷（卡）","sen":"Water flows from the tap.","trans":"水从水龙头流出来。","mne":""},{"word":"tape","ipa":"/teɪp/","pos":"n.","def":"磁带；胶带，胶条；带子；  v.录音；用胶带粘贴","sen":"I'm using a pencil to rewind the tape.","trans":"我用铅笔来倒磁带。","mne":""},{"word":"target","ipa":"/ˈtɑrɡɪt/","pos":"n.","def":"靶子；目标；  v.瞄准","sen":"Yes! I hit the target, right in the center!","trans":"太好了！我击中了靶子，正中靶心！","mne":""},{"word":"task","ipa":"/tæsk/ ","pos":"n.","def":"任务，工作；作业","sen":"I'm so happy—there isn't a single task on my to-do list!","trans":"我很高兴，我的任务列表上已经没有任务了！","mne":""},{"word":"taste","ipa":"/teɪst/","pos":"v.","def":"品尝，尝（......的味道），尝起来；有……的味道；  n.味道；鉴赏力；品味；爱好，志趣","sen":"She always tastes the soup before serving it to others.","trans":"她上汤之前总要先尝一尝。","mne":""},{"word":"tax","ipa":"/tæks/ ","pos":"n.","def":"税，税款；  v.征税；使负重担","sen":"The amount of tax people pay to the government depends on their income.","trans":"人们向政府纳税的数额取决于他们的收入。","mne":""},{"word":"taxi","ipa":"/ˈtæksi/","pos":"n.","def":"出租车，计程车；  v.用出租车运送","sen":"The man is waiting for a taxi.","trans":"这位男士正等着出租车。","mne":""},{"word":"tea","ipa":"/tiː/","pos":"n.","def":"茶（叶）","sen":"Would you like a cup of tea?","trans":"你要来杯茶吗？","mne":""},{"word":"teach","ipa":"/tiːtʃ/","pos":"v.","def":"教育，教导；教训","sen":"My mother taught me the importance of waste segregation.","trans":"妈妈教我了解了垃圾分类的重要性。","mne":""},{"word":"teacher","ipa":"/ˈtiːtʃər/","pos":"n.","def":"教师，老师，教员","sen":"Our teacher showed us where America and China were in the world.","trans":"老师指给我们看了美国和中国在地球上的位置。","mne":"teach教 + er人 → teacher教师"},{"word":"team","ipa":"/tiːm/","pos":"n.","def":"队，组；球队","sen":"The superheroes formed a team to fight together.","trans":"超级英雄们组成一个团队一起战斗。","mne":""},{"word":"tear","ipa":"/ter/, /tɪr/","pos":"v.","def":"撕裂，撕碎（读作/ter/ ）；  n.眼泪（读作/tɪr/）","sen":"The broken-hearted man is tearing the photo into pieces.","trans":"这个心碎的男人正在把照片撕成碎片。","mne":""},{"word":"technical","ipa":"/ˈteknɪkl/","pos":"adj.","def":"技术的，工艺的","sen":"She is responsible for answering technical questions.","trans":"她负责解答技术问题。","mne":"techn技术，能力 + ical形容词后缀 → technical技术上的"},{"word":"technician","ipa":"/tekˈnɪʃn/","pos":"n.","def":"技术员，技师","sen":"We brought the technician in to repair our computers.","trans":"我们把技术员叫来修电脑。","mne":"techn技术 + ician表专家，从事某职业的人 → technician技术员"},{"word":"technique","ipa":"/tekˈniːk/","pos":"n.","def":"技巧，技能；技术，方法","sen":"The musician combines different techniques in the performance.","trans":"这位音乐家在表演中结合了不同的技巧。","mne":"techni技术 + que后缀 -> 技术"},{"word":"technological","ipa":"/ˌteknəˈlɑːdʒɪkl/","pos":"adj.","def":"技术的，工艺的","sen":"Communication is much easier nowadays thanks to technological advancements.","trans":"由于技术的进步，现今通信更容易了。","mne":"techno技术  +logical……学的 → 技术的"},{"word":"technology","ipa":"/tekˈnɑːlədʒi/","pos":"n.","def":"科技；技术，工艺，工程技术","sen":"Now there are more and more technology products in our lives.","trans":"现在我们的生活中科技产品越来越多。","mne":"techno技术，能力 + logy学说 → 技术，科技"},{"word":"tedious","ipa":"/ˈtiːdiəs/","pos":"adj.","def":"沉闷的，冗长乏味的","sen":"It is really tedious to look at the screen all day long. ","trans":"整天看着屏幕非常枯燥。","mne":"ted厌倦 + ious表形容词 → 冗长沉闷的"},{"word":"teenager","ipa":"/ˈtiːneɪdʒər/","pos":"n.","def":"（13～19岁的）青少年","sen":"Teenagers are always full of energy.","trans":"青少年总是充满了能量。","mne":"teen青少年 + age年龄 + r=er表人 → teenager青少年"},{"word":"telegram","ipa":"/ˈtelɪɡræm/ ","pos":"n.","def":"电报，电文","sen":"She sent a telegram upon her arrival in Beijing.","trans":"她一抵达北京就发了一封电报。","mne":"tele远，传送 + gram写，画 → telegram电报"},{"word":"telephone","ipa":"/ˈtelɪfoʊn/","pos":"n.","def":"电话（机）","sen":"The telephone rang while she was sleeping.","trans":"电话在她睡觉的时候响了起来。","mne":"tele远，传送 + phone声音 → 远方声音传过来 → 电话"},{"word":"telescope","ipa":"/ˈtelɪskoʊp/","pos":"n.","def":"望远镜","sen":"You can see many distant stars through the telescope.","trans":"通过望远镜，你可以看到许多遥远的星星。","mne":"tele远，传送 + scope看 → 看远方 → 望远镜"},{"word":"television","ipa":"/ˈtelɪvɪʒn/","pos":"n.","def":"电视（机）；电视节目；电视行业","sen":"We can watch the games on television.","trans":"我们可以通过电视看球赛。","mne":"tele电 + vis看 + ion表名词 → television电视（机）"},{"word":"tell","ipa":"/tel/","pos":"v.","def":"说，告诉；讲述；辨别","sen":"She is telling a story to her two children.","trans":"她在给两个孩子讲故事。","mne":""},{"word":"teller","ipa":"/ˈtelər/","pos":"n.","def":"出纳员","sen":"Tellers deal with customers face-to-face in the bank, including giving and receiving cash.","trans":"银行出纳员与客户面对面打交道，包括给出和收取现金。","mne":""},{"word":"temper","ipa":"/ˈtempər/","pos":"n.","def":"脾气，性情；  v.使缓和","sen":"Stuck in traffic for over an hour, the man began to lose his temper.","trans":"堵车一个多小时了，这个男人开始发火了。","mne":"temper=tempor时间；节制；调节 → 不同的时间不同的心情 → temper脾气；心情；调和"},{"word":"temperature","ipa":"/ˈtemprətʃər/","pos":"n.","def":"温度；气温；某人的体温（尤指用来检测是否生病）","sen":"The temperature of my phone is high enough to cook eggs.","trans":"我的手机温度好高，都可以煎蛋了。","mne":"tempera克制自己 + ture名词后缀 → 可管控自己的 → temperature气温；体温"},{"word":"temple","ipa":"/ˈtempl/","pos":"n.","def":"庙宇，寺院；圣殿，神殿；太阳穴","sen":"People usually go to temples to pray for good fortune.","trans":"人们经常去寺庙祈求好运。","mne":"tem切割，隔断 + ple → 被独立隔断的地方 → temple庙宇"},{"word":"temporary","ipa":"/ˈtempəreri/","pos":"adj.","def":"临时的","sen":"The tent on the car is a temporary home for us.","trans":"车顶上的帐篷是我们的临时居所。","mne":"tempor时间 + ary形容词后缀 → 有时间性的 → temporary临时的"},{"word":"tempt","ipa":"/tempt/","pos":"v.","def":"诱惑","sen":"The squirrel is easily tempted by the acorn.","trans":"这只松鼠很容易被一颗橡子引诱。","mne":""},{"word":"temptation","ipa":"/tempˈteɪʃn/","pos":"n.","def":"诱惑，引诱","sen":"He gave in to his temptation to try the desserts.","trans":"他没能抵抗住这些甜点的诱惑。","mne":"tempt诱惑 + ation名词后缀 → temptation诱惑，引诱"},{"word":"ten","ipa":"/ten/","pos":"num.","def":"十，十个","sen":"There are ten girls standing together.","trans":"有10个女孩正站在一起。","mne":""},{"word":"tend","ipa":"/tend/","pos":"v.","def":"照顾，照料；往往会发生某事","sen":"They tend the tree with care.","trans":"他们小心地照料这棵树。","mne":""},{"word":"tendency","ipa":"/ˈtendənsi/","pos":"n.","def":"趋向，趋势，倾向","sen":"There is an increasing tendency in our sales.","trans":"我们的销量有增长的趋势。","mne":"tend倾向 + ency名词后缀；状态 → tendency倾向"},{"word":"tender","ipa":"/ˈtendər/","pos":"adj.","def":"温柔的；柔弱的，脆弱的；嫩的；  n.煤水车；  v.提出（希望对方接受的意见等）","sen":"You have to be soft and tender with the baby.","trans":"你得对婴儿温柔呵护。","mne":"tend伸，伸出 + er形容词后缀 → 刚伸出的嫩芽 → tender嫩的，柔软的，温柔的"},{"word":"tennis","ipa":"/ˈtenɪs/","pos":"n.","def":"网球（运动）","sen":"My father taught me how to play tennis.","trans":"我父亲教我怎样打网球。","mne":""},{"word":"tense","ipa":"/tens/","pos":"adj.","def":"紧张的；拉紧的；  n.时态","sen":"I feel really tense about the coming exam.","trans":"我真的对即将来临的考试感到紧张。","mne":"tense=tens伸展 → 绷紧的，紧张的"},{"word":"tension","ipa":"/ˈtenʃn/ ","pos":"n.","def":"紧张，不安","sen":"There was tension in the air as they waited to be interviewed.","trans":"他们等候面试时，空气中弥漫着紧张的气氛。","mne":"tens=tense拉紧的，紧张的 + ion状态 → 紧张"},{"word":"tent","ipa":"/tent/","pos":"n.","def":"帐篷","sen":"The couple put up a tent beside the river.","trans":"那对夫妇在河边支起了帐篷。","mne":""},{"word":"term","ipa":"/tɜːrm/","pos":"n.","def":"学期；术语；期限；（pl.）条款；  v.把……称为","sen":"The autumn term in China begins from September 1st.","trans":"中国的秋季学期是从9月1日开始的。","mne":""},{"word":"terminal","ipa":"/ˈtɜːrmɪnl/","pos":"n.","def":"终点站；  adj.末端的；晚期的","sen":"Our bus will arrive at the terminal around 6 pm.","trans":"我们的公交车将在晚上6点左右到达终点站。","mne":"termin终端 + al形容词词尾 → terminal终端的；末端的"},{"word":"terminate","ipa":"/ˈtɜːrmɪneɪt/","pos":"v.","def":"使结束，终止","sen":"We terminated the contract to end our cooperation.","trans":"我们终止了合同来结束合作。","mne":"termin终端 + ate动词后缀 → terminate终结"},{"word":"terrible","ipa":"/ˈterəbl/","pos":"adj.","def":"非常严重的，糟糕的；极糟的；可怕的，骇人的","sen":"Thousands of eggs were broken in the terrible traffic accident.","trans":"在这场严重的车祸中，数以千计的鸡蛋碎了。","mne":"terr怕 + ible…的 → terrible可怕的"},{"word":"terrific","ipa":"/təˈrɪfɪk/","pos":"adj.","def":"极好的；（尺寸或程度）极其巨大的，大得惊人的","sen":"The little girl feels terrific about the picnic.","trans":"这个小女孩对这次野餐感觉棒极了。","mne":"terr怕 + ific……的 → 好到了让人害怕的地步 → terrific极好的"},{"word":"territory","ipa":"/ˈterətɔːri/ ","pos":"n.","def":"地区，领土","sen":"The dog's pee helps to mark its territory.","trans":"狗狗通过撒尿来标记自己的领土。","mne":"territ=terr土地 + ory场所、范围 → 地的范围 → territory领土"},{"word":"terror","ipa":"/ˈterər/","pos":"n.","def":"恐怖，惊骇","sen":"They shouted in terror when they saw the spider.","trans":"当看见蜘蛛时，他们吓得尖叫起来。","mne":"terr战栗 + or名词后缀 → terror恐怖"},{"word":"terrorism","ipa":"/ˈterərɪzəm/","pos":"n.","def":"恐怖主义","sen":"Their acts of terrorism have caused great pain and loss to this country.","trans":"他们的恐怖主义行径给这个国家造成了巨大的痛苦和损失。","mne":"terr恐，怕 ＋ or人 ＋ ism...主义 → terrorism恐怖主义，恐怖行动"},{"word":"terrorist","ipa":"/ˈterərɪst/","pos":"n.","def":"恐怖主义者","sen":"The durian terrorist is trying to attack other fruits.","trans":"榴莲恐怖分子正试图攻击其他水果。","mne":"terror恐怖 + ist名词后缀：人 → terrorist恐怖分子"},{"word":"test","ipa":"/test/","pos":"v.","def":"试验；测验，测试；  n.试验；测验，测试","sen":"I will collect some soil to test later.","trans":"稍后我会取一些土壤进行试验。","mne":""},{"word":"text","ipa":"/tekst/","pos":"n.","def":"【计】文本；正文，原文，课文","sen":"Processing and analyzing text data is a common task in natural language processing and sentiment analysis.","trans":"处理和分析文本数据是自然语言处理和情感分析中的常见任务。","mne":""},{"word":"than","ipa":"/ðæn/","pos":"prep.","def":"比；  conj.比","sen":"As you can see, I'm heavier than my little sister.","trans":"如你看到的那样，我比妹妹要重一些。","mne":""},{"word":"thank","ipa":"/θæŋk/","pos":"v.","def":"感谢","sen":"Thank you for your gift!","trans":"谢谢你的礼物。","mne":""},{"word":"that","ipa":"/ðæt/","pos":"pron.","def":"那，那个；  adv.那样，那么","sen":"Do you want this book or that one?","trans":"你想要这本书还是那一本？","mne":""},{"word":"the","ipa":"/ðə/","pos":"art.","def":"这（表示特指），那 (指已提到或易领会到的人或事物)","sen":"Can you see the house?","trans":"你看到那栋房子了吗？","mne":""},{"word":"theater","ipa":"/ˈθiːətər/","pos":"n.","def":"戏院，电影院，剧场（=theatre）","sen":"The theater quickly emptied when the performance ended.","trans":"表演结束之后，戏院很快就空了。","mne":"thea看见 + ter=tron表地点 → theater剧场 "},{"word":"theatre","ipa":"/ˈθiːətər/","pos":"n.","def":"戏院，剧院（=theater）；电影院","sen":"Let's go to the theatre and watch a play!","trans":"我们去剧院看戏吧！","mne":""},{"word":"their","ipa":"/ðer/","pos":"det.","def":"她们的，他们的，它们的","sen":"They are exchanging their gifts.","trans":"她们在交换她们的礼物。","mne":""},{"word":"theirs","ipa":"/ðerz/","pos":"pron.","def":"他们的（所有物），属于他们的（东西）","sen":"Now, the big house is theirs!","trans":"现在，这栋大房子属于他们了。","mne":"their他们的 + s所有格后缀 → theirs他们的（所有物）"},{"word":"them","ipa":"/ðəm/","pos":"pron.","def":"（宾格）他们，她们，它们","sen":"Both of them enjoy the meal.","trans":"两个孩子都很喜欢这顿饭。","mne":""},{"word":"themselves","ipa":"/ðəmˈselvz/","pos":"pron.","def":"他/她/它们自己","sen":"The old couple are holding a photo of themselves taken 50 years ago.","trans":"这对老夫妻正拿着一张他们自己在50年前拍的照片。","mne":"them他们+selves自己的复数 → 他们自己,"},{"word":"then","ipa":"/ðen/","pos":"adv.","def":"然后；当时，那时","sen":"Type in your password, then take out your money.","trans":"输入你的密码，然后取走你的钱。","mne":""},{"word":"theory","ipa":"/ˈθiːəri/","pos":"n.","def":"理论，原理；学说","sen":"It can be inferred from his theory that the universe is expanding.","trans":"我们可以从他的理论推测出宇宙在膨胀。","mne":"theor思考 + y抽象名词词尾 → theory理论，原理；学说"},{"word":"therapy","ipa":"/ˈθerəpi/","pos":"n.","def":"治疗，理疗；疗法","sen":"The man is trying a kind of Chinese therapy.","trans":"这个男人正在尝试一种中医理疗。","mne":"therap治疗 + y表名词 → therapy治疗，理疗"},{"word":"there","ipa":"/ðer/","pos":"adv.","def":"在那里","sen":"Look! There is a bird in the tree.","trans":"看，树上有一只鸟！","mne":"the去，到 + re状语后缀 → there在那里"},{"word":"thereby","ipa":"/ˌðerˈbaɪ/","pos":"adv.","def":"因此；从而","sen":"He ate a lot of junk food and thereby got fat.","trans":"他吃了很多垃圾食品，因此长胖了。","mne":"there在那里 + by后缀 → thereby因此"},{"word":"therefore","ipa":"/ˈðerfɔːr/","pos":"adv.","def":"因此，所以","sen":"The criminal was caught and therefore went to jail.","trans":"罪犯已经被抓住了，因此他被送入了监狱。","mne":"there这样 + fore因为 → therefore因此"},{"word":"thermometer","ipa":"/θərˈmɑːmɪtər/","pos":"n.","def":"温度计；体温计","sen":"The man used a thermometer to take his temperature.","trans":"这个男人用一支温度计来测量体温。","mne":"thermo热 + meter计量，测量 → thermometer温度计，寒暑表"},{"word":"these","ipa":"/ðiːz/","pos":"adj.","def":"这些的","sen":"I bought these items this morning.","trans":"今天早上我买了这些东西。","mne":""},{"word":"thesis","ipa":"/ˈθiːsɪs/","pos":"n.","def":"论题，论点；（学位）论文","sen":"The latest findings support the thesis of natural selection.","trans":"这些最新发现证实了自然选择这一论点。","mne":"thesis=thet安排，放置 → 放好的研究主题 → thesis论文；命题"},{"word":"they","ipa":"/ðeɪ/","pos":"pron.","def":"她们，他们，它们","sen":"\"Where are your parents?\" \"They went on a trip.\"","trans":"“你父母在哪儿？” “他们去旅游了。”","mne":""},{"word":"thick","ipa":"/θɪk/","pos":"adj.","def":"厚的；稠的，浓的","sen":"The study material for the final exam is surprisingly this thick!","trans":"期末考试要复习的资料居然有这么厚！","mne":""},{"word":"thief","ipa":"/θiːf/","pos":"n.","def":"小偷；窃贼","sen":"A thief is stealing the girl's phone.","trans":"一个小偷正在偷这个女孩的手机。","mne":""},{"word":"thin","ipa":"/θɪn/","pos":"adj.","def":"瘦的；稀薄的，淡的","sen":"He became very thin due to work stress.","trans":"他因工作压力变得很瘦。","mne":""},{"word":"thing","ipa":"/θɪŋ/","pos":"n.","def":"东西，事物；事情，事件，事态","sen":"These are different things that people need in daily life.","trans":"这些都是人们在日常生活中所需的不同物品。","mne":""},{"word":"think","ipa":"/θɪŋk/","pos":"v.","def":"认为；思考，想，思索","sen":"The person is thinking about a question.","trans":"这个人正在考虑一个问题。","mne":""},{"word":"third","ipa":"/θɜːrd/","pos":"n.","def":"三分之一；  adj.第三的","sen":"One third of the pie chart is orange.","trans":"饼图的三分之一是橘色的。","mne":""},{"word":"thirsty","ipa":"/ˈθɜːrsti/","pos":"adj.","def":"口渴的；渴望的","sen":"The girl is so thirsty wandering in the desert.","trans":"女孩在沙漠里漫无目的地走着，渴极了。","mne":"thirst口渴 + y……的 → thirsty口渴的，渴望的"},{"word":"thirteen","ipa":"/ˌθɜːrˈtiːn/","pos":"num.","def":"十三","sen":"There's a number thirteen on my shirt.","trans":"我的T恤上印有数字13。","mne":"thir=three三 + teen十几 → thirteen十三"},{"word":"thirty","ipa":"/ˈθɜːrti/","pos":"num.","def":"三十","sen":"The chef was thirty years old.","trans":"主厨三十岁了。","mne":"thir三 + ty十 → thirty三十"},{"word":"this","ipa":"/ðɪs/","pos":"det.","def":"这，这个；  adv.这样，这么","sen":"This car is very fast.","trans":"这部车非常快。","mne":""},{"word":"thorough","ipa":"/ˈθɜːroʊ/","pos":"adj.","def":"彻底的，完全的；详尽的，细致的","sen":"A thorough brushing will give you fresh breath.","trans":"彻底的刷牙可以使你口气清新。","mne":""},{"word":"thoroughly","ipa":"/ˈθɜːrəli/","pos":"adv.","def":"彻底地；完全","sen":"You need wash the hair thoroughly after using shampoo. ","trans":"每次用洗发剂洗发后都要彻底冲干净。","mne":""},{"word":"those","ipa":"/ðoʊz/","pos":"det.","def":"那些","sen":"Look, those birds are flying high in the sky.","trans":"看，那些鸟正在天空中展翅高飞。","mne":""},{"word":"though","ipa":"/ðoʊ/","pos":"conj.","def":"虽然，尽管","sen":"Even though life is not entirely satisfactory, we still need to maintain optimism.","trans":"尽管生活不尽人意，但我们还是要保持乐观。","mne":""},{"word":"thought","ipa":"/θɔːt/","pos":"n.","def":"思想，想法；  v.想，以为（think的过去式和过去分词）；思考","sen":"He has many thoughts about his future.","trans":"他对自己的未来有很多想法。","mne":""},{"word":"thoughtful","ipa":"/ˈθɔːtfl/","pos":"adj.","def":"体贴的，周到的；沉思的","sen":"Her boyfriend is very thoughtful.","trans":"她的男朋友非常体贴。","mne":"thought想法，思考 + ful形容词后缀 → thoughtful体贴的，沉思的"},{"word":"thousand","ipa":"/ˈθaʊznd/","pos":"n.","def":"【数】千","sen":"Let's count to a thousand.","trans":"让我们数到一千。","mne":""},{"word":"thread","ipa":"/θred/","pos":"n.","def":"线；头绪，线索，思路；  v.穿线于；穿过","sen":"I can use these colorful threads to make knitted scarves.","trans":"我能用这些五颜六色的线织成围巾。","mne":""},{"word":"threat","ipa":"/θret/","pos":"n.","def":"威胁，恐吓；凶兆，坏事发生的可能","sen":"The big guy is making a threat to the man in blue.","trans":"这个大块头正在威胁那个穿蓝衣服的人。","mne":""},{"word":"threaten","ipa":"/ˈθretn/","pos":"v.","def":"威胁；恐吓","sen":"The landlord threatened to kick out the tenant if he didn't pay the rent.","trans":"房东威胁租客，如果不付房租就把他赶出去。","mne":"threat威胁 + en动词后缀 → threaten威胁，恐吓"},{"word":"three","ipa":"/θriː/","pos":"num.","def":"三，三个","sen":"This hand gesture represents the number three.","trans":"这一手势代表数字三。","mne":""},{"word":"thrill","ipa":"/θrɪl/","pos":"n.","def":"兴奋；震颤；引起激动的事物；  v.激动；（使）非常兴奋","sen":"It's quite a thrill to play with a virtual reality headset.","trans":"玩VR头盔是一件令人兴奋不已的事情。","mne":""},{"word":"thrive","ipa":"/θraɪv/","pos":"v.","def":"繁荣，兴旺；茁壮成长 ","sen":"Today, this city continues to thrive.","trans":"如今，这座城市继续繁荣发展。","mne":""},{"word":"throat","ipa":"/θroʊt/","pos":"n.","def":"咽喉，喉咙","sen":"I had a sore throat after I caught a cold.","trans":"我感冒后喉咙很疼。","mne":""},{"word":"throne","ipa":" /θrəʊn/","pos":"n.","def":"王位；宝座","sen":"The king is sitting on the throne.","trans":"国王正坐在王座上。","mne":""},{"word":"through","ipa":"/θruː/","pos":"prep.","def":"通过；  adv.彻底；  adj.直通的","sen":"I can run through brick walls—what can you do?","trans":"我能奔跑着穿过砖墙——你能干什么？","mne":""},{"word":"throughout","ipa":"/θruːˈaʊt/","pos":"prep.","def":"到处；到处；全部；贯穿，遍及；自始至终","sen":"The Internet's base stations have been built throughout the world.","trans":"互联网的基站遍布世界各地。","mne":"through通过 + out在外部 → 走到底最后到外面 → throughout遍及，到处"},{"word":"throw","ipa":"/θroʊ/","pos":"v.","def":"扔，抛，投掷；  n.投掷","sen":"The two kids are throwing balls to each other.","trans":"这两个孩子在互相扔球。","mne":""},{"word":"thumb","ipa":"/θʌm/","pos":"n.","def":"大拇指","sen":"The fracture of the thumb can affect the grip strength.","trans":"大拇指的骨折会影响握力。","mne":""},{"word":"thunder","ipa":"/ˈθʌndər/","pos":"n.","def":"雷，雷声；轰隆声；  v.大声斥责","sen":"Don't stand under a tree when there is thunder. Lightning might strike you.","trans":"打雷时不要站在树下，闪电可能会击中你。","mne":""},{"word":"thursday","ipa":"/ˈθɜːrzdeɪ/","pos":"n.","def":"星期四","sen":"Tomorrow is Thursday.","trans":"明天是星期四。","mne":""},{"word":"thus","ipa":"/ðʌs/","pos":"adv.","def":"因此；这样，如此","sen":"He exercises every day and thus has managed to lose some weight.","trans":"他每天都锻炼，因此减肥成功了。","mne":""},{"word":"ticket","ipa":"/ˈtɪkɪt/","pos":"n.","def":"票，券；车票","sen":"They got two tickets to fly back.","trans":"他们有两张返程的机票。","mne":""},{"word":"tide","ipa":"/taɪd/ ","pos":"n.","def":"潮汐；潮流","sen":"The tide is going out, leaving the beach soft and clean.","trans":"潮水退去了，海滩变得柔软又干净。","mne":""},{"word":"tidy","ipa":"/ˈtaɪdi/","pos":"adj.","def":"整洁的；整齐的","sen":"The living room looked so tidy after mom cleaned it.","trans":"妈妈打扫后，客厅看起来如此干净整洁。","mne":"tid=tide季节，时间 + y形容词后缀 → 符合季节和时间规律 → tidy整洁的"},{"word":"tie","ipa":"/taɪ/","pos":"n.","def":"领带；联系，关系，纽带；平局；  v.绑，捆；系","sen":"I finally learned how to wear my tie.","trans":"我终于学会了如何系领带。","mne":" "},{"word":"tiger","ipa":"/ˈtaɪɡər/","pos":"n.","def":"老虎","sen":"The tiger is a large wild animal.","trans":"老虎是一种大型野生动物。","mne":""},{"word":"tight","ipa":"/taɪt/","pos":"adj.","def":"紧身的，紧的；  adv.紧紧地，牢固地","sen":"Oh no, this sweater is too tight for me.","trans":"哦不，这件线衣对我来说太紧了。","mne":""},{"word":"till","ipa":"/tɪl/","pos":"prep.","def":"直到……才；  conj.直到……才","sen":"He continued working till night.","trans":"他一直工作到了晚上。","mne":""},{"word":"time","ipa":"/taɪm/","pos":"n.","def":"时间；次数；时期，时代，年代；  v.计时，定时；安排……的时间；  adj.时间的；定时的；分期的","sen":"Look at the time! I'm late again! My boss is going to kill me.","trans":"看看时间！我又迟到了！我老板会杀了我的。","mne":""},{"word":"timing","ipa":"/ˈtaɪmɪŋ/","pos":"n.","def":"时机；时间的安排","sen":"With perfect timing, he captured the perfect shot of the smile.","trans":"他在完美的时机抓拍下了完美的笑容。","mne":""},{"word":"tin","ipa":"/tɪn/","pos":"n.","def":"罐头；锡","sen":"The kids like using tins as telephones.","trans":"孩子们喜欢拿罐子当电话。","mne":""},{"word":"tiny","ipa":"/ˈtaɪni/","pos":"adj.","def":"微小的，很小的；极小的；微量的","sen":"The tiny girl sat on his shoulder.","trans":"袖珍的爱丽丝坐在疯帽子的肩上。（《爱丽丝梦游仙境》）","mne":"tin=tine尖齿 + y表形容词 → tiny微小的"},{"word":"tip","ipa":"/tɪp/","pos":"n.","def":"小费；诀窍，建议；指示，指点；尖端；  v.给小费","sen":"He gave the porter a 5-dollar tip.","trans":"他给了那名行李员五美元的小费。","mne":""},{"word":"tire","ipa":"/ˈtaɪər/","pos":"n.","def":"（=tyre）轮胎，车胎；  v.使疲倦","sen":"The strange guy rolls a tire out into the road.","trans":"狂鼠扔出了一个轮胎（其实是炸弹）。","mne":""},{"word":"tired","ipa":"/ˈtaɪərd/","pos":"adj.","def":"累的，疲倦的，疲劳的","sen":"He is feeling really tired.","trans":"他感到非常疲劳。","mne":"tire使...劳累 + d → tired疲劳的"},{"word":"tissue","ipa":"/ˈtɪʃuː/","pos":"n.","def":"纸巾；（人、动植物细胞的）组织","sen":"The little girl uses a tissue when she sneezes.","trans":"打喷嚏时，小女孩用了一张纸巾。","mne":""},{"word":"title","ipa":"/ˈtaɪtl/","pos":"n.","def":"标题；  v.授予……称号","sen":"She read a book whose title shows it's about a woman born in 1982.","trans":"她读了一本书，书名表明这本书和一位在1982年出生的女性有关。","mne":""},{"word":"to","ipa":"/tuː/","pos":"prep.","def":"到；向，往；至……，到……（时间）；于……","sen":"Welcome to Beijing!","trans":"欢迎到北京来玩。","mne":""},{"word":"toast","ipa":"/toʊst/","pos":"n.","def":"敬酒；干杯；  v.为……干杯；烤；烘","sen":"He made a toast at the wedding.","trans":"夏洛克在华生的婚礼上说了祝酒词。","mne":""},{"word":"tobacco","ipa":"/təˈbækoʊ/","pos":"n.","def":"烟草，烟叶","sen":"Tobacco is made up of dried leaves.","trans":"烟草是由干叶片制成的。","mne":""},{"word":"today","ipa":"/təˈdeɪ/","pos":"n.","def":"今天；  adv.在今天","sen":"Today is the day for me to pay my taxes.","trans":"今天是我要交税的日子。","mne":""},{"word":"toe","ipa":"/toʊ/","pos":"n.","def":"脚趾；  v.用脚尖走","sen":"When I drop a rock on my foot, every single toe hurts.","trans":"当我把石头砸到脚上的时候，每个脚趾都疼。","mne":""},{"word":"together","ipa":"/təˈɡeðər/","pos":"adv.","def":"一起，在一起","sen":"This place is even more beautiful to me because we're here together.","trans":"因为我们在一起，所以这个地方变得分外美丽。","mne":"to去 + gether聚集 → 聚集在一起 → together一起"},{"word":"toilet","ipa":"/ˈtɔɪlət/","pos":"n.","def":"马桶；厕所，卫生间","sen":"The boy is cleaning the toilet.","trans":"那个男孩正在清洗马桶。","mne":"toil网 + et小词后缀 → 用作梳妆台台布的小块薄麻布 → 梳洗引申到马桶"},{"word":"tolerance","ipa":"/ˈtɑːlərəns/","pos":"n.","def":"忍耐力","sen":"I've had to develop a tolerance for loud noise at home.","trans":"我不得不在家养成耐受巨大噪声的能力。","mne":"toler容忍 + ance表示状态、情况、性质、行为 → tolerance忍受，容忍"},{"word":"tolerant","ipa":"/ˈtɑːlərənt/","pos":"adj.","def":"容忍的；宽容的","sen":"He is tolerant of his naughty cat.","trans":"他对他淘气的小猫很容忍。","mne":"toler容忍 + ant形容词后缀 → tolerant心胸宽大的"},{"word":"tolerate","ipa":"/ˈtɑːləreɪt/","pos":"v.","def":"忍受，容忍","sen":"They have to tolerate the bad smell in the elevator.","trans":"他们不得不忍受电梯里的臭味。","mne":"toler容忍 + ate动词后缀 → tolerate容忍"},{"word":"tomato","ipa":"/təˈmeɪtoʊ/","pos":"n.","def":"番茄，西红柿","sen":"I washed some tomatoes.","trans":"我洗了一些西红柿。","mne":""},{"word":"tomorrow","ipa":"/təˈmɔːroʊ/","pos":"adv.","def":"在明天，在明日；  n. 明天","sen":"We'll spend the Christmas Day together tomorrow.","trans":"明天我们会一起过圣诞节。","mne":"to在...时 + morrow早晨 → 到下一个早晨 → tomorrow明天"},{"word":"ton","ipa":"/tʌn/","pos":"n.","def":"[数]吨","sen":"One ton is equal to 1,000 kilograms.","trans":"一吨等于1 000千克。","mne":""},{"word":"tone","ipa":"/təʊn/","pos":"n.","def":"语气；语调；色调；  v.使更健壮","sen":"The little boy learned to use a more polite tone when speaking to his mother.","trans":"这个小男孩学会用更礼貌的语气和母亲说话。","mne":""},{"word":"tongue","ipa":"/tʌŋ/","pos":"n.","def":"舌头；语言，说话方式","sen":"The boy sticks out his tongue to make a face to me.","trans":"男孩伸出舌头来对我做鬼脸。","mne":""},{"word":"tonight","ipa":"/təˈnaɪt/","pos":"adv.","def":"今晚；  n.今晚，今夜","sen":"He is watching the news tonight.","trans":"他今晚在看新闻。","mne":""},{"word":"too","ipa":"/tuː/","pos":"adv.","def":"也，而且","sen":"I will eat one too!","trans":"我也要吃一个！","mne":""},{"word":"tool","ipa":"/tuːl/","pos":"n.","def":"工具","sen":"We have all kinds of useful tools.","trans":"我们有各种各样的实用工具。","mne":""},{"word":"tooth","ipa":"/tuːθ/","pos":"n.","def":"牙齿；齿状物","sen":"Every tooth was straight and white.","trans":"每颗牙齿都整齐洁白。","mne":""},{"word":"top","ipa":"/tɑːp/","pos":"n.","def":"顶部，顶端；  v.胜过；  adj.（位置、级别或程度）最高的","sen":"He stands on the top of the mountain.","trans":"他站在山顶上。","mne":""},{"word":"topic","ipa":"/ˈtɑːpɪk/","pos":"n.","def":"话题，主题；题目，标题","sen":"He wrote down a topic for us to discuss.","trans":"他写下一个主题供我们讨论。","mne":""},{"word":"torch","ipa":"/tɔːrtʃ/","pos":"n.","def":"手电筒；火把，火炬","sen":"He is holding up a flaming torch to throw light on the wall.","trans":"他正举着燃烧的火把将墙面照亮。","mne":""},{"word":"torture","ipa":"/ˈtɔːrtʃər/","pos":"v.","def":"折磨；对……施以酷刑，拷问；  n.酷刑，折磨","sen":"My friend tortured us with her terrible singing.","trans":"我朋友用她糟糕的歌声折磨我们。","mne":"tort扭转 + ure表名词 → 扭曲别人 → torture 折磨"},{"word":"total","ipa":"/ˈtoʊtl/","pos":"adj.","def":"整个的，总体的；  n.总数；  v.合计，总共","sen":"What's the total number of ducks in the pond?","trans":"池塘里一共有多少只鸭子呢？","mne":"tot全部 + al表形容词 → total总体的"},{"word":"totally","ipa":"/ˈtoʊtəli/","pos":"adv.","def":"完全地，全部地，彻底地","sen":"The moon is totally blocking the sun's light.","trans":"月球完全阻挡了射到地面的阳光。","mne":"tot合计 + ally...地 → totally完全地"},{"word":"touch","ipa":"/tʌtʃ/","pos":"v.","def":"触，碰，摸；  n.触觉","sen":"He is touching her belly to feel the baby moving.","trans":"他想摸摸她的肚子来感受宝宝的移动。","mne":""},{"word":"tough","ipa":"/tʌf/","pos":"adj.","def":"健壮的；棘手的；严厉的","sen":"She is a tough and ambitious athlete. ","trans":"她是一位健壮且有抱负的运动员。","mne":""},{"word":"tour","ipa":"/tʊr/","pos":"v.","def":"旅游；做巡回演出；  n.巡游","sen":"The family is planning to tour around the world together.","trans":"这家人正计划一起环游世界。","mne":"tour=turn旋转；迂回 → 转着玩 → tour旅游"},{"word":"tourism","ipa":"/ˈtʊrɪzəm/","pos":"n.","def":"旅游业","sen":"The beach is a popular location for tourism.","trans":"沙滩是旅游胜地。","mne":"tour旅行 + ism名词后缀  → tourism 旅游"},{"word":"tourist","ipa":"/ˈtʊrɪst/ ","pos":"n.","def":"游客","sen":"The tourists enjoyed traveling to new places.","trans":"这些旅行者喜欢去新地方旅行。","mne":"tour旋转；迂回 ＋ ist表示人 → tourist旅游者"},{"word":"toward","ipa":"/tɔːrd/","pos":"prep.","def":"向；朝；对于","sen":"The little girl is walking toward her father.","trans":"这个小女孩正向爸爸走去。","mne":"to朝，向 + ward副词后缀，表方向 → toward向"},{"word":"towards","ipa":"/tɔːrdz/","pos":"prep.","def":"向；朝，对着；关于","sen":"He is running towards his goal.","trans":"他正向着他的目标奔去。","mne":""},{"word":"towel","ipa":"/ˈtaʊəl/","pos":"n.","def":"毛巾，手巾","sen":"She uses a blue towel to dry her hair.","trans":"她用一条蓝色的毛巾擦头发。","mne":""},{"word":"tower","ipa":"/ˈtaʊər/","pos":"n.","def":"塔，楼塔；  v.高耸；胜过；高于，超过","sen":"All the lights of this tower will be on at night.","trans":"一到晚上，这座塔的灯就会被全部点亮。","mne":""},{"word":"town","ipa":"/taʊn/","pos":"n.","def":"城镇，市镇，集镇","sen":"I grew up in a seaside town.","trans":"我在一个海滨小镇长大。","mne":""},{"word":"toy","ipa":"/tɔɪ/","pos":"n.","def":"玩具；  v.玩弄","sen":"I like this toy. It can be used to scare others.","trans":"我喜欢这个玩具，它可以用来吓人。","mne":""},{"word":"trace","ipa":"/treɪs/","pos":"v.","def":"追踪；  n.痕迹","sen":"The police dog traced the scent and located the stolen money.","trans":"这只警犬循着气味找到了被偷走的钱款。","mne":""},{"word":"track","ipa":"/træk/","pos":"v.","def":"跟踪，追赶；  n.足迹；轨道；小路，小径；跑道","sen":"He follows the footprints to track the bad guy.","trans":"他跟着脚印追踪那个坏蛋。","mne":""},{"word":"tractor","ipa":"/ˈtræktər/","pos":"n.","def":"拖拉机，牵引车","sen":"We use tractors to farm.","trans":"我们用拖拉机来耕地。","mne":"tract拉 + or名词后缀，物 → 拉东西 → tractor拖拉机"},{"word":"trade","ipa":"/treɪd/","pos":"n.","def":"贸易，商业；职业，行业；  v.经商，交易；做买卖，交易","sen":"International trade has become a major source of income for this company.","trans":"国际贸易成了这家公司的一项主要收入来源。","mne":""},{"word":"trademark","ipa":"/ˈtreɪdmɑːrk/","pos":"n.","def":"商标","sen":"This is the trademark of a popular APP.","trans":"这是一款很火的应用的商标。","mne":"trade贸易 + mark记号，符号 → trademark商标"},{"word":"tradition","ipa":"/trəˈdɪʃn/ ","pos":"n.","def":"传统，风俗，惯例","sen":"Dragon Boat Festival has many different traditions.","trans":"端午节有许多不同的传统习俗。","mne":"tra过 + di给 + tion名词后缀 → 一代一代地传递 → tradition传统"},{"word":"traditional","ipa":"/trəˈdɪʃənl/","pos":"adj.","def":"传统的","sen":"The kid is dressing in traditional clothing.","trans":"这个小朋友穿着传统的服饰。","mne":""},{"word":"traffic","ipa":"/ˈtræfɪk/","pos":"n.","def":"交通，车流；信息流量；非法买卖，非法交易；  v.买卖","sen":"The cars are hardly moving in the traffic jam.","trans":"车子在交通堵塞中艰难地移动着。","mne":"tra=trans穿过 + ffic摩擦 → 在相互摩擦中穿过 → traffic交通，车流，流量"},{"word":"tragedy","ipa":"/ˈtrædʒədi/ ","pos":"n.","def":"悲剧；灾难","sen":"The car accident was a tragedy for the man.","trans":"这场车祸对这个男人来说是场悲剧。","mne":""},{"word":"trail","ipa":"/treɪl/ ","pos":"n.","def":"小径，路径","sen":"The cyclist is riding on the forest trail.","trans":"自行车手正在森林小径上骑行。","mne":""},{"word":"train","ipa":"/treɪn/ ","pos":"n.","def":"火车，列车；行列；  v.训练；培训","sen":"The train is about to travel through the building.","trans":"列车即将穿楼而过。","mne":""},{"word":"trainer","ipa":"/ˈtreɪnər/","pos":"n.","def":"教练；驯兽师","sen":"His personal trainer is teaching him how to use the fitness equipment correctly.","trans":"他的私人教练正在教他如何正确使用健身器材。","mne":""},{"word":"training","ipa":"/ˈtreɪnɪŋ/","pos":"n.","def":"【计】训练；培训；训练，锻炼","sen":"We use train_test_split function to split the dataset into training and testing sets, with 80% of the data used for training.","trans":"我们使用train_test_split函数将数据集分为训练集和测试集，其中80%的数据用于训练。","mne":""},{"word":"trait","ipa":"/treɪt/","pos":"n.","def":"特性，特征","sen":"The most obvious trait of his appearance is his big nose.","trans":"他最明显的外貌特征就是他的大鼻子。","mne":""},{"word":"transaction","ipa":"/trænˈzækʃən/","pos":"n.","def":"交易；【财】交易，业务","sen":"I paid him and he gave me the house—it was an easy transaction.","trans":"我给他钱，他给我房子——这是一笔轻松的交易。","mne":"trans变换，转移 + action行动 → 交换行动 → 交易"},{"word":"transfer","ipa":"/trænsˈfɜr/, /ˈtrænsfər/","pos":"v.","def":"转移；调任；换乘；  n.转让；转移；汇兑（读作/ˈtrænsfər/）","sen":"The worker transferred the box to another place.","trans":"工人把箱子转移到了另一个地方。","mne":"trans横过，越过 + fer带来 → transfer转移"},{"word":"transform","ipa":"/trænsˈfɔːrm/ ","pos":"v.","def":"改变，转换；改造","sen":"Makeup transformed him into a strikingly handsome man.","trans":"这个男人化妆爆改后变得很帅。","mne":"trans变换，转移 + form形状 → 改变形状 → transform变形"},{"word":"transformation","ipa":"/ˌtrænsfərˈmeɪʃn/","pos":"n.","def":"【化】转化","sen":"The transformation of reactants into products is the key in chemical reactions.","trans":"反应物转化为生成物是化学反应的关键。","mne":"trans变 + form形状 + ation名词后缀 → 转变，变形"},{"word":"transformer","ipa":"/trænsˈfɔːrmər/","pos":"n.","def":"变压器","sen":"These transformers help to send electricity across the grid.","trans":"这些变压器把电传输到整个电网中。","mne":"trans转变 + form形状 + er表人/物 → 变压器，转换器，变形金刚"},{"word":"transit","ipa":"/ˈtrænzɪt/","pos":"n.","def":"运输；运送；  v.穿过，经过","sen":"This truck is used for transit between the two cities.","trans":"这辆卡车用于在这两个城市之间运输货物。","mne":"trans越过 + it走 → 越过……走 → transit 运送，通行"},{"word":"translate","ipa":"/trænsˈleɪt/ ","pos":"v.","def":"翻译；转换","sen":"The girl used a phone app to translate this phrase into English.","trans":"女孩用一款手机应用程序把这个短语翻译成了英文。","mne":"trans交换 + late拿出，带出 → 交换拿出 → translate翻译；转化"},{"word":"translation","ipa":"/trænsˈleɪʃn/","pos":"n.","def":"译本；翻译；转变","sen":"The little boy is trying to do some translation exercises.","trans":"这个小男孩正尝试着做一些翻译练习。","mne":"translat=translate翻译 + ion表行为，状态 → 翻译"},{"word":"transmission","ipa":"/trænsˈmɪʃn/","pos":"n.","def":"传输，发射","sen":"This tower was built for mobile phone signal transmission.","trans":"这座塔是用来传输手机信号的。","mne":"trans横 + miss送 + ion表名词  → 横着送  → transmission传输，发射"},{"word":"transmit","ipa":"/trænsˈmɪt/","pos":"v.","def":"发射；发送；传播","sen":"The tower transmits the TV signal.","trans":"这座塔发射电视信号。","mne":"trans横过，超过 + mit送 → 横着送消息 → transmit传播，传送"},{"word":"transparent","ipa":"/trænsˈpærənt/","pos":"adj.","def":"透明的","sen":"The transparent sterile dressing allows for continuous wound observation without the need for frequent removal.","trans":"透明的无菌敷料允许持续观察伤口，而无需频繁更换。","mne":"trans横过，超过 + par出现 + ent形容词后缀 → 横穿某物能看见 → transparent透明的"},{"word":"transplant","ipa":"/trænsˈplænt/, /ˈtrænsˌplænt/","pos":"v.","def":"移植","sen":"The gardener transplanted the flowers to a sunnier spot.","trans":"园丁将花移植到更阳光的地方。","mne":"trans转移 + plant种植 → transplant移植"},{"word":"transport","ipa":"/trænsˈpɔrt/, /ˈtrænsˌpɔrt/","pos":"v.","def":"运输，运送；  n.运输","sen":"Airplanes, ships, trains and trucks are means of transporting goods.","trans":"飞机、轮船、火车和卡车是运输货物的方式。","mne":"trans转移 + port运 → transport运输"},{"word":"transportation","ipa":"/ˌtrænspərˈteɪʃn/","pos":"n.","def":"运输工具；运输系统；交通；运输","sen":"The common forms of transportation include bus, plane, ship and train.","trans":"常见的运输工具有：汽车、飞机、轮船和火车。","mne":"trans转移 + port拿，运 + ation名词后缀 → 运输，运输业"},{"word":"trap","ipa":"/træp/","pos":"n.","def":"陷阱；险境；圈套；  v.使陷入圈套；困住","sen":"The man is about to fall into the trap!","trans":"这个男人就要陷入圈套了！","mne":""},{"word":"travel","ipa":"/ˈtrævl/","pos":"v.","def":"旅行；行走；  n.旅行，旅游","sen":"My girlfriend and I travelled all over the world.","trans":"我和女友曾环游世界。","mne":""},{"word":"tray","ipa":"/treɪ/","pos":"n.","def":"盘，碟，托盘","sen":"He brought three glasses of water on a tray.","trans":"他用托盘端过来三杯水。","mne":""},{"word":"treasure","ipa":"/ˈtreʒər/ ","pos":"n.","def":"金银财宝；不可多得的人才；  v.珍视，珍爱","sen":"These treasures will make me rich.","trans":"这些财宝会让我富有。","mne":""},{"word":"treat","ipa":"/triːt/","pos":"v.","def":"治疗；请客，款待；对待；  n.款待","sen":"The doctor is carefully treating the wound on the little girl's leg.","trans":"医生正在仔细治疗小女孩腿上的伤。","mne":""},{"word":"treatment","ipa":"/ˈtriːtmənt/ ","pos":"n.","def":"治疗，疗法；对待，待遇","sen":"She is receiving treatment for a hand injury.","trans":"她的手受伤了，正在接受治疗。","mne":"treat处理 + ment名词后缀 → treatment处理，治疗"},{"word":"treaty","ipa":"/ˈtriːti/","pos":"n.","def":"条约；协议","sen":"The two nations declared a ceasefire and penned a peace treaty.","trans":"两个国家停战并签订了和平条约。","mne":"treat处理 + y表名词 → 作出处理的文件 → treaty条约；约定"},{"word":"tree","ipa":"/triː/","pos":"n.","def":"【计】树；树，树木","sen":"The `add_child` method allows you to add child nodes to the tree.","trans":"`add_child`方法允许你向树中添加子节点。","mne":""},{"word":"tremble","ipa":"/ˈtrembl/ ","pos":"v.","def":"颤抖，哆嗦；（因害怕等而）颤抖；  n.颤抖，战栗","sen":"The horror movie made her tremble with fear.","trans":"这个恐怖电影让她害怕得发抖。","mne":"trem颤抖 + ble能...的 → tremble颤抖，哆嗦"},{"word":"tremendous","ipa":"/trəˈmendəs/","pos":"adj.","def":"巨大的；极大的","sen":"I feel the tremendous pressure of car and house loans on my shoulders.","trans":"我感觉肩上扛着巨大的车贷和房贷压力。","mne":"trem颤抖 + end尽头 + ous形容词后缀 → 让人颤抖的 → tremendous可怕的，惊人的"},{"word":"trend","ipa":"/trend/","pos":"n.","def":"趋势；趋向，动向；  v.倾向；走向","sen":"The trend of prices is still going up.","trans":"物价的趋势是仍在上涨。","mne":""},{"word":"trial","ipa":"/ˈtraɪəl/","pos":"n.","def":"审判，审讯；考验；  v.审讯，审判，试验，试用","sen":"The judge in charge of the trial is listening to the lawyers.","trans":"负责此次审判的法官正在听取律师发言。","mne":"tri=try审理 + al名词后缀，表行为 → trial审判"},{"word":"triangle","ipa":"/ˈtraɪæŋɡl/","pos":"n.","def":"三角形","sen":"A triangle has three angles and three sides.","trans":"三角形有三个角和三条边。","mne":"tri三 + angle角 → triangle三角形"},{"word":"tribe","ipa":"/traɪb/","pos":"n.","def":"部落","sen":"The primitive tribe people make the fire with wood.","trans":"原始部落的人用木柴生火。","mne":""},{"word":"trick","ipa":"/trɪk/","pos":"v.","def":"捉弄，戏弄；哄骗；欺骗；  n.恶作剧，诡计，花招；诀窍","sen":"He tricked his brother by pretending to be a ghost.","trans":"他假装成幽灵来捉弄他的弟弟。","mne":""},{"word":"trigger","ipa":"/ˈtrɪɡər/","pos":"n.","def":"（枪等的）扳机；诱因；  v.【计】触发；  v.触发，引发，引起","sen":"Pulling the gun's trigger causes it to fire.","trans":"扣动枪的扳机开火。","mne":""},{"word":"trip","ipa":"/trɪp/","pos":"n.","def":"旅行，旅游；  v.绊倒，失足；轻快地走或跑","sen":"He is going to make a trip by plane.","trans":"他打算坐飞机去旅行。","mne":""},{"word":"triumph","ipa":"/ˈtraɪʌmf/","pos":"n.","def":"胜利，凯旋","sen":"\"I win!\" he shouted in triumph.","trans":"“我赢了！” 他在胜利时喊道。","mne":""},{"word":"troop","ipa":"/truːp/","pos":"n.","def":"军队，部队；群；  v.结队而行","sen":"The statues of the ancient troop are great historic heritage.","trans":"这支古老军队的雕像是伟大的历史遗迹。","mne":""},{"word":"tropical","ipa":"/ˈtrɑːpɪkl/ ","pos":"adj.","def":"热带的","sen":"There is a variety of plants and animals in the tropical rainforest.","trans":"热带雨林中有很多不同种类的动植物。","mne":"tropic回归线 + al形容词后缀 → tropical热带的"},{"word":"trouble","ipa":"/ˈtrʌbl/","pos":"n.","def":"烦恼，忧虑；问题，麻烦；  v.（使）烦恼，麻烦","sen":"My car has broken down; I'm in big trouble now!","trans":"我的车坏了，我现在麻烦大啦！","mne":""},{"word":"troublesome","ipa":"/ˈtrʌblsəm/","pos":"adj.","def":"令人烦恼的，讨厌的；困难的，棘手的","sen":"Frequently feeling the call of nature can be so troublesome for old people.","trans":"对老人来说，总想上厕所实在是令人烦恼。","mne":"trouble烦恼 + some……的 → troublesome令人烦恼的"},{"word":"trousers","ipa":"/ˈtraʊzərz/","pos":"n.","def":"裤子","sen":"She wears a pair of yellow trousers.","trans":"她穿了一条黄色的裤子。","mne":""},{"word":"truck","ipa":"/trʌk/","pos":"n.","def":"卡车；手推车；  v.用卡车装运","sen":"Big trucks carry goods across the country.","trans":"大卡车载着货在乡间穿行。","mne":""},{"word":"true","ipa":"/truː/","pos":"adj.","def":"真实的，真正的","sen":"The true identity of the shadow is a cat.","trans":"影子的真正身份是一只猫。","mne":""},{"word":"truly","ipa":"/ˈtruːli/","pos":"adv.","def":"真诚地，衷心地","sen":"I truly love you from the bottom of my heart!","trans":"我真心爱你，从心底里爱你！","mne":"tru=true真实 + ly表副词 → truly真正地，确实地"},{"word":"trumpet","ipa":"/ˈtrʌmpɪt/","pos":"n.","def":"喇叭，小号；小号声；  v.宣扬；鼓吹，吹嘘","sen":"We are trying our best to play the trumpet!","trans":"我们使出了吃奶的劲儿来吹喇叭！","mne":""},{"word":"trunk","ipa":"/trʌŋk/","pos":"n.","def":"树干；（人）躯干；大衣箱；象鼻","sen":"The bird is feeding on the trunk of the tree.","trans":"小鸟正在树干上进食。","mne":""},{"word":"trust","ipa":"/trʌst/","pos":"v.","def":"信任，相信；盼望，希望；  n.委托","sen":"My boss trusts me so much. I can't let him down.","trans":"我的老板那么信任我，我不能让他失望。","mne":"tru坚固，坚定 + st表名词  → （坚定地）相信  → trust信任"},{"word":"truth","ipa":"/truːθ/","pos":"n.","def":"真相，事实；真实","sen":"The truth is that the \"Batman\" is actually just the cat's shadow.","trans":"真相是这个“蝙蝠侠”只是这只猫的影子。","mne":"tru相信，真实 + th抽象名词 → truth事实，真理"},{"word":"try","ipa":"/traɪ/","pos":"v.","def":"试图，努力；  n.努力，尝试","sen":"The woman is trying on a pair of high heels.","trans":"这个女人正在试穿一双高跟鞋。","mne":""},{"word":"tube","ipa":"/tuːb/","pos":"n.","def":"管子，管道；地铁；电视","sen":"These tubes are made of steel.","trans":"这些管子都是由钢制成的。","mne":""},{"word":"tuesday","ipa":"/ˈtuːzdeɪ/","pos":"n.","def":"星期二","sen":"The first lesson on Tuesday is math.","trans":"周二的第一节课是数学课。","mne":""},{"word":"tuition","ipa":"/tuˈɪʃn/","pos":"n.","def":"学费","sen":"The students are queueing up to pay their tuition fees.","trans":"这些学生在排队交学费。","mne":"tuit保护 + ion表名词 → 受教育的费用 → tuition学费；教导"},{"word":"tune","ipa":"/tuːn/","pos":"n.","def":"曲调，旋律，曲子；调音；  v.调整，校准；给……调音","sen":"Sure, I'll play a little tune for you.","trans":"当然，我会为你弹奏一曲。","mne":""},{"word":"tunnel","ipa":"/ˈtʌnl/","pos":"n.","def":"隧道，地道，地下通道","sen":"The man dug a tunnel, trying to find the gold mine.","trans":"这个男人挖了一条地道，企图找到金矿。","mne":""},{"word":"turkey","ipa":"/ˈtɜːrki/","pos":"n.","def":"火鸡，火鸡肉","sen":"The man is holding a big roast turkey.","trans":"这个男人手里拿着一只大的烤火鸡。","mne":""},{"word":"turn","ipa":"/tɜːrn/","pos":"v.","def":"转动；  n.机会；变化，转变","sen":"The man turned the stone to unlock the door.","trans":"为了打开（奥古公主的）墓门，凯爷转了转面前（标有彼岸花图案）的石盘。（《鬼吹灯之寻龙诀》）","mne":""},{"word":"tutor","ipa":"/ˈtuːtər/","pos":"n.","def":"导师；家庭教师，指导教师；  v.个别指导","sen":"He is a tutor in physics.","trans":"他是物理专业的导师。","mne":"tut保护 + or人 → tutor保护人，导师，教师"},{"word":"tv","ipa":"/ˌtiː ˈviː/","pos":"abbr.","def":"电视（television）","sen":"We can watch TV at my house.","trans":"我们可以在我家看电视。","mne":""},{"word":"twelfth","ipa":"/twelfθ/","pos":"num.","def":"第十二","sen":"It's the boy's twelfth birthday, which means he's arriving at puberty.","trans":"这是他的第十二个生日，意味着他快到青春期了。","mne":"twelf=twelve十二 + th第…/…分之一 → twelfth第十二；十二分之一的"},{"word":"twelve","ipa":"/twelv/","pos":"num.","def":"十二","sen":"There are twelve eggs in a box.","trans":"一盒鸡蛋有十二个。","mne":""},{"word":"twentieth","ipa":"/ˈtwentiəθ/","pos":"num.","def":"第二十","sen":"Today is our twentieth wedding anniversary!","trans":"今天是我们结婚20周年纪念日！","mne":"twenti=twenty二十 + eth第... → twentieth第二十"},{"word":"twenty","ipa":"/ˈtwenti/","pos":"adj.","def":"二十的","sen":"They give twenty percent discount for online payment. Take out your phone!","trans":"在线支付的话可以打八折，快把你手机拿出来！","mne":"twen=two二 + ty十 → twenty二十"},{"word":"twice","ipa":"/twaɪs/","pos":"adv.","def":"两次；两倍","sen":"I go swimming twice a week.","trans":"我一周游两次泳。","mne":"twi二，两 + ce副词后缀，…次 → twice二次"},{"word":"twin","ipa":"/twɪn/ ","pos":"n.","def":"双胞胎之一；  adj.孪生的","sen":"The two girls are twins.","trans":"这两个女孩是双胞胎。","mne":""},{"word":"twist","ipa":"/twɪst/","pos":"v.","def":"扭；歪曲；拧，捻，搓；  n.搓，扭，拧","sen":"The right way to eat this biscuit is to twist it, lick it, then dip it.","trans":"吃这种饼干的正确方式是扭一扭，舔一舔，再泡一泡。","mne":""},{"word":"two","ipa":"/tuː/","pos":"num.","def":"二，两个","sen":"There are two cups of coffee on the table.","trans":"桌上有两杯咖啡。","mne":""},{"word":"type","ipa":"/taɪp/","pos":"n.","def":"类型，种类；  v.打字；成为…的典型","sen":"There are several types of dogs for sale.","trans":"这里有几个种类的狗在售卖。","mne":""},{"word":"typewriter","ipa":"/ˈtaɪpraɪtər/","pos":"n.","def":"打字机","sen":"The author used a typewriter to write the novel.","trans":"作家用打字机来写小说。","mne":"type打字 ＋ writer用来打字的东西 → typewriter打字机"},{"word":"typhoon","ipa":"/taɪˈfuːn/","pos":"n.","def":"台风，强热带风暴","sen":"The trees and houses were blown away by the powerful typhoon.","trans":"树木和房子都被强劲的台风吹走了。","mne":""},{"word":"typical","ipa":"/ˈtɪpɪkl/","pos":"adj.","def":"典型的，有代表性的","sen":"It's typical of many Japanese to eat rice this way.","trans":"这是许多日本人吃米饭的典型方式。","mne":"typ类型 + ical…的 → 成模式的 → typical典型的"},{"word":"typically","ipa":"/ˈtɪpɪkli/","pos":"adv.","def":"一般地，通常地；代表性地，典型地","sen":"Typically, when you travel to Beijing, you would try the roasted duck.","trans":"通常来说，当你去北京旅行时，你会去吃烤鸭。","mne":"typ模式，形状 ＋ ic...的 ＋ ally...地 → typically代表性地；作为特色地"},{"word":"typist","ipa":"/ˈtaɪpɪst/","pos":"n.","def":"（尤指专职）打字员","sen":"The typist is finishing her documents.","trans":"打字员正在完成她的文件。","mne":"typ=type打字 + ist从事某种职业的人 → typist打字员"},{"word":"tyre","ipa":"/ˈtaɪər/","pos":"n.","def":"轮胎，车胎","sen":"A car needs four tyres to drive.","trans":"一辆汽车需要四个轮子来行驶。","mne":""},{"word":"ugly","ipa":"/ˈʌɡli/","pos":"adj.","def":"丑陋的","sen":"I have never seen such an ugly dog as this.","trans":"我从未见过如此丑的狗。","mne":"ug害怕，恐惧 + ly表形容词，有…特质的 → ugly令人不快的；丑陋的"},{"word":"ultimate","ipa":"/ˈʌltɪmət/","pos":"adj.","def":"最终的","sen":"My ultimate goal is to buy a house.","trans":"我的终极目标是买套房子。","mne":"ult(er)那边的 + im最高级后缀 + ate形容词后缀 → 最那边的，最终的"},{"word":"umbrella","ipa":"/ʌmˈbrelə/","pos":"n.","def":"伞，雨伞","sen":"This umbrella is yellow.","trans":"这把伞是黄色的。","mne":"umbr阴影 + ella小东西 → 带来影子的小东西 → umbrella伞"},{"word":"unable","ipa":"/ʌnˈeɪbl/","pos":"adj.","def":"不能的；不会的","sen":"What to do? Obviously I'm unable to climb these stairs in my wheelchair!","trans":"我该怎么办？很明显我坐在轮椅上不能爬楼梯！","mne":"un不 + able能够…的 → unable不能的, 不会的"},{"word":"uncertain","ipa":"/ʌnˈsɜːrtn/","pos":"adj.","def":"不确定的；易变的","sen":"He was uncertain of the correct answer to the multiple choice question.","trans":"他不确定这道选择题的正确答案是哪个。","mne":"un不，没有 ＋ certain确实的 → uncertain不确定的，靠不住的"},{"word":"uncle","ipa":"/ˈʌŋkl/","pos":"n.","def":"伯父，叔父，舅父，姑父，姨父","sen":"My dad and uncle look very much alike.","trans":"我的爸爸和叔叔看起来很像。","mne":""},{"word":"uncomfortable","ipa":"/ʌnˈkʌmfərtəbl/ ","pos":"adj.","def":"不舒服的；不自在的，尴尬的","sen":"She looked uncomfortable at the crowded airport.","trans":"她在机场拥挤的人群中看起来很不自在。","mne":"un不，没有 + com一起 + fort强大、力量 + able形容词后缀，能…的 → 不能一起强大 → uncomfortable不舒服的"},{"word":"unconscious","ipa":"/ʌnˈkɑːnʃəs/ ","pos":"adj.","def":"失去意识的","sen":"We found him unconscious on the floor.","trans":"我们发现他倒在地上，不省人事。","mne":"un表否定 + con共同 + sci知道 + ous…的 → 什么都不知道 → unconscious无意识的，不知不觉的"},{"word":"uncover","ipa":"/ʌnˈkʌvər/","pos":"v.","def":"揭露；移去……的覆盖物，发现","sen":"He uncovered a classified secret to the public.","trans":"他向公众揭露了一个机密。","mne":"un打开，解开 + cover盖子 → uncover揭开盖子"},{"word":"under","ipa":"/ˈʌndər/","pos":"prep.","def":"在……之下；少于，低于","sen":"The cat is hiding under the sofa.","trans":"猫咪正躲在沙发下面。","mne":""},{"word":"underestimate","ipa":"/ˌʌndərˈestɪmeɪt/","pos":"v.","def":"低估；  n.低估；轻视","sen":"The worst thing you can do is underestimate an opponent.","trans":"最严重的错误就是低估对手。","mne":"under不足，不够 + estimate估计 → underestimate估计不足"},{"word":"undergo","ipa":"/ˌʌndərˈɡoʊ/","pos":"v.","def":"经历；遭受，经受（变化、不快等）","sen":"He underwent strict training before he officially became an armed police.","trans":"他在正式成为武警之前接受了严格的训练。","mne":"under下 + go进行 → undergo经历"},{"word":"undergraduate","ipa":"/ˌʌndərˈɡrædʒuət/","pos":"n.","def":"（本科）学生","sen":"The undergraduate has spent four years at university and will hopefully graduate soon.","trans":"这名本科学生已经度过了四年的大学时光并将顺利毕业。","mne":"under低于，不够 + graduate毕业生 → undergraduate沿未毕业者，大学肄业生"},{"word":"underground","ipa":"/ˈʌndərɡraʊnd/ˌ /ˌʌndərˈɡraʊnd/","pos":"adj.","def":"地下的；秘密的；  n.地铁；  adv.在地下；秘密地","sen":"The building has underground parking.","trans":"这栋楼有地下停车场。","mne":"under在…下 + ground地 → underground地下的"},{"word":"underline","ipa":"/ˌʌndərˈlaɪn/","pos":"v.","def":"画线于……之下；强调","sen":"It is a good habit to underline the important parts when you read.","trans":"在阅读时，勾画重要的部分是一个好习惯。","mne":"under在…下 + line线 → 划线于…下"},{"word":"undermine","ipa":"/ˌʌndərˈmaɪn/","pos":"v.","def":"暗中破坏","sen":"Cyber-criminals undermine the Internet's security.","trans":"网络罪犯破坏互联网的安全。","mne":"under在…下 + mine开采 → 挖墙脚 → undermine破坏，损坏"},{"word":"underneath","ipa":"/ˌʌndərˈniːθ/","pos":"prep.","def":"在……下面；  adv.在……底下","sen":"We pass underneath the highway.","trans":"我们从公路下面穿过。","mne":"under下 ＋ neath下面 → underneath在下面"},{"word":"understand","ipa":"/ˌʌndərˈstænd/","pos":"v.","def":"理解，明白","sen":"Ha! I understand now!","trans":"哈！我现在懂了！","mne":"under在下面 + stand站立、立场 → 同一立场的 → understand理解，明白"},{"word":"undertake","ipa":"/ˌʌndərˈteɪk/","pos":"v.","def":"承担，承包；保证；从事","sen":"Companies should undertake greater responsibility for reducing their carbon emissions.","trans":"企业应承担更大的责任来减少碳排放。","mne":"under下 + take接受 → undertake从事"},{"word":"undertaking","ipa":"/ˌʌndərˈteɪkɪŋ/","pos":"n.","def":"事业，企业；承诺，保证","sen":"Having babies is a huge undertaking.","trans":"抚养孩子是一项很重大的事业。","mne":"under下 ＋ tak进行 ＋ ing名词后缀 → undertaking承诺；事业"},{"word":"undo","ipa":"/ʌnˈduː/","pos":"v.","def":"松开，解开；取消，撤销；毁掉","sen":"At the end of the day, the man undoes his tie.","trans":"一天结束后，这个男人松了松领带。","mne":"un除去，解开 + do做 → undo取消，解开"},{"word":"undoubtedly","ipa":"/ʌnˈdaʊtɪdli/","pos":"adv.","def":"毫无疑问地","sen":"Just as the sun rises in the east, it undoubtedly sets in the west.","trans":"正如太阳从东方升起，它肯定会在西方落下。","mne":"un无 ＋ doubt怀疑 ＋ ed形容词后缀 ＋ ly...地 → undoubtedly无容置疑，肯定地"},{"word":"uneasy","ipa":"/ʌnˈiːzi/","pos":"adj.","def":"心神不宁；令人不安的；心神不安的，不自在的；忧虑的","sen":"Insomnia made the man feel uneasy.","trans":"失眠让这个男人感到不安。","mne":"un不 + eas放松 + y形容词后缀 → uneasy心神不安的"},{"word":"unexpected","ipa":"/ˌʌnɪkˈspektɪd/","pos":"adj.","def":"想不到的，意外的","sen":"Something unexpected happened when they were posing.","trans":"当他们在摆造型的时候，让人意想不到的事情发生了。","mne":"un不 ＋ expect期望 ＋ ed“...的” → unexpected想不到的，意外的，突然的"},{"word":"unfair","ipa":"/ˌʌnˈfer/","pos":"adj.","def":"不公平的","sen":"This is unfair! Why is he more important than us!","trans":"这不公平！凭什么他比我们更重要！","mne":"un不 + fair公平的 → unfair不公平的"},{"word":"unfamiliar","ipa":"/ˌʌnfəˈmɪliər/","pos":"adj.","def":"不熟悉的","sen":"The old man is unfamiliar with computers.","trans":"老人对电脑不熟悉。","mne":""},{"word":"unfold","ipa":"/ʌnˈfoʊld/","pos":"v.","def":"展开，伸展；表露，显露","sen":"He unfolds the map to see which way to go next.","trans":"他展开地图，想看看接下来走哪条路。","mne":"un不 + fold折叠 → unfold展现"},{"word":"unfortunate","ipa":"/ʌnˈfɔːrtʃənət/","pos":"adj.","def":"不幸的；  n.不幸的人","sen":"I’m so unfortunate—why does it only rain on me?","trans":"我真不幸，为什么雨只下在我头上？","mne":"un不，没有 + fortun运气 + ate形容词后缀 → unfortunate不幸的"},{"word":"unfortunately","ipa":"/ʌnˈfɔːrtʃənətli/","pos":"adv.","def":"遗憾地，可惜地，不幸地","sen":"Unfortunately, a heavy rain interrupted their romantic dinner.","trans":"不幸的是，一场大雨打断了他们浪漫的晚餐。","mne":"un不 + fortun=fortune运气 + ate造成…的 + ly有…特征的 → unfortunately遗憾的是，可惜的是"},{"word":"uniform","ipa":"/ˈjuːnɪfɔːrm/","pos":"n.","def":"制服，军服；  adj.统一的，一致的","sen":"The singer gave out school uniforms as gifts to fans at the concert.","trans":"歌手在演唱会上把校服当作礼物送给粉丝。","mne":"uni一个，单一 + form形状 → uniform制服"},{"word":"unify","ipa":"/ˈjuːnɪfaɪ/","pos":"v.","def":"使联合，统一","sen":"People are unified when facing natural disasters.","trans":"自然灾害让人们团结起来。","mne":"uni一个，单一 + fy动词后缀，使成为… → unify统一"},{"word":"union","ipa":"/ˈjunjən/ ","pos":"n.","def":"工会；联合；同盟","sen":"The union is trying to protect their rights as workers.","trans":"工会在努力保护他们作为劳动者的权利。","mne":"un单一 + ion名词后缀 → 联成一体 → 联合，工会，联盟"},{"word":"unique","ipa":"/juˈniːk/","pos":"adj.","def":"独一无二的，独特的，特别的","sen":"This square apple looks unique in a pile of round ones.","trans":"这个方苹果在一堆圆苹果中显得独一无二。","mne":"uni一个 + que形容词后缀 → unique独立无二的，独特的"},{"word":"unit","ipa":"/ˈjuːnɪt/","pos":"n.","def":"整体；单元","sen":"We will succeed if we work as a unit.","trans":"如果我们万众一心，就能成功。","mne":""},{"word":"unite","ipa":"/juˈnaɪt/","pos":"v.","def":"团结，联合","sen":"Humans across the globe should unite in their efforts to fight the virus.","trans":"全人类应该团结起来共同抗击病毒。","mne":"uni一个，单一 + te动词后缀，促成 → unite团结，合并"},{"word":"united","ipa":"/juˈnaɪtɪd/","pos":"adj.","def":"团结的，和谐的；联合的，统一的","sen":"The six of us are united and working on a business plan together.","trans":"我们六人团结一致，一起制定商业计划。","mne":"unit单元 + ed形容词后缀 → 统一的，联合的"},{"word":"unity","ipa":"/ˈjuːnəti/","pos":"n.","def":"团结，一致","sen":"Our group's strength lies in our unity.","trans":"我们队伍的力量来源于我们的团结！","mne":"uni一个 + ty名词后缀 → 成为一个整体 → 联合；统一体；团结"},{"word":"universal","ipa":"/ˌjuːnɪˈvɜːrsl/","pos":"adj.","def":"普遍的，全体的；广泛适用的","sen":"Electronic devices such as cellphones are universal now.","trans":"如今像手机这样的电子设备已经得到了普及。","mne":"uni一个 + vers=versus转变 + al具有...性质的 → 变成一个的 → universal普遍的，全体的"},{"word":"universe","ipa":"/ˈjuːnɪvɜːrs/ ","pos":"n.","def":"宇宙，天地万物","sen":"There are a lot of stars in the universe.","trans":"宇宙中有很多星星。","mne":"uni一个 + vers转向 + e → 统一旋转 → universe宇宙"},{"word":"university","ipa":"/ˌjuːnɪˈvɜːrsəti/","pos":"n.","def":"大学","sen":"Tsinghua University is one of the most famous universities in China.","trans":"清华大学是国内最知名的大学之一。","mne":"univers宇宙 + ity名词 → 由宇宙引申为知识，知识之地 → university大学"},{"word":"unjustified","ipa":"/ʌnˈdʒʌstɪfaɪd/","pos":"adj.","def":"不合理的；不正当的","sen":"We believe that Your Highness's faith will not be unjustified.","trans":"我们相信，陛下的信心不会落空。","mne":""},{"word":"unless","ipa":"/ənˈles/","pos":"conj.","def":"除非，如果不","sen":"The river won’t get clean unless we stop polluting it.","trans":"除非我们停止污染，否则这条河不会变干净。","mne":""},{"word":"unlike","ipa":"/ˌʌnˈlaɪk/","pos":"adj.","def":"不同的","sen":"These two men  have muscles that are unlike each other.","trans":"这两个男人的手臂肌肉很不一样。","mne":"un不 + like像 → unlike与……不像、不同"},{"word":"unlikely","ipa":"/ʌnˈlaɪkli/","pos":"adj.","def":"不太可能的","sen":"\"Wow! There are seven twos! It's extremely unlikely to see this many.\"","trans":"哇！竟然有七个2！能看到这么多真是极其罕见。","mne":"un不+likely可能的→unlikely不太可能的"},{"word":"unload","ipa":"/ˌʌnˈloʊd/","pos":"v.","def":"卸（货）","sen":"It's going to take all afternoon to unload these boxes.","trans":"要把这些箱子卸下来得花一个下午的时间。","mne":"un由……中弄出 + load装载 → 把东西从车上弄下来 → unload卸货"},{"word":"unnecessary","ipa":"/ʌnˈnesəseri/","pos":"adj.","def":"不必要的，不需要的，多余的","sen":"Grandma tidied up some unnecessary items.","trans":"外婆整理出一些不必要的杂物。","mne":"un不 + necess必要 + ary 表示有……性质的 → unnecessary不必要的，无用的"},{"word":"unpleasant","ipa":"/ʌnˈpleznt/","pos":"adj.","def":"令人不快的，讨厌的","sen":"There's an unpleasant smell coming out from the refrigerator.","trans":"有股难闻的味道从冰箱里冒了出来。","mne":"un不 + pleas=please快乐 + ant……的 → unpleasant令人不快的"},{"word":"until","ipa":"/ʌnˈtɪl/","pos":"prep.","def":"到……为止；直到（某时刻）为止；  conj.到……为止，直到……才","sen":"He continued working until it got dark.","trans":"他一直工作到天黑。","mne":""},{"word":"unusual","ipa":"/ʌnˈjuːʒuəl/","pos":"adj.","def":"特别的，不常见的","sen":"That guy has an unusual ability! He can fly!","trans":"这个男人有不寻常的能力！他会飞！","mne":"un不 + usual通常的 → unusual不平常的；与众不同的"},{"word":"unwilling","ipa":"/ʌnˈwɪlɪŋ/","pos":"adj.","def":"不愿意的，不情愿的，勉强的","sen":"The dog is unwilling to follow its master.","trans":"这只狗不愿意跟着它的主人走。","mne":"un不 + will愿意 + ing...的 → unwilling不愿意的"},{"word":"up","ipa":"/ʌp/","pos":"adv.","def":"向上，在上面","sen":"My balloon is flying up into the sky!","trans":"我的气球飞上了天空！","mne":""},{"word":"up-to-date","ipa":"/ˌʌp tə ˈdeɪt/","pos":"adj.","def":"时新的，新式的；最新的，现代的","sen":"A smart phone is the most up-to-date way to get important information.","trans":"智能手机是获取重要信息的最新方式。","mne":""},{"word":"upgrade","ipa":"/ʌpˈgreɪd/, /ˈʌpˌgreɪd/","pos":"v.","def":"升级，提升；提高（读作/ʌpˈgreɪd/）","sen":"I decided to upgrade my wardrobe with some trendy pieces this season.","trans":"我决定在这个季节用一些流行单品来升级我的衣橱。","mne":"up向上 + grade步，级 → 向上升级 → 上升，升级"},{"word":"upon","ipa":"/əˈpɑːn/","pos":"prep.","def":"在……上面","sen":"Once upon a time, there was a temple upon a mountain.","trans":"从前有座山，山上有座庙。","mne":"up向上 + on在...上面 → upon在...上面"},{"word":"upper","ipa":"/ˈʌpər/","pos":"adj.","def":"较高的，上面的","sen":"You can see the entire city from the upper floors of the building.","trans":"从大厦的高层，你可以看到整个城市。","mne":""},{"word":"upright","ipa":"/ˈʌpraɪt/","pos":"adj.","def":"直立的，挺直的；正直的","sen":"He sits in an upright position to ease his back.","trans":"他用笔直的姿势坐着来减轻背部不适。","mne":"up向上 ＋ right直 → upright垂直的，正直的"},{"word":"upset","ipa":"/ˈʌpset, /ʌpˈset/","pos":"adj.","def":"苦恼的，沮丧的，心烦意乱的；  v.使苦恼","sen":"The little boy is upset about his test.","trans":"这个小男孩正为考试苦恼。","mne":"up向上 + set安置好 → 把底向上放 → upset打翻"},{"word":"upstairs","ipa":"/ˌʌpˈsterz/","pos":"adv.","def":"往楼上，在楼上；  adj.楼上的；  n.楼上，二楼","sen":"The dog ran upstairs to eat his food.","trans":"狗狗上楼去吃食物。","mne":"upstair在楼上 ＋ s表副词 → upstairs在楼上，往楼上"},{"word":"upward","ipa":"/ˈʌpwərd/","pos":"adv.","def":"向上地；  adj.向上的","sen":"The pilot tried to pull the aircraft into an upward climb.","trans":"飞行员试着驾驶飞机向上爬升。","mne":"up向上 + ward向... → upward向上的"},{"word":"upwards","ipa":"/ˈʌpwərdz/","pos":"adv.","def":"向上；上升，上涨，提高","sen":"The roller coaster was going upwards along the track very fast.","trans":"过山车正沿着轨道向上飞驰。","mne":"up向上 + wards表副词，向... → 向下，朝上"},{"word":"urban","ipa":"/ˈɜːrbən/","pos":"adj.","def":"城市的，城镇的，都市的","sen":"I like urban environments, especially the night scenes.","trans":"我喜欢都市的环境，尤其是夜景。","mne":"urb城市 + an…的 → urban城市的"},{"word":"urbanisation","ipa":"/ˌɜːbənɪ'zeɪʃən/","pos":"n.","def":"都市化","sen":"A guide explained urbanisation while pointing at cranes above the new station.","trans":"一名向导指着新车站上方的起重机讲解都市化。","mne":""},{"word":"urbanise","ipa":"/'ɜːbənˌaɪz/","pos":"v.","def":"使都市化","sen":"Many farming areas were urbanised in the past twenty years, with new roads and tall buildings.","trans":"许多农业地区在过去二十年里被城镇化，建起了新道路和高楼。","mne":""},{"word":"urbanization","ipa":"/ˌɜːrbənəˈzeɪʃn/","pos":"n.","def":"都市化；城市化（=urbanisation）","sen":"Modern China's urbanization is turning what used to be rural areas into cities.","trans":"现代中国的城市化就是将过去的农村地区变成城市。","mne":"urban城市的 ＋ ization名词后缀，...化 → urbanization都市化"},{"word":"urbanize","ipa":"/ˈɜːrbənaɪz/","pos":"v.","def":"使都市化；使文雅","sen":"The government is spending a lot of money to urbanize some parts of China.","trans":"政府花费了大量资金以推动中国某些地区的城镇化进程。","mne":"urban城市的 ＋ ize动词后缀，使…化 → urbanize使都市化"},{"word":"urge","ipa":"/ɜːrdʒ/","pos":"v.","def":"催促；强烈要求；  n.强烈的愿望","sen":"The mother urged her little one to hurry up and have dinner while it's still warm.","trans":"妈妈催促她的小宝贝赶快吃晚饭，趁还热的时候。","mne":""},{"word":"urgent","ipa":"/ˈɜːrdʒənt/","pos":"adj.","def":"急迫的；紧急的","sen":"The cat’s most urgent need now is to pee.","trans":"这只猫现在迫切需要上厕所。","mne":"urg紧急 ＋ ent具有...性质的 → urgent紧急的；强求的"},{"word":"us","ipa":"/ʌs/","pos":"pron.","def":"（宾格）我们","sen":"All of us are enjoying the party.","trans":"我们所有人在派对上都很开心。","mne":""},{"word":"usage","ipa":"/ˈjuːsɪdʒ/","pos":"n.","def":"使用，用法；使用（量）","sen":"The teacher wrote the correct usage of the word on the board.","trans":"老师在黑板上写了这个单词的正确用法。","mne":"us用 + age状态 → 用的状态 → usage用法；惯例"},{"word":"use","ipa":"/juːz/, /juːs/","pos":"v.","def":"使用，利用，消耗；  n.使用权（读作/juːs/）；用途，效用","sen":"I use a pencil to draw a picture.","trans":"我用一支铅笔来画画。","mne":""},{"word":"used","ipa":"/juːst/","pos":"adj.","def":"旧的；习惯的，惯常的；二手的，使用过的","sen":"Used plastic bottles can be recycled.","trans":"用过的塑料瓶可以回收利用。","mne":""},{"word":"useful","ipa":"/ˈjuːsfl/","pos":"adj.","def":"有用的，有益的","sen":"A Swiss Army knife contains many different useful tools.","trans":"一把瑞士军刀有许多不同且实用的工具。","mne":"use用 + ful可…的 → useful有用的"},{"word":"usual","ipa":"/ˈjuːʒuəl/","pos":"adj.","def":"通常的，惯常的","sen":"As per usual, he becomes sleepy in the afternoon.","trans":"通常，他下午就开始犯困。","mne":"usu用 + al...的 → 平时经常用的 → usual通常的"},{"word":"usually","ipa":"/ˈjuːʒuəli/","pos":"adv.","def":"通常，经常","sen":"We usually have lunch at 12:00.","trans":"我们通常在十二点吃午饭。","mne":"usual通常的 + ly副词后缀 → usually通常地，惯常地"},{"word":"utilise","ipa":"/'juːtlˌaɪz/","pos":"v.","def":"利用","sen":"We utilise recycled aluminum cans to make new ones.","trans":"我们利用回收铝罐制造新的。","mne":""},{"word":"utility","ipa":"/juːˈtɪləti/","pos":"n.","def":"效用；公用事业","sen":"Utility measures satisfaction from consuming goods and services.","trans":"效用衡量消费商品和服务的满意度。","mne":"util用 + ity名词后缀，状态 → utility公用事业，有用"},{"word":"utilize","ipa":"/ˈjuːtəlaɪz/","pos":"v.","def":"利用","sen":"It's better to utilize waste than to throw it away.","trans":"废物再利用总比把它扔掉要好。","mne":"ut用 + ilize动词后缀，……化 → utilize利用"},{"word":"utmost","ipa":"/ˈʌtmoʊst/","pos":"adj.","def":"最大的，极度的；最远的；  n.极限","sen":"I drive to the utmost extent; it is so fast.","trans":"我把车开到了最大速度，真是太快了。","mne":"ut=out向外 + most最多的 → utmost极度的"},{"word":"utter","ipa":"/ˈʌtər/ ","pos":"adj.","def":"完全的；十足的","sen":"Utter whiteness is the color of these apples.","trans":"这些苹果是纯白色的。","mne":""},{"word":"vacant","ipa":"/ˈveɪkənt/","pos":"adj.","def":"空的，未被占用的；空缺的","sen":"There is a vacant seat between those two people.","trans":"那两个人之间有一个空位。","mne":"vac空 + ant…的 → vacant空的"},{"word":"vacation","ipa":"/veɪˈkeɪʃn/","pos":"n.","def":"假期；  v.度假","sen":"The girl took a vacation on the beach.","trans":"这个女孩在海边度假。","mne":"vac空 + ation表名词 → vacation假期"},{"word":"vague","ipa":"/veɪg/","pos":"adj.","def":"含糊的，模糊的；不明确的","sen":"This sign is too vague! I have no idea what it means.","trans":"这个路标太混乱了，我不知道它到底是什么意思。","mne":""},{"word":"vain","ipa":"/veɪn/ ","pos":"adj.","def":"徒劳的；徒然的，没用的；自负的","sen":"Throw away the chocolate, or your efforts to lose weight will be in vain.","trans":"扔掉那块巧克力，不然你为减肥所做的努力就白费了。","mne":""},{"word":"valid","ipa":"/ˈvælɪd/","pos":"adj.","def":"有效的，正式认可的；合理的，有根据的","sen":"The official stamp showed that the document was valid.","trans":"这枚公章证明这份文件是有效的。","mne":""},{"word":"valley","ipa":"/ˈvæli/","pos":"n.","def":"山谷，溪谷，低谷；流域","sen":"A small stream flows through the valley.","trans":"一条小溪流过山谷。","mne":""},{"word":"valuable","ipa":"/ˈvæljuəbl/","pos":"adj.","def":"宝贵的，有价值的；值钱的；  n.（复数）贵重物品","sen":"My grandfather left me valuable jewelry.","trans":"我的祖父给我留下了贵重的珠宝。","mne":"valu=value价值 + able形容词后缀 → valuable有价值的"},{"word":"value","ipa":"/ˈvæljuː/","pos":"v.","def":"重视；给……估价；  n.价值","sen":"Which do you value more—the economy or the environment?","trans":"经济和环境，你更重视哪个呢？","mne":""},{"word":"van","ipa":"/væn/","pos":"n.","def":"厢式货车","sen":"Food vans on the street have the cheapest and best food!","trans":"街边的流动食品车有着最物美价廉的食物！","mne":""},{"word":"vanish","ipa":"/ˈvænɪʃ/","pos":"v.","def":"消失，绝迹；突然不见；消灭；  v.使消失；使不见","sen":"The magician waved the wand and the woman vanished.","trans":"魔术师挥动了一下魔杖，那位女士就消失了。","mne":"van空 + ish动词后缀 → 凭空消失了 → vanish突然不见，消失"},{"word":"vapor","ipa":"/ˈveɪpər/","pos":"n.","def":"（水）蒸汽","sen":"Water turns into vapor when we boil it.","trans":"水加热之后会变成蒸汽。","mne":""},{"word":"vapour","ipa":"/ˈveɪpər/","pos":"n.","def":"蒸气","sen":"Water vapour arose from the boiling pool.","trans":"水蒸气从沸腾的池塘中升起。","mne":""},{"word":"variable","ipa":"/ˈveriəbl/","pos":"adj.","def":"可变的；易变的，可变的；  n.【计】变量","sen":"Individual responses to the same medication can be highly variable due to genetic and metabolic differences.","trans":"由于遗传和代谢差异，个体对同一种药物的反应可能非常多变。","mne":"vari=vary变化 + able形容词后缀 → 易变的"},{"word":"variety","ipa":"/vəˈraɪəti/ ","pos":"n.","def":"种类；变化，多样性","sen":"There is a wide variety of tomatoes; they are different in color.","trans":"番茄有很多种类，颜色各不相同。","mne":"vari变化 + ety名词后缀 → variety变化，多样化"},{"word":"various","ipa":"/ˈveəriəs/","pos":"adj.","def":"各种各样的，不同的","sen":"We saw various types of fish during our dive.","trans":"潜水时，我们看到了各种各样的鱼。","mne":"vari变化 + ous形容词后缀 → various不相同的"},{"word":"vary","ipa":"/ˈveri/","pos":"v.","def":"相异；（根据情况）变化；使多样化","sen":"Each cup on the table varies in color and size.","trans":"桌上的每个杯子颜色和大小各不相同。","mne":"vary=vari变化 → vary改变，变化"},{"word":"vast","ipa":"/væst/","pos":"adj.","def":"辽阔的；巨大的","sen":"This vast desert looks impossible to pass.","trans":"这片辽阔的沙漠看上去不可能穿越。","mne":""},{"word":"vegetable","ipa":"/ˈvedʒtəbl/","pos":"n.","def":"蔬菜","sen":"These are just a few of the fresh, ripe vegetables in my garden.","trans":"这只是我花园里一部分新鲜成熟的蔬菜。","mne":""},{"word":"vegetarian","ipa":"/ˌvedʒəˈteriən/","pos":"n.","def":"素食者","sen":"They became vegetarians because they couldn’t find anything else to eat.","trans":"僵尸成了素食者，因为他们找不到别的东西吃了。","mne":"veget=vegetable蔬菜 + arian表形容词或名词，…的（人） → vegetarian素食的（人）"},{"word":"vehicle","ipa":"/ˈviːəkl/","pos":"n.","def":"车辆；交通工具；传播媒介；工具，手段","sen":"The vehicle drove off with a container.","trans":"那辆车载着一个集装箱开走了。","mne":"veh带来 + icle=le表名词 → 开车把人带来 → vehicle车辆，机动车"},{"word":"venture","ipa":"/ˈventʃər/","pos":"v.","def":"冒险；  n.（商业）冒险；投机，风险投资","sen":"The boys venture deep into the forest.","trans":"男孩们深入森林冒险。","mne":"vent来 + ure表名词 → 来冒险一试 → venture冒险"},{"word":"verb","ipa":"/vɜːrb/","pos":"n.","def":"动词","sen":"\"Dance\" can be a verb because it's an action word.","trans":"“跳舞”可以是一个动词，因为它是一个表示动作的词。","mne":""},{"word":"verbal","ipa":"/ˈvɜːrbl/","pos":"adj.","def":"言语的，口头的；动词的","sen":"Thanks to her great verbal skills, she delivered a brilliant presentation.","trans":"多亏她良好的语言表达能力，她发表了精彩的演讲。","mne":"verb词语 + al形容词后缀 → verbal词语的"},{"word":"verge","ipa":"/vɜːrdʒ/","pos":"n.","def":"边缘；边界；  v.濒临；接近","sen":"The verge of the road is covered with lovely blue flowers.","trans":"路的边缘长满了可爱的蓝色花朵。","mne":""},{"word":"verify","ipa":"/ˈverɪfaɪ/","pos":"v.","def":"查证，证明，证实","sen":"This card can verify the man's identity.","trans":"这个证件可以证实此人的身份。","mne":"veri真实 ＋ fy使... → 使真实 → verify核实"},{"word":"verse","ipa":"/vɜːrs/","pos":"n.","def":"诗句，诗节，诗；韵文","sen":"Li Bai’s poem is made up of four verses.","trans":"李白的诗有四句。","mne":""},{"word":"version","ipa":"/ˈvɜːrʒn/","pos":"n.","def":"版本","sen":"This book has many different versions.","trans":"这本书有很多不同的版本。","mne":"vers转 + ion表名词 → 把原文转换成另一版本 → version翻译，译文"},{"word":"versus","ipa":"/ˈvɜːrsəs/","pos":"prep.","def":"与……相对，与……相比","sen":"The superhero versus the female agent will be a good fight to watch.","trans":"这场战斗是超级英雄对阵女特工，值得一看。","mne":""},{"word":"vertical","ipa":"/ˈvɜːrtɪkl/","pos":"adj.","def":"【财】垂直的","sen":"In the past, courts have been reluctant to block or unwind such deals, known as vertical acquisitions.","trans":"在过去，法院通常不愿阻止或撤销这类被称为垂直并购的交易。","mne":"vert转变 + ical…的 → 转变成直的 → vertical垂直"},{"word":"very","ipa":"/ˈveri/","pos":"adv.","def":"很，非常","sen":"They are very excited.","trans":"他们非常激动。","mne":""},{"word":"vessel","ipa":"/ˈvesl/","pos":"n.","def":"船，舰；容器；血管","sen":"The vessel with loads of containers is moving on the ocean.","trans":"满载集装箱的轮船正在海上航行。","mne":""},{"word":"veteran","ipa":"/ˈvetərən/","pos":"n.","def":"老兵；经验丰富的人，老手；  adj.老练的","sen":"This veteran has fought in many wars.","trans":"这位老兵曾多次参战。","mne":"veter老 + an名词后缀，表示人 → veteran老兵"},{"word":"veto","ipa":"/ˈviːtoʊ/","pos":"v.","def":"否决；  n.否决权；否决","sen":"Her mom suggested that yellow dress to her, but she vetoed it.","trans":"她妈妈给她推荐了那条黄色连衣裙，但是被她否决了。","mne":""},{"word":"via","ipa":"/ˈvaɪə/,  /ˈviːə/","pos":"prep.","def":"经过，通过","sen":"We left Guangzhou, taking the bus to Beijing via Wuhan.","trans":"我们离开了广州，乘大巴经武汉去北京。","mne":""},{"word":"vibrate","ipa":"/ˈvaɪbreɪt/","pos":"v.","def":"颤动，震动，摇摆，踌躇","sen":"The smartphone vibrates when it rings.","trans":"这个智能手机响的时候还会振动。","mne":"vibr动摇，颤抖 + ate表动词，使...成为 → vibrate（使）振动"},{"word":"vice","ipa":"/vaɪs/","pos":"n.","def":"恶习；缺点；  adj.代理的","sen":"Both smoking and gambling are vices. You should quit them.","trans":"抽烟和赌博都是恶习，你们应该戒掉。","mne":""},{"word":"victim","ipa":"/ˈvɪktɪm/","pos":"n.","def":"受害者","sen":"The family are victims of the flood, and they are now homeless. ","trans":"这一家人是这次洪灾的受害者，现在他们无家可归了。","mne":""},{"word":"victorious","ipa":"/vɪkˈtɔːriəs/","pos":"adj.","def":"胜利的，得胜的","sen":"He was victorious in the competition, taking first prize.","trans":"他在比赛中获得了胜利，取得了第一名。","mne":"victor=victory胜利 + ious=ous形容词后缀 → victorious胜利的"},{"word":"victory","ipa":"/ˈvɪktəri/","pos":"n.","def":"胜利；成功","sen":"The V-shaped gesture is the symbol of victory.","trans":"V形手势是胜利的象征。","mne":"vict征服，战胜 + ory表名词 → victory胜利"},{"word":"video","ipa":"/ˈvɪdioʊ/","pos":"n.","def":"视频，录像；录像带","sen":"Her job is to record the show on video.","trans":"她的工作是制作演出的录像。","mne":"vid=see看 + eo后缀 → video视频，录像"},{"word":"view","ipa":"/vju/","pos":"n.","def":"风景，景色；观点，看法；  v.看待；观看，收看","sen":"What an amazing view from the top of the hill!","trans":"从山顶看到的风景太棒啦！","mne":""},{"word":"viewpoint","ipa":"/ˈvjuːpɔɪnt/","pos":"n.","def":"观点，视点，见解，角度","sen":"The man is thinking about his viewpoints and is ready to write them down.","trans":"这个男人正在思考他的观点并准备写下来。","mne":"view看 ＋ point点 → viewpoint观点，看法"},{"word":"vigor","ipa":"/ˈvɪɡər/","pos":"n.","def":"活力","sen":"She always approaches her work with great vigor, which makes her an asset to our team.","trans":"她总是充满活力地投入工作，这使得她成为我们团队的宝贵财富。","mne":"vig生命 + or表名词 → vigor精力"},{"word":"vigorous","ipa":"/ˈvɪɡərəs/","pos":"adj.","def":"精力充沛的","sen":"He is always vigorous and he never gets tired.","trans":"路飞总是精力充沛，似乎永远也不会累。","mne":"vig生命 + orous...的 → vigorous精力旺盛的"},{"word":"vigour","ipa":"/ˈvɪɡər/","pos":"n.","def":"活力；精力，力量","sen":"My daily exercise gives me a lot of vigour and strength.","trans":"每天运动使我充满活力和力量。","mne":"vig=life生命 + our=or名词词根 → vigour活力，元气"},{"word":"village","ipa":"/ˈvɪlɪdʒ/","pos":"n.","def":"村庄，乡村","sen":"I lived in a remote mountain village.","trans":"我住在一个遥远的小山村里。","mne":"vill=villa茅房，别墅 + age场所，物品 → village村庄"},{"word":"vinegar","ipa":"/ˈvɪnɪɡər/","pos":"n.","def":"醋","sen":"Shanxi Province is famous for its vinegar.","trans":"山西省以醋闻名。","mne":"vin葡萄酒 + egar酸的 → vinegar醋"},{"word":"violate","ipa":"/ˈvaɪəleɪt/","pos":"v.","def":"违反，违背","sen":"The bird's behavior violated the sign's rules.","trans":"鸟儿的行为违反了这个标牌上的规定。","mne":""},{"word":"violence","ipa":"/ˈvaɪələns/","pos":"n.","def":"暴力，暴行","sen":"The youngsters shouldn't settle the problem by using violence.","trans":"年轻人不该用暴力解决问题。","mne":"viol力量 + ence表名词  → 暴力，暴行"},{"word":"violent","ipa":"/ˈvaɪələnt/","pos":"adj.","def":"暴力的；猛烈的","sen":"Some violent pictures in this cartoon will have a negative effect on the boy.","trans":"这部动画片中的一些暴力画面会对这个男孩产生负面影响。","mne":"viol暴力 + ent形容词后缀 → violent暴力的，粗暴的 "},{"word":"violin","ipa":"/ˌvaɪəˈlɪn/","pos":"n.","def":"小提琴（一种乐器）","sen":"She can play the violin well.","trans":"她小提琴拉得很好。","mne":""},{"word":"violinist","ipa":"/ˌvaɪəˈlɪnɪst/","pos":"n.","def":"小提琴演奏者，小提琴家","sen":"The young violinist impressed us with his great talent.","trans":"这位年轻的小提琴家以其极高的天赋给我们留下了深刻的印象。","mne":"violin小提琴 + ist从事某种职业的人 → violinist小提琴手"},{"word":"virtual","ipa":"/ˈvɜːrtʃuəl/","pos":"adj.","def":"（计算机）虚拟的；事实上的","sen":"They are driving a virtual car.","trans":"他们正在驾驶一辆虚拟汽车。","mne":""},{"word":"virtually","ipa":"/ˈvɜːrtʃuəli/","pos":"adv.","def":"几乎；实际上","sen":"The man was virtually on the point of striking gold.","trans":"这个人几乎快要挖到黄金了。","mne":""},{"word":"virtue","ipa":" /ˈvɜːrtʃuː/","pos":"n.","def":"美德，高尚的道德；好处，优点","sen":"Her kindness is a virtue she shows every day.","trans":"她的美德体现在日常善举之中。","mne":""},{"word":"virus","ipa":"/ˈvaɪrəs/","pos":"n.","def":"病毒","sen":"This virus is really dangerous.","trans":"这种病毒真的很危险。","mne":""},{"word":"visa","ipa":"/ˈviːzə/","pos":"n.","def":"签证","sen":"I've got my visa ready, and now I can travel around the world!","trans":"我拿到了我的签证，现在我可以环游世界啦！","mne":"vis看 + a → 审视，审查 → 审查后的签证 → visa签证，签准"},{"word":"visible","ipa":"/ˈvɪzəbl/","pos":"adj.","def":"明显的，看得见的；看得见的","sen":"The cake is visible in the right box.","trans":"右边盒子里的蛋糕是可见的。","mne":"vis看 + ible形容词后缀，可…的 → visible看得见的，可见的"},{"word":"vision","ipa":"/ˈvɪʒn/","pos":"n.","def":"视力；视野；想象","sen":"The eye doctor said that my vision is excellent.","trans":"眼科医生说我的视力非常好。","mne":"vis看 + ion表名词 → vision视力，眼界"},{"word":"visit","ipa":"/ˈvɪzɪt/","pos":"v.","def":"参观，访问；  n.访问参观，游览","sen":"We visited the history museum today.","trans":"今天我们去参观了历史博物馆。","mne":"vis看，观看 + it → visit参观"},{"word":"visitor","ipa":"/ˈvɪzɪtər/","pos":"n.","def":"访问者，来宾；访问者，参观者","sen":"I think we have a visitor at the door.","trans":"我想我们有客人来了。","mne":"visit参观 + or表示人 → visitor参观者，观光者"},{"word":"visual","ipa":"/ˈvɪʒuəl/","pos":"adj.","def":"视觉的；视力的","sen":"The debate over the dress color is actually a visual trick.","trans":"关于裙子颜色的争论实际上是一个视觉游戏。","mne":"vis看 + ual表形容词 → visual视觉的"},{"word":"visualise","ipa":"/'vɪʒʊəlˌaɪz/","pos":"v.","def":"想象；设想，想象","sen":"Imagine the future you want and visualise it every day.","trans":"想象你想要的未来，并每天去想象它。","mne":""},{"word":"visualize","ipa":"/ˈvɪʒuəlaɪz/","pos":"v.","def":"使形象化","sen":"We can visualize a solution to the problem.","trans":"我们可以设想出一个解决问题的方案。","mne":"visual看得见的 + ize动词后缀：使 → visualize使形象化"},{"word":"vital","ipa":"/ˈvaɪtl/","pos":"adj.","def":"必不可少的，至关重要的；有活力的；生死攸关的","sen":"Water is vital to living beings.","trans":"水对生物来说是必不可少的。","mne":"vit生命 + al形容词后缀 → vital有活力的；重要的"},{"word":"vitamin","ipa":"/ˈvaɪtəmɪn/","pos":"n.","def":"维生素","sen":"Fruits such as oranges and grapes are rich in vitamin C.","trans":"橙子、葡萄这类水果富含维生素C。","mne":"vita生命 + min小要素 → 生命要素 → vitamin维生素"},{"word":"vivid","ipa":"/ˈvɪvɪd/","pos":"adj.","def":"生动的，清晰的（记忆、描述）；（颜色）鲜艳的，强烈的（颜色、光）","sen":"This painting is a vivid representation of a horse.","trans":"这幅画是对马的生动再现。","mne":"viv生命 + id…形容词后缀，具有…性质的 → 有生命的 → vivid活泼的；生动的"},{"word":"vocabulary","ipa":"/vəˈkæbjəleri/","pos":"n.","def":"词汇（量）","sen":"This software will help increase your English vocabulary!","trans":"这个软件会帮你增加你的英语词汇量。","mne":"vocabul=vocable词 + ary表名词 → vocabulary词汇"},{"word":"vocation","ipa":"/voʊˈkeɪʃn/","pos":"n.","def":"职业；行业；使命","sen":"These vocations play different roles in our society.","trans":"这些职业在我们的社会中扮演着不同的角色。","mne":"voc呼喊，声，召集 + ation表名词 → [受到]召唤 → vocation使命，职业"},{"word":"vocational","ipa":"/voʊˈkeɪʃənl/","pos":"adj.","def":"职业的","sen":"I learned how to drive this in vocational school.","trans":"我是在职业学校学会如何驾驶这个的。","mne":"vocation职业 + al…的 → 叫喊的 → 职业的，行业的"},{"word":"voice","ipa":"/vɔɪs/","pos":"n.","def":"声音；意见；  v.表达","sen":"She has such a wonderful voice - no wonder so many people buy her music!","trans":"她有如此美妙的嗓音，难怪这么多人买她的歌。","mne":""},{"word":"volleyball","ipa":"/ˈvɑːlibɔːl/","pos":"n.","def":"排球（运动）","sen":"The women's volleyball player hit the ball over the net vigorously.","trans":"这位女子排球运动员用力地把球击过网。","mne":"volley截击 + ball球 → volleyball排球"},{"word":"volt","ipa":"/voʊlt/ ","pos":"n.","def":"伏特（电压单位）","sen":"The cable has 220 volts of electricity.","trans":"这根电线有220伏的电。","mne":""},{"word":"voltage","ipa":"/ˈvoʊltɪdʒ/","pos":"n.","def":"电压","sen":"“Be careful, this machine has a high voltage.”","trans":"“小心，这台机器带高压电。”","mne":"volt电压 + age表示集合名词、总称 → voltage电压"},{"word":"volume","ipa":"/ˈvɑːljəm/","pos":"n.","def":"音量；容量，容积；册，卷","sen":"I turned the volume up to listen to the radio.","trans":"我把收音机音量调大来听广播。","mne":"vol旋转，卷 + ume表物 → 卷起来的东西 → volume卷，册"},{"word":"voluntary","ipa":"/ˈvɑːlənteri/","pos":"adj.","def":"自愿的；志愿的","sen":"Giving blood is 100% voluntary: Nobody will force you to do it.","trans":"献血是百分之百自愿的，没人会强迫你去做。","mne":"volunt自愿，意愿 + ary形容词后缀 → voluntary志愿的，自愿的"},{"word":"volunteer","ipa":"/ˌvɑːlənˈtɪr/","pos":"n.","def":"志愿者；  v.自愿做","sen":"Volunteers are cleaning up the public environment.","trans":"志愿者们正在清理公共环境。","mne":"volunt自愿，意愿 + eer表示人 → volunteer志愿者"},{"word":"vote","ipa":"/voʊt/","pos":"v.","def":"投票，表决；  n.投票","sen":"Voting is a fair way for selection.","trans":"投票是一种公平的选举方式。","mne":"vot发誓 + e → 投票前需要发誓以示诚实 → vote投票"},{"word":"voyage","ipa":"/ˈvɔɪɪdʒ/","pos":"n.","def":"航海，航行；  v.航海；航行","sen":"The ship Titanic sank on its first voyage.","trans":"“泰坦尼克号”在首航中便沉没了。","mne":"voy道路 + age表状态 → 一直在路上 → voyage航海，航行"},{"word":"vulnerable","ipa":"/ˈvʌlnərəbl/","pos":"adj.","def":"脆弱的；易受伤的","sen":"The vulnerable baby required unwavering attention and care.","trans":"脆弱的婴儿需要得到无微不至的关注和照顾。","mne":"vulner创伤 + able表形容词 → 容易被创伤的 → vulnerable脆弱的"},{"word":"wage","ipa":"/weɪdʒ/","pos":"n.","def":"工资，薪水；  v.开展，进行（战争、运动）","sen":"The worker was so happy when she got her wages.","trans":"这个工人拿到工资的时候很开心。","mne":""},{"word":"waist","ipa":"/weɪst/","pos":"n.","def":"腰","sen":"The man put the measuring tape around his waist.","trans":"这个人在腰上围了一条软尺。","mne":""},{"word":"wait","ipa":"/weɪt/","pos":"v.","def":"等待；  n.等待","sen":"She is waiting for her flight.","trans":"她正在等她的航班。","mne":""},{"word":"waiter","ipa":"/ˈweɪtər/","pos":"n.","def":"侍者，服务员；（餐馆的）男服务员","sen":"The young man is a waiter in a restaurant.","trans":"这个年轻的小伙子是一家餐馆的服务员。","mne":"wait等待 + er名词后缀 → 等待着的人 → waiter侍者"},{"word":"waitress","ipa":"/ˈweɪtrəs/","pos":"n.","def":"女服务员；女侍者","sen":"Can you ask the waitress to bring the bill?","trans":"你能让女服务员把账单拿来吗？","mne":"wait等待 + ress女性 → waitress女服务员"},{"word":"wake","ipa":"/weɪk/","pos":"v.","def":"醒来，唤醒","sen":"The alarm woke up the man.","trans":"闹钟把男人吵醒了。","mne":""},{"word":"waken","ipa":"/ˈweɪkən/","pos":"v.","def":"弄醒","sen":"The alarm clock wakens me at 6 o'clock every day.","trans":"闹钟每天都在六点的时候把我叫醒。","mne":"wake唤醒 + en表动词 → waken弄醒"},{"word":"walk","ipa":"/wɔːk/  ","pos":"v.","def":"行走","sen":"Many people are walking on the road.","trans":"许多人行走在路上。","mne":""},{"word":"walkman","ipa":"/'wɔːkmən/","pos":"n.","def":"随身听","sen":"This Walkman uses a cassette tape to play music.","trans":"这款随声听需要一盘磁带才能播放音乐。","mne":""},{"word":"wall","ipa":"/wɔːl/","pos":"n.","def":"墙","sen":"This wall is made up of oddly shaped bricks.","trans":"这道墙由形状不规则的砖砌成。","mne":""},{"word":"wallet","ipa":"/ˈwɑːlɪt/","pos":"n.","def":"钱包；皮夹，钱包","sen":"I left my wallet at the store.","trans":"我把钱包忘在商店里了。","mne":""},{"word":"wander","ipa":"/ˈwɑːndər/","pos":"v.","def":"闲逛，漫步；蜿蜒；漫游","sen":"The couple are casually wandering amidst the maple trees.","trans":"这对恋人正在枫叶林里悠闲地漫步。","mne":""},{"word":"want","ipa":"/wɑːnt/","pos":"v.","def":"想要","sen":"The young couple really want a baby.","trans":"这对年轻夫妇很想要个孩子。","mne":""},{"word":"war","ipa":"/wɔːr/","pos":"n.","def":"战争；  v.打仗，作战，对抗","sen":"Follow me into battle and we shall win this war!","trans":"跟着我加入战斗，我们一定会赢得这场战争！","mne":""},{"word":"warm","ipa":"/wɔːrm/","pos":"adj.","def":"温暖的，暖的，温热的","sen":"The weather cooled off, so we made a fire to keep warm.","trans":"天气变凉了，所以我们生火取暖。","mne":""},{"word":"warn","ipa":"/wɔːrn/","pos":"v.","def":"警告，告诫","sen":"The sign warned the bone about the danger of being eaten.","trans":"这个标牌警告骨头有被吃掉的危险。","mne":""},{"word":"warning","ipa":"/ˈwɔːrnɪŋ/","pos":"adj.","def":"警告的；  n.警告","sen":"After the tree fell onto the road, they put a warning sign in front of it.","trans":"树倒在路上之后，他们在树前面放了一块警告牌。","mne":"warn警告 + ing表示……的 → warning警告的"},{"word":"wash","ipa":"/wɑːʃ/","pos":"v.","def":"清洗","sen":"My grandpa is washing the clothes.","trans":"友藏爷爷正在洗衣服。","mne":""},{"word":"waste","ipa":"/weɪst/","pos":"n.","def":"废物，垃圾；浪费；  v.浪费；  adj.废弃的","sen":"A lot of waste has been dumped in the field.","trans":"许多废物被倒在这片地上。","mne":""},{"word":"watch","ipa":"/wɑːtʃ/","pos":"v.","def":"观看，注视；注意；留神观察；小心，当心，留意；  n.手表；监视","sen":"There were two little dogs watching the television.","trans":"两只小斑点狗在看电视。","mne":""},{"word":"water","ipa":"/ˈwɔːtər/","pos":"n.","def":"水；  v.给……浇水，给……供水","sen":"Would you like a glass of ice water?","trans":"你要一杯冰水吗？","mne":""},{"word":"waterproof","ipa":"/ˈwɔːtərpruːf/","pos":"adj.","def":"防水的","sen":"Luckily, this kind of shoes is waterproof.","trans":"幸运的是，这种鞋子是防水的。","mne":"water水 + proof防……的 → waterproof防水的"},{"word":"wave","ipa":"/weɪv/","pos":"n.","def":"海浪，波浪；挥手；  v.挥手，招手；上下起伏，左右摇晃","sen":"The waves are washing off the drawing on the beach.","trans":"海浪就快把海滩上的画冲掉了。","mne":""},{"word":"way","ipa":"/weɪ/","pos":"n.","def":"道路；方向；方法；方式","sen":"There's a way across the field.","trans":"这儿有一条路穿过田地。","mne":""},{"word":"we","ipa":"/wi/","pos":"pron.","def":"（主格）我们","sen":"We are a good team.","trans":"我们是一个好团队。","mne":""},{"word":"weak","ipa":"/wiːk/","pos":"adj.","def":"虚弱的；软弱的","sen":"He's so weak that he can't even lift this tiny weight.","trans":"他真的是太虚弱了，竟然连这么轻的重量都举不起来。","mne":""},{"word":"weaken","ipa":"/ˈwiːkən/","pos":"v.","def":"削弱，使虚弱","sen":"His eating disorder and insufficient food intake obviously weakened him.","trans":"饮食失调和摄入不足明显使他变得虚弱了。","mne":"weak虚弱的 + en表动词 → weaken削弱，变弱"},{"word":"weakness","ipa":"/ˈwi:knəs/","pos":"n.","def":"（性格、系统的）弱点","sen":"Vampires' weakness is that they are afraid of sunshine.","trans":"吸血鬼的弱点是害怕阳光。","mne":"weak虚弱的 + ness表名词 → weakness懦弱，虚弱"},{"word":"wealth","ipa":"/welθ/","pos":"n.","def":"财富，财产","sen":"He is a man of great wealth.","trans":"他是一个拥有大量财富的人。","mne":"weal幸福 + th抽象名词后缀 → wealth财富"},{"word":"wealthy","ipa":"/ˈwelθi/","pos":"adj.","def":"富有的；富饶的","sen":"I'm so wealthy that I bathe in money.","trans":"我太有钱了，我在钱里沐浴。","mne":"wealth财富 + y……的 → 富裕的"},{"word":"weapon","ipa":"/ˈwepən/","pos":"n.","def":"武器","sen":"There are a number of different kinds of weapons on the floor.","trans":"地板上有很多种不同种类的武器。","mne":""},{"word":"wear","ipa":"/wer/","pos":"v.","def":"穿，戴；  n.磨损；穿戴物，衣物","sen":"She loves to wear white coats.","trans":"她爱穿白色的大衣。","mne":""},{"word":"weary","ipa":"/ˈwɪri/","pos":"adj.","def":"疲倦的，困乏的，令人厌倦的；  v.使厌倦；  v.疲倦，厌烦","sen":"He had a weary look on his face.","trans":"他脸上带着疲倦的神情。","mne":""},{"word":"weather","ipa":"/ˈweðər/","pos":"n.","def":"天气","sen":"The weather was different when we went back to that place.","trans":"我们再回到那个地方的时候，天气不一样了。","mne":"we吹 + ther后缀 → 吹风等天气 → weather天气"},{"word":"weave","ipa":"/wiːv/","pos":"v.","def":"编织","sen":"The elder is weaving a basket.","trans":"老人正在编篮子。","mne":""},{"word":"web","ipa":"/web/","pos":"n.","def":"网；网络","sen":"I am in a complex web of relationships.","trans":"我处在一个复杂的关系网中。","mne":""},{"word":"website","ipa":"/ˈwebsaɪt/","pos":"n.","def":"网站","sen":"The company website is up and running.","trans":"公司网站上线并开始运行。","mne":""},{"word":"wedding","ipa":"/ˈwedɪŋ/","pos":"n.","def":"婚礼","sen":"The couple held their wedding ceremony on the grass.","trans":"这对夫妻在草地上举行了他们的婚礼。","mne":"wed嫁，娶 + ding名词后缀 → wedding婚礼，婚宴，结婚典礼"},{"word":"wednesday","ipa":"/ˈwenzdeɪ/","pos":"n.","def":"星期三","sen":"I have an appointment on Wednesday.","trans":"我周三有个约会。","mne":""},{"word":"week","ipa":"/wiːk/","pos":"n.","def":"星期，周","sen":"They are talking about the week's plan.","trans":"他们在谈论这周的计划。","mne":""},{"word":"weekday","ipa":"/ˈwiːkdeɪ/","pos":"n.","def":"工作日，平日","sen":"He works on weekdays, from Monday to Friday.","trans":"他在工作日上班，从星期一上到星期五。","mne":"week一周 + day日子 → 一周里除了周末 → 工作日"},{"word":"weekend","ipa":"/ˈwiːkend/","pos":"n.","def":"周末，星期六和星期日","sen":"The weekend is coming!","trans":"就要到周末啦！","mne":"week周 + end结束 → weekend周末"},{"word":"weekly","ipa":"/ˈwiːkli/","pos":"adv.","def":"一周一次地；  adj.每周的，一周一次的；  n.周报，周刊","sen":"This TV show is updated weekly.","trans":"这个电视节目每周更新一次。","mne":"week周 + ly表副词，每……地 → 每周的"},{"word":"weep","ipa":"/wiːp/","pos":"v.","def":"哭泣，流泪；流出，渗出；  n.哭泣","sen":"I could feel his sadness when I saw him weeping.","trans":"当我看到他在哭泣时，我能感受到他的悲伤。","mne":""},{"word":"weigh","ipa":"/weɪ/","pos":"v.","def":"称重；认真考虑，权衡","sen":"Please weigh the apples and pears for me.","trans":"请替我称一下苹果和梨的重量。","mne":""},{"word":"weight","ipa":"/weɪt/","pos":"n.","def":"重量，分量；砝码；重物；  v.使负重","sen":"The weight of the apples you chose is 2 kilos.","trans":"你所选的苹果的重量是2千克。","mne":"weigh称量 + t名词后缀 → weight重量"},{"word":"welcome","ipa":"/ˈwelkəm/","pos":"v.","def":"欢迎；  adj.受欢迎的；  n.欢迎","sen":"He stood at the door to welcome the student.","trans":"他站在门口欢迎这位学生。","mne":""},{"word":"welfare","ipa":"/ˈwelfer/","pos":"n.","def":"福利","sen":"The organization aims to improve the welfare of animals.","trans":"这个组织旨在提升动物的福利。","mne":""},{"word":"well","ipa":"/wel/","pos":"adv.","def":"令人满意地；  adj.健康的；  n.水井；  int.好吧","sen":"She can play the piano very well.","trans":"她钢琴弹得非常好。","mne":""},{"word":"well-being","ipa":"/ˈwel biːɪŋ/","pos":"n.","def":"健康，康乐","sen":"Meditation and yoga are good for your well-being.","trans":"冥想和瑜伽有助于保持健康。","mne":""},{"word":"well-known","ipa":"/ˌwel ˈnəʊn/","pos":"adj.","def":"众所周知的；有名的，著名的","sen":"It is a well-known fact that smoking is bad for our health.","trans":"众所周知，吸烟有害人体健康。","mne":""},{"word":"west","ipa":"/west/","pos":"n.","def":"西，西方，西部；  adj.西的，西方的；  adv.向西方","sen":"On the compass, \"W\" stands for west.","trans":"在指南针上，“W”代表西方。","mne":""},{"word":"western","ipa":"/ˈwestərn/","pos":"adj.","def":"西方的；西部的；  n.西方人","sen":"These dresses are typical western wedding dresses.","trans":"这些裙子是典型的西式婚纱。","mne":"west西方 + ern……方向的 → western西方的"},{"word":"wet","ipa":"/wet/","pos":"adj.","def":"湿的；  v.把……弄湿","sen":"He got wet because of the rain.","trans":"因为下雨，他被淋湿了。","mne":""},{"word":"what","ipa":"/wʌt/","pos":"pron.","def":"什么","sen":"What is going on here?","trans":"这里发生了什么事情？","mne":""},{"word":"whatever","ipa":"/wətˈevər/","pos":"pron.","def":"无论什么","sen":"The man shrugs his shoulders and says: \"whatever.\"","trans":"他耸了耸肩说道：“无所谓。”","mne":"what什么 + ever究竟 → whatever无论什么"},{"word":"wheat","ipa":"/wiːt/","pos":"n.","def":"小麦；小麦色","sen":"The golden wheat rippled in the breeze.","trans":"金黄色的小麦在微风中荡漾。","mne":""},{"word":"wheel","ipa":"/wiːl/","pos":"n.","def":"轮子","sen":"The wheels of these bicycles are the same size.","trans":"这些自行车的轮子大小相同。","mne":""},{"word":"when","ipa":"/wen/","pos":"adv.","def":"什么时候","sen":"When will you leave tomorrow? In the morning or in the evening?","trans":"你明天什么时候走？早上还是晚上？","mne":""},{"word":"whenever","ipa":"/wenˈevər/","pos":"conj.","def":"无论何时；每当；  adv.不论何时","sen":"You can call customer service whenever you want.","trans":"无论何时，你都可以呼叫客服。","mne":"when何时 + ever究竟 → whenever无论何时，随时"},{"word":"where","ipa":"/wer/","pos":"adv.","def":"什么地方，哪里，在哪里，……的（地方）","sen":"Do you know where we are?","trans":"你知道我们现在在哪儿么？","mne":""},{"word":"whereas","ipa":"/ˌwerˈæz/","pos":"conj.","def":"然而，但是，尽管；【法】鉴于，就……而论","sen":"The line chart shows one thing, whereas the bar chart shows the other.","trans":"折线图显示的是一回事，而柱状图显示的则是另一回事。","mne":"where在哪 + as如此 → whereas然而，但是，尽管"},{"word":"wherever","ipa":"/werˈevər/","pos":"conj.","def":"无论在哪里；在任何地方；  adv.无论在哪里","sen":"Wherever you want your package to go, we can deliver it.","trans":"无论你想让你的包裹去哪儿，我们都能送达。","mne":""},{"word":"whether","ipa":"/ˈweðər/","pos":"conj.","def":"是否；不管，无论","sen":"The mother still doesn't know whether it's a boy or a girl.","trans":"这位母亲还不知道宝宝是男是女。","mne":"whe=who谁 + ther比较级后缀 → 是两人中的谁 → whether是否"},{"word":"which","ipa":"/wɪtʃ/","pos":"pron.","def":"哪个，哪几个，……的，……那个","sen":"The teacher asked the girl which pen was hers.","trans":"老师问女孩哪一支笔是她的。","mne":""},{"word":"whichever","ipa":"/wɪtʃˈevər/","pos":"det.","def":"无论哪个；  pron.无论哪些","sen":"I will have whichever drink is the most delicious.","trans":"无论哪种饮料，我都要喝最好喝的。","mne":"which哪个 + ever究竟 → whichever无论哪一个，任何一个"},{"word":"while","ipa":"/waɪl/","pos":"conj.","def":"当……的时候，在...期间；然而；  n.一会儿，一段时间；一段时间","sen":"He snores while he sleeps.","trans":"他睡觉的时候会打呼噜。","mne":""},{"word":"whip","ipa":"/wɪp/","pos":"v.","def":"鞭打，抽打；猛地移动，急走，急冲；  n.抽打","sen":"The guy whips his horses to make them run faster.","trans":"那人鞭打他的马儿让它们跑得更快。","mne":""},{"word":"whisky","ipa":"/ˈwɪski/","pos":"n.","def":"威士忌酒","sen":"I prefer whisky over any other hard drink.","trans":"烈酒里面我最喜欢威士忌。","mne":""},{"word":"whisper","ipa":"/ˈwɪspər/","pos":"v.","def":"小声说，耳语，低语；低声低语地讲，悄悄地说；  n.私语；沙沙声，飒飒声","sen":"The little boy is whispering something to his grandfather.","trans":"这个小男孩正和他的爷爷说悄悄话。","mne":"whisp轻语 + er表拟声动作 → whisper低语，作沙沙声"},{"word":"whistle","ipa":"/ˈwɪsl/","pos":"n.","def":"口哨（声），哨子（声）；汽笛声，警笛声；  v.吹口哨","sen":"He blows a red whistle.","trans":"他吹响一个红色哨子。","mne":""},{"word":"white","ipa":"/waɪt/","pos":"adj.","def":"白色的；  n.白色","sen":"There is a white piece of paper on the table.","trans":"桌子上有一张白纸。","mne":""},{"word":"who","ipa":"/huː/","pos":"pron.","def":"谁，那……的（人）","sen":"No one knows who he is.","trans":"没人知道他是谁。","mne":""},{"word":"whoever","ipa":"/huːˈevər/","pos":"pron.","def":"无论是谁，不管谁，任何人","sen":"Whoever comes to the party has to show their invitation card.","trans":"无论谁来参加这场聚会，都必须出示邀请函。","mne":"who谁 + ever究竟 → whoever无论谁，任何人"},{"word":"whole","ipa":"/hoʊl/","pos":"adj.","def":"整个的；完整的，完好无损的；全部的，所有的；  n.全部；整体","sen":"The boy ate the whole watermelon by himself.","trans":"男孩自己吃了一整个西瓜。","mne":""},{"word":"whom","ipa":"/huːm/","pos":"pron.","def":"谁（who的宾格）","sen":"Do you know whom the reporters are discussing?","trans":"你知道记者们在讨论谁吗？","mne":""},{"word":"whose","ipa":"/huːz/","pos":"det.","def":"谁的","sen":"Whose phone and umbrella are those?","trans":"这是谁的手机和雨伞啊？","mne":""},{"word":"why","ipa":"/waɪ/","pos":"adv.","def":"为什么，……的（理由）","sen":"He shrugged and spread his hands as if to ask, \"Why?\"","trans":"他耸耸肩、摊开手，仿佛在问：“为什么？”","mne":""},{"word":"wicked","ipa":"/ˈwɪkɪd/ ","pos":"adj.","def":"邪恶的，恶毒的；淘气的，恶作剧的；缺德的","sen":"The wicked witch possesses powerful magic.","trans":"这位邪恶的女巫有着强大法力。","mne":""},{"word":"wide","ipa":"/waɪd/","pos":"adj.","def":"宽的，宽阔的；广泛的；  adv.尽可能远地","sen":"The sofa is wide enough for many people.","trans":"这张沙发很宽，足够坐很多人。","mne":""},{"word":"widely","ipa":"/ˈwaɪdli/","pos":"adv.","def":"广泛地，普遍地","sen":"The color red is widely used during the Spring Festival celebrations.","trans":"欢度春节时，处处可见红色。","mne":""},{"word":"widen","ipa":"/ˈwaɪdn/","pos":"v.","def":"加宽","sen":"This road was too narrow, so now we have to widen it.","trans":"这条路太窄了，所以现在我们要把它加宽。","mne":"wid宽的 + en表动词 → widen 加宽，变宽"},{"word":"widespread","ipa":"/ˈwaɪdspred/","pos":"adj.","def":"分布广的；普遍的，广泛的","sen":"My love story quickly became widespread through the Internet.","trans":"通过网络，我的爱情故事很快就传开了。","mne":"wide广泛的 + spread展开 → widespread分布广的，普遍的"},{"word":"widow","ipa":"/ˈwɪdoʊ/","pos":"n.","def":"寡妇，遗孀","sen":"The poor woman became a widow after her husband's death.","trans":"那个可怜的女人在她丈夫死后就成了寡妇。","mne":""},{"word":"width","ipa":"/wɪdθ/","pos":"n.","def":"宽度，广度，宽阔","sen":"They are expanding the width of the road.","trans":"他们正在扩大道路的宽度。","mne":"wid=wide宽的 + th抽象名词 → width宽度"},{"word":"wife","ipa":"/waɪf/","pos":"n.","def":"妻子，夫人","sen":"The man looked at the wedding photo and missed his wife.","trans":"男人看着结婚照片，思念他的妻子。","mne":""},{"word":"wild","ipa":"/waɪld/","pos":"adj.","def":"自然生长的，野生的；野性的；狂热的；荒芜的；疯狂的","sen":"The wild kid is making a big mess in the dining room.","trans":"这个熊孩子把餐厅搞得一团糟。","mne":""},{"word":"wildlife","ipa":"/ˈwaɪldlaɪf/","pos":"n.","def":"野生生物；  adj.野生动植物的","sen":"Wildlife reserves are created to keep animals safe.","trans":"建立野生动物保护区是为了让动物安全。","mne":"wild野生的 + life生命 → wildlife野生动植物"},{"word":"will","ipa":"/wɪl/","pos":"v.","def":"愿意；  n.意志；遗嘱","sen":"She said: \"Yes, I will.\"","trans":"她说：”我愿意。“","mne":""},{"word":"willing","ipa":"/ˈwɪlɪŋ/","pos":"adj.","def":"愿意的，心甘情愿的","sen":"The man is willing to be at his boss's service.","trans":"这个人愿意听从老板的吩咐。","mne":"will愿意 + ing名词后缀 → willing愿意的"},{"word":"willingness","ipa":"/ˈwɪlɪŋnəs/","pos":"n.","def":"愿意，乐意","sen":"The boy shows his willingness to answer the question by raising his hand.","trans":"这个男孩举手表示愿意回答这个问题。","mne":"will心愿 + ing名词后缀 + ness表名词，行为或状态 → willingness心甘情愿"},{"word":"win","ipa":"/wɪn/","pos":"v.","def":"赢得；  n.胜利","sen":"She won the position by her amazing interview performance.","trans":"她靠出色的面试表现赢得了这个岗位。","mne":""},{"word":"wind","ipa":"/wɪnd/, /waɪnd/","pos":"n.","def":"风；  v.（道路、河流等）蜿蜒曲折；缠绕","sen":"The wind is blowing the leaves.","trans":"风正吹着树叶。","mne":""},{"word":"window","ipa":"/ˈwɪndoʊ/","pos":"n.","def":"窗口； 窗","sen":"She withdraws money from the cash department window in the bank.","trans":"她从银行的现金业务窗口取到了钱。","mne":""},{"word":"wine","ipa":"/waɪn/","pos":"n.","def":"葡萄酒；果酒；  v.喝酒；  v.请...喝酒","sen":"Red wine is made from high quality grapes.","trans":"红葡萄酒是用优质葡萄酿制的。","mne":""},{"word":"wing","ipa":"/wɪŋ/","pos":"n.","def":"翅膀，翼；  v.飞行","sen":"Mommy, I want the doll with the butterfly wings.","trans":"妈妈，我想要那个带蝴蝶翅膀的洋娃娃。","mne":""},{"word":"winner","ipa":"/ˈwɪnər/","pos":"n.","def":"获胜者，得奖者","sen":"Hell yeah, I'm the winner!","trans":"没错，我就是获胜者！","mne":""},{"word":"winter","ipa":"/ˈwɪntər/","pos":"n.","def":"冬，冬季","sen":"It always snows heavily here in winter.","trans":"这儿冬天总是下大雪。","mne":"wint水，潮湿 + er名词后缀，人或事物 → 有很多冰和水的季节 → winter冬季"},{"word":"wipe","ipa":"/waɪp/","pos":"v.","def":"擦，拭，揩；  n.擦","sen":"The bride wipes away the tears from the groom's face.","trans":"新娘拭去了新郎脸上的泪水。","mne":""},{"word":"wire","ipa":"/ˈwaɪər/","pos":"n.","def":"电线，电缆，导线，金属丝，金属线；  v.接通电源；将……连接到","sen":"It's a bird sitting on a wire.","trans":"鸟停落在电线上。","mne":""},{"word":"wisdom","ipa":"/ˈwɪzdəm/","pos":"n.","def":"智慧，学问","sen":"The old man's wisdom comes from books.","trans":"这位老人的智慧来自于博览群书。","mne":"wis=wise智慧的 + dom状态或领域 → wisdom智慧"},{"word":"wise","ipa":"/waɪz/","pos":"adj.","def":"有智慧的，博学的；明智的","sen":"My college professor is quite wise about many things.","trans":"我的大学教授很博学。","mne":""},{"word":"wish","ipa":"/wɪʃ/","pos":"n.","def":"愿望，心愿；  v.祝愿；希望，想要","sen":"The little boy made a wish in front of the dragon.","trans":"小悟空在神龙面前许下了愿望。","mne":""},{"word":"wit","ipa":"/wɪt/","pos":"n.","def":"智力，才智；机智；风趣，措辞巧妙的能力","sen":"The wit of that little boy fascinates us.","trans":"那个小男孩的机智让我们感到惊叹。","mne":""},{"word":"with","ipa":"/wɪð/","pos":"prep.","def":"有，以，用，同……一起，由于，和……一致，赞成，关于，就","sen":"I like coffee with milk.","trans":"我喜欢咖啡加牛奶。","mne":""},{"word":"withdraw","ipa":"/wɪðˈdrɔː/","pos":"v.","def":"取款；撤退","sen":"I'd like to withdraw 500 dollars from the machine.","trans":"我想从这台机器里取500美元。","mne":"with向后，相反 + draw拉 → 向相反拉 → withdraw撤消，撤退"},{"word":"withdrawal","ipa":"/wɪðˈdrɔːəl/","pos":"n.","def":"取款；收回","sen":"I made a withdrawal from my bank account.","trans":"我从我的银行账户里取了一笔钱。","mne":"with向后，相反 + draw拉 + al表名词后缀 → withdrawal撤退"},{"word":"within","ipa":"/wɪˈðɪn/","pos":"adv.","def":"在内部，在里面","sen":"There is light coming from within.","trans":"有光从屋内传出来。","mne":"with和，与 + in里面 → within在内部"},{"word":"without","ipa":"/wɪˈðaʊt/","pos":"prep.","def":"没有，不；  adv.在没有（某种不言而喻的东西）的情况下，在缺乏的情况下","sen":"I feel so lonely without you.","trans":"没有你我感觉好孤单。","mne":"with和，与 + out离开，不在  → without没有"},{"word":"withstand","ipa":"/wɪðˈstænd/","pos":"v.","def":"抵挡","sen":"The shield is solid enough to withstand the enemy's attack.","trans":"大锤的护盾太结实了，挡住敌人的进攻不在话下。","mne":"with向后，相反 + stand站 → 向相反的方向站 → withstand抵抗，反抗"},{"word":"witness","ipa":"/ˈwɪtnəs/","pos":"n.","def":"目击者；  v.目击，亲眼看见","sen":"The little girl is the only witness of the accident.","trans":"小女孩是这场事故的唯一目击者。","mne":"wit智慧 + ness表名词 → 目击者"},{"word":"wolf","ipa":"/wʊlf/","pos":"n.","def":"狼（复数wolves）；残忍凶狠的人；  v.狼吞虎咽地吃","sen":"Even though a wolf looks a bit like a dog, it is actually much more dangerous.","trans":"尽管狼看起来有点儿像狗，但其实它们要危险得多。","mne":""},{"word":"woman","ipa":"/ˈwʊmən/","pos":"n.","def":"女人；妇女，成年女性","sen":"My grandmother is such an elegant woman!","trans":"我的奶奶是一个多么优雅的女人啊！","mne":""},{"word":"wonder","ipa":"/ˈwʌndər/","pos":"v.","def":"想知道，想弄明白；  n.惊奇，惊异；奇迹，奇观","sen":"He was wondering what was in the box.","trans":"他想知道箱子里是什么。","mne":""},{"word":"wonderful","ipa":"/ˈwʌndərfl/","pos":"adj.","def":"极好的，精彩的；绝妙的","sen":"Many people have wonderful things to say about this English learning app.","trans":"人们对这款英语学习应用有极好的评价。","mne":"wonder奇迹，神奇 + ful形容词后缀 → wonderful极好的"},{"word":"wood","ipa":"/wʊd/","pos":"n.","def":"木头，木材","sen":"Wood can be used to build houses.","trans":"木材可以用来建造房屋。","mne":""},{"word":"wooden","ipa":"/ˈwʊdn/","pos":"adj.","def":"木制的，木质的；呆笨的，死板的","sen":"All of the kitchenware in this set is wooden.","trans":"这套厨具全都是木制的。","mne":"wood木头 + en由……制成的 → 木制的"},{"word":"wool","ipa":"/wʊl/","pos":"n.","def":"羊毛；（羊等动物的）毛","sen":"This sweater is made of high-quality wool.","trans":"这件毛衣是由高品质羊毛制成的。","mne":""},{"word":"woolen","ipa":"/ˈwʊlən/","pos":"adj.","def":"羊毛的；毛纺的；  n.毛织品","sen":"He wanted to make a woolen scarf.","trans":"他想做一条羊毛围巾。","mne":"wool羊毛 + en由……制成的 → woolen羊毛制的"},{"word":"woollen","ipa":"/ˈwʊlən/","pos":"adj.","def":"毛纺的；羊毛（制）的；  n.毛织品","sen":"Since the 1960s, several new techniques have been researched and applied in woollen production.","trans":"20世纪60年代以来，毛纺生产中已经研究和应用了一些新技术。","mne":"wooll羊毛 + en表示由…制成的，含有…质的，似…的 → woollen羊毛制的"},{"word":"word","ipa":"/wərd/","pos":"n.","def":"字，词，话","sen":"The word on the paper was written in black ink.","trans":"纸上的词是用黑墨水写的。","mne":""},{"word":"work","ipa":"/wɜːrk/","pos":"n.","def":"工作；作品，著作；  v.工作，劳动，干活；运转，运行；起作用，有效果，奏效","sen":"They are doing their work on the farm. ","trans":"他们在田野里劳作。","mne":""},{"word":"worker","ipa":"/ˈwɜːrkər/","pos":"n.","def":"工人，雇员；工作者","sen":"The worker was ready to work.","trans":"工人准备好工作了。","mne":"work工作 + er人 → worker工人"},{"word":"workforce","ipa":"/ˈwɜːrkfɔːrs/","pos":"n.","def":"劳动力","sen":"The city's workforce accounts for about 60 percent of the population.","trans":"这座城市的劳动力约占总人口的 60%。","mne":""},{"word":"workplace","ipa":"/ˈwɜːrkpleɪs/","pos":"n.","def":"工作场所","sen":"I spend five days a week at my workplace.","trans":"一周我花五天在工作场所。","mne":""},{"word":"workshop","ipa":"/ˈwɜːrkʃɑːp/","pos":"n.","def":"车间，工场，工作室；研讨会，工作坊","sen":"I left my car at the workshop for repair.","trans":"我把我的车留在车间修理。","mne":"work工作 + shop工厂 → workshop车间"},{"word":"world","ipa":"/wɜːrld/","pos":"n.","def":"世界","sen":"His dream is to travel around the world.","trans":"他的梦想是环游世界。","mne":"wor人 + ld年龄，生长 → 人类的生长存在 → world世界"},{"word":"worldwide","ipa":"/ˌwɜːrldˈwaɪd/","pos":"adv.","def":"在世界各地，遍及全球地","sen":"The Internet connects users worldwide.","trans":"互联网连接的用户遍布世界各地。","mne":"world世界 + wide宽的 → worldwide全世界的"},{"word":"worm","ipa":"/wɜːrm/","pos":"n.","def":"虫，蠕虫","sen":"Worms make good fish bait.","trans":"蠕虫是很好的鱼饵。","mne":""},{"word":"worried","ipa":"/ˈwɜːrid/","pos":"adj.","def":"发愁的，担心的，烦恼的；  v.担忧（worry的过去式和过去分词）","sen":"She looks worried. She must be in some trouble.","trans":"她看起来愁容满面。她一定有什么麻烦。","mne":"worr=worry担心 + ied形容词后缀 → worried担心的"},{"word":"worry","ipa":"/ˈwɜːri/","pos":"v.","def":"担心，操心","sen":"She worries about the safety of the child.","trans":"她担心孩子的安全。","mne":""},{"word":"worse","ipa":"/wɜːrs/","pos":"adv.","def":"更坏地，更恶劣地；  adj.更坏的，更恶劣的；  n.更坏的事，更恶劣的事","sen":"The company is performing worse and worse.","trans":"这家公司的业绩越来越差。","mne":""},{"word":"worship","ipa":"/ˈwɜːrʃɪp/","pos":"v.","def":"崇拜，爱戴；做礼拜，拜神；  n.礼拜，礼拜仪式；崇拜，敬仰","sen":"In ancient times, Chinese farmers used to worship the god of earth.","trans":"在古代，中国农民常常敬拜土地公公。","mne":"wor值得敬仰的 + ship表示条件、行动、地位、关系等 -> worship崇拜"},{"word":"worst","ipa":"/wɜːrst/","pos":"adv.","def":"最坏地；最糟地；  adj.最差的，最坏的；  n.最坏的事","sen":"I think rainy days are the worst type of weather.","trans":"我认为下雨天是最糟糕的天气。","mne":""},{"word":"worth","ipa":"/wɜːrθ/","pos":"adj.","def":"值……钱；值得的；  n.价值","sen":"My house is worth two hundred thousand dollars.","trans":"我的房子值二十万美元。","mne":""},{"word":"worthless","ipa":"/ˈwɜːrθləs/","pos":"adj.","def":"无价值的","sen":"The broken coin is worthless; you can't buy anything with it.","trans":"硬币碎裂了后变得毫无价值，你用它买不到任何东西。","mne":"worth价值 + less无……的 → worthless无价值的，无用的"},{"word":"worthwhile","ipa":"/ˌwɜːrθˈwaɪl/","pos":"adj.","def":"值得的，有意义的","sen":"Studying English words with this app is definitely worthwhile!","trans":"用这款应用学英语单词绝对超值哦！","mne":"worth有...价值 + while一段时间 → worthwhile值得的"},{"word":"worthy","ipa":"/ˈwɜːrði/","pos":"adj.","def":"值得……的，配得上……的","sen":"She is worthy of respect as she sacrificed herself for others.","trans":"她舍己为人的精神值得尊敬。","mne":"worth价值，价格 + y形容词后缀 → worthy值得...的"},{"word":"would","ipa":"/wʊd/","pos":"v.","def":"会","sen":"He said if he earned a million dollars he would buy a house.","trans":"他说如果他挣了一百万美元，他就会买一栋房子。","mne":""},{"word":"wound","ipa":"/wuːnd/","pos":"n.","def":"伤口（读作/wuːnd/）；  v.伤害；缠绕（wind的过去式）（读作/waʊnd/）","sen":"She has a small wound on her knee.","trans":"她膝盖上有一个小伤口。","mne":""},{"word":"wrap","ipa":"/ræp/","pos":"v.","def":"裹，包，捆；覆盖；用……缠绕；  n.外衣；围巾；包裹材料","sen":"She wrapped the gift with some colorful paper.","trans":"她用彩色的纸把礼物包了起来。","mne":"wr=wer拧 + ap  → wrap裹，包，捆"},{"word":"wreck","ipa":"/rek/","pos":"v.","def":"破坏，毁坏；  n.失事；残骸","sen":"The hurricane wrecked dozens of coastal villages last night.","trans":"昨晚的飓风摧毁了数十个沿海村落。","mne":""},{"word":"wrist","ipa":"/rɪst/","pos":"n.","def":"腕部；腕关节","sen":"The basketball player injured his wrist.","trans":"这名篮球运动员的手腕受伤了。","mne":""},{"word":"write","ipa":"/raɪt/","pos":"v.","def":"写，书写，写字；写信给","sen":"Let me write down these things.","trans":"让我写下这些事情。","mne":""},{"word":"writer","ipa":"/ˈraɪtər/","pos":"n.","def":"作家；作者","sen":"Who do you prefer out of these famous foreign writers?","trans":"在这些著名的外国作家中，你最喜欢谁？","mne":"writ=write写 + er人 → writer作家"},{"word":"writing","ipa":"/ˈraɪtɪŋ/","pos":"n.","def":"写作；文章","sen":"She is a writer and good at writing.","trans":"她是一个作家，擅长写作。","mne":"writ写作 + ing名词后缀 → 写出来的东西 → writing著作，作品"},{"word":"wrong","ipa":"/rɔːŋ/","pos":"adj.","def":"错误的","sen":"Press the red button if you think the answer is wrong.","trans":"如果你认为回答错误，就按下红色按钮。","mne":""},{"word":"x-ray","ipa":"/ˈɛksˌre/","pos":"n.","def":"X光照片","sen":"The doctor took an x-ray of my leg to see if it was broken.","trans":"医生给我的腿拍了 X 光片，看看是否骨折。","mne":""},{"word":"yard","ipa":"/jɑːrd/","pos":"n.","def":"院子，庭院；码（长度单位，等于3英尺或0.9144米）","sen":"What a large yard! We can have a barbecue.","trans":"这个院子真大！我们可以烤烧烤。","mne":""},{"word":"year","ipa":"/jɪr/","pos":"n.","def":"【数】年份，年","sen":"There are 12 months in a year.","trans":"一年有十二个月。","mne":""},{"word":"yearly","ipa":"/ˈjɪrli/","pos":"adj.","def":"每年的，一年一度的；  n.年刊","sen":"The yearly rental of the house is 2,350 dollars.","trans":"这房子的年租金是2350美元。","mne":"year年 + ly表副词，每……地 → yearly每年地"},{"word":"yellow","ipa":"/ˈjeloʊ/","pos":"adj.","def":"黄色的；  n.黄色","sen":"Look at this big yellow sunflower.","trans":"瞧这朵黄色的大向日葵。","mne":""},{"word":"yes","ipa":"/jes/","pos":"excl.","def":"答话时表示正确或真实","sen":"Yes, I promise to be a good boy.","trans":"好，我保证做一个好男孩！","mne":""},{"word":"yesterday","ipa":"/ˈjestərdeɪ/","pos":"n.","def":"昨天；  adv.在昨天","sen":"Today is Saturday, so yesterday was Friday.","trans":"今天是周六，所以昨天就是周五。","mne":"yester昨日 + day一天 → yesterday昨天"},{"word":"yet","ipa":"/jet/","pos":"conj.","def":"但是；  adv.尚，还，仍然","sen":"I studied hard, yet I still failed the exam.","trans":"我学习很努力，但考试还是没及格。","mne":""},{"word":"yield","ipa":"/jiːld/","pos":"v.","def":"出产（作物）；  v.弯曲；屈服；让行；  n.收益","sen":"The fields yielded many carrots this year.","trans":"这片土地今年产出了很多胡萝卜。","mne":""},{"word":"you","ipa":"/juː/","pos":"pron.","def":"你，您","sen":"I need you!","trans":"我需要你。","mne":""},{"word":"young","ipa":"/jʌŋ/","pos":"adj.","def":"年轻的，年纪小的；没有经验的；  n.青年人；（动物的）崽","sen":"These young women are so excited for the coming holiday.","trans":"假期就要到了，这些年轻的女孩很是激动。","mne":""},{"word":"your","ipa":"/jʊr/","pos":"det.","def":"（you的所有格）你的，您的，你们的","sen":"Don't forget your umbrella. It might rain.","trans":"不要忘了你的雨伞，可能会下雨。","mne":""},{"word":"yours","ipa":"/jɔːrz/","pos":"pron.","def":"你的，你们的（所属物）","sen":"The car is yours now—drive safe!","trans":"这辆车现在是你的了，安全驾驶！","mne":""},{"word":"yourself","ipa":"/jɔːrˈself/","pos":"pron.","def":"你自己，您自己","sen":"Look at yourself in the mirror.","trans":"看看镜子里的你自己。","mne":"your你的 ＋ self自己 → yourself你自己"},{"word":"yourselves","ipa":"/jə'selvz/","pos":"pron.","def":"你们自己","sen":"Look at yourselves in the mirror!","trans":"看看镜子里的你们自己吧！","mne":""},{"word":"youth","ipa":"/juːθ/","pos":"n.","def":"青年；年轻人；青春","sen":"Youth is the symbol of hope.","trans":"青年是希望的象征。","mne":"you青春活力，生命力 + th抽象名词后缀 → youth青春；青年"},{"word":"zero","ipa":"/ˈzɪroʊ/","pos":"n.","def":"【数】零","sen":"The result of 1 minus 1 is zero.","trans":"1-1=0","mne":""},{"word":"zone","ipa":"/zoʊn/","pos":"n.","def":"地带，空间，地区，区域，范围；  v.将…划为特殊区域","sen":"Our school is in this zone.","trans":"我们学校在这个区域。","mne":""},{"word":"zoo","ipa":"/zuː/","pos":"n.","def":"动物园","sen":"There are so many animals in the zoo!","trans":"动物园里有好多动物啊！","mne":""}];
